internal sealed class EmbeddedTriggerDepthException : EmbeddedSqlException
{
    public EmbeddedTriggerDepthException(long lastInsertRowId, bool preserveChanges = false)
        : base("too many levels of trigger recursion")
    {
        LastInsertRowId = lastInsertRowId;
        PreserveChanges = preserveChanges;
    }

    public EmbeddedTriggerDepthException(
        EmbeddedTriggerDepthException exception,
        long lastInsertRowId,
        bool? preserveChanges = null)
        : base(exception.Message, exception)
    {
        LastInsertRowId = lastInsertRowId;
        PreserveChanges = preserveChanges ?? exception.PreserveChanges;
    }

    public long LastInsertRowId { get; }

    public bool PreserveChanges { get; }
}

/// <summary>
/// Reports that a catalog mutation reached its durable WAL commit marker, but
/// subsequent checkpoint maintenance failed. Retrying the mutation would apply
/// it twice; dispose and reopen before attempting another write.
/// </summary>
public sealed class EmbeddedPostCommitMaintenanceException : EmbeddedSqlException
{
    public EmbeddedPostCommitMaintenanceException(Exception maintenanceFailure)
        : base(
            "The managed database mutation committed successfully, but post-commit checkpoint maintenance failed. "
            + "Do not retry the mutation; dispose and reopen the database before another write.",
            maintenanceFailure)
    {
        MaintenanceFailure = maintenanceFailure;
    }

    /// <summary>The maintenance failure that occurred after the durable commit.</summary>
    public Exception MaintenanceFailure { get; }
}

public sealed partial class EmbeddedDatabase : IDisposable
{
    private const int MaximumTriggerDepth = 1_000;
    private const int MaximumForeignKeyActionDepth = 1_000;
    private const int RecursiveTriggerStackSize = 32 * 1024 * 1024;

    /// <summary>SQLite's default PRAGMA integrity_check error budget.</summary>
    private const int DefaultIntegrityCheckErrorLimit = 100;
    [ThreadStatic]
    private static bool s_hasRecursiveTriggerStack;
    [ThreadStatic]
    private static RecursiveTriggerCallbackDispatcher? s_recursiveTriggerCallbackDispatcher;
    private static readonly AsyncLocal<EmbeddedDatabase?> RecursiveTriggerCallbackDatabase = new();
    internal const string SqliteSequenceTableName = "sqlite_sequence";
    private static readonly ConditionalWeakTable<IFileSystem, FileCatalogWriteLockScope> FileCatalogWriteLocks = new();
    private static readonly ConditionalWeakTable<IFileSystem, FileCatalogWriterRegistry> FileCatalogWriterRegistries = new();
    private readonly object _gate = new();
    private Dictionary<string, EmbeddedTable> _tables = new(StringComparer.OrdinalIgnoreCase);
    private Dictionary<string, ViewDefinition> _views = new(StringComparer.OrdinalIgnoreCase);
    private Dictionary<string, TriggerDefinition> _triggers = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<(string Name, int Arity), Func<IReadOnlyList<SqlValue>, SqlValue>> _scalarFunctions = new();
    private readonly Dictionary<(string Name, int Arity), ManagedAggregateFunction> _aggregateFunctions = new();
    private readonly Dictionary<string, Func<string, string, int>> _collations = new(StringComparer.OrdinalIgnoreCase);
    private EmbeddedFileStore? _fileStore;
    private readonly string _databasePath = string.Empty;
    private readonly IFileSystem? _fileSystem;
    private readonly object? _fileCatalogWriteLock;
    private readonly bool _readOnly;
    private readonly bool _foreignReadOnly;
    private SqlitePagerViewToken _foreignViewToken;
    private FileCatalogVersion _fileCatalogVersion;
    private long _ownedCommittedGeneration;
    private PragmaHeaderMetadata _inMemoryPragmaHeader;
    private long _version;
    private int _activeTransactions;
    private int _activeStatementReaders;
    private readonly Dictionary<BlobMutationIdentity, int> _activeBlobMutations = new();
    private readonly Dictionary<BlobMutationIdentity, long> _blobMutationGenerations = new();
    private long _nextBlobMutationGeneration;
    private readonly EmbeddedTransactionLock _transactionLock;

    public EmbeddedDatabase()
    {
        _transactionLock = new EmbeddedTransactionLock();
    }

    private EmbeddedDatabase(
        EmbeddedFileStore fileStore,
        EmbeddedFileCatalog catalog,
        string databasePath,
        IFileSystem fileSystem,
        FileCatalogVersion fileCatalogVersion,
        object fileCatalogWriteLock,
        bool readOnly,
        bool foreignReadOnly = false)
    {
        _fileStore = fileStore;
        _databasePath = databasePath;
        _fileSystem = fileSystem;
        _fileCatalogVersion = fileCatalogVersion;
        _fileCatalogWriteLock = fileCatalogWriteLock;
        _readOnly = readOnly;
        _foreignReadOnly = foreignReadOnly;
        _foreignViewToken = foreignReadOnly
            ? fileStore.CaptureCommittedViewToken()
            : default;
        _ownedCommittedGeneration = fileStore.CommittedViewGeneration;
        _tables = catalog.Tables;
        _views = catalog.Views;
        _triggers = catalog.Triggers;
        _transactionLock = EmbeddedTransactionLockRegistry.Get(fileSystem, databasePath);
    }

    /// <summary>
    /// Opens (or creates) a file-backed managed database that persists its schema
    /// and table data as real SQLite pages. See <c>AhtolaBindings.OpenManagedDatabase</c>
    /// for the exact set of supported schema and data and the documented gaps.
    /// </summary>
    public static EmbeddedDatabase OpenFile(
        string path,
        IFileSystem? fileSystem = null,
        bool readOnly = false,
        bool foreignReadOnly = false)
    {
        ArgumentException.ThrowIfNullOrEmpty(path);
        if (foreignReadOnly && !readOnly)
            throw new ArgumentException("A foreign open is always read-only.", nameof(foreignReadOnly));
        var effectiveFileSystem = fileSystem ?? PhysicalFileSystem.Instance;
        var fileCatalogWriteLock = GetFileCatalogWriteLock(effectiveFileSystem, path);
        lock (fileCatalogWriteLock)
        {
            using var catalogWriteLease = readOnly
                ? null
                : EnterPhysicalFileCatalogWriteLock(effectiveFileSystem, path);
            var store = EmbeddedFileStore.Open(
                path,
                effectiveFileSystem,
                out var catalog,
                readOnly: readOnly,
                foreignReadOnly: foreignReadOnly);
            try
            {
                // The store now owns the physical database before this second pager
                // reads the durable version, so no foreign client can race catalog load.
                // A foreign read-only open holds no ownership, but the version read
                // is a self-contained snapshot and only feeds catalog-cache reuse.
                var catalogVersion = ReadFileCatalogVersion(effectiveFileSystem, path, foreignReadOnly);
                return new EmbeddedDatabase(
                    store,
                    catalog,
                    path,
                    effectiveFileSystem,
                    catalogVersion,
                    fileCatalogWriteLock,
                    readOnly,
                    foreignReadOnly);
            }
            catch
            {
                store.Dispose();
                throw;
            }
        }
    }

    /// <summary>Releases the backing file store, if any.</summary>
    public void Dispose()
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        lock (_gate)
            _fileStore?.Dispose();
    }

    internal bool IsFileBacked => _fileStore is not null;

    /// <summary>
    /// How long autocommit statements on this database wait out a conflicting
    /// writer and retry against a stale catalog snapshot before surfacing busy.
    /// The owning connection sets this from its command timeout; zero fails
    /// fast, matching SQLite's default <c>busy_timeout</c>.
    /// </summary>
    internal TimeSpan BusyTimeout { get; set; }

    /// <summary>Re-reads the committed catalog after a stale-snapshot signal. Throws busy when the version cannot settle.</summary>
    internal void ReloadFileCatalogAfterStale()
    {
        lock (_gate)
        {
            if (_fileStore is null || _fileSystem is null || _fileCatalogWriteLock is null)
                throw new InvalidOperationException("The managed file catalog persistence state is not initialized.");

            lock (_fileCatalogWriteLock)
            {
                // A commit landing mid-reload fails the race check; spin until the
                // reload observes a settled version. Bounded so a commit storm
                // degrades to the public busy error instead of hanging.
                for (var attempt = 0; attempt < 1000; attempt++)
                {
                    if (TryReloadFileCatalogIfChanged())
                        return;
                    Thread.Sleep(1);
                }

                throw new EmbeddedCatalogSnapshotStaleException();
            }
        }
    }

    /// <summary>
    /// The write reservation shared by every managed connection open on this
    /// database, modeling SQLite's RESERVED and EXCLUSIVE locks.
    /// </summary>
    internal EmbeddedTransactionLock TransactionLock => _transactionLock;

    /// <summary>
    /// Whether an EXCLUSIVE transaction also excludes readers. SQLite only does
    /// that under a rollback journal; in WAL mode EXCLUSIVE behaves as IMMEDIATE
    /// because WAL readers never contend with the writer.
    /// </summary>
    internal bool ExclusiveTransactionsExcludeReaders => GetJournalMode() != SqliteJournalMode.Wal;

    internal bool IsReadOnly => _readOnly;

    internal string DatabasePath => _databasePath;

    internal IFileSystem FileSystem
        => _fileSystem ?? throw new InvalidOperationException("The managed database is not file-backed.");

    internal static StringComparer PhysicalPathComparer { get; } =
        OperatingSystem.IsWindows() || OperatingSystem.IsMacOS()
            ? StringComparer.OrdinalIgnoreCase
            : StringComparer.Ordinal;

    internal bool ReferencesSameDatabase(EmbeddedDatabase other)
    {
        ArgumentNullException.ThrowIfNull(other);
        if (ReferenceEquals(this, other))
            return true;
        if (!IsFileBacked || !other.IsFileBacked || _fileSystem is null || other._fileSystem is null)
            return false;

        var fileSystem = AhtolaEncryptionFileSystem.Unwrap(_fileSystem);
        var otherFileSystem = AhtolaEncryptionFileSystem.Unwrap(other._fileSystem);
        if (fileSystem is PhysicalFileSystem && otherFileSystem is PhysicalFileSystem)
        {
            return PhysicalPathComparer.Equals(
                Path.GetFullPath(_databasePath),
                Path.GetFullPath(other._databasePath));
        }

        return ReferenceEquals(fileSystem, otherFileSystem)
               && string.Equals(_databasePath, other._databasePath, StringComparison.Ordinal);
    }

    internal bool ReferencesStoragePath(string path, IFileSystem fileSystem)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);
        ArgumentNullException.ThrowIfNull(fileSystem);
        if (!IsFileBacked || _fileSystem is null)
            return false;

        var ownFileSystem = AhtolaEncryptionFileSystem.Unwrap(_fileSystem);
        var candidateFileSystem = AhtolaEncryptionFileSystem.Unwrap(fileSystem);
        if (ownFileSystem is PhysicalFileSystem && candidateFileSystem is PhysicalFileSystem)
        {
            var candidate = Path.GetFullPath(path);
            return new[] { string.Empty, "-wal", "-journal", "-shm" }.Any(suffix =>
                PhysicalPathComparer.Equals(Path.GetFullPath(_databasePath + suffix), candidate));
        }

        return ReferenceEquals(ownFileSystem, candidateFileSystem)
               && new[] { string.Empty, "-wal", "-journal", "-shm" }.Any(suffix =>
                   string.Equals(_databasePath + suffix, path, StringComparison.Ordinal));
    }

    private sealed record ManagedAggregateFunction(
        SqlValue Seed,
        Func<SqlValue, IReadOnlyList<SqlValue>, SqlValue> Step,
        Func<SqlValue, SqlValue> Finalize);

    private sealed record GroupedResult(SourceRow Representative, IReadOnlyList<SourceRow> Rows, SqlValue[] Values);

    private sealed record OrderByKeyed<T>(T Item, SqlValue[] Keys, int Position);

    private sealed record LimitedDmlCandidate(int Position, SqlValue[] OrderValues);

    private enum TriggerMutationKind
    {
        Insert,
        Update,
        Delete,
    }

    private sealed record ManagedIndexScanPlan(
        NamedTableSource Source,
        EmbeddedTable Table,
        EmbeddedIndex Index,
        bool Search);

    private sealed record IndexConstraint(Expression Expression, bool RequiresNullRejection);

    // The rows of an enclosing aggregate evaluation (one GROUP BY group, or the whole
    // selected set for an ungrouped aggregate query) together with the context that
    // evaluation runs under. A nested query consults the chain to resolve an aggregate
    // call whose argument columns belong to an outer block (SQLite's aggregate-ownership
    // rule: such a reference is legal only in an aggregate-bearing SELECT).
    internal sealed record OuterAggregateScope(
        IReadOnlyList<SourceRow> Rows,
        OuterAggregateScope? Parent,
        QueryContext Context);

    internal sealed record QueryContext(
        Dictionary<string, EmbeddedTable> Tables,
        IReadOnlyDictionary<string, SourceData> CommonTableExpressions,
        IReadOnlyDictionary<string, ViewDefinition>? Views = null,
        IReadOnlyDictionary<string, TriggerDefinition>? Triggers = null,
        IReadOnlyList<string>? ExpandingViews = null,
        bool InsideTrigger = false,
        long LastInsertRowId = 0,
        bool ForeignKeysEnabled = false,
        bool DeferForeignKeys = false,
        bool InTransaction = false,
        bool RecursiveTriggersEnabled = false,
        IReadOnlySet<string>? ActiveTriggers = null,
        int TriggerDepth = 0,
        AutoIncrementStatementState? AutoIncrementState = null,
        int ForeignKeyActionDepth = 0,
        ForeignKeyStatementState? ForeignKeyStatement = null,
        TriggerRowFrame? TriggerRow = null,
        TriggerStatementState? TriggerState = null,
        InsertConflictAlgorithm? ConflictAlgorithmOverride = null,
        bool InheritedTriggerConflict = false,
        bool IndexExpression = false,
        CancellationToken CancellationToken = default,
        bool SchemaValidation = false,
        TableSource? CollationSource = null,
        IReadOnlyDictionary<string, string?>? CollationScope = null,
        IReadOnlyList<IReadOnlyDictionary<string, string?>>? OuterCollationScopes = null,
        InsertConflictAlgorithm? TriggerConflictAlgorithm = null,
        bool PreserveUpsertFail = false,
        StatementExecutionState? StatementState = null,
        bool CompilationEnabled = true,
        TempTriggerBridge? TempTriggers = null,
        ManagedStatementHooks? Hooks = null,
        OuterAggregateScope? OuterAggregateScope = null)
    {
        /// <summary>
        /// Row-loop checkpoint. It honors cooperative cancellation exactly as before and
        /// additionally drives the connection's progress handler, which can interrupt the
        /// statement. Trigger and subquery contexts are derived with <c>with</c> expressions,
        /// so the hooks propagate to nested execution automatically.
        /// </summary>
        internal void CheckInterrupt()
        {
            CancellationToken.ThrowIfCancellationRequested();
            Hooks?.Progress?.Step();
        }

        /// <summary>
        /// Reports a committed row change to the connection's update hook. Mirrors SQLite:
        /// WITHOUT ROWID tables and internal <c>sqlite_*</c> tables never notify.
        /// </summary>
        internal void ReportRowChange(SqliteChangeOperation operation, string tableName, EmbeddedTable table, long rowId)
        {
            if (Hooks?.RowChanged is not { } rowChanged || !table.HasRowid)
                return;
            if (tableName.StartsWith("sqlite_", StringComparison.OrdinalIgnoreCase))
                return;

            rowChanged(operation, tableName, rowId);
        }
    }

    /// <summary>
    /// Connection-owned hook that lets connection-private temp triggers take part in a statement
    /// executed by another database. Temp objects live in a separate in-memory database so they
    /// stay invisible to other connections and never reach the persistent schema, which means a
    /// temp trigger watching a main table has to be handed to the main database at execution time,
    /// and a body statement that targets a different schema has to be routed back out.
    /// </summary>
    internal sealed class TempTriggerBridge(
        IReadOnlyList<TriggerDefinition> overlay,
        Func<ParsedStatement, bool> isForeign,
        Func<ParsedStatement, ParsedStatement> localize,
        Func<ParsedStatement, QueryContext, ExecutionResult> executeForeign)
    {
        /// <summary>Temp triggers whose watched table lives in the executing database.</summary>
        public IReadOnlyList<TriggerDefinition> Overlay { get; } = overlay;

        /// <summary>True when a temp trigger body statement targets a different database.</summary>
        public bool IsForeign(ParsedStatement statement) => isForeign(statement);

        /// <summary>
        /// Strips the schema qualifier from a body statement that does belong to the executing
        /// database, because a temp trigger body may name its own schema explicitly.
        /// </summary>
        public ParsedStatement Localize(ParsedStatement statement) => localize(statement);

        public ExecutionResult ExecuteForeign(ParsedStatement statement, QueryContext context)
            => executeForeign(statement, context);
    }

    internal sealed class StatementExecutionState(long lastInsertRowId)
    {
        public long LastInsertRowId { get; set; } = lastInsertRowId;

        // Automatic (transient) equality indexes built on demand for scans whose predicates
        // equate a scan column to a scan-constant expression - the shape correlated
        // subqueries and pushed-down join side predicates produce once per outer row.
        // Entries validate against RowStore.Revision, so any table mutation rebuilds them.
        public Dictionary<TransientLookupKey, TransientLookup> TransientLookups { get; } = [];

        // Collation-resolution memo. Without caching, every projection of a query over a
        // derived or compound source re-derives the full collation scope of the source
        // below it, multiplying cost by the column count at each nesting level - EF's
        // 42-column DISTINCT-over-UNION-over-derived queries never finished. Keys pin the
        // AST node identity plus the lexical CTE map (instance and fill level), which is
        // exactly the resolution context these pure lookups observe.
        public Dictionary<CollationMemoKey, IReadOnlyDictionary<string, string?>> CollationScopes { get; } =
            new(CollationMemoKeyComparer.Instance);

        public Dictionary<CollationMemoKey, IReadOnlyList<string?>> QueryCollations { get; } =
            new(CollationMemoKeyComparer.Instance);

        // Statement-scoped memoization of uncorrelated, deterministic subqueries. An
        // uncorrelated subquery yields the same result for every outer row, so the executor
        // computes it once (proving row-independence by evaluating with no outer row) and
        // reuses it instead of re-executing the inner query per row - the quadratic blowup
        // behind EF's BulkUpdates DELETEs. Entries are keyed by the subquery AST node
        // identity and revalidated against the table revision fingerprint below.
        public Dictionary<object, SubqueryMemoEntry> MemoizedSubqueries { get; } =
            new(ReferenceEqualityComparer.Instance);

        // Subqueries proven correlated (the no-outer-row probe could not resolve a column)
        // or non-deterministic are executed fresh per row; recording them here avoids
        // re-probing on every outer row.
        public HashSet<object> NonMemoizableSubqueries { get; } =
            new(ReferenceEqualityComparer.Instance);

        // Mid-statement DDL (a user callback running DROP/CREATE through another connection)
        // invalidates every memoized collation answer. The executor signals exactly that
        // moment through RefreshCollationSource, which calls this before rebuilding.
        public void ClearCollationMemos()
        {
            CollationScopes.Clear();
            QueryCollations.Clear();
        }
    }

    internal readonly record struct CollationMemoKey(
        object Node,
        IReadOnlyDictionary<string, SourceData> LexicalCtes,
        int LexicalCteCount);

    // A memoized uncorrelated-subquery result plus the table revision fingerprint observed
    // when it was computed. The fingerprint is a sum of the monotonic RowStore revisions
    // over the active catalog, so any table mutation strictly increases it; a mismatch on
    // reuse means the data changed and the result must be recomputed.
    internal sealed class SubqueryMemoEntry(ExecutionResult result, long revisionFingerprint)
    {
        public ExecutionResult Result { get; set; } = result;

        public long RevisionFingerprint { get; set; } = revisionFingerprint;
    }

    internal sealed class CollationMemoKeyComparer : IEqualityComparer<CollationMemoKey>
    {
        public static readonly CollationMemoKeyComparer Instance = new();

        public bool Equals(CollationMemoKey x, CollationMemoKey y)
            => ReferenceEquals(x.Node, y.Node)
                && ReferenceEquals(x.LexicalCtes, y.LexicalCtes)
                && x.LexicalCteCount == y.LexicalCteCount;

        public int GetHashCode(CollationMemoKey key)
            => HashCode.Combine(
                RuntimeHelpers.GetHashCode(key.Node),
                RuntimeHelpers.GetHashCode(key.LexicalCtes),
                key.LexicalCteCount);
    }

    internal readonly record struct TransientLookupKey(EmbeddedTable Table, int ColumnOrdinal, string Collation);

    internal sealed class TransientLookup
    {
        public long Revision { get; set; } = -1;

        // Canonical key -> table row positions, appended in ascending scan order.
        public Dictionary<string, List<int>> Buckets { get; } = new(StringComparer.Ordinal);
    }


