    // Bundles the mutable schema (tables, views, triggers) so a transaction can
    // snapshot and atomically publish all managed catalog state together.
    internal sealed class SchemaCatalog
    {
        public SchemaCatalog(
            Dictionary<string, EmbeddedTable> tables,
            Dictionary<string, ViewDefinition> views,
            Dictionary<string, TriggerDefinition> triggers)
        {
            Tables = tables;
            Views = views;
            Triggers = triggers;
        }

        public Dictionary<string, EmbeddedTable> Tables { get; }

        public Dictionary<string, ViewDefinition> Views { get; }

        public Dictionary<string, TriggerDefinition> Triggers { get; }

        public SchemaCatalog Clone() => new(
            CloneTables(Tables),
            new Dictionary<string, ViewDefinition>(Views, StringComparer.OrdinalIgnoreCase),
            new Dictionary<string, TriggerDefinition>(Triggers, StringComparer.OrdinalIgnoreCase));
    }

    internal sealed class AutoIncrementStatementState
    {
        private readonly Dictionary<string, AutoIncrementTracker> _trackers =
            new(StringComparer.OrdinalIgnoreCase);

        public AutoIncrementTracker GetTracker(
            string tableName,
            EmbeddedTable table,
            IReadOnlyDictionary<string, EmbeddedTable> tables)
        {
            if (!table.IsAutoIncrement)
                throw new InvalidOperationException($"Table '{tableName}' is not AUTOINCREMENT.");
            if (_trackers.TryGetValue(table.Name, out var tracker))
                return tracker;

            ValidateSqliteSequenceCatalog(tables);
            var sequence = tables[SqliteSequenceTableName];
            var sequenceRowIndex = -1;
            for (var index = 0; index < sequence.Rows.Count; index++)
            {
                var name = sequence.Rows[index][0];
                if (name.Kind == SqlValueKind.Text
                    && string.Equals(name.AsText(), table.Name, StringComparison.Ordinal))
                {
                    if (sequenceRowIndex < 0
                        || sequence.RowIds[index] < sequence.RowIds[sequenceRowIndex])
                    {
                        sequenceRowIndex = index;
                    }
                }
            }

            var originalSequence = sequenceRowIndex < 0
                ? 0
                : CoerceSqliteSequenceInteger(sequence.Rows[sequenceRowIndex][1]);
            tracker = new AutoIncrementTracker(
                table.Name,
                sequenceRowIndex < 0 ? null : sequence.RowIds[sequenceRowIndex],
                originalSequence);
            _trackers.Add(table.Name, tracker);
            return tracker;
        }

        public bool Commit(IReadOnlyDictionary<string, EmbeddedTable> tables)
        {
            if (_trackers.Count == 0)
                return false;

            ValidateSqliteSequenceCatalog(tables);
            var sequence = tables[SqliteSequenceTableName];
            var changed = false;
            foreach (var tracker in _trackers.Values)
                changed |= tracker.Commit(sequence);
            return changed;
        }
    }

    internal sealed class AutoIncrementTracker
    {
        private readonly string _tableName;
        private readonly long? _originalSequenceRowId;
        private readonly long _originalSequence;
        private long _highWaterMark;

        public AutoIncrementTracker(
            string tableName,
            long? originalSequenceRowId,
            long originalSequence)
        {
            _tableName = tableName;
            _originalSequenceRowId = originalSequenceRowId;
            _originalSequence = originalSequence;
            _highWaterMark = originalSequence;
        }

        public long NextRowId(bool anyRow, long largestRowId)
        {
            HasAttempt = true;
            if (_highWaterMark == long.MaxValue || (anyRow && largestRowId == long.MaxValue))
                throw new EmbeddedSqlException("database or disk is full");

            var candidate = anyRow ? largestRowId + 1 : 1;
            if (candidate <= _highWaterMark)
                candidate = _highWaterMark + 1;
            Observe(candidate);
            return candidate;
        }

        public void Observe(long rowId)
        {
            HasAttempt = true;
            if (rowId > _highWaterMark)
                _highWaterMark = rowId;
        }

        private bool HasAttempt { get; set; }

        public bool Commit(EmbeddedTable sequence)
        {
            if (!HasAttempt && _originalSequenceRowId is not null)
                return false;

            var sequenceRowIndex = _originalSequenceRowId is { } rowId
                ? sequence.RowIds.IndexOf(rowId)
                : -1;
            if (_originalSequenceRowId is not null && _highWaterMark <= _originalSequence)
                return false;

            if (sequenceRowIndex < 0)
            {
                var newRowId = _originalSequenceRowId
                    ?? (sequence.RowIds.Count == 0
                        ? 1
                        : NextAutoRowId(sequence.RowIds.Max(), new HashSet<long>(sequence.RowIds)));
                var insertionIndex = sequence.RowIds.FindIndex(existingRowId => existingRowId > newRowId);
                if (insertionIndex < 0)
                {
                    sequence.Rows.Add([SqlValue.Text(_tableName), SqlValue.Integer(_highWaterMark)]);
                    sequence.RowIds.Add(newRowId);
                }
                else
                {
                    sequence.Rows.Insert(
                        insertionIndex,
                        [SqlValue.Text(_tableName), SqlValue.Integer(_highWaterMark)]);
                    sequence.RowIds.Insert(insertionIndex, newRowId);
                }
                return true;
            }

            // Whole-row replacement so the RowStore revision (transient-lookup staleness
            // tracking) observes the mutation.
            sequence.Rows[sequenceRowIndex] = [SqlValue.Text(_tableName), SqlValue.Integer(_highWaterMark)];
            return true;
        }
    }

    public EmbeddedConnection Connect() => new(this);

    internal void CopyFunctionAndCollationRegistriesTo(EmbeddedDatabase target)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ArgumentNullException.ThrowIfNull(target);

        KeyValuePair<(string Name, int Arity), Func<IReadOnlyList<SqlValue>, SqlValue>>[] scalarFunctions;
        KeyValuePair<(string Name, int Arity), ManagedAggregateFunction>[] aggregateFunctions;
        KeyValuePair<string, Func<string, string, int>>[] collations;
        lock (_gate)
        {
            scalarFunctions = _scalarFunctions.ToArray();
            aggregateFunctions = _aggregateFunctions.ToArray();
            collations = _collations.ToArray();
        }

        foreach (var ((name, arity), function) in scalarFunctions)
            target.RegisterScalarFunction(name, arity, function);
        foreach (var ((name, arity), function) in aggregateFunctions)
            target.RegisterAggregateFunction(name, arity, function.Seed, function.Step, function.Finalize);
        foreach (var (name, compare) in collations)
            target.RegisterCollation(name, compare);
    }

    public void RegisterScalarFunction(string name, int arity, Func<IReadOnlyList<SqlValue>, SqlValue> function)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ArgumentException.ThrowIfNullOrWhiteSpace(name);
        if (arity < -1)
            throw new ArgumentOutOfRangeException(nameof(arity));
        ArgumentNullException.ThrowIfNull(function);

        lock (_gate)
        {
            _scalarFunctions[(name.ToUpperInvariant(), arity)] = function;
        }
    }

    public bool UnregisterScalarFunction(string name, int arity)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ArgumentException.ThrowIfNullOrWhiteSpace(name);
        if (arity < -1)
            throw new ArgumentOutOfRangeException(nameof(arity));

        lock (_gate)
        {
            return _scalarFunctions.Remove((name.ToUpperInvariant(), arity));
        }
    }

    public int UnregisterScalarFunctions(string name)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ArgumentException.ThrowIfNullOrWhiteSpace(name);

        lock (_gate)
        {
            var normalizedName = name.ToUpperInvariant();
            var keys = _scalarFunctions.Keys
                .Where(key => key.Name == normalizedName)
                .ToArray();
            foreach (var key in keys)
                _scalarFunctions.Remove(key);

            return keys.Length;
        }
    }

    public void RegisterAggregateFunction(
        string name,
        int arity,
        SqlValue seed,
        Func<SqlValue, IReadOnlyList<SqlValue>, SqlValue> step,
        Func<SqlValue, SqlValue> finalize)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ArgumentException.ThrowIfNullOrWhiteSpace(name);
        if (arity < -1)
            throw new ArgumentOutOfRangeException(nameof(arity));
        ArgumentNullException.ThrowIfNull(step);
        ArgumentNullException.ThrowIfNull(finalize);

        lock (_gate)
        {
            _aggregateFunctions[(name.ToUpperInvariant(), arity)] = new ManagedAggregateFunction(seed, step, finalize);
        }
    }

    public int UnregisterAggregateFunctions(string name)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ArgumentException.ThrowIfNullOrWhiteSpace(name);

        lock (_gate)
        {
            var normalizedName = name.ToUpperInvariant();
            var keys = _aggregateFunctions.Keys
                .Where(key => key.Name == normalizedName)
                .ToArray();
            foreach (var key in keys)
                _aggregateFunctions.Remove(key);

            return keys.Length;
        }
    }

    public void RegisterCollation(string name, Func<string, string, int> compare)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ArgumentException.ThrowIfNullOrWhiteSpace(name);
        ArgumentNullException.ThrowIfNull(compare);

        lock (_gate)
        {
            _collations[name.ToUpperInvariant()] = compare;
        }
    }

    public bool UnregisterCollation(string name)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ArgumentException.ThrowIfNullOrWhiteSpace(name);

        lock (_gate)
        {
            return _collations.Remove(name.ToUpperInvariant());
        }
    }

    internal ExecutionResult Execute(
        ParsedStatement statement,
        SqlValue[] parameters,
        long lastInsertRowId = 0,
        bool foreignKeysEnabled = false,
        bool recursiveTriggersEnabled = false,
        bool deferForeignKeys = false,
        bool inTransaction = false,
        CancellationToken cancellationToken = default,
        bool compilationEnabled = true,
        TempTriggerBridge? tempTriggers = null,
        ManagedStatementHooks? hooks = null)
    {
        var result = ExecuteCore(
            statement,
            parameters,
            lastInsertRowId,
            foreignKeysEnabled,
            recursiveTriggersEnabled,
            deferForeignKeys,
            inTransaction,
            cancellationToken,
            compilationEnabled,
            tempTriggers,
            hooks);

        RecordChangeCounters(statement, result);
        return result;
    }

    /// <summary>
    /// Mirrors sqlite3_changes()/sqlite3_total_changes(): only INSERT, UPDATE, and
    /// DELETE update the counters, and every other statement leaves them intact.
    /// </summary>
    internal void RecordChangeCounters(ParsedStatement statement, ExecutionResult result)
    {
        if (statement is not (InsertStatement or UpdateStatement or DeleteStatement))
            return;

        _changes = result.RowsAffected;
        _totalChanges += result.RowsAffected;
    }

    private ExecutionResult ExecuteCore(
        ParsedStatement statement,
        SqlValue[] parameters,
        long lastInsertRowId = 0,
        bool foreignKeysEnabled = false,
        bool recursiveTriggersEnabled = false,
        bool deferForeignKeys = false,
        bool inTransaction = false,
        CancellationToken cancellationToken = default,
        bool compilationEnabled = true,
        TempTriggerBridge? tempTriggers = null,
        ManagedStatementHooks? hooks = null)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        if (RequiresRecursiveTriggerStack(
                statement,
                recursiveTriggersEnabled,
                hasTriggers: true))
        {
            return ExecuteWithRecursiveTriggerStack(() => ExecuteCore(
                statement,
                parameters,
                lastInsertRowId,
                foreignKeysEnabled,
                recursiveTriggersEnabled,
                deferForeignKeys,
                inTransaction,
                cancellationToken,
                compilationEnabled,
                tempTriggers,
                hooks));
        }

        cancellationToken.ThrowIfCancellationRequested();
        // An autocommit write that finds its snapshot stale reloads the catalog
        // and restarts the whole statement against the new snapshot, mirroring
        // SQLite's SQLITE_SCHEMA statement restart: everything up to the persist
        // lives in the discarded working clone, so re-execution is safe and
        // cannot clobber the other writer's committed rows. Explicit-transaction
        // and file-less paths fail fast as before. The retry budget is the
        // database's busy timeout (zero preserves the original fail-fast shape).
        var busyRetryDeadline = IsFileBacked && BusyTimeout > TimeSpan.Zero
            ? GetBusyWaitDeadline(BusyTimeout)
            : 0L;
        while (true)
        {
        try
        {
        lock (_gate)
        {
            // A commit hook can veto the implicit commit of an autocommit mutation, so the
            // statement has to run against a working clone that can be discarded. The in-memory
            // fast path below mutates the live catalog in place and cannot be rolled back, so an
            // installed gate forces the clone-and-publish shape here.
            var commitGate = hooks?.CommitGate;
            if ((cancellationToken.CanBeCanceled || commitGate is not null) && MayMutate(statement))
            {
                var cancellableWorking = new SchemaCatalog(_tables, _views, _triggers).Clone();
                ExecutionResult cancellableResult;
                try
                {
                    cancellableResult = Execute(
                        statement,
                        parameters,
                        cancellableWorking,
                        lastInsertRowId,
                        foreignKeysEnabled,
                        recursiveTriggersEnabled,
                        deferForeignKeys,
                        inTransaction,
                        cancellationToken,
                        compilationEnabled,
                        tempTriggers,
                        hooks);
                }
                catch (EmbeddedConflictFailException)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    // ON CONFLICT FAIL keeps the rows written before the failure, so this is still
                    // a commit and the hook still gets to veto it.
                    if (commitGate is not null && !commitGate())
                        throw new EmbeddedCommitVetoException();
                    if (_fileStore is null)
                        PublishCatalog(cancellableWorking);
                    else
                        PersistFileCatalog(
                            cancellableWorking,
                            busyTimeout: GetRemainingBusyTimeout(busyRetryDeadline));
                    throw;
                }

                cancellationToken.ThrowIfCancellationRequested();
                if (!cancellableResult.Changed)
                    return cancellableResult;

                if (commitGate is not null && !commitGate())
                    throw new EmbeddedCommitVetoException();

                if (_fileStore is null)
                {
                    if (MayChangeSchema(statement))
                    {
                        _inMemoryPragmaHeader = _inMemoryPragmaHeader with
                        {
                            SchemaVersion = unchecked(_inMemoryPragmaHeader.SchemaVersion + 1),
                        };
                    }

                    PublishCatalog(cancellableWorking);
                }
                else
                {
                    PersistFileCatalog(
                        cancellableWorking,
                        forceFullRewrite: cancellableResult.ForceFullCatalogRewrite,
                        busyTimeout: GetRemainingBusyTimeout(busyRetryDeadline));
                }

                return cancellableResult;
            }

            if (_fileStore is null)
            {
                ExecutionResult inMemoryResult;
                try
                {
                    inMemoryResult = Execute(
                        statement,
                        parameters,
                        new SchemaCatalog(_tables, _views, _triggers),
                        lastInsertRowId,
                        foreignKeysEnabled,
                        recursiveTriggersEnabled,
                        deferForeignKeys,
                        inTransaction,
                        cancellationToken,
                        compilationEnabled,
                        tempTriggers,
                        hooks);
                }
                catch (EmbeddedConflictFailException)
                {
                    _version++;
                    throw;
                }
                if (inMemoryResult.Changed)
                {
                    if (MayChangeSchema(statement))
                        _inMemoryPragmaHeader = _inMemoryPragmaHeader with
                        {
                            SchemaVersion = unchecked(_inMemoryPragmaHeader.SchemaVersion + 1),
                        };
                    _version++;
                }

                return inMemoryResult;
            }

            // For file-backed databases a mutating autocommit statement runs against
            // a working clone so that a rejected pre-commit persist rolls back
            // cleanly. A reported post-commit maintenance failure instead publishes
            // the catalog because the WAL mutation is already durable.
            if (!MayMutate(statement))
                return Execute(
                    statement,
                    parameters,
                    new SchemaCatalog(_tables, _views, _triggers),
                    lastInsertRowId,
                    foreignKeysEnabled,
                    recursiveTriggersEnabled,
                    deferForeignKeys,
                    inTransaction,
                    cancellationToken,
                    compilationEnabled,
                    tempTriggers,
                    hooks);

            var working = new SchemaCatalog(_tables, _views, _triggers).Clone();
            ExecutionResult result;
            try
            {
                result = Execute(
                    statement,
                    parameters,
                    working,
                    lastInsertRowId,
                    foreignKeysEnabled,
                    recursiveTriggersEnabled,
                    deferForeignKeys,
                    inTransaction,
                    cancellationToken,
                    compilationEnabled,
                    tempTriggers,
                    hooks);
            }
            catch (EmbeddedConflictFailException)
            {
                PersistFileCatalog(
                    working,
                    busyTimeout: GetRemainingBusyTimeout(busyRetryDeadline));
                throw;
            }
            if (result.Changed)
            {
                PersistFileCatalog(
                    working,
                    forceFullRewrite: result.ForceFullCatalogRewrite,
                    busyTimeout: GetRemainingBusyTimeout(busyRetryDeadline));
            }
            else if (!inTransaction)
            {
                // A mutating autocommit statement that produced no change (most
                // importantly a conflicting INSERT OR IGNORE returning changes()==0)
                // decided its outcome against the heap clone. If another connection
                // committed meanwhile (e.g. deleted the conflicting row), that decision
                // is stale: native SQLite serializes the conflicting write through the
                // write lock against the live btree, so a loser retries and can win.
                // Force the same stale-check the persist path runs so a changed durable
                // version reloads the catalog and re-executes this statement instead of
                // silently returning the stale outcome (ENGINE #17 migrations lock).
                EnsureFileCatalogVersionCurrent(GetRemainingBusyTimeout(busyRetryDeadline));
            }

            return result;
        }
        }
        catch (EmbeddedCatalogSnapshotStaleException)
        {
            if (busyRetryDeadline == 0)
                throw;

            ReloadFileCatalogAfterStale();
            cancellationToken.ThrowIfCancellationRequested();
        }
        }
    }

    /// <summary>
    /// Executes one statement from a temp trigger body that targets this database while another
    /// database is running the statement that fired the trigger. The outer context supplies the
    /// OLD/NEW row and the recursion guard so the body behaves exactly like a local trigger body.
    /// </summary>
    /// <param name="statement">The trigger body statement to execute against this database.</param>
    /// <param name="catalog">This database's catalog that the body statement resolves against.</param>
    /// <param name="outer">
    /// The firing statement's context, supplying the OLD/NEW row, recursion guard and cancellation.
    /// </param>
    /// <param name="hooks">
    /// Hooks scoped to <em>this</em> database: the update hook reports the schema that actually
    /// changed, so the caller rebuilds them rather than forwarding the firing database's.
    /// </param>
    internal ExecutionResult ExecuteTriggerBodyStatement(
        ParsedStatement statement,
        SchemaCatalog catalog,
        QueryContext outer,
        ManagedStatementHooks? hooks)
    {
        lock (_gate)
        {
            if (_readOnly && MayMutate(statement))
                throw new EmbeddedSqlException("attempt to write a readonly database");

            var context = new QueryContext(
                catalog.Tables,
                new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
                catalog.Views,
                catalog.Triggers,
                InsideTrigger: true,
                LastInsertRowId: outer.LastInsertRowId,
                ForeignKeysEnabled: outer.ForeignKeysEnabled,
                DeferForeignKeys: outer.DeferForeignKeys,
                InTransaction: outer.InTransaction,
                RecursiveTriggersEnabled: outer.RecursiveTriggersEnabled,
                ActiveTriggers: outer.ActiveTriggers,
                TriggerDepth: outer.TriggerDepth,
                TriggerRow: outer.TriggerRow,
                CancellationToken: outer.CancellationToken,
                StatementState: new StatementExecutionState(outer.LastInsertRowId),
                CompilationEnabled: false,
                Hooks: hooks);
            return statement switch
            {
                InsertStatement insert => ExecuteDmlWithAutoIncrementState(
                    context,
                    scoped => ExecuteInsert(insert, EmptyParameters, scoped)),
                UpdateStatement update => ExecuteDmlWithAutoIncrementState(
                    context,
                    scoped => ExecuteUpdate(update, EmptyParameters, scoped)),
                DeleteStatement delete => ExecuteDmlWithAutoIncrementState(
                    context,
                    scoped => ExecuteDelete(delete, EmptyParameters, scoped)),
                QueryStatement query => ExecuteQuery(query, EmptyParameters, context, outerRow: null),
                _ => throw new EmbeddedSqlException(
                    $"unsupported trigger body statement {statement.GetType().Name}"),
            };
        }
    }

    /// <summary>The live catalog dictionaries, for connection-owned temp schema bookkeeping.</summary>
    internal SchemaCatalog LiveCatalog
    {
        get
        {
            lock (_gate)
                return new SchemaCatalog(_tables, _views, _triggers);
        }
    }

    /// <summary>
    /// Publishes the working catalog a temp trigger body mutated. The connection only calls this
    /// once the statement that fired the trigger succeeded, so a failed statement discards the
    /// working copy exactly like a failed local statement does.
    /// </summary>
    internal void PublishTriggerBodyCatalog(SchemaCatalog catalog, bool forceFullRewrite)
    {
        lock (_gate)
        {
            _inMemoryPragmaHeader = _inMemoryPragmaHeader with
            {
                SchemaVersion = unchecked(_inMemoryPragmaHeader.SchemaVersion + 1),
            };
            if (_fileStore is null)
                PublishCatalog(catalog);
            else
                PersistFileCatalog(catalog, forceFullRewrite: forceFullRewrite);
        }
    }

    internal bool HasTriggers
    {
        get
        {
            lock (_gate)
                return _triggers.Count > 0;
        }
    }

    internal IReadOnlyList<TriggerDefinition> SnapshotTriggers()
    {
        lock (_gate)
            return _triggers.Values.ToArray();
    }

    internal void MarkSchemaMutated()
    {
        lock (_gate)
        {
            _inMemoryPragmaHeader = _inMemoryPragmaHeader with
            {
                SchemaVersion = unchecked(_inMemoryPragmaHeader.SchemaVersion + 1),
            };
            _version++;
        }
    }

    // A temp trigger that watches a table in another schema is dropped with that table, matching
    // SQLite, but the trigger lives in the temp catalog so the connection has to prune it there.
    internal static bool RemoveForeignTargetTriggers(
        SchemaCatalog catalog,
        string targetSchema,
        string tableName)
    {
        var orphaned = catalog.Triggers
            .Where(entry => entry.Value.TargetSchema is { } schema
                && schema.Equals(targetSchema, StringComparison.OrdinalIgnoreCase)
                && string.Equals(entry.Value.TableName, tableName, StringComparison.OrdinalIgnoreCase))
            .Select(entry => entry.Key)
            .ToArray();
        foreach (var trigger in orphaned)
            catalog.Triggers.Remove(trigger);
        return orphaned.Length != 0;
    }

    internal static bool MayMutate(ParsedStatement statement) => statement is
        CreateTableStatement or CreateTableAsSelectStatement
        or DropTableStatement or CreateIndexStatement or DropIndexStatement
        or CreateViewStatement or DropViewStatement or CreateTriggerStatement or DropTriggerStatement
        or AlterTableAddColumnStatement or AlterTableRenameStatement or AlterTableRenameColumnStatement
        or AlterTableDropColumnStatement
        or InsertStatement or UpdateStatement or DeleteStatement or WithDmlStatement
        or ReindexStatement or VacuumStatement
        or PragmaHeaderIntegerStatement { Value: not null }
        or PragmaJournalModeStatement { Mode: not null };

    internal static bool MayChangeSchema(ParsedStatement statement) => statement is
        CreateTableStatement or CreateTableAsSelectStatement
        or DropTableStatement or CreateIndexStatement or DropIndexStatement
        or CreateViewStatement or DropViewStatement or CreateTriggerStatement or DropTriggerStatement
        or AlterTableAddColumnStatement or AlterTableRenameStatement or AlterTableRenameColumnStatement
        or AlterTableDropColumnStatement;

    /// <summary>
    /// A read-only view over the live schema, used to resolve column ownership while an
    /// authorizer inspects a statement. It deliberately does not clone, does not take a
    /// transaction snapshot, and must never be mutated.
    /// </summary>
    internal SchemaCatalog CreateAuthorizationCatalog()
    {
        lock (_gate)
            return new SchemaCatalog(_tables, _views, _triggers);
    }

    internal TransactionSnapshot CreateTransactionSnapshot(TimeSpan busyTimeout = default)
    {
        lock (_gate)
        {
            if (_fileStore is not null)
            {
                if (_fileCatalogWriteLock is null)
                    throw new InvalidOperationException("The managed file catalog persistence state is not initialized.");

                lock (_fileCatalogWriteLock)
                {
                    if (_foreignReadOnly)
                    {
                        RefreshForeignCatalogIfChangedLocked();
                    }
                    else
                    {
                        // BEGIN has no working state yet, so a stale snapshot is
                        // simply re-read: the same catalog a freshly opened SQLite
                        // connection would observe.
                        while (true)
                        {
                            try
                            {
                                EnsureFileCatalogVersionCurrent(busyTimeout);
                                break;
                            }
                            catch (EmbeddedCatalogSnapshotStaleException)
                            {
                                if (TryReloadFileCatalogIfChanged())
                                    break;
                                // The reload lost a mid-flight commit race; loop
                                // to re-wait for stability and try again.
                            }
                        }
                    }
                }
            }

            var pragmaHeader = _fileStore is null
                ? _inMemoryPragmaHeader
                : new PragmaHeaderMetadata(
                    unchecked((int)_fileCatalogVersion.SchemaCookie),
                    _fileCatalogVersion.UserVersion,
                    _fileCatalogVersion.ApplicationId);
            var catalog = new SchemaCatalog(_tables, _views, _triggers).Clone();
            _activeTransactions = checked(_activeTransactions + 1);
            return new TransactionSnapshot(
                catalog,
                _version,
                pragmaHeader);
        }
    }

    internal SqlValue EvaluateConstant(Expression expression, SqlValue[] parameters, long lastInsertRowId)
    {
        lock (_gate)
        {
            return Evaluate(
                expression,
                parameters,
                row: null,
                new QueryContext(
                    _tables,
                    new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
                    _views,
                    _triggers,
                    LastInsertRowId: lastInsertRowId));
        }
    }

    internal void EndTransaction()
    {
        lock (_gate)
        {
            if (_activeTransactions == 0)
                throw new InvalidOperationException("Managed transaction count underflow.");
            _activeTransactions--;
        }
    }

    internal string[] DescribeColumns(QueryStatement statement)
    {
        lock (_gate)
        {
            var context = new QueryContext(
                _tables,
                new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
                _views,
                _triggers);
            ValidateQueryIndexDirectives(statement, context);
            return DescribeQuery(statement, context);
        }
    }

    internal string[] DescribeColumns(QueryStatement statement, SchemaCatalog catalog)
    {
        lock (_gate)
        {
            var context = new QueryContext(
                catalog.Tables,
                new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
                catalog.Views,
                catalog.Triggers);
            ValidateQueryIndexDirectives(statement, context);
            return DescribeQuery(statement, context);
        }
    }

    internal CreateTableMaterialization MaterializeCreateTableAs(
        QueryStatement statement,
        SqlValue[] parameters,
        long lastInsertRowId,
        bool foreignKeysEnabled,
        bool recursiveTriggersEnabled,
        CancellationToken cancellationToken)
    {
        lock (_gate)
        {
            return MaterializeCreateTableAs(
                statement,
                parameters,
                new SchemaCatalog(_tables, _views, _triggers),
                lastInsertRowId,
                foreignKeysEnabled,
                recursiveTriggersEnabled,
                cancellationToken);
        }
    }

    internal CreateTableMaterialization MaterializeCreateTableAs(
        QueryStatement statement,
        SqlValue[] parameters,
        SchemaCatalog catalog,
        long lastInsertRowId,
        bool foreignKeysEnabled,
        bool recursiveTriggersEnabled,
        CancellationToken cancellationToken)
    {
        var context = new QueryContext(
            catalog.Tables,
            new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
            catalog.Views,
            catalog.Triggers,
            LastInsertRowId: lastInsertRowId,
            ForeignKeysEnabled: foreignKeysEnabled,
            RecursiveTriggersEnabled: recursiveTriggersEnabled,
            CancellationToken: cancellationToken);
        var result = MaterializeQueryResult(ExecuteQuery(statement, parameters, context, outerRow: null));
        var affinities = DescribeQueryAffinities(
            statement,
            context,
            new Dictionary<string, IReadOnlyList<QueryAffinityColumn>>(StringComparer.OrdinalIgnoreCase));
        if (affinities.Count != result.Columns.Length)
            throw new InvalidOperationException("CREATE TABLE AS SELECT affinity metadata does not match the result width.");

        var names = MakeCreateTableColumnNamesUnique(result.Columns);
        var columns = new EmbeddedColumn[names.Length];
        for (var index = 0; index < columns.Length; index++)
        {
            columns[index] = new EmbeddedColumn(
                names[index],
                CtasDeclaredType(affinities[index].Affinity),
                PrimaryKey: false,
                NotNull: false,
                Unique: false,
                DefaultValue: null);
        }

        var rows = new SqlValue[result.Rows.Count][];
        for (var rowIndex = 0; rowIndex < rows.Length; rowIndex++)
        {
            cancellationToken.ThrowIfCancellationRequested();
            rows[rowIndex] = MaterializeQueryRow(result.Rows[rowIndex]);
        }

        return new CreateTableMaterialization(columns, rows);
    }

    internal bool ContainsTableOrView(string name)
    {
        lock (_gate)
            return _tables.ContainsKey(name) || _views.ContainsKey(name);
    }

    internal bool ContainsSchemaObject(string name, ManagedSchemaObjectKind kind)
    {
        lock (_gate)
        {
            return kind switch
            {
                ManagedSchemaObjectKind.Table => _tables.ContainsKey(name),
                ManagedSchemaObjectKind.View => _views.ContainsKey(name),
                ManagedSchemaObjectKind.Trigger => _triggers.ContainsKey(name),
                ManagedSchemaObjectKind.Index => _tables.Values.Any(table =>
                    table.Indexes.Any(index =>
                        string.Equals(index.Name, name, StringComparison.OrdinalIgnoreCase))
                    || string.Equals(
                        table.WithoutRowidPrimaryKeyIndexName,
                        name,
                        StringComparison.OrdinalIgnoreCase)),
                _ => throw new InvalidOperationException($"Unknown managed schema object kind {kind}."),
            };
        }
    }

    // Extracts the target table and RETURNING projections from a DML statement so callers
    // can treat INSERT/UPDATE/DELETE ... RETURNING as row-producing.
    internal static bool TryGetReturning(
        ParsedStatement statement,
        out string tableName,
        out IReadOnlyList<Projection> returning)
    {
        switch (statement)
        {
            case WithDmlStatement with:
                return TryGetReturning(with.Dml, out tableName, out returning);
            case InsertStatement { Returning: { } insertReturning } insert:
                tableName = insert.TableName;
                returning = insertReturning;
                return true;
            case UpdateStatement { Returning: { } updateReturning } update:
                tableName = update.TableName;
                returning = updateReturning;
                return true;
            case DeleteStatement { Returning: { } deleteReturning } delete:
                tableName = delete.TableName;
                returning = deleteReturning;
                return true;
            default:
                tableName = string.Empty;
                returning = null!;
                return false;
        }
    }

    internal string[] DescribeReturning(string tableName, IReadOnlyList<Projection> returning)
    {
        lock (_gate)
        {
            return DescribeReturning(tableName, returning, new SchemaCatalog(_tables, _views, _triggers));
        }
    }

    internal string[] DescribeReturning(
        string tableName,
        IReadOnlyList<Projection> returning,
        SchemaCatalog catalog)
    {
        if (!catalog.Tables.TryGetValue(tableName, out var table))
            throw new EmbeddedSqlException($"no such table: {tableName}");

        var outputColumns = BuildOutputColumns(tableName, table.Columns);
        return GetColumnNames(returning, outputColumns, outputColumns);
    }

    internal void CommitTransaction(
        SchemaCatalog catalog,
        long version,
        PragmaHeaderMetadata? pragmaHeader = null,
        bool forceFullRewrite = false,
        TimeSpan busyTimeout = default)
    {
        lock (_gate)
        {
            if (_readOnly)
                throw new EmbeddedSqlException("attempt to write a readonly database");

            if (_version != version)
                throw new EmbeddedSqlException("database is locked");

            if (_fileStore is null)
            {
                if (pragmaHeader is { } metadata)
                    _inMemoryPragmaHeader = metadata;
                PublishCatalog(catalog);
                return;
            }

            PersistFileCatalog(catalog, pragmaHeader, forceFullRewrite, busyTimeout);
        }
    }

    internal PragmaHeaderMetadata GetPragmaHeaderMetadata()
    {
        lock (_gate)
        {
            return _fileStore is null
                ? _inMemoryPragmaHeader
                : new PragmaHeaderMetadata(
                    unchecked((int)_fileCatalogVersion.SchemaCookie),
                    _fileCatalogVersion.UserVersion,
                    _fileCatalogVersion.ApplicationId);
        }
    }

    internal IDisposable OpenBlobMutationLease(string tableName, long rowId)
    {
        lock (_gate)
        {
            var identity = new BlobMutationIdentity(tableName, rowId);
            _activeBlobMutations.TryGetValue(identity, out var handles);
            _activeBlobMutations[identity] = checked(handles + 1);
            return new BlobMutationLease(this, identity);
        }
    }

    internal IDisposable OpenStatementReaderLease()
    {
        lock (_gate)
        {
            _activeStatementReaders = checked(_activeStatementReaders + 1);
            return new StatementReaderLease(this);
        }
    }

    internal long GetBlobMutationGeneration(string tableName, long rowId)
    {
        lock (_gate)
        {
            return _blobMutationGenerations.GetValueOrDefault(new BlobMutationIdentity(tableName, rowId));
        }
    }

    internal bool HasOpenBlobHandles
    {
        get
        {
            lock (_gate)
                return _activeBlobMutations.Count > 0;
        }
    }

    internal bool HasUpdateTrigger(string tableName)
    {
        lock (_gate)
        {
            return _triggers.Values.Any(trigger =>
                trigger.Event == TriggerEvent.Update
                && string.Equals(trigger.TableName, tableName, StringComparison.OrdinalIgnoreCase));
        }
    }

    internal void RecordBlobMutation(string tableName, long rowId)
    {
        lock (_gate)
        {
            var identity = new BlobMutationIdentity(tableName, rowId);
            if (_activeBlobMutations.ContainsKey(identity))
                _blobMutationGenerations[identity] = checked(++_nextBlobMutationGeneration);
        }
    }

    internal void ReleaseBlobMutationLease(BlobMutationIdentity identity)
    {
        lock (_gate)
        {
            var handles = _activeBlobMutations[identity] - 1;
            if (handles == 0)
            {
                _activeBlobMutations.Remove(identity);
                _blobMutationGenerations.Remove(identity);
                return;
            }

            _activeBlobMutations[identity] = handles;
        }
    }

    internal void ReleaseStatementReaderLease()
    {
        lock (_gate)
        {
            if (_activeStatementReaders == 0)
                throw new InvalidOperationException("Managed statement reader count underflow.");
            _activeStatementReaders--;
        }
    }

    internal int GetPageSize()
    {
        lock (_gate)
            return _fileStore is null ? SqlitePageSize.Default : _fileCatalogVersion.PageSize;
    }

    internal uint GetPageCount()
    {
        lock (_gate)
        {
            if (_fileStore is null)
                throw new EmbeddedSqlException("Managed PRAGMA page_count requires a file-backed database.");
            return _fileCatalogVersion.DatabaseSizeInPages;
        }
    }

    internal uint GetFreelistCount()
    {
        lock (_gate)
        {
            if (_fileStore is null)
                throw new EmbeddedSqlException("Managed PRAGMA freelist_count requires a file-backed database.");
            return _fileCatalogVersion.FreelistPageCount;
        }
    }

    internal SqliteTextEncoding GetTextEncoding()
    {
        lock (_gate)
        {
            return _fileStore is null || _fileCatalogVersion.TextEncoding == SqliteTextEncoding.Unset
                ? SqliteTextEncoding.Utf8
                : _fileCatalogVersion.TextEncoding;
        }
    }

    internal SqliteJournalMode GetJournalMode()
    {
        lock (_gate)
            return _fileStore is null ? SqliteJournalMode.Delete : _fileStore.JournalMode;
    }

    internal SqliteJournalMode SwitchJournalMode(SqliteJournalMode journalMode, TimeSpan busyTimeout = default)
    {
        lock (_gate)
        {
            if (_fileStore is null)
                throw new EmbeddedSqlException("In-memory databases support only MEMORY journal mode.");
            if (_readOnly)
                throw new EmbeddedSqlException("attempt to write a readonly database");
            if (_activeTransactions != 0)
                throw new EmbeddedSqlException("cannot change journal mode while a transaction is active");
            if (_activeStatementReaders != 0)
                throw new EmbeddedSqlException("cannot change journal mode while a SQL statement is in progress");
            if (_activeBlobMutations.Count != 0)
                throw new EmbeddedSqlException("cannot change journal mode while a blob handle is active");
            if (_fileSystem is null || _fileCatalogWriteLock is null)
                throw new InvalidOperationException("The managed file catalog persistence state is not initialized.");

            lock (_fileCatalogWriteLock)
            {
                using var catalogWriteLease = EnterPhysicalFileCatalogWriteLock(_fileSystem, _databasePath);
                EnsureFileCatalogVersionCurrent(busyTimeout);
                using var writeRegistration = RegisterCatalogWrite(_databasePath);
                var result = _fileStore.SwitchJournalMode(journalMode);
                _fileCatalogVersion = ReadFileCatalogVersion(_fileSystem, _databasePath);
                _version++;
                return result;
            }
        }
    }

    internal void MigratePageSize(int pageSize, TimeSpan busyTimeout = default)
    {
        lock (_gate)
        {
            if (_fileStore is null)
                throw new EmbeddedSqlException("In-memory databases have a fixed managed page size.");
            if (_readOnly)
                throw new EmbeddedSqlException("attempt to write a readonly database");
            if (_activeTransactions != 0)
                throw new EmbeddedSqlException("cannot VACUUM while a transaction is active");
            if (_activeStatementReaders != 0)
                throw new EmbeddedSqlException("cannot VACUUM - SQL statements in progress");
            if (_activeBlobMutations.Count != 0)
                throw new EmbeddedSqlException("cannot VACUUM while a blob handle is active");
            if (_fileSystem is null || _fileCatalogWriteLock is null)
                throw new InvalidOperationException("The managed file catalog persistence state is not initialized.");

            lock (_fileCatalogWriteLock)
            {
                using var catalogWriteLease = EnterPhysicalFileCatalogWriteLock(_fileSystem, _databasePath);
                EnsureFileCatalogVersionCurrent(busyTimeout);
                using var writeRegistration = RegisterCatalogWrite(_databasePath);
                if (pageSize == _fileCatalogVersion.PageSize)
                    _fileStore.Compact();
                else
                    _fileStore.MigratePageSize(pageSize, _tables, _views, _triggers);
                _fileStore.AdoptCommittedTables(_tables);
                _fileCatalogVersion = ReadFileCatalogVersion(_fileSystem, _databasePath);
                _version++;
            }
        }
    }

    internal void VacuumInto(string destinationPath, int pageSize, TimeSpan busyTimeout = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(destinationPath);
        lock (_gate)
        {
            if (_fileStore is null)
                throw new EmbeddedSqlException("Managed VACUUM INTO requires a file-backed source database.");
            if (_readOnly)
                throw new EmbeddedSqlException("attempt to write a readonly database");
            if (_activeTransactions != 0)
                throw new EmbeddedSqlException("cannot VACUUM while a transaction is active");
            if (_activeStatementReaders != 0)
                throw new EmbeddedSqlException("cannot VACUUM - SQL statements in progress");
            if (_activeBlobMutations.Count != 0)
                throw new EmbeddedSqlException("cannot VACUUM while a blob handle is active");
            if (_fileSystem is null || _fileCatalogWriteLock is null)
                throw new InvalidOperationException("The managed file catalog persistence state is not initialized.");

            var destinationWriteLock = GetFileCatalogWriteLock(_fileSystem, destinationPath);
            var sourceLockPath = GetFileCatalogLockPath(_fileSystem, _databasePath);
            var destinationLockPath = GetFileCatalogLockPath(_fileSystem, destinationPath);
            if (string.Equals(sourceLockPath, destinationLockPath, StringComparison.Ordinal))
                throw new EmbeddedSqlException("output file already exists");

            if (string.CompareOrdinal(sourceLockPath, destinationLockPath) < 0)
            {
                lock (_fileCatalogWriteLock)
                {
                    using var sourceWriteLease =
                        EnterPhysicalFileCatalogWriteLock(_fileSystem, _databasePath);
                    lock (destinationWriteLock)
                    {
                        using var destinationWriteLease =
                            EnterPhysicalFileCatalogWriteLock(_fileSystem, destinationPath);
                        VacuumIntoCore(destinationPath, pageSize, busyTimeout);
                    }
                }
            }
            else
            {
                lock (destinationWriteLock)
                {
                    using var destinationWriteLease =
                        EnterPhysicalFileCatalogWriteLock(_fileSystem, destinationPath);
                    lock (_fileCatalogWriteLock)
                    {
                        using var sourceWriteLease =
                            EnterPhysicalFileCatalogWriteLock(_fileSystem, _databasePath);
                        VacuumIntoCore(destinationPath, pageSize, busyTimeout);
                    }
                }
            }
        }
    }

    private void VacuumIntoCore(string destinationPath, int pageSize, TimeSpan busyTimeout)
    {
        EnsureFileCatalogVersionCurrent(busyTimeout);
        _fileStore!.VacuumInto(
            destinationPath,
            pageSize,
            _tables,
            _views,
            _triggers);
    }

    internal void SetPragmaHeaderInteger(
        PragmaHeaderIntegerKind kind,
        int value,
        TimeSpan busyTimeout = default,
        CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (_readOnly)
                throw new EmbeddedSqlException("attempt to write a readonly database");

            if (_fileStore is null)
            {
                var updated = UpdatePragmaHeaderInteger(_inMemoryPragmaHeader, kind, value);
                if (_inMemoryPragmaHeader == updated)
                    return;
                _inMemoryPragmaHeader = updated;
                _version++;
                return;
            }
            if (_fileSystem is null || _fileCatalogWriteLock is null)
                throw new InvalidOperationException("The managed file catalog persistence state is not initialized.");

            lock (_fileCatalogWriteLock)
            {
                using var catalogWriteLease = EnterPhysicalFileCatalogWriteLock(_fileSystem, _databasePath);
                EnsureFileCatalogVersionCurrent(busyTimeout);
                using var writeRegistration = RegisterCatalogWrite(_databasePath);
                var current = new PragmaHeaderMetadata(
                    unchecked((int)_fileCatalogVersion.SchemaCookie),
                    _fileCatalogVersion.UserVersion,
                    _fileCatalogVersion.ApplicationId);
                var updated = UpdatePragmaHeaderInteger(current, kind, value);
                if (current == updated)
                    return;
                cancellationToken.ThrowIfCancellationRequested();
                try
                {
                    _fileCatalogVersion = _fileStore.UpdatePragmaHeader(updated);
                    _version++;
                }
                catch (EmbeddedPostCommitMaintenanceException)
                {
                    _fileCatalogVersion = _fileStore.CommittedCatalogVersion;
                    _version++;
                    throw;
                }
            }
        }
    }

    private static PragmaHeaderMetadata UpdatePragmaHeaderInteger(
        PragmaHeaderMetadata current,
        PragmaHeaderIntegerKind kind,
        int value)
        => kind switch
        {
            PragmaHeaderIntegerKind.SchemaVersion => current with { SchemaVersion = value },
            PragmaHeaderIntegerKind.UserVersion => current with { UserVersion = value },
            PragmaHeaderIntegerKind.ApplicationId => current with { ApplicationId = value },
            _ => throw new InvalidOperationException($"Unknown PRAGMA header integer kind {kind}."),
        };

    private void PersistFileCatalog(
        SchemaCatalog catalog,
        PragmaHeaderMetadata? pragmaHeader = null,
        bool forceFullRewrite = false,
        TimeSpan busyTimeout = default)
    {
        if (_fileStore is null || _fileSystem is null || _fileCatalogWriteLock is null)
            throw new InvalidOperationException("The managed file catalog persistence state is not initialized.");

        lock (_fileCatalogWriteLock)
        {
            using var catalogWriteLease = EnterPhysicalFileCatalogWriteLock(_fileSystem, _databasePath);
            EnsureFileCatalogVersionCurrent(busyTimeout);
            using var writeRegistration = RegisterCatalogWrite(_databasePath);
            try
            {
                var committedVersion = _fileStore.Persist(
                    catalog.Tables,
                    catalog.Views,
                    catalog.Triggers,
                    pragmaHeader,
                    forceFullRewrite,
                    previousTables: _tables);
                PublishCatalog(catalog, committedVersion);
            }
            catch (EmbeddedPostCommitMaintenanceException)
            {
                PublishCatalog(catalog, _fileStore.CommittedCatalogVersion);
                throw;
            }
        }
    }

    private void EnsureFileCatalogVersionCurrent(TimeSpan busyTimeout)
    {
        // SQLITE_BUSY_SNAPSHOT semantics: the busy timeout also covers waiting
        // for the writer whose commit is still landing. Once the catalog is
        // settled the caller learns the snapshot is stale and decides whether
        // to reload (BEGIN), retry the statement (autocommit), or surface the
        // busy error (explicit transaction commit). A transaction holder that
        // has not committed yet is irrelevant here: its rows are invisible to
        // the reload, and its eventual commit is handled by the write lock.
        var deadline = GetBusyWaitDeadline(busyTimeout);
        while (true)
        {
            if (TryReadFileCatalogVersion(out var durableVersion))
            {
                if (durableVersion == _fileCatalogVersion)
                    return;
                break;
            }

            // The durable header is mid-write (a persist is flipping WAL frames
            // to the header); give it the busy budget to settle.
            if (busyTimeout == TimeSpan.Zero)
                break;

            var settle = GetRemainingBusyWait(deadline);
            if (settle <= 0)
                break;

            Thread.Sleep(settle == long.MaxValue ? 50 : (int)Math.Min(settle, 50));
        }

        if (busyTimeout != TimeSpan.Zero)
            WaitForCatalogStability(deadline);

        throw new EmbeddedCatalogSnapshotStaleException();
    }

    private bool TryReadFileCatalogVersion(out FileCatalogVersion version)
    {
        try
        {
            version = ReadFileCatalogVersion(_fileSystem!, _databasePath);
            return true;
        }
        catch (InvalidDataException)
        {
            // A writer is between WAL frames and the header update; the durable
            // version is momentarily unreadable, which the caller treats as
            // "still changing" until the busy deadline expires.
            version = default;
            return false;
        }
    }

    private static void ThrowCatalogSnapshotBusy()
        => throw new EmbeddedCatalogSnapshotStaleException();

    private bool TryReloadFileCatalogIfChanged()
    {
        var durableVersion = ReadFileCatalogVersion(_fileSystem!, _databasePath);
        if (durableVersion == _fileCatalogVersion)
            return true;

        // Same adoption a pooled connection performs when it is handed out:
        // reopen the committed store and publish its catalog and version.
        var replacement = EmbeddedFileStore.Open(
            _databasePath,
            _fileSystem!,
            out var catalog,
            readOnly: _readOnly);
        try
        {
            var loadedVersion = ReadFileCatalogVersion(_fileSystem!, _databasePath);
            if (loadedVersion != durableVersion)
            {
                // Another writer committed mid-reload; leave the current
                // snapshot untouched and let the caller retry against it.
                return false;
            }

            var previous = _fileStore!;
            _fileStore = replacement;
            replacement = null;
            PublishCatalog(new SchemaCatalog(catalog.Tables, catalog.Views, catalog.Triggers), loadedVersion);
            previous.Dispose();
            return true;
        }
        finally
        {
            replacement?.Dispose();
        }
    }

    private void WaitForCatalogStability(long deadline)
    {
        var registry = GetFileCatalogWriterRegistry(_fileSystem!);
        var registryKey = GetFileCatalogLockPath(_fileSystem!, _databasePath);

        // Wait out any persist a managed writer is mid-flight on so the
        // caller's reload observes a settled catalog. Deliberately not the
        // transaction lock: under continuous write contention a free instant
        // may never come, and an uncommitted transaction is invisible anyway.
        lock (registry.WritersGate)
        {
            while (registry.IsWriting(registryKey))
            {
                var remaining = GetRemainingBusyWait(deadline);
                if (remaining <= 0)
                    ThrowCatalogSnapshotBusy();

                if (deadline == long.MaxValue)
                    Monitor.Wait(registry.WritersGate);
                else
                    Monitor.Wait(registry.WritersGate, (int)Math.Min(remaining, int.MaxValue));
            }
        }
    }

    private static long GetBusyWaitDeadline(TimeSpan busyTimeout)
    {
        if (busyTimeout == Timeout.InfiniteTimeSpan)
            return long.MaxValue;

        var milliseconds = Math.Max(0, (long)Math.Ceiling(busyTimeout.TotalMilliseconds));
        return Environment.TickCount64 + milliseconds;
    }

    private static long GetRemainingBusyWait(long deadline)
        => deadline == long.MaxValue ? long.MaxValue : deadline - Environment.TickCount64;

    private static TimeSpan GetRemainingBusyTimeout(long deadline)
    {
        if (deadline == long.MaxValue)
            return Timeout.InfiniteTimeSpan;

        var remaining = Math.Max(0, deadline - Environment.TickCount64);
        return TimeSpan.FromMilliseconds(remaining);
    }

    /// <summary>
    /// A foreign read-only connection holds no ownership and no catalog write
    /// lease, so the owner may commit between its statements. When the durable
    /// view token changed, reload the heap-materialized catalog from the current
    /// committed view — the same adoption a freshly opened SQLite read-only
    /// connection would observe. Caller must hold <see cref="_fileCatalogWriteLock"/>.
    /// </summary>
    private void RefreshForeignCatalogIfChangedLocked()
    {
        if (_fileStore is null || _fileSystem is null)
            return;

        var token = _fileStore.CaptureCommittedViewToken();
        if (token == _foreignViewToken)
            return;

        var replacement = EmbeddedFileStore.Open(
            _databasePath,
            _fileSystem,
            out var catalog,
            readOnly: true,
            foreignReadOnly: true);
        try
        {
            var previous = _fileStore;
            _fileStore = replacement;
            replacement = null;
            _fileCatalogVersion = ReadFileCatalogVersion(_fileSystem, _databasePath, foreignReadOnly: true);
            PublishCatalog(new SchemaCatalog(catalog.Tables, catalog.Views, catalog.Triggers));
            _foreignViewToken = _fileStore.CaptureCommittedViewToken();
            previous.Dispose();
        }
        finally
        {
            replacement?.Dispose();
        }
    }

    /// <summary>
    /// Statement-boundary adoption for foreign read-only connections. Callers
    /// skip this while an explicit transaction is active on their connection:
    /// the transaction's catalog snapshot stays pinned for its lifetime.
    /// </summary>
    internal void RefreshForeignCatalogForStatementIfNeeded()
    {
        if (!_foreignReadOnly || _fileStore is null)
            return;

        lock (_gate)
        {
            if (_fileCatalogWriteLock is null)
                throw new InvalidOperationException("The managed file catalog persistence state is not initialized.");
            lock (_fileCatalogWriteLock)
                RefreshForeignCatalogIfChangedLocked();
        }
    }

    /// <summary>
    /// Statement-boundary adoption for owned file-backed connections in autocommit.
    /// SQLite serves every autocommit statement from the latest committed view, so
    /// another owned connection's commit on the same file must become visible here.
    /// An explicit transaction is exempt: its catalog snapshot stays pinned for its
    /// lifetime (adopted once by <see cref="CreateTransactionSnapshot"/>).
    /// </summary>
    internal void RefreshOwnedCatalogForStatementIfNeeded()
    {
        if (_foreignReadOnly || _fileStore is null)
            return;

        // Cheap race-free gate: the shared storage generation only moves when some
        // connection commits or checkpoints on this file, and PublishCatalog pins
        // our own commits, so an unchanged generation means nothing external
        // happened. Read-only statement phases and our own writes skip entirely.
        if (_fileStore.CommittedViewGeneration == _ownedCommittedGeneration)
            return;

        // Another connection committed (or checkpointed) on this file. Adopt it via
        // the proven stale-reload path: a fresh foreign pager (process-local locks,
        // no file-lock contention) that re-checks the durable version and reloads
        // only when it truly moved, so transient checkpoints cost one no-op check.
        ReloadFileCatalogAfterStale();
        _ownedCommittedGeneration = _fileStore.CommittedViewGeneration;
    }

    /// <summary>
    /// Convoy-rotation refresh for a mutating autocommit write. When another
    /// connection is contending for this file's write reservation, this connection
    /// re-reads the committed view from durable storage before deciding, even if
    /// its own generation looks current. Native SQLite serializes every write
    /// through the OS write lock against the live btree, so a just-committed
    /// connection pays the same read cost as any other and the lock rotates
    /// fairly. The managed engine heap-materializes the catalog, so a connection
    /// that just committed sees its own locally-published rows and re-acquires
    /// instantly while a peer is still re-materializing the store — the winner
    /// free-runs the convoy (ENGINE #17 migrations lock). Paying the same reload
    /// under contention removes that head start without holding the lock across
    /// the statement (which would deadlock the winner's own release).
    /// </summary>
    // NOTE: a "reload under contention" throttle was prototyped here for ENGINE
    // #17 and reverted. It does not rotate the convoy: the lock winner releases
    // and re-acquires in a tight loop (no backoff after a win), so by the time a
    // loser wakes from EF backoff the winner has already re-inserted. The loser
    // never catches the empty window because its reload is slower than the
    // winner's re-acquire. Slowing the winner or ordering the write lock cannot
    // fix that; it needs fast (incremental) reload or a genuinely blocking
    // winner — a design decision deferred to the owner.

    internal void RefreshFileCatalogForPooling()
    {
        lock (_gate)
        {
            if (_fileStore is null)
                return;
            if (_fileSystem is null || _fileCatalogWriteLock is null)
                throw new InvalidOperationException("The managed file catalog persistence state is not initialized.");

            lock (_fileCatalogWriteLock)
            {
                using var catalogWriteLease = EnterPhysicalFileCatalogWriteLock(_fileSystem, _databasePath);
                var durableVersion = ReadFileCatalogVersion(_fileSystem, _databasePath);
                if (durableVersion == _fileCatalogVersion)
                    return;

                var replacement = EmbeddedFileStore.Open(
                    _databasePath,
                    _fileSystem,
                    out var catalog,
                    readOnly: _readOnly);
                try
                {
                    var loadedVersion = ReadFileCatalogVersion(_fileSystem, _databasePath);
                    if (loadedVersion != durableVersion)
                    {
                        throw new EmbeddedSqlException(
                            "database is busy: the managed file catalog changed while refreshing a pooled connection.");
                    }

                    var previous = _fileStore;
                    _fileStore = replacement;
                    replacement = null;
                    PublishCatalog(
                        new SchemaCatalog(catalog.Tables, catalog.Views, catalog.Triggers),
                        loadedVersion);
                    previous.Dispose();
                }
                finally
                {
                    replacement?.Dispose();
                }
            }
        }
    }

    private void PublishCatalog(SchemaCatalog catalog, FileCatalogVersion? fileCatalogVersion = null)
    {
        _tables = catalog.Tables;
        _views = catalog.Views;
        _triggers = catalog.Triggers;
        if (fileCatalogVersion is { } version)
            _fileCatalogVersion = version;
        _version++;

        // Pin the storage generation to this commit/reload so the statement-level
        // owned-refresh gate skips it: an unchanged generation there means no
        // *external* connection has committed since we last saw the file.
        if (_fileStore is not null)
            _ownedCommittedGeneration = _fileStore.CommittedViewGeneration;
    }

    private static FileCatalogVersion ReadFileCatalogVersion(
        IFileSystem fileSystem,
        string path,
        bool foreignReadOnly = false)
    {
        try
        {
            return ReadFileCatalogVersionCore(fileSystem, path, foreignReadOnly);
        }
        catch (InvalidOperationException exception) when (
            !foreignReadOnly
            && fileSystem is not AhtolaEncryptionFileSystem
            && exception.InnerException is FileNotFoundException)
        {
            // Stock SQLite removes the -shm lock carrier on the last clean close,
            // and the owned read-only probe refuses to recreate it by contract.
            // The probe only needs a self-contained durable snapshot, which the
            // process-local foreign pager reads without ever touching the carrier.
            // Encrypted pagers cannot open foreign, so they keep the original error.
            return ReadFileCatalogVersionCore(fileSystem, path, foreignReadOnly: true);
        }
    }

    private static FileCatalogVersion ReadFileCatalogVersionCore(
        IFileSystem fileSystem,
        string path,
        bool foreignReadOnly)
    {
        using var pager = SqlitePager.Open(
            fileSystem,
            path,
            path + "-wal",
            readOnly: true,
            foreignReadOnly: foreignReadOnly);
        var header = SqliteDatabaseHeader.Parse(pager.ReadCommittedPage(1));
        if (header.VersionValidFor != header.ChangeCounter
            || header.DatabaseSizeInPages != pager.CommittedPageCount)
        {
            throw new InvalidDataException(
                "The managed file catalog does not have an authoritative committed SQLite header.");
        }

        return new FileCatalogVersion(
            header.ChangeCounter,
            header.SchemaCookie,
            header.DatabaseSizeInPages,
            header.FreelistPageCount,
            header.UserVersion,
            header.ApplicationId,
            header.PageSize,
            header.TextEncoding);
    }

    private static object GetFileCatalogWriteLock(IFileSystem fileSystem, string path)
    {
        var unwrappedFileSystem = AhtolaEncryptionFileSystem.Unwrap(fileSystem);
        return FileCatalogWriteLocks
            .GetValue(unwrappedFileSystem, static _ => new FileCatalogWriteLockScope())
            .Get(GetFileCatalogLockPath(fileSystem, path));
    }

    private static FileCatalogWriterRegistry GetFileCatalogWriterRegistry(IFileSystem fileSystem)
    {
        var unwrappedFileSystem = AhtolaEncryptionFileSystem.Unwrap(fileSystem);
        return FileCatalogWriterRegistries
            .GetValue(unwrappedFileSystem, static _ => new FileCatalogWriterRegistry());
    }

    /// <summary>
    /// Marks this database as actively writing <paramref name="path"/>'s catalog
    /// for the lifetime of the returned lease. Waiters blocked on a stale
    /// snapshot use the registration to pace their retry.
    /// </summary>
    private IDisposable RegisterCatalogWrite(string path)
    {
        var registry = GetFileCatalogWriterRegistry(_fileSystem!);
        var registryKey = GetFileCatalogLockPath(_fileSystem!, path);
        registry.Enter(registryKey);
        return new FileCatalogWriteRegistration(registry, registryKey);
    }

    private sealed class FileCatalogWriteRegistration(
        FileCatalogWriterRegistry registry,
        string path) : IDisposable
    {
        private FileCatalogWriterRegistry? _registry = registry;

        public void Dispose()
        {
            var registry = Interlocked.Exchange(ref _registry, null);
            registry?.Exit(path);
        }
    }

    private static string GetFileCatalogLockPath(IFileSystem fileSystem, string path)
    {
        var unwrappedFileSystem = AhtolaEncryptionFileSystem.Unwrap(fileSystem);
        var lockPath = unwrappedFileSystem is PhysicalFileSystem
            ? Path.GetFullPath(path)
            : path;
        return OperatingSystem.IsWindows() ? lockPath.ToUpperInvariant() : lockPath;
    }

    private static IDisposable? EnterPhysicalFileCatalogWriteLock(IFileSystem fileSystem, string path)
    {
        if (AhtolaEncryptionFileSystem.Unwrap(fileSystem) is not PhysicalFileSystem)
            return null;

        var lockPath = Path.GetFullPath(path);
        if (OperatingSystem.IsWindows())
            lockPath = lockPath.ToUpperInvariant();
        var name = "Ahtola.ManagedCatalog."
            + Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(lockPath)));
        var mutex = new Mutex(initiallyOwned: false, name);
        try
        {
            try
            {
                mutex.WaitOne();
            }
            catch (AbandonedMutexException)
            {
                // The prior owner terminated before publishing or releasing. The
                // durable catalog version check below decides whether this handle
                // can safely write.
            }

            return new FileCatalogMutexLease(mutex);
        }
        catch
        {
            mutex.Dispose();
            throw;
        }
    }

    private sealed class FileCatalogWriteLockScope
    {
        private readonly Dictionary<string, object> _locks = new(StringComparer.OrdinalIgnoreCase);

        public object Get(string path)
        {
            lock (_locks)
            {
                if (!_locks.TryGetValue(path, out var fileCatalogWriteLock))
                {
                    fileCatalogWriteLock = new object();
                    _locks.Add(path, fileCatalogWriteLock);
                }

                return fileCatalogWriteLock;
            }
        }
    }

    /// <summary>
    /// Tracks which connections are currently persisting one file's catalog so a
    /// connection whose snapshot just went stale can wait out the conflicting
    /// writer, then re-read the durable version and retry. Persisting writers
    /// do not always hold the transaction lock (autocommit writes only hold it
    /// transiently), so the lock alone cannot signal catalog stability.
    /// </summary>
    private sealed class FileCatalogWriterRegistry
    {
        private readonly Dictionary<string, int> _writers = new(StringComparer.OrdinalIgnoreCase);

        internal object WritersGate => _writers;

        public void Enter(string path)
        {
            lock (_writers)
                _writers[path] = _writers.TryGetValue(path, out var count) ? count + 1 : 1;
        }

        public void Exit(string path)
        {
            lock (_writers)
            {
                if (!_writers.TryGetValue(path, out var count))
                    throw new InvalidOperationException("The managed file catalog writer count went negative.");

                if (count == 1)
                    _writers.Remove(path);
                else
                    _writers[path] = count - 1;

                Monitor.PulseAll(_writers);
            }
        }

        public bool IsWriting(string path)
        {
            // Caller must hold WritersGate.
            return _writers.ContainsKey(path);
        }
    }

    private sealed class FileCatalogMutexLease(Mutex mutex) : IDisposable
    {
        private Mutex? _mutex = mutex;

        public void Dispose()
        {
            var mutex = Interlocked.Exchange(ref _mutex, null);
            if (mutex is null)
                return;

            try
            {
                mutex.ReleaseMutex();
            }
            finally
            {
                mutex.Dispose();
            }
        }
    }

    internal ExecutionResult Execute(
        ParsedStatement statement,
        SqlValue[] parameters,
        SchemaCatalog catalog,
        long lastInsertRowId = 0,
        bool foreignKeysEnabled = false,
        bool recursiveTriggersEnabled = false,
        bool deferForeignKeys = false,
        bool inTransaction = false,
        CancellationToken cancellationToken = default,
        bool compilationEnabled = true,
        TempTriggerBridge? tempTriggers = null,
        ManagedStatementHooks? hooks = null)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        if (RequiresRecursiveTriggerStack(
                statement,
                recursiveTriggersEnabled,
                catalog.Triggers.Count != 0))
        {
            return ExecuteWithRecursiveTriggerStack(() => Execute(
                statement,
                parameters,
                catalog,
                lastInsertRowId,
                foreignKeysEnabled,
                recursiveTriggersEnabled,
                deferForeignKeys,
                inTransaction,
                cancellationToken,
                compilationEnabled,
                tempTriggers,
                hooks));
        }

        cancellationToken.ThrowIfCancellationRequested();
        if (_readOnly && MayMutate(statement))
            throw new EmbeddedSqlException("attempt to write a readonly database");

        var tables = catalog.Tables;
        var context = new QueryContext(
            tables,
            new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
            catalog.Views,
            catalog.Triggers,
            LastInsertRowId: lastInsertRowId,
            ForeignKeysEnabled: foreignKeysEnabled,
            DeferForeignKeys: deferForeignKeys,
            InTransaction: inTransaction,
            RecursiveTriggersEnabled: recursiveTriggersEnabled,
            ForeignKeyStatement: foreignKeysEnabled ? new ForeignKeyStatementState() : null,
            CancellationToken: cancellationToken,
            StatementState: new StatementExecutionState(lastInsertRowId),
            CompilationEnabled: compilationEnabled,
            TempTriggers: tempTriggers,
            Hooks: hooks);
        return statement switch
        {
            CreateTableStatement create => ExecuteCreateTable(create, catalog, cancellationToken),
            CreateTableAsSelectStatement => throw new InvalidOperationException(
                "CREATE TABLE AS SELECT must be materialized by the owning connection."),
            DropTableStatement drop => ExecuteDmlWithAutoIncrementState(
                context,
                scoped => scoped.ForeignKeysEnabled
                    ? ExecuteWithForeignKeyStatement(
                        scoped,
                        () => ExecuteDropTable(drop, catalog, scoped))
                    : ExecuteDropTable(drop, catalog, scoped)),
            CreateIndexStatement createIndex => ExecuteCreateIndex(createIndex, catalog),
            DropIndexStatement dropIndex => ExecuteDropIndex(dropIndex, tables),
            CreateViewStatement createView => ExecuteCreateView(createView, catalog),
            DropViewStatement dropView => ExecuteDropView(dropView, catalog),
            CreateTriggerStatement createTrigger => ExecuteCreateTrigger(createTrigger, catalog, context),
            DropTriggerStatement dropTrigger => ExecuteDropTrigger(dropTrigger, catalog),
            AlterTableAddColumnStatement addColumn => ExecuteAlterTableAddColumn(addColumn, parameters, context),
            AlterTableRenameStatement rename => ExecuteAlterTableRename(rename, catalog, context),
            AlterTableRenameColumnStatement renameColumn => ExecuteAlterTableRenameColumn(
                renameColumn,
                catalog,
                context),
            AlterTableDropColumnStatement dropColumn => ExecuteAlterTableDropColumn(dropColumn, catalog, context),
            InsertStatement insert => ExecuteDmlWithAutoIncrementState(
                context,
                scoped => ExecuteInsert(insert, parameters, scoped)),
            UpdateStatement update => ExecuteDmlWithAutoIncrementState(
                context,
                scoped => ExecuteUpdate(update, parameters, scoped)),
            DeleteStatement delete => ExecuteDmlWithAutoIncrementState(
                context,
                scoped => ExecuteDelete(delete, parameters, scoped)),
            WithDmlStatement with => ExecuteDmlWithAutoIncrementState(
                context,
                scoped => ExecuteWithDml(with, parameters, scoped)),
            ValuesClause values => ExecuteValuesStatement(values, parameters, context, null),
            QueryStatement query => ExecuteQuery(query, parameters, context, null),
            PragmaTableInfoStatement tableInfo => ExecutePragmaTableInfo(tableInfo, context),
            PragmaTableXInfoStatement tableXInfo => ExecutePragmaTableXInfo(tableXInfo, context),
            PragmaIndexListStatement indexList => ExecutePragmaIndexList(indexList, tables),
            PragmaIndexInfoStatement indexInfo => ExecutePragmaIndexInfo(indexInfo, tables),
            PragmaIndexXInfoStatement indexXInfo => ExecutePragmaIndexXInfo(indexXInfo, tables),
            PragmaForeignKeyListStatement foreignKeyList => ExecutePragmaForeignKeyList(foreignKeyList, tables),
            PragmaForeignKeyCheckStatement foreignKeyCheck => ExecutePragmaForeignKeyCheck(foreignKeyCheck, tables),
            PragmaIntegrityCheckStatement integrityCheck => ExecutePragmaIntegrityCheck(
                integrityCheck,
                tables,
                parameters,
                context),
            PragmaTableListStatement tableList => ExecutePragmaTableList(
                catalog,
                tableList.Schema ?? "main"),
            PragmaDatabaseListStatement => ExecutePragmaDatabaseList(),
            PragmaEncodingStatement => ExecutePragmaEncoding(),
            PragmaPageCountStatement => ExecutePragmaPageCount(),
            PragmaFreelistCountStatement => ExecutePragmaFreelistCount(),
            AnalyzeStatement => throw AnalyzeNotSupported(),
            ReindexStatement reindex => ExecuteReindex(reindex, catalog),
            ExplainStatement explain => ExecuteExplain(explain, parameters, context),
            ExplainQueryPlanStatement explainQueryPlan => ExecuteExplainQueryPlan(explainQueryPlan, parameters, context),
            BeginStatement => ExecutionResult.Empty,
            CommitStatement => ExecutionResult.Empty,
            RollbackStatement => ExecutionResult.Empty,
            SavepointStatement => ExecutionResult.Empty,
            ReleaseSavepointStatement => ExecutionResult.Empty,
            RollbackToSavepointStatement => ExecutionResult.Empty,
            _ => throw new EmbeddedSqlException($"Unsupported statement type {statement.GetType().Name}."),
        };
    }

    private static ExecutionResult ExecutePragmaTableInfo(
        PragmaTableInfoStatement statement,
        QueryContext context)
    {
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
        {
            if (TryGetView(context, statement.TableName, out var infoView))
            {
                return new ExecutionResult(
                    ["cid", "name", "type", "notnull", "dflt_value", "pk"],
                    BuildPragmaViewColumnRows(infoView, context, includeHidden: false),
                    0);
            }
            return TryDescribeTableValuedFunction(statement.TableName, includeHidden: false, out var moduleRows)
                ? new ExecutionResult(["cid", "name", "type", "notnull", "dflt_value", "pk"], moduleRows, 0)
                : new ExecutionResult(["cid", "name", "type", "notnull", "dflt_value", "pk"], [], 0);
        }

        // PRAGMA table_info excludes generated columns (they appear only in table_xinfo),
        // reports the 1-based position of each primary-key column, and treats a WITHOUT
        // ROWID primary-key column as implicitly NOT NULL, matching SQLite.
        return new ExecutionResult(
            ["cid", "name", "type", "notnull", "dflt_value", "pk"],
            BuildPragmaColumnRows(table, includeGeneratedColumns: false),
            0);
    }

    private static ExecutionResult ExecutePragmaTableXInfo(
        PragmaTableXInfoStatement statement,
        QueryContext context)
    {
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
        {
            if (TryGetView(context, statement.TableName, out var xinfoView))
            {
                return new ExecutionResult(
                    ["cid", "name", "type", "notnull", "dflt_value", "pk", "hidden"],
                    BuildPragmaViewColumnRows(xinfoView, context, includeHidden: true),
                    0);
            }
            return TryDescribeTableValuedFunction(statement.TableName, includeHidden: true, out var moduleRows)
                ? new ExecutionResult(
                    ["cid", "name", "type", "notnull", "dflt_value", "pk", "hidden"],
                    moduleRows,
                    0)
                : new ExecutionResult(["cid", "name", "type", "notnull", "dflt_value", "pk", "hidden"], [], 0);
        }

        return new ExecutionResult(
            ["cid", "name", "type", "notnull", "dflt_value", "pk", "hidden"],
            BuildPragmaColumnRows(table, includeGeneratedColumns: true),
            0);
    }

    // SQLite's table-valued PRAGMA functions resolve a view's columns from the view's
    // SELECT: names come from the projection (or the CREATE VIEW column list) and the
    // type is derived per SQLite's expression HASTYPE rules (source column declared
    // type verbatim, CAST affinity names, no type for computed expressions). A view
    // reports notnull/dflt_value/pk (and hidden) as zero for every column.
    private static SqlValue[][] BuildPragmaViewColumnRows(
        ViewDefinition view,
        QueryContext context,
        bool includeHidden)
    {
        var columns = DescribeViewAffinities(
            view,
            EnterView(context, view.Name),
            new Dictionary<string, IReadOnlyList<QueryAffinityColumn>>(StringComparer.OrdinalIgnoreCase));
        var rows = new SqlValue[columns.Count][];
        for (var index = 0; index < rows.Length; index++)
        {
            var row = new List<SqlValue>
            {
                SqlValue.Integer(index),
                SqlValue.Text(columns[index].Name),
                SqlValue.Text(columns[index].DeclaredType ?? string.Empty),
                SqlValue.Integer(0),
                SqlValue.Null,
                SqlValue.Integer(0),
            };
            if (includeHidden)
            {
                row.Add(SqlValue.Integer(0));
            }
            rows[index] = row.ToArray();
        }
        return rows;
    }

    private static SqlValue[][] BuildPragmaColumnRows(EmbeddedTable table, bool includeGeneratedColumns)
    {
        var rows = new List<SqlValue[]>();
        for (var index = 0; index < table.ColumnDefinitions.Length; index++)
        {
            var column = table.ColumnDefinitions[index];
            if (column.IsGenerated && !includeGeneratedColumns)
                continue;

            var primaryKeyPosition = table.PrimaryKeyPosition(index);
            var notNull = column.NotNull || (table.WithoutRowid && primaryKeyPosition > 0);

            // table_info renumbers cid over the columns it reports, so hiding a generated
            // column closes the gap it would otherwise leave; table_xinfo reports every
            // column and therefore keeps the declaration position.
            var row = new List<SqlValue>
            {
                SqlValue.Integer(includeGeneratedColumns ? index : rows.Count),
                SqlValue.Text(column.Name),
                SqlValue.Text(column.DeclaredType ?? string.Empty),
                SqlValue.Integer(notNull ? 1 : 0),
                GetPragmaDefaultValue(column),
                SqlValue.Integer(primaryKeyPosition),
            };
            if (includeGeneratedColumns)
            {
                row.Add(SqlValue.Integer(column.IsGenerated ? (column.GeneratedStored ? 3 : 2) : 0));
            }

            rows.Add(row.ToArray());
        }

        return rows.ToArray();
    }

    private static SqlValue GetPragmaDefaultValue(EmbeddedColumn column)
    {
        if (column.DefaultSql is { } sql)
        {
            if (sql.Length >= 2 && sql[0] == '(' && sql[^1] == ')')
                sql = sql[1..^1].Trim();
            return SqlValue.Text(sql);
        }
        if (column.DefaultValue is { } defaultValue)
            return SqlValue.Text(FormatSqlLiteral(defaultValue));

        return SqlValue.Null;
    }

    private static ExecutionResult ExecutePragmaTableList(SchemaCatalog catalog, string schema)
    {
        var rows = new List<SqlValue[]>
        {
            new[]
            {
                SqlValue.Text(schema),
                SqlValue.Text(
                    schema.Equals("temp", StringComparison.OrdinalIgnoreCase)
                        ? "sqlite_temp_schema"
                        : "sqlite_schema"),
                SqlValue.Text("table"),
                SqlValue.Integer(5),
                SqlValue.Integer(0),
                SqlValue.Integer(0),
            },
        };

        foreach (var (name, table) in catalog.Tables.OrderBy(pair => pair.Key, StringComparer.OrdinalIgnoreCase))
        {
            rows.Add(
            [
                SqlValue.Text(schema),
                SqlValue.Text(name),
                SqlValue.Text("table"),
                SqlValue.Integer(table.ColumnDefinitions.Length),
                SqlValue.Integer(table.WithoutRowid ? 1 : 0),
                SqlValue.Integer(table.Strict ? 1 : 0),
            ]);
        }

        foreach (var (name, view) in catalog.Views.OrderBy(pair => pair.Key, StringComparer.OrdinalIgnoreCase))
        {
            var columns = view.Columns
                ?? DescribeQuery(
                    view.Query,
                    new QueryContext(
                        catalog.Tables,
                        new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
                        catalog.Views,
                        catalog.Triggers));
            rows.Add(
            [
                SqlValue.Text(schema),
                SqlValue.Text(name),
                SqlValue.Text("view"),
                SqlValue.Integer(columns.Count),
                SqlValue.Integer(0),
                SqlValue.Integer(0),
            ]);
        }

        return new ExecutionResult(["schema", "name", "type", "ncol", "wr", "strict"], rows.ToArray(), 0);
    }

    private ExecutionResult ExecutePragmaDatabaseList()
        => new(
            ["seq", "name", "file"],
            [[SqlValue.Integer(0), SqlValue.Text("main"), SqlValue.Text(_databasePath)]],
            0);

    private ExecutionResult ExecutePragmaEncoding()
        => new(["encoding"], [[SqlValue.Text(FormatPragmaEncoding(GetTextEncoding()))]], 0);

    internal static string FormatPragmaEncoding(SqliteTextEncoding encoding)
        => encoding switch
        {
            SqliteTextEncoding.Utf8 or SqliteTextEncoding.Unset => "UTF-8",
            SqliteTextEncoding.Utf16LittleEndian => "UTF-16le",
            SqliteTextEncoding.Utf16BigEndian => "UTF-16be",
            _ => throw new InvalidOperationException($"Unknown SQLite text encoding {encoding}."),
        };

    private ExecutionResult ExecutePragmaPageCount()
        => new(["page_count"], [[SqlValue.Integer(GetPageCount())]], 0);

    private ExecutionResult ExecutePragmaFreelistCount()
        => new(["freelist_count"], [[SqlValue.Integer(GetFreelistCount())]], 0);

    private static ExecutionResult ExecutePragmaIndexList(
        PragmaIndexListStatement statement,
        Dictionary<string, EmbeddedTable> tables)
    {
        string[] columns = ["seq", "name", "unique", "origin", "partial"];
        if (!tables.TryGetValue(statement.TableName, out var table))
            return new ExecutionResult(columns, [], 0);

        var indexes = table.Indexes
            .Where(index => index.Origin == EmbeddedIndexOrigin.Explicit)
            .Reverse()
            .Select(index => (
                index.Name,
                index.Unique,
                index.Origin,
                index.IsPartial))
            .Concat(
                table.Indexes
                    .Where(index => index.Origin != EmbeddedIndexOrigin.Explicit)
                    .Select(index => (
                        index.Name,
                        index.Unique,
                        index.Origin,
                        index.IsPartial))
                    .Concat(table.WithoutRowidPrimaryKeyIndexName is { } primaryKeyIndexName
                        ?
                        [
                            (
                                primaryKeyIndexName,
                                Unique: true,
                                Origin: EmbeddedIndexOrigin.PrimaryKey,
                                IsPartial: false),
                        ]
                        : [])
                    .OrderByDescending(index => GetAutoIndexOrdinal(index.Name)))
            .ToArray();
        var rows = new SqlValue[indexes.Length][];
        for (var seq = 0; seq < indexes.Length; seq++)
        {
            var index = indexes[seq];
            rows[seq] =
            [
                SqlValue.Integer(seq),
                SqlValue.Text(index.Name),
                SqlValue.Integer(index.Unique ? 1 : 0),
                SqlValue.Text(index.Origin switch
                {
                    EmbeddedIndexOrigin.Explicit => "c",
                    EmbeddedIndexOrigin.PrimaryKey => "pk",
                    _ => "u",
                }),
                SqlValue.Integer(index.IsPartial ? 1 : 0),
            ];
        }

        return new ExecutionResult(columns, rows, 0);
    }

    private static int GetAutoIndexOrdinal(string indexName)
    {
        var separator = indexName.LastIndexOf('_');
        return separator >= 0
            && int.TryParse(
                indexName.AsSpan(separator + 1),
                NumberStyles.None,
                CultureInfo.InvariantCulture,
                out var ordinal)
                ? ordinal
                : 0;
    }

    private static ExecutionResult ExecutePragmaIndexInfo(
        PragmaIndexInfoStatement statement,
        Dictionary<string, EmbeddedTable> tables)
    {
        string[] columns = ["seqno", "cid", "name"];
        if (TryFindWithoutRowidPrimaryKey(
                tables,
                statement.IndexName,
                out _,
                out var primaryKeyTable))
        {
            var primaryKey = primaryKeyTable.PrimaryKeySchema
                ?? throw new InvalidOperationException("WITHOUT ROWID table has no primary-key metadata.");
            var primaryKeyRows = primaryKey.Terms.Select((term, seqno) => new[]
            {
                SqlValue.Integer(seqno),
                SqlValue.Integer(term.ColumnIndex),
                SqlValue.Text(term.ColumnName),
            }).ToArray();
            return new ExecutionResult(columns, primaryKeyRows, 0);
        }
        if (!TryFindIndex(tables, statement.IndexName, out _, out var index))
            return new ExecutionResult(columns, [], 0);

        var rows = new SqlValue[index.Columns.Count][];
        for (var seqno = 0; seqno < index.Columns.Count; seqno++)
        {
            var column = index.Columns[seqno];
            rows[seqno] =
            [
                SqlValue.Integer(seqno),
                SqlValue.Integer(column.ColumnIndex),
                column.IsExpression ? SqlValue.Null : SqlValue.Text(column.Name),
            ];
        }

        return new ExecutionResult(columns, rows, 0);
    }

    private static ExecutionResult ExecutePragmaIndexXInfo(
        PragmaIndexXInfoStatement statement,
        Dictionary<string, EmbeddedTable> tables)
    {
        string[] columns = ["seqno", "cid", "name", "desc", "coll", "key"];
        if (TryFindWithoutRowidPrimaryKey(
                tables,
                statement.IndexName,
                out _,
                out var primaryKeyTable))
        {
            return new ExecutionResult(
                columns,
                BuildWithoutRowidPrimaryKeyXInfo(primaryKeyTable),
                0);
        }
        if (!TryFindIndex(tables, statement.IndexName, out var table, out var index))
            return new ExecutionResult(columns, [], 0);

        var rows = new List<SqlValue[]>(index.Columns.Count + table.PrimaryKeyColumns.Count + 1);
        for (var seqno = 0; seqno < index.Columns.Count; seqno++)
        {
            var term = index.Columns[seqno];
            rows.Add(
            [
                SqlValue.Integer(seqno),
                SqlValue.Integer(term.ColumnIndex),
                term.IsExpression ? SqlValue.Null : SqlValue.Text(term.Name),
                SqlValue.Integer(term.Descending ? 1 : 0),
                SqlValue.Text(IndexExpressionSemantics.GetCollationName(table, term)),
                SqlValue.Integer(1),
            ]);
        }

        if (table.WithoutRowid)
        {
            var primaryKey = table.PrimaryKeySchema
                ?? throw new InvalidOperationException("WITHOUT ROWID table has no primary-key metadata.");
            foreach (var suffix in primaryKey.Terms)
            {
                var alreadyPresent = index.Columns.Any(term =>
                    !term.IsExpression
                    && term.ColumnIndex == suffix.ColumnIndex
                    && string.Equals(
                        IndexExpressionSemantics.GetCollationName(table, term),
                        suffix.Collation.Name ?? "BINARY",
                        StringComparison.OrdinalIgnoreCase));
                if (alreadyPresent)
                    continue;

                rows.Add(
                [
                    SqlValue.Integer(rows.Count),
                    SqlValue.Integer(suffix.ColumnIndex),
                    SqlValue.Text(suffix.ColumnName),
                    SqlValue.Integer(
                        index.Origin == EmbeddedIndexOrigin.Explicit
                        && suffix.SortOrder == SqliteKeySortOrder.Descending
                            ? 1
                            : 0),
                    SqlValue.Text(suffix.Collation.Name ?? "BINARY"),
                    SqlValue.Integer(0),
                ]);
            }
        }
        else
        {
            rows.Add(
            [
                SqlValue.Integer(rows.Count),
                SqlValue.Integer(-1),
                SqlValue.Null,
                SqlValue.Integer(0),
                SqlValue.Text("BINARY"),
                SqlValue.Integer(0),
            ]);
        }

        return new ExecutionResult(columns, rows, 0);
    }

    private static SqlValue[][] BuildWithoutRowidPrimaryKeyXInfo(EmbeddedTable table)
    {
        var primaryKey = table.PrimaryKeySchema
            ?? throw new InvalidOperationException("WITHOUT ROWID table has no primary-key metadata.");
        var rows = new List<SqlValue[]>(table.ColumnDefinitions.Length);
        var primaryKeyColumns = new HashSet<int>();
        foreach (var term in primaryKey.Terms)
        {
            primaryKeyColumns.Add(term.ColumnIndex);
            rows.Add(
            [
                SqlValue.Integer(rows.Count),
                SqlValue.Integer(term.ColumnIndex),
                SqlValue.Text(term.ColumnName),
                SqlValue.Integer(term.SortOrder == SqliteKeySortOrder.Descending ? 1 : 0),
                SqlValue.Text(term.Collation.Name ?? "BINARY"),
                SqlValue.Integer(1),
            ]);
        }

        for (var columnIndex = 0; columnIndex < table.ColumnDefinitions.Length; columnIndex++)
        {
            if (primaryKeyColumns.Contains(columnIndex))
                continue;
            var column = table.ColumnDefinitions[columnIndex];
            if (column.IsGenerated && !column.GeneratedStored)
                continue;
            rows.Add(
            [
                SqlValue.Integer(rows.Count),
                SqlValue.Integer(columnIndex),
                SqlValue.Text(column.Name),
                SqlValue.Integer(0),
                SqlValue.Text(column.Collation ?? "BINARY"),
                SqlValue.Integer(0),
            ]);
        }

        return rows.ToArray();
    }

    private static ExecutionResult ExecutePragmaForeignKeyList(
        PragmaForeignKeyListStatement statement,
        IReadOnlyDictionary<string, EmbeddedTable> tables)
    {
        var columns = new[] { "id", "seq", "table", "from", "to", "on_update", "on_delete", "match" };
        if (!tables.TryGetValue(statement.TableName, out var table))
            return new ExecutionResult(columns, [], 0);

        var rows = new List<SqlValue[]>();
        var foreignKeys = table.ForeignKeys.Reverse().ToArray();
        for (var id = 0; id < foreignKeys.Length; id++)
        {
            var foreignKey = foreignKeys[id];
            for (var sequence = 0; sequence < foreignKey.ChildColumns.Count; sequence++)
            {
                rows.Add(
                [
                    SqlValue.Integer(id),
                    SqlValue.Integer(sequence),
                    SqlValue.Text(foreignKey.ParentTable),
                    SqlValue.Text(foreignKey.ChildColumns[sequence]),
                    sequence < foreignKey.ParentColumns.Count
                        ? SqlValue.Text(foreignKey.ParentColumns[sequence])
                        : SqlValue.Null,
                    SqlValue.Text(FormatForeignKeyAction(foreignKey.OnUpdate)),
                    SqlValue.Text(FormatForeignKeyAction(foreignKey.OnDelete)),
                    SqlValue.Text("NONE"),
                ]);
            }
        }

        return new ExecutionResult(columns, rows, 0);
    }

    private ExecutionResult ExecutePragmaForeignKeyCheck(
        PragmaForeignKeyCheckStatement statement,
        IReadOnlyDictionary<string, EmbeddedTable> tables)
    {
        var columns = new[] { "table", "rowid", "parent", "fkid" };
        var selectedTables = statement.TableName is null
            ? tables
            : tables.TryGetValue(statement.TableName, out var selected)
                ? new Dictionary<string, EmbeddedTable>(StringComparer.OrdinalIgnoreCase)
                {
                    [statement.TableName] = selected,
                }
                : new Dictionary<string, EmbeddedTable>(StringComparer.OrdinalIgnoreCase);
        var rows = new List<SqlValue[]>();
        foreach (var (childTableName, childTable) in selectedTables.Reverse())
        {
            var foreignKeys = childTable.ForeignKeys.Reverse().ToArray();
            for (var foreignKeyId = 0; foreignKeyId < foreignKeys.Length; foreignKeyId++)
            {
                var foreignKey = foreignKeys[foreignKeyId];
                var childColumns = ResolveForeignKeyChildColumns(childTable, childTableName, foreignKey);
                ForeignKeyParent? parent = null;
                if (tables.ContainsKey(foreignKey.ParentTable))
                    parent = ResolveForeignKeyParent(tables, childTableName, foreignKey);

                for (var rowIndex = 0; rowIndex < childTable.Rows.Count; rowIndex++)
                {
                    var childValues = GetForeignKeyValues(childTable.Rows[rowIndex], childColumns);
                    if (childValues.Any(value => value.Kind == SqlValueKind.Null)
                        || (parent is not null && ParentContains(
                            parent,
                            parent.Table.Rows,
                            childValues,
                            childTable.Rows[rowIndex],
                            ReferenceEquals(childTable, parent.Table))))
                    {
                        continue;
                    }

                    rows.Add(
                    [
                        SqlValue.Text(childTableName),
                        childTable.HasRowid && rowIndex < childTable.RowIds.Count
                            ? SqlValue.Integer(childTable.RowIds[rowIndex])
                            : SqlValue.Null,
                        SqlValue.Text(foreignKey.ParentTable),
                        SqlValue.Integer(foreignKeyId),
                    ]);
                }
            }
        }

        return new ExecutionResult(columns, rows, 0);
    }

    /// <summary>
    /// Reports the SQLite integrity problems the managed catalog can actually
    /// prove: declared NOT NULL and CHECK constraints that stored rows violate.
    /// </summary>
    /// <remarks>
    /// Index and page-structure problems are unreachable here. The managed file
    /// store validates stored index records, page linkage, and record framing
    /// while loading a database, so a database that would make SQLite report
    /// <c>non-unique entry in index</c> or <c>wrong # of entries in index</c>
    /// fails to open at all. That makes <c>quick_check</c> and
    /// <c>integrity_check</c> report the same problems, differing only in their
    /// result column name.
    /// </remarks>
    private ExecutionResult ExecutePragmaIntegrityCheck(
        PragmaIntegrityCheckStatement statement,
        IReadOnlyDictionary<string, EmbeddedTable> tables,
        SqlValue[] parameters,
        QueryContext context)
    {
        var columns = new[] { statement.Quick ? "quick_check" : "integrity_check" };
        if (statement.TableName is { } requested && !tables.ContainsKey(requested))
            throw new EmbeddedSqlException($"no such table: {requested}");

        var maxErrors = statement.MaxErrors ?? DefaultIntegrityCheckErrorLimit;
        if (maxErrors <= 0)
            return new ExecutionResult(columns, [], 0);

        var problems = new List<string>();
        foreach (var (tableName, table) in tables)
        {
            if (statement.TableName is { } selected
                && !selected.Equals(tableName, StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }
            if (problems.Count >= maxErrors)
                break;

            AppendIntegrityRowProblems(tableName, table, parameters, context, maxErrors, problems);
        }

        var rows = problems.Count == 0
            ? (IReadOnlyList<SqlValue[]>)[[SqlValue.Text("ok")]]
            : [.. problems.Take(maxErrors).Select(problem => new[] { SqlValue.Text(problem) })];
        return new ExecutionResult(columns, rows, 0);
    }

    private void AppendIntegrityRowProblems(
        string tableName,
        EmbeddedTable table,
        SqlValue[] parameters,
        QueryContext context,
        int maxErrors,
        List<string> problems)
    {
        for (var rowIndex = 0; rowIndex < table.Rows.Count && problems.Count < maxErrors; rowIndex++)
        {
            var row = table.Rows[rowIndex];
            for (var columnIndex = 0;
                 columnIndex < table.ColumnDefinitions.Length && problems.Count < maxErrors;
                 columnIndex++)
            {
                var column = table.ColumnDefinitions[columnIndex];
                if (column.NotNull && columnIndex < row.Length && row[columnIndex].Kind == SqlValueKind.Null)
                    problems.Add($"NULL value in {tableName}.{column.Name}");
            }

            if (problems.Count >= maxErrors || !table.HasCheckConstraints)
                continue;

            var rowid = table.HasRowid && rowIndex < table.RowIds.Count ? table.RowIds[rowIndex] : 0;
            if (!SatisfiesCheckConstraints(tableName, table, row, rowid, parameters, context))
                problems.Add($"CHECK constraint failed in {tableName}");
        }
    }

    private bool SatisfiesCheckConstraints(
        string tableName,
        EmbeddedTable table,
        SqlValue[] row,
        long rowid,
        SqlValue[] parameters,
        QueryContext context)
    {
        try
        {
            ValidateCheckConstraints(tableName, table, row, rowid, parameters, context);
            return true;
        }
        catch (EmbeddedSqlException)
        {
            // A stored row that cannot be evaluated is itself an integrity problem.
            return false;
        }
    }


    private ExecutionResult ExecuteCreateTable(
        CreateTableStatement statement,
        SchemaCatalog catalog,
        CancellationToken cancellationToken)
    {
        var tables = catalog.Tables;
        if (IsSqliteSequenceTable(statement.Name))
            throw new EmbeddedSqlException($"object name reserved for internal use: {SqliteSequenceTableName}");
        if (tables.ContainsKey(statement.Name))
        {
            if (statement.IfNotExists)
                return ExecutionResult.Empty;

            throw new EmbeddedSqlException($"table {statement.Name} already exists");
        }
        if (catalog.Views.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"there is already a view named {statement.Name}");
        if (catalog.Triggers.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"there is already a trigger named {statement.Name}");
        if (TryFindIndex(tables, statement.Name, out _, out _))
            throw new EmbeddedSqlException($"there is already an index named {statement.Name}");

        // A WITHOUT ROWID table has no hidden rowid to fall back on, so SQLite requires a
        // PRIMARY KEY; reject the table before it is registered when none is declared.
        if (statement.WithoutRowid
            && statement.PrimaryKeyColumns is null
            && !statement.Columns.Any(column => column.PrimaryKey))
        {
            throw new EmbeddedSqlException($"PRIMARY KEY missing on table {statement.Name}");
        }

        foreach (var check in statement.Columns
                     .SelectMany(column => column.CheckConstraints)
                     .Concat(statement.CheckConstraints ?? []))
        {
            ValidateCheckConstraintFunctions(check.Expression);
        }

        var table = new EmbeddedTable(
            statement.Name,
            statement.Columns,
            statement.WithoutRowid,
            statement.PrimaryKeyColumns,
            statement.UniqueConstraints,
            statement.CheckConstraints,
            statement.PrimaryKeyConflictAlgorithm,
            statement.PrimaryKeyConstraintName,
            statement.PrimaryKeyDeclarationOrder,
            statement.TableForeignKeys,
            statement.Strict);
        if (statement.InitialRows is { } initialRows)
        {
            for (var rowIndex = 0; rowIndex < initialRows.Count; rowIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var row = initialRows[rowIndex].ToArray();
                if (row.Length != table.ColumnDefinitions.Length)
                {
                    throw new InvalidOperationException(
                        "A materialized CREATE TABLE AS SELECT row has the wrong column count.");
                }

                table.ApplyAffinities(row);
                table.Rows.Add(row);
                table.RowIds.Add(checked(rowIndex + 1L));
            }
        }
        if (table.IsAutoIncrement)
            EnsureSqliteSequenceTable(catalog);

        tables.Add(statement.Name, table);
        return new ExecutionResult([], [], 0, true);
    }

    // SQLite resolves functions in CHECK constraints when the CREATE TABLE statement is
    // prepared, so unknown names fail immediately with "no such function" instead of
    // surfacing when a row is written. A name resolves when the engine implements it
    // (SqliteBuiltinFunctions) or the connection registered a callback with a matching
    // arity. Aggregate and window names still resolve here; the structural validation in
    // EmbeddedTable rejects them with its own diagnostic.
    private void ValidateCheckConstraintFunctions(Expression expression)
    {
        switch (expression)
        {
            case FunctionExpression function:
                if (!SqliteBuiltinFunctions.Contains(function.Name)
                    && !_scalarFunctions.ContainsKey((function.Name, function.Arguments.Count))
                    && !_scalarFunctions.ContainsKey((function.Name, -1)))
                {
                    throw new EmbeddedSqlException($"no such function: {function.Name}");
                }
                foreach (var argument in function.Arguments)
                    ValidateCheckConstraintFunctions(argument);
                if (function.Filter is not null)
                    ValidateCheckConstraintFunctions(function.Filter);
                return;
            case RowValueExpression rowValue:
                foreach (var value in rowValue.Values)
                    ValidateCheckConstraintFunctions(value);
                return;
            case CollationExpression collation:
                ValidateCheckConstraintFunctions(collation.Expression);
                return;
            case CastExpression cast:
                ValidateCheckConstraintFunctions(cast.Expression);
                return;
            case CaseExpression @case:
                if (@case.Operand is not null)
                    ValidateCheckConstraintFunctions(@case.Operand);
                foreach (var clause in @case.Clauses)
                {
                    ValidateCheckConstraintFunctions(clause.When);
                    ValidateCheckConstraintFunctions(clause.Then);
                }
                if (@case.Else is not null)
                    ValidateCheckConstraintFunctions(@case.Else);
                return;
            case LikeExpression like:
                ValidateCheckConstraintFunctions(like.Value);
                ValidateCheckConstraintFunctions(like.Pattern);
                if (like.Escape is not null)
                    ValidateCheckConstraintFunctions(like.Escape);
                return;
            case GlobExpression glob:
                ValidateCheckConstraintFunctions(glob.Value);
                ValidateCheckConstraintFunctions(glob.Pattern);
                return;
            case InExpression @in:
                ValidateCheckConstraintFunctions(@in.Value);
                foreach (var value in @in.Values)
                    ValidateCheckConstraintFunctions(value);
                return;
            case InSubqueryExpression inSubquery:
                ValidateCheckConstraintFunctions(inSubquery.Value);
                return;
            case BetweenExpression between:
                ValidateCheckConstraintFunctions(between.Value);
                ValidateCheckConstraintFunctions(between.Lower);
                ValidateCheckConstraintFunctions(between.Upper);
                return;
            case UnaryExpression unary:
                ValidateCheckConstraintFunctions(unary.Operand);
                return;
            case BinaryExpression binary:
                ValidateCheckConstraintFunctions(binary.Left);
                ValidateCheckConstraintFunctions(binary.Right);
                return;
            default:
                return;
        }
    }

    private ExecutionResult ExecuteDropTable(
        DropTableStatement statement,
        SchemaCatalog catalog,
        QueryContext context)
    {
        var tables = catalog.Tables;
        if (IsSqliteSequenceTable(statement.Name) && tables.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"table {SqliteSequenceTableName} may not be dropped");
        if (catalog.Views.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"use DROP VIEW to delete view {statement.Name}");

        if (tables.TryGetValue(statement.Name, out var table))
        {
            if (context.ForeignKeysEnabled && table.Rows.Count > 0)
            {
                var backup = CloneTables(tables);
                var originalRows = table.Rows.ToArray();
                try
                {
                    table.Rows.Clear();
                    table.RowIds.Clear();
                    ValidateForeignKeysAfterDelete(
                        context,
                        statement.Name,
                        table,
                        originalRows,
                        table.Rows,
                        originalRows);
                }
                catch
                {
                    RestoreTables(tables, backup);
                    throw;
                }
            }

            tables.Remove(statement.Name);
            if (table.IsAutoIncrement)
                DeleteSqliteSequenceRows(tables, table.Name);
            RemoveTriggersForTable(catalog, statement.Name);
            return new ExecutionResult([], [], 0, true);
        }

        if (statement.IfExists)
            return ExecutionResult.Empty;

        throw new EmbeddedSqlException($"no such table: {statement.Name}");
    }

    private static void RemoveTriggersForTable(SchemaCatalog catalog, string tableName)
    {
        var orphaned = catalog.Triggers
            // A temp trigger that watches a table in another schema is stored here but is not
            // orphaned by a drop in this schema; the owning connection cleans those up instead.
            .Where(entry => entry.Value.TargetSchema is null
                && string.Equals(entry.Value.TableName, tableName, StringComparison.OrdinalIgnoreCase))
            .Select(entry => entry.Key)
            .ToArray();
        foreach (var trigger in orphaned)
            catalog.Triggers.Remove(trigger);
    }

    private static void EnsureSqliteSequenceTable(SchemaCatalog catalog)
    {
        if (catalog.Tables.TryGetValue(SqliteSequenceTableName, out _))
        {
            ValidateSqliteSequenceCatalog(catalog.Tables);
            return;
        }
        if (catalog.Views.ContainsKey(SqliteSequenceTableName)
            || catalog.Triggers.ContainsKey(SqliteSequenceTableName)
            || TryFindIndex(catalog.Tables, SqliteSequenceTableName, out _, out _))
        {
            throw new EmbeddedSqlException($"object name reserved for internal use: {SqliteSequenceTableName}");
        }

        catalog.Tables.Add(
            SqliteSequenceTableName,
            new EmbeddedTable(
                SqliteSequenceTableName,
                [
                    new EmbeddedColumn("name", null, false, false, false, null),
                    new EmbeddedColumn("seq", null, false, false, false, null),
                ]));
    }

    internal static void ValidateSqliteSequenceCatalog(
        IReadOnlyDictionary<string, EmbeddedTable> tables)
    {
        var requiresSequence = tables.Any(entry =>
            !IsSqliteSequenceTable(entry.Key) && entry.Value.IsAutoIncrement);
        if (!tables.TryGetValue(SqliteSequenceTableName, out var sequence))
        {
            if (requiresSequence)
                throw new EmbeddedSqlException("database disk image is malformed");
            return;
        }

        if (!sequence.HasRowid
            || sequence.ColumnDefinitions.Length != 2
            || !string.Equals(sequence.ColumnDefinitions[0].Name, "name", StringComparison.OrdinalIgnoreCase)
            || !string.Equals(sequence.ColumnDefinitions[1].Name, "seq", StringComparison.OrdinalIgnoreCase)
            || sequence.PrimaryKeyColumns.Count != 0
            || sequence.Indexes.Count != 0)
        {
            throw new EmbeddedSqlException("database disk image is malformed");
        }
    }

    private static void DeleteSqliteSequenceRows(
        IReadOnlyDictionary<string, EmbeddedTable> tables,
        string tableName)
    {
        if (!tables.TryGetValue(SqliteSequenceTableName, out var sequence))
            throw new InvalidOperationException("An AUTOINCREMENT table is missing sqlite_sequence.");

        for (var index = sequence.Rows.Count - 1; index >= 0; index--)
        {
            var name = sequence.Rows[index][0];
            if (name.Kind != SqlValueKind.Text
                || !string.Equals(name.AsText(), tableName, StringComparison.Ordinal))
            {
                continue;
            }

            sequence.Rows.RemoveAt(index);
            sequence.RowIds.RemoveAt(index);
        }
    }

    private ExecutionResult ExecuteCreateIndex(CreateIndexStatement statement, SchemaCatalog catalog)
    {
        var tables = catalog.Tables;
        if (IsSqliteSequenceTable(statement.Name))
            throw new EmbeddedSqlException($"object name reserved for internal use: {SqliteSequenceTableName}");
        if (tables.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"there is already a table named {statement.Name}");
        if (catalog.Views.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"there is already a view named {statement.Name}");
        if (catalog.Triggers.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"there is already a trigger named {statement.Name}");

        if (TryFindIndex(tables, statement.Name, out _, out _))
        {
            if (statement.IfNotExists)
                return ExecutionResult.Empty;

            throw new EmbeddedSqlException($"index {statement.Name} already exists");
        }

        if (IsSchemaTable(statement.TableName))
            throw new EmbeddedSqlException($"table {statement.TableName} may not be indexed");
        if (IsSqliteSequenceTable(statement.TableName))
            throw new EmbeddedSqlException($"table {SqliteSequenceTableName} may not be indexed");
        if (catalog.Views.ContainsKey(statement.TableName))
            throw new EmbeddedSqlException($"views may not be indexed");
        if (!tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");

        var definition = EmbeddedIndexFactory.Create(statement.TableName, table, statement);
        if (definition.Columns.Any(column =>
                column.Expression is not null
                && IndexExpressionSemantics.ContainsFunction(column.Expression, IsRegisteredScalarFunction))
            || definition.Where is not null
                && IndexExpressionSemantics.ContainsFunction(definition.Where, IsRegisteredScalarFunction))
        {
            throw new EmbeddedSqlException(
                "application-defined functions are prohibited in index expressions and partial index WHERE clauses");
        }
        IndexExpressionSemantics.ValidateRoundTrip(statement.TableName, table, definition);
        if (definition.Unique)
            ValidateUniqueIndex(statement.TableName, table, definition, table.Rows);

        table.Indexes.Add(definition);
        return new ExecutionResult([], [], 0, true);
    }

    private ExecutionResult ExecuteReindex(ReindexStatement statement, SchemaCatalog catalog)
    {
        var selected = new List<(string TableName, EmbeddedTable Table, EmbeddedIndex Index)>();
        if (statement.Target is null)
        {
            AddAllIndexes(selected, catalog.Tables);
        }
        else if (statement.TargetKind == ReindexTargetKind.Collation)
        {
            if (!HasCollation(statement.Target))
                throw new EmbeddedSqlException($"no such collation sequence: {statement.Target}");

            foreach (var (tableName, table) in catalog.Tables)
            {
                foreach (var index in table.Indexes)
                {
                    if (index.Columns.Any(term => string.Equals(
                            IndexExpressionSemantics.GetCollationName(table, term),
                            statement.Target,
                            StringComparison.OrdinalIgnoreCase)))
                    {
                        selected.Add((tableName, table, index));
                    }
                }
            }
        }
        else if (catalog.Tables.TryGetValue(statement.Target, out var targetTable))
        {
            foreach (var index in targetTable.Indexes)
                selected.Add((statement.Target, targetTable, index));
        }
        else if (TryFindIndex(catalog.Tables, statement.Target, out var indexedTable, out var targetIndex))
        {
            var tableName = catalog.Tables.Single(entry => ReferenceEquals(entry.Value, indexedTable)).Key;
            selected.Add((tableName, indexedTable, targetIndex));
        }
        else if (TryFindWithoutRowidPrimaryKey(
                     catalog.Tables,
                     statement.Target,
                     out var primaryKeyTableName,
                     out var primaryKeyTable))
        {
            foreach (var index in primaryKeyTable.Indexes)
                selected.Add((primaryKeyTableName, primaryKeyTable, index));
        }
        else
        {
            throw new EmbeddedSqlException("unable to identify the object to be reindexed");
        }

        foreach (var (tableName, table, index) in selected)
        {
            IndexExpressionSemantics.ValidateDefinition(tableName, table, index);
            IndexExpressionSemantics.ValidateRoundTrip(tableName, table, index);
        }

        // The file writer's unchanged-schema full rewrite rebuilds every index tree in one
        // pager transaction. In-memory catalogs have no physical index image to rebuild.
        return _fileStore is null
            ? ExecutionResult.Empty
            : new ExecutionResult(
                [],
                [],
                0,
                Changed: true,
                ForceFullCatalogRewrite: true);
    }

    private static void AddAllIndexes(
        ICollection<(string TableName, EmbeddedTable Table, EmbeddedIndex Index)> destination,
        IReadOnlyDictionary<string, EmbeddedTable> tables)
    {
        foreach (var (tableName, table) in tables)
        {
            foreach (var index in table.Indexes)
                destination.Add((tableName, table, index));
        }
    }

    internal bool HasCollation(string name)
    {
        lock (_gate)
        {
            return name.Equals("BINARY", StringComparison.OrdinalIgnoreCase)
                || name.Equals("NOCASE", StringComparison.OrdinalIgnoreCase)
                || name.Equals("RTRIM", StringComparison.OrdinalIgnoreCase)
                || _collations.ContainsKey(name);
        }
    }

    internal static EmbeddedSqlException AnalyzeNotSupported()
        => new(
            "Managed ANALYZE is not supported because sqlite_stat tables and planner statistics "
            + "are not implemented; no statistics were changed.");

    private bool IsRegisteredScalarFunction(string name, int arity)
    {
        var normalized = name.ToUpperInvariant();
        return _scalarFunctions.ContainsKey((normalized, arity))
            || _scalarFunctions.ContainsKey((normalized, -1));
    }

    private static ExecutionResult ExecuteDropIndex(DropIndexStatement statement, Dictionary<string, EmbeddedTable> tables)
    {
        if (TryFindIndex(tables, statement.Name, out var table, out var index))
        {
            if (index.Origin != EmbeddedIndexOrigin.Explicit)
            {
                throw new EmbeddedSqlException(
                    $"index associated with UNIQUE or PRIMARY KEY constraint cannot be dropped: {statement.Name}");
            }

            table.Indexes.Remove(index);
            return new ExecutionResult([], [], 0, true);
        }

        if (statement.IfExists)
            return ExecutionResult.Empty;

        throw new EmbeddedSqlException($"no such index: {statement.Name}");
    }

    private static bool TryFindIndex(
        Dictionary<string, EmbeddedTable> tables,
        string indexName,
        out EmbeddedTable table,
        out EmbeddedIndex index)
    {
        foreach (var entry in tables)
        {
            foreach (var candidate in entry.Value.Indexes)
            {
                if (string.Equals(candidate.Name, indexName, StringComparison.OrdinalIgnoreCase))
                {
                    table = entry.Value;
                    index = candidate;
                    return true;
                }
            }
        }

        table = null!;
        index = null!;
        return false;
    }

    private static bool TryFindWithoutRowidPrimaryKey(
        IReadOnlyDictionary<string, EmbeddedTable> tables,
        string target,
        out string tableName,
        out EmbeddedTable table)
    {
        foreach (var entry in tables)
        {
            if (!entry.Value.WithoutRowid
                || (!string.Equals(entry.Key, target, StringComparison.OrdinalIgnoreCase)
                    && !string.Equals(
                        entry.Value.WithoutRowidPrimaryKeyIndexName,
                        target,
                        StringComparison.OrdinalIgnoreCase)))
            {
                continue;
            }

            tableName = entry.Key;
            table = entry.Value;
            return true;
        }

        tableName = string.Empty;
        table = null!;
        return false;
    }

    private static ExecutionResult ExecuteCreateView(CreateViewStatement statement, SchemaCatalog catalog)
    {
        var tables = catalog.Tables;
        if (IsSqliteSequenceTable(statement.Name))
            throw new EmbeddedSqlException($"object name reserved for internal use: {SqliteSequenceTableName}");
        if (catalog.Views.ContainsKey(statement.Name))
        {
            if (statement.IfNotExists)
                return ExecutionResult.Empty;

            throw new EmbeddedSqlException($"view {statement.Name} already exists");
        }
        if (tables.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"there is already a table named {statement.Name}");
        if (catalog.Triggers.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"there is already a trigger named {statement.Name}");
        if (TryFindIndex(tables, statement.Name, out _, out _))
            throw new EmbeddedSqlException($"there is already an index named {statement.Name}");

        var view = new ViewDefinition(statement.Name, statement.Columns, statement.Query, statement.Sql);

        // SQLite validates the view body when it is created: base tables must exist and,
        // when an explicit column list is supplied, its arity must match the query output.
        // Register the view before validating so a self-referential body is reported as a
        // circular definition; roll the registration back if validation fails.
        var context = new QueryContext(
            tables,
            new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
            catalog.Views,
            catalog.Triggers);
        catalog.Views.Add(statement.Name, view);
        try
        {
            _ = ResolveViewColumns(view, EnterView(context, view.Name));
        }
        catch
        {
            catalog.Views.Remove(statement.Name);
            throw;
        }

        return new ExecutionResult([], [], 0, true);
    }

    private static ExecutionResult ExecuteDropView(DropViewStatement statement, SchemaCatalog catalog)
    {
        if (catalog.Views.Remove(statement.Name))
        {
            RemoveTriggersForTable(catalog, statement.Name);
            return new ExecutionResult([], [], 0, true);
        }
        if (catalog.Tables.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"use DROP TABLE to delete table {statement.Name}");
        if (statement.IfExists)
            return ExecutionResult.Empty;

        throw new EmbeddedSqlException($"no such view: {statement.Name}");
    }

    private ExecutionResult ExecuteCreateTrigger(
        CreateTriggerStatement statement,
        SchemaCatalog catalog,
        QueryContext context)
    {
        var tables = catalog.Tables;
        if (IsSqliteSequenceTable(statement.Name))
            throw new EmbeddedSqlException($"object name reserved for internal use: {SqliteSequenceTableName}");
        if (catalog.Triggers.ContainsKey(statement.Name))
        {
            if (statement.IfNotExists)
                return ExecutionResult.Empty;

            throw new EmbeddedSqlException($"trigger {statement.Name} already exists");
        }
        if (tables.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"there is already a table named {statement.Name}");
        if (catalog.Views.ContainsKey(statement.Name))
            throw new EmbeddedSqlException($"there is already a view named {statement.Name}");
        if (TryFindIndex(tables, statement.Name, out _, out _))
            throw new EmbeddedSqlException($"there is already an index named {statement.Name}");

        var targetsTable = tables.ContainsKey(statement.TableName);
        var targetsView = catalog.Views.ContainsKey(statement.TableName);
        // A temp trigger may watch a table in another schema. That table lives in a database this
        // instance cannot see, so the owning connection validates the target before routing here.
        if (statement.TargetSchema is null)
        {
            if (IsSqliteSequenceTable(statement.TableName) && targetsTable)
                throw new EmbeddedSqlException("cannot create trigger on system table");
            if (statement.Timing == TriggerTiming.InsteadOf)
            {
                if (targetsTable)
                    throw new EmbeddedSqlException($"cannot create INSTEAD OF trigger on table: {statement.TableName}");
                if (!targetsView)
                    throw new EmbeddedSqlException($"no such view: {statement.TableName}");
            }
            else
            {
                if (targetsView)
                    throw new EmbeddedSqlException($"cannot create {statement.Timing.ToString().ToUpperInvariant()} trigger on view: {statement.TableName}");
                if (!targetsTable)
                    throw new EmbeddedSqlException($"no such table: {statement.TableName}");
            }
        }

        var declarationOrder = catalog.Triggers.Count == 0
            ? 0
            : checked(catalog.Triggers.Values.Max(trigger => trigger.DeclarationOrder) + 1);

        var definition = new TriggerDefinition(
            statement.Name,
            statement.Timing,
            statement.Event,
            statement.UpdateOfColumns,
            statement.TableName,
            statement.When,
            statement.Body,
            statement.Sql,
            declarationOrder,
            statement.TargetSchema,
            statement.Temporary);
        catalog.Triggers.Add(statement.Name, definition);
        return new ExecutionResult([], [], 0, true);
    }

    private static ExecutionResult ExecuteDropTrigger(DropTriggerStatement statement, SchemaCatalog catalog)
    {
        if (catalog.Triggers.Remove(statement.Name))
            return new ExecutionResult([], [], 0, true);
        if (statement.IfExists)
            return ExecutionResult.Empty;

        throw new EmbeddedSqlException($"no such trigger: {statement.Name}");
    }

    private ExecutionResult ExecuteAlterTableAddColumn(
        AlterTableAddColumnStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (IsSqliteSequenceTable(statement.TableName) && context.Tables.ContainsKey(statement.TableName))
            throw new EmbeddedSqlException($"table {SqliteSequenceTableName} may not be altered");
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");

        var candidate = table.Clone();
        candidate.AddColumn(statement.Column);
        for (var position = 0; position < candidate.Rows.Count; position++)
        {
            var rowid = position < candidate.RowIds.Count ? candidate.RowIds[position] : position + 1;
            ValidateCheckConstraints(
                statement.TableName,
                candidate,
                candidate.Rows[position],
                rowid,
                parameters,
                context);
        }
        table.AddColumn(statement.Column);
        return new ExecutionResult([], [], 0, true);
    }

    private ExecutionResult ExecuteAlterTableRename(
        AlterTableRenameStatement statement,
        SchemaCatalog catalog,
        QueryContext context)
    {
        var tables = catalog.Tables;
        if (IsSqliteSequenceTable(statement.TableName) && tables.ContainsKey(statement.TableName))
            throw new EmbeddedSqlException($"table {SqliteSequenceTableName} may not be altered");
        if (IsSqliteSequenceTable(statement.NewName))
            throw new EmbeddedSqlException($"object name reserved for internal use: {SqliteSequenceTableName}");
        if (tables.ContainsKey(statement.NewName))
            throw new EmbeddedSqlException($"table {statement.NewName} already exists");
        if (TryFindIndex(tables, statement.NewName, out _, out _))
            throw new EmbeddedSqlException($"there is already an index named {statement.NewName}");
        if (!tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");
        if (table.HasQualifiedCheckReferences())
        {
            throw new EmbeddedSqlException(
                "ALTER TABLE RENAME cannot rewrite table-qualified CHECK expressions until "
                + "managed schema token rewriting is implemented.");
        }

        var candidateTables = new Dictionary<string, EmbeddedTable>(
            tables,
            StringComparer.OrdinalIgnoreCase);
        var candidateTable = table.Clone();
        candidateTables.Remove(statement.TableName);
        candidateTable.Rename(statement.NewName);
        candidateTables.Add(statement.NewName, candidateTable);
        ValidateDependentSchema(
            catalog,
            context with
            {
                Tables = candidateTables,
                SchemaValidation = true,
            },
            context.CancellationToken,
            "rename table",
            catalog,
            context with { SchemaValidation = true });

        if (!tables.Remove(statement.TableName))
            throw new InvalidOperationException($"Table '{statement.TableName}' disappeared during rename.");
        var previousName = table.Name;
        table.Rename(statement.NewName);
        tables.Add(statement.NewName, table);
        if (table.IsAutoIncrement)
            RenameSqliteSequenceRows(tables, previousName, statement.NewName);
        return new ExecutionResult([], [], 0, true);
    }

    private static void RenameSqliteSequenceRows(
        IReadOnlyDictionary<string, EmbeddedTable> tables,
        string previousName,
        string newName)
    {
        if (!tables.TryGetValue(SqliteSequenceTableName, out var sequence))
            throw new InvalidOperationException("An AUTOINCREMENT table is missing sqlite_sequence.");

        foreach (var row in sequence.Rows)
        {
            if (row[0].Kind == SqlValueKind.Text
                && string.Equals(row[0].AsText(), previousName, StringComparison.Ordinal))
            {
                row[0] = SqlValue.Text(newName);
            }
        }
    }

    private ExecutionResult ExecuteAlterTableRenameColumn(
        AlterTableRenameColumnStatement statement,
        SchemaCatalog catalog,
        QueryContext context)
    {
        var tables = catalog.Tables;
        if (IsSqliteSequenceTable(statement.TableName) && tables.ContainsKey(statement.TableName))
            throw new EmbeddedSqlException($"table {SqliteSequenceTableName} may not be altered");
        if (!tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");

        var oldName = table.Columns[table.GetColumnIndex(statement.ColumnName)];
        var newName = statement.NewName;
        var quoteNewName = statement.QuoteNewName;
        var replacement = table.CreateWithRenamedColumn(
            statement.ColumnName,
            newName,
            quoteNewName,
            context.CancellationToken);

        var candidateTables = new Dictionary<string, EmbeddedTable>(tables, StringComparer.OrdinalIgnoreCase)
        {
            [statement.TableName] = replacement,
        };

        // A foreign key in another table names the parent column by its old spelling, so the
        // REFERENCES clause follows the rename the way SQLite rewrites it.
        foreach (var entry in tables)
        {
            if (string.Equals(entry.Key, statement.TableName, StringComparison.OrdinalIgnoreCase))
                continue;

            if (CreateWithRenamedForeignKeyParentColumn(entry.Value, table.Name, oldName, newName) is { } rewritten)
                candidateTables[entry.Key] = rewritten;
        }

        var renameSchema = CreateRenameColumnSchema(
            candidateTables,
            catalog.Views,
            table.Name,
            table.Columns.ToArray());
        Dictionary<string, ViewDefinition>? candidateViews = null;
        Dictionary<string, TriggerDefinition>? candidateTriggers = null;
        try
        {
            foreach (var view in catalog.Views.Values)
            {
                context.CheckInterrupt();
                var rewritten = RenameColumnRewriter.RewriteSchemaObject(
                    view.Sql,
                    oldName,
                    newName,
                    quoteNewName,
                    renameSchema);
                if (rewritten is null)
                    continue;

                candidateViews ??= new Dictionary<string, ViewDefinition>(
                    catalog.Views,
                    StringComparer.OrdinalIgnoreCase);
                var parsed = (CreateViewStatement)SqlParser.Parse(rewritten, SqlParameterMap.Parse(rewritten));
                candidateViews[view.Name] = view with { Query = parsed.Query, Sql = parsed.Sql };
            }

            foreach (var trigger in catalog.Triggers.Values)
            {
                context.CheckInterrupt();
                var rewritten = RenameColumnRewriter.RewriteSchemaObject(
                    trigger.Sql,
                    oldName,
                    newName,
                    quoteNewName,
                    renameSchema);
                if (rewritten is null)
                    continue;

                candidateTriggers ??= new Dictionary<string, TriggerDefinition>(
                    catalog.Triggers,
                    StringComparer.OrdinalIgnoreCase);
                var parsed = (CreateTriggerStatement)SqlParser.Parse(rewritten, SqlParameterMap.Parse(rewritten));
                candidateTriggers[trigger.Name] = trigger with
                {
                    UpdateOfColumns = parsed.UpdateOfColumns,
                    When = parsed.When,
                    Body = parsed.Body,
                    Sql = parsed.Sql,
                };
            }
        }
        catch (RenameColumnRewriteException exception)
        {
            throw new EmbeddedSqlException(exception.Message, exception);
        }

        var candidateCatalog = candidateViews is null && candidateTriggers is null
            ? catalog
            : new SchemaCatalog(
                candidateTables,
                candidateViews ?? catalog.Views,
                candidateTriggers ?? catalog.Triggers);

        ValidateDependentSchema(
            candidateCatalog,
            context with
            {
                Tables = candidateTables,
                Views = candidateCatalog.Views,
                Triggers = candidateCatalog.Triggers,
                SchemaValidation = true,
            },
            context.CancellationToken,
            "rename",
            catalog,
            context with
            {
                Views = catalog.Views,
                Triggers = catalog.Triggers,
                SchemaValidation = true,
            });

        foreach (var entry in candidateTables)
            tables[entry.Key] = entry.Value;

        if (candidateViews is not null)
        {
            foreach (var entry in candidateViews)
                catalog.Views[entry.Key] = entry.Value;
        }

        if (candidateTriggers is not null)
        {
            foreach (var entry in candidateTriggers)
                catalog.Triggers[entry.Key] = entry.Value;
        }

        return new ExecutionResult([], [], 0, true);
    }

    private static RenameColumnSchema CreateRenameColumnSchema(
        IReadOnlyDictionary<string, EmbeddedTable> tables,
        IReadOnlyDictionary<string, ViewDefinition> views,
        string renamedTable,
        IReadOnlyList<string> renamedTableColumns)
    {
        return new RenameColumnSchema(ResolveColumns, IsRenameTarget);

        IReadOnlyList<string>? ResolveColumns(string name)
        {
            var key = UnqualifiedCatalogName(name);
            // References resolve against the pre-rename shape of the altered table so the old
            // spelling is still recognized while the stored SQL is being edited.
            if (string.Equals(key, renamedTable, StringComparison.OrdinalIgnoreCase))
                return renamedTableColumns;
            if (tables.TryGetValue(key, out var found))
                return found.Columns;

            return views.TryGetValue(key, out var view) ? view.Columns : null;
        }

        bool IsRenameTarget(string name)
            => string.Equals(UnqualifiedCatalogName(name), renamedTable, StringComparison.OrdinalIgnoreCase);

        static string UnqualifiedCatalogName(string name)
            => ManagedSchemaName.TrySplit(name, out _, out var bare) ? bare : name;
    }

    /// <summary>
    /// Rewrites the parent column list of every foreign key in <paramref name="table"/> that
    /// points at the renamed column, returning <see langword="null"/> when nothing referenced it.
    /// </summary>
    private static EmbeddedTable? CreateWithRenamedForeignKeyParentColumn(
        EmbeddedTable table,
        string parentTable,
        string oldName,
        string newName)
    {
        var changed = false;
        var columns = table.ColumnDefinitions.Select(column =>
        {
            var foreignKey = column.ForeignKey is null ? null : Rewrite(column.ForeignKey);
            var additional = column.AdditionalForeignKeys is { Count: > 0 } keys
                && keys.Any(key => Rewrite(key) is not null)
                    ? keys.Select(key => Rewrite(key) ?? key).ToArray()
                    : null;
            if (foreignKey is null && additional is null)
                return column;

            changed = true;
            return column.WithConstraints(
                column.Checks,
                foreignKey ?? column.ForeignKey,
                additional ?? column.AdditionalForeignKeys);
        }).ToArray();

        var tableForeignKeys = table.TableForeignKeys.Select(key =>
        {
            if (Rewrite(key) is not { } replacementKey)
                return key;

            changed = true;
            return replacementKey;
        }).ToArray();

        if (!changed)
            return null;

        var replacement = new EmbeddedTable(
            table.Name,
            columns,
            table.WithoutRowid,
            table.TableLevelPrimaryKey,
            table.TableUniqueConstraints,
            table.CheckConstraints,
            table.TablePrimaryKeyConflictAlgorithm,
            table.TablePrimaryKeyConstraintName,
            table.TablePrimaryKeyDeclarationOrder,
            tableForeignKeys,
            table.Strict);
        foreach (var row in table.Rows)
            replacement.Rows.Add(row.ToArray());

        replacement.RowIds.AddRange(table.RowIds);
        replacement.Indexes.RemoveAll(index => index.Origin == EmbeddedIndexOrigin.Explicit);
        replacement.Indexes.AddRange(table.Indexes.Where(index => index.Origin == EmbeddedIndexOrigin.Explicit));
        return replacement;

        ForeignKeyDefinition? Rewrite(ForeignKeyDefinition foreignKey)
        {
            if (!string.Equals(foreignKey.ParentTable, parentTable, StringComparison.OrdinalIgnoreCase))
                return null;
            if (!foreignKey.ParentColumns.Any(column =>
                    string.Equals(column, oldName, StringComparison.OrdinalIgnoreCase)))
            {
                return null;
            }

            return foreignKey with
            {
                ParentColumns = foreignKey.ParentColumns
                    .Select(column => string.Equals(column, oldName, StringComparison.OrdinalIgnoreCase)
                        ? newName
                        : column)
                    .ToArray(),
            };
        }
    }

    private ExecutionResult ExecuteAlterTableDropColumn(
        AlterTableDropColumnStatement statement,
        SchemaCatalog catalog,
        QueryContext context)
    {
        if (IsSqliteSequenceTable(statement.TableName)
            && catalog.Tables.ContainsKey(statement.TableName))
        {
            throw new EmbeddedSqlException($"table {SqliteSequenceTableName} may not be altered");
        }
        if (!catalog.Tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");

        var replacement = table.CreateWithoutColumn(statement.ColumnName, context.CancellationToken);
        var candidateTables = new Dictionary<string, EmbeddedTable>(
            catalog.Tables,
            StringComparer.OrdinalIgnoreCase)
        {
            [statement.TableName] = replacement,
        };
        var candidateContext = context with
        {
            Tables = candidateTables,
            SchemaValidation = true,
        };

        ValidateDependentSchema(
            catalog,
            candidateContext,
            context.CancellationToken,
            "drop column",
            catalog,
            context with { SchemaValidation = true });

        catalog.Tables[statement.TableName] = replacement;
        return new ExecutionResult([], [], 0, true);
    }

    private void ValidateDependentSchema(
        SchemaCatalog catalog,
        QueryContext candidateContext,
        CancellationToken cancellationToken,
        string operation,
        SchemaCatalog originalCatalog,
        QueryContext originalContext)
    {
        foreach (var view in catalog.Views.Values.OrderBy(view => view.Name, StringComparer.OrdinalIgnoreCase))
        {
            cancellationToken.ThrowIfCancellationRequested();
            try
            {
                var viewContext = EnterView(candidateContext, view.Name);
                ValidateQuerySchema(view.Query, viewContext, outerRow: null, cancellationToken);
            }
            catch (EmbeddedSqlException exception)
            {
                var alreadyBroken = originalCatalog.Views.TryGetValue(view.Name, out var original)
                    && FailsAgainstOriginalSchema(() => ValidateQuerySchema(
                        original.Query,
                        EnterView(originalContext, original.Name),
                        outerRow: null,
                        cancellationToken));
                throw DescribeDependentSchemaFailure("view", view.Name, operation, alreadyBroken, exception);
            }
        }

        foreach (var trigger in catalog.Triggers.Values.OrderBy(trigger => trigger.Name, StringComparer.OrdinalIgnoreCase))
        {
            cancellationToken.ThrowIfCancellationRequested();
            try
            {
                ValidateTriggerSchema(trigger, candidateContext, cancellationToken);
            }
            catch (EmbeddedSqlException exception)
            {
                var alreadyBroken = originalCatalog.Triggers.TryGetValue(trigger.Name, out var original)
                    && FailsAgainstOriginalSchema(
                        () => ValidateTriggerSchema(original, originalContext, cancellationToken));
                throw DescribeDependentSchemaFailure("trigger", trigger.Name, operation, alreadyBroken, exception);
            }
        }
    }

    /// <summary>
    /// Re-runs a dependent-schema check against the pre-ALTER definition and schema to find out
    /// whether the object was already broken. Only <see cref="EmbeddedSqlException"/> is treated as
    /// "already broken"; anything else propagates, because an unexpected failure while classifying
    /// an error is a bug worth surfacing rather than swallowing.
    /// </summary>
    private static bool FailsAgainstOriginalSchema(Action validate)
    {
        try
        {
            validate();
            return false;
        }
        catch (EmbeddedSqlException)
        {
            return true;
        }
    }

    /// <summary>
    /// SQLite blames the ALTER only when it is actually to blame. An object that was valid before
    /// the statement and is invalid after it reports "error in view v after drop column: ...",
    /// while one that was already broken - because a table it referenced was dropped, or because it
    /// never resolved in the first place - reports "error in view v: ..." with no operation.
    /// </summary>
    private static EmbeddedSqlException DescribeDependentSchemaFailure(
        string kind,
        string name,
        string operation,
        bool alreadyBroken,
        EmbeddedSqlException failure)
        => new(
            alreadyBroken
                ? $"error in {kind} {name}: {failure.Message}"
                : $"error in {kind} {name} after {operation}: {failure.Message}",
            failure);

    private void ValidateTriggerSchema(
        TriggerDefinition trigger,
        QueryContext context,
        CancellationToken cancellationToken)
    {
        string[] triggerColumns;
        EmbeddedColumn[]? triggerColumnDefinitions;
        var triggerHasRowid = false;
        if (context.Tables.TryGetValue(trigger.TableName, out var triggerTable))
        {
            triggerColumns = triggerTable.Columns;
            triggerColumnDefinitions = triggerTable.ColumnDefinitions;
            triggerHasRowid = triggerTable.HasRowid;
        }
        else if (context.Views is not null
                 && context.Views.TryGetValue(trigger.TableName, out var triggerView))
        {
            triggerColumns = ResolveViewColumns(triggerView, EnterView(context, triggerView.Name));
            triggerColumnDefinitions = null;
        }
        else
        {
            throw new EmbeddedSqlException($"no such table: {trigger.TableName}");
        }

        var triggerQualifiedColumns = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        var triggerQualifiedDefinitions = new Dictionary<string, EmbeddedColumn>(StringComparer.OrdinalIgnoreCase);
        var triggerValues = new List<SqlValue>();
        var triggerDefinitions = new List<EmbeddedColumn?>();
        var triggerRowIds = new Dictionary<string, long?>(StringComparer.OrdinalIgnoreCase);
        void AddPseudoRow(string qualifier)
        {
            var offset = triggerValues.Count;
            for (var columnIndex = 0; columnIndex < triggerColumns.Length; columnIndex++)
            {
                var qualifiedName = $"{qualifier}.{triggerColumns[columnIndex]}";
                triggerQualifiedColumns.Add(qualifiedName, offset + columnIndex);
                triggerValues.Add(SqlValue.Null);
                var definition = triggerColumnDefinitions?[columnIndex];
                triggerDefinitions.Add(definition);
                if (definition is not null)
                    triggerQualifiedDefinitions.Add(qualifiedName, definition);
            }
            triggerRowIds.Add(qualifier, triggerHasRowid ? 0 : null);
        }
        if (trigger.Event != TriggerEvent.Insert)
            AddPseudoRow("OLD");
        if (trigger.Event != TriggerEvent.Delete)
            AddPseudoRow("NEW");

        var triggerRow = new SourceRow(
            [],
            triggerValues.ToArray(),
            triggerQualifiedColumns,
            QualifiedRowIds: triggerRowIds,
            ColumnDefinitions: triggerDefinitions,
            QualifiedColumnDefinitions: triggerQualifiedDefinitions);
        ValidateExpressionSchema(trigger.When, triggerRow, context, cancellationToken);
        foreach (var bodyStatement in trigger.Body)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (LocalizeTriggerBodyStatement(context, trigger, bodyStatement) is not { } statement)
                continue;

            switch (statement)
            {
                case InsertStatement insert:
                    ValidateTriggerInsert(insert, context, triggerRow, cancellationToken);
                    break;
                case UpdateStatement update:
                    ValidateTriggerUpdate(update, context, triggerRow, cancellationToken);
                    break;
                case DeleteStatement delete:
                    ValidateTriggerDelete(delete, context, triggerRow, cancellationToken);
                    break;
                case QueryStatement query:
                    ValidateQuerySchema(query, context, triggerRow, cancellationToken);
                    break;
                default:
                    throw new EmbeddedSqlException(
                        $"unsupported trigger body statement {statement.GetType().Name}");
            }
        }
    }

    private void ValidateTriggerInsert(
        InsertStatement statement,
        QueryContext context,
        SourceRow triggerRow,
        CancellationToken cancellationToken)
    {
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
        {
            if (context.Views?.TryGetValue(statement.TableName, out var view) == true)
            {
                ValidateTriggerViewInsert(statement, view, context, triggerRow, cancellationToken);
                return;
            }
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");
        }

        if (statement.Columns is { } columns)
        {
            foreach (var column in columns)
                _ = table.GetColumnIndex(column);
        }
        else if (statement.Source is null
                 && statement.Rows.Any(row => row.Length != table.Columns.Length))
        {
            throw new EmbeddedSqlException(
                $"table {statement.TableName} has {table.Columns.Length} columns but "
                + $"{statement.Rows.First(row => row.Length != table.Columns.Length).Length} values were supplied");
        }

        foreach (var row in statement.Rows)
        {
            foreach (var expression in row)
                ValidateExpressionSchema(expression, triggerRow, context, cancellationToken);
        }
        if (statement.Source is not null)
            ValidateQuerySchema(statement.Source, context, triggerRow, cancellationToken);

        var targetRow = CreateSchemaValidationRow(statement.TableName, table, triggerRow);
        if (statement.Upsert is { } upsert)
        {
            foreach (var target in upsert.Target)
            {
                if (target.Expression is { } expression)
                {
                    ValidateExpressionSchema(expression, targetRow, context, cancellationToken);
                }
                else
                {
                    _ = table.GetColumnIndex(
                        target.Name
                        ?? throw new InvalidOperationException("UPSERT target is missing a column or expression."));
                }
            }
            ValidateExpressionSchema(upsert.TargetWhere, targetRow, context, cancellationToken);
            if (upsert.Action is DoUpdateUpsertAction update)
            {
                var upsertRow = CreateUpsertSourceRow(
                    statement.TableName,
                    table,
                    Enumerable.Repeat(SqlValue.Null, table.Columns.Length).ToArray(),
                    targetRowId: 0,
                    Enumerable.Repeat(SqlValue.Null, table.Columns.Length).ToArray()) with
                {
                    Parent = triggerRow,
                };
                foreach (var assignment in update.Assignments)
                {
                    _ = table.GetColumnIndex(assignment.Column);
                    ValidateExpressionSchema(assignment.Value, upsertRow, context, cancellationToken);
                }
                ValidateExpressionSchema(update.Where, upsertRow, context, cancellationToken);
            }
        }
        if (statement.Returning is not null)
        {
            foreach (var projection in statement.Returning)
                ValidateExpressionSchema(projection.Expression, targetRow, context, cancellationToken);
        }
    }

    private void ValidateTriggerUpdate(
        UpdateStatement statement,
        QueryContext context,
        SourceRow triggerRow,
        CancellationToken cancellationToken)
    {
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
        {
            if (context.Views?.TryGetValue(statement.TableName, out var view) == true)
            {
                ValidateTriggerViewUpdate(statement, view, context, triggerRow, cancellationToken);
                return;
            }
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");
        }

        var row = CreateSchemaValidationRow(statement.TableName, table, triggerRow);
        if (statement.From is not null)
        {
            // A trigger body may drive its UPDATE from a source list, so schema validation has to
            // see the joined target/source shape rather than the target table alone.
            var joined = new JoinTableSource(
                new NamedTableSource(statement.TableName, statement.TargetQualifier),
                statement.From,
                Condition: null,
                JoinKind.Inner);
            row = CreateQuerySchemaValidationRow(
                joined,
                context,
                GetSourceColumns(joined, context),
                GetOutputColumns(joined, context),
                triggerRow);
        }

        foreach (var assignment in statement.Assignments)
        {
            _ = table.GetColumnIndex(assignment.Column);
            ValidateExpressionSchema(assignment.Value, row, context, cancellationToken);
        }
        ValidateExpressionSchema(statement.Where, row, context, cancellationToken);
        foreach (var term in ResolveOrderBy(statement.EffectiveOrderBy, statement.Returning ?? []))
            ValidateExpressionSchema(term.Expression, row, context, cancellationToken);
        ValidateExpressionSchema(statement.Limit, row, context, cancellationToken);
        ValidateExpressionSchema(statement.Offset, row, context, cancellationToken);
        if (statement.Returning is not null)
        {
            foreach (var projection in statement.Returning)
                ValidateExpressionSchema(projection.Expression, row, context, cancellationToken);
        }
    }

    private void ValidateTriggerDelete(
        DeleteStatement statement,
        QueryContext context,
        SourceRow triggerRow,
        CancellationToken cancellationToken)
    {
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
        {
            if (context.Views?.TryGetValue(statement.TableName, out var view) == true)
            {
                var viewRow = CreateViewSchemaValidationRow(
                    statement.TableName,
                    view,
                    context,
                    triggerRow);
                ValidateExpressionSchema(statement.Where, viewRow, context, cancellationToken);
                return;
            }
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");
        }

        var row = CreateSchemaValidationRow(statement.TableName, table, triggerRow);
        ValidateExpressionSchema(statement.Where, row, context, cancellationToken);
        foreach (var term in ResolveOrderBy(statement.EffectiveOrderBy, statement.Returning ?? []))
            ValidateExpressionSchema(term.Expression, row, context, cancellationToken);
        ValidateExpressionSchema(statement.Limit, row, context, cancellationToken);
        ValidateExpressionSchema(statement.Offset, row, context, cancellationToken);
        if (statement.Returning is not null)
        {
            foreach (var projection in statement.Returning)
                ValidateExpressionSchema(projection.Expression, row, context, cancellationToken);
        }
    }

    private void ValidateTriggerViewInsert(
        InsertStatement statement,
        ViewDefinition view,
        QueryContext context,
        SourceRow triggerRow,
        CancellationToken cancellationToken)
    {
        if (statement.Upsert is not null || statement.ConflictAlgorithm is not null)
            throw new EmbeddedSqlException("cannot UPSERT a view");
        var row = CreateViewSchemaValidationRow(statement.TableName, view, context, triggerRow);
        if (statement.Columns is { } columns)
        {
            foreach (var column in columns)
                _ = Array.FindIndex(row.Columns, candidate =>
                    string.Equals(candidate, column, StringComparison.OrdinalIgnoreCase)) >= 0
                    ? 0
                    : throw new EmbeddedSqlException(
                        $"table {statement.TableName} has no column named {column}");
        }
        foreach (var values in statement.Rows)
        {
            foreach (var expression in values)
                ValidateExpressionSchema(expression, triggerRow, context, cancellationToken);
        }
        if (statement.Source is not null)
            ValidateQuerySchema(statement.Source, context, triggerRow, cancellationToken);
    }

    private void ValidateTriggerViewUpdate(
        UpdateStatement statement,
        ViewDefinition view,
        QueryContext context,
        SourceRow triggerRow,
        CancellationToken cancellationToken)
    {
        var row = CreateViewSchemaValidationRow(statement.TableName, view, context, triggerRow);
        foreach (var assignment in statement.Assignments)
        {
            if (!row.Columns.Contains(assignment.Column, StringComparer.OrdinalIgnoreCase))
                throw new EmbeddedSqlException($"no such column: {assignment.Column}");
            ValidateExpressionSchema(assignment.Value, row, context, cancellationToken);
        }
        ValidateExpressionSchema(statement.Where, row, context, cancellationToken);
    }

    private SourceRow CreateViewSchemaValidationRow(
        string viewName,
        ViewDefinition view,
        QueryContext context,
        SourceRow? parent)
    {
        var columns = ResolveViewColumns(view, EnterView(context, view.Name));
        return new SourceRow(
            columns,
            Enumerable.Repeat(SqlValue.Null, columns.Length).ToArray(),
            BuildQualifiedColumns(viewName, columns),
            parent,
            BuildOutputColumns(viewName, columns));
    }

    private static SourceRow CreateSchemaValidationRow(
        string tableName,
        EmbeddedTable table,
        SourceRow? parent)
        => new(
            table.Columns,
            Enumerable.Repeat(SqlValue.Null, table.Columns.Length).ToArray(),
            BuildQualifiedColumns(tableName, table.Columns),
            parent,
            BuildOutputColumns(tableName, table.Columns),
            RowId: table.HasRowid ? 0 : null,
            RowIdQualifier: tableName);

    private static SourceRow CreateQuerySchemaValidationRow(
        TableSource? source,
        QueryContext context,
        IReadOnlyList<string> columns,
        IReadOnlyList<OutputColumn> outputColumns,
        SourceRow? outerRow)
    {
        var values = Enumerable.Repeat(SqlValue.Null, columns.Count).ToList();
        Dictionary<string, int>? qualifiedColumns = null;
        long? rowId = null;
        string? rowIdQualifier = null;
        if (source is not null)
        {
            qualifiedColumns = new Dictionary<string, int>(
                GetQualifiedColumns(source, context),
                StringComparer.OrdinalIgnoreCase);
            AppendSchemaRowidBindings(source, context, values, qualifiedColumns);
            if (source is NamedTableSource named
                && !context.CommonTableExpressions.ContainsKey(named.Name)
                && context.Tables.TryGetValue(named.Name, out var table)
                && table.HasRowid)
            {
                rowId = 0;
                rowIdQualifier = named.Alias ?? named.Name;
            }
        }

        return new SourceRow(
            columns.ToArray(),
            values.ToArray(),
            qualifiedColumns,
            outerRow,
            outputColumns,
            rowId,
            rowIdQualifier);
    }

    private static void AppendSchemaRowidBindings(
        TableSource source,
        QueryContext context,
        List<SqlValue> values,
        Dictionary<string, int> qualifiedColumns)
    {
        switch (source)
        {
            case NamedTableSource named
                when !context.CommonTableExpressions.ContainsKey(named.Name)
                     && context.Tables.TryGetValue(named.Name, out var table)
                     && table.HasRowid:
                var rowIdIndex = values.Count;
                values.Add(SqlValue.Integer(0));
                var qualifier = named.Alias ?? named.Name;
                qualifiedColumns.TryAdd($"{qualifier}.rowid", rowIdIndex);
                qualifiedColumns.TryAdd($"{qualifier}._rowid_", rowIdIndex);
                qualifiedColumns.TryAdd($"{qualifier}.oid", rowIdIndex);
                return;
            case JoinTableSource join:
                AppendSchemaRowidBindings(join.Left, context, values, qualifiedColumns);
                AppendSchemaRowidBindings(join.Right, context, values, qualifiedColumns);
                return;
        }
    }

    private void ValidateQuerySchema(
        QueryStatement statement,
        QueryContext context,
        SourceRow? outerRow,
        CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        switch (statement)
        {
            case SelectStatement select:
                select = ResolveNamedWindows(select);
                ValidateTableSourceSchema(select.Source, context, outerRow, cancellationToken);
                var sourceColumns = GetSourceColumns(select.Source, context);
                var outputColumns = GetOutputColumns(select.Source, context);
                var rawOutputColumns = GetRawOutputColumns(select.Source, context);
                var row = CreateQuerySchemaValidationRow(
                    select.Source,
                    context,
                    sourceColumns,
                    outputColumns,
                    outerRow);
                foreach (var projection in select.Projections)
                    ValidateExpressionSchema(projection.Expression, row, context, cancellationToken);
                ValidateExpressionSchema(select.Where, row, context, cancellationToken);
                foreach (var expression in select.GroupBy)
                    ValidateExpressionSchema(expression, row, context, cancellationToken);
                ValidateExpressionSchema(select.Having, row, context, cancellationToken);
                foreach (var window in select.NamedWindows)
                    ValidateWindowSchema(window.Specification, row, context, cancellationToken);
                foreach (var term in ResolveOrderBy(select.OrderBy, select.Projections))
                    ValidateExpressionSchema(term.Expression, row, context, cancellationToken);
                ValidateExpressionSchema(select.Limit, row, context, cancellationToken);
                ValidateExpressionSchema(select.Offset, row, context, cancellationToken);
                _ = GetColumnNames(select.Projections, outputColumns, rawOutputColumns);
                return;
            case ValuesClause values:
                foreach (var valueRow in values.Rows)
                {
                    foreach (var expression in valueRow)
                        ValidateExpressionSchema(expression, outerRow, context, cancellationToken);
                }
                return;
            case CompoundSelectStatement compound:
                foreach (var term in compound.Terms)
                    ValidateQuerySchema(term, context, outerRow, cancellationToken);
                ValidateExpressionSchema(compound.Limit, outerRow, context, cancellationToken);
                ValidateExpressionSchema(compound.Offset, outerRow, context, cancellationToken);
                return;
            case WithSelectStatement with:
                ValidateWithQuerySchema(
                    with.CommonTableExpressions,
                    with.Query,
                    context,
                    outerRow,
                    cancellationToken);
                return;
            default:
                throw new EmbeddedSqlException($"Unsupported query type {statement.GetType().Name}.");
        }
    }

    private void ValidateWindowSchema(
        WindowSpecification window,
        SourceRow? row,
        QueryContext context,
        CancellationToken cancellationToken)
    {
        foreach (var expression in window.PartitionBy)
            ValidateExpressionSchema(expression, row, context, cancellationToken);
        foreach (var term in window.OrderBy)
            ValidateExpressionSchema(term.Expression, row, context, cancellationToken);
        if (window.Frame is { } frame)
        {
            ValidateExpressionSchema(frame.Start.Offset, row, context, cancellationToken);
            ValidateExpressionSchema(frame.End.Offset, row, context, cancellationToken);
        }
    }

    private void ValidateWithQuerySchema(
        IReadOnlyList<CommonTableExpression> expressions,
        QueryStatement query,
        QueryContext context,
        SourceRow? outerRow,
        CancellationToken cancellationToken)
    {
        var resolved = new Dictionary<string, SourceData>(
            context.CommonTableExpressions,
            StringComparer.OrdinalIgnoreCase);
        var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var expression in expressions)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (!names.Add(expression.Name))
                throw new EmbeddedSqlException($"duplicate WITH table name: {expression.Name}");

            var expressionContext = context with { CommonTableExpressions = resolved };
            var descriptor = expression.Query is CompoundSelectStatement { Terms.Count: > 0 } compound
                ? compound.Terms[0]
                : expression.Query;
            ValidateQuerySchema(descriptor, expressionContext, outerRow, cancellationToken);
            var columns = ResolveCommonTableExpressionColumns(
                expression,
                DescribeQuery(descriptor, expressionContext));
            resolved[expression.Name] = new SourceData(columns, []);
            if (!ReferenceEquals(descriptor, expression.Query))
            {
                ValidateQuerySchema(
                    expression.Query,
                    context with { CommonTableExpressions = resolved },
                    outerRow,
                    cancellationToken);
            }
        }

        ValidateQuerySchema(
            query,
            context with { CommonTableExpressions = resolved },
            outerRow,
            cancellationToken);
    }

    private void ValidateTableSourceSchema(
        TableSource? source,
        QueryContext context,
        SourceRow? outerRow,
        CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        switch (source)
        {
            case null:
                return;
            case NamedTableSource named when TryGetView(context, named.Name, out var view):
                var viewContext = EnterView(context, view.Name);
                ValidateQuerySchema(view.Query, viewContext, outerRow, cancellationToken);
                _ = ResolveViewColumns(view, viewContext);
                return;
            case NamedTableSource named:
                _ = GetSourceColumns(named, context);
                return;
            case TableValuedFunctionSource function:
                foreach (var argument in function.Arguments)
                    ValidateExpressionSchema(argument, outerRow, context, cancellationToken);
                return;
            case DerivedTableSource derived:
                ValidateQuerySchema(derived.Query, context, outerRow, cancellationToken);
                return;
            case JoinTableSource join:
                ValidateTableSourceSchema(join.Left, context, outerRow, cancellationToken);
                ValidateTableSourceSchema(join.Right, context, outerRow, cancellationToken);
                var columns = GetSourceColumns(join, context);
                var outputColumns = GetOutputColumns(join, context);
                var row = new SourceRow(
                    columns,
                    Enumerable.Repeat(SqlValue.Null, columns.Length).ToArray(),
                    GetQualifiedColumns(join, context),
                    outerRow,
                    outputColumns);
                ValidateExpressionSchema(join.Condition, row, context, cancellationToken);
                return;
            default:
                throw new EmbeddedSqlException($"Unsupported table source {source.GetType().Name}.");
        }
    }

    private void ValidateExpressionSchema(
        Expression? expression,
        SourceRow? row,
        QueryContext context,
        CancellationToken cancellationToken)
    {
        if (expression is null)
            return;

        cancellationToken.ThrowIfCancellationRequested();
        switch (expression)
        {
            case LiteralExpression or CurrentTimeExpression or ParameterExpression
                or StarExpression or QualifiedStarExpression:
                return;
            case RowValueExpression rowValue:
                foreach (var value in rowValue.Values)
                    ValidateExpressionSchema(value, row, context, cancellationToken);
                return;
            case ColumnExpression column:
                (row ?? new SourceRow([], [])).GetValue(column);
                return;
            case FunctionExpression function:
                foreach (var argument in function.Arguments)
                    ValidateExpressionSchema(argument, row, context, cancellationToken);
                ValidateExpressionSchema(function.Filter, row, context, cancellationToken);
                if (function.Window is not null)
                {
                    foreach (var partition in function.Window.PartitionBy)
                        ValidateExpressionSchema(partition, row, context, cancellationToken);
                    foreach (var term in function.Window.OrderBy)
                        ValidateExpressionSchema(term.Expression, row, context, cancellationToken);
                    if (function.Window.Frame is { } frame)
                    {
                        ValidateExpressionSchema(frame.Start.Offset, row, context, cancellationToken);
                        ValidateExpressionSchema(frame.End.Offset, row, context, cancellationToken);
                    }
                }
                return;
            case RaiseExpression raise:
                return;
            case ScalarSubqueryExpression scalar:
                ValidateQuerySchema(scalar.Query, context, row, cancellationToken);
                return;
            case ExistsExpression exists:
                ValidateQuerySchema(exists.Query, context, row, cancellationToken);
                return;
            case CollationExpression collation:
                ValidateExpressionSchema(collation.Expression, row, context, cancellationToken);
                return;
            case CastExpression cast:
                ValidateExpressionSchema(cast.Expression, row, context, cancellationToken);
                return;
            case CaseExpression @case:
                ValidateExpressionSchema(@case.Operand, row, context, cancellationToken);
                foreach (var clause in @case.Clauses)
                {
                    ValidateExpressionSchema(clause.When, row, context, cancellationToken);
                    ValidateExpressionSchema(clause.Then, row, context, cancellationToken);
                }
                ValidateExpressionSchema(@case.Else, row, context, cancellationToken);
                return;
            case LikeExpression like:
                ValidateExpressionSchema(like.Value, row, context, cancellationToken);
                ValidateExpressionSchema(like.Pattern, row, context, cancellationToken);
                ValidateExpressionSchema(like.Escape, row, context, cancellationToken);
                return;
            case GlobExpression glob:
                ValidateExpressionSchema(glob.Value, row, context, cancellationToken);
                ValidateExpressionSchema(glob.Pattern, row, context, cancellationToken);
                return;
            case InExpression @in:
                ValidateExpressionSchema(@in.Value, row, context, cancellationToken);
                foreach (var value in @in.Values)
                    ValidateExpressionSchema(value, row, context, cancellationToken);
                return;
            case InSubqueryExpression inSubquery:
                ValidateExpressionSchema(inSubquery.Value, row, context, cancellationToken);
                ValidateQuerySchema(inSubquery.Query, context, row, cancellationToken);
                return;
            case BetweenExpression between:
                ValidateExpressionSchema(between.Value, row, context, cancellationToken);
                ValidateExpressionSchema(between.Lower, row, context, cancellationToken);
                ValidateExpressionSchema(between.Upper, row, context, cancellationToken);
                return;
            case UnaryExpression unary:
                ValidateExpressionSchema(unary.Operand, row, context, cancellationToken);
                return;
            case BinaryExpression binary:
                ValidateExpressionSchema(binary.Left, row, context, cancellationToken);
                ValidateExpressionSchema(binary.Right, row, context, cancellationToken);
                return;
            default:
                throw new EmbeddedSqlException($"Unsupported expression type {expression.GetType().Name}.");
        }
    }

    private ExecutionResult ExecuteInsert(InsertStatement statement, SqlValue[] parameters, QueryContext context)
    {
        if (context.InsideTrigger && context.TriggerConflictAlgorithm is { } triggerConflictAlgorithm)
            statement = statement with { ConflictAlgorithm = triggerConflictAlgorithm };
        else if (context.InsideTrigger
            && statement.Upsert is null
            && context.ConflictAlgorithmOverride is { } conflictOverride)
        {
            statement = statement with { ConflictAlgorithm = conflictOverride };
            context = context with { InheritedTriggerConflict = true };
        }
        var mayReplaceRows = statement.ConflictAlgorithm == InsertConflictAlgorithm.Replace
            || context.Tables.TryGetValue(statement.TableName, out var triggerTable)
                && triggerTable.HasNonDefaultConflictAlgorithms;
        if (context.Views?.ContainsKey(statement.TableName) == true
            || HasRowTriggers(context, statement.TableName, TriggerEvent.Insert)
            || statement.Upsert is not null
                && HasTriggerEvent(context, statement.TableName, TriggerEvent.Update)
            || context.RecursiveTriggersEnabled
                && mayReplaceRows
                && HasTriggerEvent(context, statement.TableName, TriggerEvent.Delete))
        {
            return ExecuteRowTriggeredInsert(statement, parameters, context);
        }

        if (statement.Upsert is not null)
        {
            return context.ForeignKeysEnabled
                ? ExecuteWithForeignKeyStatement(context, () => ExecuteUpsert(statement, parameters, context))
                : ExecuteUpsert(statement, parameters, context);
        }
        if (statement.ConflictAlgorithm is { } algorithm)
        {
            return context.ForeignKeysEnabled
                ? ExecuteWithForeignKeyStatement(
                    context,
                    () => ExecuteConflictResolvedInsert(
                        statement,
                        algorithm,
                        parameters,
                        context,
                        statementPolicyExplicit: true))
                : ExecuteConflictResolvedInsert(
                    statement,
                    algorithm,
                    parameters,
                    context,
                    statementPolicyExplicit: true);
        }
        if (context.Tables.TryGetValue(statement.TableName, out var table)
            && table.HasNonDefaultConflictAlgorithms)
        {
            return context.ForeignKeysEnabled
                ? ExecuteWithForeignKeyStatement(
                    context,
                    () => ExecuteConflictResolvedInsert(
                        statement,
                        InsertConflictAlgorithm.Abort,
                        parameters,
                        context,
                        statementPolicyExplicit: false))
                : ExecuteConflictResolvedInsert(
                    statement,
                    InsertConflictAlgorithm.Abort,
                    parameters,
                    context,
                    statementPolicyExplicit: false);
        }

        if (GetMatchingTriggers(context, statement.TableName, TriggerEvent.Insert, TriggerTiming.Before).Count > 0
            || GetMatchingTriggers(context, statement.TableName, TriggerEvent.Insert, TriggerTiming.After).Count > 0)
        {
            return context.ForeignKeysEnabled
                ? ExecuteWithForeignKeyStatement(
                context,
                () => ExecuteConflictResolvedInsert(
                    statement,
                    InsertConflictAlgorithm.Abort,
                    parameters,
                    context,
                    statementPolicyExplicit: false))
                : ExecuteConflictResolvedInsert(
                statement,
                InsertConflictAlgorithm.Abort,
                parameters,
                context,
                statementPolicyExplicit: false);
        }

        return ExecuteWithTriggers(
            statement.TableName,
            TriggerEvent.Insert,
            context,
            () => PerformInsert(statement, parameters, context));
    }

    private static bool RequiresRecursiveTriggerStack(
        ParsedStatement statement,
        bool recursiveTriggersEnabled,
        bool hasTriggers)
        => recursiveTriggersEnabled
            && hasTriggers
            && !s_hasRecursiveTriggerStack
            && statement is InsertStatement or UpdateStatement or DeleteStatement or WithDmlStatement;

    private T ExecuteWithRecursiveTriggerStack<T>(Func<T> operation)
    {
        // A SQL trigger level spans several managed calls. Use a bounded larger stack so
        // SQLite's 1,000-level limit surfaces as a SQL error instead of terminating the process.
        T result = default!;
        ExceptionDispatchInfo? failure = null;
        using var callbacks = new RecursiveTriggerCallbackDispatcher(this);
        using var completed = new ManualResetEventSlim();
        var thread = new Thread(
            () =>
            {
                s_hasRecursiveTriggerStack = true;
                s_recursiveTriggerCallbackDispatcher = callbacks;
                try
                {
                    result = operation();
                }
                catch (Exception exception)
                {
                    failure = ExceptionDispatchInfo.Capture(exception);
                }
                finally
                {
                    s_recursiveTriggerCallbackDispatcher = null;
                    s_hasRecursiveTriggerStack = false;
                    completed.Set();
                }
            },
            RecursiveTriggerStackSize)
        {
            IsBackground = true,
            Name = "Ahtola recursive trigger",
        };
        thread.Start();
        callbacks.RunUntil(completed);
        thread.Join();
        failure?.Throw();
        return result;
    }

    private T InvokeManagedCallback<T>(Func<T> callback)
        => s_recursiveTriggerCallbackDispatcher is { } dispatcher
            ? dispatcher.Invoke(callback)
            : callback();

    private void ThrowIfRecursiveTriggerCallbackReentry()
    {
        if (ReferenceEquals(RecursiveTriggerCallbackDatabase.Value, this))
            ThrowRecursiveTriggerCallbackReentry();
    }

    internal static bool IsRecursiveTriggerCallbackDatabase(EmbeddedDatabase database)
        => ReferenceEquals(RecursiveTriggerCallbackDatabase.Value, database);

    internal static void ThrowRecursiveTriggerCallbackReentry()
    {
        throw new EmbeddedSqlException(
            "reentrant managed database use from a recursive trigger callback is not supported");
    }

    private sealed class RecursiveTriggerCallbackDispatcher(
        EmbeddedDatabase database) : IDisposable
    {
        private readonly ConcurrentQueue<Action> _pending = new();
        private readonly AutoResetEvent _pendingAvailable = new(initialState: false);

        public T Invoke<T>(Func<T> callback)
        {
            T result = default!;
            ExceptionDispatchInfo? failure = null;
            using var completed = new ManualResetEventSlim();
            _pending.Enqueue(() =>
            {
                var previousDatabase = RecursiveTriggerCallbackDatabase.Value;
                RecursiveTriggerCallbackDatabase.Value = database;
                try
                {
                    result = callback();
                }
                catch (Exception exception)
                {
                    failure = ExceptionDispatchInfo.Capture(exception);
                }
                finally
                {
                    RecursiveTriggerCallbackDatabase.Value = previousDatabase;
                    completed.Set();
                }
            });
            _pendingAvailable.Set();
            completed.Wait();
            failure?.Throw();
            return result;
        }

        public void RunUntil(ManualResetEventSlim workerCompleted)
        {
            var waitHandles = new[] { _pendingAvailable, workerCompleted.WaitHandle };
            while (true)
            {
                Drain();
                if (workerCompleted.IsSet)
                {
                    Drain();
                    return;
                }

                _ = WaitHandle.WaitAny(waitHandles);
            }
        }

        private void Drain()
        {
            while (_pending.TryDequeue(out var callback))
                callback();
        }

        public void Dispose() => _pendingAvailable.Dispose();
    }

    private void MarkTriggerStatementRollbackRequirement(
        QueryContext context,
        EmbeddedTable table,
        TriggerMutationKind mutationKind,
        UpdatePlan? updatePlan = null)
    {
        if (context.TriggerState is not { } state || state.RequiresStatementRollback)
            return;

        state.RequiresStatementRollback = TriggerMutationRequiresStatementRollback(
            context,
            table,
            mutationKind,
            updatePlan);
    }

    private bool TriggerMutationRequiresStatementRollback(
        QueryContext context,
        EmbeddedTable table,
        TriggerMutationKind mutationKind,
        UpdatePlan? updatePlan = null)
    {
        var assignedColumns = updatePlan?.ColumnAssignments
            .Select(assignment => assignment.Index)
            .ToHashSet();
        var affectsEveryColumn = mutationKind == TriggerMutationKind.Insert;
        bool AffectsColumn(int index)
            => affectsEveryColumn || assignedColumns!.Contains(index);
        bool AffectsNamedColumn(string name)
            => table.TryGetColumnIndex(name, out var index)
                && (AffectsColumn(index)
                    || mutationKind == TriggerMutationKind.Update
                        && table.ColumnDefinitions[index].IsGenerated
                        && assignedColumns!.Count != 0);
        var affectsRowid = updatePlan?.RowidAssignment is not null;
        var referencesAsParent = context.Tables.Values
            .SelectMany(candidate => candidate.ForeignKeys)
            .Where(foreignKey => string.Equals(
                foreignKey.ParentTable,
                table.Name,
                StringComparison.OrdinalIgnoreCase))
            .ToArray();
        var hasRelevantForeignKeys = context.ForeignKeysEnabled
            && (mutationKind switch
            {
                TriggerMutationKind.Insert => table.ForeignKeys.Any(foreignKey =>
                    ForeignKeyCanAbortStatement(
                        context,
                        foreignKey,
                        ForeignKeyAction.NoAction)),
                TriggerMutationKind.Delete => referencesAsParent.Any(foreignKey =>
                    ForeignKeyCanAbortStatement(
                        context,
                        foreignKey,
                        foreignKey.OnDelete)),
                TriggerMutationKind.Update => table.ForeignKeys.Any(foreignKey =>
                        foreignKey.ChildColumns.Any(AffectsNamedColumn)
                        && ForeignKeyCanAbortStatement(
                            context,
                            foreignKey,
                            ForeignKeyAction.NoAction))
                    || referencesAsParent.Any(foreignKey =>
                        (foreignKey.ParentColumns.Count == 0
                            ? affectsRowid
                                || table.PrimaryKeyColumns.Any(primaryKey =>
                                    AffectsColumn(primaryKey.Index))
                            : foreignKey.ParentColumns.Any(AffectsNamedColumn))
                        && ForeignKeyCanAbortStatement(
                            context,
                            foreignKey,
                            foreignKey.OnUpdate)),
                _ => throw new InvalidOperationException(
                    $"Unknown trigger mutation kind {mutationKind}."),
            });
        if (mutationKind == TriggerMutationKind.Delete)
            return hasRelevantForeignKeys;
        bool AffectsIndex(EmbeddedIndex index)
            => index.Columns.Any(column =>
                    column.IsExpression
                    || column.ColumnIndex >= 0 && AffectsColumn(column.ColumnIndex))
                || index.Where is not null
                    && EnumerateTriggerColumnExpressions(index.Where).Any(column =>
                        AffectsNamedColumn(column.UnqualifiedName ?? column.Name))
                || table.HasGeneratedColumns
                    && (affectsEveryColumn || assignedColumns!.Count != 0);
        var checkConstraintsRequireRollback =
            (affectsEveryColumn || assignedColumns!.Count != 0)
            && (table.CheckConstraints.Any(check =>
                    NotNullConstraintRequiresStatementRollback(
                        context.ConflictAlgorithmOverride,
                        check.ConflictAlgorithm))
                || table.ColumnDefinitions.Any(column =>
                    (affectsEveryColumn
                        || AffectsNamedColumn(column.Name)
                        || mutationKind == TriggerMutationKind.Update
                            && column.IsGenerated
                            && assignedColumns!.Count != 0)
                    && column.CheckConstraints.Any(check =>
                        NotNullConstraintRequiresStatementRollback(
                            context.ConflictAlgorithmOverride,
                            check.ConflictAlgorithm))));

        // SQLite opens a statement journal when a trigger program can abort on an
        // enforced constraint. A depth error then rolls back the statement, while an
        // unconstrained program inside a transaction retains its completed prefix.
        return table.PrimaryKeyColumns.Any(primaryKey =>
                AffectsColumn(primaryKey.Index) || affectsRowid)
                && ConstraintRequiresStatementRollback(
                    context.ConflictAlgorithmOverride,
                    table.PrimaryKeyConflictAlgorithm)
            || table.TableUniqueConstraints.Any(constraint => constraint.Columns.Any(column =>
                    AffectsNamedColumn(column.Name))
                &&
                ConstraintRequiresStatementRollback(
                    context.ConflictAlgorithmOverride,
                    constraint.ConflictAlgorithm))
            || checkConstraintsRequireRollback
            || table.ColumnDefinitions.Any(column =>
                table.TryGetColumnIndex(column.Name, out var columnIndex)
                && (AffectsColumn(columnIndex)
                    || mutationKind == TriggerMutationKind.Update
                        && column.IsGenerated
                        && assignedColumns!.Count != 0)
                && (column.NotNull
                    && NotNullConstraintRequiresStatementRollback(
                        context.ConflictAlgorithmOverride,
                        column.NotNullConflictAlgorithm)
                || column.Unique
                    && ConstraintRequiresStatementRollback(
                        context.ConflictAlgorithmOverride,
                        column.UniqueConflictAlgorithm)))
            || table.ColumnDefinitions.Any(column =>
                column.IsGenerated
                && (affectsEveryColumn || assignedColumns!.Count != 0)
                && TriggerExpressionCanAbort(column.GenerationExpression))
            || table.Indexes.Any(index =>
                index.Unique
                && index.Origin == EmbeddedIndexOrigin.Explicit
                && AffectsIndex(index)
                && ConstraintRequiresStatementRollback(
                    context.ConflictAlgorithmOverride,
                    index.ConflictAlgorithm))
            || table.Indexes.Any(index =>
                AffectsIndex(index)
                && (TriggerExpressionCanAbort(index.Where)
                    || index.Columns.Any(column =>
                        TriggerExpressionCanAbort(column.Expression))))
            || hasRelevantForeignKeys;
    }

    private static bool ForeignKeyCanAbortStatement(
        QueryContext context,
        ForeignKeyDefinition foreignKey,
        ForeignKeyAction action)
    {
        if (action == ForeignKeyAction.Restrict)
            return true;
        if (action == ForeignKeyAction.NoAction)
        {
            return !context.InTransaction
                || !context.DeferForeignKeys
                    && foreignKey.Deferral != ForeignKeyDeferral.InitiallyDeferred;
        }
        if (action is ForeignKeyAction.Cascade
            or ForeignKeyAction.SetNull
            or ForeignKeyAction.SetDefault)
        {
            return true;
        }
        return false;
    }

    private static bool ConstraintRequiresStatementRollback(
        InsertConflictAlgorithm? statementAlgorithm,
        InsertConflictAlgorithm? constraintAlgorithm)
        => (statementAlgorithm ?? constraintAlgorithm) is null
            or InsertConflictAlgorithm.Abort;

    private static bool NotNullConstraintRequiresStatementRollback(
        InsertConflictAlgorithm? statementAlgorithm,
        InsertConflictAlgorithm? constraintAlgorithm)
        => (statementAlgorithm ?? constraintAlgorithm) is null
            or InsertConflictAlgorithm.Abort
            or InsertConflictAlgorithm.Replace;

    private static ExecutionResult ExecuteDmlWithAutoIncrementState(
        QueryContext context,
        Func<QueryContext, ExecutionResult> execute)
    {
        if (context.AutoIncrementState is not null)
            return execute(context);

        var state = new AutoIncrementStatementState();
        var scoped = context with { AutoIncrementState = state };
        var result = execute(scoped);
        var sequenceChanged = state.Commit(scoped.Tables);
        return sequenceChanged && !result.Changed
            ? result with { Changed = true }
            : result;
    }

    private ExecutionResult ExecuteConflictResolvedInsert(
        InsertStatement statement,
        InsertConflictAlgorithm algorithm,
        SqlValue[] parameters,
        QueryContext context,
        bool statementPolicyExplicit)
    {
        if (statement.Upsert is not null)
        {
            throw new EmbeddedSqlException(
                "Managed INSERT OR conflict resolution cannot be combined with an ON CONFLICT UPSERT clause.");
        }
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");

        ValidateInsertReturning(statement, table, context);
        var triggerContext = context with
        {
            TriggerConflictAlgorithm = statementPolicyExplicit ? algorithm : null,
        };
        var beforeTriggers = GetMatchingTriggers(
            triggerContext,
            statement.TableName,
            TriggerEvent.Insert,
            TriggerTiming.Before);
        var afterTriggers = GetMatchingTriggers(
            triggerContext,
            statement.TableName,
            TriggerEvent.Insert,
            TriggerTiming.After);
        var beforeDeleteTriggers = triggerContext.RecursiveTriggersEnabled
            ? GetMatchingTriggers(
                triggerContext,
                statement.TableName,
                TriggerEvent.Delete,
                TriggerTiming.Before)
            : [];
        var afterDeleteTriggers = triggerContext.RecursiveTriggersEnabled
            ? GetMatchingTriggers(
                triggerContext,
                statement.TableName,
                TriggerEvent.Delete,
                TriggerTiming.After)
            : [];
        var sourceRows = statement.Source is null
            ? null
            : ExecuteQuery(
                statement.Source,
                parameters,
                triggerContext,
                outerRow: null).Rows;
        var backup = CloneTablesShallow(triggerContext.Tables);
        var initialLastInsertRowId = GetLastInsertRowId(triggerContext);
        var insertedRows = new List<SqlValue[]>();
        var insertedRowIds = new List<long>();
        try
        {
            if (sourceRows is not null)
            {
                foreach (var values in sourceRows)
                    InsertValues(values);
            }
            else
            {
                foreach (var values in statement.Rows)
                    InsertExpressions(values);
            }

            var lastInsertRowId = table.HasRowid && insertedRowIds.Count > 0
                ? insertedRowIds[^1]
                : (long?)null;
            return BuildConflictInsertResult(
                statement,
                table,
                insertedRows,
                insertedRowIds,
                parameters,
                triggerContext,
                lastInsertRowId,
                updateLastInsertRowIdPerRow: table.HasRowid);
        }
        catch (EmbeddedConflictFailException)
        {
            throw;
        }
        catch (EmbeddedConflictRollbackException)
        {
            RestoreTables(triggerContext.Tables, backup);
            throw;
        }
        catch (EmbeddedTriggerRaiseException exception)
            when (exception.Algorithm == InsertConflictAlgorithm.Ignore)
        {
            throw;
        }
        catch (EmbeddedTriggerRaiseException exception)
            when (exception.Algorithm == InsertConflictAlgorithm.Fail)
        {
            throw new EmbeddedConflictFailException(
                exception,
                GetLastInsertRowId(triggerContext));
        }
        catch (EmbeddedTriggerRaiseException exception)
            when (exception.Algorithm == InsertConflictAlgorithm.Rollback)
        {
            RestoreTables(triggerContext.Tables, backup);
            throw new EmbeddedConflictRollbackException(
                exception,
                GetLastInsertRowId(triggerContext));
        }
        catch (EmbeddedSqlException exception)
        {
            var failedLastInsertRowId = GetLastInsertRowId(triggerContext);
            RestoreTables(triggerContext.Tables, backup);
            if (failedLastInsertRowId != initialLastInsertRowId)
                throw new EmbeddedStatementAbortException(exception, failedLastInsertRowId);
            throw;
        }
        catch
        {
            RestoreTables(triggerContext.Tables, backup);
            throw;
        }

        void InsertExpressions(Expression[] values)
        {
            var plan = PrepareInsert(statement, table, triggerContext);
            var deferredRowId = table.HasRowid && beforeTriggers.Count > 0
                ? new DeferredInsertRowId()
                : null;
            InsertCandidate(() => BuildInsertRow(
                statement,
                table,
                plan,
                values,
                parameters,
                triggerContext,
                allowExistingRowid: true,
                validateCheckConstraints: false,
                resolveNotNullReplace: false,
                deferRowidTracking: deferredRowId is not null), plan, deferredRowId);
        }

        void InsertValues(IReadOnlyList<SqlValue> values)
        {
            var plan = PrepareInsert(statement, table, triggerContext);
            var deferredRowId = table.HasRowid && beforeTriggers.Count > 0
                ? new DeferredInsertRowId()
                : null;
            InsertCandidate(() => BuildInsertRow(
                statement,
                table,
                plan,
                values,
                parameters,
                triggerContext,
                allowExistingRowid: true,
                validateCheckConstraints: false,
                resolveNotNullReplace: false,
                deferRowidTracking: deferredRowId is not null), plan, deferredRowId);
        }

        void InsertCandidate(
            Func<(SqlValue[] Row, long RowId)> build,
            InsertPlan plan,
            DeferredInsertRowId? deferredRowId)
        {
            SqlValue[] row;
            long rowId;
            try
            {
                (row, rowId) = build();
            }
            catch (EmbeddedSqlException exception) when (IsConflictAlgorithmConstraint(exception))
            {
                var effectiveAlgorithm = statementPolicyExplicit
                    ? algorithm
                    : exception.ConflictAlgorithm ?? InsertConflictAlgorithm.Abort;
                switch (effectiveAlgorithm)
                {
                    case InsertConflictAlgorithm.Ignore:
                        return;
                    case InsertConflictAlgorithm.Fail:
                        throw new EmbeddedConflictFailException(
                            exception,
                            GetLastInsertRowId(triggerContext));
                    case InsertConflictAlgorithm.Rollback:
                        throw new EmbeddedConflictRollbackException(
                            exception,
                            GetLastInsertRowId(triggerContext));
                    default:
                        throw;
                }
            }

            var frame = new TriggerRowFrame(null, null, row, table.HasRowid ? rowId : null);
            try
            {
                if (beforeTriggers.Count > 0 && FireTriggers(beforeTriggers, triggerContext, frame))
                    return;

                ResolveNotNullReplaceDefaults(statement, table, row, triggerContext);
                if (deferredRowId is not null)
                {
                    rowId = FinalizeAutomaticRowId(
                        statement.TableName,
                        table,
                        plan,
                        row,
                        parameters,
                        triggerContext);
                    frame = new TriggerRowFrame(null, null, row, rowId);
                }
                ValidateCheckConstraints(
                    statement.TableName,
                    table,
                    row,
                    rowId,
                    parameters,
                    triggerContext);
                if (algorithm == InsertConflictAlgorithm.Replace)
                {
                    CommitReplacement(
                        triggerContext,
                        statement.TableName,
                        table,
                        row,
                        rowId,
                        beforeDeleteTriggers,
                        afterDeleteTriggers);
                }
                else
                {
                    CommitInserts(triggerContext, statement.TableName, table, [row], [rowId]);
                }
            }
            catch (EmbeddedTriggerRaiseException exception)
            {
                HandleRaise(exception);
                return;
            }
            catch (EmbeddedSqlException exception)
            {
                var effectiveAlgorithm = statementPolicyExplicit
                    ? algorithm
                    : exception.ConflictAlgorithm ?? InsertConflictAlgorithm.Abort;
                if (!IsConflictAlgorithmConstraint(exception))
                    throw;

                switch (effectiveAlgorithm)
                {
                    case InsertConflictAlgorithm.Ignore:
                        return;
                    case InsertConflictAlgorithm.Fail:
                        throw new EmbeddedConflictFailException(
                            exception,
                            GetLastInsertRowId(triggerContext));
                    case InsertConflictAlgorithm.Rollback:
                        throw new EmbeddedConflictRollbackException(
                            exception,
                            GetLastInsertRowId(triggerContext));
                    case InsertConflictAlgorithm.Abort:
                        throw;
                    case InsertConflictAlgorithm.Replace
                        when !statementPolicyExplicit
                            && exception.Message.StartsWith(
                            "UNIQUE constraint failed:",
                            StringComparison.Ordinal):
                        CommitReplacement(
                            triggerContext,
                            statement.TableName,
                            table,
                            row,
                            rowId,
                            beforeDeleteTriggers,
                            afterDeleteTriggers);
                        break;
                    case InsertConflictAlgorithm.Replace:
                        throw;
                    default:
                        throw new InvalidOperationException("Unknown INSERT conflict algorithm.");
                }
            }

            insertedRows.Add(row);
            insertedRowIds.Add(rowId);
            if (table.HasRowid)
                SetLastInsertRowId(triggerContext, rowId);
            try
            {
                if (afterTriggers.Count > 0)
                    _ = FireTriggers(afterTriggers, triggerContext, frame);
            }
            catch (EmbeddedTriggerRaiseException exception)
            {
                HandleRaise(exception);
            }
        }

        void HandleRaise(EmbeddedTriggerRaiseException exception)
        {
            switch (exception.Algorithm)
            {
                case InsertConflictAlgorithm.Ignore:
                    return;
                case InsertConflictAlgorithm.Fail:
                    throw new EmbeddedConflictFailException(
                        exception,
                        GetLastInsertRowId(triggerContext));
                case InsertConflictAlgorithm.Rollback:
                    throw new EmbeddedConflictRollbackException(
                        exception,
                        GetLastInsertRowId(triggerContext));
                case InsertConflictAlgorithm.Abort:
                    throw exception;
                default:
                    throw new InvalidOperationException("REPLACE is not valid in RAISE().");
            }
        }
    }

    private ExecutionResult ExecuteInsteadOfInsert(
        InsertStatement statement,
        ViewDefinition view,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (statement.Upsert is not null)
            throw new EmbeddedSqlException("cannot UPSERT a view");

        var triggers = GetMatchingTriggers(
            context,
            statement.TableName,
            TriggerEvent.Insert,
            TriggerTiming.InsteadOf);
        if (triggers.Count == 0)
            throw new EmbeddedSqlException($"cannot modify {statement.TableName} because it is a view");

        var columns = ResolveViewColumns(view, EnterView(context, view.Name));
        ValidateViewInsertReturning(statement, columns, context);
        var targetColumns = statement.Columns ?? columns;
        var targetIndices = new int[targetColumns.Length];
        for (var index = 0; index < targetColumns.Length; index++)
        {
            targetIndices[index] = Array.FindIndex(
                columns,
                column => string.Equals(column, targetColumns[index], StringComparison.OrdinalIgnoreCase));
            if (targetIndices[index] < 0)
            {
                throw new EmbeddedSqlException(
                    $"table {statement.TableName} has no column named {targetColumns[index]}");
            }
        }

        var triggerContext = context with
        {
            TriggerConflictAlgorithm = statement.ConflictAlgorithm,
        };
        var sourceRows = statement.Source is null
            ? null
            : ExecuteQuery(statement.Source, parameters, triggerContext, outerRow: null).Rows;
        var backup = CloneTablesShallow(context.Tables);
        var returnedRows = new List<SqlValue[]>();
        var triggerInvoked = false;
        try
        {
            if (sourceRows is not null)
            {
                foreach (var values in sourceRows)
                    InsertValues(values);
            }
            else
            {
                foreach (var expressions in statement.Rows)
                {
                    var values = expressions
                        .Select(expression => Evaluate(expression, parameters, null, triggerContext))
                        .ToArray();
                    InsertValues(values);
                }
            }
        }
        catch (EmbeddedConflictFailException)
        {
            throw;
        }
        catch (EmbeddedConflictRollbackException)
        {
            RestoreTables(context.Tables, backup);
            throw;
        }
        catch (EmbeddedTriggerRaiseException exception)
            when (exception.Algorithm == InsertConflictAlgorithm.Fail)
        {
            throw new EmbeddedConflictFailException(exception, GetLastInsertRowId(context));
        }
        catch (EmbeddedTriggerRaiseException exception)
            when (exception.Algorithm == InsertConflictAlgorithm.Rollback)
        {
            RestoreTables(context.Tables, backup);
            throw new EmbeddedConflictRollbackException(exception, GetLastInsertRowId(context));
        }
        catch
        {
            RestoreTables(context.Tables, backup);
            throw;
        }

        if (statement.Returning is null)
            return new ExecutionResult([], [], 0, triggerInvoked);

        var outputColumns = BuildOutputColumns(statement.TableName, columns);
        foreach (var projection in statement.Returning)
        {
            if (projection.Expression is QualifiedStarExpression)
                throw new EmbeddedSqlException("RETURNING may not use TABLE.* wildcards");
            if (ContainsAggregate(projection.Expression) || ContainsWindowFunction(projection.Expression))
                throw new EmbeddedSqlException("aggregate and window functions are not allowed in RETURNING");
        }

        var resultRows = new List<SqlValue[]>(returnedRows.Count);
        foreach (var returnedRow in returnedRows)
        {
            var source = new SourceRow(
                columns,
                returnedRow,
                BuildQualifiedColumns(statement.TableName, columns),
                OutputColumns: outputColumns);
            var resultRow = new List<SqlValue>();
            foreach (var projection in statement.Returning)
            {
                if (projection.Expression is StarExpression)
                    resultRow.AddRange(returnedRow);
                else
                    resultRow.Add(Evaluate(projection.Expression, parameters, source, context));
            }
            resultRows.Add(resultRow.ToArray());
        }

        return new ExecutionResult(
            GetColumnNames(statement.Returning, outputColumns, outputColumns),
            resultRows,
            0,
            triggerInvoked);

        void InsertValues(IReadOnlyList<SqlValue> values)
        {
            if (values.Count != targetIndices.Length)
                throw new EmbeddedSqlException("table has a different number of columns");

            var row = Enumerable.Repeat(SqlValue.Null, columns.Length).ToArray();
            for (var index = 0; index < values.Count; index++)
                row[targetIndices[index]] = values[index];
            triggerInvoked = true;
            var ignored = FireTriggers(
                triggers,
                triggerContext,
                new TriggerRowFrame(null, null, row, null));
            if (!ignored)
                returnedRows.Add(row);
        }
    }

    private void ValidateInsertReturning(
        InsertStatement statement,
        EmbeddedTable table,
        QueryContext context)
        => ValidateTableReturning(
            statement.Returning,
            statement.TableName,
            table,
            context);

    private void ValidateTableReturning(
        IReadOnlyList<Projection>? returning,
        string tableName,
        EmbeddedTable table,
        QueryContext context)
    {
        if (returning is null)
            return;

        var row = CreateSchemaValidationRow(tableName, table, parent: null);
        foreach (var projection in returning)
        {
            if (projection.Expression is QualifiedStarExpression)
                throw new EmbeddedSqlException("RETURNING may not use TABLE.* wildcards");
            if (ContainsAggregate(projection.Expression) || ContainsWindowFunction(projection.Expression))
                throw new EmbeddedSqlException("aggregate and window functions are not allowed in RETURNING");
            ValidateExpressionSchema(
                projection.Expression,
                row,
                context,
                context.CancellationToken);
        }
    }

    private void ValidateViewInsertReturning(
        InsertStatement statement,
        string[] columns,
        QueryContext context)
    {
        if (statement.Returning is null)
            return;

        var outputColumns = BuildOutputColumns(statement.TableName, columns);
        var row = new SourceRow(
            columns,
            Enumerable.Repeat(SqlValue.Null, columns.Length).ToArray(),
            BuildQualifiedColumns(statement.TableName, columns),
            Parent: null,
            outputColumns);
        foreach (var projection in statement.Returning)
        {
            if (projection.Expression is QualifiedStarExpression)
                throw new EmbeddedSqlException("RETURNING may not use TABLE.* wildcards");
            if (ContainsAggregate(projection.Expression) || ContainsWindowFunction(projection.Expression))
                throw new EmbeddedSqlException("aggregate and window functions are not allowed in RETURNING");
            ValidateExpressionSchema(
                projection.Expression,
                row,
                context,
                context.CancellationToken);
        }
    }

    private ExecutionResult BuildConflictInsertResult(
        InsertStatement statement,
        EmbeddedTable table,
        IReadOnlyList<SqlValue[]> insertedRows,
        IReadOnlyList<long> insertedRowIds,
        SqlValue[] parameters,
        QueryContext context,
        long? lastInsertRowId,
        bool updateLastInsertRowIdPerRow = false)
    {
        if (statement.Returning is not null)
        {
            return BuildReturningResult(
                statement.Returning,
                statement.TableName,
                table,
                insertedRows,
                insertedRowIds,
                insertedRows.Count,
                insertedRows.Count > 0,
                parameters,
                context,
                lastInsertRowId,
                updateLastInsertRowIdPerRow
                    ? insertedRowIds.Cast<long?>().ToArray()
                    : null);
        }

        return new ExecutionResult([], [], insertedRows.Count, insertedRows.Count > 0)
        {
            LastInsertRowId = lastInsertRowId,
        };
    }

    private void CommitReplacement(
        QueryContext context,
        string tableName,
        EmbeddedTable table,
        SqlValue[] candidate,
        long candidateRowId,
        IReadOnlyList<TriggerDefinition> deleteTriggers,
        IReadOnlyList<TriggerDefinition> insertTriggers,
        IReadOnlyList<int>? conflictPositions = null,
        Action<IReadOnlyList<TriggerDefinition>, bool>? triggerDispatcher = null)
    {
        var orderedConflicts = conflictPositions
            ?? FindInsertUniqueConflicts(tableName, table, candidate, candidateRowId)
                .Select(conflict => conflict.RowPosition)
                .Distinct()
                .ToArray();
        var conflicts = orderedConflicts.ToHashSet();
        var conflictedRowIds = orderedConflicts
            .Select(index => table.RowIds[index])
            .ToArray();
        var conflictSet = conflicts.ToHashSet();
        var rows = new List<SqlValue[]>(table.Rows.Count - conflicts.Count + 1);
        var rowIds = new List<long>(table.RowIds.Count - conflicts.Count + 1);
        for (var index = 0; index < table.Rows.Count; index++)
        {
            if (conflictSet.Contains(index))
                continue;

            rows.Add(table.Rows[index]);
            rowIds.Add(table.RowIds[index]);
        }

        rows.Add(candidate);
        rowIds.Add(candidateRowId);
        ValidateRowIdsUnique(tableName, table, rowIds, table.RowidAliasColumnIndex);
        table.ValidateRows(tableName, rows);
        ValidateColumnUniqueConstraints(table, rows);
        ValidatePrimaryKey(tableName, table, rows);
        ValidateUniqueIndexes(tableName, table, rows);
        ValidateForeignKeysAfterInsert(context, tableName, table, [candidate], rows);

        foreach (var conflictedRowId in conflictedRowIds)
        {
            var conflictIndex = table.RowIds.IndexOf(conflictedRowId);
            if (conflictIndex < 0)
                continue;

            var deletedRow = table.Rows[conflictIndex];
            var frame = new TriggerRowFrame(
                deletedRow,
                table.HasRowid ? conflictedRowId : null,
                null,
                null);
            conflictIndex = table.RowIds.IndexOf(conflictedRowId);
            if (conflictIndex < 0)
                continue;
            var originalRows = table.Rows.ToArray();
            deletedRow = table.Rows[conflictIndex];
            table.Rows.RemoveAt(conflictIndex);
            table.RowIds.RemoveAt(conflictIndex);
            if (table.HasRowid)
                RecordBlobMutation(tableName, conflictedRowId);
            ValidateForeignKeysAfterDelete(context, tableName, table, originalRows, rows, [deletedRow]);
            if (deleteTriggers.Count > 0)
                DispatchTriggers(deleteTriggers, candidateInserted: false);
        }

        CommitInserts(context, tableName, table, [candidate], [candidateRowId]);
        if (insertTriggers.Count > 0)
            DispatchTriggers(insertTriggers, candidateInserted: true);

        void DispatchTriggers(
            IReadOnlyList<TriggerDefinition> triggers,
            bool candidateInserted)
        {
            if (triggerDispatcher is null)
                FireTriggers(triggers, context);
            else
                triggerDispatcher(triggers, candidateInserted);
        }
    }

    private IReadOnlyList<InsertUniqueConflict> FindInsertUniqueConflicts(
        string tableName,
        EmbeddedTable table,
        SqlValue[] candidate,
        long candidateRowId,
        Func<IReadOnlyList<InsertUniqueConflict>, bool>? shouldStop = null)
    {
        var conflicts = new List<InsertUniqueConflict>();
        if (table.HasRowid)
        {
            var rowPosition = table.RowIds.IndexOf(candidateRowId);
            if (rowPosition >= 0)
            {
                var aliasIndex = table.RowidAliasColumnIndex;
                var column = aliasIndex >= 0 ? table.Columns[aliasIndex] : "rowid";
                if (Add(
                        rowPosition,
                        $"UNIQUE constraint failed: {tableName}.{column}",
                        aliasIndex >= 0 ? table.RowidAliasConflictAlgorithm : null))
                {
                    return conflicts;
                }
            }
        }

        var primaryKeyAdded = false;
        if (table.WithoutRowid)
        {
            if (AddWithoutRowidPrimaryKeyConflict())
                return conflicts;
            primaryKeyAdded = true;
        }
        for (var indexPosition = table.Indexes.Count - 1; indexPosition >= 0; indexPosition--)
        {
            var index = table.Indexes[indexPosition];
            if (!primaryKeyAdded
                && table.WithoutRowid
                && table.PrimaryKeyConstraintOrdinal is { } primaryKeyOrdinal
                && index.Origin != EmbeddedIndexOrigin.Explicit
                && primaryKeyOrdinal > (index.ConstraintOrdinal ?? indexPosition))
            {
                if (AddWithoutRowidPrimaryKeyConflict())
                    return conflicts;
                primaryKeyAdded = true;
            }

            if (!index.Unique)
                continue;
            var rowPosition = table.Rows.FindIndex(row =>
                RowsConflictOnIndex(table, index, row, candidate));
            if (rowPosition < 0)
                continue;

            var message = index.Columns.Any(column => column.IsExpression)
                ? $"UNIQUE constraint failed: index '{index.Name}'"
                : "UNIQUE constraint failed: "
                    + string.Join(", ", index.Columns.Select(column => $"{tableName}.{column.Name}"));
            if (Add(rowPosition, message, index.ConflictAlgorithm))
                return conflicts;
        }
        if (!primaryKeyAdded && table.WithoutRowid && AddWithoutRowidPrimaryKeyConflict())
            return conflicts;

        return conflicts;

        bool AddWithoutRowidPrimaryKeyConflict()
        {
            if (table.PrimaryKeyColumns.Count == 0)
                return false;
            var primaryKey = table.PrimaryKeyColumns
                .Select((entry, position) => new UpsertConflictColumn(
                    table.Columns[entry.Index],
                    entry.Index,
                    table.TableLevelPrimaryKey?[position].Collation
                        ?? table.ColumnDefinitions[entry.Index].Collation))
                .ToArray();
            var rowPosition = table.Rows.FindIndex(row =>
                RowsConflictOnConstraint(row, candidate, primaryKey));
            if (rowPosition < 0)
                return false;

            return Add(
                rowPosition,
                "UNIQUE constraint failed: "
                    + string.Join(", ", primaryKey.Select(column => $"{tableName}.{column.Name}")),
                table.PrimaryKeyConflictAlgorithm);
        }

        bool Add(
            int rowPosition,
            string message,
            InsertConflictAlgorithm? algorithm)
        {
            conflicts.Add(new InsertUniqueConflict(
                rowPosition,
                new EmbeddedSqlException(message, algorithm, constraintViolation: true)));
            return shouldStop?.Invoke(conflicts) ?? false;
        }
    }

    private bool RowsConflictOnConstraint(
        SqlValue[] existing,
        SqlValue[] candidate,
        IReadOnlyList<UpsertConflictColumn> constraint)
    {
        foreach (var column in constraint)
        {
            if (existing[column.Index].Kind == SqlValueKind.Null
                || candidate[column.Index].Kind == SqlValueKind.Null
                || Compare(existing[column.Index], candidate[column.Index], column.Collation) != 0)
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsConflictAlgorithmConstraint(EmbeddedSqlException exception)
        => exception.Message.StartsWith("UNIQUE constraint failed:", StringComparison.Ordinal)
            || exception.Message.StartsWith("NOT NULL constraint failed:", StringComparison.Ordinal)
            || exception.Message.StartsWith("CHECK constraint failed:", StringComparison.Ordinal);

    // Trigger bodies can fail after row mutations are published. Keep one statement backup;
    // only a top-level FAIL policy may retain the successfully processed prefix.
    private ExecutionResult ExecuteUpsert(InsertStatement statement, SqlValue[] parameters, QueryContext context)
    {
        var backup = CloneTablesShallow(context.Tables);
        var upsertContext = context with
        {
            TriggerConflictAlgorithm = statement.ConflictAlgorithm,
        };
        var initialLastInsertRowId = GetLastInsertRowId(upsertContext);
        try
        {
            return PerformUpsertEvaluated(statement, parameters, context);
        }
        catch (EmbeddedUpsertConflictFailException)
        {
            throw;
        }
        catch (EmbeddedConflictFailException exception)
        {
            RestoreTables(context.Tables, backup);
            throw new EmbeddedSqlException(
                exception.Message,
                exception.InnerException ?? exception);
        }
        catch (EmbeddedConflictRollbackException)
        {
            RestoreTables(context.Tables, backup);
            throw;
        }
        catch
        {
            RestoreTables(context.Tables, backup);
            throw;
        }
    }

    private ExecutionResult PerformUpsertEvaluated(
        InsertStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (statement.Upsert is null)
            throw new InvalidOperationException("UPSERT execution requires an UPSERT clause.");
        if (statement.Source is not null || context.CommonTableExpressions.Count != 0)
        {
            throw new EmbeddedSqlException(
                "Managed UPSERT supports VALUES rows only and does not support INSERT ... SELECT or CTE sources.");
        }
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");

        var triggerConflictAlgorithm = statement.ConflictAlgorithm;
        context = context with
        {
            TriggerConflictAlgorithm = triggerConflictAlgorithm,
            PreserveUpsertFail = true,
        };
        var conflictTarget = ResolveUpsertConflictTarget(statement.TableName, table, statement.Upsert);
        var insertPlan = PrepareInsert(statement, table, context);
        var updateAction = statement.Upsert.Action as DoUpdateUpsertAction;
        UpdatePlan? updatePlan = null;
        if (updateAction is null && statement.Upsert.Action is not DoNothingUpsertAction)
            throw new InvalidOperationException("Unknown UPSERT action.");

        if (updateAction is not null)
        {
            var updateStatement = new UpdateStatement(statement.TableName, updateAction.Assignments, Where: null);
            updatePlan = PrepareUpdate(updateStatement, table, context);
            ValidateUpsertUpdateExpressions(statement.TableName, updateAction.Assignments, updateAction.Where);
        }

        var beforeInsertTriggers = GetMatchingTriggers(
            context,
            statement.TableName,
            TriggerEvent.Insert,
            TriggerTiming.Before);
        var afterInsertTriggers = GetMatchingTriggers(
            context,
            statement.TableName,
            TriggerEvent.Insert,
            TriggerTiming.After);
        var beforeDeleteTriggers = context.RecursiveTriggersEnabled
            ? GetMatchingTriggers(
                context,
                statement.TableName,
                TriggerEvent.Delete,
                TriggerTiming.Before)
            : [];
        var afterDeleteTriggers = context.RecursiveTriggersEnabled
            ? GetMatchingTriggers(
                context,
                statement.TableName,
                TriggerEvent.Delete,
                TriggerTiming.After)
            : [];
        var updatedColumns = updateAction?.Assignments
            .Select(assignment => assignment.Column)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var beforeUpdateTriggers = updateAction is null
            ? []
            : GetMatchingTriggers(
                context,
                statement.TableName,
                TriggerEvent.Update,
                TriggerTiming.Before,
                updatedColumns);
        var afterUpdateTriggers = updateAction is null
            ? []
            : GetMatchingTriggers(
                context,
                statement.TableName,
                TriggerEvent.Update,
                TriggerTiming.After,
                updatedColumns);
        var affectedRows = new List<SqlValue[]>();
        var affectedRowIds = new List<long>();
        var affectedLastInsertRowIds = new List<long?>();
        var insertTriggers = GetMatchingTriggers(context, statement.TableName, TriggerEvent.Insert);
        var updateTriggers = GetMatchingTriggers(context, statement.TableName, TriggerEvent.Update);
        var deleteTriggers = context.RecursiveTriggersEnabled
            ? GetMatchingTriggers(context, statement.TableName, TriggerEvent.Delete)
            : Array.Empty<TriggerDefinition>();
        long? lastInsertRowId = null;
        foreach (var values in statement.Rows)
        {
            SynchronizeInsertAllocation(insertPlan, table);
            var allocationSnapshot = CaptureInsertAllocation(insertPlan);
            SqlValue[]? candidate = null;
            var candidateRowId = 0L;
            try
            {
                (candidate, candidateRowId) = BuildInsertRow(
                    statement,
                    table,
                    insertPlan,
                    values,
                    parameters,
                    context,
                    allowExistingRowid: true);
                table.ValidateRows(statement.TableName, [candidate]);
                ValidatePrimaryKey(statement.TableName, table, [candidate]);
            }
            catch (EmbeddedSqlException exception) when (IsConflictAlgorithmConstraint(exception))
            {
                if (HandleInsertConflict(
                        exception,
                        candidate,
                        candidateRowId,
                        allocationSnapshot,
                        uniqueConflicts: null))
                    continue;
                throw;
            }
            catch (Exception exception) when (
                lastInsertRowId.HasValue
                && exception is not OperationCanceledException
                && exception is not EmbeddedConflictFailException
                && exception is not EmbeddedConflictRollbackException
                && exception is not EmbeddedStatementAbortException
                && exception is not EmbeddedStatementFailureException)
            {
                throw new EmbeddedStatementFailureException(exception, lastInsertRowId.Value);
            }

            var conflictPosition = PreserveLastInsertRowIdOnFailure(() =>
                FindUpsertConflictPosition(
                    table,
                    conflictTarget,
                    candidate,
                    candidateRowId,
                    table.Rows,
                    table.RowIds));

            if (conflictPosition < 0)
            {
                var uniqueConflicts = PreserveLastInsertRowIdOnFailure(() =>
                    FindInsertUniqueConflicts(
                        statement.TableName,
                        table,
                        candidate,
                        candidateRowId,
                        conflicts =>
                        {
                            if (statement.ConflictAlgorithm == InsertConflictAlgorithm.Replace)
                                return false;
                            if (statement.ConflictAlgorithm is not null)
                                return true;
                            return conflicts.Any(conflict =>
                                (conflict.Exception.ConflictAlgorithm ?? InsertConflictAlgorithm.Abort)
                                != InsertConflictAlgorithm.Replace);
                        }));
                if (uniqueConflicts.Count > 0
                    && HandleInsertConflict(
                        uniqueConflicts[0].Exception,
                        candidate,
                        candidateRowId,
                        allocationSnapshot,
                        uniqueConflicts))
                {
                    continue;
                }

                try
                {
                    CommitInserts(
                        context,
                        statement.TableName,
                        table,
                        [candidate],
                        [candidateRowId]);
                }
                catch (EmbeddedSqlException exception) when (IsConflictAlgorithmConstraint(exception))
                {
                    if (HandleInsertConflict(exception, candidate, candidateRowId, allocationSnapshot))
                        continue;
                    throw;
                }
                catch (Exception exception) when (
                    lastInsertRowId.HasValue
                    && exception is not OperationCanceledException
                    && exception is not EmbeddedConflictFailException
                    && exception is not EmbeddedConflictRollbackException
                    && exception is not EmbeddedStatementAbortException
                    && exception is not EmbeddedStatementFailureException)
                {
                    throw new EmbeddedStatementFailureException(exception, lastInsertRowId.Value);
                }

                affectedRows.Add(candidate);
                affectedRowIds.Add(candidateRowId);
                if (table.HasRowid)
                {
                    lastInsertRowId = candidateRowId;
                    SetLastInsertRowId(context, candidateRowId);
                    context = context with { LastInsertRowId = candidateRowId };
                }
                affectedLastInsertRowIds.Add(context.LastInsertRowId);
                FireMutationTriggers(insertTriggers, triggerConflictAlgorithm);
                continue;
            }

            RestoreInsertAllocation(insertPlan, allocationSnapshot);
            if (updateAction is null)
                continue;

            try
            {
                var updateContext = context with
                {
                    TriggerConflictAlgorithm = InsertConflictAlgorithm.Abort,
                    PreserveUpsertFail = false,
                };
                var original = table.Rows[conflictPosition];
                var originalRowId = table.RowIds[conflictPosition];
                var source = CreateUpsertSourceRow(
                    statement.TableName,
                    table,
                    original,
                    originalRowId,
                    candidate);
                if (updateAction.Where is not null
                    && !IsTrue(Evaluate(updateAction.Where, parameters, source, updateContext)))
                {
                    continue;
                }

                var (updated, updatedRowId) = BuildUpsertUpdatedRow(
                    statement.TableName,
                    table,
                    updatePlan!,
                    original,
                    originalRowId,
                    source,
                    parameters,
                    updateContext);
                var updatedRows = new List<SqlValue[]>(table.Rows);
                updatedRows[conflictPosition] = updated;
                var updatedRowIds = new List<long>(table.RowIds);
                if (table.HasRowid && conflictPosition < updatedRowIds.Count)
                    updatedRowIds[conflictPosition] = updatedRowId;

                ValidateRowIdsUnique(statement.TableName, table, updatedRowIds, updatePlan!.AliasIndex);
                table.ValidateRows(statement.TableName, updatedRows);

                // SQLite validates the DO UPDATE result against the table's CHECK
                // constraints exactly as it does for a plain UPDATE, after NOT NULL and
                // before uniqueness. Without this the conflict branch could store a row
                // that violates its own declared schema. The result's rowid is used, not
                // the conflicting row's, because a DO UPDATE may reassign it.
                ValidateCheckConstraints(
                    statement.TableName,
                    table,
                    updated,
                    updatedRowId,
                    parameters,
                    updateContext);
                ValidateColumnUniqueConstraints(table, updatedRows);
                ValidatePrimaryKey(statement.TableName, table, updatedRows);
                ValidateUniqueIndexes(statement.TableName, table, updatedRows);
                var originalRows = table.Rows.Select(row => row.ToArray()).ToArray();
                MarkTriggerStatementRollbackRequirement(
                    updateContext,
                    table,
                    TriggerMutationKind.Update,
                    updatePlan);
                ApplyUpsertRows(table, updatedRows, updatedRowIds);
                updateContext.ReportRowChange(
                    SqliteChangeOperation.Update,
                    statement.TableName,
                    table,
                    updatedRowIds[conflictPosition]);
                ValidateForeignKeysAfterUpdate(
                    updateContext,
                    statement.TableName,
                    table,
                    originalRows,
                    updatedRows,
                    updatePlan!,
                    [conflictPosition]);

                affectedRows.Add(updated);
                affectedRowIds.Add(updatedRowId);
                affectedLastInsertRowIds.Add(context.LastInsertRowId);
                FireMutationTriggers(updateTriggers, InsertConflictAlgorithm.Abort);
            }
            catch (EmbeddedUpsertConflictFailException)
            {
                throw;
            }
            catch (EmbeddedConflictFailException exception)
            {
                var failure = new EmbeddedSqlException(
                    exception.Message,
                    exception.InnerException ?? exception);
                if (lastInsertRowId is { } insertedRowId)
                    throw new EmbeddedStatementAbortException(failure, insertedRowId);
                throw failure;
            }
            catch (EmbeddedSqlException exception) when (
                lastInsertRowId.HasValue
                && exception is not EmbeddedConflictFailException
                && exception is not EmbeddedConflictRollbackException
                && exception is not EmbeddedStatementAbortException)
            {
                throw new EmbeddedStatementAbortException(exception, lastInsertRowId.Value);
            }
            catch (Exception exception) when (
                lastInsertRowId.HasValue
                && exception is not OperationCanceledException
                && exception is not EmbeddedConflictFailException
                && exception is not EmbeddedConflictRollbackException
                && exception is not EmbeddedStatementAbortException
                && exception is not EmbeddedStatementFailureException)
            {
                throw new EmbeddedStatementFailureException(exception, lastInsertRowId.Value);
            }
        }

        try
        {
            return BuildUpsertReturningResult(
                statement,
                table,
                affectedRows,
                affectedRowIds,
                parameters,
                context,
                rowsAffected: affectedRows.Count,
                changed: affectedRows.Count > 0,
                lastInsertRowId: lastInsertRowId,
                affectedLastInsertRowIds: affectedLastInsertRowIds);
        }
        catch (EmbeddedSqlException exception) when (
            lastInsertRowId.HasValue
            && exception is not EmbeddedConflictFailException
            && exception is not EmbeddedConflictRollbackException
            && exception is not EmbeddedStatementAbortException)
        {
            throw new EmbeddedStatementAbortException(exception, lastInsertRowId.Value);
        }
        catch (Exception exception) when (
            lastInsertRowId.HasValue
            && exception is not OperationCanceledException
            && exception is not EmbeddedConflictFailException
            && exception is not EmbeddedConflictRollbackException
            && exception is not EmbeddedStatementAbortException
            && exception is not EmbeddedStatementFailureException)
        {
            throw new EmbeddedStatementFailureException(exception, lastInsertRowId.Value);
        }

        bool HandleInsertConflict(
            EmbeddedSqlException exception,
            SqlValue[]? conflictingCandidate,
            long conflictingRowId,
            InsertAllocationSnapshot? allocationSnapshot,
            IReadOnlyList<InsertUniqueConflict>? uniqueConflicts = null)
        {
            var algorithm = statement.ConflictAlgorithm
                ?? exception.ConflictAlgorithm
                ?? InsertConflictAlgorithm.Abort;
            switch (algorithm)
            {
                case InsertConflictAlgorithm.Ignore:
                    RestoreInsertAllocation(insertPlan, allocationSnapshot);
                    return true;
                case InsertConflictAlgorithm.Replace
                    when conflictingCandidate is not null
                        && exception.Message.StartsWith("UNIQUE constraint failed:", StringComparison.Ordinal):
                    IReadOnlyList<int>? replacementConflicts = null;
                    if (statement.ConflictAlgorithm is null && uniqueConflicts is not null)
                    {
                        var nonReplace = uniqueConflicts.FirstOrDefault(conflict =>
                            (conflict.Exception.ConflictAlgorithm ?? InsertConflictAlgorithm.Abort)
                            != InsertConflictAlgorithm.Replace);
                        if (nonReplace is not null)
                        {
                            return HandleInsertConflict(
                                nonReplace.Exception,
                                conflictingCandidate,
                                conflictingRowId,
                                allocationSnapshot);
                        }

                        replacementConflicts = uniqueConflicts
                            .Select(conflict => conflict.RowPosition)
                            .Distinct()
                            .ToArray();
                    }

                    EnsureTriggersMayFire(deleteTriggers);
                    EnsureTriggersMayFire(insertTriggers);
                    PreserveLastInsertRowIdOnFailure(() =>
                    {
                        ExecuteReplacement();
                        return true;
                    });
                    affectedRows.Add(conflictingCandidate);
                    affectedRowIds.Add(conflictingRowId);
                    if (table.HasRowid)
                    {
                        lastInsertRowId = conflictingRowId;
                        context = context with { LastInsertRowId = conflictingRowId };
                    }
                    affectedLastInsertRowIds.Add(context.LastInsertRowId);
                    return true;

                    void ExecuteReplacement()
                    {
                        CommitReplacement(
                            context,
                            statement.TableName,
                            table,
                            conflictingCandidate,
                            conflictingRowId,
                            deleteTriggers,
                            insertTriggers,
                            replacementConflicts,
                            (triggers, candidateInserted) => FireUpsertTriggers(
                                triggers,
                                candidateInserted && table.HasRowid
                                    ? conflictingRowId
                                    : lastInsertRowId,
                                triggerConflictAlgorithm));
                    }
                case InsertConflictAlgorithm.Fail:
                    if (affectedRows.Count == 0
                        && !(context.InsideTrigger && context.PreserveUpsertFail))
                    {
                        throw exception;
                    }
                    throw new EmbeddedUpsertConflictFailException(
                        exception,
                        lastInsertRowId ?? context.LastInsertRowId);
                case InsertConflictAlgorithm.Rollback:
                    throw new EmbeddedConflictRollbackException(exception, lastInsertRowId);
                case InsertConflictAlgorithm.Abort:
                case InsertConflictAlgorithm.Replace:
                    if (lastInsertRowId is { } insertedRowId)
                        throw new EmbeddedStatementAbortException(exception, insertedRowId);
                    throw exception;
                default:
                    throw new InvalidOperationException("Unknown INSERT conflict algorithm.");
            }
        }

        void FireMutationTriggers(
            IReadOnlyList<TriggerDefinition> triggers,
            InsertConflictAlgorithm? inheritedConflictAlgorithm)
            => FireUpsertTriggers(triggers, lastInsertRowId, inheritedConflictAlgorithm);

        void FireUpsertTriggers(
            IReadOnlyList<TriggerDefinition> triggers,
            long? failureLastInsertRowId,
            InsertConflictAlgorithm? inheritedConflictAlgorithm)
        {
            EnsureTriggersMayFire(triggers);
            if (triggers.Count == 0)
                return;

            try
            {
                var mutationContext = failureLastInsertRowId is { } insertedRowId
                    ? context with { LastInsertRowId = insertedRowId }
                    : context;
                FireTriggers(
                    triggers,
                    mutationContext,
                    triggerConflictAlgorithm: inheritedConflictAlgorithm);
            }
            catch (EmbeddedConflictRollbackException exception)
            {
                if (failureLastInsertRowId is not { } insertedRowId)
                    throw;
                throw new EmbeddedConflictRollbackException(
                    new EmbeddedSqlException(
                        exception.Message,
                        exception.InnerException ?? exception),
                    insertedRowId);
            }
            catch (EmbeddedConflictFailException exception)
            {
                var failure = new EmbeddedSqlException(
                    exception.Message,
                    exception.InnerException ?? exception);
                if (inheritedConflictAlgorithm != InsertConflictAlgorithm.Abort)
                {
                    throw new EmbeddedUpsertConflictFailException(
                        failure,
                        failureLastInsertRowId ?? context.LastInsertRowId);
                }
                if (failureLastInsertRowId is { } insertedRowId)
                    throw new EmbeddedStatementAbortException(failure, insertedRowId);
                throw failure;
            }
            catch (EmbeddedStatementAbortException exception)
            {
                if (failureLastInsertRowId is not { } insertedRowId)
                    throw;
                throw new EmbeddedStatementAbortException(
                    new EmbeddedSqlException(
                        exception.Message,
                        exception.InnerException ?? exception),
                    insertedRowId);
            }
            catch (EmbeddedSqlException exception)
            {
                if (inheritedConflictAlgorithm == InsertConflictAlgorithm.Fail
                    && IsConflictAlgorithmConstraint(exception))
                {
                    throw new EmbeddedUpsertConflictFailException(
                        exception,
                        failureLastInsertRowId ?? context.LastInsertRowId);
                }
                if (failureLastInsertRowId is { } insertedRowId)
                    throw new EmbeddedStatementAbortException(exception, insertedRowId);
                throw;
            }
            catch (Exception exception) when (exception is not OperationCanceledException)
            {
                if (failureLastInsertRowId is { } insertedRowId)
                    throw new EmbeddedStatementFailureException(exception, insertedRowId);
                throw;
            }
        }

        void EnsureTriggersMayFire(IReadOnlyList<TriggerDefinition> triggers)
        {
            if (triggers.Count > 0 && context.InsideTrigger)
            {
                throw new EmbeddedSqlException(
                    $"cannot modify {statement.TableName} within a trigger body: recursive triggers are not supported");
            }
        }

        T PreserveLastInsertRowIdOnFailure<T>(Func<T> operation)
        {
            try
            {
                return operation();
            }
            catch (Exception exception) when (
                exception is EmbeddedConflictFailException
                    or EmbeddedConflictRollbackException
                    or EmbeddedStatementAbortException
                    or EmbeddedStatementFailureException)
            {
                throw;
            }
            catch (EmbeddedSqlException exception) when (lastInsertRowId.HasValue)
            {
                throw new EmbeddedStatementAbortException(exception, lastInsertRowId.Value);
            }
            catch (Exception exception) when (
                lastInsertRowId.HasValue
                && exception is not OperationCanceledException)
            {
                throw new EmbeddedStatementFailureException(exception, lastInsertRowId.Value);
            }
        }
    }

    private void ApplyUpsertRows(EmbeddedTable table, List<SqlValue[]> rows, List<long> rowIds)
    {
        table.Rows.Clear();
        table.Rows.AddRange(rows);
        table.RowIds.Clear();
        table.RowIds.AddRange(rowIds);
        SortWithoutRowid(table);
    }

    private ExecutionResult BuildUpsertReturningResult(
        InsertStatement statement,
        EmbeddedTable table,
        IReadOnlyList<SqlValue[]> affectedRows,
        IReadOnlyList<long> affectedRowIds,
        SqlValue[] parameters,
        QueryContext context,
        int rowsAffected,
        bool changed,
        long? lastInsertRowId,
        IReadOnlyList<long?> affectedLastInsertRowIds)
    {
        if (statement.Returning is null)
        {
            return new ExecutionResult([], [], rowsAffected, changed)
            {
                LastInsertRowId = lastInsertRowId,
            };
        }

        return BuildReturningResult(
            statement.Returning,
            statement.TableName,
            table,
            affectedRows,
            affectedRowIds,
            rowsAffected,
            changed,
            parameters,
            context,
            lastInsertRowId,
            affectedLastInsertRowIds);
    }

    private UpsertConflictTarget ResolveUpsertConflictTarget(
        string tableName,
        EmbeddedTable table,
        UpsertClause upsert)
    {
        var target = upsert.Target;
        if (target.Count == 0)
        {
            // SQLite treats an omitted conflict target as "any uniqueness constraint", so the
            // action runs for whichever PRIMARY KEY or UNIQUE index the candidate row violates.
            if (upsert.TargetWhere is not null)
                throw new EmbeddedSqlException("ON CONFLICT clause requires a conflict target before WHERE.");

            return new UpsertConflictTarget(Index: null, Columns: null, CatchesAllUniqueConstraints: true);
        }

        UpsertConflictTarget? constraintMatch = null;
        var constraintOrdinal = int.MinValue;
        for (var position = table.Indexes.Count - 1; position >= 0; position--)
        {
            var index = table.Indexes[position];
            if (!index.Unique
                || !IndexExpressionSemantics.ExpressionsEqual(upsert.TargetWhere, index.Where)
                || !UpsertTargetMatches(table, target, index.Columns))
            {
                continue;
            }

            if (index.Origin == EmbeddedIndexOrigin.Explicit)
                return new UpsertConflictTarget(index, Columns: null, CatchesAllUniqueConstraints: false);

            var ordinal = index.ConstraintOrdinal ?? position;
            if (constraintMatch is null || ordinal > constraintOrdinal)
            {
                constraintMatch = new UpsertConflictTarget(
                    index,
                    Columns: null,
                    CatchesAllUniqueConstraints: false);
                constraintOrdinal = ordinal;
            }
        }

        UpsertConflictTarget? primaryKeyMatch = null;
        if (upsert.TargetWhere is null
            && table.PrimaryKeyColumns.Count > 0
            && (!table.HasRowidAlias || target.All(term => term.Collation is null)))
        {
            var columns = table.PrimaryKeyColumns
                .Select((entry, position) => new UpsertConflictColumn(
                    table.Columns[entry.Index],
                    entry.Index,
                    table.TableLevelPrimaryKey?[position].Collation
                        ?? table.ColumnDefinitions[entry.Index].Collation))
                .ToArray();
            if (UpsertTargetMatches(target, columns))
                primaryKeyMatch = new UpsertConflictTarget(
                    Index: null,
                    Columns: columns,
                    CatchesAllUniqueConstraints: false);
        }

        if (primaryKeyMatch is not null
            && table.WithoutRowid
            && table.PrimaryKeyConstraintOrdinal is { } primaryKeyOrdinal
            && primaryKeyOrdinal > constraintOrdinal)
        {
            return primaryKeyMatch;
        }
        if (constraintMatch is not null)
            return constraintMatch;
        if (primaryKeyMatch is not null)
            return primaryKeyMatch;

        throw new EmbeddedSqlException(
            $"ON CONFLICT clause does not match any PRIMARY KEY or UNIQUE constraint on table {tableName}.");
    }

    private static void ValidateUpsertTargetQualifiers(
        Expression? expression,
        string tableName)
    {
        if (expression is null)
            return;
        foreach (var column in EnumerateTriggerColumnExpressions(expression))
        {
            if (column.Qualifier is not null
                && !string.Equals(column.Qualifier, tableName, StringComparison.OrdinalIgnoreCase))
            {
                throw new EmbeddedSqlException($"no such column: {column.Name}");
            }
        }
    }

    private static bool UpsertTargetMatches(
        EmbeddedTable table,
        IReadOnlyList<UpsertTargetColumn> target,
        IReadOnlyList<EmbeddedIndexColumn> constraint)
    {
        return UpsertTargetTermsMatch(target, constraint, (targetTerm, indexTerm) =>
        {
            if (targetTerm.IsExpression != indexTerm.IsExpression)
                return false;
            if (targetTerm.IsExpression)
            {
                if (!IndexExpressionSemantics.ExpressionsEqual(targetTerm.Expression, indexTerm.Expression))
                    return false;
            }
            else if (!string.Equals(targetTerm.Name, indexTerm.Name, StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            return targetTerm.Collation is null
                || string.Equals(
                    targetTerm.Collation,
                    IndexExpressionSemantics.GetCollationName(table, indexTerm),
                    StringComparison.OrdinalIgnoreCase);
        });
    }

    private static bool UpsertTargetMatches(
        IReadOnlyList<UpsertTargetColumn> target,
        IReadOnlyList<UpsertConflictColumn> constraint)
    {
        return UpsertTargetTermsMatch(target, constraint, static (targetTerm, constraintTerm) =>
        {
            return !targetTerm.IsExpression
                && string.Equals(targetTerm.Name, constraintTerm.Name, StringComparison.OrdinalIgnoreCase)
                && (targetTerm.Collation is null
                    || string.Equals(
                        targetTerm.Collation,
                        constraintTerm.Collation ?? "BINARY",
                        StringComparison.OrdinalIgnoreCase));
        });
    }

    private static bool UpsertTargetTermsMatch<TConstraint>(
        IReadOnlyList<UpsertTargetColumn> target,
        IReadOnlyList<TConstraint> constraint,
        Func<UpsertTargetColumn, TConstraint, bool> termsMatch)
    {
        if (target.Count != constraint.Count)
            return false;

        var assignedTargets = Enumerable.Repeat(-1, constraint.Count).ToArray();
        for (var targetPosition = 0; targetPosition < target.Count; targetPosition++)
        {
            if (!TryAssign(targetPosition, new bool[constraint.Count]))
                return false;
        }

        return true;

        bool TryAssign(int targetPosition, bool[] visited)
        {
            for (var constraintPosition = 0; constraintPosition < constraint.Count; constraintPosition++)
            {
                if (visited[constraintPosition]
                    || !termsMatch(target[targetPosition], constraint[constraintPosition]))
                {
                    continue;
                }

                visited[constraintPosition] = true;
                if (assignedTargets[constraintPosition] < 0
                    || TryAssign(assignedTargets[constraintPosition], visited))
                {
                    assignedTargets[constraintPosition] = targetPosition;
                    return true;
                }
            }

            return false;
        }
    }

    private int FindUpsertConflictPosition(
        EmbeddedTable table,
        UpsertConflictTarget target,
        SqlValue[] candidate,
        long candidateRowId,
        IReadOnlyList<SqlValue[]> rows,
        IReadOnlyList<long> rowIds)
    {
        if (target.CatchesAllUniqueConstraints)
        {
            var conflicts = FindInsertUniqueConflicts(
                table.Name,
                table,
                candidate,
                candidateRowId,
                _ => true);
            return conflicts.Count == 0 ? -1 : conflicts[0].RowPosition;
        }

        if (target.Index is { } index)
        {
            if (!IndexExpressionSemantics.Qualifies(
                    index,
                    table,
                    candidate,
                    rowId: null,
                    EvaluateIndexExpression))
            {
                return -1;
            }

            for (var rowIndex = 0; rowIndex < rows.Count; rowIndex++)
            {
                if (RowsConflictOnIndex(table, index, rows[rowIndex], candidate))
                    return rowIndex;
            }

            return -1;
        }

        var columns = target.Columns
            ?? throw new InvalidOperationException("UPSERT conflict target has no key metadata.");
        foreach (var column in columns)
        {
            if (candidate[column.Index].Kind == SqlValueKind.Null)
                return -1;
        }

        for (var rowIndex = 0; rowIndex < rows.Count; rowIndex++)
        {
            var matches = true;
            foreach (var column in columns)
            {
                if (Compare(rows[rowIndex][column.Index], candidate[column.Index], column.Collation) != 0)
                {
                    matches = false;
                    break;
                }
            }

            if (matches)
                return rowIndex;
        }

        return -1;
    }

    private (SqlValue[] Row, long RowId) BuildUpsertUpdatedRow(
        string tableName,
        EmbeddedTable table,
        UpdatePlan plan,
        SqlValue[] original,
        long rowId,
        SourceRow source,
        SqlValue[] parameters,
        QueryContext context)
    {
        var updated = original.ToArray();
        var assignmentValues = new Dictionary<Expression, SqlValue[]>(ReferenceEqualityComparer.Instance);
        foreach (var assignment in plan.ColumnAssignments)
        {
            updated[assignment.Index] = EvaluateAssignmentValue(
                assignment,
                assignmentValues,
                parameters,
                source,
                context);
        }

        table.ApplyAffinities(updated);

        // A DO UPDATE may assign the rowid pseudo-column or the INTEGER PRIMARY KEY
        // alias, which moves the conflicting row exactly as the equivalent UPDATE would.
        var updatedRowId = rowId;
        if (plan.RowidAssignment is not null)
        {
            updatedRowId = CoerceRowidOrThrow(EvaluateAssignmentValue(
                plan.RowidAssignment,
                assignmentValues,
                parameters,
                source,
                context));
        }
        else if (plan.AliasIndex >= 0)
            updatedRowId = CoerceRowidOrThrow(updated[plan.AliasIndex]);

        if (plan.AliasIndex >= 0)
            updated[plan.AliasIndex] = SqlValue.Integer(updatedRowId);
        ComputeGeneratedColumns(table, tableName, updated, parameters, context);
        return (updated, updatedRowId);
    }

    private static SourceRow CreateUpsertSourceRow(
        string tableName,
        EmbeddedTable table,
        SqlValue[] target,
        long targetRowId,
        SqlValue[] excluded)
    {
        var values = new SqlValue[target.Length + excluded.Length];
        Array.Copy(target, values, target.Length);
        Array.Copy(excluded, 0, values, target.Length, excluded.Length);
        var qualified = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        for (var index = 0; index < table.Columns.Length; index++)
        {
            qualified.Add($"{tableName}.{table.Columns[index]}", index);
            qualified.Add($"excluded.{table.Columns[index]}", table.Columns.Length + index);
        }

        return new SourceRow(
            table.Columns,
            values,
            qualified,
            RowId: table.HasRowid ? targetRowId : null,
            RowIdQualifier: tableName,
            ColumnDefinitions: table.ColumnDefinitions
                .Cast<EmbeddedColumn?>()
                .Concat(table.ColumnDefinitions)
                .ToArray());
    }

    private void ValidateUpsertUpdateExpressions(
        string tableName,
        IReadOnlyList<ColumnAssignment> assignments,
        Expression? where)
    {
        foreach (var assignment in assignments)
            ValidateUpsertUpdateExpression(tableName, assignment.Value);

        if (where is not null)
            ValidateUpsertUpdateExpression(tableName, where);
    }

    private void ValidateUpsertUpdateExpression(string tableName, Expression expression)
    {
        if (ContainsAggregate(expression)
            || ContainsWindowFunction(expression))
        {
            throw new EmbeddedSqlException(
                "Managed UPSERT DO UPDATE does not support aggregate or window expressions.");
        }

        switch (expression)
        {
            case LiteralExpression:
            case ParameterExpression:
                return;
            case RowValueExpression rowValue:
                foreach (var value in rowValue.Values)
                    ValidateUpsertUpdateExpression(tableName, value);
                return;
            case ColumnExpression column:
                {
                    var separator = column.Name.IndexOf('.');
                    if (separator < 0)
                        return;

                    var qualifier = column.Name[..separator];
                    var name = column.Name[(separator + 1)..];
                    if (qualifier.Equals("excluded", StringComparison.OrdinalIgnoreCase)
                        && EmbeddedTable.IsRowidAliasName(name))
                    {
                        throw new EmbeddedSqlException(
                            "Managed UPSERT DO UPDATE does not support excluded.rowid references.");
                    }

                    if (!qualifier.Equals("excluded", StringComparison.OrdinalIgnoreCase)
                        && !qualifier.Equals(tableName, StringComparison.OrdinalIgnoreCase))
                    {
                        throw new EmbeddedSqlException(
                            $"no such table: {qualifier}");
                    }

                    return;
                }
            case ScalarSubqueryExpression or ExistsExpression or InSubqueryExpression:
                throw new EmbeddedSqlException(
                    "Managed UPSERT DO UPDATE does not support subquery expressions.");
            case FunctionExpression function:
                foreach (var argument in function.Arguments)
                    ValidateUpsertUpdateExpression(tableName, argument);
                return;
            case CollationExpression collation:
                ValidateUpsertUpdateExpression(tableName, collation.Expression);
                return;
            case CastExpression cast:
                ValidateUpsertUpdateExpression(tableName, cast.Expression);
                return;
            case CaseExpression @case:
                if (@case.Operand is not null)
                    ValidateUpsertUpdateExpression(tableName, @case.Operand);
                foreach (var clause in @case.Clauses)
                {
                    ValidateUpsertUpdateExpression(tableName, clause.When);
                    ValidateUpsertUpdateExpression(tableName, clause.Then);
                }
                if (@case.Else is not null)
                    ValidateUpsertUpdateExpression(tableName, @case.Else);
                return;
            case LikeExpression like:
                ValidateUpsertUpdateExpression(tableName, like.Value);
                ValidateUpsertUpdateExpression(tableName, like.Pattern);
                if (like.Escape is not null)
                    ValidateUpsertUpdateExpression(tableName, like.Escape);
                return;
            case GlobExpression glob:
                ValidateUpsertUpdateExpression(tableName, glob.Value);
                ValidateUpsertUpdateExpression(tableName, glob.Pattern);
                return;
            case InExpression @in:
                ValidateUpsertUpdateExpression(tableName, @in.Value);
                foreach (var value in @in.Values)
                    ValidateUpsertUpdateExpression(tableName, value);
                return;
            case BetweenExpression between:
                ValidateUpsertUpdateExpression(tableName, between.Value);
                ValidateUpsertUpdateExpression(tableName, between.Lower);
                ValidateUpsertUpdateExpression(tableName, between.Upper);
                return;
            case UnaryExpression unary:
                ValidateUpsertUpdateExpression(tableName, unary.Operand);
                return;
            case BinaryExpression binary:
                ValidateUpsertUpdateExpression(tableName, binary.Left);
                ValidateUpsertUpdateExpression(tableName, binary.Right);
                return;
            case StarExpression or QualifiedStarExpression:
                throw new EmbeddedSqlException("row value misused");
            default:
                throw new EmbeddedSqlException(
                    $"Managed UPSERT DO UPDATE does not support {expression.GetType().Name} expressions.");
        }
    }

    private sealed record UpsertConflictColumn(string Name, int Index, string? Collation);

    private sealed record InsertUniqueConflict(
        int RowPosition,
        EmbeddedSqlException Exception);

    private sealed record UpsertConflictTarget(
        EmbeddedIndex? Index,
        IReadOnlyList<UpsertConflictColumn>? Columns,
        bool CatchesAllUniqueConstraints);

    private static InsertAllocationSnapshot? CaptureInsertAllocation(InsertPlan plan)
    {
        plan.LastAddedRowId = null;
        return plan.AutoIncrement is null
            ? new InsertAllocationSnapshot(plan.AnyRow, plan.LargestRowId)
            : null;
    }

    private static void RestoreInsertAllocation(InsertPlan plan, InsertAllocationSnapshot? snapshot)
    {
        if (snapshot is not { } value)
            return;

        plan.AnyRow = value.AnyRow;
        plan.LargestRowId = value.LargestRowId;
        if (plan.LastAddedRowId is { } rowId && !plan.Used.Remove(rowId))
            throw new InvalidOperationException("The skipped UPSERT rowid allocation was lost.");
        plan.LastAddedRowId = null;
    }

    private static void SynchronizeInsertAllocation(InsertPlan plan, EmbeddedTable table)
    {
        if (plan.AutoIncrement is null)
        {
            plan.Used.Clear();
            plan.Used.UnionWith(table.RowIds);
            plan.AnyRow = table.RowIds.Count > 0;
            plan.LargestRowId = plan.AnyRow ? table.RowIds.Max() : long.MinValue;
            return;
        }

        plan.Used.UnionWith(table.RowIds);
        if (table.RowIds.Count == 0)
            return;
        plan.AnyRow = true;
        plan.LargestRowId = Math.Max(plan.LargestRowId, table.RowIds.Max());
    }

    private sealed record InsertAllocationSnapshot(
        bool AnyRow,
        long LargestRowId);

    // Materializes every generated column into the row in dependency order, applying the
    // declared-type affinity and enforcing NOT NULL with a table-qualified message. The
    // generation expression sees the row's stored values but never a rowid pseudo-column.
    private void ComputeGeneratedColumns(
        EmbeddedTable table,
        string tableName,
        SqlValue[] row,
        SqlValue[] parameters,
        QueryContext context,
        bool virtualOnly = false)
    {
        if (!table.HasGeneratedColumns)
            return;

        var source = new SourceRow(
            table.Columns,
            row,
            ColumnDefinitions: table.ColumnDefinitions);
        foreach (var columnIndex in table.GeneratedColumnOrder)
        {
            var column = table.ColumnDefinitions[columnIndex];
            if (virtualOnly && column.GeneratedStored)
                continue;

            var value = table.ApplyColumnAffinity(
                column,
                Evaluate(column.GenerationExpression!, parameters, source, context));
            row[columnIndex] = value;
            if (column.NotNull && value.Kind == SqlValueKind.Null)
            {
                throw new EmbeddedSqlException(
                    $"NOT NULL constraint failed: {tableName}.{column.Name}",
                    column.NotNullConflictAlgorithm);
            }
        }
    }

    internal static void RecomputeVirtualGeneratedColumns(
        EmbeddedTable table,
        string tableName,
        SqlValue[] row)
    {
        if (!table.HasGeneratedColumns)
            return;

        var evaluator = new EmbeddedDatabase();
        evaluator.ComputeGeneratedColumns(
            table,
            tableName,
            row,
            [],
            new QueryContext(
                new Dictionary<string, EmbeddedTable>(StringComparer.OrdinalIgnoreCase)
                {
                    [tableName] = table,
                },
                new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase)),
            virtualOnly: true);
    }

    internal SqlValue EvaluateIndexExpression(
        Expression expression,
        EmbeddedTable table,
        SqlValue[] row,
        long? rowId)
    {
        var qualifiedColumns = BuildQualifiedColumns(table.Name, table.Columns);
        var source = new SourceRow(
            table.Columns,
            row,
            qualifiedColumns,
            RowId: table.HasRowid ? rowId : null,
            RowIdQualifier: table.Name,
            ColumnDefinitions: table.ColumnDefinitions,
            QualifiedColumnDefinitions: BuildQualifiedColumnDefinitions(
                table.Name,
                table.ColumnDefinitions));
        return Evaluate(
            expression,
            EmptyParameters,
            source,
            new QueryContext(
                new Dictionary<string, EmbeddedTable>(StringComparer.OrdinalIgnoreCase)
                {
                    [table.Name] = table,
                },
                new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
                IndexExpression: true));
    }

    // Enforces primary-key integrity that a rowid alias cannot cover. WITHOUT ROWID and
    // STRICT keys are implicitly NOT NULL; a non-STRICT rowid table otherwise treats a
    // table-level PRIMARY KEY like a UNIQUE index with distinct NULLs.
    private void ValidatePrimaryKey(string tableName, EmbeddedTable table, IReadOnlyList<SqlValue[]> rows)
    {
        if (!table.WithoutRowid && table.TableLevelPrimaryKey is null)
            return;

        var primaryKey = table.PrimaryKeyColumns;
        if (primaryKey.Count == 0)
            return;

        if (table.WithoutRowid || table.Strict)
        {
            foreach (var row in rows)
            {
                foreach (var (columnIndex, _) in primaryKey)
                {
                    if (row[columnIndex].Kind == SqlValueKind.Null)
                        throw new EmbeddedSqlException(
                            $"NOT NULL constraint failed: {tableName}.{table.Columns[columnIndex]}",
                            table.PrimaryKeyConflictAlgorithm);
                }
            }
        }

        var seenKeys = new List<SqlValue[]>();
        var pkColumnIndices = primaryKey.Select(entry => entry.Index).ToArray();
        var pkCollations = new string?[primaryKey.Count];
        for (var i = 0; i < primaryKey.Count; i++)
        {
            pkCollations[i] = table.TableLevelPrimaryKey?[i].Collation
                ?? table.ColumnDefinitions[pkColumnIndices[i]].Collation;
        }
        var hashable = true;
        foreach (var collation in pkCollations)
        {
            if (!IsUniqueKeyCollationHashable(collation))
            {
                hashable = false;
                break;
            }
        }

        if (hashable)
        {
            var seen = new Dictionary<string, List<SqlValue[]>>(StringComparer.Ordinal);
            foreach (var row in rows)
            {
                // A rowid table's PRIMARY KEY is backed by a UNIQUE index whose NULLs are
                // distinct; WITHOUT ROWID has already rejected NULL key columns above.
                if (!table.WithoutRowid && pkColumnIndices.Any(ci => row[ci].Kind == SqlValueKind.Null))
                    continue;

                var key = BuildUniqueCanonicalKey(row, pkColumnIndices, pkCollations);
                if (key is null)
                    continue;

                if (seen.TryGetValue(key, out var bucket))
                {
                    var rowKey = new SqlValue[primaryKey.Count];
                    for (var i = 0; i < primaryKey.Count; i++)
                        rowKey[i] = row[pkColumnIndices[i]];

                    foreach (var existing in bucket)
                    {
                        var conflict = true;
                        for (var index = 0; index < primaryKey.Count; index++)
                        {
                            if (Compare(existing[index], rowKey[index], pkCollations[index] ?? "BINARY") != 0)
                            {
                                conflict = false;
                                break;
                            }
                        }

                        if (conflict)
                        {
                            var columns = primaryKey.Select(entry => $"{tableName}.{table.Columns[entry.Index]}");
                            throw new EmbeddedSqlException(
                                $"UNIQUE constraint failed: {string.Join(", ", columns)}",
                                table.PrimaryKeyConflictAlgorithm);
                        }
                    }

                    bucket.Add(rowKey);
                }
                else
                {
                    var rowKey = new SqlValue[primaryKey.Count];
                    for (var i = 0; i < primaryKey.Count; i++)
                        rowKey[i] = row[pkColumnIndices[i]];
                    seen[key] = new List<SqlValue[]> { rowKey };
                }
            }

            return;
        }

        foreach (var row in rows)
        {
            var key = new SqlValue[primaryKey.Count];
            var hasNull = false;
            for (var index = 0; index < primaryKey.Count; index++)
            {
                key[index] = row[primaryKey[index].Index];
                if (key[index].Kind == SqlValueKind.Null)
                    hasNull = true;
            }

            // A rowid table's PRIMARY KEY is backed by a UNIQUE index whose NULLs are
            // distinct; WITHOUT ROWID has already rejected NULL key columns above.
            if (hasNull && !table.WithoutRowid)
                continue;

            foreach (var existing in seenKeys)
            {
                var conflict = true;
                for (var index = 0; index < primaryKey.Count; index++)
                {
                    var columnIndex = primaryKey[index].Index;
                    var collation = table.TableLevelPrimaryKey?[index].Collation
                        ?? table.ColumnDefinitions[columnIndex].Collation;
                    if (Compare(existing[index], key[index], collation) != 0)
                    {
                        conflict = false;
                        break;
                    }
                }

                if (conflict)
                {
                    var columns = primaryKey.Select(entry => $"{tableName}.{table.Columns[entry.Index]}");
                    throw new EmbeddedSqlException(
                        $"UNIQUE constraint failed: {string.Join(", ", columns)}",
                        table.PrimaryKeyConflictAlgorithm);
                }
            }

            seenKeys.Add(key);
        }
    }

    // Re-sorts a WITHOUT ROWID table's rows into primary-key order (honoring per-column
    // ASC/DESC) so scans observe the physical key order SQLite exposes. The parallel internal
    // row-identity list is reordered in lock-step even though SQL cannot access those values.
    private void SortWithoutRowid(EmbeddedTable table)
    {
        if (!table.WithoutRowid)
            return;

        var primaryKey = table.PrimaryKeyColumns;
        var primaryKeySchema = table.PrimaryKeySchema
            ?? throw new InvalidOperationException("WITHOUT ROWID table is missing primary-key metadata.");
        SqliteIndexRecordComparer? persistedComparer = null;
        if (primaryKeySchema.Terms.All(term => term.Collation.IsSupportedByManagedIndexWriter))
        {
            persistedComparer = new SqliteIndexRecordComparer(
                SqliteTextEncoding.Utf8,
                primaryKeySchema.Terms.Select(term =>
                    new SqliteIndexComparisonTerm(term.SortOrder, term.Collation)).ToArray());
        }
        var keys = persistedComparer is null
            ? null
            : table.Rows.Select(primaryKeySchema.ProjectKey).ToArray();
        var order = Enumerable.Range(0, table.Rows.Count).ToList();
        order.Sort((left, right) =>
        {
            if (persistedComparer is not null)
                return persistedComparer.Compare(keys![left], keys[right]);

            for (var position = 0; position < primaryKey.Count; position++)
            {
                var (columnIndex, descending) = primaryKey[position];
                var collation = table.TableLevelPrimaryKey?[position].Collation
                    ?? table.ColumnDefinitions[columnIndex].Collation;
                var comparison = Compare(
                    table.Rows[left][columnIndex],
                    table.Rows[right][columnIndex],
                    collation);
                if (comparison != 0)
                    return descending ? -comparison : comparison;
            }

            return 0;
        });

        var sortedRows = order.Select(index => table.Rows[index]).ToList();
        var sortedRowIds = order.Select(index => table.RowIds[index]).ToList();
        table.Rows.Clear();
        table.Rows.AddRange(sortedRows);
        table.RowIds.Clear();
        table.RowIds.AddRange(sortedRowIds);
    }

    // Routes an INSERT through the bytecode compiler when it falls inside the supported
    // subset (real base table, lowerable RETURNING), running the emitted program as a
    // real write path. Everything else keeps the tree-walking evaluator. The compiled
    // attempt sits inside the trigger-wrapped Perform* so atomicity and triggers apply
    // to both paths identically.
    private ExecutionResult PerformInsert(InsertStatement statement, SqlValue[] parameters, QueryContext context)
    {
        if (CanRouteInsertThroughCompiler(statement, context)
            && TryCompileInsert(statement, parameters, context, out var compiled, out var columns, out var hasReturning))
            return RunCompiledDml(compiled, columns, hasReturning, parameters);

        return PerformInsertEvaluated(statement, parameters, context);
    }

    private ExecutionResult PerformInsertEvaluated(InsertStatement statement, SqlValue[] parameters, QueryContext context)
    {
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");
        if (table.IsAutoIncrement)
            return PerformAutoIncrementInsertEvaluated(statement, parameters, context, table);

        var plan = PrepareInsert(statement, table, context);
        var sourceRows = statement.Source is null
            ? null
            : ExecuteQuery(statement.Source, parameters, context, outerRow: null).Rows;
        var rowCount = sourceRows?.Count ?? statement.Rows.Count;
        var rowsToInsert = new List<SqlValue[]>(rowCount);
        var insertedRowIds = new List<long>(rowCount);
        if (sourceRows is not null)
        {
            foreach (var sourceRow in sourceRows)
            {
                var (row, rowid) = BuildInsertRow(statement, table, plan, sourceRow, parameters, context);
                rowsToInsert.Add(row);
                insertedRowIds.Add(rowid);
            }
        }
        else
        {
            foreach (var valueExpressions in statement.Rows)
            {
                var (row, rowid) = BuildInsertRow(statement, table, plan, valueExpressions, parameters, context);
                rowsToInsert.Add(row);
                insertedRowIds.Add(rowid);
            }
        }

        CommitInserts(context, statement.TableName, table, rowsToInsert, insertedRowIds);

        var lastInsertRowId = table.HasRowid && insertedRowIds.Count > 0
            ? insertedRowIds[^1]
            : (long?)null;
        if (statement.Returning is not null)
        {
            return BuildReturningResult(
                statement.Returning,
                statement.TableName,
                table,
                rowsToInsert,
                insertedRowIds,
                rowsToInsert.Count,
                rowsToInsert.Count > 0,
                parameters,
                context,
                lastInsertRowId);
        }

        return new ExecutionResult([], [], rowsToInsert.Count, rowsToInsert.Count > 0)
        {
            LastInsertRowId = lastInsertRowId,
        };
    }

    private ExecutionResult PerformAutoIncrementInsertEvaluated(
        InsertStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        EmbeddedTable table)
    {
        var plan = PrepareInsert(statement, table, context);
        var sourceRows = statement.Source is null
            ? null
            : ExecuteQuery(statement.Source, parameters, context, outerRow: null).Rows;
        var rowCount = sourceRows?.Count ?? statement.Rows.Count;
        var rowsToInsert = new List<SqlValue[]>(rowCount);
        var insertedRowIds = new List<long>(rowCount);
        var backup = CloneTablesShallow(context.Tables);
        try
        {
            if (sourceRows is not null)
            {
                foreach (var sourceRow in sourceRows)
                    InsertCandidate(sourceRow);
            }
            else
            {
                foreach (var valueExpressions in statement.Rows)
                {
                    var (row, rowId) = BuildInsertRow(
                        statement,
                        table,
                        plan,
                        valueExpressions,
                        parameters,
                        context);
                    AddCandidate(row, rowId);
                }
            }

            CommitInserts(context, statement.TableName, table, rowsToInsert, insertedRowIds);
        }
        catch (EmbeddedSqlException exception)
        {
            var validPrefixLastInsertRowId = FindLastValidInsertRowId(
                context,
                statement.TableName,
                table,
                rowsToInsert,
                insertedRowIds);
            RestoreTables(context.Tables, backup);
            if (validPrefixLastInsertRowId is { } insertedRowId)
                throw new EmbeddedStatementAbortException(exception, insertedRowId);
            throw;
        }
        catch
        {
            RestoreTables(context.Tables, backup);
            throw;
        }

        var lastInsertRowId = insertedRowIds.Count > 0 ? insertedRowIds[^1] : (long?)null;
        if (statement.Returning is not null)
        {
            return BuildReturningResult(
                statement.Returning,
                statement.TableName,
                table,
                rowsToInsert,
                insertedRowIds,
                rowsToInsert.Count,
                rowsToInsert.Count > 0,
                parameters,
                context,
                lastInsertRowId);
        }

        return new ExecutionResult([], [], rowsToInsert.Count, rowsToInsert.Count > 0)
        {
            LastInsertRowId = lastInsertRowId,
        };

        void InsertCandidate(IReadOnlyList<SqlValue> values)
        {
            var (row, rowId) = BuildInsertRow(
                statement,
                table,
                plan,
                values,
                parameters,
                context);
            AddCandidate(row, rowId);
        }

        void AddCandidate(SqlValue[] row, long rowId)
        {
            rowsToInsert.Add(row);
            insertedRowIds.Add(rowId);
        }
    }

    private long? FindLastValidInsertRowId(
        QueryContext context,
        string tableName,
        EmbeddedTable table,
        List<SqlValue[]> candidateRows,
        List<long> candidateRowIds)
    {
        long? lastInsertRowId = null;
        for (var count = 1; count <= candidateRows.Count; count++)
        {
            try
            {
                ValidateInserts(
                    context,
                    tableName,
                    table,
                    candidateRows.GetRange(0, count),
                    candidateRowIds.GetRange(0, count));
                lastInsertRowId = candidateRowIds[count - 1];
            }
            catch (EmbeddedSqlException)
            {
                break;
            }
        }

        return lastInsertRowId;
    }

    // Resolves the INSERT's target columns and the mutable rowid-allocation state shared
    // across every value row. Extracted so the evaluated loop and the compiled write
    // target build rows through identical logic.
    private InsertPlan PrepareInsert(
        InsertStatement statement,
        EmbeddedTable table,
        QueryContext context)
    {
        // The default column list excludes generated columns, which are computed rather than
        // supplied, matching SQLite's INSERT ... VALUES arity for generated-column tables.
        var targetColumns = statement.Columns
            ?? table.ColumnDefinitions.Where(column => !column.IsGenerated).Select(column => column.Name).ToArray();

        // Resolve each target to a real column index, or to the rowid pseudo-column (-1)
        // when the name is rowid/_rowid_/oid and no declared column shadows it.
        var targetIndices = new int[targetColumns.Length];
        var rowidTargetPosition = -1;
        for (var index = 0; index < targetColumns.Length; index++)
        {
            if (table.TryGetColumnIndex(targetColumns[index], out var columnIndex))
            {
                if (table.ColumnDefinitions[columnIndex].IsGenerated)
                    throw new EmbeddedSqlException(
                        $"cannot INSERT into generated column \"{table.Columns[columnIndex]}\"");

                targetIndices[index] = columnIndex;
            }
            else if (table.HasRowid && EmbeddedTable.IsRowidAliasName(targetColumns[index]))
            {
                targetIndices[index] = -1;
                rowidTargetPosition = index;
            }
            else
            {
                throw new EmbeddedSqlException($"table {statement.TableName} has no column named {targetColumns[index]}");
            }
        }

        var anyRow = table.RowIds.Count > 0;
        return new InsertPlan
        {
            TargetIndices = targetIndices,
            RowidTargetPosition = rowidTargetPosition,
            AliasIndex = table.RowidAliasColumnIndex,
            Used = new HashSet<long>(table.RowIds),
            AnyRow = anyRow,
            LargestRowId = anyRow ? table.RowIds.Max() : long.MinValue,
            AutoIncrement = table.IsAutoIncrement
                ? context.AutoIncrementState?.GetTracker(statement.TableName, table, context.Tables)
                    ?? throw new InvalidOperationException("AUTOINCREMENT allocation is missing statement state.")
                : null,
        };
    }

    // Builds a single INSERT row and assigns its rowid, threading the shared allocation
    // state through <paramref name="plan"/> so successive rows see each other's rowids.
    private (SqlValue[] Row, long RowId) BuildInsertRow(
        InsertStatement statement,
        EmbeddedTable table,
        InsertPlan plan,
        Expression[] valueExpressions,
        SqlValue[] parameters,
        QueryContext context,
        bool allowExistingRowid = false,
        bool validateCheckConstraints = true,
        bool resolveNotNullReplace = true,
        bool deferRowidTracking = false)
    {
        var values = new SqlValue[valueExpressions.Length];
        for (var index = 0; index < valueExpressions.Length; index++)
            values[index] = Evaluate(valueExpressions[index], parameters, null, context);

        return BuildInsertRow(
            statement,
            table,
            plan,
            values,
            parameters,
            context,
            allowExistingRowid,
            validateCheckConstraints,
            resolveNotNullReplace,
            deferRowidTracking);
    }

    private (SqlValue[] Row, long RowId) BuildInsertRow(
        InsertStatement statement,
        EmbeddedTable table,
        InsertPlan plan,
        IReadOnlyList<SqlValue> values,
        SqlValue[] parameters,
        QueryContext context,
        bool allowExistingRowid = false,
        bool validateCheckConstraints = true,
        bool resolveNotNullReplace = true,
        bool deferRowidTracking = false)
    {
        if (values.Count != plan.TargetIndices.Length)
            throw new EmbeddedSqlException("table has a different number of columns");

        var assignedTargetIndices = new HashSet<int>();
        foreach (var targetIndex in plan.TargetIndices)
        {
            if (targetIndex >= 0)
                assignedTargetIndices.Add(targetIndex);
        }

        var row = table.CreateRowWithDefaults(
            expression => Evaluate(expression, EmptyParameters, row: null, context),
            assignedTargetIndices);
        var assignedColumns = new HashSet<int>();
        SqlValue explicitRowidValue = SqlValue.Null;
        for (var index = 0; index < values.Count; index++)
        {
            var value = values[index];
            if (plan.TargetIndices[index] < 0)
                explicitRowidValue = value; // rowid pseudo-column: last write wins.
            else if (assignedColumns.Add(plan.TargetIndices[index]))
                row[plan.TargetIndices[index]] = value;
        }

        if (resolveNotNullReplace)
            ResolveNotNullReplaceDefaults(statement, table, row, context);

        table.ApplyAffinities(row);

        // The rowid pseudo-column overrides the alias column when both are supplied,
        // matching SQLite; otherwise a rowid-alias table takes the alias column value.
        var rowidSource = plan.RowidTargetPosition >= 0
            ? explicitRowidValue
            : plan.AliasIndex >= 0 ? row[plan.AliasIndex] : SqlValue.Null;

        long rowid;
        var automaticRowidDeferred = deferRowidTracking
            && table.HasRowid
            && rowidSource.Kind == SqlValueKind.Null;
        if (automaticRowidDeferred)
        {
            rowid = -1;
        }
        else if (rowidSource.Kind == SqlValueKind.Null)
        {
            rowid = plan.AutoIncrement is null
                ? plan.AnyRow ? NextAutoRowId(plan.LargestRowId, plan.Used) : 1
                : plan.AutoIncrement.NextRowId(plan.AnyRow, plan.LargestRowId);
            plan.Used.Add(rowid);
        }
        else if (EmbeddedTable.TryCoerceRowid(rowidSource, out var explicitRowid))
        {
            rowid = explicitRowid;
            if (!deferRowidTracking)
            {
                plan.AutoIncrement?.Observe(rowid);
                if (!plan.Used.Add(rowid) && !allowExistingRowid)
                {
                    if (!allowExistingRowid)
                    {
                        var conflictColumn = plan.AliasIndex >= 0 ? table.Columns[plan.AliasIndex] : "rowid";
                        throw new EmbeddedSqlException(
                            $"UNIQUE constraint failed: {statement.TableName}.{conflictColumn}",
                            plan.AliasIndex >= 0
                                ? table.RowidAliasConflictAlgorithm
                                : null);
                    }
                }
            }
        }
        else
        {
            throw new EmbeddedSqlException("datatype mismatch");
        }

        if (!deferRowidTracking || !table.HasRowid)
        {
            if (!plan.AnyRow || rowid > plan.LargestRowId)
                plan.LargestRowId = rowid;
            plan.AnyRow = true;
        }

        // A rowid-alias column stores exactly the rowid value.
        if (plan.AliasIndex >= 0)
            row[plan.AliasIndex] = SqlValue.Integer(rowid);

        // Generated columns are computed after the base columns (and any rowid alias)
        // are final, so they can reference every stored column value.
        ComputeGeneratedColumns(table, statement.TableName, row, parameters, context);
        if (validateCheckConstraints)
            ValidateCheckConstraints(statement.TableName, table, row, rowid, parameters, context);

        return (row, rowid);
    }

    private void ResolveNotNullReplaceDefaults(
        InsertStatement statement,
        EmbeddedTable table,
        SqlValue[] row,
        QueryContext context)
        => ResolveNotNullReplaceDefaults(statement.ConflictAlgorithm, table, row, context);

    // REPLACE resolves a NOT NULL violation by substituting the column default; a column with no
    // default falls through and the constraint failure is reported as ABORT would report it.
    private void ResolveNotNullReplaceDefaults(
        InsertConflictAlgorithm? statementAlgorithm,
        EmbeddedTable table,
        SqlValue[] row,
        QueryContext context)
    {
        var changed = false;
        for (var columnIndex = 0; columnIndex < table.ColumnDefinitions.Length; columnIndex++)
        {
            var column = table.ColumnDefinitions[columnIndex];
            var conflictAlgorithm = statementAlgorithm ?? column.NotNullConflictAlgorithm;
            if (!column.NotNull
                || row[columnIndex].Kind != SqlValueKind.Null
                || conflictAlgorithm != InsertConflictAlgorithm.Replace
                || !column.HasDefault)
            {
                continue;
            }

            row[columnIndex] = column.DefaultExpression is { } expression
                ? Evaluate(expression, EmptyParameters, row: null, context)
                : column.DefaultValue
                    ?? throw new InvalidOperationException("Default metadata is incomplete.");
            changed = true;
        }

        if (changed)
            table.ApplyAffinities(row);
    }

    // Validates the pending inserts against the whole table, then appends them and
    // restores WITHOUT ROWID key order. A validation failure leaves the table untouched.
    private void CommitInserts(
        QueryContext context,
        string tableName,
        EmbeddedTable table,
        List<SqlValue[]> rowsToInsert,
        List<long> insertedRowIds)
    {
        ValidateInserts(context, tableName, table, rowsToInsert, insertedRowIds);
        MarkTriggerStatementRollbackRequirement(
            context,
            table,
            TriggerMutationKind.Insert);
        table.Rows.AddRange(rowsToInsert);
        table.RowIds.AddRange(insertedRowIds);
        SortWithoutRowid(table);
        if (table.HasRowid)
        {
            foreach (var rowId in insertedRowIds)
                RecordBlobMutation(tableName, rowId);
        }

        foreach (var rowId in insertedRowIds)
            context.ReportRowChange(SqliteChangeOperation.Insert, tableName, table, rowId);
    }

    private void ValidateInserts(
        QueryContext context,
        string tableName,
        EmbeddedTable table,
        IReadOnlyList<SqlValue[]> rowsToInsert,
        IReadOnlyList<long> insertedRowIds)
    {
        ValidateRowids(tableName, table, insertedRowIds);
        var allRows = new List<SqlValue[]>(table.Rows.Count + rowsToInsert.Count);
        allRows.AddRange(table.Rows);
        allRows.AddRange(rowsToInsert);
        table.ValidateRows(tableName, allRows);
        ValidateColumnUniqueConstraints(table, allRows);
        ValidatePrimaryKey(tableName, table, allRows);
        ValidateUniqueIndexes(tableName, table, allRows);
        ValidateForeignKeysAfterInsert(context, tableName, table, rowsToInsert, allRows);
    }

    private static void ValidateRowids(
        string tableName,
        EmbeddedTable table,
        IReadOnlyList<long> insertedRowIds)
    {
        if (!table.HasRowid)
            return;

        var used = new HashSet<long>(table.RowIds);
        foreach (var rowId in insertedRowIds)
        {
            if (used.Add(rowId))
                continue;

            var aliasIndex = table.RowidAliasColumnIndex;
            var conflictColumn = aliasIndex >= 0 ? table.Columns[aliasIndex] : "rowid";
            throw new EmbeddedSqlException(
                $"UNIQUE constraint failed: {tableName}.{conflictColumn}",
                aliasIndex >= 0
                    ? table.RowidAliasConflictAlgorithm
                    : null);
        }
    }

    // Mutable per-statement INSERT plan: the resolved column targets plus the rowid
    // allocation state threaded across value rows.
    private sealed class InsertPlan
    {
        public required int[] TargetIndices { get; init; }

        public required int RowidTargetPosition { get; init; }

        public required int AliasIndex { get; init; }

        public required HashSet<long> Used { get; init; }

        public bool AnyRow { get; set; }

        public long LargestRowId { get; set; }

        public AutoIncrementTracker? AutoIncrement { get; init; }

        public long? LastAddedRowId { get; set; }
    }

    private sealed class DeferredInsertRowId
    {
        public bool IsImplicit { get; set; }

        public long? ExplicitRowId { get; set; }
    }

    private static long CoerceSqliteSequenceInteger(SqlValue value)
    {
        switch (value.Kind)
        {
            case SqlValueKind.Integer:
                return value.AsInteger();
            case SqlValueKind.Real:
                return TruncateSqliteInteger(value.AsReal());
            case SqlValueKind.Text:
                return ParseSqliteIntegerPrefix(value.AsText());
            case SqlValueKind.Blob:
                return ParseSqliteIntegerPrefix(Encoding.UTF8.GetString(value.AsBlob().Span));
            default:
                return 0;
        }
    }

    private static long ParseSqliteIntegerPrefix(ReadOnlySpan<char> text)
    {
        var index = 0;
        while (index < text.Length && IsSqliteNumericWhitespace(text[index]))
            index++;

        var negative = false;
        if (index < text.Length && text[index] is '+' or '-')
        {
            negative = text[index] == '-';
            index++;
        }

        var start = index;
        var limit = negative ? 1UL << 63 : long.MaxValue;
        ulong magnitude = 0;
        while (index < text.Length && text[index] is >= '0' and <= '9')
        {
            var digit = (uint)(text[index] - '0');
            if (magnitude > (limit - digit) / 10)
                return negative ? long.MinValue : long.MaxValue;
            magnitude = magnitude * 10 + digit;
            index++;
        }

        if (index == start)
            return 0;
        if (!negative)
            return (long)magnitude;
        if (magnitude == 1UL << 63)
            return long.MinValue;
        return -(long)magnitude;
    }

    private static bool IsSqliteNumericWhitespace(char value)
        => value is ' ' or '\t' or '\n' or '\r' or '\v' or '\f';

    private static long TruncateSqliteInteger(double value)
    {
        if (double.IsNaN(value))
            return 0;
        if (value >= long.MaxValue)
            return long.MaxValue;
        if (value <= long.MinValue)
            return long.MinValue;
        return (long)value;
    }

    // Computes the next autogenerated rowid: one greater than the largest rowid in use,
    // or a random unused positive value once the maximum integer rowid is reached, exactly
    // as SQLite does.
    private static long NextAutoRowId(long largestRowId, HashSet<long> used)
    {
        if (largestRowId != long.MaxValue)
            return largestRowId + 1;

        while (true)
        {
            var candidate = Random.Shared.NextInt64(1, long.MaxValue);
            if (!used.Contains(candidate))
                return candidate;
        }
    }

    // Superseded by the row-frame trigger implementation below.
#if false
    private ExecutionResult ExecuteUpdate(
        UpdateStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        var updatedColumns = statement.Assignments
            .Select(assignment => assignment.Column)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var beforeTriggers = GetMatchingTriggers(
            context,
            statement.TableName,
            TriggerEvent.Update,
            TriggerTiming.Before,
            updatedColumns);
        var afterTriggers = GetMatchingTriggers(
            context,
            statement.TableName,
            TriggerEvent.Update,
            TriggerTiming.After,
            updatedColumns);
        if (beforeTriggers.Count > 0 || afterTriggers.Count > 0)
        {
            return context.ForeignKeysEnabled
                ? ExecuteWithForeignKeyStatement(
                    context,
                    () => ExecuteUpdateWithRowTriggers(
                        statement,
                        parameters,
                        context,
                        beforeTriggers,
                        afterTriggers))
                : ExecuteUpdateWithRowTriggers(
                    statement,
                    parameters,
                    context,
                    beforeTriggers,
                    afterTriggers);
        }

        return context.ForeignKeysEnabled
            ? ExecuteWithForeignKeyStatement(
                context,
                () => PerformUpdate(statement, parameters, context))
            : PerformUpdate(statement, parameters, context);
    }

    private ExecutionResult ExecuteUpdateWithRowTriggers(
        UpdateStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        IReadOnlyList<TriggerDefinition> beforeTriggers,
        IReadOnlyList<TriggerDefinition> afterTriggers)
    {
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");

        ValidateTableReturning(statement.Returning, statement.TableName, table, context);
        var plan = PrepareUpdate(statement, table, context);
        var selectedPositions = statement.Limit is null
            ? null
            : SelectLimitedDmlPositions(
                statement.TargetQualifier,
                table,
                statement.Where,
                statement.EffectiveOrderBy,
                statement.Limit,
                statement.Offset,
                statement.Assignments.Select(assignment => assignment.Value),
                statement.Returning,
                parameters,
                context);
        var selectedRowIds = new List<long>();
        for (var position = 0; position < table.Rows.Count; position++)
        {
            var row = table.Rows[position];
            var rowId = table.RowIds[position];
            var source = new SourceRow(
                table.Columns,
                row,
                BuildQualifiedColumns(statement.TableName, table.Columns),
                RowId: table.HasRowid ? rowId : null,
                RowIdQualifier: statement.TableName,
                ColumnDefinitions: table.ColumnDefinitions,
                QualifiedColumnDefinitions: BuildQualifiedColumnDefinitions(
                    statement.TableName,
                    table.ColumnDefinitions));
            var selected = selectedPositions is not null
                ? selectedPositions.Contains(position)
                : statement.Where is null || IsTrue(Evaluate(statement.Where, parameters, source, context));
            if (selected)
                selectedRowIds.Add(rowId);
        }

        var backup = CloneTablesShallow(context.Tables);
        var updatedRows = new List<SqlValue[]>();
        var updatedRowIds = new List<long>();
        try
        {
            foreach (var selectedRowId in selectedRowIds)
            {
                var position = table.RowIds.IndexOf(selectedRowId);
                if (position < 0)
                    continue;

                var original = table.Rows[position].ToArray();
                SqlValue[] updated;
                long newRowId;
                try
                {
                    (updated, newRowId) = BuildUpdatedRow(
                        statement,
                        table,
                        plan,
                        original,
                        selectedRowId,
                        parameters,
                        context);
                }
                catch (EmbeddedSqlException exception) when (IsConflictAlgorithmConstraint(exception))
                {
                    if (HandleUpdateConflict(exception))
                        continue;
                    throw;
                }
                var frame = new TriggerRowFrame(
                    original,
                    table.HasRowid ? selectedRowId : null,
                    updated,
                    table.HasRowid ? newRowId : null);
                if (beforeTriggers.Count > 0 && FireTriggers(beforeTriggers, context, frame))
                    continue;

                position = table.RowIds.IndexOf(selectedRowId);
                if (position < 0)
                    continue;
                var originalRows = table.Rows.Select(row => row.ToArray()).ToArray();
                var rows = table.Rows.Select(row => row.ToArray()).ToList();
                var rowIds = table.RowIds.ToList();
                rows[position] = updated;
                rowIds[position] = newRowId;
                try
                {
                    CommitUpdates(
                        context,
                        statement.TableName,
                        table,
                        originalRows,
                        rows,
                        rowIds,
                        plan,
                        [position]);
                }
                catch (EmbeddedSqlException exception) when (IsConflictAlgorithmConstraint(exception))
                {
                    if (HandleUpdateConflict(exception))
                        continue;
                    throw;
                }

                updatedRows.Add(updated);
                updatedRowIds.Add(newRowId);
                if (afterTriggers.Count > 0)
                    _ = FireTriggers(afterTriggers, context, frame);
            }
        }
        catch (EmbeddedTriggerRaiseException exception)
            when (exception.Algorithm == InsertConflictAlgorithm.Fail)
        {
            throw new EmbeddedConflictFailException(exception, GetLastInsertRowId(context));
        }
        catch (EmbeddedTriggerRaiseException exception)
            when (exception.Algorithm == InsertConflictAlgorithm.Rollback)
        {
            RestoreTables(context.Tables, backup);
            throw new EmbeddedConflictRollbackException(exception, GetLastInsertRowId(context));
        }
        catch (EmbeddedConflictFailException)
        {
            throw;
        }
        catch (EmbeddedConflictRollbackException)
        {
            RestoreTables(context.Tables, backup);
            throw;
        }
        catch
        {
            RestoreTables(context.Tables, backup);
            throw;
        }

        if (statement.Returning is not null)
        {
            try
            {
                return BuildReturningResult(
                    statement.Returning,
                    statement.TableName,
                    table,
                    updatedRows,
                    updatedRowIds,
                    updatedRows.Count,
                    updatedRows.Count > 0,
                    parameters,
                    context);
            }
            catch
            {
                RestoreTables(context.Tables, backup);
                throw;
            }
        }

        return new ExecutionResult([], [], updatedRows.Count, updatedRows.Count > 0);

        bool HandleUpdateConflict(EmbeddedSqlException exception)
        {
            switch (exception.ConflictAlgorithm ?? InsertConflictAlgorithm.Abort)
            {
                case InsertConflictAlgorithm.Ignore:
                    return true;
                case InsertConflictAlgorithm.Fail:
                    throw new EmbeddedConflictFailException(
                        exception,
                        GetLastInsertRowId(context));
                case InsertConflictAlgorithm.Rollback:
                    throw new EmbeddedConflictRollbackException(
                        exception,
                        GetLastInsertRowId(context));
                case InsertConflictAlgorithm.Replace:
                    throw new EmbeddedSqlException(
                        "Managed UPDATE cannot apply schema-level ON CONFLICT REPLACE "
                        + "until replacement deletes are supported.");
                case InsertConflictAlgorithm.Abort:
                    return false;
                default:
                    throw new InvalidOperationException("Unknown UPDATE conflict algorithm.");
            }
        }
    }

#endif
    private ExecutionResult ExecuteUpdate(
        UpdateStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        var updatedColumns = statement.Assignments
            .Select(assignment => assignment.Column)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        ValidateForeignKeyActionTriggerPrograms(
            context,
            statement.TableName,
            TriggerEvent.Update,
            updatedColumns);
        var hasForeignKeyActionTriggers = HasForeignKeyActionTriggers(
            context,
            statement.TableName,
            TriggerEvent.Update,
            updatedColumns);
        // OR REPLACE removes the conflicting rows before the target row is rewritten, which the
        // evaluated path cannot express: it stages every row and publishes once at the end. The
        // row-triggered path commits row by row and already owns the delete-then-insert
        // replacement used by INSERT OR REPLACE, so replacement updates route through it.
        var replacesRows = statement.ConflictAlgorithm == InsertConflictAlgorithm.Replace;
        if (context.Views?.ContainsKey(statement.TableName) == true
            || HasTriggerEvent(context, statement.TableName, TriggerEvent.Update)
            || context.InsideTrigger && context.ConflictAlgorithmOverride is not null
            || replacesRows
            || hasForeignKeyActionTriggers)
        {
            return ExecuteRowTriggeredUpdate(statement, parameters, context, updatedColumns);
        }

        return ExecuteWithTriggers(
            statement.TableName,
            TriggerEvent.Update,
            context,
            () => PerformUpdate(statement, parameters, context));
    }

    private ExecutionResult PerformUpdate(
        UpdateStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        context = EnterCollationSource(
            context,
            new NamedTableSource(statement.TableName, statement.Alias));
        if (CanRouteUpdateThroughCompiler(statement, context)
            && TryCompileUpdate(statement, parameters, context, out var compiled, out var columns, out var hasReturning))
            return RunCompiledDml(compiled, columns, hasReturning, parameters);

        return PerformUpdateEvaluated(statement, parameters, context);
    }

    private ExecutionResult PerformUpdateEvaluated(
        UpdateStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");

        var plan = PrepareUpdate(statement, table, context);
        var fromMatches = statement.From is null
            ? null
            : MatchUpdateFromRows(statement, table, parameters, context)
                .ToDictionary(match => match.Position, match => match.Row);
        var selectedPositions = statement.Limit is null
            ? null
            : SelectLimitedDmlPositions(
                statement.TargetQualifier,
                table,
                statement.Where,
                statement.EffectiveOrderBy,
                statement.Limit,
                statement.Offset,
                statement.Assignments.Select(assignment => assignment.Value),
                statement.Returning,
                parameters,
                context);
        var rows = table.Rows.Select(row => row.ToArray()).ToList();
        var rowIds = table.RowIds.Count == table.Rows.Count
            ? table.RowIds.ToList()
            : Enumerable.Range(1, table.Rows.Count).Select(position => (long)position).ToList();
        var updatedRows = statement.Returning is null ? null : new List<SqlValue[]>();
        var updatedRowIds = statement.Returning is null ? null : new List<long>();
        var updatedPositions = new List<int>();
        var rowsAffected = 0;
        var updateOrder = table.HasRowid
            ? Enumerable.Range(0, table.Rows.Count).OrderBy(position => rowIds[position]).ToArray()
            : Enumerable.Range(0, table.Rows.Count).ToArray();
        foreach (var position in updateOrder)
        {
            var row = table.Rows[position];
            var rowid = position < table.RowIds.Count ? table.RowIds[position] : position + 1;
            SourceRow? evaluationRow = null;
            if (fromMatches is not null)
            {
                if (!fromMatches.TryGetValue(position, out evaluationRow))
                    continue;
            }
            else if (selectedPositions is not null)
            {
                if (!selectedPositions.Contains(position))
                    continue;
            }
            else if (statement.Where is not null)
            {
                var source = CreateDmlTargetRow(table, statement.TargetQualifier, row, rowid);
                if (!IsTrue(Evaluate(statement.Where, parameters, source, context)))
                    continue;
            }

            SqlValue[]? updated = null;
            var newRowid = rowid;
            try
            {
                (updated, newRowid) = BuildUpdatedRow(
                    statement,
                    table,
                    plan,
                    row,
                    rowid,
                    parameters,
                    context,
                    evaluationRow: evaluationRow);
                rows[position] = updated;
                rowIds[position] = newRowid;
                ValidateRowIdsUnique(statement.TableName, table, rowIds, plan.AliasIndex);
                table.ValidateRows(statement.TableName, rows);
                ValidateColumnUniqueConstraints(table, rows);
                ValidatePrimaryKey(statement.TableName, table, rows);
                ValidateUniqueIndexes(statement.TableName, table, rows);
            }
            catch (EmbeddedSqlException exception)
            {
                rows[position] = row;
                rowIds[position] = rowid;
                // A trigger body ignores its own OR clause: the statement that fired the trigger
                // supplies the policy. Outside a trigger the statement's OR clause wins over any
                // schema-level ON CONFLICT recorded on the violated constraint.
                var statementAlgorithm = context.InsideTrigger
                    ? context.TriggerConflictAlgorithm
                    : statement.ConflictAlgorithm;
                if (statementAlgorithm is not null && !IsConflictAlgorithmConstraint(exception))
                    throw;
                var algorithm = statementAlgorithm ?? exception.ConflictAlgorithm;
                if (algorithm == InsertConflictAlgorithm.Ignore)
                    continue;
                if (statementAlgorithm == InsertConflictAlgorithm.Fail)
                {
                    if (rowsAffected > 0)
                    {
                        CommitUpdates(
                            context,
                            statement.TableName,
                            table,
                            table.Rows,
                            rows,
                            rowIds,
                            plan,
                            updatedPositions,
                            beforeMutation: null);
                    }

                    throw new EmbeddedUpsertConflictFailException(
                        exception,
                        context.LastInsertRowId);
                }
                if (statementAlgorithm == InsertConflictAlgorithm.Rollback)
                    throw new EmbeddedConflictRollbackException(exception);
                if (algorithm is InsertConflictAlgorithm.Fail
                    or InsertConflictAlgorithm.Rollback
                    or InsertConflictAlgorithm.Replace)
                {
                    throw new EmbeddedSqlException(
                        "Managed UPDATE cannot apply schema-level ON CONFLICT "
                        + $"{algorithm.Value.ToString().ToUpperInvariant()} until the pending "
                        + "row-update engine supports partial publication, transaction rollback, and replacement.");
                }
                throw;
            }
            updatedRows?.Add(updated!);
            updatedRowIds?.Add(newRowid);
            updatedPositions.Add(position);
            rowsAffected++;
        }

        ExecutionResult? returningResult = null;
        CommitUpdates(
            context,
            statement.TableName,
            table,
            table.Rows,
            rows,
            rowIds,
            plan,
            updatedPositions,
            statement.Returning is null
                ? null
                : () => returningResult = BuildReturningResult(
                    statement.Returning,
                    statement.TableName,
                    table,
                    updatedRows!,
                    updatedRowIds!,
                    rowsAffected,
                    rowsAffected > 0,
                    parameters,
                    context));
        if (statement.Returning is not null)
            return returningResult!;

        return new ExecutionResult([], [], rowsAffected, rowsAffected > 0);
    }

    // Pairs each target row with the FROM row that drives its assignments. SQLite compiles
    // UPDATE ... FROM by prepending the target to the FROM list, so the target is invisible to
    // join constraints written inside FROM: materialising FROM on its own reproduces that and
    // snapshots the source before the first target row is written. Each target row is updated at
    // most once; SQLite leaves the choice of source row unspecified when several match, and
    // keeping the first one seen also keeps every SET column consistent with a single source row.
    private List<(int Position, SourceRow Row)> MatchUpdateFromRows(
        UpdateStatement statement,
        EmbeddedTable table,
        SqlValue[] parameters,
        QueryContext context)
    {
        var from = statement.From!;
        RejectDuplicateUpdateFromQualifiers(from, context);
        RejectAmbiguousUpdateFromCoalescedColumns(from, context);
        var qualifier = statement.TargetQualifier;
        var joined = new JoinTableSource(
            new NamedTableSource(statement.TableName, qualifier),
            from,
            Condition: null,
            JoinKind.Inner);
        var sourceData = GetSourceRows(from, parameters, context, maximumRows: null, outerRow: null);
        var targetQualifiedColumns = BuildQualifiedColumns(qualifier, table.Columns);
        var sourceQualifiedColumns = GetQualifiedColumns(from, context);
        var columns = table.Columns.Concat(sourceData.Columns).ToArray();
        var outputColumns = GetOutputColumns(joined, context);
        var columnDefinitions = GetSourceColumnDefinitions(joined, context);
        var qualifiedColumnDefinitions = GetSourceQualifiedColumnDefinitions(joined, context);
        var targetWidth = table.Columns.Length;
        // A source that reuses the target's qualifier does not hide it: SQLite resolves the
        // qualified name against both and only complains when the column exists on both sides.
        var ambiguousQualifiedColumns = targetQualifiedColumns.Keys
            .Where(sourceQualifiedColumns.ContainsKey)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        var matches = new List<(int Position, SourceRow Row)>();
        for (var position = 0; position < table.Rows.Count; position++)
        {
            context.CheckInterrupt();
            var targetValues = table.Rows[position];
            var rowid = position < table.RowIds.Count ? table.RowIds[position] : position + 1;
            var targetRowIds = new Dictionary<string, long?>(StringComparer.OrdinalIgnoreCase)
            {
                [qualifier] = table.HasRowid ? rowid : null,
            };
            foreach (var sourceRow in sourceData.Rows)
            {
                var combined = new SourceRow(
                    columns,
                    [.. targetValues, .. sourceRow.Values],
                    CombineQualifiedColumns(targetQualifiedColumns, sourceRow.QualifiedColumns, targetWidth),
                    Parent: null,
                    OutputColumns: outputColumns,
                    RowId: table.HasRowid ? rowid : null,
                    RowIdQualifier: qualifier,
                    QualifiedRowIds: CombineQualifiedRowIds(targetRowIds, GetQualifiedRowIds(sourceRow)),
                    ColumnDefinitions: columnDefinitions,
                    QualifiedColumnDefinitions: qualifiedColumnDefinitions,
                    AmbiguousQualifiedColumns: ambiguousQualifiedColumns);
                if (statement.Where is not null
                    && !IsTrue(Evaluate(statement.Where, parameters, combined, context)))
                {
                    continue;
                }

                matches.Add((position, combined));
                break;
            }
        }

        return matches;
    }

    // SQLite adds a hidden rowid reference for every FROM entry so it can drive the update from
    // an ephemeral table; two entries sharing a qualifier make that reference ambiguous. The
    // target is exempt because its rowid is referenced positionally rather than by name.
    private static void RejectDuplicateUpdateFromQualifiers(TableSource from, QueryContext context)
    {
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        Walk(from);

        void Walk(TableSource source)
        {
            switch (source)
            {
                case JoinTableSource join:
                    Walk(join.Left);
                    Walk(join.Right);
                    return;
                case NamedTableSource named:
                    Add(named);
                    return;
                default:
                    return;
            }
        }

        void Add(NamedTableSource named)
        {
            var isCommonTableExpression = context.CommonTableExpressions.ContainsKey(named.Name);
            var qualifier = named.Alias
                ?? (isCommonTableExpression ? named.Name : ManagedSchemaName.Display(named.Name));
            if (seen.Add(qualifier))
                return;

            var schema = ManagedSchemaName.TrySplit(named.Name, out var explicitSchema, out _)
                ? explicitSchema
                : "main";
            throw new EmbeddedSqlException($"ambiguous column name: {schema}.{qualifier}._ROWID_");
        }
    }

    // Compiling UPDATE ... FROM leaves SQLite with an unqualified reference to every column a
    // NATURAL or USING join coalesced. That reference is resolved against the FROM list alone -
    // the update target never takes part - and the right side of the coalescing join is hidden,
    // so the statement is rejected as soon as any other FROM entry still exposes the same name.
    private static void RejectAmbiguousUpdateFromCoalescedColumns(TableSource from, QueryContext context)
    {
        var leaves = new List<(TableSource Source, string[] Columns)>();
        var hidden = new HashSet<(int Leaf, string Column)>();
        var coalesced = new List<string>();
        Walk(from);

        foreach (var name in coalesced)
        {
            var visible = 0;
            for (var leaf = 0; leaf < leaves.Count; leaf++)
            {
                if (hidden.Contains((leaf, name)))
                    continue;
                if (leaves[leaf].Columns.Contains(name, StringComparer.OrdinalIgnoreCase))
                    visible++;
            }

            if (visible > 1)
                throw new EmbeddedSqlException($"ambiguous column name: {name}");
        }

        (int Start, int End) Walk(TableSource source)
        {
            if (source is not JoinTableSource join)
            {
                leaves.Add((source, GetSourceColumns(source, context)));
                return (leaves.Count - 1, leaves.Count);
            }

            var (leftStart, leftEnd) = Walk(join.Left);
            var (rightStart, rightEnd) = Walk(join.Right);
            var names = join.UsingColumns
                ?? (join.Natural
                    ? leaves
                        .Skip(rightStart)
                        .Take(rightEnd - rightStart)
                        .SelectMany(leaf => leaf.Columns)
                        .Where(column => leaves
                            .Skip(leftStart)
                            .Take(leftEnd - leftStart)
                            .Any(leaf => leaf.Columns.Contains(column, StringComparer.OrdinalIgnoreCase)))
                        .ToArray()
                    : null);
            if (names is not null)
            {
                foreach (var name in names)
                {
                    coalesced.Add(name);
                    for (var leaf = rightStart; leaf < rightEnd; leaf++)
                        hidden.Add((leaf, name));
                }
            }

            return (leftStart, rightEnd);
        }
    }

    private HashSet<int> SelectLimitedDmlPositions(
        string qualifier,
        EmbeddedTable table,
        Expression? where,
        IReadOnlyList<OrderByTerm> orderBy,
        Expression limitExpression,
        Expression? offsetExpression,
        IEnumerable<Expression> mutationExpressions,
        IReadOnlyList<Projection>? returning,
        SqlValue[] parameters,
        QueryContext context)
    {
        ValidateOrderByCollations(orderBy);
        var validationRow = CreateDmlTargetRow(
            table,
            qualifier,
            Enumerable.Repeat(SqlValue.Null, table.Columns.Length).ToArray(),
            1);
        ValidateColumnReferences(where, validationRow);
        foreach (var expression in mutationExpressions)
            ValidateColumnReferences(expression, validationRow);
        foreach (var term in orderBy)
            ValidateColumnReferences(term.Expression, validationRow);
        if (returning is not null)
        {
            foreach (var projection in returning)
            {
                if (projection.Expression is not (StarExpression or QualifiedStarExpression))
                    ValidateColumnReferences(projection.Expression, validationRow);
            }
        }

        var limit = RequireLimitInteger(Evaluate(limitExpression, parameters, null, context));
        var offset = offsetExpression is null
            ? 0
            : Math.Max(0, RequireLimitInteger(Evaluate(offsetExpression, parameters, null, context)));
        if (limit == 0)
            return [];

        var candidates = new List<LimitedDmlCandidate>();
        for (var position = 0; position < table.Rows.Count; position++)
        {
            var rowid = position < table.RowIds.Count ? table.RowIds[position] : position + 1;
            var source = CreateDmlTargetRow(table, qualifier, table.Rows[position], rowid);
            if (where is not null && !IsTrue(Evaluate(where, parameters, source, context)))
                continue;

            var orderValues = new SqlValue[orderBy.Count];
            for (var index = 0; index < orderBy.Count; index++)
                orderValues[index] = Evaluate(orderBy[index].Expression, parameters, source, context);
            candidates.Add(new LimitedDmlCandidate(position, orderValues));
        }

        if (orderBy.Count > 0)
        {
            candidates.Sort((left, right) =>
            {
                for (var index = 0; index < orderBy.Count; index++)
                {
                    var term = orderBy[index];
                    var comparison = CompareForOrdering(
                        left.OrderValues[index],
                        right.OrderValues[index],
                        term,
                        GetCollation(term.Expression));
                    if (comparison == 0)
                        continue;
                    return comparison;
                }

                return left.Position.CompareTo(right.Position);
            });
        }

        var selected = new HashSet<int>();
        long skipped = 0;
        long taken = 0;
        foreach (var candidate in candidates)
        {
            if (skipped < offset)
            {
                skipped++;
                continue;
            }
            if (limit >= 0 && taken >= limit)
                break;

            selected.Add(candidate.Position);
            taken++;
        }

        return selected;
    }

    // Resolves the UPDATE's column and rowid assignments. Extracted so the evaluated loop
    // and the compiled write target update rows through identical logic.
    private UpdatePlan PrepareUpdate(
        UpdateStatement statement,
        EmbeddedTable table,
        QueryContext context)
    {
        var columnAssignments = new List<ResolvedAssignment>();
        ResolvedAssignment? rowidAssignment = null;
        var validatedValues = new HashSet<Expression>(ReferenceEqualityComparer.Instance);
        foreach (var assignment in statement.Assignments)
        {
            if (validatedValues.Add(assignment.Value))
                ValidateAssignmentArity(assignment, context);

            if (table.TryGetColumnIndex(assignment.Column, out var index))
            {
                if (table.ColumnDefinitions[index].IsGenerated)
                    throw new EmbeddedSqlException(
                        $"cannot UPDATE generated column \"{table.Columns[index]}\"");

                columnAssignments.Add(new ResolvedAssignment(
                    index,
                    assignment.Value,
                    assignment.ValueIndex,
                    assignment.ValueCount));
            }
            else if (table.HasRowid && EmbeddedTable.IsRowidAliasName(assignment.Column))
            {
                rowidAssignment = new ResolvedAssignment(
                    Index: -1,
                    assignment.Value,
                    assignment.ValueIndex,
                    assignment.ValueCount); // rowid pseudo-column: last write wins.
            }
            else
            {
                throw new EmbeddedSqlException($"no such column: {assignment.Column}");
            }
        }

        return new UpdatePlan
        {
            AliasIndex = table.RowidAliasColumnIndex,
            ColumnAssignments = columnAssignments,
            RowidAssignment = rowidAssignment,
        };
    }

    private static void ValidateAssignmentArity(ColumnAssignment assignment, QueryContext context)
    {
        var actualCount = GetExpressionValueCount(assignment.Value, context);
        if (actualCount == assignment.ValueCount)
            return;

        if (assignment.IsRowAssignment)
        {
            throw new EmbeddedSqlException(
                $"{assignment.ValueCount} columns assigned {actualCount} values");
        }
        if (assignment.Value is ScalarSubqueryExpression)
        {
            throw new EmbeddedSqlException(
                $"sub-select returns {actualCount} columns - expected {assignment.ValueCount}");
        }

        throw new EmbeddedSqlException("row value misused");
    }

    // Applies the UPDATE assignments to one matched row, computing its new rowid and
    // regenerated columns. The original row and its rowid drive the value expressions;
    // UPDATE ... FROM supplies the joined target/source row so assignments can read both.
    private (SqlValue[] Row, long RowId) BuildUpdatedRow(
        UpdateStatement statement,
        EmbeddedTable table,
        UpdatePlan plan,
        SqlValue[] originalRow,
        long rowid,
        SqlValue[] parameters,
        QueryContext context,
        bool validateCheckConstraints = true,
        SourceRow? evaluationRow = null)
    {
        var source = evaluationRow
            ?? CreateDmlTargetRow(table, statement.TargetQualifier, originalRow, rowid);

        var updated = originalRow.ToArray();
        var assignmentValues = new Dictionary<Expression, SqlValue[]>(ReferenceEqualityComparer.Instance);
        foreach (var assignment in plan.ColumnAssignments)
        {
            updated[assignment.Index] = EvaluateAssignmentValue(
                assignment,
                assignmentValues,
                parameters,
                source,
                context);
        }

        table.ApplyAffinities(updated);

        // The rowid pseudo-column overrides a reassigned alias column; when neither is
        // touched the alias column still equals the unchanged rowid.
        var newRowid = rowid;
        if (plan.RowidAssignment is not null)
        {
            newRowid = CoerceRowidOrThrow(EvaluateAssignmentValue(
                plan.RowidAssignment,
                assignmentValues,
                parameters,
                source,
                context));
        }
        else if (plan.AliasIndex >= 0)
            newRowid = CoerceRowidOrThrow(updated[plan.AliasIndex]);

        if (plan.AliasIndex >= 0)
            updated[plan.AliasIndex] = SqlValue.Integer(newRowid);

        // Recompute generated columns from the freshly updated base values so a change
        // to any source column is reflected in the stored generated value.
        ComputeGeneratedColumns(table, statement.TableName, updated, parameters, context);
        if (validateCheckConstraints)
            ValidateCheckConstraints(statement.TableName, table, updated, newRowid, parameters, context);

        return (updated, newRowid);
    }

    private SqlValue EvaluateAssignmentValue(
        ResolvedAssignment assignment,
        Dictionary<Expression, SqlValue[]> cache,
        SqlValue[] parameters,
        SourceRow source,
        QueryContext context)
    {
        if (!cache.TryGetValue(assignment.Value, out var values))
        {
            values = EvaluateExpressionValues(
                assignment.Value,
                assignment.ValueCount,
                parameters,
                source,
                context);
            cache.Add(assignment.Value, values);
        }

        return values[assignment.ValueIndex];
    }

    private void ValidateCheckConstraints(
        string tableName,
        EmbeddedTable table,
        SqlValue[] row,
        long rowid,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (!table.HasCheckConstraints)
            return;

        var source = new SourceRow(
            table.Columns,
            row,
            BuildQualifiedColumns(tableName, table.Columns),
            RowId: table.HasRowid ? rowid : null,
            RowIdQualifier: tableName,
            ColumnDefinitions: table.ColumnDefinitions);
        foreach (var column in table.ColumnDefinitions)
        {
            foreach (var check in column.CheckConstraints)
                Validate(check);
        }
        foreach (var check in table.CheckConstraints)
            Validate(check);

        void Validate(CheckConstraint check)
        {
            var value = Evaluate(check.Expression, parameters, source, context);
            if (value.Kind != SqlValueKind.Null && !IsTrue(value))
            {
                throw new EmbeddedSqlException(
                    $"CHECK constraint failed: {check.Name ?? check.Sql}",
                    InsertConflictAlgorithm.Abort);
            }
        }
    }

    // Validates the fully assembled post-update rows, then swaps them in and restores
    // WITHOUT ROWID key order. A validation failure leaves the table untouched.
    private void CommitUpdates(
        QueryContext context,
        string tableName,
        EmbeddedTable table,
        IReadOnlyList<SqlValue[]> originalRows,
        List<SqlValue[]> rows,
        List<long> rowIds,
        UpdatePlan plan,
        IReadOnlyList<int> updatedPositions,
        Action? beforeMutation = null)
    {
        ValidateRowIdsUnique(tableName, table, rowIds, plan.AliasIndex);
        table.ValidateRows(tableName, rows);
        ValidateColumnUniqueConstraints(table, rows);
        ValidatePrimaryKey(tableName, table, rows);
        ValidateUniqueIndexes(tableName, table, rows);
        var originalRowSnapshot = originalRows.Select(row => row.ToArray()).ToArray();
        var postUpdateRowSnapshot = rows.ToArray();
        MarkTriggerStatementRollbackRequirement(
            context,
            table,
            TriggerMutationKind.Update,
            plan);
        beforeMutation?.Invoke();
        var originalRowIds = table.HasRowid
            ? updatedPositions.Select(position => table.RowIds[position]).ToArray()
            : [];
        table.Rows.Clear();
        table.Rows.AddRange(rows);
        table.RowIds.Clear();
        table.RowIds.AddRange(rowIds);
        SortWithoutRowid(table);
        ValidateForeignKeysAfterUpdate(
            context,
            tableName,
            table,
            originalRowSnapshot,
            postUpdateRowSnapshot,
            plan,
            updatedPositions);
        if (table.HasRowid)
        {
            for (var index = 0; index < updatedPositions.Count; index++)
            {
                var position = updatedPositions[index];
                RecordBlobMutation(tableName, originalRowIds[index]);
                RecordBlobMutation(tableName, rowIds[position]);
            }
        }

        // SQLite reports the post-update rowid, so an UPDATE that rewrites an INTEGER PRIMARY
        // KEY notifies with the new value rather than the one the row had before.
        foreach (var position in updatedPositions)
            context.ReportRowChange(SqliteChangeOperation.Update, tableName, table, rowIds[position]);
    }

    // Foreign-key checks run against the complete post-statement image, but only inspect
    // rows or parent keys touched by this statement. That preserves SQLite's behavior when
    // enforcement is enabled after legacy violations were inserted with foreign_keys OFF.
    private void ValidateForeignKeysAfterInsert(
        QueryContext context,
        string tableName,
        EmbeddedTable table,
        IReadOnlyList<SqlValue[]> insertedRows,
        IReadOnlyList<SqlValue[]> postInsertRows)
    {
        if (!context.ForeignKeysEnabled || insertedRows.Count == 0)
            return;

        ValidateChildForeignKeys(context, tableName, table, insertedRows, tableName, postInsertRows);
    }

    private void ValidateForeignKeysAfterUpdate(
        QueryContext context,
        string tableName,
        EmbeddedTable table,
        IReadOnlyList<SqlValue[]> originalRows,
        IReadOnlyList<SqlValue[]> postUpdateRows,
        UpdatePlan plan,
        IReadOnlyList<int> updatedPositions)
    {
        if (!context.ForeignKeysEnabled || updatedPositions.Count == 0)
            return;

        var assignedColumns = plan.ColumnAssignments
            .Select(assignment => assignment.Index)
            .ToHashSet();
        var changedRows = updatedPositions.Select(position => postUpdateRows[position]).ToArray();
        foreach (var foreignKey in table.ForeignKeys.Reverse())
        {
            var childColumns = ResolveForeignKeyChildColumns(table, tableName, foreignKey);
            if (childColumns.Any(assignedColumns.Contains))
            {
                ValidateChildForeignKeys(context, tableName, table, changedRows, tableName, postUpdateRows, foreignKey);
            }
        }

        ValidateChildrenAfterParentUpdate(
            context,
            tableName,
            originalRows,
            postUpdateRows,
            assignedColumns,
            updatedPositions);
    }

    private void ValidateForeignKeysAfterDelete(
        QueryContext context,
        string tableName,
        EmbeddedTable table,
        IReadOnlyList<SqlValue[]> originalRows,
        IReadOnlyList<SqlValue[]> postDeleteRows,
        IReadOnlyList<SqlValue[]> deletedRows)
    {
        if (!context.ForeignKeysEnabled || deletedRows.Count == 0)
            return;

        foreach (var (childTableName, childTable) in context.Tables)
        {
            foreach (var foreignKey in childTable.ForeignKeys.Reverse())
            {
                if (!string.Equals(foreignKey.ParentTable, tableName, StringComparison.OrdinalIgnoreCase))
                    continue;

                var parent = ResolveForeignKeyParent(context.Tables, childTableName, foreignKey);
                foreach (var deletedRow in deletedRows)
                {
                    ApplyForeignKeyParentAction(
                        context,
                        childTableName,
                        childTable,
                        foreignKey,
                        parent,
                        GetForeignKeyValues(deletedRow, parent.ColumnIndices),
                        newParentValues: null,
                        foreignKey.OnDelete,
                        tableName,
                        postDeleteRows);
                }
            }
        }
    }

    private void ValidateChildrenAfterParentUpdate(
        QueryContext context,
        string tableName,
        IReadOnlyList<SqlValue[]> originalRows,
        IReadOnlyList<SqlValue[]> postUpdateRows,
        IReadOnlySet<int> assignedColumns,
        IReadOnlyList<int> updatedPositions)
    {
        for (var updatedIndex = 0; updatedIndex < updatedPositions.Count; updatedIndex++)
        {
            var position = updatedPositions[updatedIndex];
            foreach (var (childTableName, childTable) in context.Tables)
            {
                foreach (var foreignKey in childTable.ForeignKeys.Reverse())
                {
                    if (!string.Equals(
                            foreignKey.ParentTable,
                            tableName,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    var parent = ResolveForeignKeyParent(context.Tables, childTableName, foreignKey);
                    if (!parent.ColumnIndices.Any(assignedColumns.Contains))
                        continue;

                    var oldValues = GetForeignKeyValues(originalRows[position], parent.ColumnIndices);
                    var newValues = GetForeignKeyValues(postUpdateRows[position], parent.ColumnIndices);
                    if (ForeignKeyValuesEqual(parent, oldValues, newValues))
                        continue;

                    ApplyForeignKeyParentAction(
                        context,
                        childTableName,
                        childTable,
                        foreignKey,
                        parent,
                        oldValues,
                        newValues,
                        foreignKey.OnUpdate,
                        tableName,
                        postUpdateRows);
                }
            }
        }
    }

    private void ValidateChildForeignKeys(
        QueryContext context,
        string childTableName,
        EmbeddedTable childTable,
        IReadOnlyList<SqlValue[]> childRows,
        string targetTableName,
        IReadOnlyList<SqlValue[]> targetRows,
        ForeignKeyDefinition? onlyForeignKey = null)
    {
        foreach (var foreignKey in childTable.ForeignKeys.Reverse())
        {
            if (onlyForeignKey is not null && !ReferenceEquals(foreignKey, onlyForeignKey))
                continue;

            var childColumns = ResolveForeignKeyChildColumns(childTable, childTableName, foreignKey);
            var parent = ResolveForeignKeyParent(context.Tables, childTableName, foreignKey);
            var parentRows = string.Equals(parent.TableName, targetTableName, StringComparison.OrdinalIgnoreCase)
                ? targetRows
                : parent.Table.Rows;
            foreach (var childRow in childRows)
            {
                var childValues = GetForeignKeyValues(childRow, childColumns);
                if (childValues.Any(value => value.Kind == SqlValueKind.Null))
                    continue;

                if (!ParentContains(
                        parent,
                        parentRows,
                        childValues,
                        childRow,
                        ReferenceEquals(childTable, parent.Table)))
                    ThrowForeignKeyConstraint(context, foreignKey);
            }
        }
    }

    private void ApplyForeignKeyParentAction(
        QueryContext context,
        string childTableName,
        EmbeddedTable childTable,
        ForeignKeyDefinition foreignKey,
        ForeignKeyParent parent,
        IReadOnlyList<SqlValue> oldParentValues,
        IReadOnlyList<SqlValue>? newParentValues,
        ForeignKeyAction action,
        string targetTableName,
        IReadOnlyList<SqlValue[]> targetRows)
    {
        var matchingRows = FindForeignKeyChildPositions(
            childTable,
            childTableName,
            foreignKey,
            parent,
            oldParentValues);
        if (matchingRows.Count == 0)
            return;

        switch (action)
        {
            case ForeignKeyAction.Cascade when newParentValues is null:
                ExecuteForeignKeyDelete(
                    context,
                    childTableName,
                    childTable,
                    foreignKey,
                    parent,
                    oldParentValues);
                return;
            case ForeignKeyAction.Cascade:
                ExecuteForeignKeyUpdate(
                    context,
                    childTableName,
                    childTable,
                    foreignKey,
                    parent,
                    oldParentValues,
                    ForeignKeyAction.Cascade,
                    newParentValues);
                return;
            case ForeignKeyAction.SetNull:
            case ForeignKeyAction.SetDefault:
                ExecuteForeignKeyUpdate(
                    context,
                    childTableName,
                    childTable,
                    foreignKey,
                    parent,
                    oldParentValues,
                    action,
                    newParentValues: null);
                return;
            case ForeignKeyAction.Restrict:
                throw new EmbeddedSqlException("FOREIGN KEY constraint failed");
            case ForeignKeyAction.NoAction:
                ValidateChildrenReferencingParentValue(
                    context,
                    childTableName,
                    childTable,
                    foreignKey,
                    parent,
                    oldParentValues,
                    targetTableName,
                    targetRows);
                return;
            default:
                throw new InvalidOperationException($"Unknown foreign key action {action}.");
        }
    }

    private void ValidateChildrenReferencingParentValue(
        QueryContext context,
        string childTableName,
        EmbeddedTable childTable,
        ForeignKeyDefinition foreignKey,
        ForeignKeyParent parent,
        IReadOnlyList<SqlValue> oldParentValues,
        string targetTableName,
        IReadOnlyList<SqlValue[]> targetRows)
    {
        var childColumns = ResolveForeignKeyChildColumns(childTable, childTableName, foreignKey);
        var childRows = string.Equals(childTableName, targetTableName, StringComparison.OrdinalIgnoreCase)
            ? targetRows
            : childTable.Rows;
        var parentRows = string.Equals(parent.TableName, targetTableName, StringComparison.OrdinalIgnoreCase)
            ? targetRows
            : parent.Table.Rows;
        foreach (var childRow in childRows)
        {
            var childValues = GetForeignKeyValues(childRow, childColumns);
            if (childValues.Any(value => value.Kind == SqlValueKind.Null)
                || !ValuesMatchParent(parent, oldParentValues, childValues))
            {
                continue;
            }

            if (!ParentContains(
                    parent,
                    parentRows,
                    childValues,
                    childRow,
                    ReferenceEquals(childTable, parent.Table)))
                ThrowForeignKeyConstraint(context, foreignKey);
        }
    }

    private IReadOnlyList<int> FindForeignKeyChildPositions(
        EmbeddedTable childTable,
        string childTableName,
        ForeignKeyDefinition foreignKey,
        ForeignKeyParent parent,
        IReadOnlyList<SqlValue> oldParentValues)
    {
        var childColumns = ResolveForeignKeyChildColumns(childTable, childTableName, foreignKey);
        var positions = new List<int>();
        for (var position = 0; position < childTable.Rows.Count; position++)
        {
            var childValues = GetForeignKeyValues(childTable.Rows[position], childColumns);
            if (childValues.Any(value => value.Kind == SqlValueKind.Null))
                continue;
            if (ValuesMatchParent(parent, oldParentValues, childValues))
                positions.Add(position);
        }

        return positions;
    }

    private void ExecuteForeignKeyDelete(
        QueryContext context,
        string childTableName,
        EmbeddedTable childTable,
        ForeignKeyDefinition foreignKey,
        ForeignKeyParent parent,
        IReadOnlyList<SqlValue> oldParentValues)
    {
        var actionContext = EnterForeignKeyAction(context);
        if (context.PreserveUpsertFail)
            actionContext = actionContext with { TriggerConflictAlgorithm = null };
        try
        {
            _ = ExecuteRowTriggerStatement(
                actionContext,
                triggerContext => PerformForeignKeyDelete(
                    triggerContext,
                    childTableName,
                    childTable,
                    foreignKey,
                    parent,
                    oldParentValues));
        }
        catch (EmbeddedConflictFailException exception) when (actionContext.PreserveUpsertFail)
        {
            throw PromoteUpsertFail(exception, actionContext);
        }
    }

    private ExecutionResult PerformForeignKeyDelete(
        QueryContext triggerContext,
        string childTableName,
        EmbeddedTable childTable,
        ForeignKeyDefinition foreignKey,
        ForeignKeyParent parent,
        IReadOnlyList<SqlValue> oldParentValues)
    {
        var deletedPositions = FindForeignKeyChildPositions(
            childTable,
            childTableName,
            foreignKey,
            parent,
            oldParentValues).ToHashSet();
        if (deletedPositions.Count == 0)
            return ExecutionResult.Empty;

        var beforeTriggers = GetRowTriggers(
            triggerContext,
            childTableName,
            TriggerTiming.Before,
            TriggerEvent.Delete);
        var afterTriggers = GetRowTriggers(
            triggerContext,
            childTableName,
            TriggerTiming.After,
            TriggerEvent.Delete);
        ValidateTriggerPrograms(
            triggerContext,
            childTableName,
            TriggerEvent.Delete,
            beforeTriggers.Concat(afterTriggers));
        var candidates = CaptureTriggerRowIdentities(childTable, deletedPositions);
        var rowsAffected = 0;
        foreach (var identity in candidates)
        {
            var position = FindTriggerRowPosition(childTable, identity);
            if (position < 0)
                continue;
            var row = childTable.Rows[position].ToArray();
            var rowId = childTable.HasRowid ? childTable.RowIds[position] : position + 1;
            var frame = new TriggerRowFrame(
                CreateTriggerRowImage(childTable, row, rowId),
                New: null);
            if (FireRowTriggers(beforeTriggers, frame, triggerContext))
                continue;

            position = FindTriggerRowPosition(childTable, identity);
            if (position < 0)
                continue;
            DeleteTriggerRow(triggerContext, childTableName, childTable, position, row);
            rowsAffected++;
            triggerContext.TriggerState!.Changed = true;
            _ = FireRowTriggers(afterTriggers, frame, triggerContext);
        }

        return new ExecutionResult([], [], rowsAffected, rowsAffected > 0);
    }

    private void ExecuteForeignKeyUpdate(
        QueryContext context,
        string childTableName,
        EmbeddedTable childTable,
        ForeignKeyDefinition foreignKey,
        ForeignKeyParent parent,
        IReadOnlyList<SqlValue> oldParentValues,
        ForeignKeyAction action,
        IReadOnlyList<SqlValue>? newParentValues)
    {
        var actionContext = EnterForeignKeyAction(context) with
        {
            TriggerConflictAlgorithm = context.PreserveUpsertFail
                ? null
                : context.TriggerConflictAlgorithm,
            PreserveUpsertFail = false,
        };
        try
        {
            _ = ExecuteRowTriggerStatement(
                actionContext,
                triggerContext => PerformForeignKeyUpdate(
                    triggerContext,
                    childTableName,
                    childTable,
                    foreignKey,
                    parent,
                    oldParentValues,
                    action,
                    newParentValues));
        }
        catch (EmbeddedConflictFailException exception)
        {
            if (IsFailingTriggerRaise(exception))
            {
                throw;
            }

            throw DemoteUpsertFail(exception, actionContext);
        }
    }

    private static bool IsFailingTriggerRaise(EmbeddedConflictFailException exception)
    {
        Exception? current = exception;
        while (current is EmbeddedConflictFailException)
            current = current.InnerException;

        return current is EmbeddedTriggerRaiseException
        {
            Algorithm: InsertConflictAlgorithm.Fail,
        };
    }

    private static EmbeddedUpsertConflictFailException PromoteUpsertFail(
        EmbeddedConflictFailException exception,
        QueryContext context)
    {
        var conflict = exception.InnerException as EmbeddedSqlException
            ?? new EmbeddedSqlException(
                exception.Message,
                exception.InnerException ?? exception);
        return new EmbeddedUpsertConflictFailException(conflict, context.LastInsertRowId);
    }

    private static EmbeddedStatementAbortException DemoteUpsertFail(
        EmbeddedConflictFailException exception,
        QueryContext context)
    {
        var conflict = exception.InnerException as EmbeddedSqlException
            ?? new EmbeddedSqlException(
                exception.Message,
                exception.InnerException ?? exception);
        return new EmbeddedStatementAbortException(conflict, context.LastInsertRowId);
    }

    private ExecutionResult PerformForeignKeyUpdate(
        QueryContext context,
        string childTableName,
        EmbeddedTable childTable,
        ForeignKeyDefinition foreignKey,
        ForeignKeyParent parent,
        IReadOnlyList<SqlValue> oldParentValues,
        ForeignKeyAction action,
        IReadOnlyList<SqlValue>? newParentValues)
    {
        var updatedPositions = FindForeignKeyChildPositions(
            childTable,
            childTableName,
            foreignKey,
            parent,
            oldParentValues);
        if (updatedPositions.Count == 0)
            return ExecutionResult.Empty;

        var assignments = new List<ColumnAssignment>(foreignKey.ChildColumns.Count);
        for (var position = 0; position < foreignKey.ChildColumns.Count; position++)
        {
            var columnIndex = childTable.GetColumnIndex(foreignKey.ChildColumns[position]);
            var value = action switch
            {
                ForeignKeyAction.Cascade => newParentValues?[position]
                    ?? throw new InvalidOperationException("ON UPDATE CASCADE lost the new parent key."),
                ForeignKeyAction.SetNull => SqlValue.Null,
                ForeignKeyAction.SetDefault => EvaluateForeignKeyDefault(
                    childTable.ColumnDefinitions[columnIndex],
                    context),
                _ => throw new InvalidOperationException($"Foreign key action {action} cannot update child rows."),
            };
            assignments.Add(new ColumnAssignment(
                foreignKey.ChildColumns[position],
                new LiteralExpression(value)));
        }

        var statement = new UpdateStatement(childTableName, assignments, Where: null);
        var plan = PrepareUpdate(statement, childTable, context);
        var updatedColumns = assignments
            .Select(assignment => assignment.Column)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var beforeTriggers = GetRowTriggers(
            context,
            childTableName,
            TriggerTiming.Before,
            TriggerEvent.Update,
            updatedColumns);
        var afterTriggers = GetRowTriggers(
            context,
            childTableName,
            TriggerTiming.After,
            TriggerEvent.Update,
            updatedColumns);
        ValidateTriggerPrograms(
            context,
            childTableName,
            TriggerEvent.Update,
            beforeTriggers.Concat(afterTriggers));
        var candidates = CaptureTriggerRowIdentities(childTable, updatedPositions.ToHashSet());
        var rowsAffected = 0;
        foreach (var identity in candidates)
        {
            var position = FindTriggerRowPosition(childTable, identity);
            if (position < 0)
                continue;
            var original = childTable.Rows[position].ToArray();
            var rowId = childTable.HasRowid ? childTable.RowIds[position] : position + 1;
            var (updated, newRowId) = BuildUpdatedRow(
                statement,
                childTable,
                plan,
                original,
                rowId,
                EmptyParameters,
                context,
                validateCheckConstraints: false);
            var frame = new TriggerRowFrame(
                CreateTriggerRowImage(childTable, original, rowId),
                CreateTriggerRowImage(childTable, updated, newRowId));
            if (FireRowTriggers(beforeTriggers, frame, context))
                continue;

            position = FindTriggerRowPosition(childTable, identity);
            if (position < 0)
                continue;
            ValidateCheckConstraints(
                childTableName,
                childTable,
                updated,
                newRowId,
                EmptyParameters,
                context);
            var rows = childTable.Rows.Select(row => row.ToArray()).ToList();
            var rowIds = childTable.RowIds.Count == childTable.Rows.Count
                ? childTable.RowIds.ToList()
                : Enumerable.Range(1, childTable.Rows.Count).Select(index => (long)index).ToList();
            rows[position] = updated;
            if (childTable.HasRowid)
                rowIds[position] = newRowId;
            CommitUpdates(
                context,
                childTableName,
                childTable,
                childTable.Rows,
                rows,
                rowIds,
                plan,
                [position]);
            rowsAffected++;
            context.TriggerState!.Changed = true;
            _ = FireRowTriggers(afterTriggers, frame, context);
        }

        return new ExecutionResult([], [], rowsAffected, rowsAffected > 0);
    }

    private SqlValue EvaluateForeignKeyDefault(EmbeddedColumn column, QueryContext context)
        => column.DefaultExpression is { } expression
            ? Evaluate(expression, EmptyParameters, row: null, context)
            : column.DefaultValue ?? SqlValue.Null;

    private static QueryContext EnterForeignKeyAction(QueryContext context)
    {
        if (context.ForeignKeyActionDepth >= MaximumForeignKeyActionDepth)
            throw new EmbeddedSqlException("too many levels of trigger recursion");
        return context with { ForeignKeyActionDepth = context.ForeignKeyActionDepth + 1 };
    }

    // A per-mutation FK validator detected a violation on a row it just touched. SQLite
    // defers the throw to the end of the statement so a trigger can repair a transient
    // violation within the same statement, and only rejects violations that persist to
    // statement end. At depth 0 (no trigger) the violation can never be repaired, so throw
    // now; at depth > 0 return and let ExecuteWithForeignKeyStatement's retained-state scan
    // re-check the full catalog image once the statement completes.
    private static void ThrowForeignKeyConstraint(QueryContext context, ForeignKeyDefinition foreignKey)
    {
        if (context.InTransaction
            && (context.DeferForeignKeys || foreignKey.Deferral == ForeignKeyDeferral.InitiallyDeferred))
        {
            return;
        }
        if (context.ForeignKeyStatement is { Depth: > 0 })
            return;

        throw new EmbeddedSqlException("FOREIGN KEY constraint failed");
    }


    private ForeignKeyParent ResolveForeignKeyParent(
        IReadOnlyDictionary<string, EmbeddedTable> tables,
        string childTableName,
        ForeignKeyDefinition foreignKey)
    {
        if (!tables.TryGetValue(foreignKey.ParentTable, out var parent))
            throw new EmbeddedSqlException($"no such table: main.{foreignKey.ParentTable}");
        if (foreignKey.ParentColumns.Count != 0
            && foreignKey.ParentColumns.Count != foreignKey.ChildColumns.Count)
        {
            throw ForeignKeyMismatch(childTableName, foreignKey.ParentTable);
        }

        int[] parentColumns;
        if (foreignKey.ParentColumns.Count == 0)
        {
            if (parent.PrimaryKeyColumns.Count != foreignKey.ChildColumns.Count)
                throw ForeignKeyMismatch(childTableName, foreignKey.ParentTable);
            parentColumns = parent.PrimaryKeyColumns.Select(column => column.Index).ToArray();
        }
        else
        {
            parentColumns = new int[foreignKey.ParentColumns.Count];
            for (var position = 0; position < parentColumns.Length; position++)
            {
                if (!parent.TryGetColumnIndex(foreignKey.ParentColumns[position], out parentColumns[position]))
                    throw ForeignKeyMismatch(childTableName, foreignKey.ParentTable);
            }
        }

        if (PrimaryKeyMatches(parent, parentColumns))
        {
            return new ForeignKeyParent(
                parent,
                foreignKey.ParentTable,
                parentColumns,
                parentColumns
                    .Select((column, position) =>
                        parent.TableLevelPrimaryKey?[position].Collation
                        ?? parent.ColumnDefinitions[column].Collation)
                    .ToArray());
        }

        var uniqueIndex = parent.Indexes.FirstOrDefault(index =>
            index.Unique
            && !index.IsPartial
            && index.Columns.All(column => !column.IsExpression)
            && index.Columns.Count == parentColumns.Length
            && index.Columns.Select(column => column.ColumnIndex).SequenceEqual(parentColumns)
            && index.Columns.Select(column => NormalizeCollation(column.Collation)).SequenceEqual(
                parentColumns.Select(column => NormalizeCollation(parent.ColumnDefinitions[column].Collation)),
                StringComparer.OrdinalIgnoreCase));
        if (uniqueIndex is not null)
        {
            return new ForeignKeyParent(
                parent,
                foreignKey.ParentTable,
                parentColumns,
                uniqueIndex.Columns.Select(column => column.Collation).ToArray());
        }

        throw ForeignKeyMismatch(childTableName, foreignKey.ParentTable);
    }

    private static bool PrimaryKeyMatches(EmbeddedTable parent, IReadOnlyList<int> columns)
        => parent.PrimaryKeyColumns.Count == columns.Count
            && parent.PrimaryKeyColumns.Select(column => column.Index).SequenceEqual(columns);

    private static string NormalizeCollation(string? collation)
        => collation ?? "BINARY";

    private static int[] ResolveForeignKeyChildColumns(
        EmbeddedTable childTable,
        string childTableName,
        ForeignKeyDefinition foreignKey)
    {
        var childColumns = new int[foreignKey.ChildColumns.Count];
        for (var position = 0; position < childColumns.Length; position++)
        {
            if (!childTable.TryGetColumnIndex(foreignKey.ChildColumns[position], out childColumns[position]))
                throw ForeignKeyMismatch(childTableName, foreignKey.ParentTable);
        }

        return childColumns;
    }

    private static SqlValue[] GetForeignKeyValues(SqlValue[] row, IReadOnlyList<int> columns)
        => columns.Select(column => row[column]).ToArray();

    // Per-statement hash probe of a parent table's FK key columns, built once per
    // statement and reused across every child row validated against that parent so an
    // N-row bulk insert no longer scans all parentRows per child row (the O(N^2) that
    // turned Northwind bulk inserts into minute-long hangs). Keyed by parent identity +
    // FK column/collation signature and invalidated by the parent's RowStore revision so
    // a trigger mutating the parent mid-statement rebuilds against the current rows.
    private readonly Dictionary<ForeignKeyParentProbeKey, ForeignKeyParentProbe> _foreignKeyParentProbes = new();

    private bool ParentContains(
        ForeignKeyParent parent,
        IReadOnlyList<SqlValue[]> parentRows,
        IReadOnlyList<SqlValue> childValues,
        SqlValue[]? childRow = null,
        bool selfReferential = false)
    {
        // Self-referential FKs need the per-row identity skip (a row can't be its own
        // parent mid-insert) and parentRows may be the post-mutation child rows rather
        // than a RowStore, so fall back to the linear scan for that shape.
        if (selfReferential || parentRows is not RowStore parentRowStore)
            return ParentContainsLinear(parent, parentRows, childValues, childRow, selfReferential);

        // Fast path: hash the parent's FK key columns once and probe per child row, turning
        // N×parentRows comparisons into parentRows + N×O(1). Bucket hits are confirmed with
        // the exact ValuesMatchParent comparison, so the probe never yields a false positive.
        // The child value is coerced to the parent column's affinity first (exactly as
        // ValuesMatchParent does) and canonicalized with the same #8 equi-join key builder
        // proved sound for Compare-equality, so matching values always share a bucket.
        // Custom/overridden collations and unhashable values fall back to the linear scan.
        if (!TryGetForeignKeyParentProbe(parent, parentRowStore, out var probe))
            return ParentContainsLinear(parent, parentRows, childValues, childRow, selfReferential);

        var key = CanonicalizeForeignKeyChildKey(parent, childValues);
        if (key is null || !probe.Buckets.TryGetValue(key, out var candidates))
            return false;

        foreach (var parentRow in candidates)
        {
            if (ValuesMatchParent(parent, GetForeignKeyValues(parentRow, parent.ColumnIndices), childValues))
                return true;
        }
        return false;
    }

    private bool ParentContainsLinear(
        ForeignKeyParent parent,
        IReadOnlyList<SqlValue[]> parentRows,
        IReadOnlyList<SqlValue> childValues,
        SqlValue[]? childRow,
        bool selfReferential)
    {
        foreach (var parentRow in parentRows)
        {
            var parentValues = GetForeignKeyValues(parentRow, parent.ColumnIndices);
            if (selfReferential && ReferenceEquals(parentRow, childRow))
            {
                if (parentValues.SequenceEqual(childValues))
                    return true;
                continue;
            }
            if (ValuesMatchParent(parent, parentValues, childValues))
                return true;
        }
        return false;
    }

    private bool TryGetForeignKeyParentProbe(
        ForeignKeyParent parent,
        RowStore parentRowStore,
        [System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out ForeignKeyParentProbe? probe)
    {
        var probeKey = new ForeignKeyParentProbeKey(parent.Table, BuildForeignKeyColumnSignature(parent));
        if (!_foreignKeyParentProbes.TryGetValue(probeKey, out probe))
        {
            probe = new ForeignKeyParentProbe();
            if (!BuildForeignKeyParentProbe(parent, parentRowStore, probe))
            {
                probe = null;
                return false;
            }
            _foreignKeyParentProbes[probeKey] = probe;
            return true;
        }

        if (probe.Revision == parentRowStore.Revision)
            return true;

        // Parent mutated since the probe was built (e.g. a trigger inserted into the
        // parent mid-statement): rebuild against the current rows.
        probe.Buckets.Clear();
        if (!BuildForeignKeyParentProbe(parent, parentRowStore, probe))
        {
            _foreignKeyParentProbes.Remove(probeKey);
            probe = null;
            return false;
        }
        return true;
    }

    private bool BuildForeignKeyParentProbe(
        ForeignKeyParent parent,
        RowStore parentRowStore,
        ForeignKeyParentProbe probe)
    {
        probe.Revision = parentRowStore.Revision;
        for (var position = 0; position < parent.ColumnIndices.Count; position++)
        {
            var collation = parent.Collations[position] ?? "BINARY";
            if (!IsHashableJoinKeyCollation(collation) || IsUnsafeCompiledCollation(collation))
                return false;
        }

        foreach (var parentRow in parentRowStore)
        {
            // A parent row with NULL in any FK column can never match a non-NULL child
            // (SQLite: NULL is not equal to anything), so skip it rather than bail the
            // whole probe — keeps the fast path for tables with a few NULL parent keys.
            var key = CanonicalizeForeignKeyParentRow(parent, parentRow);
            if (key is null)
                continue;
            if (!probe.Buckets.TryGetValue(key, out var bucket))
            {
                bucket = new List<SqlValue[]>();
                probe.Buckets[key] = bucket;
            }
            bucket.Add(parentRow);
        }
        return true;
    }

    private static string BuildForeignKeyColumnSignature(ForeignKeyParent parent)
    {
        var sb = new StringBuilder();
        for (var position = 0; position < parent.ColumnIndices.Count; position++)
            sb.Append(parent.ColumnIndices[position]).Append(',').Append(parent.Collations[position] ?? string.Empty).Append('|');
        return sb.ToString();
    }

    private string? CanonicalizeForeignKeyParentRow(ForeignKeyParent parent, SqlValue[] parentRow)
    {
        string? key = null;
        for (var position = 0; position < parent.ColumnIndices.Count; position++)
        {
            var value = parentRow[parent.ColumnIndices[position]];
            var collation = parent.Collations[position] ?? "BINARY";
            var segment = EquiJoinHashIndex.CanonicalizeJoinKeyValue(value, convertTextToNumeric: false, convertNumericToText: false, collation);
            if (segment is null)
                return null;
            key = key is null
                ? segment.Length + ":" + segment
                : key + segment.Length + ":" + segment;
        }
        return key;
    }

    private string? CanonicalizeForeignKeyChildKey(ForeignKeyParent parent, IReadOnlyList<SqlValue> childValues)
    {
        string? key = null;
        for (var position = 0; position < parent.ColumnIndices.Count; position++)
        {
            var parentColumn = parent.ColumnIndices[position];
            var coerced = parent.Table.CoerceColumnAffinity(
                parent.Table.ColumnDefinitions[parentColumn], childValues[position]);
            var collation = parent.Collations[position] ?? "BINARY";
            var segment = EquiJoinHashIndex.CanonicalizeJoinKeyValue(coerced, convertTextToNumeric: false, convertNumericToText: false, collation);
            if (segment is null)
                return null;
            key = key is null
                ? segment.Length + ":" + segment
                : key + segment.Length + ":" + segment;
        }
        return key;
    }

    private sealed class ForeignKeyParentProbe
    {
        public long Revision { get; set; } = -1;

        public Dictionary<string, List<SqlValue[]>> Buckets { get; } = new(StringComparer.Ordinal);
    }

    private readonly record struct ForeignKeyParentProbeKey(EmbeddedTable ParentTable, string ColumnSignature)
    {
        public bool Equals(ForeignKeyParentProbeKey other)
            => ReferenceEquals(ParentTable, other.ParentTable)
                && string.Equals(ColumnSignature, other.ColumnSignature, StringComparison.Ordinal);

        public override int GetHashCode()
            => HashCode.Combine(RuntimeHelpers.GetHashCode(ParentTable), StringComparer.Ordinal.GetHashCode(ColumnSignature));
    }

    private bool ValuesMatchParent(
        ForeignKeyParent parent,
        IReadOnlyList<SqlValue> parentValues,
        IReadOnlyList<SqlValue> childValues)
    {
        for (var position = 0; position < parent.ColumnIndices.Count; position++)
        {
            var parentColumn = parent.ColumnIndices[position];
            var comparableChildValue = parent.Table.CoerceColumnAffinity(
                parent.Table.ColumnDefinitions[parentColumn],
                childValues[position]);
            if (Compare(parentValues[position], comparableChildValue, parent.Collations[position]) != 0)
                return false;
        }

        return true;
    }

    private bool ForeignKeyValuesEqual(
        ForeignKeyParent parent,
        IReadOnlyList<SqlValue> left,
        IReadOnlyList<SqlValue> right)
    {
        for (var position = 0; position < parent.ColumnIndices.Count; position++)
        {
            if (Compare(left[position], right[position], parent.Collations[position]) != 0)
                return false;
        }

        return true;
    }

    internal HashSet<ForeignKeyViolation> CollectForeignKeyViolations(
        IReadOnlyDictionary<string, EmbeddedTable> tables,
        bool includeImmediate)
    {
        var violations = new HashSet<ForeignKeyViolation>();
        foreach (var (childTableName, childTable) in tables)
        {
            for (var foreignKeyIndex = 0; foreignKeyIndex < childTable.ForeignKeys.Count; foreignKeyIndex++)
            {
                var foreignKey = childTable.ForeignKeys[foreignKeyIndex];
                var declaredDeferred = foreignKey.Deferral == ForeignKeyDeferral.InitiallyDeferred;
                if (!includeImmediate && !declaredDeferred)
                    continue;

                ForeignKeyParent? parent = null;
                int[] childColumns;
                try
                {
                    childColumns = ResolveForeignKeyChildColumns(childTable, childTableName, foreignKey);
                    if (tables.ContainsKey(foreignKey.ParentTable))
                        parent = ResolveForeignKeyParent(tables, childTableName, foreignKey);
                }
                catch (EmbeddedSqlException exception) when (
                    exception.Message.StartsWith("foreign key mismatch", StringComparison.Ordinal))
                {
                    continue;
                }

                for (var rowIndex = 0; rowIndex < childTable.Rows.Count; rowIndex++)
                {
                    var childValues = GetForeignKeyValues(childTable.Rows[rowIndex], childColumns);
                    if (childValues.Any(value => value.Kind == SqlValueKind.Null)
                        || (parent is not null && ParentContains(
                            parent,
                            parent.Table.Rows,
                            childValues,
                            childTable.Rows[rowIndex],
                            ReferenceEquals(childTable, parent.Table))))
                    {
                        continue;
                    }

                    violations.Add(new ForeignKeyViolation(
                        childTableName,
                        foreignKeyIndex,
                        BuildForeignKeyRowIdentity(childTable, rowIndex),
                        string.Join("|", childValues.Select(EncodeForeignKeyValue)),
                        declaredDeferred));
                }
            }
        }

        return violations;
    }

    private static string BuildForeignKeyRowIdentity(EmbeddedTable table, int rowIndex)
    {
        if (table.HasRowid && rowIndex < table.RowIds.Count)
            return "R:" + table.RowIds[rowIndex].ToString(CultureInfo.InvariantCulture);

        if (table.PrimaryKeyColumns.Count == 0)
            throw new InvalidOperationException($"WITHOUT ROWID table {table.Name} lost its primary key.");

        return "K:" + string.Join(
            "|",
            table.PrimaryKeyColumns.Select(column => EncodeForeignKeyValue(table.Rows[rowIndex][column.Index])));
    }

    private static string EncodeForeignKeyValue(SqlValue value)
        => value.Kind switch
        {
            SqlValueKind.Null => "N",
            SqlValueKind.Integer => "I" + value.AsInteger().ToString(CultureInfo.InvariantCulture),
            SqlValueKind.Real => "R" + BitConverter.DoubleToInt64Bits(value.AsReal()).ToString("X16", CultureInfo.InvariantCulture),
            SqlValueKind.Text => "T" + Convert.ToHexString(Encoding.UTF8.GetBytes(value.AsText())),
            SqlValueKind.Blob => "B" + Convert.ToHexString(value.AsBlob().Span),
            _ => throw new InvalidOperationException($"Unknown SQL value kind {value.Kind}."),
        };

    private static bool IsBinaryCollation(string? collation)
        => collation is null || string.Equals(collation, "BINARY", StringComparison.OrdinalIgnoreCase);

    private static bool IsStreamingSafeDistinctCollation(string? collation)
        => IsBinaryCollation(collation)
            || string.Equals(collation, "NOCASE", StringComparison.OrdinalIgnoreCase)
            || string.Equals(collation, "RTRIM", StringComparison.OrdinalIgnoreCase);

    private static EmbeddedSqlException ForeignKeyMismatch(string childTable, string parentTable)
        => new($"foreign key mismatch - \"{childTable}\" referencing \"{parentTable}\"");

    private sealed record ForeignKeyParent(
        EmbeddedTable Table,
        string TableName,
        IReadOnlyList<int> ColumnIndices,
        IReadOnlyList<string?> Collations);

    // Mutable per-statement UPDATE plan: the resolved column assignments and any rowid
    // (or rowid-alias) reassignment.
    private sealed record ResolvedAssignment(
        int Index,
        Expression Value,
        int ValueIndex,
        int ValueCount);

    private sealed class UpdatePlan
    {
        public required int AliasIndex { get; init; }

        public required List<ResolvedAssignment> ColumnAssignments { get; init; }

        public required ResolvedAssignment? RowidAssignment { get; init; }
    }

    // Coerces a value assigned to a rowid (or rowid-alias column) into an integer, applying
    // SQLite INTEGER affinity, and rejects anything that cannot be an integer rowid.
    private static long CoerceRowidOrThrow(SqlValue value)
        => EmbeddedTable.TryCoerceRowid(value, out var rowid)
            ? rowid
            : throw new EmbeddedSqlException("datatype mismatch");

    // Rejects duplicate rowids produced by an UPDATE, using the same qualified message
    // SQLite reports for a rowid-alias or hidden-rowid collision.
    private static void ValidateRowIdsUnique(string tableName, EmbeddedTable table, List<long> rowIds, int aliasIndex)
    {
        var seen = new HashSet<long>(rowIds.Count);
        foreach (var rowid in rowIds)
        {
            if (!seen.Add(rowid))
            {
                var column = aliasIndex >= 0 ? table.Columns[aliasIndex] : "rowid";
                var conflictAlgorithm = aliasIndex >= 0
                    ? table.RowidAliasConflictAlgorithm
                    : null;
                throw new EmbeddedSqlException(
                    $"UNIQUE constraint failed: {tableName}.{column}",
                    conflictAlgorithm);
            }
        }
    }

    // Column-level UNIQUE and PRIMARY KEY constraints are not represented in Indexes. They
    // still use the column's declared collation, so validate them with the same comparer as
    // explicit UNIQUE indexes rather than SqlValue's binary HashSet equality.
    private void ValidateColumnUniqueConstraints(EmbeddedTable table, IReadOnlyList<SqlValue[]> rows)
    {
        for (var columnIndex = 0; columnIndex < table.ColumnDefinitions.Length; columnIndex++)
        {
            if ((table.WithoutRowid || table.TableLevelPrimaryKey is not null)
                && table.IsPrimaryKeyColumn(columnIndex))
            {
                continue;
            }

            var column = table.ColumnDefinitions[columnIndex];
            if (!column.PrimaryKey)
                continue;
            if (table.Indexes.Any(index =>
                    index.Origin == EmbeddedIndexOrigin.PrimaryKey
                    && index.Columns.Count == 1
                    && index.Columns[0].ColumnIndex == columnIndex))
            {
                continue;
            }

            var collation = column.Collation;
            if (IsUniqueKeyCollationHashable(collation))
            {
                var seen = new Dictionary<string, List<SqlValue>>(StringComparer.Ordinal);
                foreach (var row in rows)
                {
                    var value = row[columnIndex];
                    if (value.Kind == SqlValueKind.Null)
                        continue;

                    var key = EquiJoinHashIndex.CanonicalizeJoinKeyValue(
                        value,
                        convertTextToNumeric: false,
                        convertNumericToText: false,
                        collation ?? "BINARY");
                    if (key is null)
                        continue;

                    if (seen.TryGetValue(key, out var bucket))
                    {
                        foreach (var existing in bucket)
                        {
                            if (Compare(existing, value, collation ?? "BINARY") == 0)
                            {
                                throw new EmbeddedSqlException(
                                    $"UNIQUE constraint failed: {table.Name}.{column.Name}",
                                    column.PrimaryKeyConflictAlgorithm);
                            }
                        }

                        bucket.Add(value);
                    }
                    else
                    {
                        seen[key] = new List<SqlValue> { value };
                    }
                }

                continue;
            }

            var values = new List<SqlValue>();
            foreach (var row in rows)
            {
                var value = row[columnIndex];
                if (value.Kind == SqlValueKind.Null)
                    continue;

                if (values.Any(existing => Compare(existing, value, column.Collation) == 0))
                    throw new EmbeddedSqlException(
                        $"UNIQUE constraint failed: {table.Name}.{column.Name}",
                        column.PrimaryKeyConflictAlgorithm);

                values.Add(value);
            }
        }
    }

    private void ValidateUniqueIndexes(string tableName, EmbeddedTable table, IReadOnlyList<SqlValue[]> rows)
    {
        foreach (var index in table.Indexes)
        {
            if (index.Unique)
                ValidateUniqueIndex(tableName, table, index, rows);
            else
                ValidateIndexExpressions(table, index, rows);
        }
    }

    private void ValidateIndexExpressions(
        EmbeddedTable table,
        EmbeddedIndex index,
        IReadOnlyList<SqlValue[]> rows)
    {
        foreach (var row in rows)
        {
            if (!IndexExpressionSemantics.Qualifies(
                    index,
                    table,
                    row,
                    rowId: null,
                    EvaluateIndexExpression))
            {
                continue;
            }

            _ = IndexExpressionSemantics.ProjectKey(
                index,
                table,
                row,
                rowId: null,
                EvaluateIndexExpression);
        }
    }

    private void ValidateUniqueIndex(
        string tableName,
        EmbeddedTable table,
        EmbeddedIndex index,
        IReadOnlyList<SqlValue[]> rows)
    {
        var indexCollations = index.Columns
            .Select(column => (string?)IndexExpressionSemantics.GetCollationName(table, column))
            .ToArray();
        var hashable = indexCollations.All(IsUniqueKeyCollationHashable);

        if (hashable)
        {
            var seen = new Dictionary<string, List<SqlValue[]>>(StringComparer.Ordinal);
            foreach (var row in rows)
            {
                if (!IndexExpressionSemantics.Qualifies(
                        index,
                        table,
                        row,
                        rowId: null,
                        EvaluateIndexExpression))
                    continue;

                var key = IndexExpressionSemantics.ProjectKey(
                    index,
                    table,
                    row,
                    rowId: null,
                    EvaluateIndexExpression);
                // SQLite treats NULLs in a UNIQUE index as distinct, so such rows never conflict.
                if (key.Any(value => value.Kind == SqlValueKind.Null))
                    continue;

                var canonicalKey = BuildUniqueCanonicalKeyFromValues(key, indexCollations);
                if (canonicalKey is null)
                {
                    hashable = false;
                    break;
                }

                if (seen.TryGetValue(canonicalKey, out var bucket))
                {
                    foreach (var existing in bucket)
                    {
                        var conflict = true;
                        for (var column = 0; column < index.Columns.Count; column++)
                        {
                            if (Compare(
                                    existing[column],
                                    key[column],
                                    IndexExpressionSemantics.GetCollationName(table, index.Columns[column])) != 0)
                            {
                                conflict = false;
                                break;
                            }
                        }

                        if (conflict)
                        {
                            var message = index.Columns.Any(column => column.IsExpression)
                                ? $"UNIQUE constraint failed: index '{index.Name}'"
                                : "UNIQUE constraint failed: "
                                    + string.Join(", ", index.Columns.Select(column => $"{tableName}.{column.Name}"));
                            throw new EmbeddedSqlException(
                                message,
                                index.ConflictAlgorithm);
                        }
                    }

                    bucket.Add(key);
                }
                else
                {
                    seen[canonicalKey] = new List<SqlValue[]> { key };
                }
            }

            if (hashable)
                return;
        }

        var seenKeys = new List<SqlValue[]>();
        foreach (var row in rows)
        {
            if (!IndexExpressionSemantics.Qualifies(
                    index,
                    table,
                    row,
                    rowId: null,
                    EvaluateIndexExpression))
                continue;

            var key = IndexExpressionSemantics.ProjectKey(
                index,
                table,
                row,
                rowId: null,
                EvaluateIndexExpression);
            var hasNull = key.Any(value => value.Kind == SqlValueKind.Null);

            // SQLite treats NULLs in a UNIQUE index as distinct, so such rows never conflict.
            if (hasNull)
                continue;

            foreach (var existing in seenKeys)
            {
                var conflict = true;
                for (var column = 0; column < index.Columns.Count; column++)
                {
                    if (Compare(
                            existing[column],
                            key[column],
                            IndexExpressionSemantics.GetCollationName(table, index.Columns[column])) != 0)
                    {
                        conflict = false;
                        break;
                    }
                }

                if (conflict)
                {
                    var message = index.Columns.Any(column => column.IsExpression)
                        ? $"UNIQUE constraint failed: index '{index.Name}'"
                        : "UNIQUE constraint failed: "
                            + string.Join(", ", index.Columns.Select(column => $"{tableName}.{column.Name}"));
                    throw new EmbeddedSqlException(
                        message,
                        index.ConflictAlgorithm);
                }
            }

            seenKeys.Add(key);
        }
    }

    private bool RowsConflictOnIndex(
        EmbeddedTable table,
        EmbeddedIndex index,
        SqlValue[] existing,
        SqlValue[] candidate)
    {
        if (!IndexExpressionSemantics.Qualifies(
                index,
                table,
                existing,
                rowId: null,
                EvaluateIndexExpression)
            || !IndexExpressionSemantics.Qualifies(
                index,
                table,
                candidate,
                rowId: null,
                EvaluateIndexExpression))
        {
            return false;
        }

        var existingKey = IndexExpressionSemantics.ProjectKey(
            index,
            table,
            existing,
            rowId: null,
            EvaluateIndexExpression);
        var candidateKey = IndexExpressionSemantics.ProjectKey(
            index,
            table,
            candidate,
            rowId: null,
            EvaluateIndexExpression);
        for (var position = 0; position < index.Columns.Count; position++)
        {
            if (existingKey[position].Kind == SqlValueKind.Null
                || candidateKey[position].Kind == SqlValueKind.Null
                || Compare(
                    existingKey[position],
                    candidateKey[position],
                    IndexExpressionSemantics.GetCollationName(table, index.Columns[position])) != 0)
            {
                return false;
            }
        }

        return true;
    }

    // Superseded by the row-frame trigger implementation below.
#if false
    private ExecutionResult ExecuteDelete(
        DeleteStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        var beforeTriggers = GetMatchingTriggers(
            context,
            statement.TableName,
            TriggerEvent.Delete,
            TriggerTiming.Before);
        var afterTriggers = GetMatchingTriggers(
            context,
            statement.TableName,
            TriggerEvent.Delete,
            TriggerTiming.After);
        if (beforeTriggers.Count > 0 || afterTriggers.Count > 0)
        {
            return context.ForeignKeysEnabled
                ? ExecuteWithForeignKeyStatement(
                    context,
                    () => ExecuteDeleteWithRowTriggers(
                        statement,
                        parameters,
                        context,
                        beforeTriggers,
                        afterTriggers))
                : ExecuteDeleteWithRowTriggers(
                    statement,
                    parameters,
                    context,
                    beforeTriggers,
                    afterTriggers);
        }

        return ExecuteWithTriggers(
            statement.TableName,
            TriggerEvent.Delete,
            context,
            () => PerformDelete(statement, parameters, context));
    }

    private ExecutionResult ExecuteDeleteWithRowTriggers(
        DeleteStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        IReadOnlyList<TriggerDefinition> beforeTriggers,
        IReadOnlyList<TriggerDefinition> afterTriggers)
    {
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");

        ValidateTableReturning(statement.Returning, statement.TableName, table, context);
        var selectedPositions = statement.Limit is null
            ? null
            : SelectLimitedDmlPositions(
                statement.TargetQualifier,
                table,
                statement.Where,
                statement.EffectiveOrderBy,
                statement.Limit,
                statement.Offset,
                [],
                statement.Returning,
                parameters,
                context);
        var selectedRowIds = new List<long>();
        for (var position = 0; position < table.Rows.Count; position++)
        {
            var row = table.Rows[position];
            var rowId = table.RowIds[position];
            var source = new SourceRow(
                table.Columns,
                row,
                BuildQualifiedColumns(statement.TableName, table.Columns),
                RowId: table.HasRowid ? rowId : null,
                RowIdQualifier: statement.TableName,
                ColumnDefinitions: table.ColumnDefinitions,
                QualifiedColumnDefinitions: BuildQualifiedColumnDefinitions(
                    statement.TableName,
                    table.ColumnDefinitions));
            var selected = selectedPositions is not null
                ? selectedPositions.Contains(position)
                : statement.Where is null || IsTrue(Evaluate(statement.Where, parameters, source, context));
            if (selected)
                selectedRowIds.Add(rowId);
        }

        var backup = CloneTablesShallow(context.Tables);
        var deletedRows = new List<SqlValue[]>();
        var deletedRowIds = new List<long>();
        try
        {
            foreach (var selectedRowId in selectedRowIds)
            {
                var position = table.RowIds.IndexOf(selectedRowId);
                if (position < 0)
                    continue;

                var deletedRow = table.Rows[position].ToArray();
                var frame = new TriggerRowFrame(
                    deletedRow,
                    table.HasRowid ? selectedRowId : null,
                    null,
                    null);
                if (beforeTriggers.Count > 0 && FireTriggers(beforeTriggers, context, frame))
                    continue;

                position = table.RowIds.IndexOf(selectedRowId);
                if (position < 0)
                    continue;
                var originalRows = table.Rows.Select(row => row.ToArray()).ToArray();
                deletedRow = table.Rows[position].ToArray();
                table.Rows.RemoveAt(position);
                table.RowIds.RemoveAt(position);
                ValidateForeignKeysAfterDelete(
                    context,
                    statement.TableName,
                    table,
                    originalRows,
                    table.Rows,
                    [deletedRow]);
                if (table.HasRowid)
                    RecordBlobMutation(statement.TableName, selectedRowId);
                context.ReportRowChange(
                    SqliteChangeOperation.Delete,
                    statement.TableName,
                    table,
                    selectedRowId);
                deletedRows.Add(deletedRow);
                deletedRowIds.Add(selectedRowId);
                if (afterTriggers.Count > 0)
                    _ = FireTriggers(afterTriggers, context, frame);
            }
        }
        catch (EmbeddedTriggerRaiseException exception)
            when (exception.Algorithm == InsertConflictAlgorithm.Fail)
        {
            throw new EmbeddedConflictFailException(exception, GetLastInsertRowId(context));
        }
        catch (EmbeddedTriggerRaiseException exception)
            when (exception.Algorithm == InsertConflictAlgorithm.Rollback)
        {
            RestoreTables(context.Tables, backup);
            throw new EmbeddedConflictRollbackException(exception, GetLastInsertRowId(context));
        }
        catch (EmbeddedConflictFailException)
        {
            throw;
        }
        catch (EmbeddedConflictRollbackException)
        {
            RestoreTables(context.Tables, backup);
            throw;
        }
        catch
        {
            RestoreTables(context.Tables, backup);
            throw;
        }

        if (statement.Returning is not null)
        {
            try
            {
                return BuildReturningResult(
                    statement.Returning,
                    statement.TableName,
                    table,
                    deletedRows,
                    deletedRowIds,
                    deletedRows.Count,
                    deletedRows.Count > 0,
                    parameters,
                    context);
            }
            catch
            {
                RestoreTables(context.Tables, backup);
                throw;
            }
        }

        return new ExecutionResult([], [], deletedRows.Count, deletedRows.Count > 0);
    }

#endif
    private ExecutionResult ExecuteDelete(
        DeleteStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        ValidateForeignKeyActionTriggerPrograms(
            context,
            statement.TableName,
            TriggerEvent.Delete);
        var hasForeignKeyActionTriggers = HasForeignKeyActionTriggers(
            context,
            statement.TableName,
            TriggerEvent.Delete);
        if (context.Views?.ContainsKey(statement.TableName) == true
            || HasRowTriggers(context, statement.TableName, TriggerEvent.Delete)
            || hasForeignKeyActionTriggers)
        {
            return ExecuteRowTriggeredDelete(statement, parameters, context);
        }

        return ExecuteWithTriggers(
            statement.TableName,
            TriggerEvent.Delete,
            context,
            () => PerformDelete(statement, parameters, context));
    }

    private ExecutionResult PerformDelete(
        DeleteStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        context = EnterCollationSource(
            context,
            new NamedTableSource(statement.TableName, statement.Alias));
        if (CanCompileDml(context)
            && TryCompileDelete(statement, parameters, context, out var compiled, out var columns, out var hasReturning))
            return RunCompiledDml(compiled, columns, hasReturning, parameters);

        return PerformDeleteEvaluated(statement, parameters, context);
    }

    // Compiled DML reports only an aggregate affected-row count; live blob handles need
    // the evaluator's matched rowids to expire only when their own row is mutated. A cancelable
    // execution also stays evaluator-owned because the current VDBE loop has no cancellation opcode.
    private bool CanCompileDml(QueryContext context)
        => !context.CancellationToken.CanBeCanceled
            && !context.ForeignKeysEnabled
            && !HasOpenBlobHandles;

    private bool CanRouteInsertThroughCompiler(InsertStatement statement, QueryContext context)
        => CanCompileDml(context)
            && statement.ConflictAlgorithm is null
            && statement.Upsert is null
            && (!context.Tables.TryGetValue(statement.TableName, out var table)
                || !table.HasNonDefaultConflictAlgorithms);

    private bool CanRouteUpdateThroughCompiler(UpdateStatement statement, QueryContext context)
        => CanCompileDml(context)
            && (!context.Tables.TryGetValue(statement.TableName, out var table)
                || (table.PrimaryKeyColumns.Count == 0
                    && !table.Indexes.Any(index => index.Unique)
                    && !table.HasNonDefaultConflictAlgorithms));

    private ExecutionResult PerformDeleteEvaluated(
        DeleteStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (!context.Tables.TryGetValue(statement.TableName, out var table))
            throw new EmbeddedSqlException($"no such table: {statement.TableName}");

        var selectedPositions = statement.Limit is null
            ? null
            : SelectLimitedDmlPositions(
                statement.TargetQualifier,
                table,
                statement.Where,
                statement.EffectiveOrderBy,
                statement.Limit,
                statement.Offset,
                [],
                statement.Returning,
                parameters,
                context);
        var rows = new List<SqlValue[]>(table.Rows.Count);
        var rowIds = new List<long>(table.Rows.Count);
        var deletedRows = new List<SqlValue[]>();
        var deletedRowIds = new List<long>();
        var rowsAffected = 0;
        for (var position = 0; position < table.Rows.Count; position++)
        {
            var row = table.Rows[position];
            var rowid = position < table.RowIds.Count ? table.RowIds[position] : position + 1;
            var source = CreateDmlTargetRow(table, statement.TargetQualifier, row, rowid);
            var shouldDelete = selectedPositions is not null
                ? selectedPositions.Contains(position)
                : statement.Where is null || IsTrue(Evaluate(statement.Where, parameters, source, context));
            if (shouldDelete)
            {
                rowsAffected++;
                deletedRows.Add(row);
                deletedRowIds.Add(rowid);
                continue;
            }

            rows.Add(row);
            rowIds.Add(rowid);
        }

        var originalRows = table.Rows.ToArray();
        var returningResult = statement.Returning is null
            ? null
            : BuildReturningResult(
                statement.Returning,
                statement.TableName,
                table,
                deletedRows,
                deletedRowIds,
                rowsAffected,
                rowsAffected > 0,
                parameters,
                context);
        table.Rows.Clear();
        table.Rows.AddRange(rows);
        table.RowIds.Clear();
        table.RowIds.AddRange(rowIds);
        if (rowsAffected > 0)
        {
            ValidateForeignKeysAfterDelete(
                context,
                statement.TableName,
                table,
                originalRows,
                table.Rows,
                deletedRows);
        }
        if (table.HasRowid)
        {
            foreach (var rowId in deletedRowIds)
                RecordBlobMutation(statement.TableName, rowId);
        }

        foreach (var rowId in deletedRowIds)
            context.ReportRowChange(SqliteChangeOperation.Delete, statement.TableName, table, rowId);
        if (statement.Returning is not null)
            return returningResult!;

        return new ExecutionResult([], [], rowsAffected, rowsAffected > 0);
    }

    // Builds the result set produced by a RETURNING clause. Each projection is evaluated
    // against the affected row (new values for INSERT/UPDATE, old values for DELETE), the
    // same rows the statement committed, so RETURNING observes exactly what changed.
    private ExecutionResult BuildReturningResult(
        IReadOnlyList<Projection> returning,
        string tableName,
        EmbeddedTable table,
        IReadOnlyList<SqlValue[]> affectedRows,
        IReadOnlyList<long> affectedRowIds,
        int rowsAffected,
        bool changed,
        SqlValue[] parameters,
        QueryContext context,
        long? lastInsertRowId = null,
        IReadOnlyList<long?>? rowFailureLastInsertRowIds = null)
    {
        var outputColumns = BuildOutputColumns(tableName, table.Columns);

        foreach (var projection in returning)
        {
            if (projection.Expression is QualifiedStarExpression)
                throw new EmbeddedSqlException("RETURNING may not use TABLE.* wildcards");
            if (projection.Expression is StarExpression)
                continue;
            if (ContainsAggregate(projection.Expression) || ContainsWindowFunction(projection.Expression))
                throw new EmbeddedSqlException("aggregate and window functions are not allowed in RETURNING");
        }

        var columnNames = GetColumnNames(returning, outputColumns, outputColumns);
        var resultRows = new List<SqlValue[]>(affectedRows.Count);
        var savedLastInsertRowId = GetLastInsertRowId(context);
        try
        {
            for (var rowIndex = 0; rowIndex < affectedRows.Count; rowIndex++)
            {
                var rowValues = affectedRows[rowIndex];
                var source = new SourceRow(
                    table.Columns,
                    rowValues,
                    BuildQualifiedColumns(tableName, table.Columns),
                    RowId: table.HasRowid && rowIndex < affectedRowIds.Count ? affectedRowIds[rowIndex] : null,
                    RowIdQualifier: tableName,
                    ColumnDefinitions: table.ColumnDefinitions);
                var evaluationContext = rowFailureLastInsertRowIds is not null
                    && rowIndex < rowFailureLastInsertRowIds.Count
                    && rowFailureLastInsertRowIds[rowIndex] is { } rowLastInsertRowId
                        ? context with
                        {
                            TriggerState = new TriggerStatementState(rowLastInsertRowId),
                        }
                        : context;
                var output = new List<SqlValue>();
                try
                {
                    foreach (var projection in returning)
                    {
                        switch (projection.Expression)
                        {
                            case StarExpression:
                                for (var index = 0; index < table.Columns.Length; index++)
                                    output.Add(rowValues[index]);
                                break;
                            case QualifiedStarExpression qualifiedStar:
                                if (!string.Equals(qualifiedStar.Qualifier, tableName, StringComparison.OrdinalIgnoreCase))
                                    throw new EmbeddedSqlException($"no such table: {qualifiedStar.Qualifier}");
                                for (var index = 0; index < table.Columns.Length; index++)
                                    output.Add(rowValues[index]);
                                break;
                            default:
                                output.Add(Evaluate(projection.Expression, parameters, source, evaluationContext));
                                break;
                        }
                    }
                }
                catch (Exception exception) when (
                    rowFailureLastInsertRowIds is not null
                    && rowIndex < rowFailureLastInsertRowIds.Count
                    && rowFailureLastInsertRowIds[rowIndex].HasValue
                    && exception is not OperationCanceledException
                    && exception is not EmbeddedConflictFailException
                    && exception is not EmbeddedConflictRollbackException
                    && exception is not EmbeddedStatementAbortException
                    && exception is not EmbeddedStatementFailureException)
                {
                    var failureLastInsertRowId = rowFailureLastInsertRowIds[rowIndex]!.Value;
                    if (exception is EmbeddedSqlException sqlException)
                        throw new EmbeddedStatementAbortException(sqlException, failureLastInsertRowId);
                    throw new EmbeddedStatementFailureException(exception, failureLastInsertRowId);
                }

                resultRows.Add(output.ToArray());
            }
        }
        finally
        {
            if (context.StatementState is not null)
                context.StatementState.LastInsertRowId = savedLastInsertRowId;
        }

        return new ExecutionResult(columnNames, resultRows, rowsAffected, changed)
        {
            LastInsertRowId = lastInsertRowId,
        };
    }

    // Runs a base INSERT/UPDATE/DELETE and, if the statement affects at least one row,
    // fires any statement-level AFTER triggers. The triggering statement plus every
    // trigger it fires form a single atomic unit: a failure anywhere restores the tables.
    private ExecutionResult ExecuteWithTriggers(
        string tableName,
        TriggerEvent triggerEvent,
        QueryContext context,
        Func<ExecutionResult> performBase)
    {
        var triggers = GetMatchingTriggers(context, tableName, triggerEvent, TriggerTiming.After);
        if (triggers.Count == 0 && !context.ForeignKeysEnabled)
            return performBase();

        if (triggers.Count > 0 && context.TriggerDepth >= MaximumTriggerDepth)
        {
            throw new EmbeddedTriggerDepthException(
                context.TriggerState?.LiveLastInsertRowId ?? context.LastInsertRowId);
        }

        ExecutionResult PerformAndFire()
        {
            var result = performBase();
            if (result.RowsAffected > 0 && triggers.Count > 0)
            {
                var triggerContext = result.LastInsertRowId is { } insertedRowId
                    ? context with { LastInsertRowId = insertedRowId }
                    : context;
                FireTriggers(triggers, triggerContext);
            }
            return result;
        }

        if (context.ForeignKeysEnabled)
            return ExecuteWithForeignKeyStatement(context, PerformAndFire);

        var backup = CloneTablesShallow(context.Tables);
        try
        {
            return PerformAndFire();
        }
        catch (EmbeddedUpsertConflictFailException)
        {
            throw;
        }
        catch (EmbeddedConflictFailException) when (context.PreserveUpsertFail)
        {
            throw;
        }
        catch
        {
            RestoreTables(context.Tables, backup);
            throw;
        }
    }

    private ExecutionResult ExecuteWithForeignKeyStatement(
        QueryContext context,
        Func<ExecutionResult> operation)
    {
        var foreignKeyState = context.ForeignKeyStatement
            ?? throw new InvalidOperationException("Foreign-key enforcement lost its statement state.");
        if (foreignKeyState.Depth > 0)
            return operation();

        // The parent-key probes (ForeignKeyParentProbe) are cached in _foreignKeyParentProbes
        // and validated against RowStore.Revision at lookup time, so a probe is rebuilt lazily
        // only when the parent table's rows actually mutate. We deliberately do NOT clear the
        // cache per statement: across a bulk insert of N rows into a child table the parent
        // rows never change, so the probe is built once (O(parent rows)) and reused for all N
        // statements, turning the per-statement CollectForeignKeyViolations scan from
        // O(N * parent rows) probe-builds into O(parent rows) once + O(N) lookups.

        // Fast path: when the catalog has no triggers, no deferred foreign keys, no
        // referential actions, and every foreign key references the parent primary key (with
        // no generated parent columns), the per-mutation validators run at depth 0 and throw
        // immediately on a violation — matching SQLite's per-row enforcement against the
        // parent index. The O(rows) per-statement full-catalog CollectForeignKeyViolations
        // scan (O(N^2) across a bulk insert of N statements) is skipped entirely. Schemas
        // that need statement-end arbitration (triggers that may repair, CASCADE/SET NULL/
        // SET DEFAULT actions, deferred foreign keys, UNIQUE-index or generated-column FK
        // parents) fall through to the retained-state slow path below.
        if (CatalogSupportsFastForeignKeyValidation(context.Tables, context.Triggers))
        {
            var fastBackup = CloneTablesShallow(context.Tables);
            try
            {
                return operation();
            }
            catch (EmbeddedConflictFailException)
            {
                throw;
            }
            catch (EmbeddedTriggerDepthException)
            {
                throw;
            }
            catch
            {
                RestoreTables(context.Tables, fastBackup);
                throw;
            }
        }

        // Slow path: keep depth > 0 during the operation so the per-mutation validators
        // return instead of throwing mid-statement, then diff the full-catalog violation set
        // before and after. CollectForeignKeyViolations uses the hash-probed ParentContains,
        // so each scan is O(rows) (not O(rows^2)); the probe is shared across both scans and
        // across statements.
        var backup = CloneTablesShallow(context.Tables);
        foreignKeyState.Depth++;
        var baseline = CollectForeignKeyViolations(context.Tables, includeImmediate: true);
        void ValidateRetainedState()
        {
            var remaining = CollectForeignKeyViolations(context.Tables, includeImmediate: true);
            var introducedImmediate = remaining
                .Except(baseline)
                .Any(violation => !context.InTransaction
                    || (!context.DeferForeignKeys && !violation.DeclaredDeferred));
            if (introducedImmediate)
                throw new EmbeddedSqlException("FOREIGN KEY constraint failed");
        }

        try
        {
            var result = operation();
            ValidateRetainedState();
            return result;
        }
        catch (EmbeddedConflictFailException)
        {
            try
            {
                ValidateRetainedState();
            }
            catch
            {
                RestoreTables(context.Tables, backup);
                throw;
            }
            throw;
        }
        catch (EmbeddedTriggerDepthException)
        {
            throw;
        }
        catch
        {
            RestoreTables(context.Tables, backup);
            throw;
        }
        finally
        {
            foreignKeyState.Depth--;
        }
    }

    // Whether the catalog can use the fast (depth-0, no full-scan) foreign-key path in
    // ExecuteWithForeignKeyStatement. The per-mutation validators must be able to detect
    // every possible violation immediately at depth 0; any schema feature that defers,
    // repairs, or obscures a violation forces the retained-state slow path.
    private bool CatalogSupportsFastForeignKeyValidation(
        IReadOnlyDictionary<string, EmbeddedTable> tables,
        IReadOnlyDictionary<string, TriggerDefinition>? triggers)
    {
        // Triggers may repair foreign-key violations mid-statement, so unresolved
        // violations must be caught by the retained-state scan at statement end.
        if (triggers is { Count: > 0 })
            return false;

        foreach (var (_, table) in tables)
        {
            foreach (var foreignKey in table.ForeignKeys)
            {
                // Deferred foreign keys need statement-end + commit-time enforcement.
                if (foreignKey.Deferral == ForeignKeyDeferral.InitiallyDeferred)
                    return false;

                // Referential actions (CASCADE / SET NULL / SET DEFAULT) repair child rows
                // mid-statement; the per-mutation validators fire before the repair, so the
                // retained-state scan must arbitrate. RESTRICT throws immediately and is fine
                // on the fast path, but it still differs from NO ACTION only in timing, so we
                // keep it on the slow path for parity with the retained-scan semantics.
                if (foreignKey.OnDelete != ForeignKeyAction.NoAction
                    || foreignKey.OnUpdate != ForeignKeyAction.NoAction)
                    return false;

                // The per-mutation parent-side validators (ValidateChildrenAfterParentUpdate /
                // ValidateForeignKeysAfterDelete) only inspect foreign keys whose parent
                // columns are in the statement's assigned-columns set. A foreign key that
                // references a UNIQUE index (non-primary-key) or a generated parent column can
                // be orphaned by an update to an underlying column without appearing in that set
                // (e.g. a generated column recomputed from an updated base column). Those
                // schemas need the full-catalog scan to catch the orphan.
                if (!tables.TryGetValue(foreignKey.ParentTable, out var parent))
                    return false;

                int[] parentColumns;
                if (foreignKey.ParentColumns.Count == 0)
                {
                    if (parent.PrimaryKeyColumns.Count != foreignKey.ChildColumns.Count)
                        return false;
                    parentColumns = parent.PrimaryKeyColumns.Select(column => column.Index).ToArray();
                }
                else
                {
                    parentColumns = new int[foreignKey.ParentColumns.Count];
                    for (var position = 0; position < parentColumns.Length; position++)
                    {
                        if (!parent.TryGetColumnIndex(
                                foreignKey.ParentColumns[position],
                                out parentColumns[position]))
                        {
                            return false;
                        }
                    }

                    if (!PrimaryKeyMatches(parent, parentColumns))
                        return false;
                }

                foreach (var column in parentColumns)
                {
                    if (parent.ColumnDefinitions[column].IsGenerated)
                        return false;
                }
            }
        }

        return true;
    }

    private bool FireTriggers(
        IReadOnlyList<TriggerDefinition> triggers,
        QueryContext context,
        TriggerRowFrame? frame = null,
        InsertConflictAlgorithm? triggerConflictAlgorithm = null)
    {
        if (triggers.Count > 0 && context.TriggerDepth >= MaximumTriggerDepth)
            throw new EmbeddedSqlException("too many levels of trigger recursion");

        foreach (var trigger in triggers)
        {
            var activeTriggers = context.ActiveTriggers is null
                ? new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                : new HashSet<string>(context.ActiveTriggers, StringComparer.OrdinalIgnoreCase);
            activeTriggers.Add(trigger.Name);
            var triggerContext = context with
            {
                CommonTableExpressions = new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
                InsideTrigger = true,
                ActiveTriggers = activeTriggers,
                TriggerDepth = context.TriggerDepth + 1,
                TriggerConflictAlgorithm = triggerConflictAlgorithm ?? context.TriggerConflictAlgorithm,
                TriggerRow = frame ?? context.TriggerRow,
            };
            var savedLastInsertRowId = GetLastInsertRowId(context);
            try
            {
                if (trigger.When is not null
                    && !IsTrue(Evaluate(trigger.When, EmptyParameters, row: null, triggerContext)))
                {
                    continue;
                }

                foreach (var bodyStatement in trigger.Body)
                {
                    var result = bodyStatement switch
                    {
                        InsertStatement insert => ExecuteInsert(insert, EmptyParameters, triggerContext),
                        UpdateStatement update => ExecuteUpdate(update, EmptyParameters, triggerContext),
                        DeleteStatement delete => ExecuteDelete(delete, EmptyParameters, triggerContext),
                        QueryStatement query => ExecuteQuery(
                            query,
                            EmptyParameters,
                            triggerContext,
                            outerRow: null),
                        _ => throw new EmbeddedSqlException(
                            $"unsupported trigger body statement {bodyStatement.GetType().Name}"),
                    };
                    if (result.LastInsertRowId is { } insertedRowId)
                        triggerContext = triggerContext with { LastInsertRowId = insertedRowId };
                }
            }
            catch (TriggerIgnoreException)
            {
                return true;
            }
            finally
            {
                if (context.StatementState is not null)
                    context.StatementState.LastInsertRowId = savedLastInsertRowId;
            }
        }

        return false;
    }

    private SourceRow? CreateTriggerRow(
        TriggerDefinition trigger,
        QueryContext context,
        TriggerRowFrame frame)
    {
        if (frame.IsEmpty)
            return null;

        string[] columns;
        IReadOnlyList<EmbeddedColumn?>? columnDefinitions = null;
        var hasRowid = false;
        if (context.Tables.TryGetValue(trigger.TableName, out var table))
        {
            columns = table.Columns;
            columnDefinitions = table.ColumnDefinitions;
            hasRowid = table.HasRowid;
        }
        else if (context.Views is not null
                 && context.Views.TryGetValue(trigger.TableName, out var view))
        {
            columns = ResolveViewColumns(view, EnterView(context, view.Name));
        }
        else
        {
            throw new EmbeddedSqlException($"no such table: {trigger.TableName}");
        }

        var values = new List<SqlValue>();
        var definitions = new List<EmbeddedColumn?>();
        var qualifiedColumns = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        var qualifiedDefinitions = new Dictionary<string, EmbeddedColumn>(StringComparer.OrdinalIgnoreCase);
        var qualifiedRowIds = new Dictionary<string, long?>(StringComparer.OrdinalIgnoreCase);
        void AddPseudoRow(string qualifier, SqlValue[]? row, long? rowId)
        {
            if (row is null)
                return;
            if (row.Length != columns.Length)
                throw new InvalidOperationException($"Trigger row for '{trigger.Name}' has the wrong column count.");

            var offset = values.Count;
            for (var columnIndex = 0; columnIndex < columns.Length; columnIndex++)
            {
                var qualifiedName = $"{qualifier}.{columns[columnIndex]}";
                qualifiedColumns.Add(qualifiedName, offset + columnIndex);
                values.Add(row[columnIndex]);
                var definition = columnDefinitions?[columnIndex];
                definitions.Add(definition);
                if (definition is not null)
                    qualifiedDefinitions.Add(qualifiedName, definition);
            }
            qualifiedRowIds.Add(qualifier, hasRowid ? rowId : null);
        }

        AddPseudoRow("OLD", frame.OldRow, frame.OldRowId);
        AddPseudoRow("NEW", frame.NewRow, frame.NewRowId);
        return new SourceRow(
            [],
            values.ToArray(),
            qualifiedColumns,
            QualifiedRowIds: qualifiedRowIds,
            ColumnDefinitions: definitions,
            QualifiedColumnDefinitions: qualifiedDefinitions);
    }

    private static IReadOnlyList<TriggerDefinition> GetMatchingTriggers(
        QueryContext context,
        string tableName,
        TriggerEvent triggerEvent)
    {
        if (context.Triggers is null || context.Triggers.Count == 0)
            return [];

        return context.Triggers.Values
            .Where(trigger => trigger.Event == triggerEvent
                && string.Equals(trigger.TableName, tableName, StringComparison.OrdinalIgnoreCase))
            .OrderByDescending(trigger => trigger.DeclarationOrder)
            .ThenByDescending(trigger => trigger.Name, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static IReadOnlyList<TriggerDefinition> GetMatchingTriggers(
        QueryContext context,
        string tableName,
        TriggerEvent triggerEvent,
        TriggerTiming timing,
        IReadOnlySet<string>? updatedColumns = null)
    {
        if (context.Triggers is null || context.Triggers.Count == 0)
            return [];

        var triggers = context.Triggers.Values
            .Where(trigger => trigger.Event == triggerEvent
                && trigger.Timing == timing
                && string.Equals(trigger.TableName, tableName, StringComparison.OrdinalIgnoreCase)
                && (trigger.UpdateOfColumns is null
                    || updatedColumns is null
                    || trigger.UpdateOfColumns.Any(updatedColumns.Contains)))
            .Reverse()
            .ToArray();
        if (context.InsideTrigger && !context.RecursiveTriggersEnabled && context.ActiveTriggers is not null)
        {
            triggers = triggers
                .Where(trigger => !context.ActiveTriggers.Contains(trigger.Name))
                .ToArray();
        }
        return triggers;
    }

#if false
    private readonly record struct TriggerRowFrame(
        SqlValue[]? OldRow,
        long? OldRowId,
        SqlValue[]? NewRow,
        long? NewRowId)
    {
        public static TriggerRowFrame Empty { get; } = new(null, null, null, null);

        public bool IsEmpty => OldRow is null && NewRow is null;
    }
#endif

    internal static void RestoreTables(
        Dictionary<string, EmbeddedTable> target,
        Dictionary<string, EmbeddedTable> backup)
    {
        target.Clear();
        foreach (var pair in backup)
            target.Add(pair.Key, pair.Value.Clone());
    }

    // Trigger bodies never reference bind parameters (rejected at parse time); the slot-0
    // placeholder mirrors the 1-indexed parameter convention used elsewhere.
    private static readonly SqlValue[] EmptyParameters = new SqlValue[1];

    private ExecutionResult ExecuteQuery(
        QueryStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        context.CheckInterrupt();
        if (context.OuterAggregateScope is not null
            && statement is SelectStatement selectStatement
            && !SelectIsAggregateBearing(selectStatement))
        {
            // SQLite ownership rule: an aggregate owned by an enclosing block may only be
            // referenced when the immediately enclosing SELECT is itself aggregate-bearing.
            // A non-aggregate block cannot host one, so drop the scope here; the reference
            // then falls through to scalar dispatch and fails with the same "wrong number
            // of arguments" misuse error native reports.
            context = context with { OuterAggregateScope = null };
        }
        ValidateLimitOffsetColumnScope(statement, context.TriggerRow is not null);
        return statement switch
        {
            SelectStatement select => ExecuteSelectStatement(select, parameters, context, outerRow),
            CompoundSelectStatement compound => ExecuteCompoundSelect(compound, parameters, context, outerRow),
            WithSelectStatement with => ExecuteWithSelect(with, parameters, context, outerRow),
            ValuesClause values => ExecuteValues(values, parameters, context, outerRow),
            _ => throw new EmbeddedSqlException($"Unsupported query type {statement.GetType().Name}."),
        };
    }

    private static SqlValue[] MaterializeQueryRow(IReadOnlyList<SqlValue> row)
    {
        var materialized = new SqlValue[row.Count];
        for (var index = 0; index < row.Count; index++)
            materialized[index] = row[index].WithoutJsonSubtype();

        return materialized;
    }

    private static ExecutionResult MaterializeQueryResult(ExecutionResult result)
    {
        if (result.Rows is StreamingProjectionRows streamingRows)
        {
            result = result with
            {
                Rows = streamingRows.Materialize(),
            };
        }

        if (!result.Rows.Any(row => row.Any(value => value.IsJson)))
            return result;

        return new ExecutionResult(
            result.Columns,
            result.Rows.Select(MaterializeQueryRow).ToArray(),
            result.RowsAffected,
            result.Changed)
        {
            LastInsertRowId = result.LastInsertRowId,
        };
    }

    // Routes a SELECT through the bytecode compiler when its source and expression
    // shapes are representable, running the emitted program as a real execution path.
    // Deliberately unsupported semantic families keep the tree-walking evaluator.
    private ExecutionResult ExecuteSelectStatement(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        context.CheckInterrupt();
        ValidateSelectIndexDirectives(select, context);
        ValidateGroupByCollations(select.GroupBy);
        var canUseCompiledRoute = CanUseCompiledSelectRoute(select, context, outerRow);
        CompiledSelect? compiled = null;
        if (canUseCompiledRoute)
        {
            var compiledIndex = false;
            if ((!context.CancellationToken.CanBeCanceled || IsAggregateSelect(select))
                && TryPlanManagedIndexScan(select, context) is { } indexPlan)
            {
                compiledIndex = TryCompileManagedIndexSelect(
                    select,
                    indexPlan,
                    parameters,
                    context,
                    outerRow,
                    materializeIndexRows: true,
                    out compiled);
            }

            if (!compiledIndex)
                TryCompileSelect(select, parameters, context, outerRow, out compiled);
        }

        if (compiled is not null)
        {
            var columns = GetColumnNames(
                select.Projections,
                GetOutputColumns(select.Source, context),
                GetRawOutputColumns(select.Source, context));
            return RunCompiledProgram(
                compiled,
                columns,
                BuildValuesBinding(compiled.ParameterIndices ?? [], parameters),
                context.CancellationToken);
        }

        return ExecuteSelect(select, parameters, context, outerRow);
    }

    // The evaluator streams this subset so callback failures and cancellation stay observable at the
    // same row boundary as SQLite. Execution and EXPLAIN QUERY PLAN share this gate so the latter
    // never reports a bytecode route that execution deliberately declines.
    private bool CanUseCompiledSelectRoute(
        SelectStatement select,
        QueryContext context,
        SourceRow? outerRow)
        => (!context.CancellationToken.CanBeCanceled || IsAggregateSelect(select))
            && !CanStreamProjectionRows(select, context, outerRow);

    private bool IsAggregateSelect(SelectStatement select) =>
        select.GroupBy.Count > 0
        || select.Projections.Any(projection => ContainsAggregate(projection.Expression))
        || select.Having is not null && ContainsAggregate(select.Having)
        || select.OrderBy.Any(term => ContainsAggregate(term.Expression));

    private bool TryCompileSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
    {
        select = ResolveNamedWindows(select);
        context = EnterCollationSource(context, select.Source);

        // A SELECT carrying LIMIT/OFFSET lowers only when its LIMIT/OFFSET-free base is a
        // gate-able route. Direct scans, constant projections, source-less scalar Function programs,
        // aggregates, windows, the deliberately narrow bounded sorted-scan subset, and a strictly-gated
        // equi-join subset route through the dedicated path that layers LimitOffsetProgramBuilder
        // gates onto that base. DISTINCT, computed shapes, outer joins, and compounds keep
        // LIMIT/OFFSET on the evaluator.
        if (select.Limit is not null || select.Offset is not null)
        {
            // The window route owns its own LIMIT/OFFSET composition because its base is a buffered
            // pipeline the generic limited-select preflight does not model.
            if (TryCompileWindowSelect(select, parameters, context, outerRow, out compiled))
                return true;

            if (TryCompileLimitedSelect(select, parameters, context, outerRow, out compiled))
                return true;

            return TryCompileGeneralJoinSelect(select, parameters, context, outerRow, out compiled);
        }

        // A bare star over a lowerable derived query is the same result stream with only a metadata
        // boundary. Reuse the child's program so nested compounds remain fully compiled.
        if (TryCompileDerivedPassThroughSelect(select, parameters, context, outerRow, out compiled))
            return true;

        // The direct scan / source-less constant projection subset.
        if (TryCompileScanOrConstant(select, parameters, context, outerRow, out compiled))
            return true;

        // The bare `SELECT COUNT(*) FROM <source>` shape (no WHERE/GROUP BY/HAVING/ORDER BY/
        // DISTINCT/LIMIT/OFFSET) reads the bound row source's row count directly via RowCount
        // instead of scanning. This runs only on the original select here at the top-level
        // dispatch, so a COUNT(*) that carries LIMIT/OFFSET lowers through TryCompileLimitedSelect
        // (which strips LIMIT/OFFSET before calling TryCompileAggregateSelect) and keeps its
        // accumulator+gate EXPLAIN shape.
        if (TryCompileCountStarShortcut(select, context, out compiled))
            return true;

        // The unordered scan/constant compiler declines aggregation. Try the aggregate
        // route so whole-table and GROUP BY aggregations over a single base table lower to
        // the real AggReset/AggStep/AggFinalize opcode family instead of the evaluator,
        // reusing the evaluator's accumulation and grouping helpers so results stay exact.
        if (TryCompileAggregateSelect(select, parameters, context, outerRow, out compiled))
            return true;

        // The aggregate route declines window calls (ContainsAggregate is false for them). Try the
        // running-frame window route so a single-table SELECT whose window functions all share one
        // ROWS UNBOUNDED PRECEDING -> CURRENT ROW frame lowers to the real sorter + AggReset/AggStep/
        // AggFinalize opcode family, reusing the evaluator's accumulation, partition equality, and
        // ordering so routed rows stay byte-identical; every other window shape stays on the evaluator.
        if (TryCompileWindowSelect(select, parameters, context, outerRow, out compiled))
            return true;

        // The unordered scan/constant compiler declines ORDER BY. Try the sorter-backed
        // route so single-table ordered scans also lower to real bytecode instead of the
        // evaluator, keeping ordering semantics identical by reusing the evaluator's
        // comparison logic through the emitted VdbeRowComparer.
        if (TryCompileSortedSelect(select, parameters, context, outerRow, out compiled))
            return true;

        // The single-table routes all decline a join source. Try the nested-loop join route
        // so a two-table INNER/LEFT OUTER join over base tables lowers to the real
        // OpenReadCursor/Rewind/Column/FilterRegisters/JumpIf/ResultRow opcode family instead
        // of the evaluator, delegating the ON/WHERE predicate to the evaluator's own
        // comparison semantics so routed rows stay byte-identical.
        if (TryCompileJoinSelect(
                select,
                parameters,
                context,
                outerRow,
                allowPostJoinWhere: false,
                compiled: out compiled))
        {
            return true;
        }

        return TryCompileGeneralJoinSelect(select, parameters, context, outerRow, out compiled);
    }

    private bool TryCompileDerivedPassThroughSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
    {
        compiled = null!;
        if (select.Distinct
            || select.Where is not null
            || select.GroupBy.Count != 0
            || select.Having is not null
            || select.OrderBy.Count != 0
            || select.Limit is not null
            || select.Offset is not null
            || select.Source is not DerivedTableSource derived
            || select.Projections.Count != 1)
        {
            return false;
        }

        var expression = select.Projections[0].Expression;
        if (expression is not StarExpression
            && (expression is not QualifiedStarExpression qualified
                || derived.Alias is null
                || !string.Equals(qualified.Qualifier, derived.Alias, StringComparison.OrdinalIgnoreCase)))
        {
            return false;
        }

        return TryCompileCompoundTerm(derived.Query, parameters, context, outerRow, out compiled);
    }

    // Generic source-less and direct-scan projections, delegated to the shared
    // SelectStatementCompiler. Constant folding, scalar functions, numeric affinity,
    // table resolution, and predicate compilation reuse evaluator helpers so the emitted
    // program matches evaluator value semantics.
    private bool TryCompileScanOrConstant(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
    {
        var compiler = new SelectStatementCompiler(
            IsConstantScalarExpression,
            expression => Evaluate(expression, parameters, null, context),
            source => ResolveScanTarget(source, context),
            (where, target) => IsStreamingSafeScalarScanPredicate(where, target, context)
                ? CompileRowPredicate(where, target, parameters, context, outerRow)
                : null,
            (where, target) => CanEmitNativeScanPredicate(where, target, context),
            (where, target) => CompileSimpleRowIdPredicate(where, target, parameters, context, outerRow),
            (select, target) => CompileDistinctScanEquality(select, target, context),
            function => TryGetRoutableBuiltinScalarCall(function, out var routable)
                ? BuildBuiltinScalarFunction(routable, parameters, context)
                : null,
            ArithmeticNumericAffinity,
            ModuloNumericAffinity,
            BitwiseIntegerAffinity);
        return compiler.TryCompile(select, out compiled);
    }

    private bool TryCompileManagedIndexSelect(
        SelectStatement select,
        ManagedIndexScanPlan plan,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        bool materializeIndexRows,
        out CompiledSelect compiled)
    {
        select = ResolveNamedWindows(select);
        context = EnterCollationSource(context, select.Source);

        ScanTarget CreateTarget(
            IReadOnlyList<SqlValue[]> targetRows,
            IReadOnlyList<long>? targetRowIds)
        {
            var qualifier = plan.Source.Alias ?? plan.Source.Name;
            var qualifiedColumns = BuildQualifiedColumns(qualifier, plan.Table.Columns);
            return new ScanTarget(
                plan.Source.Name,
                qualifier,
                plan.Table.Columns,
                targetRows,
                name => ResolveScanColumnIndex(
                    name,
                    plan.Table.Columns,
                    qualifiedColumns),
                targetRowIds,
                plan.Index.Name,
                plan.Table.ColumnDefinitions,
                BuildQualifiedColumnDefinitions(
                    qualifier,
                    plan.Table.ColumnDefinitions));
        }

        var compileSelect = select;
        var aggregateSelect = IsAggregateSelect(select);
        if (aggregateSelect)
        {
            if ((select.Limit is not null || select.Offset is not null)
                && select.Distinct
                && select.Projections.Any(projection =>
                    IsCustomCollation(
                        GetEffectiveCollation(projection.Expression, context))))
            {
                compiled = null!;
                return false;
            }

            var baseSelect = select with { Limit = null, Offset = null };
            var probeTarget = CreateTarget(
                plan.Table.Rows,
                plan.Table.HasRowid ? plan.Table.RowIds : null);
            if (!TryCompileAggregateSelect(
                    baseSelect,
                    parameters,
                    context,
                    outerRow,
                    out _,
                    probeTarget))
            {
                compiled = null!;
                return false;
            }

            if (select.Limit is not null || select.Offset is not null)
            {
                ResolveLimitOffset(
                    select,
                    parameters,
                    context,
                    outerRow,
                    out var limit,
                    out var offset);
                if (limit == 0)
                {
                    compiled = CompileLimitZeroSelect(select, context, outerRow);
                    return true;
                }

                compileSelect = WithResolvedBounds(select, limit, offset);

                var refreshedPlan = TryPlanManagedIndexScan(select, context);
                if (refreshedPlan is null)
                {
                    context = RefreshCollationSource(context, select.Source);
                    var refreshedTarget = ResolveScanTarget(select.Source, context)
                        ?? MaterializeAggregateScanTarget(
                            select.Source,
                            parameters,
                            context,
                            outerRow);

                    if (TryCompileLimitedSelect(
                            compileSelect,
                            parameters,
                            context,
                            outerRow,
                            out compiled,
                            refreshedTarget))
                    {
                        return true;
                    }

                    compiled = CompileMaterializedSelect(
                        ExecuteSelect(
                            compileSelect,
                            parameters,
                            context,
                            outerRow));
                    return true;
                }

                plan = refreshedPlan;
                context = RefreshCollationSource(context, select.Source);
                var refreshedProbe = CreateTarget(
                    plan.Table.Rows,
                    plan.Table.HasRowid ? plan.Table.RowIds : null);
                if (!TryCompileAggregateSelect(
                        baseSelect,
                        parameters,
                        context,
                        outerRow,
                        out _,
                        refreshedProbe))
                {
                    compiled = CompileMaterializedSelect(
                        ExecuteSelect(
                            compileSelect,
                            parameters,
                            context,
                            outerRow));
                    return true;
                }
            }
        }

        IReadOnlyList<SqlValue[]> rows;
        IReadOnlyList<long>? rowIds;
        if (materializeIndexRows)
        {
            var indexed = GetManagedIndexRows(plan, context, outerRow);
            rows = indexed.Rows.Select(row => row.Values).ToArray();
            rowIds = plan.Table.HasRowid
                ? indexed.Rows.Select(row =>
                    row.RowId ?? throw new InvalidOperationException("Indexed row is missing its rowid.")).ToArray()
                : null;
        }
        else
        {
            rows = plan.Table.Rows;
            rowIds = plan.Table.HasRowid ? plan.Table.RowIds : null;
        }

        var target = CreateTarget(rows, rowIds);
        if (aggregateSelect)
        {
            if (compileSelect.Limit is not null || compileSelect.Offset is not null)
            {
                return TryCompileLimitedSelect(
                    compileSelect,
                    parameters,
                    context,
                    outerRow,
                    out compiled,
                    target);
            }

            return TryCompileAggregateSelect(
                compileSelect,
                parameters,
                context,
                outerRow,
                out compiled,
                target);
        }
        if (select.Projections.Any(projection =>
                ContainsWindowFunction(projection.Expression)))
        {
            return TryCompileWindowSelect(
                select,
                parameters,
                context,
                outerRow,
                out compiled,
                target);
        }

        var compiler = new SelectStatementCompiler(
            IsConstantScalarExpression,
            expression => Evaluate(expression, parameters, null, context),
            _ => target,
            (where, scan) => CompileRowPredicate(where, scan, parameters, context, outerRow),
            (where, scan) => CanEmitNativeScanPredicate(where, scan, context),
            (where, scan) => CompileSimpleRowIdPredicate(where, scan, parameters, context, outerRow),
            (statement, scan) => CompileDistinctScanEquality(statement, scan, context),
            function => TryGetRoutableBuiltinScalarCall(function, out var routable)
                ? BuildBuiltinScalarFunction(routable, parameters, context)
                : null,
            ArithmeticNumericAffinity,
            ModuloNumericAffinity,
            BitwiseIntegerAffinity);
        return compiler.TryCompile(select, out compiled);
    }

    // DISTINCT runs as rows stream from the cursor, whereas the evaluator first materializes every filtered
    // source row before it evaluates projections and de-duplicates. Restrict the direct route to direct declared
    // columns with built-in declared collations plus an optional single declared-column comparison against a literal
    // or parameter: neither stage can introduce a deferred expression failure after an earlier DISTINCT result has
    // been yielded. Custom collations remain evaluator-owned because their callbacks can throw while de-duplicating.
    // More complex predicates also remain evaluator-owned so their value and error timing are preserved.
    private VdbeRowEquality? CompileDistinctScanEquality(
        SelectStatement select,
        ScanTarget target,
        QueryContext context)
    {
        if (!select.Distinct
            || select.Projections.Count == 0
            || (select.Where is not null && !IsExactDistinctScanWherePredicate(select.Where, target)))
            return null;

        var table = context.Tables[target.TableName];
        var collations = new List<string?>(select.Projections.Count);
        foreach (var projection in select.Projections)
        {
            if (projection.Expression is not ColumnExpression column)
            {
                return null;
            }

            var index = target.ResolveColumnIndex(column.Name);
            if (index is null)
                return null;

            var collation = table.ColumnDefinitions[index.Value].Collation;
            if (!IsStreamingSafeDistinctCollation(collation))
                return null;

            collations.Add(collation);
        }

        return (left, right) => RowsEqual(left, right, collations);
    }

    private static bool IsExactDistinctScanWherePredicate(Expression expression, ScanTarget target)
    {
        if (expression is not BinaryExpression binary || !IsComparisonOperator(binary.Operator))
            return false;

        return (IsDeclaredScanColumnReference(binary.Left, target) && IsLiteralOrParameter(binary.Right))
            || (IsDeclaredScanColumnReference(binary.Right, target) && IsLiteralOrParameter(binary.Left));
    }

    private static bool IsDeclaredScanColumnReference(Expression expression, ScanTarget target)
        => expression is ColumnExpression column && target.ResolveColumnIndex(column.Name) is not null;

    // Builtin scalar functions whose evaluator implementation reads ONLY the already-evaluated argument
    // values — never the argument AST, the current row, the collation, or the query context — so applying
    // the function through the direct Function opcode over the same argument values is byte-identical to the
    // evaluator. Names are compared upper-cased (the evaluator's own normalization). Deliberately excluded:
    // NULLIF/MIN/MAX (collation/comparison via the argument AST), LIKE/GLOB (collation/pattern), all JSON_*
    // (read the argument AST for error text), LAST_INSERT_ROWID (reads the context), and the date/time and
    // UUID families (non-deterministic). See TryGetRoutableBuiltinScalarCall for the per-call gates.
    private static readonly HashSet<string> RoutableBuiltinScalarFunctions = new(StringComparer.Ordinal)
    {
        "ABS",
        "COALESCE",
        "HEX",
        "IFNULL",
        "INSTR",
        "LENGTH",
        "LOWER",
        "TYPEOF",
        "UPPER",
    };

    private static readonly VdbeNumericAffinity ArithmeticNumericAffinity = new()
    {
        Name = "numeric",
        Apply = value => value.Kind == SqlValueKind.Null ? value : ApplyNumericAffinity(value),
    };

    private static readonly VdbeNumericAffinity ModuloNumericAffinity = new()
    {
        Name = "integer-numeric",
        Apply = value => value.Kind == SqlValueKind.Null ? value : ApplyModuloNumericAffinity(value),
    };

    private static readonly VdbeNumericAffinity BitwiseIntegerAffinity = new()
    {
        Name = "integer",
        Apply = value => value.Kind == SqlValueKind.Null
            ? value
            : SqlValue.Integer(ToPrintfInteger(value)),
    };

    private static bool IsStreamingSafeScalarScanPredicate(
        Expression expression,
        ScanTarget target,
        QueryContext context)
    {
        if (expression is not BinaryExpression binary
            || !IsComparisonOperator(binary.Operator)
            || !context.Tables.TryGetValue(target.TableName, out var table))
        {
            return false;
        }

        return (IsStreamingSafeScalarScanColumn(binary.Left, target, table) && IsLiteralOrParameter(binary.Right))
            || (IsStreamingSafeScalarScanColumn(binary.Right, target, table) && IsLiteralOrParameter(binary.Left));
    }

    private bool CanEmitNativeScanPredicate(
        Expression expression,
        ScanTarget target,
        QueryContext context)
        => IsStreamingSafeScalarScanPredicate(expression, target, context)
            && !ContainsEffectiveCustomCollation(expression, context);

    private static bool IsStreamingSafeScalarScanColumn(
        Expression expression,
        ScanTarget target,
        EmbeddedTable table)
    {
        return expression switch
        {
            ColumnExpression column when target.ResolveColumnIndex(column.Name) is { } ordinal
                => IsStreamingSafeDistinctCollation(table.ColumnDefinitions[ordinal].Collation),
            CollationExpression
            {
                Expression: ColumnExpression column,
                Name: var collation,
            } when target.ResolveColumnIndex(column.Name) is not null
                => IsStreamingSafeDistinctCollation(collation),
            _ => false,
        };
    }

    // Recognizes a plain builtin scalar call eligible for the Function opcode: an allow-listed name, no
    // OVER/FILTER/DISTINCT/COUNT(*) decoration, and no user-defined function registered under the name (for
    // this arity or variadically) that would shadow the builtin in the evaluator's own dispatch.
    private bool TryGetRoutableBuiltinScalarCall(Expression expression, out FunctionExpression function)
    {
        function = null!;
        if (expression is not FunctionExpression candidate)
            return false;

        if (candidate.Window is not null
            || candidate.Filter is not null
            || candidate.Distinct
            || candidate.CountStar)
        {
            return false;
        }

        var name = candidate.Name.ToUpperInvariant();
        if (!RoutableBuiltinScalarFunctions.Contains(name))
            return false;

        if (_scalarFunctions.ContainsKey((name, candidate.Arguments.Count))
            || _scalarFunctions.ContainsKey((name, -1)))
        {
            return false;
        }

        function = candidate;
        return true;
    }

    // Maps the arithmetic BinaryOperators to their ArithmeticOperator opcode. Only the numeric family the
    // Arithmetic opcode implements is routable; Concatenate, the comparison operators, And/Or, and Is/IsNot
    // carry text/comparison/collation/logical semantics VdbeArithmetic does not model, so they decline.
    private static bool TryMapArithmeticOperator(BinaryOperator op, out ArithmeticOperator arithmetic)
    {
        switch (op)
        {
            case BinaryOperator.Add:
                arithmetic = ArithmeticOperator.Add;
                return true;
            case BinaryOperator.Subtract:
                arithmetic = ArithmeticOperator.Subtract;
                return true;
            case BinaryOperator.Multiply:
                arithmetic = ArithmeticOperator.Multiply;
                return true;
            case BinaryOperator.Divide:
                arithmetic = ArithmeticOperator.Divide;
                return true;
            case BinaryOperator.Modulo:
                arithmetic = ArithmeticOperator.Modulo;
                return true;
            case BinaryOperator.BitwiseAnd:
                arithmetic = ArithmeticOperator.BitwiseAnd;
                return true;
            case BinaryOperator.BitwiseOr:
                arithmetic = ArithmeticOperator.BitwiseOr;
                return true;
            case BinaryOperator.ShiftLeft:
                arithmetic = ArithmeticOperator.ShiftLeft;
                return true;
            case BinaryOperator.ShiftRight:
                arithmetic = ArithmeticOperator.ShiftRight;
                return true;
            default:
                arithmetic = default;
                return false;
        }
    }

    private static bool TryMapArithmeticOperator(UnaryOperator op, out ArithmeticOperator arithmetic)
    {
        switch (op)
        {
            case UnaryOperator.Plus:
                arithmetic = ArithmeticOperator.Identity;
                return true;
            case UnaryOperator.Negate:
                arithmetic = ArithmeticOperator.Negate;
                return true;
            case UnaryOperator.BitwiseNot:
                arithmetic = ArithmeticOperator.BitwiseNot;
                return true;
            default:
                arithmetic = default;
                return false;
        }
    }

    // Wraps the evaluator's own EvaluateScalarFunction as a Function-opcode delegate: at execution the opcode
    // hands over the already-computed argument values, which are re-wrapped as literals and dispatched through
    // the exact same builtin switch — so values, NULL propagation, and thrown EmbeddedSqlExceptions (including
    // arity errors, raised here rather than by the builder) are byte-identical to the evaluator. Arity is left
    // null so the builder never pre-validates the count and the evaluator owns arity checking as it always does.
    private VdbeScalarFunction BuildBuiltinScalarFunction(
        FunctionExpression function,
        SqlValue[] parameters,
        QueryContext context)
    {
        var name = function.Name;
        return new VdbeScalarFunction
        {
            Name = name.ToLowerInvariant(),
            Arity = null,
            Invoke = arguments =>
            {
                var literalArguments = new Expression[arguments.Length];
                for (var index = 0; index < arguments.Length; index++)
                    literalArguments[index] = new LiteralExpression(arguments[index]);

                return EvaluateScalarFunction(
                    new FunctionExpression(name, literalArguments, CountStar: false),
                    parameters,
                    row: null,
                    context);
            },
        };
    }

    // Lowers a LIMIT/OFFSET SELECT by compiling its LIMIT/OFFSET-free base and layering the
    // LimitOffsetProgramBuilder gates onto it, or returns false so the evaluator keeps
    // ownership of every shape below.
    //
    // Routed entirely through the VDBE:
    //  - the base (the same SELECT with LIMIT/OFFSET stripped) lowers via the direct-scan /
    //    constant-projection compiler, aggregate route, bounded sorted-scan route, or the
    //    deliberately small direct join route. Each emits through unconditional ResultRow
    //    instructions, which is exactly what the gate can bound: OFFSET skips leading candidates
    //    without charging LIMIT, then LIMIT caps the survivors, matching the evaluator's
    //    OFFSET-then-LIMIT ApplyDistinctLimit order.
    //  - LIMIT/OFFSET resolve to integers exactly as ExecuteSelect resolves them
    //    (RequireLimitInteger, with a negative OFFSET clamped to zero and a null/negative
    //    LIMIT treated as unbounded), so the gated program yields the identical row window.
    //
    // Deliberately kept on the evaluator (fallback):
    //  - ORDER BY outside the bounded sorted-scan subset; joins outside the narrow direct
    //    equi-join or cross-join shape; DISTINCT, aggregate/window shapes, non-base sources, computed
    //    projections, and non-column order keys all need semantics this pipeline does not
    //    represent exactly.
    //  - DISTINCT outside row-aware aggregation: direct DISTINCT still combines de-duplication
    //    and emission in DistinctResultRow, which cannot be gated without counting duplicates.
    //  - LIMIT 0: the evaluator validates every projection/WHERE/GROUP BY/HAVING/ORDER BY
    //    expression against a synthetic row and returns empty WITHOUT scanning, so its
    //    validation-and-evaluation timing differs from a gate that would scan first; keep it
    //    on the evaluator so that timing is preserved.
    //  - a LIMIT/OFFSET expression that does not resolve to an integer (e.g. LIMIT 'x' or
    //    LIMIT NULL -> "datatype mismatch"): fall back so the evaluator raises the identical
    //    error at its identical (pre-scan) point rather than the router surfacing it.
    private bool TryCompileLimitedSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled,
        ScanTarget? targetOverride = null)
    {
        compiled = null!;

        if (select.OrderBy.Count != 0)
            ValidateOrderByCollations(ResolveOrderBy(select.OrderBy, select.Projections));
        var windowFunctions = CollectSelectWindowFunctions(select);
        foreach (var function in windowFunctions)
        {
            ValidateOrderByCollations(function.Window!.OrderBy);
            ValidateGroupByCollations(function.Window.PartitionBy);
        }
        if (windowFunctions.Count != 0)
            return false;

        var baseSelect = select with { Limit = null, Offset = null };

        // Row-aware aggregate DISTINCT lowers to DistinctGate + ResultRow, so its limit
        // gates see only novel finalized rows. Other DISTINCT routes still emit through
        // DistinctResultRow and remain ineligible for this transform.
        if (select.Distinct)
        {
            if (!IsAggregateSelect(select)
                || select.Projections.Any(projection =>
                    IsCustomCollation(GetEffectiveCollation(projection.Expression, context))))
            {
                return false;
            }

            if (!TryCompileAggregateSelect(
                    baseSelect,
                    parameters,
                    context,
                    outerRow,
                    out var compiledDistinct,
                    targetOverride))
            {
                return false;
            }
            ResolveLimitOffset(
                select,
                parameters,
                context,
                outerRow,
                out var distinctLimit,
                out var distinctOffset);
            if (distinctLimit == 0)
            {
                compiled = CompileLimitZeroSelect(select, context, outerRow);
                return true;
            }
            var resolvedDistinct = WithResolvedBounds(
                select,
                distinctLimit,
                distinctOffset);
            if (targetOverride is null
                && !TryCompileRefreshedAggregate(
                    baseSelect,
                    resolvedDistinct,
                    parameters,
                    context,
                    outerRow,
                    out compiledDistinct))
            {
                return false;
            }

            var gatedDistinct = LimitOffsetProgramBuilder.Apply(
                compiledDistinct.Program,
                distinctOffset,
                distinctLimit);
            compiled = ReferenceEquals(gatedDistinct, compiledDistinct.Program)
                ? compiledDistinct
                : new CompiledSelect(
                    gatedDistinct,
                    compiledDistinct.CursorSources,
                    compiledDistinct.ParameterIndices);
            return true;
        }

        // ORDER BY needs a sorter before row gates run. Its bounded subset has an explicit
        // preflight below. A row-aware aggregate already owns its post-group output sorter,
        // so gate that compiled stream directly before considering the plain sorted-scan route.
        if (select.OrderBy.Count != 0)
        {
            if (IsAggregateSelect(baseSelect))
            {
                if (!TryCompileAggregateSelect(
                        baseSelect,
                        parameters,
                        context,
                        outerRow,
                        out var compiledAggregate,
                        targetOverride))
                {
                    return false;
                }
                ResolveLimitOffset(
                    select,
                    parameters,
                    context,
                    outerRow,
                    out var orderedLimit,
                    out var orderedOffset);
                if (orderedLimit == 0)
                {
                    compiled = CompileLimitZeroSelect(select, context, outerRow);
                    return true;
                }
                var resolvedOrdered = WithResolvedBounds(
                    select,
                    orderedLimit,
                    orderedOffset);
                if (targetOverride is null
                    && !TryCompileRefreshedAggregate(
                        baseSelect,
                        resolvedOrdered,
                        parameters,
                        context,
                        outerRow,
                        out compiledAggregate))
                {
                    return false;
                }

                var gatedAggregate = LimitOffsetProgramBuilder.Apply(
                    compiledAggregate.Program,
                    orderedOffset,
                    orderedLimit);
                compiled = ReferenceEquals(gatedAggregate, compiledAggregate.Program)
                    ? compiledAggregate
                    : new CompiledSelect(
                        gatedAggregate,
                        compiledAggregate.CursorSources,
                        compiledAggregate.ParameterIndices);
                return true;
            }

            return TryCompileLimitedSortedSelect(select, parameters, context, outerRow, out compiled);
        }

        if (IsAggregateSelect(baseSelect))
        {
            if (!TryCompileAggregateSelect(
                    baseSelect,
                    parameters,
                    context,
                    outerRow,
                    out var compiledAggregate,
                    targetOverride))
            {
                return false;
            }
            ResolveLimitOffset(
                select,
                parameters,
                context,
                outerRow,
                out var aggregateLimit,
                out var aggregateOffset);
            if (aggregateLimit == 0)
            {
                compiled = CompileLimitZeroSelect(select, context, outerRow);
                return true;
            }
            var resolvedAggregate = WithResolvedBounds(
                select,
                aggregateLimit,
                aggregateOffset);
            if (targetOverride is null
                && !TryCompileRefreshedAggregate(
                    baseSelect,
                    resolvedAggregate,
                    parameters,
                    context,
                    outerRow,
                    out compiledAggregate))
            {
                return false;
            }

            var gatedAggregate = LimitOffsetProgramBuilder.Apply(
                compiledAggregate.Program,
                aggregateOffset,
                aggregateLimit);
            compiled = ReferenceEquals(gatedAggregate, compiledAggregate.Program)
                ? compiledAggregate
                : new CompiledSelect(
                    gatedAggregate,
                    compiledAggregate.CursorSources,
                    compiledAggregate.ParameterIndices);
            return true;
        }

        // Resolve bounds before compiling the base. This keeps a bad bound's error ahead of
        // any projection folding or source work, as in ExecuteSelect.
        if (!TryResolveLimitOffset(select, parameters, context, outerRow, out var limit, out var offset))
            return false;

        // LIMIT 0 has evaluator-specific validate-and-skip-the-scan semantics the gate cannot
        // reproduce; keep it on the evaluator (which also returns empty, but only after its
        // LIMIT 0 expression validation).
        if (limit == 0)
            return false;

        // Gate only the row-count-preserving routes whose unconditional ResultRows the builder
        // can bound exactly. Any generic source-less expression is safe because it has one
        // candidate row; scan projections remain direct-only so an early gate cannot change
        // expression error timing. Bounded joins claim only direct INNER/LEFT equi-joins or
        // INNER cross joins over two base tables with direct projections.
        var directProjectionIsGateSafe = baseSelect.Source is null
            || baseSelect.Projections.All(projection =>
                projection.Expression is StarExpression
                    or QualifiedStarExpression
                    or ColumnExpression
                || IsConstantScalarExpression(projection.Expression));
        if (!(directProjectionIsGateSafe
                && TryCompileScanOrConstant(baseSelect, parameters, context, outerRow, out var compiledBase))
            && !TryCompileLimitedJoinSelect(baseSelect, parameters, context, outerRow, out compiledBase))
        {
            return false;
        }

        // The gate returns the program unchanged when neither bound is needed (offset <= 0 and
        // an unbounded limit), so an unbounded LIMIT -1 still routes as the plain base scan.
        var gated = LimitOffsetProgramBuilder.Apply(compiledBase.Program, offset, limit);
        compiled = ReferenceEquals(gated, compiledBase.Program)
            ? compiledBase
            : new CompiledSelect(gated, compiledBase.CursorSources, compiledBase.ParameterIndices);
        return true;
    }

    private bool TryCompileRefreshedAggregate(
        SelectStatement baseSelect,
        SelectStatement resolvedSelect,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
    {
        context = RefreshCollationSource(context, baseSelect.Source);
        var target = ResolveScanTarget(baseSelect.Source, context)
            ?? MaterializeAggregateScanTarget(
                baseSelect.Source,
                parameters,
                context,
                outerRow);
        if (TryCompileAggregateSelect(
                baseSelect,
                parameters,
                context,
                outerRow,
                out compiled,
                target))
        {
            return true;
        }

        compiled = CompileMaterializedSelect(
            ExecuteSelect(
                resolvedSelect,
                parameters,
                context,
                outerRow));
        return true;
    }

    private static SelectStatement WithResolvedBounds(
        SelectStatement select,
        long? limit,
        long offset) => select with
        {
            Limit = limit is null
            ? null
            : new LiteralExpression(SqlValue.Integer(limit.Value)),
            Offset = offset == 0
            ? null
            : new LiteralExpression(SqlValue.Integer(offset)),
        };

    private static CompiledSelect CompileMaterializedSelect(ExecutionResult result)
    {
        var program = result.Rows.Count == 0
            ? new VdbeProgram(
                registerCount: 0,
                cursorCount: 0,
                [new HaltInstruction()])
            : ValuesProgramBuilder.Build(
                result.Rows
                    .Select(row => (IReadOnlyList<SqlValue>)row)
                    .ToArray());
        return new CompiledSelect(program, []);
    }

    private ScanTarget MaterializeAggregateScanTarget(
        TableSource? source,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        var materialized = GetSourceRows(
            source,
            parameters,
            context,
            maximumRows: null,
            outerRow);
        var qualifier = source switch
        {
            NamedTableSource named => named.Alias ?? named.Name,
            DerivedTableSource { Alias: { } alias } => alias,
            _ => "__aggregate_source",
        };
        var qualifiedColumns = BuildQualifiedColumns(qualifier, materialized.Columns);
        var firstRow = materialized.Rows.FirstOrDefault();
        return new ScanTarget(
            "__materialized_aggregate_source",
            qualifier,
            materialized.Columns,
            materialized.Rows.Select(row => row.Values.ToArray()).ToArray(),
            name => ResolveScanColumnIndex(
                name,
                materialized.Columns,
                qualifiedColumns),
            ColumnDefinitions: firstRow?.ColumnDefinitions
                ?? (source is null
                    ? []
                    : GetSourceColumnDefinitions(source, context)),
            QualifiedColumnDefinitions: firstRow?.QualifiedColumnDefinitions
                ?? (source is null
                    ? new Dictionary<string, EmbeddedColumn>(
                        StringComparer.OrdinalIgnoreCase)
                    : GetSourceQualifiedColumnDefinitions(source, context)));
    }

    // Bounded joins are deliberately a smaller contract than TryCompileJoinSelect. A LIMIT/OFFSET gate is
    // mechanically valid over every unconditional ResultRow that JoinProgramBuilder emits, including the
    // mutually-exclusive matched and null-extension emission sites of a LEFT join. This route claims two base
    // tables, direct column/literal projections, and either an explicit equality between one direct column from
    // each side or an INNER cross join with no ON condition. INNER joins may add a direct post-join WHERE.
    // LEFT joins may add only a direct, collation-free comparison over the combined input row, which the
    // nested-loop program applies after null extension.
    private bool TryCompileLimitedJoinSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
    {
        compiled = null!;

        if (select.Source is not JoinTableSource
            {
                Natural: false,
                UsingColumns: null,
            } join
            || join.Kind is not (JoinKind.Inner or JoinKind.Left))
        {
            return false;
        }

        var leftTarget = ResolveScanTarget(join.Left, context);
        var rightTarget = ResolveScanTarget(join.Right, context);
        if (leftTarget is null
            || rightTarget is null
            || select.Projections.Any(projection =>
                !IsDirectJoinProjection(projection.Expression, leftTarget, rightTarget))
            || (select.Where is not null
                && (join.Kind == JoinKind.Left
                    ? !IsExactLeftOuterJoinWherePredicate(select.Where, leftTarget, rightTarget)
                    : !IsDirectJoinWherePredicate(select.Where, leftTarget, rightTarget))))
        {
            return false;
        }

        // A conditionless INNER join is the parser representation of both CROSS JOIN and the
        // comma operator. The reusable nested-loop builder emits its pair stream without a
        // predicate, so applying a direct WHERE before its unconditional ResultRow has the same
        // pair order and LIMIT/OFFSET window as the evaluator. A conditionless LEFT join has no
        // useful SQL spelling in this route; keep it on the evaluator rather than broadening the
        // supported surface accidentally.
        if (join.Condition is null)
        {
            if (join.Kind != JoinKind.Inner)
                return false;
        }
        else if (!IsDirectEquiJoinEquality(join.Condition, leftTarget, rightTarget))
        {
            return false;
        }

        return TryCompileJoinSelect(
            select,
            parameters,
            context,
            outerRow,
            allowPostJoinWhere: join.Kind == JoinKind.Left,
            compiled: out compiled);
    }

    // The ON comparison must use one direct column from each input. Requiring a qualifier keeps duplicate
    // names and self-joins from accidentally binding to the first matching combined-row column.
    private static bool IsDirectEquiJoinEquality(
        Expression expression,
        ScanTarget leftTarget,
        ScanTarget rightTarget)
    {
        if (expression is not BinaryExpression { Operator: BinaryOperator.Equal } equality)
            return false;

        return IsDirectColumnFrom(equality.Left, leftTarget, rightTarget)
               && IsDirectColumnFrom(equality.Right, rightTarget, leftTarget)
            || IsDirectColumnFrom(equality.Left, rightTarget, leftTarget)
               && IsDirectColumnFrom(equality.Right, leftTarget, rightTarget);
    }

    private static bool IsDirectJoinProjection(
        Expression expression,
        ScanTarget leftTarget,
        ScanTarget rightTarget)
        => expression is LiteralExpression
            || IsDirectColumnFrom(expression, leftTarget, rightTarget)
            || IsDirectColumnFrom(expression, rightTarget, leftTarget);

    private static bool IsDirectJoinWherePredicate(
        Expression expression,
        ScanTarget leftTarget,
        ScanTarget rightTarget)
    {
        if (expression is not BinaryExpression comparison
            || comparison.Operator is not (BinaryOperator.Equal
                or BinaryOperator.NotEqual
                or BinaryOperator.LessThan
                or BinaryOperator.LessThanOrEqual
                or BinaryOperator.GreaterThan
                or BinaryOperator.GreaterThanOrEqual))
        {
            return false;
        }

        return IsDirectJoinPredicateOperand(comparison.Left, leftTarget, rightTarget)
            && IsDirectJoinPredicateOperand(comparison.Right, leftTarget, rightTarget)
            && (IsDirectColumnFrom(comparison.Left, leftTarget, rightTarget)
                || IsDirectColumnFrom(comparison.Left, rightTarget, leftTarget)
                || IsDirectColumnFrom(comparison.Right, leftTarget, rightTarget)
                || IsDirectColumnFrom(comparison.Right, rightTarget, leftTarget));
    }

    private static bool IsDirectJoinPredicateOperand(
        Expression expression,
        ScanTarget leftTarget,
        ScanTarget rightTarget)
        => IsDirectColumnFrom(expression, leftTarget, rightTarget)
            || IsDirectColumnFrom(expression, rightTarget, leftTarget)
            || UnwrapCollation(expression) is LiteralExpression or ParameterExpression;

    // An explicit WHERE collation can raise a late "no such collation sequence" error. The evaluator
    // materializes the complete join before it evaluates WHERE, while the VDBE checks per row, so retain
    // those shapes on the evaluator. Direct comparison/IS predicates otherwise cannot fail after parameter
    // binding and use the evaluator itself for all SQL NULL truth semantics.
    private static bool IsExactLeftOuterJoinWherePredicate(
        Expression expression,
        ScanTarget leftTarget,
        ScanTarget rightTarget)
    {
        if (ContainsExplicitCollation(expression))
            return false;

        if (expression is BinaryExpression { Operator: BinaryOperator.Is or BinaryOperator.IsNot } comparison)
        {
            return IsDirectJoinPredicateOperand(comparison.Left, leftTarget, rightTarget)
                && IsDirectJoinPredicateOperand(comparison.Right, leftTarget, rightTarget)
                && (IsDirectColumnFrom(comparison.Left, leftTarget, rightTarget)
                    || IsDirectColumnFrom(comparison.Left, rightTarget, leftTarget)
                    || IsDirectColumnFrom(comparison.Right, leftTarget, rightTarget)
                    || IsDirectColumnFrom(comparison.Right, rightTarget, leftTarget));
        }

        return IsDirectJoinWherePredicate(expression, leftTarget, rightTarget);
    }

    private static bool ContainsExplicitCollation(Expression expression)
    {
        return expression switch
        {
            CollationExpression => true,
            RowValueExpression rowValue => rowValue.Values.Any(ContainsExplicitCollation),
            BinaryExpression binary => ContainsExplicitCollation(binary.Left)
                || ContainsExplicitCollation(binary.Right),
            _ => false,
        };
    }

    private static bool IsDirectColumnFrom(
        Expression expression,
        ScanTarget target,
        ScanTarget otherTarget)
    {
        if (UnwrapCollation(expression) is not ColumnExpression { Name: var name }
            || !name.Contains('.'))
        {
            return false;
        }

        return target.ResolveColumnIndex(name) is not null
            && otherTarget.ResolveColumnIndex(name) is null;
    }

    private static Expression UnwrapCollation(Expression expression)
    {
        while (expression is CollationExpression collation)
            expression = collation.Expression;

        return expression;
    }

    // Lowers the intentionally small ORDER BY + LIMIT/OFFSET family. The base sorter consumes
    // all qualifying rows before its unconditional ResultRow reaches the offset/limit gates, so
    // the gates trim the already ordered stream exactly. The preflight is deliberately stricter
    // than the unbounded sorter route: only a single base table, non-DISTINCT non-aggregate
    // projections made from bare columns, "*" / a resolved qualified star, or literals, and
    // resolved column (or COLLATE-column) ORDER BY keys are admitted. This prevents
    // aliases/ordinals that resolve to computed expressions from being mistaken for row-backed sort keys.
    private bool TryCompileLimitedSortedSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
    {
        compiled = null!;

        // ExecuteSelect validates collations before it resolves LIMIT/OFFSET. Do that before
        // any lowering work so a missing collation keeps its evaluator error precedence.
        ValidateOrderByCollations(ResolveOrderBy(select.OrderBy, select.Projections));
        if (!TryResolveLimitOffset(select, parameters, context, outerRow, out var limit, out var offset))
            return false;

        // LIMIT 0 validates all expressions but deliberately avoids scanning. A sorter would
        // materialize rows before its zero gate, so retain evaluator ownership.
        if (limit == 0)
            return false;

        var baseSelect = select with { Limit = null, Offset = null };
        if (!TryCompileBoundedSortedSelect(baseSelect, parameters, context, outerRow, out var compiledBase))
            return false;

        var gated = LimitOffsetProgramBuilder.Apply(compiledBase.Program, offset, limit);
        compiled = ReferenceEquals(gated, compiledBase.Program)
            ? compiledBase
            : new CompiledSelect(gated, compiledBase.CursorSources);
        return true;
    }

    private bool TryResolveLimitOffset(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out long? limit,
        out long offset)
    {
        limit = null;
        offset = 0;
        try
        {
            ResolveLimitOffset(select, parameters, context, outerRow, out limit, out offset);
            return true;
        }
        catch (EmbeddedSqlException)
        {
            // The evaluator owns diagnostics for non-integral bounds and any expression
            // failure, preserving its exact error text and timing.
            return false;
        }
    }

    private void ResolveLimitOffset(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out long? limit,
        out long offset)
    {
        limit = select.Limit is null
            ? null
            : RequireLimitInteger(Evaluate(select.Limit, parameters, outerRow, context));
        offset = select.Offset is null
            ? 0
            : Math.Max(0, RequireLimitInteger(Evaluate(select.Offset, parameters, outerRow, context)));
    }

    private CompiledSelect CompileLimitZeroSelect(
        SelectStatement select,
        QueryContext context,
        SourceRow? outerRow)
    {
        ValidateLimitZeroExpressions(
            select,
            GetSourceColumns(select.Source, context),
            context,
            outerRow);
        return new CompiledSelect(
            new VdbeProgram(
                registerCount: 0,
                cursorCount: 0,
                [new HaltInstruction()]),
            []);
    }

    // Lowers a compound SELECT whose terms are lowerable queries sequenced by a single uniform
    // UNION ALL, UNION/DISTINCT, INTERSECT, or EXCEPT operator into one VdbeProgram via
    // CompoundProgramBuilder, or returns false so the tree-walking evaluator keeps ownership of every
    // shape below.
    //
    // Routed entirely through the VDBE:
    //  - the operator chain is a single operator repeated (a same-operator chain), and that operator
    //    is UNION ALL, UNION/DISTINCT, INTERSECT, or EXCEPT. Such a chain flattens into one builder
    //    call because the evaluator folds it left-associatively into the identical result:
    //      * UNION ALL concatenates every term in order.
    //      * UNION/DISTINCT keeps each row's first occurrence across all terms in arrival order.
    //      * INTERSECT emits each distinct first-term row that also appears in every other term, in
    //        first-term first-occurrence order. A ∩ B ∩ C is associative and commutative, so the
    //        builder's "present in all probe sets" test reproduces the evaluator's step-by-step fold
    //        (each step intersects the running distinct set with the next term) exactly.
    //      * EXCEPT emits each distinct first-term row absent from every other term, in first-term
    //        first-occurrence order. A EXCEPT B EXCEPT C is left-associative and equals A minus
    //        (B ∪ C), so the builder's "absent from all probe sets" test reproduces the evaluator's
    //        fold exactly.
    //    These are precisely what BuildUnionAll/BuildUnionDistinct/BuildIntersect/BuildExcept emit,
    //    so flattening is order-, duplicate-, and membership-identical.
    //  - every term is a lowerable SELECT, VALUES row set, or nested compound, and every term projects
    //    the same number of result columns. Nested row-set and aggregate group state is retained.
    //  - for UNION/DISTINCT, INTERSECT, and EXCEPT (every operator that de-duplicates or probes rows),
    //    the first term's projection list maps one-to-one onto the output columns so the evaluator's
    //    per-output-column collation vector aligns with the row width; a star-expanded first term
    //    (whose projection count differs from the column count) stays on the evaluator, whose own
    //    row-equality would fault on that same too-short vector. UNION ALL needs no collation vector,
    //    so a star-expanded UNION ALL still routes.
    //
    // Deliberately kept on the evaluator (fallback):
    //  - ORDER BY / LIMIT / OFFSET on the compound, which reshape the sequenced stream the builder
    //    only concatenates, de-duplicates, or probes.
    //  - mixed operators (e.g. UNION ALL ... UNION ..., or INTERSECT ... EXCEPT ...); the builder
    //    sequences one uniform operator per call and the evaluator's left-associative mixed fold is
    //    not reproduced here.
    //  - any term whose expressions can invoke user callbacks, use unsupported subqueries, or otherwise
    //    cannot be represented by a child VDBE program.
    //  - terms whose result-column counts differ, so the evaluator raises its exact "SELECTs to the
    //    left and right of a compound operator do not have the same number of result columns" error.
    private bool TryCompileCompoundSelect(
        CompoundSelectStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
    {
        compiled = null!;

        if (context.CancellationToken.CanBeCanceled
            || statement.Operators.Count == 0
            || statement.OrderBy.Count != 0
            || statement.Limit is not null
            || statement.Offset is not null)
        {
            return false;
        }

        // Only a single uniform UNION ALL, UNION/DISTINCT, INTERSECT, or EXCEPT operator repeated
        // across the whole chain routes; any mixed chain stays on the evaluator.
        var compoundOperator = statement.Operators[0];
        if (compoundOperator is not (CompoundOperator.Union or CompoundOperator.UnionAll
            or CompoundOperator.Intersect or CompoundOperator.Except))
        {
            return false;
        }

        for (var index = 1; index < statement.Operators.Count; index++)
        {
            if (statement.Operators[index] != compoundOperator)
                return false;
        }

        // Bytecode set operations de-duplicate while terms emit rows; the evaluator waits
        // for a later term to complete. Keep callback-capable result collations on the
        // evaluator so a comparator cannot run before a later term's error.
        if (compoundOperator != CompoundOperator.UnionAll
            && statement.Terms.Any(term =>
                HasObservableCompoundResultCollation(term, context)))
        {
            return false;
        }

        // Every term must lower on its own and project the same number of result
        // columns; otherwise fall back so the evaluator produces the value or its exact error.
        if (statement.Terms.Any(ContainsLimitedCompoundTerm))
            return false;
        if (compoundOperator == CompoundOperator.UnionAll
            && statement.Terms.Any(term =>
                ContainsObservableAggregateCompoundTerm(term, context)))
        {
            return false;
        }

        var terms = new List<CompoundTerm>(statement.Terms.Count);
        var parameterIndices = new List<int>();
        var columnCount = -1;
        foreach (var term in statement.Terms)
        {
            if (!TryCompileCompoundTerm(term, parameters, context, outerRow, out var compiledTerm))
                return false;

            var width = ResultRowWidth(compiledTerm.Program);
            if (columnCount < 0)
                columnCount = width;
            else if (columnCount != width)
                return false;

            terms.Add(new CompoundTerm(compiledTerm.Program, compiledTerm.CursorSources));
            if (compiledTerm.ParameterIndices is { } termParameterIndices)
                parameterIndices.AddRange(termParameterIndices);
        }

        if (terms.Any(term =>
                !IsConservativeCompoundTerm(term.Program)
                && !(compoundOperator == CompoundOperator.UnionAll
                    && (IsTypeofFunctionCompoundTerm(term.Program)
                        || IsSequentialAggregateCompoundTerm(term.Program)))))
            return false;

        CompoundTerm compound;
        if (compoundOperator == CompoundOperator.UnionAll)
        {
            compound = CompoundProgramBuilder.BuildUnionAll(terms);
        }
        else
        {
            // UNION/DISTINCT, INTERSECT, and EXCEPT all de-duplicate their output and (for the set
            // operations) probe membership through the evaluator's row-equality: per-output-column
            // collations from the first term drive RowsEqual (NULL==NULL, otherwise a collation-aware
            // comparison), so the emitted DistinctResultRow / RowSetInsert / CompoundResultRow opcodes
            // de-duplicate and test membership exactly as ApplyUnion / ApplyIntersect / ApplyExcept do.
            // The collation vector only aligns with the row width when the first term projects one
            // column per output, so a star-expanded first term declines rather than index a too-short
            // vector (the same range the evaluator's own RowsEqual would fault on).
            var collations = GetCompoundCollations(statement.Terms, columnCount, context);
            if (collations.Count != columnCount
                || collations.Any(collation => !IsStreamingSafeDistinctCollation(collation)))
                return false;

            bool RowEquality(SqlValue[] left, SqlValue[] right) => RowsEqual(left, right, collations);

            compound = compoundOperator switch
            {
                CompoundOperator.Union => CompoundProgramBuilder.BuildUnionDistinct(terms, RowEquality),
                CompoundOperator.Intersect => CompoundProgramBuilder.BuildIntersect(terms, RowEquality),
                CompoundOperator.Except => CompoundProgramBuilder.BuildExcept(terms, RowEquality),
                _ => throw new EmbeddedSqlException($"Unsupported compound operator {compoundOperator}."),
            };
        }

        compiled = new CompiledSelect(compound.Program, compound.CursorSources, parameterIndices);
        return true;
    }

    private bool HasObservableCompoundResultCollation(
        QueryStatement term,
        QueryContext context)
    {
        return term is SelectStatement select
            && select.Projections.Any(projection =>
                ContainsEffectiveCustomCollation(
                    projection.Expression,
                    EnterCollationSource(context, select.Source)));
    }

    private static bool IsConservativeCompoundTerm(VdbeProgram program)
        => program.Instructions.All(IsConservativeCompoundInstruction);

    // UNION ALL runs each spliced child to completion in SQL source order, as does the evaluator.
    // typeof(value) is the only scalar function admitted: its one materialized argument has a total,
    // callback-free result. Other set operators retain their stricter eligibility because their row-set
    // work can change when expression errors become observable.
    private static bool IsTypeofFunctionCompoundTerm(VdbeProgram program)
        => program.Instructions.All(instruction =>
            IsConservativeCompoundInstruction(instruction)
            || instruction is FunctionInstruction function
                && string.Equals(function.Function.Name, "typeof", StringComparison.OrdinalIgnoreCase)
                && function.Arguments.Count == 1);

    private static bool IsConservativeCompoundInstruction(VdbeInstruction instruction)
        => instruction is not (
            FunctionInstruction
            or AggResetInstruction
            or AggStepInstruction
            or AggFinalizeInstruction
            or OpenSorterInstruction
            or OpenWindowBufferInstruction
            or FilterRegistersInstruction
            or OpenJoinCursorInstruction
            or ProjectRegistersInstruction
            or DistinctFilterInstruction);

    private static bool IsSequentialAggregateCompoundTerm(VdbeProgram program) =>
        program.Instructions.Any(instruction => instruction is AggStepInstruction)
        && program.Instructions.All(instruction => instruction is not (
            OpenJoinCursorInstruction
            or ProjectRegistersInstruction
            or DistinctFilterInstruction
            or FunctionInstruction
            or LimitGateInstruction
            or OffsetGateInstruction));

    private bool ContainsLimitedCompoundTerm(QueryStatement term)
    {
        return term switch
        {
            SelectStatement select => select.Limit is not null || select.Offset is not null
                || select.Source is DerivedTableSource derived
                    && ContainsLimitedCompoundTerm(derived.Query),
            CompoundSelectStatement compound => compound.Terms.Any(ContainsLimitedCompoundTerm),
            WithSelectStatement with => ContainsLimitedCompoundTerm(with.Query)
                || with.CommonTableExpressions.Any(cte =>
                    ContainsLimitedCompoundTerm(cte.Query)),
            _ => false,
        };
    }

    private bool ContainsObservableAggregateCompoundTerm(
        QueryStatement term,
        QueryContext context)
    {
        switch (term)
        {
            case SelectStatement select when IsAggregateSelect(select):
                var selectContext = EnterCollationSource(context, select.Source);
                return select.Projections.Any(projection =>
                    ContainsDeferredAggregateHazard(
                        projection.Expression,
                        sumIsHazard: false)
                    || ContainsEffectiveCustomCollation(
                        projection.Expression,
                        selectContext))
                || select.GroupBy.Any(expression =>
                    ContainsDeferredAggregateHazard(expression, sumIsHazard: false)
                    || ContainsEffectiveCustomCollation(expression, selectContext))
                || select.Where is not null
                    && (ContainsDeferredAggregateHazard(
                            select.Where,
                            sumIsHazard: false)
                        || ContainsEffectiveCustomCollation(
                            select.Where,
                            selectContext))
                || select.Having is not null
                    && (ContainsDeferredAggregateHazard(
                            select.Having,
                            sumIsHazard: false)
                        || ContainsEffectiveCustomCollation(
                            select.Having,
                            selectContext))
                || select.OrderBy.Any(order =>
                    ContainsDeferredAggregateHazard(
                        order.Expression,
                        sumIsHazard: false)
                    || ContainsEffectiveCustomCollation(
                        order.Expression,
                        selectContext));
            case SelectStatement { Source: DerivedTableSource derived }:
                return ContainsObservableAggregateCompoundTerm(derived.Query, context);
            case CompoundSelectStatement compound:
                return compound.Terms.Any(child =>
                    ContainsObservableAggregateCompoundTerm(child, context));
            case WithSelectStatement with:
                return ContainsObservableAggregateCompoundTerm(
                    with.Query,
                    context)
                    || with.CommonTableExpressions.Any(cte =>
                        ContainsObservableAggregateCompoundTerm(cte.Query, context));
            default:
                return false;
        }
    }

    private bool TryCompileCompoundTerm(
        QueryStatement term,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
    {
        switch (term)
        {
            case SelectStatement { Source: null } select
                when TryCompileUnfoldedSourceLessSelect(select, parameters, context, out compiled):
                return true;
            case SelectStatement select:
                return TryCompileCompoundSelectTerm(
                    select,
                    parameters,
                    context,
                    outerRow,
                    out compiled);
            case ValuesClause values:
                return TryCompileCompoundValues(values, parameters, context, out compiled);
            case CompoundSelectStatement compound:
                return TryCompileCompoundSelect(compound, parameters, context, outerRow, out compiled);
            default:
                compiled = null!;
                return false;
        }
    }

    private bool TryCompileCompoundSelectTerm(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
    {
        if (TryPlanManagedIndexScan(select, context) is { } indexPlan)
        {
            if (IsAggregateSelect(select)
                || CollectSelectWindowFunctions(select).Count != 0)
            {
                compiled = null!;
                return false;
            }

            return TryCompileManagedIndexSelect(
                select,
                indexPlan,
                parameters,
                context,
                outerRow,
                materializeIndexRows: true,
                out compiled);
        }

        return TryCompileSelect(select, parameters, context, outerRow, out compiled);
    }

    // Compiles source-less terms without eager arithmetic folding. Runtime evaluation preserves the
    // source-order timing of errors in later INTERSECT/EXCEPT terms.
    private bool TryCompileUnfoldedSourceLessSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        out CompiledSelect compiled)
    {
        var compiler = new SelectStatementCompiler(
            _ => false,
            _ => throw new InvalidOperationException("Unfolded compound terms do not fold expressions."),
            _ => null,
            (_, _) => null,
            (_, _) => false,
            (_, _) => null,
            (_, _) => null,
            function => TryGetRoutableBuiltinScalarCall(function, out var routable)
                ? BuildBuiltinScalarFunction(routable, parameters, context)
                : null,
            ArithmeticNumericAffinity,
            ModuloNumericAffinity,
            BitwiseIntegerAffinity);
        return compiler.TryCompile(select, out compiled);
    }

    private bool TryCompileCompoundValues(
        ValuesClause values,
        SqlValue[] parameters,
        QueryContext context,
        out CompiledSelect compiled)
    {
        compiled = null!;
        var width = values.Rows[0].Count;
        if (values.Rows.Any(row => row.Count != width))
            return false;

        var rows = new List<CompiledSelect>(values.Rows.Count);
        foreach (var row in values.Rows)
        {
            var select = new SelectStatement(
                Distinct: false,
                row.Select(expression => new Projection(expression, Alias: null)).ToArray(),
                Source: null,
                Where: null,
                GroupBy: [],
                Having: null,
                NamedWindows: [],
                OrderBy: [],
                Limit: null,
                Offset: null);
            if (!TryCompileUnfoldedSourceLessSelect(select, parameters, context, out var compiledRow))
                return false;
            rows.Add(compiledRow);
        }

        if (rows.Count == 1)
        {
            compiled = rows[0];
            return true;
        }

        var compound = CompoundProgramBuilder.BuildUnionAll(
            rows.Select(row => new CompoundTerm(row.Program, row.CursorSources)).ToArray());
        compiled = new CompiledSelect(
            compound.Program,
            compound.CursorSources,
            rows.SelectMany(row => row.ParameterIndices ?? []).ToArray());
        return true;
    }

    // The number of result columns a compiled term projects, read from its first result-row emission.
    // Every lowered SELECT emits one, and CompoundProgramBuilder validates the widths agree, so this
    // mirrors the builder's own width check to keep the routing decision and the builder in lock-step.
    private static int ResultRowWidth(VdbeProgram program)
    {
        foreach (var instruction in program.Instructions)
        {
            switch (instruction)
            {
                case ResultRowInstruction result:
                    return result.Values.Count;
                case DistinctResultRowInstruction distinct:
                    return distinct.Values.Count;
                case CompoundResultRowInstruction compound:
                    return compound.Values.Count;
                case GuardedRowInstruction { Destination: ResultRowDestination } guarded:
                    return guarded.Values.Count;
            }
        }

        throw new EmbeddedSqlException("A compiled SELECT term produced no result row.");
    }

    // Lowers a single base-table ORDER BY pipeline into a sorter-backed VdbeProgram, or
    // returns false so the evaluator keeps ownership of shapes the sorted route cannot
    // preserve exactly. Supported: a single real base table, one or more projections that
    // are bare columns, "*" / a resolved qualified star, or folded constants, an optional
    // row-at-a-time WHERE, and one or more ORDER BY keys evaluable against the scanned row.
    // LIMIT/OFFSET are accepted only through TryCompileLimitedSortedSelect, which strips the
    // bounds and asks the bounded overload below for its stricter column-key subset.
    // Deliberately excluded (kept on the evaluator): DISTINCT, GROUP BY/HAVING, an unresolved
    // qualified star, and any ORDER BY key that needs a subquery/aggregate/window or an
    // unbacked rowid.
    private bool TryCompileSortedSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
        => TryCompileSortedSelect(select, parameters, context, outerRow, bounded: false, out compiled);

    private bool TryCompileBoundedSortedSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
        => TryCompileSortedSelect(select, parameters, context, outerRow, bounded: true, out compiled);

    private bool TryCompileSortedSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        bool bounded,
        out CompiledSelect compiled)
    {
        compiled = null!;

        if (select.OrderBy.Count == 0
            || select.Distinct
            || select.Having is not null
            || select.GroupBy.Count != 0
            || select.Limit is not null
            || select.Offset is not null
            || select.Projections.Count == 0)
        {
            return false;
        }

        var resolvedOrderBy = ResolveOrderBy(select.OrderBy, select.Projections);
        ValidateOrderByCollations(resolvedOrderBy);

        var target = ResolveScanTarget(select.Source, context);
        if (target is null)
            return false;

        if (bounded && select.Projections.Any(
                projection => !IsBoundedSortedProjection(projection.Expression, target)))
            return false;

        // Lower every projection to a column read or folded constant, exactly as the
        // unordered scan compiler does; anything else (e.g. computed expressions or an
        // unresolved qualified star) declines the route.
        var projections = new List<SortedScanColumn>();
        foreach (var projection in select.Projections)
        {
            if (!TryLowerSortedProjection(projection.Expression, target, parameters, context, projections))
                return false;
        }

        if (projections.Count == 0)
            return false;

        // ORDER BY keys are resolved (ordinal/alias) exactly like the evaluator, then must
        // be evaluable against a single scanned row and must not read an unbacked rowid,
        // which the materialized declared-column row cannot supply.
        foreach (var term in resolvedOrderBy)
        {
            if (IndexExpressionSemantics.ContainsFunction(
                    term.Expression,
                    IsRegisteredScalarFunction)
                || (!IsScanPredicate(term.Expression)
                    || ReferencesUnbackedRowid(term.Expression, target))
                || (bounded && !IsBoundedSortedOrderKey(term, target)))
                return false;
        }

        VdbeRowPredicate? predicate = null;
        if (select.Where is not null)
        {
            predicate = CompileRowPredicate(select.Where, target, parameters, context, outerRow);
            if (predicate is null)
                return false;
        }

        // The comparer wraps each scanned row and defers to the evaluator's CompareRows so
        // direction (ASC/DESC), NULL ordering, collation, and multi-key precedence match the
        // evaluator byte-for-byte. When the table carries a rowid, the builder appends it to the
        // sorter record (kept for record-shape compatibility) and we thread it into
        // SourceRow.RowId. Equal keys preserve sorter-insertion order — the stable sorter
        // breaks ties by insertion index, which is the scan order, the same self-consistency
        // native SQLite gets from its stable sorter over a rowid-ordered b-tree scan.
        // WITHOUT-ROWID tables keep their existing relative order.
        var columns = target.Columns;
        var rowIdSlot = columns.Length;
        VdbeRowComparer comparer = (leftRow, rightRow) =>
            CompareRows(
                CreateScanSourceRow(target, leftRow, context, outerRow, ExtractSortedScanRowId(leftRow, rowIdSlot)),
                CreateScanSourceRow(target, rightRow, context, outerRow, ExtractSortedScanRowId(rightRow, rowIdSlot)),
                resolvedOrderBy,
                parameters,
                context);

        var program = SortedScanProgramBuilder.Build(
            target.TableName,
            columns.Length,
            projections,
            comparer,
            predicate,
            carryRowId: target.HasRowId);
        compiled = new CompiledSelect(program, [new VdbeCursorSource(target.Rows, target.RowIds)]);
        return true;
    }

    private static bool IsBoundedSortedProjection(Expression expression, ScanTarget target)
        => expression is StarExpression or ColumnExpression or LiteralExpression
            || (expression is QualifiedStarExpression qualifiedStar
                && string.Equals(
                    qualifiedStar.Qualifier,
                    target.Qualifier,
                    StringComparison.OrdinalIgnoreCase));

    private static bool IsBoundedSortedOrderKey(OrderByTerm term, ScanTarget target)
    {
        var expression = term.Expression;
        while (expression is CollationExpression collation)
            expression = collation.Expression;

        return expression is ColumnExpression column
            && target.ResolveColumnIndex(column.Name) is not null;
    }

    // Mirrors SelectStatementCompiler's projection lowering: bare columns and a star whose
    // qualifier resolves to this sole source become column reads, constant scalars fold to a
    // literal, and everything else declines.
    private bool TryLowerSortedProjection(
        Expression expression,
        ScanTarget target,
        SqlValue[] parameters,
        QueryContext context,
        List<SortedScanColumn> projections)
    {
        switch (expression)
        {
            case StarExpression:
                if (target.Columns.Length == 0)
                    return false;

                for (var index = 0; index < target.Columns.Length; index++)
                    projections.Add(SortedScanColumn.ForColumn(index));
                return true;
            case ColumnExpression column when target.ResolveColumnIndex(column.Name) is { } columnIndex:
                projections.Add(SortedScanColumn.ForColumn(columnIndex));
                return true;
            case QualifiedStarExpression qualifiedStar
                when string.Equals(
                    qualifiedStar.Qualifier,
                    target.Qualifier,
                    StringComparison.OrdinalIgnoreCase):
                if (target.Columns.Length == 0)
                    return false;

                for (var index = 0; index < target.Columns.Length; index++)
                    projections.Add(SortedScanColumn.ForColumn(index));
                return true;
            case QualifiedStarExpression:
                // Preserve evaluator ownership of an unresolved qualifier and its diagnostic.
                return false;
            default:
                if (IsConstantScalarExpression(expression))
                {
                    projections.Add(SortedScanColumn.ForConstant(Evaluate(expression, parameters, null, context)));
                    return true;
                }

                return false;
        }
    }

    // Lowers the legacy two-table INNER or LEFT OUTER fast path over base tables into a nested-loop
    // VdbeProgram driven by JoinProgramBuilder, or returns false so the evaluator keeps
    // ownership of shapes the join route cannot preserve exactly.
    //
    // Supported (routed to the VDBE):
    //  - select.Source is a single JoinTableSource whose Left and Right are both real base
    //    tables (each resolvable through ResolveScanTarget). A nested JoinTableSource never
    //    resolves as a base table, so three-or-more-table (N-way) joins decline this fast path.
    //  - join kind INNER or LEFT OUTER only (RIGHT/FULL continue to the materializing route).
    //  - an explicit ON condition, or no condition at all (comma/CROSS join). USING/NATURAL
    //    joins coalesce shared output columns, which the raw-concatenating builder cannot
    //    reproduce, so they stay on the evaluator.
    //  - projections that are each "*", a qualified "t.*", a bare column resolvable to a
    //    combined-row ordinal, or a folded constant scalar. Anything the builder cannot
    //    project as a column read or a constant (computed expressions, aggregates, windows)
    //    declines the route.
    //  - the ON condition and, for INNER joins only, a post-join WHERE, each a row-at-a-time
    //    scan predicate that reads no unbacked rowid over the combined row. Because an INNER
    //    join emits exactly the ON-matching pairs the evaluator then filters by WHERE,
    //    testing "ON AND WHERE" per pair is identical. A bounded caller may additionally opt
    //    into the exact direct LEFT WHERE subset, which runs after null extension.
    //
    // Deliberately excluded from this fast path: DISTINCT, GROUP BY/HAVING, ORDER BY,
    // LIMIT/OFFSET, aggregate/window projections, computed-expression projections, USING/
    // NATURAL joins, RIGHT/FULL joins, joins of more than two base tables, and LEFT OUTER
    // joins carrying a WHERE clause outside the bounded exact subset. The general materializing
    // route below claims the order-safe members of those families; the rest stay on the evaluator.
    private bool TryCompileJoinSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        bool allowPostJoinWhere,
        out CompiledSelect compiled)
    {
        compiled = null!;

        // Clauses that reshape or reorder the result set stay with the evaluator, matching
        // the single-table scan route's boundary exactly.
        if (select.Distinct
            || select.Having is not null
            || select.GroupBy.Count != 0
            || select.OrderBy.Count != 0
            || select.Limit is not null
            || select.Offset is not null
            || select.Projections.Count == 0)
        {
            return false;
        }

        if (select.Source is not JoinTableSource join)
            return false;

        // Only the two shapes JoinProgramBuilder lowers; RIGHT/FULL stay on the evaluator.
        JoinType joinType;
        if (join.Kind == JoinKind.Inner)
            joinType = JoinType.Inner;
        else if (join.Kind == JoinKind.Left)
            joinType = JoinType.LeftOuter;
        else
            return false;

        // USING/NATURAL joins coalesce their shared columns into a single output column; the
        // builder concatenates the two rows verbatim, so those joins stay on the evaluator.
        if (join.UsingColumns is not null || join.Natural)
            return false;

        // Both sides must be real base tables. A nested join, derived table, CTE, view,
        // series, or schema table declines, which is what keeps N-way joins on the evaluator.
        var leftTarget = ResolveScanTarget(join.Left, context);
        var rightTarget = ResolveScanTarget(join.Right, context);
        if (leftTarget is null || rightTarget is null)
            return false;
        if (!HaveStreamingSafeJoinCollations(leftTarget, rightTarget, context)
            || join.Condition is not null
                && (!IsDirectJoinWherePredicate(join.Condition, leftTarget, rightTarget)
                    || ContainsUnsafeCompiledCollation(join.Condition))
            || select.Where is not null
                && (!IsDirectJoinWherePredicate(select.Where, leftTarget, rightTarget)
                    || ContainsUnsafeCompiledCollation(select.Where)))
        {
            return false;
        }

        // The builder needs at least one column per side (a base table always has one).
        if (leftTarget.Columns.Length == 0 || rightTarget.Columns.Length == 0)
            return false;

        // Aggregate/window projections belong to routes this method does not own, so decline
        // them and let the evaluator (or another route) raise its own value or error.
        foreach (var projection in select.Projections)
        {
            if (ContainsAggregate(projection.Expression) || ContainsWindowFunction(projection.Expression))
                return false;
        }

        // Build the combined (left ++ right) row shape exactly as GetJoinRows does, so a
        // reconstructed SourceRow resolves qualified and bare columns identically to the
        // evaluator: left columns occupy ordinals 0..leftWidth-1 and right columns follow.
        var leftColumns = leftTarget.Columns;
        var rightColumns = rightTarget.Columns;
        var leftWidth = leftColumns.Length;
        var combinedColumns = leftColumns.Concat(rightColumns).ToArray();
        var combinedQualified = CombineQualifiedColumns(
            BuildQualifiedColumns(leftTarget.Qualifier, leftColumns),
            BuildQualifiedColumns(rightTarget.Qualifier, rightColumns),
            leftWidth);
        var leftTable = context.Tables[leftTarget.TableName];
        var rightTable = context.Tables[rightTarget.TableName];
        var combinedDefinitions = leftTable.ColumnDefinitions
            .Select(static column => (EmbeddedColumn?)column)
            .Concat(rightTable.ColumnDefinitions.Select(static column => (EmbeddedColumn?)column))
            .ToArray();
        var combinedQualifiedDefinitions = new Dictionary<string, EmbeddedColumn>(
            BuildQualifiedColumnDefinitions(leftTarget.Qualifier, leftTable.ColumnDefinitions),
            StringComparer.OrdinalIgnoreCase);
        foreach (var (name, definition) in BuildQualifiedColumnDefinitions(
                     rightTarget.Qualifier,
                     rightTable.ColumnDefinitions))
        {
            combinedQualifiedDefinitions.TryAdd(name, definition);
        }
        var outputColumns = GetOutputColumns(join, context);
        var rawOutputColumns = GetRawOutputColumns(join, context);

        // A data-free ScanTarget over the combined row lets the projection and predicate
        // helpers reuse the same (possibly-qualified) column resolution and unbacked-rowid
        // guard the single-table routes use, so the mapping matches SourceRow.GetValue.
        var combinedTarget = new ScanTarget(
            leftTarget.TableName,
            leftTarget.Qualifier,
            combinedColumns,
            [],
            name => ResolveCombinedColumnIndex(name, combinedColumns, combinedQualified));

        var projections = new List<JoinProjection>();
        foreach (var projection in select.Projections)
        {
            if (!TryLowerJoinProjection(
                    projection.Expression,
                    combinedTarget,
                    outputColumns,
                    rawOutputColumns,
                    parameters,
                    context,
                    projections))
            {
                return false;
            }
        }

        if (projections.Count == 0)
            return false;

        // A LEFT WHERE must run only after the matching state has decided whether a null-extended
        // row exists. Only the bounded caller can opt into its narrow direct-comparison subset;
        // an INNER join instead folds WHERE into the per-pair predicate.
        var whereExpr = select.Where;
        if (whereExpr is not null
            && joinType == JoinType.LeftOuter
            && (!allowPostJoinWhere
                || !IsExactLeftOuterJoinWherePredicate(whereExpr, leftTarget, rightTarget)))
            return false;

        var condition = join.Condition;
        if (condition is not null && !IsCompilableJoinPredicate(condition, combinedTarget))
            return false;
        if (whereExpr is not null && !IsCompilableJoinPredicate(whereExpr, combinedTarget))
            return false;

        VdbeRowPredicate? predicate = null;
        VdbeRowPredicate? postJoinPredicate = null;
        if (joinType == JoinType.LeftOuter)
        {
            if (condition is not null)
            {
                predicate = row => IsTrue(Evaluate(
                    condition,
                    parameters,
                    new SourceRow(
                        combinedColumns,
                        row,
                        combinedQualified,
                        outerRow,
                        outputColumns,
                        ColumnDefinitions: combinedDefinitions,
                        QualifiedColumnDefinitions: combinedQualifiedDefinitions),
                    context));
            }

            if (whereExpr is not null)
            {
                postJoinPredicate = row => IsTrue(Evaluate(
                    whereExpr,
                    parameters,
                    new SourceRow(
                        combinedColumns,
                        row,
                        combinedQualified,
                        outerRow,
                        outputColumns,
                        ColumnDefinitions: combinedDefinitions,
                        QualifiedColumnDefinitions: combinedQualifiedDefinitions),
                    context));
            }
        }
        else if (condition is not null || whereExpr is not null)
        {
            // Reconstruct the combined SourceRow exactly as GetJoinRows does and defer value
            // semantics to the evaluator, so the compiled gate matches JoinConditionMatches
            // (ON) and the evaluator's post-join WHERE byte-for-byte.
            predicate = row =>
            {
                var combined = new SourceRow(
                    combinedColumns,
                    row,
                    combinedQualified,
                    outerRow,
                    outputColumns,
                    ColumnDefinitions: combinedDefinitions,
                    QualifiedColumnDefinitions: combinedQualifiedDefinitions);
                if (condition is not null && !IsTrue(Evaluate(condition, parameters, combined, context)))
                    return false;

                return whereExpr is null || IsTrue(Evaluate(whereExpr, parameters, combined, context));
            };
        }

        var program = JoinProgramBuilder.Build(
            leftTarget.TableName,
            leftWidth,
            rightTarget.TableName,
            rightColumns.Length,
            joinType,
            projections,
            predicate,
            postJoinPredicate);
        compiled = new CompiledSelect(
            program,
            [new VdbeCursorSource(leftTarget.Rows), new VdbeCursorSource(rightTarget.Rows)]);
        return true;
    }

    // Mirrors the evaluator's join projection: "*" expands to every join output column,
    // "t.*" to that source's raw columns, a bare column reads its combined ordinal, and a
    // constant scalar folds to a literal. Because a routed join carries no USING/NATURAL
    // coalescing, each output column's ordinal is its combined-row index, so a column read is
    // byte-identical to GetOutputValue. Anything else declines so the evaluator keeps it.
    private bool TryLowerJoinProjection(
        Expression expression,
        ScanTarget combinedTarget,
        IReadOnlyList<OutputColumn> outputColumns,
        IReadOnlyList<OutputColumn> rawOutputColumns,
        SqlValue[] parameters,
        QueryContext context,
        List<JoinProjection> projections)
    {
        switch (expression)
        {
            case StarExpression:
                if (outputColumns.Count == 0)
                    return false;

                foreach (var column in outputColumns)
                    projections.Add(JoinProjection.ForColumn(column.Index));
                return true;
            case QualifiedStarExpression qualifiedStar:
                // A qualifier that matches neither side declines so the evaluator raises its
                // exact "no such table" error on fallback.
                var matched = false;
                foreach (var column in rawOutputColumns)
                {
                    if (string.Equals(column.Qualifier, qualifiedStar.Qualifier, StringComparison.OrdinalIgnoreCase))
                    {
                        projections.Add(JoinProjection.ForColumn(column.Index));
                        matched = true;
                    }
                }

                return matched;
            case ColumnExpression column when combinedTarget.ResolveColumnIndex(column.Name) is { } columnIndex:
                projections.Add(JoinProjection.ForColumn(columnIndex));
                return true;
            default:
                if (IsConstantScalarExpression(expression))
                {
                    projections.Add(JoinProjection.ForConstant(Evaluate(expression, parameters, null, context)));
                    return true;
                }

                return false;
        }
    }

    // A join ON/WHERE clause is compilable when it can be evaluated against a single combined
    // row: it must be a row-at-a-time scan predicate (no subquery/EXISTS/aggregate) and must
    // not read a rowid pseudo-column, which a joined row never exposes.
    private bool IsCompilableJoinPredicate(Expression expression, ScanTarget combinedTarget)
        => IsScanPredicate(expression)
            && !ContainsRowValue(expression)
            && !ReferencesUnbackedRowid(expression, combinedTarget);

    private static bool ContainsRowValue(Expression expression)
    {
        return expression switch
        {
            RowValueExpression => true,
            FunctionExpression function => function.Arguments.Any(ContainsRowValue)
                || (function.Filter is not null && ContainsRowValue(function.Filter)),
            UnaryExpression unary => ContainsRowValue(unary.Operand),
            BinaryExpression binary => ContainsRowValue(binary.Left) || ContainsRowValue(binary.Right),
            CollationExpression collation => ContainsRowValue(collation.Expression),
            CastExpression cast => ContainsRowValue(cast.Expression),
            CaseExpression @case => (@case.Operand is not null && ContainsRowValue(@case.Operand))
                || @case.Clauses.Any(clause => ContainsRowValue(clause.When) || ContainsRowValue(clause.Then))
                || (@case.Else is not null && ContainsRowValue(@case.Else)),
            LikeExpression like => ContainsRowValue(like.Value)
                || ContainsRowValue(like.Pattern)
                || (like.Escape is not null && ContainsRowValue(like.Escape)),
            GlobExpression glob => ContainsRowValue(glob.Value) || ContainsRowValue(glob.Pattern),
            InExpression @in => ContainsRowValue(@in.Value) || @in.Values.Any(ContainsRowValue),
            InSubqueryExpression @in => ContainsRowValue(@in.Value),
            BetweenExpression between => ContainsRowValue(between.Value)
                || ContainsRowValue(between.Lower)
                || ContainsRowValue(between.Upper),
            _ => false,
        };
    }

    private static bool HaveStreamingSafeJoinCollations(
        ScanTarget left,
        ScanTarget right,
        QueryContext context)
    {
        return context.Tables.TryGetValue(left.TableName, out var leftTable)
            && context.Tables.TryGetValue(right.TableName, out var rightTable)
            && leftTable.ColumnDefinitions.All(column =>
                IsStreamingSafeDistinctCollation(column.Collation))
            && rightTable.ColumnDefinitions.All(column =>
                IsStreamingSafeDistinctCollation(column.Collation));
    }

    private static bool ContainsUnsafeCompiledCollation(Expression expression)
    {
        return expression switch
        {
            CollationExpression collation => !IsStreamingSafeDistinctCollation(collation.Name)
                || ContainsUnsafeCompiledCollation(collation.Expression),
            BinaryExpression binary => ContainsUnsafeCompiledCollation(binary.Left)
                || ContainsUnsafeCompiledCollation(binary.Right),
            UnaryExpression unary => ContainsUnsafeCompiledCollation(unary.Operand),
            FunctionExpression function => function.Arguments.Any(ContainsUnsafeCompiledCollation)
                || function.Filter is not null && ContainsUnsafeCompiledCollation(function.Filter),
            CastExpression cast => ContainsUnsafeCompiledCollation(cast.Expression),
            CaseExpression @case => @case.Operand is not null
                    && ContainsUnsafeCompiledCollation(@case.Operand)
                || @case.Clauses.Any(clause =>
                    ContainsUnsafeCompiledCollation(clause.When)
                    || ContainsUnsafeCompiledCollation(clause.Then))
                || @case.Else is not null && ContainsUnsafeCompiledCollation(@case.Else),
            LikeExpression like => ContainsUnsafeCompiledCollation(like.Value)
                || ContainsUnsafeCompiledCollation(like.Pattern)
                || like.Escape is not null && ContainsUnsafeCompiledCollation(like.Escape),
            InExpression @in => ContainsUnsafeCompiledCollation(@in.Value)
                || @in.Values.Any(ContainsUnsafeCompiledCollation),
            BetweenExpression between => ContainsUnsafeCompiledCollation(between.Value)
                || ContainsUnsafeCompiledCollation(between.Lower)
                || ContainsUnsafeCompiledCollation(between.Upper),
            GlobExpression glob => ContainsUnsafeCompiledCollation(glob.Value)
                || ContainsUnsafeCompiledCollation(glob.Pattern),
            _ => false,
        };
    }

    // Resolves a (possibly qualified) column reference to its ordinal in the combined
    // (left ++ right) row. Ambiguous bare names return null so compilation declines and the
    // evaluator reports SQLite's ambiguity diagnostic instead of silently choosing one side.
    private static int? ResolveCombinedColumnIndex(
        string name,
        string[] combinedColumns,
        IReadOnlyDictionary<string, int> combinedQualified)
    {
        if (combinedQualified.TryGetValue(name, out var qualifiedIndex))
            return qualifiedIndex;

        int? resolved = null;
        for (var index = 0; index < combinedColumns.Length; index++)
        {
            if (string.Equals(combinedColumns[index], name, StringComparison.OrdinalIgnoreCase))
            {
                if (resolved is not null)
                    return null;

                resolved = index;
            }
        }

        return resolved;
    }

    // General join lowering uses a materializing join cursor. The cursor recursively completes each
    // left/right input before evaluating its parent join, then applies WHERE to the complete joined row
    // set before projection. That reproduces the evaluator's observable source, error, and callback order
    // while allowing ordinary VDBE sorter, aggregate, DISTINCT, LIMIT, and result opcodes to own later phases.
    private bool TryCompileGeneralJoinSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled)
    {
        compiled = null!;
        if (select.Source is not JoinTableSource || select.Projections.Count == 0)
            return false;

        var hasAggregate = select.Projections.Any(projection => ContainsAggregate(projection.Expression))
            || select.GroupBy.Count != 0
            || select.Having is not null && ContainsAggregate(select.Having)
            || select.OrderBy.Any(term => ContainsAggregate(term.Expression));
        if (hasAggregate && (select.Limit is not null || select.Offset is not null)
            || CollectSelectWindowFunctions(select).Count != 0)
        {
            return false;
        }

        if (!TryResolveGeneralJoinLimit(select, parameters, context, outerRow, out var limit, out var offset))
            return false;

        if (limit == 0)
            return false;
        if (limit is < 0)
            limit = null;

        if (hasAggregate)
        {
            return TryCompileGeneralJoinAggregate(
                select,
                parameters,
                context,
                outerRow,
                limit,
                offset,
                out compiled);
        }

        if (select.Having is not null
            || select.GroupBy.Count != 0
            || select.Projections.Any(projection =>
                ContainsWindowFunction(projection.Expression)
                || projection.Expression is not (StarExpression or QualifiedStarExpression)
                    && !IsScanPredicate(projection.Expression))
            || select.Where is not null
                && (ContainsAggregate(select.Where)
                    || ContainsWindowFunction(select.Where)
                    || !IsScanPredicate(select.Where)))
        {
            return false;
        }

        if (!TryBuildCompiledJoinSource(
                select.Source,
                parameters,
                context,
                outerRow,
                out var source))
        {
            return false;
        }

        if (select.Where is not null && !IsSafeCompiledJoinPredicate(select.Where, source))
            return false;
        foreach (var projection in select.Projections)
        {
            if (projection.Expression is not (StarExpression or QualifiedStarExpression)
                && !AllCompiledJoinColumnsResolve(projection.Expression, source))
            {
                return false;
            }
        }

        var resolvedOrderBy = ResolveOrderBy(select.OrderBy, select.Projections);
        ValidateOrderByCollations(resolvedOrderBy);
        foreach (var term in resolvedOrderBy)
        {
            if (IndexExpressionSemantics.ContainsFunction(
                    term.Expression,
                    IsRegisteredScalarFunction)
                || !IsSafeCompiledJoinOrderTerm(term, source))
                return false;
        }

        VdbeJoinedRowPredicate? filter = null;
        if (select.Where is not null)
        {
            filter = row => IsTrue(Evaluate(
                select.Where,
                parameters,
                source.CreateSourceRow(row, outerRow),
                context));
        }

        // ExecuteSelect asks GetSourceRows for at most LIMIT rows only in this exact case. Preserve
        // that early source cut so an ON/projection callback beyond the bound is not invoked.
        var sourceConsumesLimit = select.Where is null
            && select.OrderBy.Count == 0
            && !select.Distinct
            && offset == 0
            && limit is >= 0;
        int? maximumRows = sourceConsumesLimit && limit <= int.MaxValue
            ? checked((int)limit.Value)
            : null;
        var plan = new VdbeJoinPlan(
            source.Plan,
            source.Description,
            filter,
            maximumRows: maximumRows);

        var outputColumns = source.OutputColumns;
        var rawOutputColumns = source.RawOutputColumns;
        var outputCount = GetColumnNames(select.Projections, outputColumns, rawOutputColumns).Length;
        if (outputCount == 0)
            return false;

        SqlValue[] Project(SqlValue[] record) => EvaluateProjectionRow(
            select,
            source.CreateSourceRow(record, outerRow),
            parameters,
            context,
            outputColumns,
            rawOutputColumns);

        VdbeRowComparer? orderComparer = null;
        if (resolvedOrderBy.Count != 0)
        {
            orderComparer = (left, right) => CompareRows(
                source.CreateSourceRow(left, outerRow),
                source.CreateSourceRow(right, outerRow),
                resolvedOrderBy,
                parameters,
                context);
        }

        VdbeRowEquality? distinctEquality = null;
        if (select.Distinct)
        {
            var collations = GetDistinctProjectionCollations(
                select.Projections,
                outputColumns,
                rawOutputColumns,
                select.Source,
                context);
            if (collations.Any(collation => !IsStreamingSafeDistinctCollation(collation)))
                return false;
            distinctEquality = (left, right) => RowsEqual(left, right, collations);
        }

        var program = CompiledJoinProgramBuilder.BuildProjection(
            plan,
            outputCount,
            Project,
            orderComparer,
            distinctEquality,
            sourceConsumesLimit ? 0 : offset,
            sourceConsumesLimit ? null : limit);
        compiled = new CompiledSelect(program, [new VdbeCursorSource([])]);
        return true;
    }

    private bool TryCompileGeneralJoinAggregate(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        long? limit,
        long offset,
        out CompiledSelect compiled)
    {
        compiled = null!;
        if (select.Distinct
            || select.OrderBy.Count != 0
            || select.Having is not null
            || limit is not null
            || offset != 0
            || select.Projections.Any(projection => ContainsWindowFunction(projection.Expression))
            || select.Where is not null
                && (ContainsAggregate(select.Where)
                    || ContainsWindowFunction(select.Where)
                    || !IsScanPredicate(select.Where)))
        {
            return false;
        }

        if (!TryBuildCompiledJoinSource(
                select.Source!,
                parameters,
                context,
                outerRow,
                out var source))
        {
            return false;
        }

        if (select.Where is not null && !IsSafeCompiledJoinPredicate(select.Where, source))
            return false;

        VdbeJoinedRowPredicate? filter = null;
        if (select.Where is not null)
        {
            filter = row => IsTrue(Evaluate(
                select.Where,
                parameters,
                source.CreateSourceRow(row, outerRow),
                context));
        }

        var grouped = select.GroupBy.Count != 0;
        var target = source.CreateScanTarget(grouped: false);
        if (select.Projections.Any(projection =>
                !CanCompileAggregateExpression(projection.Expression, target))
            || select.GroupBy.Any(expression =>
                !CanCompileAggregateExpression(expression, target)))
        {
            return false;
        }

        CompiledAggregateContext CreateContext() => new();
        object? CollectRow(object? stateObject, SqlValue[] values)
        {
            context.CheckInterrupt();
            var state = (CompiledAggregateContext)stateObject!;
            state.Rows.Add(source.CreateSourceRow(values, outerRow));
            return state;
        }

        SourceRow? GetRepresentative(CompiledAggregateContext state) =>
            state.GetRepresentative(() =>
                GetAggregateRepresentative(select, state.Rows, parameters, context));

        VdbeAggregate BuildFinalizer(Expression expression, bool aggregateMode) => new()
        {
            Name = GetAggregateExplainName(expression, "projection"),
            CreateContext = CreateContext,
            Accumulate = CollectRow,
            Finalize = stateObject =>
            {
                context.CheckInterrupt();
                var state = (CompiledAggregateContext)stateObject!;
                var representative = GetRepresentative(state);
                return aggregateMode
                    ? EvaluateAggregate(expression, state.Rows, parameters, context, representative)
                    : Evaluate(expression, parameters, representative, context);
            },
        };

        var collector = new VdbeAggregate
        {
            Name = "rows",
            CreateContext = CreateContext,
            Accumulate = CollectRow,
            Finalize = _ => throw new InvalidOperationException(
                "The row collector is stepped but never finalized directly."),
        };
        var outputs = select.Projections
            .Select(projection => BuildFinalizer(
                projection.Expression,
                aggregateMode: !grouped || ContainsAggregate(projection.Expression)))
            .ToArray();

        var plan = new VdbeJoinPlan(source.Plan, source.Description, filter, groupKey: null);
        VdbeProgram baseProgram;
        if (grouped)
        {
            var groupCollations = select.GroupBy
                .Select(expression => GetEffectiveCollation(expression, context))
                .ToArray();
            VdbeGroupKeyProjector groupKeyProjector = values =>
                EvaluateGroupKey(
                    select.GroupBy,
                    parameters,
                    source.CreateSourceRow(values, outerRow),
                    context);
            VdbeGroupComparer groupEquality = (left, right) =>
                GroupKeysEqual(left, right, groupCollations);
            VdbeRowComparer groupKeyOrder = (left, right) =>
            {
                context.CheckInterrupt();
                return CompareGroupKeysForOrdering(left, right, select.GroupBy.Count, groupCollations);
            };
            baseProgram = AggregateProgramBuilder.BuildRowGrouped(
                source.Description,
                target.Columns.Length,
                select.GroupBy.Count,
                groupKeyProjector,
                groupEquality,
                groupKeyOrder,
                collector,
                outputs,
                orderKeys: [],
                outputOrderComparer: (left, right) =>
                {
                    context.CheckInterrupt();
                    return CompareGroupKeysForOrdering(left, right, select.GroupBy.Count, groupCollations);
                },
                groupHasher: BuildGroupHasher(groupCollations));
        }
        else
        {
            baseProgram = AggregateProgramBuilder.BuildRowScalar(
                source.Description,
                target.Columns.Length,
                collector,
                outputs);
        }

        var program = CompiledJoinProgramBuilder.BindJoinCursor(baseProgram, plan);
        compiled = new CompiledSelect(program, [new VdbeCursorSource([])]);
        return true;
    }

    private bool TryResolveGeneralJoinLimit(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out long? limit,
        out long offset)
    {
        if (select.Limit is null && select.Offset is null)
        {
            limit = null;
            offset = 0;
            return true;
        }

        return TryResolveLimitOffset(select, parameters, context, outerRow, out limit, out offset);
    }

    private static bool IsSafeCompiledJoinOrderTerm(OrderByTerm term, CompiledJoinSource source)
    {
        var expression = term.Expression;
        while (expression is CollationExpression collation)
        {
            if (!IsStreamingSafeDistinctCollation(collation.Name))
                return false;
            expression = collation.Expression;
        }

        return expression is ColumnExpression column
            && source.ResolveColumnIndex(column.Name) is not null;
    }

    private static bool IsSafeCompiledJoinPredicate(
        Expression expression,
        CompiledJoinSource source)
        => IsSafeCompiledJoinPredicate(
            expression,
            source.ResolveColumnIndex,
            source.ResolveColumnDefinition);

    private static bool IsSafeCompiledJoinPredicate(
        Expression expression,
        string[] columns,
        IReadOnlyDictionary<string, int> qualifiedColumns,
        IReadOnlyList<EmbeddedColumn?> columnDefinitions,
        IReadOnlyDictionary<string, EmbeddedColumn> qualifiedColumnDefinitions,
        IReadOnlyDictionary<string, int> qualifiedRowIdIndices)
    {
        int? ResolveIndex(string name)
        {
            if (qualifiedColumns.TryGetValue(name, out var qualified))
                return qualified;
            int? resolved = null;
            for (var index = 0; index < columns.Length; index++)
            {
                if (string.Equals(columns[index], name, StringComparison.OrdinalIgnoreCase))
                {
                    if (resolved is not null)
                        return null;

                    resolved = index;
                }
            }
            if (resolved is not null)
                return resolved;

            var separator = name.IndexOf('.');
            return separator >= 0
                && EmbeddedTable.IsRowidAliasName(name[(separator + 1)..])
                && qualifiedRowIdIndices.TryGetValue(name[..separator], out var rowIdIndex)
                    ? columns.Length + rowIdIndex
                    : null;
        }

        EmbeddedColumn? ResolveDefinition(Expression candidate)
        {
            while (candidate is CollationExpression collation)
                candidate = collation.Expression;
            if (candidate is not ColumnExpression column)
                return null;
            if (qualifiedColumnDefinitions.TryGetValue(column.Name, out var qualified))
                return qualified;
            if (column.Qualifier is not null)
                return null;
            for (var index = 0; index < columns.Length && index < columnDefinitions.Count; index++)
            {
                if (string.Equals(columns[index], column.Name, StringComparison.OrdinalIgnoreCase))
                    return columnDefinitions[index];
            }

            return null;
        }

        return IsSafeCompiledJoinPredicate(expression, ResolveIndex, ResolveDefinition);
    }

    private static bool IsSafeCompiledJoinPredicate(
        Expression expression,
        Func<string, int?> resolveColumnIndex,
        Func<Expression, EmbeddedColumn?> resolveColumnDefinition)
    {
        if (expression is UnaryExpression { Operator: UnaryOperator.Not } unary)
        {
            return IsSafeCompiledJoinPredicate(
                unary.Operand,
                resolveColumnIndex,
                resolveColumnDefinition);
        }

        if (expression is BinaryExpression
            {
                Operator: BinaryOperator.And or BinaryOperator.Or,
            } logical)
        {
            return IsSafeCompiledJoinPredicate(
                    logical.Left,
                    resolveColumnIndex,
                    resolveColumnDefinition)
                && IsSafeCompiledJoinPredicate(
                    logical.Right,
                    resolveColumnIndex,
                    resolveColumnDefinition);
        }

        if (expression is not BinaryExpression comparison || !IsComparisonOperator(comparison.Operator))
            return false;
        return IsSafeCompiledJoinOperand(
                comparison.Left,
                resolveColumnIndex,
                resolveColumnDefinition)
            && IsSafeCompiledJoinOperand(
                comparison.Right,
                resolveColumnIndex,
                resolveColumnDefinition);
    }

    private static bool IsSafeCompiledJoinOperand(
        Expression expression,
        Func<string, int?> resolveColumnIndex,
        Func<Expression, EmbeddedColumn?> resolveColumnDefinition)
    {
        while (expression is CollationExpression collation)
        {
            if (!IsStreamingSafeDistinctCollation(collation.Name))
                return false;
            expression = collation.Expression;
        }

        if (expression is LiteralExpression or ParameterExpression)
            return true;
        if (expression is not ColumnExpression column || resolveColumnIndex(column.Name) is null)
            return false;

        var declaredCollation = resolveColumnDefinition(column)?.Collation;
        return IsStreamingSafeDistinctCollation(declaredCollation);
    }

    private static bool AllCompiledJoinColumnsResolve(
        Expression expression,
        CompiledJoinSource source)
    {
        return expression switch
        {
            LiteralExpression or ParameterExpression or CurrentTimeExpression => true,
            ColumnExpression column => source.ResolveColumnIndex(column.Name) is not null,
            FunctionExpression function => function.Arguments.All(argument =>
                    AllCompiledJoinColumnsResolve(argument, source))
                && (function.Filter is null || AllCompiledJoinColumnsResolve(function.Filter, source)),
            CollationExpression collation => AllCompiledJoinColumnsResolve(collation.Expression, source),
            CastExpression cast => AllCompiledJoinColumnsResolve(cast.Expression, source),
            CaseExpression @case => (@case.Operand is null
                    || AllCompiledJoinColumnsResolve(@case.Operand, source))
                && @case.Clauses.All(clause =>
                    AllCompiledJoinColumnsResolve(clause.When, source)
                    && AllCompiledJoinColumnsResolve(clause.Then, source))
                && (@case.Else is null || AllCompiledJoinColumnsResolve(@case.Else, source)),
            LikeExpression like => AllCompiledJoinColumnsResolve(like.Value, source)
                && AllCompiledJoinColumnsResolve(like.Pattern, source)
                && (like.Escape is null || AllCompiledJoinColumnsResolve(like.Escape, source)),
            InExpression @in => AllCompiledJoinColumnsResolve(@in.Value, source)
                && @in.Values.All(value => AllCompiledJoinColumnsResolve(value, source)),
            BetweenExpression between => AllCompiledJoinColumnsResolve(between.Value, source)
                && AllCompiledJoinColumnsResolve(between.Lower, source)
                && AllCompiledJoinColumnsResolve(between.Upper, source),
            UnaryExpression unary => AllCompiledJoinColumnsResolve(unary.Operand, source),
            GlobExpression glob => AllCompiledJoinColumnsResolve(glob.Value, source)
                && AllCompiledJoinColumnsResolve(glob.Pattern, source),
            BinaryExpression binary => AllCompiledJoinColumnsResolve(binary.Left, source)
                && AllCompiledJoinColumnsResolve(binary.Right, source),
            _ => false,
        };
    }

    private bool TryBuildCompiledJoinSource(
        TableSource source,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledJoinSource compiled)
    {
        if (source is NamedTableSource)
        {
            var target = ResolveScanTarget(source, context);
            if (target is null || target.Columns.Length == 0)
            {
                compiled = null!;
                return false;
            }

            var leafRowIdIndices = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            if (target.HasRowId)
                leafRowIdIndices.Add(target.Qualifier, 0);
            var table = context.Tables[target.TableName];
            var leafColumnDefinitions = table.ColumnDefinitions
                .Select(static column => (EmbeddedColumn?)column)
                .ToArray();
            var leafQualifiedColumnDefinitions = BuildQualifiedColumnDefinitions(
                target.Qualifier,
                table.ColumnDefinitions);
            compiled = new CompiledJoinSource(
                new VdbeJoinScanPlan(
                    target.TableName,
                    target.Columns.Length,
                    new VdbeCursorSource(target.Rows, target.RowIds)),
                target.TableName,
                target.Columns,
                BuildQualifiedColumns(target.Qualifier, target.Columns),
                leafRowIdIndices,
                leafColumnDefinitions,
                leafQualifiedColumnDefinitions,
                BuildOutputColumns(target.Qualifier, target.Columns),
                BuildOutputColumns(target.Qualifier, target.Columns));
            return true;
        }

        if (source is not JoinTableSource join
            || join.Condition is not null
                && (ContainsAggregate(join.Condition)
                    || ContainsWindowFunction(join.Condition)
                    || !IsScanPredicate(join.Condition))
            || !TryBuildCompiledJoinSource(
                join.Left,
                parameters,
                context,
                outerRow,
                out var left)
            || !TryBuildCompiledJoinSource(
                join.Right,
                parameters,
                context,
                outerRow,
                out var right))
        {
            compiled = null!;
            return false;
        }

        var columns = left.Columns.Concat(right.Columns).ToArray();
        var qualifiedColumns = CombineQualifiedColumns(
            left.QualifiedColumns,
            right.QualifiedColumns,
            left.Columns.Length);
        var qualifiedRowIds = new Dictionary<string, int>(
            left.QualifiedRowIdIndices,
            StringComparer.OrdinalIgnoreCase);
        foreach (var (qualifier, index) in right.QualifiedRowIdIndices)
            qualifiedRowIds.TryAdd(qualifier, left.SourceCount + index);
        var columnDefinitions = left.ColumnDefinitions.Concat(right.ColumnDefinitions).ToArray();
        var qualifiedColumnDefinitions = new Dictionary<string, EmbeddedColumn>(
            left.QualifiedColumnDefinitions,
            StringComparer.OrdinalIgnoreCase);
        foreach (var (name, definition) in right.QualifiedColumnDefinitions)
            qualifiedColumnDefinitions.TryAdd(name, definition);
        var outputColumns = GetOutputColumns(join, context);
        var rawOutputColumns = GetRawOutputColumns(join, context);
        var joinPairs = BuildJoinPairs(join, context);
        if (join.Condition is not null
            && !IsSafeCompiledJoinPredicate(
                join.Condition,
                columns,
                qualifiedColumns,
                columnDefinitions,
                qualifiedColumnDefinitions,
                qualifiedRowIds))
        {
            compiled = null!;
            return false;
        }

        SourceRow CombinedRow(VdbeJoinRow row) => CreateCompiledJoinSourceRow(
            columns,
            row.Values,
            qualifiedColumns,
            qualifiedRowIds,
            row.RowIds,
            outputColumns,
            outerRow,
            columnDefinitions,
            qualifiedColumnDefinitions);
        VdbeJoinCondition condition = (leftRow, rightRow, combinedRow) =>
        {
            if (join.Condition is not null)
                return IsTrue(Evaluate(join.Condition, parameters, CombinedRow(combinedRow), context));

            var leftSourceRow = left.CreateSourceRow(leftRow, outerRow);
            var rightSourceRow = right.CreateSourceRow(rightRow, outerRow);
            foreach (var (leftColumn, rightColumn) in joinPairs)
            {
                if (!JoinPairMatches(
                        join,
                        leftColumn,
                        rightColumn,
                        leftSourceRow,
                        rightSourceRow,
                        context))
                    return false;
            }

            return true;
        };

        var kind = join.Kind switch
        {
            JoinKind.Inner => VdbeJoinKind.Inner,
            JoinKind.Left => VdbeJoinKind.Left,
            JoinKind.Right => VdbeJoinKind.Right,
            JoinKind.Full => VdbeJoinKind.Full,
            _ => throw new InvalidOperationException($"Unknown join kind {join.Kind}."),
        };
        var plan = new VdbeJoinOperatorPlan(
            left.Plan,
            right.Plan,
            kind,
            join.Condition is null && joinPairs.Count == 0 ? null : condition);
        compiled = new CompiledJoinSource(
            plan,
            $"{plan.SourceCount}-way {kind.ToString().ToUpperInvariant()} join",
            columns,
            qualifiedColumns,
            qualifiedRowIds,
            columnDefinitions,
            qualifiedColumnDefinitions,
            outputColumns,
            rawOutputColumns);
        return true;
    }

    private static SourceRow CreateCompiledJoinSourceRow(
        string[] columns,
        SqlValue[] values,
        IReadOnlyDictionary<string, int> qualifiedColumns,
        IReadOnlyDictionary<string, int> qualifiedRowIdIndices,
        IReadOnlyList<long?> rowIds,
        IReadOnlyList<OutputColumn> outputColumns,
        SourceRow? outerRow,
        IReadOnlyList<EmbeddedColumn?> columnDefinitions,
        IReadOnlyDictionary<string, EmbeddedColumn> qualifiedColumnDefinitions)
    {
        var qualifiedRowIds = new Dictionary<string, long?>(
            qualifiedRowIdIndices.Count,
            StringComparer.OrdinalIgnoreCase);
        foreach (var (qualifier, index) in qualifiedRowIdIndices)
            qualifiedRowIds.Add(qualifier, rowIds[index]);
        return new SourceRow(
            columns,
            values,
            qualifiedColumns,
            outerRow,
            outputColumns,
            QualifiedRowIds: qualifiedRowIds,
            ColumnDefinitions: columnDefinitions,
            QualifiedColumnDefinitions: qualifiedColumnDefinitions);
    }

    private static IReadOnlyDictionary<string, EmbeddedColumn> BuildQualifiedColumnDefinitions(
        string qualifier,
        IReadOnlyList<EmbeddedColumn> columns)
    {
        var definitions = new Dictionary<string, EmbeddedColumn>(StringComparer.OrdinalIgnoreCase);
        foreach (var column in columns)
            definitions.TryAdd($"{qualifier}.{column.Name}", column);
        return definitions;
    }

    private sealed class CompiledJoinSource(
        VdbeJoinPlanNode plan,
        string description,
        string[] columns,
        IReadOnlyDictionary<string, int> qualifiedColumns,
        IReadOnlyDictionary<string, int> qualifiedRowIdIndices,
        IReadOnlyList<EmbeddedColumn?> columnDefinitions,
        IReadOnlyDictionary<string, EmbeddedColumn> qualifiedColumnDefinitions,
        IReadOnlyList<OutputColumn> outputColumns,
        IReadOnlyList<OutputColumn> rawOutputColumns)
    {
        public VdbeJoinPlanNode Plan { get; } = plan;

        public string Description { get; } = description;

        public string[] Columns { get; } = columns;

        public IReadOnlyDictionary<string, int> QualifiedColumns { get; } = qualifiedColumns;

        public IReadOnlyDictionary<string, int> QualifiedRowIdIndices { get; } = qualifiedRowIdIndices;

        public IReadOnlyList<EmbeddedColumn?> ColumnDefinitions { get; } = columnDefinitions;

        public IReadOnlyDictionary<string, EmbeddedColumn> QualifiedColumnDefinitions { get; } =
            qualifiedColumnDefinitions;

        public IReadOnlyList<OutputColumn> OutputColumns { get; } = outputColumns;

        public IReadOnlyList<OutputColumn> RawOutputColumns { get; } = rawOutputColumns;

        public int SourceCount => Plan.SourceCount;

        public SourceRow CreateSourceRow(VdbeJoinRow row, SourceRow? outerRow)
            => CreateCompiledJoinSourceRow(
                Columns,
                row.Values,
                QualifiedColumns,
                QualifiedRowIdIndices,
                row.RowIds,
                OutputColumns,
                outerRow,
                ColumnDefinitions,
                QualifiedColumnDefinitions);

        public SourceRow CreateSourceRow(SqlValue[] record, SourceRow? outerRow)
        {
            var values = new SqlValue[Columns.Length];
            Array.Copy(record, values, values.Length);
            var rowIds = new long?[SourceCount];
            for (var index = 0; index < rowIds.Length; index++)
            {
                var value = record[Columns.Length + index];
                rowIds[index] = value.Kind == SqlValueKind.Null ? null : value.AsInteger();
            }

            return CreateCompiledJoinSourceRow(
                Columns,
                values,
                QualifiedColumns,
                QualifiedRowIdIndices,
                rowIds,
                OutputColumns,
                outerRow,
                ColumnDefinitions,
                QualifiedColumnDefinitions);
        }

        public int? ResolveColumnIndex(string name)
        {
            if (QualifiedColumns.TryGetValue(name, out var qualified))
                return qualified;

            int? resolved = null;
            for (var index = 0; index < Columns.Length; index++)
            {
                if (string.Equals(Columns[index], name, StringComparison.OrdinalIgnoreCase))
                {
                    if (resolved is not null)
                        return null;

                    resolved = index;
                }
            }
            if (resolved is not null)
                return resolved;

            var separator = name.IndexOf('.');
            if (separator >= 0
                && EmbeddedTable.IsRowidAliasName(name[(separator + 1)..])
                && QualifiedRowIdIndices.TryGetValue(name[..separator], out var rowIdIndex))
            {
                return Columns.Length + rowIdIndex;
            }

            return null;
        }

        public EmbeddedColumn? ResolveColumnDefinition(Expression expression)
        {
            while (expression is CollationExpression collation)
                expression = collation.Expression;
            if (expression is not ColumnExpression column)
                return null;
            if (QualifiedColumnDefinitions.TryGetValue(column.Name, out var qualified))
                return qualified;
            if (column.Qualifier is not null)
                return null;
            for (var index = 0; index < Columns.Length && index < ColumnDefinitions.Count; index++)
            {
                if (string.Equals(Columns[index], column.Name, StringComparison.OrdinalIgnoreCase))
                    return ColumnDefinitions[index];
            }

            return null;
        }

        public bool IsCoalescedColumn(ColumnExpression column)
        {
            if (column.Qualifier is not null)
                return false;
            return OutputColumns.Any(output =>
                (output.CoalesceIndex is not null || output.AdditionalCoalesceIndices is { Count: > 0 })
                && string.Equals(output.Name, column.Name, StringComparison.OrdinalIgnoreCase));
        }

        public ScanTarget CreateScanTarget(bool grouped)
        {
            var recordColumns = new string[checked(Columns.Length + SourceCount + (grouped ? 1 : 0))];
            Array.Copy(Columns, recordColumns, Columns.Length);
            for (var index = 0; index < SourceCount; index++)
                recordColumns[Columns.Length + index] = $"__join_rowid_{index}";
            if (grouped)
                recordColumns[^1] = "__join_group_ordinal";
            return new ScanTarget(
                Description,
                Description,
                recordColumns,
                [],
                ResolveColumnIndex);
        }
    }

    // Lowers a whole-table (scalar) or GROUP BY aggregation over a single base table into a
    // real VdbeProgram driven by the AggReset/AggStep/AggFinalize opcode family (plus the
    // sorter and SameGroup/Goto control flow for grouping), or returns false so the
    // evaluator keeps ownership of shapes the aggregate route cannot preserve exactly.
    //
    // The row-aware accumulator stores complete source rows, allowing finalizers to reuse
    // EvaluateAggregate for computed arguments, DISTINCT/FILTER, composite projections,
    // HAVING, and SQLite's representative-row MIN/MAX rules. Group keys are projected once
    // in filtered source order before the grouping sorter.
    //
    // Grouped HAVING/ORDER expressions whose callbacks or failures would run at a different
    // phase remain evaluator-owned. The grouped VM finalizes one group at a time before its
    // output sorter drains, whereas the evaluator finalizes all projections before HAVING
    // and sorting; declining those observable shapes preserves callback and error order.
    private bool TryCompileAggregateSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled,
        ScanTarget? targetOverride = null)
    {
        compiled = null!;

        if (select.Limit is not null
            || select.Offset is not null
            || select.Projections.Count == 0)
        {
            return false;
        }

        var grouped = select.GroupBy.Count > 0;
        var hasAggregate = select.Projections.Any(projection => ContainsAggregate(projection.Expression))
            || select.Having is not null && ContainsAggregate(select.Having)
            || select.OrderBy.Any(term => ContainsAggregate(term.Expression));
        if (!grouped && !hasAggregate)
            return false;
        if (select.GroupBy.Any(ContainsAggregate))
            return false;
        if (select.Projections.Any(projection => ContainsWindowFunction(projection.Expression))
            || select.GroupBy.Any(ContainsWindowFunction)
            || select.Having is not null && ContainsWindowFunction(select.Having)
            || select.OrderBy.Any(term => ContainsWindowFunction(term.Expression)))
        {
            return false;
        }

        var target = targetOverride ?? ResolveScanTarget(select.Source, context);
        if (target is null)
            return false;

        var resolvedOrderBy = ResolveOrderBy(select.OrderBy, select.Projections);
        ValidateOrderByCollations(resolvedOrderBy);
        ValidateGroupByCollations(select.GroupBy);

        var aggregateExpressions = select.Projections
            .Select(projection => projection.Expression)
            .Concat(select.GroupBy)
            .Concat(select.Having is null ? [] : [select.Having])
            .Concat(resolvedOrderBy.Select(term => term.Expression));
        foreach (var expression in aggregateExpressions)
        {
            if (!CanCompileAggregateExpression(expression, target))
                return false;
        }

        var groupKeyHasObservableEvaluation = grouped && select.GroupBy.Any(expression =>
            ContainsDeferredAggregateHazard(expression, sumIsHazard: false)
            || ContainsEffectiveCustomCollation(expression, context));
        if (groupKeyHasObservableEvaluation
            && select.Where is not null
            && (ContainsDeferredAggregateHazard(
                    select.Where,
                    sumIsHazard: false)
                || ContainsEffectiveCustomCollation(select.Where, context)))
        {
            return false;
        }

        if (grouped && select.Having is not null
            && (ContainsDeferredAggregateHazard(select.Having, sumIsHazard: true)
                || ContainsEffectiveCustomCollation(select.Having, context)))
        {
            return false;
        }

        if (grouped && resolvedOrderBy.Any(term =>
                ContainsDeferredAggregateHazard(
                    term.Expression,
                    sumIsHazard: !select.Projections.Any(projection =>
                        ReferenceEquals(projection.Expression, term.Expression)))
                || ContainsEffectiveCustomCollation(term.Expression, context)))
        {
            return false;
        }

        VdbeRowPredicate? predicate = null;
        if (select.Where is not null)
        {
            predicate = CompileRowPredicate(select.Where, target, parameters, context, outerRow);
            if (predicate is null)
                return false;
        }

        CompiledAggregateContext CreateContext() => new();

        object? CollectRow(object? stateObject, SqlValue[] values)
        {
            context.CheckInterrupt();
            var state = (CompiledAggregateContext)stateObject!;
            state.Rows.Add(CreateScanSourceRow(target, values, context, outerRow));
            return state;
        }

        SourceRow? GetRepresentative(CompiledAggregateContext state) =>
            state.GetRepresentative(() =>
                GetAggregateRepresentative(select, state.Rows, parameters, context));

        VdbeAggregate BuildFinalizer(Expression expression, bool aggregateMode, string role)
        {
            return new VdbeAggregate
            {
                Name = GetAggregateExplainName(expression, role),
                CreateContext = CreateContext,
                Accumulate = CollectRow,
                Finalize = stateObject =>
                {
                    context.CheckInterrupt();
                    var state = (CompiledAggregateContext)stateObject!;
                    var representative = GetRepresentative(state);
                    var value = aggregateMode
                        ? EvaluateAggregate(expression, state.Rows, parameters, context, representative)
                        : Evaluate(expression, parameters, representative, context);
                    context.CheckInterrupt();
                    return value;
                },
            };
        }

        var collector = new VdbeAggregate
        {
            Name = "rows",
            CreateContext = CreateContext,
            Accumulate = CollectRow,
            Finalize = _ => throw new InvalidOperationException(
                "The row collector is stepped but never finalized directly."),
        };
        var outputs = select.Projections
            .Select(projection => BuildFinalizer(
                projection.Expression,
                aggregateMode: !grouped || ContainsAggregate(projection.Expression),
                role: "projection"))
            .ToArray();
        var having = select.Having is null
            ? null
            : new AggregateFinalizerFilter(
                BuildFinalizer(
                    select.Having,
                    aggregateMode: !grouped || hasAggregate,
                    role: "having"),
                values => IsTrue(values[0]),
                "skip aggregate result when HAVING is false");
        var distinctEquality = select.Distinct
            ? BuildAggregateResultEquality(select.Projections, context)
            : null;

        VdbeProgram program;
        if (grouped)
        {
            var groupCollations = select.GroupBy
                .Select(expression => GetEffectiveCollation(expression, context))
                .ToArray();
            VdbeGroupKeyProjector groupKeyProjector = values =>
            {
                context.CheckInterrupt();
                var row = CreateScanSourceRow(target, values, context, outerRow);
                var key = new SqlValue[select.GroupBy.Count];
                for (var index = 0; index < key.Length; index++)
                {
                    context.CheckInterrupt();
                    key[index] = Evaluate(select.GroupBy[index], parameters, row, context);
                }

                return key;
            };
            VdbeGroupComparer groupEquality = (left, right) =>
                GroupKeysEqual(left, right, groupCollations);
            VdbeRowComparer groupKeyOrder = (left, right) =>
            {
                context.CheckInterrupt();
                return CompareGroupKeysForOrdering(left, right, select.GroupBy.Count, groupCollations);
            };

            var orderKeys = resolvedOrderBy
                .Select(term => BuildFinalizer(
                    term.Expression,
                    ContainsAggregate(term.Expression),
                    role: "order"))
                .ToArray();
            VdbeRowComparer outputOrderComparer = (left, right) =>
            {
                context.CheckInterrupt();
                for (var index = 0; index < resolvedOrderBy.Count; index++)
                {
                    var term = resolvedOrderBy[index];
                    var comparison = CompareForOrdering(
                        left[index],
                        right[index],
                        term,
                        GetEffectiveCollation(term.Expression, context));
                    if (comparison != 0)
                        return comparison;
                }

                // ORDER BY ties (and statements without ORDER BY) fall back to
                // ascending group-key order, the order SQLite's aggregation sorter emits.
                return CompareGroupKeysForOrdering(
                    left,
                    right,
                    select.GroupBy.Count,
                    groupCollations,
                    offset: resolvedOrderBy.Count);
            };

            program = AggregateProgramBuilder.BuildRowGrouped(
                target.TableName,
                target.Columns.Length,
                select.GroupBy.Count,
                groupKeyProjector,
                groupEquality,
                groupKeyOrder,
                collector,
                outputs,
                orderKeys,
                outputOrderComparer,
                predicate,
                having,
                distinctEquality,
                BuildGroupHasher(groupCollations));
        }
        else
        {
            program = AggregateProgramBuilder.BuildRowScalar(
                target.TableName,
                target.Columns.Length,
                collector,
                outputs,
                predicate,
                having,
                distinctEquality);
        }

        compiled = new CompiledSelect(program, [new VdbeCursorSource(target.Rows)]);
        return true;
    }

    private bool TryCompileCountStarShortcut(
        SelectStatement select,
        QueryContext context,
        out CompiledSelect compiled)
    {
        compiled = null!;
        if (!IsBareCountStarSelect(select))
            return false;

        var target = ResolveScanTarget(select.Source, context);
        if (target is null)
            return false;

        // Pump the connection's progress handler once per counted row so an interruptible
        // SELECT count(*) FROM t raises SQLITE_INTERRUPT at the same point the scan+accumulator
        // path would. Null when no handler is registered keeps the shortcut O(1) in the common case.
        Action? driveProgress = null;
        if (context.Hooks?.Progress is not null)
            driveProgress = () => context.CheckInterrupt();
        compiled = new CompiledSelect(
            AggregateProgramBuilder.BuildCountStar(target.TableName, target.Columns.Length, driveProgress),
            [new VdbeCursorSource(target.Rows)]);
        return true;
    }

    private static bool IsBareCountStarSelect(SelectStatement select)
    {
        // The exact shape `SELECT COUNT(*) FROM <source>` with no WHERE/GROUP BY/HAVING/
        // ORDER BY/DISTINCT/LIMIT/OFFSET and no FILTER/OVER on the COUNT(*). Any deviation
        // must keep the scan+accumulator path: a WHERE changes the counted rows, GROUP BY
        // produces per-group rows, ORDER BY/DISTINCT/LIMIT/OFFSET change the output shape,
        // and FILTER/OVER make COUNT(*) row-conditional or windowed. The gate fires only
        // when COUNT(*) over the whole source equals the bound row source's row count, so
        // the shortcut is semantically exact. Limit/Offset are already excluded upstream
        // but are re-checked here so the helper stays self-contained.
        if (select.Distinct
            || select.Where is not null
            || select.GroupBy.Count > 0
            || select.Having is not null
            || select.OrderBy.Count > 0
            || select.Limit is not null
            || select.Offset is not null
            || select.Projections.Count != 1)
        {
            return false;
        }

        return IsCountStarFunction(select.Projections[0].Expression);
    }

    private static bool IsCountStarFunction(Expression expression)
    {
        return expression is FunctionExpression function
            && string.Equals(function.Name, "COUNT", StringComparison.OrdinalIgnoreCase)
            && function.CountStar
            && function.Arguments.Count == 0
            && !function.Distinct
            && function.Filter is null
            && function.Window is null;
    }

    private static bool CanCompileAggregateExpression(Expression expression, ScanTarget target)
    {
        return expression switch
        {
            LiteralExpression or CurrentTimeExpression or ParameterExpression => true,
            ColumnExpression column => target.ResolveColumnIndex(column.Name) is not null,
            FunctionExpression function => function.Window is null
                && function.Arguments.All(argument => CanCompileAggregateExpression(argument, target))
                && (function.Filter is null || CanCompileAggregateExpression(function.Filter, target)),
            UnaryExpression unary => CanCompileAggregateExpression(unary.Operand, target),
            BinaryExpression binary => CanCompileAggregateExpression(binary.Left, target)
                && CanCompileAggregateExpression(binary.Right, target),
            CollationExpression collation => CanCompileAggregateExpression(collation.Expression, target),
            CastExpression cast => CanCompileAggregateExpression(cast.Expression, target),
            CaseExpression @case => (@case.Operand is null
                    || CanCompileAggregateExpression(@case.Operand, target))
                && @case.Clauses.All(clause =>
                    CanCompileAggregateExpression(clause.When, target)
                    && CanCompileAggregateExpression(clause.Then, target))
                && (@case.Else is null || CanCompileAggregateExpression(@case.Else, target)),
            LikeExpression like => CanCompileAggregateExpression(like.Value, target)
                && CanCompileAggregateExpression(like.Pattern, target)
                && (like.Escape is null || CanCompileAggregateExpression(like.Escape, target)),
            GlobExpression glob => CanCompileAggregateExpression(glob.Value, target)
                && CanCompileAggregateExpression(glob.Pattern, target),
            InExpression @in => CanCompileAggregateExpression(@in.Value, target)
                && @in.Values.All(value => CanCompileAggregateExpression(value, target)),
            BetweenExpression between => CanCompileAggregateExpression(between.Value, target)
                && CanCompileAggregateExpression(between.Lower, target)
                && CanCompileAggregateExpression(between.Upper, target),
            _ => false,
        };
    }

    // Grouped finalizers run one group at a time in the VDBE, while the evaluator
    // finishes every projection before its HAVING and ORDER BY phases. Keep expressions
    // with observable callbacks or failures on the evaluator at those deferred phases.
    private bool ContainsDeferredAggregateHazard(
        Expression expression,
        bool sumIsHazard)
    {
        return expression switch
        {
            FunctionExpression function when function.Window is not null => true,
            FunctionExpression { Name: "SUM" } when sumIsHazard => true,
            FunctionExpression function when IsManagedPercentileAggregate(function.Name) => true,
            FunctionExpression function
                when TryGetAggregateFunction(function.Name, function.Arguments.Count, out _) => true,
            FunctionExpression function when !IsBuiltInAggregate(function) => true,
            FunctionExpression function => function.Arguments.Any(argument =>
                    ContainsDeferredAggregateHazard(argument, sumIsHazard))
                || function.Filter is not null
                    && ContainsDeferredAggregateHazard(function.Filter, sumIsHazard),
            BinaryExpression binary when binary.Operator is BinaryOperator.Add
                or BinaryOperator.Subtract
                or BinaryOperator.Multiply
                or BinaryOperator.Divide
                or BinaryOperator.Modulo
                or BinaryOperator.JsonArrow
                or BinaryOperator.JsonArrowText => true,
            UnaryExpression unary => ContainsDeferredAggregateHazard(
                unary.Operand,
                sumIsHazard),
            BinaryExpression binary => ContainsDeferredAggregateHazard(
                    binary.Left,
                    sumIsHazard)
                || ContainsDeferredAggregateHazard(binary.Right, sumIsHazard),
            CollationExpression collation when IsCustomCollation(collation.Name) => true,
            CollationExpression collation => ContainsDeferredAggregateHazard(
                collation.Expression,
                sumIsHazard),
            CastExpression cast => ContainsDeferredAggregateHazard(
                cast.Expression,
                sumIsHazard),
            CaseExpression @case => (@case.Operand is not null
                    && ContainsDeferredAggregateHazard(
                        @case.Operand,
                        sumIsHazard))
                || @case.Clauses.Any(clause =>
                    ContainsDeferredAggregateHazard(clause.When, sumIsHazard)
                    || ContainsDeferredAggregateHazard(clause.Then, sumIsHazard))
                || @case.Else is not null
                    && ContainsDeferredAggregateHazard(
                        @case.Else,
                        sumIsHazard),
            LikeExpression or GlobExpression or ScalarSubqueryExpression or ExistsExpression
                or InSubqueryExpression => true,
            InExpression @in => ContainsDeferredAggregateHazard(
                    @in.Value,
                    sumIsHazard)
                || @in.Values.Any(value =>
                    ContainsDeferredAggregateHazard(value, sumIsHazard)),
            BetweenExpression between => ContainsDeferredAggregateHazard(
                    between.Value,
                    sumIsHazard)
                || ContainsDeferredAggregateHazard(between.Lower, sumIsHazard)
                || ContainsDeferredAggregateHazard(between.Upper, sumIsHazard),
            _ => false,
        };
    }

    private bool ContainsEffectiveCustomCollation(
        Expression expression,
        QueryContext context)
    {
        if (IsUnsafeCompiledCollation(GetEffectiveCollation(expression, context)))
            return true;

        return expression switch
        {
            FunctionExpression function => function.Arguments.Any(argument =>
                    ContainsEffectiveCustomCollation(argument, context))
                || function.Filter is not null
                    && ContainsEffectiveCustomCollation(function.Filter, context),
            UnaryExpression unary => ContainsEffectiveCustomCollation(unary.Operand, context),
            BinaryExpression binary => ContainsEffectiveCustomCollation(binary.Left, context)
                || ContainsEffectiveCustomCollation(binary.Right, context),
            CollationExpression collation => ContainsEffectiveCustomCollation(
                collation.Expression,
                context),
            CastExpression cast => ContainsEffectiveCustomCollation(cast.Expression, context),
            CaseExpression @case => @case.Operand is not null
                    && ContainsEffectiveCustomCollation(@case.Operand, context)
                || @case.Clauses.Any(clause =>
                    ContainsEffectiveCustomCollation(clause.When, context)
                    || ContainsEffectiveCustomCollation(clause.Then, context))
                || @case.Else is not null
                    && ContainsEffectiveCustomCollation(@case.Else, context),
            LikeExpression like => ContainsEffectiveCustomCollation(like.Value, context)
                || ContainsEffectiveCustomCollation(like.Pattern, context)
                || like.Escape is not null
                    && ContainsEffectiveCustomCollation(like.Escape, context),
            GlobExpression glob => ContainsEffectiveCustomCollation(glob.Value, context)
                || ContainsEffectiveCustomCollation(glob.Pattern, context),
            InExpression @in => ContainsEffectiveCustomCollation(@in.Value, context)
                || @in.Values.Any(value => ContainsEffectiveCustomCollation(value, context)),
            InSubqueryExpression @in => ContainsEffectiveCustomCollation(@in.Value, context),
            BetweenExpression between => ContainsEffectiveCustomCollation(between.Value, context)
                || ContainsEffectiveCustomCollation(between.Lower, context)
                || ContainsEffectiveCustomCollation(between.Upper, context),
            _ => false,
        };
    }

    private bool IsUnsafeCompiledCollation(string? collation)
        => IsCustomCollation(collation) || IsOverriddenBuiltInCollation(collation);

    private bool IsOverriddenBuiltInCollation(string? collation)
        => IsBuiltInCollation(collation)
            && _collations.ContainsKey(collation ?? "BINARY");

    private static bool IsBuiltInCollation(string? collation)
        => collation is null
            || collation.Equals("BINARY", StringComparison.OrdinalIgnoreCase)
            || collation.Equals("NOCASE", StringComparison.OrdinalIgnoreCase)
            || collation.Equals("RTRIM", StringComparison.OrdinalIgnoreCase);

    private static bool IsCustomCollation(string? collation) =>
        collation is not null
        && !collation.Equals("BINARY", StringComparison.OrdinalIgnoreCase)
        && !collation.Equals("NOCASE", StringComparison.OrdinalIgnoreCase)
        && !collation.Equals("RTRIM", StringComparison.OrdinalIgnoreCase);

    private static bool CollationsEquivalent(string? left, string? right) =>
        string.Equals(
            left ?? "BINARY",
            right ?? "BINARY",
            StringComparison.OrdinalIgnoreCase);

    private static string GetAggregateExplainName(Expression expression, string role) =>
        expression is FunctionExpression function && function.Window is null
            ? function.Name.ToLowerInvariant()
            : role;

    private VdbeRowEquality BuildAggregateResultEquality(
        IReadOnlyList<Projection> projections,
        QueryContext context)
    {
        var collations = projections
            .Select(projection => GetEffectiveCollation(projection.Expression, context))
            .ToArray();
        return (left, right) => RowsEqual(left, right, collations);
    }

    private bool GroupKeysEqual(
        SqlValue[] left,
        SqlValue[] right,
        IReadOnlyList<string?> collations)
    {
        if (left.Length != right.Length || left.Length != collations.Count)
            return false;

        for (var index = 0; index < left.Length; index++)
        {
            if (!DistinctValuesEqual(left[index], right[index], collations[index]))
                return false;
        }

        return true;
    }

    // Orders two group keys the way SQLite's aggregation sorter does: NULLs first,
    // then per-key collation-aware comparison, left to right. The equality guard
    // returns 0 for keys GroupKeysEqual would merge, which keeps one group's rows
    // contiguous in the sorter even if a collation's ordering and equality ever
    // disagreed. <paramref name="offset"/> skips leading non-key slots (the output
    // record carries ORDER BY keys before the group key).
    private int CompareGroupKeysForOrdering(
        IReadOnlyList<SqlValue> left,
        IReadOnlyList<SqlValue> right,
        int count,
        IReadOnlyList<string?> collations,
        int offset = 0)
    {
        var equal = true;
        for (var index = 0; index < count; index++)
        {
            if (!DistinctValuesEqual(left[offset + index], right[offset + index], collations[index]))
            {
                equal = false;
                break;
            }
        }

        if (equal)
            return 0;

        for (var index = 0; index < count; index++)
        {
            var comparison = CompareGroupKeyValues(
                left[offset + index],
                right[offset + index],
                collations[index]);
            if (comparison != 0)
                return comparison;
        }

        return 0;
    }

    private int CompareGroupKeyValues(SqlValue left, SqlValue right, string? collation)
    {
        if (left.Kind == SqlValueKind.Null || right.Kind == SqlValueKind.Null)
            return left.Kind == right.Kind ? 0 : left.Kind == SqlValueKind.Null ? -1 : 1;
        return Compare(left, right, collation);
    }

    private VdbeGroupHasher? BuildGroupHasher(
        IReadOnlyList<string?> collations)
    {
        if (collations.Any(IsUnsafeCompiledCollation))
            return null;

        return key =>
        {
            if (key.Length != collations.Count)
                throw new InvalidOperationException("GROUP BY hash key width does not match its collation vector.");

            var hash = new HashCode();
            for (var index = 0; index < key.Length; index++)
                AddGroupHash(ref hash, key[index], collations[index]);
            return hash.ToHashCode();
        };
    }

    private static void AddGroupHash(
        ref HashCode hash,
        SqlValue value,
        string? collation)
    {
        switch (value.Kind)
        {
            case SqlValueKind.Null:
                hash.Add(0);
                return;
            case SqlValueKind.Integer:
                hash.Add(1);
                hash.Add((double)value.AsInteger());
                return;
            case SqlValueKind.Real:
                hash.Add(1);
                hash.Add(value.AsReal() == 0 ? 0d : value.AsReal());
                return;
            case SqlValueKind.Text:
                hash.Add(2);
                var text = value.AsText();
                if (string.Equals(collation, "NOCASE", StringComparison.OrdinalIgnoreCase))
                {
                    var bytes = System.Text.Encoding.UTF8.GetBytes(text);
                    foreach (var octet in bytes)
                    {
                        var folded = FoldNoCaseAscii(octet);
                        hash.Add(folded);
                        if (folded == 0)
                        {
                            hash.Add(bytes.Length);
                            break;
                        }
                    }
                }
                else
                {
                    if (string.Equals(collation, "RTRIM", StringComparison.OrdinalIgnoreCase))
                        text = text.TrimEnd(' ');
                    hash.Add(text, StringComparer.Ordinal);
                }

                return;
            case SqlValueKind.Blob:
                hash.Add(3);
                foreach (var octet in value.AsBlob().Span)
                    hash.Add(octet);
                return;
            default:
                throw new InvalidOperationException($"Unknown SQL value kind {value.Kind}.");
        }
    }

    private static byte FoldNoCaseAscii(byte value) =>
        value is >= (byte)'A' and <= (byte)'Z'
            ? (byte)(value + 0x20)
            : value;

    private sealed class GroupKeyEqualityComparer(
        VdbeGroupComparer equality,
        VdbeGroupHasher hasher) : IEqualityComparer<SqlValue[]>
    {
        public bool Equals(SqlValue[]? left, SqlValue[]? right) =>
            left is not null
            && right is not null
            && equality(left, right);

        public int GetHashCode(SqlValue[] key) => hasher(key);
    }

    private sealed class CompiledAggregateContext
    {
        private bool _representativeInitialized;
        private SourceRow? _representative;

        public List<SourceRow> Rows { get; } = [];

        public SourceRow? GetRepresentative(Func<SourceRow?> factory)
        {
            if (!_representativeInitialized)
            {
                _representative = factory();
                _representativeInitialized = true;
            }

            return _representative;
        }
    }

    // Lowers a windowed SELECT over one base table to real bytecode, or declines so the tree-walking
    // evaluator keeps ownership and raises its own value or error. Two lowerings sit behind this router,
    // tried in order:
    //
    //  1. The streaming running-frame program (WindowProgramBuilder): the narrow shape whose window calls
    //     all share one ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW spec over aggregate functions of
    //     bare columns, which folds into the AggReset/AggStep/AggFinalize opcode family without buffering
    //     a partition. See TryBuildRunningWindowProgram for its exact grammar.
    //  2. The buffered-window program (BufferedWindowProgramBuilder): every other window shape whose
    //     inputs are computable from one scanned row. It buffers the scanned rows through the
    //     OpenWindowBuffer/WindowBufferInsert/WindowBufferCompute/WindowBufferData opcode family and
    //     defers every window semantic — partitioning, per-partition ordering, peer groups, ROWS/RANGE/
    //     GROUPS frames, EXCLUDE, FILTER, and the ranking/navigation/aggregate families — to the
    //     evaluator's own ComputeWindowFunctions through a VdbeWindowEvaluator. That is what makes
    //     sliding, forward-looking and peer-relative frames representable exactly.
    //
    // Both lowerings emit unconditional ResultRows, so LIMIT/OFFSET composes onto either through
    // LimitOffsetProgramBuilder.
    //
    // Deliberately kept on the evaluator (decline, never a fake success):
    //  - DISTINCT, GROUP BY, HAVING: the route owns only the window pipeline.
    //  - a plain aggregate mixed with a window call, or a window call in WHERE/GROUP BY/HAVING: the
    //    evaluator raises the exact diagnostic.
    //  - any source that is not one base table (joins, compounds, CTEs, views, derived tables, schema
    //    tables), and any base table the managed index planner would scan in index order, whose row
    //    order the compiled scan does not reproduce.
    //  - a WHERE the scan cannot evaluate per row, or any window argument / FILTER / PARTITION BY /
    //    window ORDER BY / projection / ORDER BY term that is not computable from one scanned row
    //    (subqueries, EXISTS, unbacked rowid references).
    //  - a non-integral LIMIT/OFFSET bound and LIMIT 0, whose evaluator diagnostics and
    //    validate-without-scanning timing the gate cannot reproduce.
    private bool TryCompileWindowSelect(
        SelectStatement select,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out CompiledSelect compiled,
        ScanTarget? targetOverride = null)
    {
        compiled = null!;

        // Only engage for a SELECT that actually projects a window call; every other shape is
        // owned by the scan/aggregate/sorted/join routes or the evaluator.
        if (!context.CompilationEnabled
            || context.CancellationToken.CanBeCanceled
            || !select.Projections.Any(projection => ContainsWindowFunction(projection.Expression)))
            return false;

        // Reshaping/dedup clauses stay on the evaluator so this route owns only the pure
        // buffer -> window -> order -> emit pipeline.
        if (select.Distinct
            || select.Having is not null
            || select.GroupBy.Count != 0
            || select.Projections.Count == 0)
        {
            return false;
        }

        // A window select that also carries a plain (non-window) aggregate or GROUP BY runs the
        // window pass over grouped rows (ExecuteGroupedWindowSelect); this route only knows how to
        // window over scanned rows, so decline. An aggregate nested inside a window call's own
        // subtree - sum(count(*)) OVER () - groups the statement just the same.
        if (select.Projections.Any(projection => ContainsAggregateAcrossWindows(projection.Expression))
            || select.OrderBy.Any(term => ContainsAggregateAcrossWindows(term.Expression)))
        {
            return false;
        }

        // A window call outside the projection/ORDER BY positions is a misuse the evaluator names.
        if (select.Where is not null && ContainsWindowFunction(select.Where))
            return false;

        // ExecuteSelect validates ORDER BY collations and then every window call before it touches a row.
        // Running the same validations here decides eligibility, but a validation failure declines rather
        // than throws: the evaluator owns every window diagnostic, so it raises the exact error at its
        // exact point and EXPLAIN QUERY PLAN keeps reporting the statement as evaluator-owned.
        IReadOnlyList<OrderByTerm> resolvedOrderBy;
        List<FunctionExpression> windowFunctions;
        try
        {
            resolvedOrderBy = ResolveOrderBy(select.OrderBy, select.Projections);
            ValidateOrderByCollations(resolvedOrderBy);
            windowFunctions = CollectSelectWindowFunctions(select);
            foreach (var function in windowFunctions)
            {
                foreach (var partition in function.Window!.PartitionBy)
                    ValidateCollation(GetCollation(partition));
                ValidateOrderByCollations(function.Window!.OrderBy);
                ValidateWindowFunction(function);
            }
        }
        catch (EmbeddedSqlException)
        {
            return false;
        }

        if (windowFunctions.Count == 0)
            return false;

        if (windowFunctions.Any(function =>
                !IsBuiltInAggregate(function)
                && TryGetAggregateFunction(function.Name, function.Arguments.Count, out _))
            || select.Projections.Any(projection =>
                IndexExpressionSemantics.ContainsFunction(
                    projection.Expression,
                    IsRegisteredScalarFunction))
            || select.Where is not null
                && IndexExpressionSemantics.ContainsFunction(
                    select.Where,
                    IsRegisteredScalarFunction)
            || resolvedOrderBy.Any(term =>
                IndexExpressionSemantics.ContainsFunction(
                    term.Expression,
                    IsRegisteredScalarFunction))
            || windowFunctions.Any(function =>
                function.Arguments.Any(argument =>
                    IndexExpressionSemantics.ContainsFunction(
                        argument,
                        IsRegisteredScalarFunction))
                || function.Filter is not null
                    && IndexExpressionSemantics.ContainsFunction(
                        function.Filter,
                        IsRegisteredScalarFunction)
                || function.Window!.PartitionBy.Any(expression =>
                    IndexExpressionSemantics.ContainsFunction(
                        expression,
                        IsRegisteredScalarFunction))
                || function.Window!.OrderBy.Any(term =>
                    IndexExpressionSemantics.ContainsFunction(
                        term.Expression,
                        IsRegisteredScalarFunction))
                || function.Window!.PartitionBy.Any(expression =>
                    ContainsEffectiveCustomCollation(expression, context))
                || function.Window!.OrderBy.Any(term =>
                    ContainsEffectiveCustomCollation(term.Expression, context)))
            || resolvedOrderBy.Any(term =>
                ContainsEffectiveCustomCollation(term.Expression, context)))
        {
            return false;
        }

        // A top-level ordering over the same partition keys can interleave a partition
        // when it applies a different collation. Keep that observable ordering on the
        // evaluator rather than relying on the buffered pass to reproduce it.
        if (windowFunctions.Any(function =>
                HasMismatchedWindowPartitionOrder(
                    function.Window!.PartitionBy,
                    resolvedOrderBy,
                    context)))
        {
            return false;
        }

        var target = targetOverride ?? ResolveScanTarget(select.Source, context);
        if (target is null || target.Columns.Length == 0)
            return false;

        // A managed index plan makes the evaluator scan in index order, which the compiled cursor (which
        // walks the table's rows) does not reproduce. Decline so a routed window pass can never observe a
        // different input order than the fallback would.
        if (TryPlanManagedIndexScan(select, context) is not null)
            return false;

        // Resolve the bounds only after the non-executing validations above. ExecuteSelect establishes the
        // same precedence, so a user callback in LIMIT/OFFSET cannot run before a missing collation or an
        // invalid window diagnostic.
        if (!TryResolveLimitOffset(select, parameters, context, outerRow, out var limit, out var offset))
            return false;
        if (limit == 0)
            return false;

        var baseSelect = select.Limit is null && select.Offset is null
            ? select
            : select with { Limit = null, Offset = null };

        if (!TryBuildRunningWindowProgram(baseSelect, target, parameters, context, outerRow, out var program)
            && !TryBuildBufferedWindowProgram(
                baseSelect,
                target,
                windowFunctions,
                resolvedOrderBy,
                parameters,
                context,
                outerRow,
                out program))
        {
            return false;
        }

        compiled = new CompiledSelect(
            LimitOffsetProgramBuilder.Apply(program, offset, limit),
            [new VdbeCursorSource(target.Rows)]);
        return true;
    }

    private bool HasMismatchedWindowPartitionOrder(
        IReadOnlyList<Expression> partitionBy,
        IReadOnlyList<OrderByTerm> orderBy,
        QueryContext context)
    {
        if (partitionBy.Count == 0 || orderBy.Count < partitionBy.Count)
            return false;

        for (var index = 0; index < partitionBy.Count; index++)
        {
            if (UnwrapCollation(partitionBy[index]) is not ColumnExpression partition
                || UnwrapCollation(orderBy[index].Expression) is not ColumnExpression top
                || !string.Equals(
                    partition.Name,
                    top.Name,
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            if (!CollationsEquivalent(
                    GetEffectiveCollation(partitionBy[index], context),
                    GetEffectiveCollation(orderBy[index].Expression, context)))
            {
                return true;
            }
        }

        return false;
    }

    // The streaming running-frame lowering. It reuses the evaluator's own accumulation
    // (BuildAccumulatorAggregate), partition equality (BuildGroupComparers), and ordering (CompareRows)
    // so a routed row is byte-identical to the fallback.
    //
    // Routed grammar (all conditions required):
    //   SELECT <proj> [,...] FROM <single base table> [WHERE <row predicate>]
    //   [ORDER BY <partition cols as prefix> , <window ORDER BY terms>]
    // where each <proj> is one of: '*', a bare backed column, a folded constant, or
    //   agg(<bare column>|*) OVER ([PARTITION BY <bare cols>] [ORDER BY <scan terms>]
    //                              ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
    // with agg in {count, sum, total, avg, min, max, group_concat/1, registered aggregates}, and
    // every window call sharing one identical OVER spec.
    //
    // Exactness of the emitted (partition, order) sort order requires the top-level ORDER BY to be
    // the partition columns (in any direction, as a bijective prefix) followed by the window ORDER BY
    // terms verbatim; absent an ORDER BY the window must be unpartitioned and unordered so the sorter
    // preserves scan order. Everything else declines to the buffered lowering.
    private bool TryBuildRunningWindowProgram(
        SelectStatement select,
        ScanTarget target,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out VdbeProgram program)
    {
        program = null!;

        // Classify every projection into a pass-through column, a running window call sharing
        // one spec, or a folded constant. Any other shape (computed expressions over window
        // results, qualified stars, scalar functions) declines to the buffered lowering.
        WindowSpecification? spec = null;
        var windows = new List<AggregateFunctionSpec>();
        var outputs = new List<WindowOutput>();
        var sawWindow = false;
        foreach (var projection in select.Projections)
        {
            switch (projection.Expression)
            {
                case StarExpression:
                    for (var index = 0; index < target.Columns.Length; index++)
                        outputs.Add(WindowOutput.ForColumn(index));
                    continue;
                case ColumnExpression column when target.ResolveColumnIndex(column.Name) is { } ordinal:
                    outputs.Add(WindowOutput.ForColumn(ordinal));
                    continue;
                case FunctionExpression function when function.Window is not null:
                    if (!TryClassifyRunningWindowCall(
                            function, target, parameters, context, outerRow, ref spec, windows, out var windowOutput))
                    {
                        return false;
                    }

                    outputs.Add(windowOutput);
                    sawWindow = true;
                    continue;
                default:
                    if (IsConstantScalarExpression(projection.Expression))
                    {
                        outputs.Add(WindowOutput.ForConstant(Evaluate(projection.Expression, parameters, null, context)));
                        continue;
                    }

                    return false;
            }
        }

        if (!sawWindow || spec is null)
            return false;

        ValidateOrderByCollations(spec.OrderBy);
        ValidateGroupByCollations(spec.PartitionBy);
        if (spec.PartitionBy.Any(expression =>
                ContainsEffectiveCustomCollation(expression, context))
            || spec.OrderBy.Any(term =>
                ContainsEffectiveCustomCollation(term.Expression, context)))
        {
            return false;
        }

        // PARTITION BY keys must be bare, backed columns so the builder can copy them into the
        // partition-key registers and the reused group-key equality can compare them.
        var partitionColumns = new List<int>();
        var partitionNames = new List<string>();
        foreach (var partitionExpression in spec.PartitionBy)
        {
            if (UnwrapCollation(partitionExpression) is not ColumnExpression column
                || target.ResolveColumnIndex(column.Name) is not { } ordinal)
            {
                return false;
            }

            partitionColumns.Add(ordinal);
            partitionNames.Add(column.Name);
        }

        // Window ORDER BY terms drive the running accumulation order, so they must be evaluable
        // against a single scanned row and must not read an unbacked rowid the materialized row
        // cannot supply. (IsScanPredicate already rejects nested window/aggregate terms.)
        foreach (var term in spec.OrderBy)
        {
            if (!IsScanPredicate(term.Expression) || ReferencesUnbackedRowid(term.Expression, target))
                return false;
        }

        var partitionCount = partitionColumns.Count;
        var windowOrderCount = spec.OrderBy.Count;
        if (partitionCount > 0
            && CollectSelectWindowFunctions(select).Any(function =>
                !IsBuiltInAggregate(function)
                && TryGetAggregateFunction(function.Name, function.Arguments.Count, out _)))
        {
            return false;
        }

        VdbeRowPredicate? predicate = null;
        if (select.Where is not null)
        {
            predicate = CompileRowPredicate(select.Where, target, parameters, context, outerRow);
            if (predicate is null)
                return false;
        }

        // The builder emits rows in its own (partition, order) sort order. That order is exact
        // only when the evaluator would emit the same order:
        //   * no ORDER BY  -> the evaluator emits scan order, which matches only the single
        //     unordered, unpartitioned running frame; the sorter preserves scan order.
        //   * ORDER BY      -> it must be [all partition columns as a bijective prefix] ++ [the
        //     window ORDER BY terms verbatim], so the sort is partition-contiguous with window
        //     order within each partition and equals the evaluator's output order term-for-term.
        VdbeRowComparer orderComparer;
        if (select.OrderBy.Count == 0)
        {
            if (partitionCount != 0 || windowOrderCount != 0)
                return false;

            orderComparer = static (_, _) => 0;
        }
        else
        {
            var resolvedOrderBy = ResolveOrderBy(select.OrderBy, select.Projections);
            ValidateOrderByCollations(resolvedOrderBy);
            if (resolvedOrderBy.Any(term =>
                    ContainsEffectiveCustomCollation(term.Expression, context)))
            {
                return false;
            }
            if (resolvedOrderBy.Count != partitionCount + windowOrderCount)
                return false;

            var partitionOrdinals = new HashSet<int>(partitionColumns);
            var seenOrdinals = new HashSet<int>();
            for (var index = 0; index < partitionCount; index++)
            {
                var topExpression = resolvedOrderBy[index].Expression;
                if (UnwrapCollation(topExpression) is not ColumnExpression column
                    || target.ResolveColumnIndex(column.Name) is not { } ordinal
                    || !partitionOrdinals.Contains(ordinal)
                    || !seenOrdinals.Add(ordinal))
                {
                    return false;
                }

                var partitionIndex = partitionColumns.IndexOf(ordinal);
                if (!CollationsEquivalent(
                        GetEffectiveCollation(topExpression, context),
                        GetEffectiveCollation(spec.PartitionBy[partitionIndex], context)))
                {
                    return false;
                }
            }

            for (var index = 0; index < windowOrderCount; index++)
            {
                var top = resolvedOrderBy[partitionCount + index];
                var windowTerm = spec.OrderBy[index];
                if (!top.Expression.Equals(windowTerm.Expression)
                    || top.Descending != windowTerm.Descending
                    || top.NullPlacement != windowTerm.NullPlacement)
                    return false;
            }

            foreach (var term in resolvedOrderBy)
            {
                if (!IsScanPredicate(term.Expression) || ReferencesUnbackedRowid(term.Expression, target))
                    return false;
            }

            orderComparer = (leftRow, rightRow) => CompareRows(
                CreateScanSourceRow(target, leftRow, context, outerRow),
                CreateScanSourceRow(target, rightRow, context, outerRow),
                resolvedOrderBy,
                parameters,
                context);
        }

        // Partition boundary detection reuses the evaluator's group-key equality so a routed
        // partition break matches the evaluator's GetGroupKey exactly. The builder requires a
        // partition comparer iff there are partition columns.
        VdbeGroupComparer? partitionComparer = null;
        if (partitionCount > 0)
        {
            var (_, groupComparer) = BuildGroupComparers(
                spec.PartitionBy, partitionNames, target, predicate, parameters, context, outerRow);
            partitionComparer = groupComparer;
        }

        program = WindowProgramBuilder.Build(
            target.TableName,
            target.Columns.Length,
            partitionColumns,
            windows,
            outputs,
            orderComparer,
            partitionComparer,
            predicate);
        return true;
    }

    // The general buffered-window lowering: every window shape whose inputs are computable from one
    // scanned row. Partitioning, window ordering, peer groups, frame resolution, EXCLUDE, FILTER and the
    // ranking/navigation/aggregate function families are all supplied to the emitted program as one
    // VdbeWindowEvaluator built from the evaluator's own ComputeWindowFunctions, so a routed row is
    // byte-identical to the fallback for every frame the evaluator supports. The projection and the
    // statement's ORDER BY are likewise lowered as delegates over the (row, window values) record, reusing
    // ReplaceWindowFunctions/Evaluate/CompareForOrdering, which is how computed keys and computed results
    // over window values stay exact.
    private bool TryBuildBufferedWindowProgram(
        SelectStatement select,
        ScanTarget target,
        IReadOnlyList<FunctionExpression> windowFunctions,
        IReadOnlyList<OrderByTerm> resolvedOrderBy,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out VdbeProgram program)
    {
        program = null!;

        // Stripping every window call to a placeholder value is exactly the substitution the routed
        // projection performs, so eligibility is decided against the shape that will actually be
        // evaluated rather than an approximation of it.
        var placeholders = new Dictionary<FunctionExpression, SqlValue>();
        foreach (var function in windowFunctions)
            placeholders[function] = SqlValue.Null;

        // Everything the window pass evaluates per row must be computable from that row alone.
        foreach (var function in windowFunctions)
        {
            foreach (var argument in function.Arguments)
            {
                if (!IsRoutableWindowExpression(argument, target, placeholders))
                    return false;
            }

            if (function.Filter is not null
                && !IsRoutableWindowExpression(function.Filter, target, placeholders))
            {
                return false;
            }

            var window = function.Window!;
            foreach (var partition in window.PartitionBy)
            {
                if (!IsRoutableWindowExpression(partition, target, placeholders))
                    return false;
            }

            foreach (var term in window.OrderBy)
            {
                if (!IsRoutableWindowExpression(term.Expression, target, placeholders))
                    return false;
            }
        }

        var outputs = new List<BufferedWindowOutput>();
        foreach (var projection in select.Projections)
        {
            switch (projection.Expression)
            {
                case StarExpression:
                    for (var index = 0; index < target.Columns.Length; index++)
                        outputs.Add(BufferedWindowOutput.ForColumn(index));
                    continue;
                case QualifiedStarExpression qualified
                    when string.Equals(qualified.Qualifier, target.Qualifier, StringComparison.OrdinalIgnoreCase):
                    for (var index = 0; index < target.Columns.Length; index++)
                        outputs.Add(BufferedWindowOutput.ForColumn(index));
                    continue;
                case QualifiedStarExpression:
                    // The evaluator raises "no such table: <qualifier>"; let it.
                    return false;
                case ColumnExpression column when target.ResolveColumnIndex(column.Name) is { } ordinal:
                    outputs.Add(BufferedWindowOutput.ForColumn(ordinal));
                    continue;
                case FunctionExpression function when function.Window is not null:
                    var windowOrdinal = IndexOfWindowFunction(windowFunctions, function);
                    if (windowOrdinal < 0)
                        return false;

                    outputs.Add(BufferedWindowOutput.ForWindow(windowOrdinal));
                    continue;
                default:
                    if (IsConstantScalarExpression(projection.Expression))
                    {
                        outputs.Add(BufferedWindowOutput.ForConstant(
                            Evaluate(projection.Expression, parameters, null, context)));
                        continue;
                    }

                    if (!IsRoutableWindowExpression(projection.Expression, target, placeholders))
                        return false;

                    outputs.Add(BufferedWindowOutput.ForComputed(BuildWindowProjectionFunction(
                        projection.Expression, target, windowFunctions, parameters, context, outerRow)));
                    continue;
            }
        }

        if (outputs.Count == 0)
            return false;

        VdbeRowPredicate? predicate = null;
        if (select.Where is not null)
        {
            predicate = CompileRowPredicate(select.Where, target, parameters, context, outerRow);
            if (predicate is null)
                return false;
        }

        VdbeRowComparer? orderComparer = null;
        if (resolvedOrderBy.Count > 0)
        {
            foreach (var term in resolvedOrderBy)
            {
                if (!IsRoutableWindowExpression(term.Expression, target, placeholders))
                    return false;
            }

            orderComparer = BuildWindowOrderComparer(
                resolvedOrderBy, target, windowFunctions, parameters, context, outerRow);
        }

        program = BufferedWindowProgramBuilder.Build(
            target.TableName,
            target.Columns.Length,
            windowFunctions.Count,
            outputs,
            BuildWindowEvaluator(target, windowFunctions, parameters, context, outerRow),
            orderComparer,
            predicate);
        return true;
    }

    // An expression is routable through the buffered window pass when, with its window calls replaced by
    // their computed values, what remains is evaluable against one scanned row and reads no rowid the
    // materialized row cannot supply.
    private bool IsRoutableWindowExpression(
        Expression expression,
        ScanTarget target,
        IReadOnlyDictionary<FunctionExpression, SqlValue> placeholders)
    {
        var stripped = ReplaceWindowFunctions(expression, placeholders);
        return IsScanPredicate(stripped) && !ReferencesUnbackedRowid(stripped, target);
    }

    private static int IndexOfWindowFunction(
        IReadOnlyList<FunctionExpression> windowFunctions,
        FunctionExpression function)
    {
        for (var index = 0; index < windowFunctions.Count; index++)
        {
            if (windowFunctions[index].Equals(function))
                return index;
        }

        return -1;
    }

    // The buffered program's single window pass: it rehydrates each buffered tuple into the SourceRow the
    // evaluator would have seen and hands the whole buffer to ComputeWindowFunctionValueRows, so routed
    // partitioning, framing, and per-function semantics are literally the evaluator's.
    private VdbeWindowEvaluator BuildWindowEvaluator(
        ScanTarget target,
        IReadOnlyList<FunctionExpression> windowFunctions,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        var functions = windowFunctions.ToArray();
        return bufferedRows =>
        {
            var rows = new List<SourceRow>(bufferedRows.Count);
            foreach (var row in bufferedRows)
                rows.Add(CreateScanSourceRow(target, row, context, outerRow));

            return ComputeWindowFunctionValueRows(functions, rows, parameters, context);
        };
    }

    // Lowers one computed projection over window results: the delegate receives the whole
    // (scanned columns, window values) record, rebuilds the evaluator's per-row window substitution from
    // its tail, and evaluates the substituted expression against the scanned row.
    private VdbeScalarFunction BuildWindowProjectionFunction(
        Expression expression,
        ScanTarget target,
        IReadOnlyList<FunctionExpression> windowFunctions,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        var functions = windowFunctions.ToArray();
        var width = target.Columns.Length;
        return new VdbeScalarFunction
        {
            Name = "window projection",
            Invoke = record => Evaluate(
                ReplaceWindowFunctions(expression, BuildWindowSubstitution(functions, record, width)),
                parameters,
                CreateScanSourceRow(target, record[..width], context, outerRow),
                context),
        };
    }

    // Lowers the statement's ORDER BY over the (row, window values) record. It mirrors
    // ExecuteWindowSelect's comparison term for term — substitute, evaluate against the source row, and
    // compare with the term's direction, NULL placement, and collation — so a routed sort is the
    // evaluator's sort. The sorter is stable, matching the evaluator's StableSortIndices tie-break on
    // scan position.
    private VdbeRowComparer BuildWindowOrderComparer(
        IReadOnlyList<OrderByTerm> resolvedOrderBy,
        ScanTarget target,
        IReadOnlyList<FunctionExpression> windowFunctions,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        var functions = windowFunctions.ToArray();
        var width = target.Columns.Length;
        return (left, right) =>
        {
            var leftRow = CreateScanSourceRow(target, left[..width], context, outerRow);
            var rightRow = CreateScanSourceRow(target, right[..width], context, outerRow);
            var leftSubstitution = BuildWindowSubstitution(functions, left, width);
            var rightSubstitution = BuildWindowSubstitution(functions, right, width);
            foreach (var term in resolvedOrderBy)
            {
                var comparison = CompareForOrdering(
                    Evaluate(
                        ReplaceWindowFunctions(term.Expression, leftSubstitution),
                        parameters,
                        leftRow,
                        context),
                    Evaluate(
                        ReplaceWindowFunctions(term.Expression, rightSubstitution),
                        parameters,
                        rightRow,
                        context),
                    term,
                    GetCollation(term.Expression));
                if (comparison != 0)
                    return comparison;
            }

            return 0;
        };
    }

    private static Dictionary<FunctionExpression, SqlValue> BuildWindowSubstitution(
        FunctionExpression[] windowFunctions,
        SqlValue[] record,
        int columnCount)
    {
        var substitution = new Dictionary<FunctionExpression, SqlValue>(windowFunctions.Length);
        for (var index = 0; index < windowFunctions.Length; index++)
            substitution[windowFunctions[index]] = record[columnCount + index];

        return substitution;
    }

    // Recognizes a top-level running-frame window call over bare, backed columns, appends its
    // VdbeAggregate to <paramref name="windows"/>, and yields the output that projects the
    // finalized per-row value. Declines (returns false) for DISTINCT/FILTER modifiers, any frame
    // other than the running frame, non-aggregate window functions (row_number/rank/percentile),
    // arguments that are not bare columns, or a spec that differs from an earlier window call, so
    // those shapes fall back to the evaluator, which produces the value or its exact error.
    private bool TryClassifyRunningWindowCall(
        FunctionExpression function,
        ScanTarget target,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        ref WindowSpecification? spec,
        List<AggregateFunctionSpec> windows,
        out WindowOutput output)
    {
        output = default;

        // Frame/window modifiers the running-frame accumulator cannot honor. FILTER would need to
        // evaluate a predicate over columns the accumulator does not buffer; DISTINCT dedup is not
        // modeled by the running AggStep.
        if (function.Distinct || function.Filter is not null)
            return false;

        var window = function.Window!;
        if (!IsRunningWindowFrame(window.Frame))
            return false;

        // The bytecode shape only models aggregate accumulation. Dedicated ranking,
        // navigation, and value functions decline to the evaluator; managed percentile
        // aggregates also decline because they are not available as window functions.
        if (!IsBuiltInAggregate(function)
            && !TryGetAggregateFunction(function.Name, function.Arguments.Count, out _))
        {
            return false;
        }

        // Every window call must share one identical OVER spec so a single sorter pass and one
        // partition/order layout serve them all.
        if (spec is null)
            spec = window;
        else if (!WindowSpecsEqual(spec, window))
            return false;

        // Arguments must be bare, backed columns (or the nullary count(*)); group_concat(col, sep)
        // and any computed argument decline because the accumulator only buffers column tuples.
        var argumentColumns = new List<int>(function.Arguments.Count);
        var argumentNames = new string[function.Arguments.Count];
        for (var index = 0; index < function.Arguments.Count; index++)
        {
            if (function.Arguments[index] is not ColumnExpression column
                || target.ResolveColumnIndex(column.Name) is not { } ordinal)
            {
                return false;
            }

            argumentColumns.Add(ordinal);
            argumentNames[index] = column.Name;
        }

        var windowIndex = windows.Count;
        windows.Add(new AggregateFunctionSpec(
            BuildAccumulatorAggregate(function, argumentNames, parameters, context, outerRow),
            argumentColumns));
        output = WindowOutput.ForWindow(windowIndex);
        return true;
    }

    // The one frame WindowProgramBuilder models: ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW.
    // The parser also produces this shape for bare "ROWS UNBOUNDED PRECEDING". A null frame (the
    // default RANGE frame) and every bounded/forward-looking ROWS frame decline.
    private static bool IsRunningWindowFrame(WindowFrame? frame)
        => frame is not null
            && frame.Mode == Ahtola.Core.Parsing.WindowFrameMode.Rows
            && frame.Start.Kind == FrameBoundKind.UnboundedPreceding
            && frame.End.Kind == FrameBoundKind.CurrentRow
            && frame.Exclusion == FrameExclusion.NoOthers;

    // Structural equality of two window specs: PARTITION BY expressions and ORDER BY terms compared
    // element-wise (record equality on the IReadOnlyList fields is reference equality, so the lists
    // must be walked), and the frame by value.
    private static bool WindowSpecsEqual(WindowSpecification left, WindowSpecification right)
    {
        if (left.PartitionBy.Count != right.PartitionBy.Count || left.OrderBy.Count != right.OrderBy.Count)
            return false;

        for (var index = 0; index < left.PartitionBy.Count; index++)
        {
            if (!left.PartitionBy[index].Equals(right.PartitionBy[index]))
                return false;
        }

        for (var index = 0; index < left.OrderBy.Count; index++)
        {
            if (!left.OrderBy[index].Equals(right.OrderBy[index]))
                return false;
        }

        return Equals(left.Frame, right.Frame);
    }

    // Builds a VdbeAggregate whose accumulation replays the evaluator's own aggregate
    // semantics: it buffers each scanned argument tuple as a synthetic single-row source
    // keyed by the argument column names, then finalizes by handing those rows to
    // EvaluateAggregateFunction. This reuses the evaluator exactly (COUNT ignoring NULLs,
    // SUM's integer/real promotion, MIN/MAX typing, GROUP_CONCAT ordering, and every
    // empty-input identity), so a routed aggregate is byte-identical to the fallback.
    private VdbeAggregate BuildAccumulatorAggregate(
        FunctionExpression function,
        string[] argumentNames,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        return new VdbeAggregate
        {
            Name = function.Name.ToLowerInvariant(),
            CreateContext = static () => new List<SqlValue[]>(),
            Accumulate = static (contextObject, arguments) =>
            {
                ((List<SqlValue[]>)contextObject!).Add(arguments);
                return contextObject;
            },
            Finalize = contextObject =>
            {
                var tuples = (List<SqlValue[]>)contextObject!;
                var rows = new List<SourceRow>(tuples.Count);
                foreach (var tuple in tuples)
                    rows.Add(new SourceRow(argumentNames, tuple, Parent: outerRow));

                return EvaluateAggregateFunction(function, rows, parameters, context);
            },
        };
    }

    // Builds the two delegates a grouped aggregate program needs: an order comparer that
    // makes each group's rows contiguous and sequences groups by first appearance (so the
    // stable sorter reproduces first-seen group order with scan-order rows inside each group),
    // and an equality comparer that decides group membership. Both evaluate the key tuple and
    // apply its effective collations, so NULL/numeric equivalence and collated text grouping
    // match the evaluator. The first-seen list is built lazily (so EXPLAIN does no data work)
    // and rebuilt on a miss (so append-only reset/replay remains correct).
    private (VdbeRowComparer OrderComparer, VdbeGroupComparer GroupComparer) BuildGroupComparers(
        IReadOnlyList<Expression> groupBy,
        IReadOnlyList<string> groupKeyNames,
        ScanTarget target,
        VdbeRowPredicate? predicate,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        var columns = target.Columns;
        var keyNames = groupKeyNames.ToArray();
        var collations = groupBy
            .Select(expression => GetEffectiveCollation(expression, context))
            .ToArray();
        VdbeGroupComparer keyEquality = (left, right) =>
            GroupKeysEqual(left, right, collations);
        var keyHasher = BuildGroupHasher(collations);

        SqlValue[] KeyOfRow(SqlValue[] row) =>
            EvaluateGroupKey(
                groupBy,
                parameters,
                CreateScanSourceRow(target, row, context, outerRow),
                context);
        SqlValue[] KeyOfSlice(SqlValue[] slice) =>
            EvaluateGroupKey(
                groupBy,
                parameters,
                new SourceRow(keyNames, slice, Parent: outerRow),
                context);

        List<SqlValue[]>? firstSeen = null;
        Dictionary<SqlValue[], int>? firstSeenIndex = null;
        int FindKey(IReadOnlyList<SqlValue[]> keys, SqlValue[] key)
        {
            for (var index = 0; index < keys.Count; index++)
            {
                if (GroupKeysEqual(keys[index], key, collations))
                    return index;
            }

            return -1;
        }

        void BuildFirstSeen()
        {
            var keys = new List<SqlValue[]>();
            var index = keyHasher is null
                ? null
                : new Dictionary<SqlValue[], int>(
                    new GroupKeyEqualityComparer(keyEquality, keyHasher));
            foreach (var row in target.Rows)
            {
                if (predicate is not null && !predicate(row))
                    continue;

                var key = KeyOfRow(row);
                var exists = index is not null
                    ? index.ContainsKey(key)
                    : FindKey(keys, key) >= 0;
                if (!exists)
                {
                    index?.Add(key, keys.Count);
                    keys.Add(key);
                }
            }

            firstSeen = keys;
            firstSeenIndex = index;
        }

        VdbeRowComparer orderComparer = (left, right) =>
        {
            var leftKey = KeyOfRow(left);
            var rightKey = KeyOfRow(right);
            if (keyEquality(leftKey, rightKey))
                return 0;

            if (firstSeen is null)
                BuildFirstSeen();

            var keys = firstSeen!;
            var leftIndex = firstSeenIndex is not null
                && firstSeenIndex.TryGetValue(leftKey, out var indexedLeft)
                    ? indexedLeft
                    : FindKey(keys, leftKey);
            var rightIndex = firstSeenIndex is not null
                && firstSeenIndex.TryGetValue(rightKey, out var indexedRight)
                    ? indexedRight
                    : FindKey(keys, rightKey);
            if (leftIndex < 0 || rightIndex < 0)
            {
                BuildFirstSeen();
                keys = firstSeen!;
                leftIndex = firstSeenIndex is not null
                    && firstSeenIndex.TryGetValue(leftKey, out indexedLeft)
                        ? indexedLeft
                        : FindKey(keys, leftKey);
                rightIndex = firstSeenIndex is not null
                    && firstSeenIndex.TryGetValue(rightKey, out indexedRight)
                        ? indexedRight
                        : FindKey(keys, rightKey);
            }

            if (leftIndex < 0 || rightIndex < 0)
                throw new InvalidOperationException("Window partition key is absent from its source rows.");
            return leftIndex.CompareTo(rightIndex);
        };

        VdbeGroupComparer groupComparer = (left, right) =>
            keyEquality(KeyOfSlice(left), KeyOfSlice(right));

        return (orderComparer, groupComparer);
    }

    // Resolves a table source to a single compilable base-table scan target, or
    // null when the source is anything else (schema table, CTE, view, join,
    // derived table, series, or a missing table) so the evaluator keeps ownership.
    private static ScanTarget? ResolveScanTarget(TableSource? source, QueryContext context)
    {
        if (source is not NamedTableSource named)
            return null;
        if (named.IndexDirective is IndexedByDirective)
            return null;
        if (IsSchemaTable(named.Name)
            || context.CommonTableExpressions.ContainsKey(named.Name)
            || TryGetView(context, named.Name, out _))
        {
            return null;
        }

        if (!context.Tables.TryGetValue(named.Name, out var table))
            return null;

        var qualifier = named.Alias ?? named.Name;
        var columns = table.Columns;
        var qualifiedColumns = BuildQualifiedColumns(qualifier, columns);
        return new ScanTarget(
            named.Name,
            qualifier,
            columns,
            table.Rows,
            name => ResolveScanColumnIndex(name, columns, qualifiedColumns),
            table.HasRowid ? table.RowIds : null,
            ColumnDefinitions: table.ColumnDefinitions,
            QualifiedColumnDefinitions: BuildQualifiedColumnDefinitions(
                qualifier,
                table.ColumnDefinitions));
    }

    private static int? ResolveScanColumnIndex(
        string name,
        string[] columns,
        IReadOnlyDictionary<string, int> qualifiedColumns)
    {
        if (qualifiedColumns.TryGetValue(name, out var qualifiedIndex))
            return qualifiedIndex;

        for (var index = 0; index < columns.Length; index++)
        {
            if (string.Equals(columns[index], name, StringComparison.OrdinalIgnoreCase))
                return index;
        }

        return null;
    }

    // Builds a per-row predicate for a compilable WHERE clause, delegating value
    // semantics to the evaluator so the compiled filter matches it exactly. Returns
    // null for predicates that need more than the current row (subqueries, EXISTS,
    // or aggregates), keeping them on the evaluator.
    private VdbeRowPredicate? CompileRowPredicate(
        Expression where,
        ScanTarget target,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        if (!IsScanPredicate(where))
            return null;

        // The compiled scan only materializes declared columns, so a WHERE that reads the
        // rowid pseudo-column (and no real column shadows it) must run on the evaluator,
        // which resolves rowids from the scanned row.
        if (ReferencesUnbackedRowid(where, target))
            return null;

        return row => IsTrue(Evaluate(
            where,
            parameters,
            CreateScanSourceRow(target, row, context, outerRow),
            context));
    }

    // A rowid-aware scan keeps the evaluator authoritative for SQL comparison semantics, but only claims a
    // single hidden-rowid comparison against a literal or bound parameter. More complex rowid expressions
    // remain evaluator-backed rather than risking a different name-resolution or error-timing contract.
    private VdbeRowIdPredicate? CompileSimpleRowIdPredicate(
        Expression where,
        ScanTarget target,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        if (!target.HasRowId || !IsSimpleRowIdComparison(where, target))
            return null;

        return (row, rowId) => IsTrue(Evaluate(
            where,
            parameters,
            CreateScanSourceRow(target, row, context, outerRow, rowId),
            context));
    }

    /// <summary>
    /// Extracts the trailing rowid that <see cref="Compilation.SortedScanProgramBuilder"/> appends
    /// to the sorter record when <c>carryRowId</c> is set, so <see cref="CompareRows"/> can break
    /// ORDER BY ties by rowid ascending. Returns null when the slot is absent (WITHOUT-ROWID
    /// tables, or the builder did not carry a rowid) so tie order is left unchanged.
    /// </summary>
    private static long? ExtractSortedScanRowId(SqlValue[] row, int rowIdSlot)
    {
        if (rowIdSlot < 0 || rowIdSlot >= row.Length)
            return null;

        var value = row[rowIdSlot];
        return value.Kind == SqlValueKind.Integer ? value.AsInteger() : null;
    }

    private static SourceRow CreateScanSourceRow(
        ScanTarget target,
        SqlValue[] row,
        QueryContext context,
        SourceRow? outerRow,
        long? rowId = null)
    {
        var qualifiedColumns = BuildQualifiedColumns(target.Qualifier, target.Columns);
        if (target.ColumnDefinitions is not null)
        {
            return new SourceRow(
                target.Columns,
                row,
                qualifiedColumns,
                outerRow,
                RowId: rowId,
                RowIdQualifier: rowId is null ? null : target.Qualifier,
                ColumnDefinitions: target.ColumnDefinitions,
                QualifiedColumnDefinitions: target.QualifiedColumnDefinitions);
        }

        if (!context.Tables.TryGetValue(target.TableName, out var table))
        {
            return new SourceRow(
                target.Columns,
                row,
                qualifiedColumns,
                outerRow,
                RowId: rowId,
                RowIdQualifier: rowId is null ? null : target.Qualifier);
        }

        return new SourceRow(
            target.Columns,
            row,
            qualifiedColumns,
            outerRow,
            RowId: rowId,
            RowIdQualifier: rowId is null ? null : target.Qualifier,
            ColumnDefinitions: table.ColumnDefinitions,
            QualifiedColumnDefinitions: BuildQualifiedColumnDefinitions(
                target.Qualifier,
                table.ColumnDefinitions));
    }

    private static bool IsSimpleRowIdComparison(Expression expression, ScanTarget target)
    {
        if (expression is not BinaryExpression binary || !IsComparisonOperator(binary.Operator))
            return false;

        return (IsTargetRowIdReference(binary.Left, target) && IsLiteralOrParameter(binary.Right))
            || (IsTargetRowIdReference(binary.Right, target) && IsLiteralOrParameter(binary.Left));
    }

    private static bool IsTargetRowIdReference(Expression expression, ScanTarget target)
    {
        if (expression is not ColumnExpression column
            || !target.HasRowId
            || target.ResolveColumnIndex(column.Name) is not null)
        {
            return false;
        }

        var separator = column.Name.IndexOf('.');
        var bareName = separator < 0 ? column.Name : column.Name[(separator + 1)..];
        return EmbeddedTable.IsRowidAliasName(bareName)
            && (separator < 0
                || string.Equals(
                    column.Name[..separator],
                    target.Qualifier,
                    StringComparison.OrdinalIgnoreCase));
    }

    private static bool IsLiteralOrParameter(Expression expression)
        => expression is LiteralExpression or ParameterExpression;

    private static bool IsComparisonOperator(BinaryOperator op)
        => op is BinaryOperator.Is
            or BinaryOperator.IsNot
            or BinaryOperator.Equal
            or BinaryOperator.NotEqual
            or BinaryOperator.LessThan
            or BinaryOperator.LessThanOrEqual
            or BinaryOperator.GreaterThan
            or BinaryOperator.GreaterThanOrEqual;

    // Detects a reference to rowid/_rowid_/oid that the scan target does not back with a
    // declared column, so the predicate cannot be compiled against materialized columns.
    private static bool ReferencesUnbackedRowid(Expression expression, ScanTarget target)
    {
        switch (expression)
        {
            case ColumnExpression column:
                var separator = column.Name.IndexOf('.');
                var bare = separator < 0 ? column.Name : column.Name[(separator + 1)..];
                return EmbeddedTable.IsRowidAliasName(bare) && target.ResolveColumnIndex(column.Name) is null;
            case UnaryExpression unary:
                return ReferencesUnbackedRowid(unary.Operand, target);
            case RowValueExpression rowValue:
                return rowValue.Values.Any(value => ReferencesUnbackedRowid(value, target));
            case BinaryExpression binary:
                return ReferencesUnbackedRowid(binary.Left, target)
                    || ReferencesUnbackedRowid(binary.Right, target);
            case CollationExpression collation:
                return ReferencesUnbackedRowid(collation.Expression, target);
            case CastExpression cast:
                return ReferencesUnbackedRowid(cast.Expression, target);
            case FunctionExpression function:
                return function.Arguments.Any(argument => ReferencesUnbackedRowid(argument, target));
            case CaseExpression @case:
                return (@case.Operand is not null && ReferencesUnbackedRowid(@case.Operand, target))
                    || @case.Clauses.Any(clause =>
                        ReferencesUnbackedRowid(clause.When, target) || ReferencesUnbackedRowid(clause.Then, target))
                    || (@case.Else is not null && ReferencesUnbackedRowid(@case.Else, target));
            case LikeExpression like:
                return ReferencesUnbackedRowid(like.Value, target)
                    || ReferencesUnbackedRowid(like.Pattern, target)
                    || (like.Escape is not null && ReferencesUnbackedRowid(like.Escape, target));
            case GlobExpression glob:
                return ReferencesUnbackedRowid(glob.Value, target)
                    || ReferencesUnbackedRowid(glob.Pattern, target);
            case BetweenExpression between:
                return ReferencesUnbackedRowid(between.Value, target)
                    || ReferencesUnbackedRowid(between.Lower, target)
                    || ReferencesUnbackedRowid(between.Upper, target);
            case InExpression @in:
                return ReferencesUnbackedRowid(@in.Value, target)
                    || @in.Values.Any(value => ReferencesUnbackedRowid(value, target));
            default:
                return false;
        }
    }

    // A WHERE clause is compilable when it can be evaluated against a single scanned
    // row: it must not embed subqueries, EXISTS, or aggregates, which the row-at-a-
    // time scan cannot satisfy on its own.
    private bool IsScanPredicate(Expression expression)
    {
        switch (expression)
        {
            case ScalarSubqueryExpression or ExistsExpression or InSubqueryExpression:
                return false;
            case LiteralExpression or ParameterExpression or ColumnExpression:
                return true;
            case RowValueExpression rowValue:
                return rowValue.Values.All(IsScanPredicate);
            case StarExpression or QualifiedStarExpression:
                return false;
            case FunctionExpression function:
                return function.Window is null
                    && !function.CountStar
                    && function.Filter is null
                    && !ContainsAggregate(function)
                    && function.Arguments.All(IsScanPredicate);
            case UnaryExpression unary:
                return IsScanPredicate(unary.Operand);
            case BinaryExpression binary:
                return IsScanPredicate(binary.Left) && IsScanPredicate(binary.Right);
            case CollationExpression collation:
                return IsScanPredicate(collation.Expression);
            case CastExpression cast:
                return IsScanPredicate(cast.Expression);
            case CaseExpression @case:
                return (@case.Operand is null || IsScanPredicate(@case.Operand))
                    && @case.Clauses.All(clause =>
                        IsScanPredicate(clause.When) && IsScanPredicate(clause.Then))
                    && (@case.Else is null || IsScanPredicate(@case.Else));
            case LikeExpression like:
                return IsScanPredicate(like.Value)
                    && IsScanPredicate(like.Pattern)
                    && (like.Escape is null || IsScanPredicate(like.Escape));
            case GlobExpression glob:
                return IsScanPredicate(glob.Value) && IsScanPredicate(glob.Pattern);
            case BetweenExpression between:
                return IsScanPredicate(between.Value)
                    && IsScanPredicate(between.Lower)
                    && IsScanPredicate(between.Upper);
            case InExpression @in:
                return IsScanPredicate(@in.Value) && @in.Values.All(IsScanPredicate);
            default:
                return false;
        }
    }

    private static ExecutionResult RunCompiledProgram(CompiledSelect compiled, string[] columns)
        => RunCompiledProgram(compiled, columns, parameterBinding: null);

    // Runs a lowered read program, optionally supplying the late-bound parameter binding its
    // LoadParameter opcodes read. A null binding matches the constant-only routes, whose programs
    // declare no parameter slots; a routed parameterized VALUES supplies a binding sized to the
    // program's ParameterSlotCount.
    private static ExecutionResult RunCompiledProgram(
        CompiledSelect compiled,
        string[] columns,
        VdbeParameterBinding? parameterBinding,
        CancellationToken cancellationToken = default)
    {
        using var runtime = new ResumableStatement(
            compiled.Program,
            compiled.CursorSources,
            parameterBinding: parameterBinding);
        var rows = new List<SqlValue[]>();
        while (true)
        {
            switch (runtime.StepResumable(cancellationToken))
            {
                case ResumableStatementStepResult.Row:
                    rows.Add([.. runtime.CurrentRow!]);
                    break;
                case ResumableStatementStepResult.Done:
                    return new ExecutionResult(columns, rows, 0);
                default:
                    throw new EmbeddedSqlException("Compiled program yielded during evaluation.");
            }
        }
    }

    // Executes a lowered INSERT/UPDATE/DELETE program, buffering any RETURNING rows and
    // surfacing the rows-affected count and last-insert rowid the write opcodes tracked.
    private static ExecutionResult RunCompiledDml(
        CompiledDml compiled,
        string[] columns,
        bool hasReturning,
        SqlValue[] parameters)
    {
        using var runtime = new ResumableStatement(
            compiled.Program,
            compiled.CursorSources,
            compiled.RuntimeWriteTargets,
            BuildValuesBinding(compiled.ParameterIndices ?? [], parameters));
        var rows = new List<SqlValue[]>();
        while (true)
        {
            switch (runtime.StepResumable())
            {
                case ResumableStatementStepResult.Row:
                    rows.Add([.. runtime.CurrentRow!]);
                    break;
                case ResumableStatementStepResult.Done:
                    var rowsAffected = runtime.RowsAffected;
                    return new ExecutionResult(
                        hasReturning ? columns : [],
                        hasReturning ? rows : [],
                        rowsAffected,
                        rowsAffected > 0)
                    {
                        LastInsertRowId = runtime.LastInsertRowId,
                    };
                default:
                    throw new EmbeddedSqlException("Compiled program yielded during evaluation.");
            }
        }
    }

    // Attempts to lower an INSERT into a write program. Returns false (falling back to the
    // evaluator) for schema tables, missing tables, or RETURNING clauses outside the
    // lowerable subset. Genuine statement errors (bad columns) still surface via the
    // shared PrepareInsert/BuildInsertRow helpers, matching the evaluator exactly.
    private bool TryCompileInsert(
        InsertStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        out CompiledDml compiled,
        out string[] columns,
        out bool hasReturning)
    {
        compiled = null!;
        columns = [];
        hasReturning = false;

        if (statement.ConflictAlgorithm is not null
            || statement.Source is not null
            || context.CommonTableExpressions.Count != 0
            || IsSchemaTable(statement.TableName)
            || !context.Tables.TryGetValue(statement.TableName, out var table))
        {
            return false;
        }
        if (table.IsAutoIncrement && statement.Rows.Count > 1)
            return false;

        if (!TryCompileReturningClause(
                statement.Returning,
                table,
                statement.TableName,
                parameters,
                context,
                out var returningProgram,
                out columns,
                out hasReturning))
            return false;

        var plan = PrepareInsert(statement, table, context);
        var rowsToInsert = new List<SqlValue[]>(statement.Rows.Count);
        var insertedRowIds = new List<long>(statement.Rows.Count);
        var returningRows = hasReturning ? new List<SqlValue[]>(statement.Rows.Count) : null;
        var returningRowIds = hasReturning ? new List<long>(statement.Rows.Count) : null;
        var writeTarget = new VdbeWriteTarget
        {
            TableName = statement.TableName,
            RowCount = statement.Rows.Count,
            MutateRow = index =>
            {
                var (row, rowid) = BuildInsertRow(statement, table, plan, statement.Rows[index], parameters, context);
                rowsToInsert.Add(row);
                insertedRowIds.Add(rowid);
                returningRows?.Add(row);
                returningRowIds?.Add(rowid);
                return new VdbeRowMutation(row, rowid);
            },
            Commit = () =>
            {
                CommitInserts(context, statement.TableName, table, rowsToInsert, insertedRowIds);
                return table.HasRowid && insertedRowIds.Count > 0
                    ? insertedRowIds[^1]
                    : (long?)null;
            },
        };

        compiled = hasReturning
            ? DmlStatementCompiler.CompileWithFilter(
                DmlKind.Insert,
                statement.TableName,
                table.Columns.Length,
                filter: null,
                returningProgram!,
                writeTarget,
                new VdbeCursorSource(
                    returningRows!,
                    table.HasRowid ? returningRowIds : null))
            : DmlStatementCompiler.Compile(
                DmlKind.Insert,
                statement.TableName,
                table.Columns.Length,
                predicate: null,
                returning: Array.Empty<DmlReturningExpression>(),
                writeTarget);
        return true;
    }

    private bool TryCompileUpdate(
        UpdateStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        out CompiledDml compiled,
        out string[] columns,
        out bool hasReturning)
    {
        compiled = null!;
        columns = [];
        hasReturning = false;

        if (statement.Limit is not null
            || statement.Offset is not null
            || statement.EffectiveOrderBy.Count != 0
            || statement.Alias is not null
            || statement.From is not null
            || statement.ConflictAlgorithm is not null
            || context.CommonTableExpressions.Count != 0
            || IsSchemaTable(statement.TableName)
            || !context.Tables.TryGetValue(statement.TableName, out var table))
        {
            return false;
        }

        DmlRowFilter? filter = null;
        if (statement.Where is not null)
        {
            filter = CompileDmlRowPredicate(statement.Where, table, statement.TableName, parameters, context);
            if (filter is null)
                return false;
        }

        if (!TryCompileReturningClause(
                statement.Returning,
                table,
                statement.TableName,
                parameters,
                context,
                out var returningProgram,
                out columns,
                out hasReturning))
            return false;

        var plan = PrepareUpdate(statement, table, context);
        var rowCount = table.Rows.Count;
        var newRows = new List<SqlValue[]>(rowCount);
        var newRowIds = new List<long>(rowCount);
        var updatedPositions = new List<int>();
        var returningRows = hasReturning ? new List<SqlValue[]>(rowCount) : null;
        var returningRowIds = hasReturning ? new List<long>(rowCount) : null;
        for (var index = 0; index < rowCount; index++)
        {
            newRows.Add(table.Rows[index]);
            newRowIds.Add(index < table.RowIds.Count ? table.RowIds[index] : index + 1);
        }

        var writeTarget = new VdbeWriteTarget
        {
            TableName = statement.TableName,
            RowCount = rowCount,
            GetRow = index => table.Rows[index],
            GetRowId = index => index < table.RowIds.Count ? table.RowIds[index] : index + 1,
            MutateRow = index =>
            {
                var original = table.Rows[index];
                var rowid = index < table.RowIds.Count ? table.RowIds[index] : index + 1;
                var (updated, newRowid) = BuildUpdatedRow(statement, table, plan, original, rowid, parameters, context);
                newRows[index] = updated;
                newRowIds[index] = newRowid;
                updatedPositions.Add(index);
                returningRows?.Add(updated);
                returningRowIds?.Add(newRowid);
                return new VdbeRowMutation(updated, newRowid);
            },
            Commit = () =>
            {
                CommitUpdates(
                    context,
                    statement.TableName,
                    table,
                    table.Rows,
                    newRows,
                    newRowIds,
                    plan,
                    updatedPositions);
                return (long?)null;
            },
        };

        compiled = hasReturning
            ? DmlStatementCompiler.CompileWithFilter(
                DmlKind.Update,
                statement.TableName,
                table.Columns.Length,
                filter,
                returningProgram!,
                writeTarget,
                new VdbeCursorSource(
                    returningRows!,
                    table.HasRowid ? returningRowIds : null))
            : DmlStatementCompiler.CompileWithFilter(
                DmlKind.Update,
                statement.TableName,
                table.Columns.Length,
                filter,
                Array.Empty<DmlReturningExpression>(),
                writeTarget);
        return true;
    }

    private bool TryCompileDelete(
        DeleteStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        out CompiledDml compiled,
        out string[] columns,
        out bool hasReturning)
    {
        compiled = null!;
        columns = [];
        hasReturning = false;

        if (statement.Limit is not null
            || statement.Offset is not null
            || statement.EffectiveOrderBy.Count != 0
            || statement.Alias is not null
            || context.CommonTableExpressions.Count != 0
            || IsSchemaTable(statement.TableName)
            || !context.Tables.TryGetValue(statement.TableName, out var table))
        {
            return false;
        }

        DmlRowFilter? filter = null;
        if (statement.Where is not null)
        {
            filter = CompileDmlRowPredicate(statement.Where, table, statement.TableName, parameters, context);
            if (filter is null)
                return false;
        }

        if (!TryCompileReturningClause(
                statement.Returning,
                table,
                statement.TableName,
                parameters,
                context,
                out var returningProgram,
                out columns,
                out hasReturning))
            return false;

        var rowCount = table.Rows.Count;
        var deleted = new bool[rowCount];
        var returningRows = hasReturning ? new List<SqlValue[]>(rowCount) : null;
        var returningRowIds = hasReturning ? new List<long>(rowCount) : null;
        var writeTarget = new VdbeWriteTarget
        {
            TableName = statement.TableName,
            RowCount = rowCount,
            GetRow = index => table.Rows[index],
            GetRowId = index => index < table.RowIds.Count ? table.RowIds[index] : index + 1,
            DeleteRow = index =>
            {
                deleted[index] = true;
                returningRows?.Add(table.Rows[index]);
                returningRowIds?.Add(index < table.RowIds.Count ? table.RowIds[index] : index + 1);
            },
            Commit = () =>
            {
                var keptRows = new List<SqlValue[]>(rowCount);
                var keptRowIds = new List<long>(rowCount);
                var deletedRowIds = new List<long>();
                for (var index = 0; index < table.Rows.Count; index++)
                {
                    var rowId = index < table.RowIds.Count ? table.RowIds[index] : index + 1;
                    if (index < deleted.Length && deleted[index])
                    {
                        deletedRowIds.Add(rowId);
                        continue;
                    }
                    keptRows.Add(table.Rows[index]);
                    keptRowIds.Add(rowId);
                }

                table.Rows.Clear();
                table.Rows.AddRange(keptRows);
                table.RowIds.Clear();
                table.RowIds.AddRange(keptRowIds);
                foreach (var deletedRowId in deletedRowIds)
                {
                    context.ReportRowChange(
                        SqliteChangeOperation.Delete,
                        statement.TableName,
                        table,
                        deletedRowId);
                }

                return (long?)null;
            },
        };

        compiled = hasReturning
            ? DmlStatementCompiler.CompileWithFilter(
                DmlKind.Delete,
                statement.TableName,
                table.Columns.Length,
                filter,
                returningProgram!,
                writeTarget,
                new VdbeCursorSource(
                    returningRows!,
                    table.HasRowid ? returningRowIds : null))
            : DmlStatementCompiler.CompileWithFilter(
                DmlKind.Delete,
                statement.TableName,
                table.Columns.Length,
                filter,
                Array.Empty<DmlReturningExpression>(),
                writeTarget);
        return true;
    }

    // Reuses the SELECT expression emitter for RETURNING. The write loop first buffers every affected
    // row, then this block runs over that buffer in source order before Commit, preserving evaluator
    // predicate/assignment callback order while keeping projection failures statement-atomic.
    private bool TryCompileReturningClause(
        IReadOnlyList<Projection>? returning,
        EmbeddedTable table,
        string tableName,
        SqlValue[] parameters,
        QueryContext context,
        out DmlReturningProgram? program,
        out string[] columns,
        out bool hasReturning)
    {
        program = null;
        columns = [];
        hasReturning = false;
        if (returning is null)
            return true;

        var qualifiedColumns = BuildQualifiedColumns(tableName, table.Columns);
        var target = new ScanTarget(
            tableName,
            tableName,
            table.Columns,
            table.Rows,
            name => ResolveScanColumnIndex(name, table.Columns, qualifiedColumns),
            table.HasRowid ? table.RowIds : null);
        if (!SelectStatementCompiler.TryExpandProjections(returning, target, out var projections))
            return false;

        var outputColumns = BuildOutputColumns(tableName, table.Columns);
        columns = GetColumnNames(returning, outputColumns, outputColumns);
        if (columns.Length != projections.Count)
            return false;

        var instructions = new List<VdbeInstruction>();
        var emitter = new SelectStatementCompiler.ExpressionEmitter(
            target,
            new Cursor(1),
            projections.Count,
            instructions,
            programCounterBase: 0,
            allowControlFlow: false,
            IsConstantScalarExpression,
            expression => Evaluate(expression, parameters, null, context),
            function => TryGetRoutableBuiltinScalarCall(function, out var routable)
                ? BuildBuiltinScalarFunction(routable, parameters, context)
                : null,
            ArithmeticNumericAffinity,
            ModuloNumericAffinity,
            BitwiseIntegerAffinity);
        for (var index = 0; index < projections.Count; index++)
        {
            var projection = projections[index];
            if (projection.ColumnIndex is { } columnIndex)
            {
                instructions.Add(new ColumnInstruction(new Cursor(1), columnIndex, new Register(index)));
            }
            else if (!emitter.TryEmit(projection.Expression!, new Register(index)))
            {
                return false;
            }
        }

        program = new DmlReturningProgram(
            instructions,
            projections.Count,
            emitter.RegisterCount,
            emitter.ParameterIndices);
        hasReturning = true;
        return true;
    }

    // Builds a per-row predicate for a compilable DML WHERE clause. The emitted filter
    // builds the same SourceRow shape the evaluated UPDATE/DELETE use, so column
    // resolution matches exactly. A hidden-rowid reference becomes a rowid-aware filter
    // only for a rowid table; WITHOUT ROWID tables keep the evaluator's diagnostic path.
    private DmlRowFilter? CompileDmlRowPredicate(
        Expression where,
        EmbeddedTable table,
        string tableName,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (!IsScanPredicate(where))
            return null;

        var qualifiedColumns = BuildQualifiedColumns(tableName, table.Columns);
        var scanTarget = new ScanTarget(
            tableName,
            tableName,
            table.Columns,
            table.Rows,
            name => ResolveScanColumnIndex(name, table.Columns, qualifiedColumns));
        if (!ReferencesUnbackedRowid(where, scanTarget))
        {
            return DmlRowFilter.ForRow(row => IsTrue(Evaluate(
                where,
                parameters,
                new SourceRow(
                    table.Columns,
                    row,
                    qualifiedColumns,
                    RowIdQualifier: tableName,
                    ColumnDefinitions: table.ColumnDefinitions),
                context)));
        }

        if (!table.HasRowid)
            return null;

        return DmlRowFilter.ForRowId((row, rowId) => IsTrue(Evaluate(
            where,
            parameters,
            CreateDmlTargetRow(table, tableName, row, rowId),
            context)));
    }

    // Only literal numeric arithmetic is safe to evaluate while compiling: it is deterministic
    // and cannot raise or invoke user code. Other row-independent expressions must execute at their
    // normal row position (when lowerable) or remain on the evaluator, so volatile functions run per
    // row and an erroring projection is not evaluated for an empty input.
    private bool IsConstantScalarExpression(Expression expression)
    {
        return expression switch
        {
            LiteralExpression => true,
            BinaryExpression binary when TryMapArithmeticOperator(binary.Operator, out _)
                => IsConstantScalarExpression(binary.Left) && IsConstantScalarExpression(binary.Right),
            UnaryExpression unary when TryMapArithmeticOperator(unary.Operator, out _)
                => IsConstantScalarExpression(unary.Operand),
            CollationExpression collation => IsConstantScalarExpression(collation.Expression),
            _ => false,
        };
    }

    private ExecutionResult ExecuteExplain(
        ExplainStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        var compilationContext = EnsureAutoIncrementStatementState(context);
        ValidateStatementIndexDirectives(statement.Inner, compilationContext);
        if (statement.Inner is SelectStatement plannedSelect
            && HasExplainSafeBounds(plannedSelect)
            && TryPlanManagedIndexScan(plannedSelect, compilationContext) is { } indexPlan)
        {
            if (TryCompileManagedIndexSelect(
                    plannedSelect,
                    indexPlan,
                    parameters,
                    compilationContext,
                    outerRow: null,
                    materializeIndexRows: false,
                    out var compiledIndexSelect))
            {
                return DescribeProgram(compiledIndexSelect.Program);
            }

            throw new EmbeddedSqlException(
                "EXPLAIN is not available for this evaluator-managed index plan; "
                + "use EXPLAIN QUERY PLAN to inspect the selected index.");
        }

        switch (statement.Inner)
        {
            case SelectStatement select
                when HasExplainSafeBounds(select)
                    && TryCompileSelect(
                        select,
                        parameters,
                        compilationContext,
                        outerRow: null,
                        out var compiledSelect):
                return DescribeProgram(compiledSelect.Program);
            case CompoundSelectStatement compound
                when TryCompileCompoundSelect(
                    compound,
                    parameters,
                    compilationContext,
                    outerRow: null,
                    out var compiledCompound):
                return DescribeProgram(compiledCompound.Program);
            case InsertStatement insert
                when CanRouteInsertThroughCompiler(insert, compilationContext)
                    && TryCompileInsert(
                        insert,
                        parameters,
                        compilationContext,
                        out var compiledInsert,
                        out _,
                        out _):
                return DescribeProgram(compiledInsert.Program);
            case UpdateStatement update
                when CanRouteUpdateThroughCompiler(update, compilationContext)
                    && TryCompileUpdate(
                        update,
                        parameters,
                        compilationContext,
                        out var compiledUpdate,
                        out _,
                        out _):
                return DescribeProgram(compiledUpdate.Program);
            case DeleteStatement delete
                when CanCompileDml(compilationContext)
                    && TryCompileDelete(
                        delete,
                        parameters,
                        compilationContext,
                        out var compiledDelete,
                        out _,
                        out _):
                return DescribeProgram(compiledDelete.Program);
            case ValuesClause values
                when TryCompileValues(values, out var compiledValues, out _):
                return DescribeProgram(compiledValues.Program);
            case WithSelectStatement with
                when TryBuildNotMaterializedPassThroughExplainProgram(
                    with,
                    parameters,
                    compilationContext,
                    out var passThroughProgram):
                return DescribeProgram(passThroughProgram);
            case WithSelectStatement with
                when TryBuildRecursiveCteExplainProgram(
                    with,
                    parameters,
                    compilationContext,
                    out var recursiveProgram):
                return DescribeProgram(recursiveProgram);
        }

        // No fake plan: EXPLAIN only reports programs that were genuinely lowered.
        throw new EmbeddedSqlException(
            "EXPLAIN is only supported for statements lowered to the bytecode compiler.");
    }

    internal static string[] ExplainColumns() => ["addr", "opcode", "p1", "p2", "p3", "p4", "comment"];

    private ExecutionResult ExecuteExplainQueryPlan(
        ExplainQueryPlanStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        var compilationContext = EnsureAutoIncrementStatementState(context);
        ValidateStatementIndexDirectives(statement.Inner, compilationContext);
        if (statement.Inner is SelectStatement plannedSelect
            && TryPlanManagedIndexScan(plannedSelect, compilationContext) is { } indexPlan)
        {
            var operation = indexPlan.Search ? "SEARCH" : "SCAN";
            return new ExecutionResult(
                ExplainQueryPlanColumns(),
                [
                    [
                        SqlValue.Integer(0),
                        SqlValue.Integer(0),
                        SqlValue.Integer(0),
                        SqlValue.Text(
                            $"{operation} {indexPlan.Source.Alias ?? indexPlan.Source.Name} "
                            + $"USING INDEX {indexPlan.Index.Name}"),
                    ],
                ],
                0);
        }

        var usesCompiledProgram = statement.Inner switch
        {
            SelectStatement select => HasExplainSafeBounds(select)
                && CanUseCompiledSelectRoute(select, compilationContext, outerRow: null)
                && TryCompileSelect(select, parameters, compilationContext, outerRow: null, out _),
            CompoundSelectStatement compound => !compilationContext.CancellationToken.CanBeCanceled
                && TryCompileCompoundSelect(
                    compound,
                    parameters,
                    compilationContext,
                    outerRow: null,
                    out _),
            ValuesClause values => TryPrepareValuesLowering(values, out _),
            WithSelectStatement with => !compilationContext.CancellationToken.CanBeCanceled
                && (TryBuildNotMaterializedPassThroughExplainProgram(
                        with,
                        parameters,
                        compilationContext,
                        out _)
                    || TryBuildRecursiveCteExplainProgram(
                        with,
                        parameters,
                        compilationContext,
                        out _)),
            InsertStatement insert => CanRouteInsertThroughCompiler(insert, compilationContext)
                && TryCompileInsert(insert, parameters, compilationContext, out _, out _, out _),
            UpdateStatement update => CanRouteUpdateThroughCompiler(update, compilationContext)
                && TryCompileUpdate(update, parameters, compilationContext, out _, out _, out _),
            DeleteStatement delete => CanCompileDml(compilationContext)
                && TryCompileDelete(delete, parameters, compilationContext, out _, out _, out _),
            QueryStatement or WithDmlStatement => false,
            _ => throw new EmbeddedSqlException(
                "EXPLAIN QUERY PLAN is only supported for queries and INSERT, UPDATE, or DELETE statements."),
        };

        var detail = usesCompiledProgram
            ? "MANAGED COMPILED VDBE"
            : "MANAGED EVALUATOR FALLBACK";
        return new ExecutionResult(
            ExplainQueryPlanColumns(),
            [
                [
                    SqlValue.Integer(0),
                    SqlValue.Integer(0),
                    SqlValue.Integer(0),
                    SqlValue.Text(detail),
                ],
            ],
            0);
    }

    private static bool HasExplainSafeBounds(SelectStatement select) =>
        IsExplainSafeBound(select.Limit) && IsExplainSafeBound(select.Offset);

    private static bool IsExplainSafeBound(Expression? expression) =>
        expression switch
        {
            null or LiteralExpression or ParameterExpression => true,
            UnaryExpression unary => IsExplainSafeBound(unary.Operand),
            BinaryExpression binary => IsExplainSafeBound(binary.Left)
                && IsExplainSafeBound(binary.Right),
            CastExpression cast => IsExplainSafeBound(cast.Expression),
            CollationExpression collation => IsExplainSafeBound(collation.Expression),
            _ => false,
        };

    private static QueryContext EnsureAutoIncrementStatementState(QueryContext context)
        => context.AutoIncrementState is null
            ? context with { AutoIncrementState = new AutoIncrementStatementState() }
            : context;

    internal static string[] ExplainQueryPlanColumns() => ["id", "parent", "notused", "detail"];

    private static ExecutionResult DescribeProgram(VdbeProgram program)
    {
        var rows = new List<SqlValue[]>(program.Instructions.Count);
        for (var address = 0; address < program.Instructions.Count; address++)
        {
            var instruction = program.Instructions[address];
            var (p1, p2, p3, p4, comment) = DescribeInstruction(instruction);
            rows.Add(
            [
                SqlValue.Integer(address),
                SqlValue.Text(instruction.Opcode.ToString()),
                SqlValue.Integer(p1),
                SqlValue.Integer(p2),
                SqlValue.Integer(p3),
                p4 is null ? SqlValue.Null : SqlValue.Text(p4),
                SqlValue.Text(comment),
            ]);
        }

        return new ExecutionResult(ExplainColumns(), rows, 0);
    }

    private static (long P1, long P2, long P3, string? P4, string Comment) DescribeInstruction(
        VdbeInstruction instruction)
    {
        return instruction switch
        {
            LoadConstantInstruction load => (
                load.Destination.Index,
                0,
                0,
                FormatExplainValue(load.Value),
                $"r[{load.Destination.Index}]={FormatExplainValue(load.Value)}"),
            LoadParameterInstruction loadParameter => (
                loadParameter.Destination.Index,
                loadParameter.Slot.Index,
                0,
                $"param[{loadParameter.Slot.Index}]",
                $"r[{loadParameter.Destination.Index}]=param[{loadParameter.Slot.Index}]"),
            CopyInstruction copy => (
                copy.Source.Index,
                copy.Destination.Index,
                0,
                null,
                $"r[{copy.Destination.Index}]=r[{copy.Source.Index}]"),
            // Mirrors VdbeExplain.Describe so a routed scalar-function projection renders byte-identically
            // to the canonical instruction renderer.
            FunctionInstruction function => (
                function.Destination.Index,
                function.Arguments.Start.Index,
                function.Arguments.Count,
                function.Function.Name,
                $"r[{function.Destination.Index}]={function.Function.Name}({FormatRegisterRange(function.Arguments)})"),
            // Shared with the executor's own describe path (like the recursive-worktable opcodes below), so a
            // routed arithmetic projection renders byte-identically to the canonical instruction renderer.
            ArithmeticInstruction => VdbeExplain.Describe(instruction),
            NumericAffinityInstruction => VdbeExplain.Describe(instruction),
            CompareInstruction => VdbeExplain.Describe(instruction),
            JumpIfNotTrueInstruction => VdbeExplain.Describe(instruction),
            CastInstruction => VdbeExplain.Describe(instruction),
            OpenJoinCursorInstruction => VdbeExplain.Describe(instruction),
            OpenReadCursorInstruction open => (
                open.Cursor.Index,
                0,
                open.ColumnCount,
                open.TableName,
                open.TableName is null
                    ? $"open read cursor {open.Cursor.Index}"
                    : $"open read cursor {open.Cursor.Index} on {open.TableName} ({open.ColumnCount} cols)"),
            OpenWriteCursorInstruction openWrite => (
                openWrite.Cursor.Index,
                0,
                openWrite.ColumnCount,
                openWrite.TableName,
                $"open write cursor {openWrite.Cursor.Index} on {openWrite.TableName} ({openWrite.ColumnCount} cols)"),
            CloseCursorInstruction close => (close.Cursor.Index, 0, 0, null, $"close cursor {close.Cursor.Index}"),
            RewindCursorInstruction rewind => (
                rewind.Cursor.Index,
                rewind.EmptyTarget.Offset,
                0,
                null,
                $"rewind cursor {rewind.Cursor.Index}, goto {rewind.EmptyTarget.Offset} if empty"),
            LastCursorInstruction => VdbeExplain.Describe(instruction),
            ColumnInstruction column => (
                column.Cursor.Index,
                column.ColumnIndex,
                column.Destination.Index,
                null,
                $"r[{column.Destination.Index}]=c{column.Cursor.Index}.col[{column.ColumnIndex}]"),
            RowIdInstruction rowId => (
                rowId.Cursor.Index,
                rowId.Destination.Index,
                0,
                null,
                $"r[{rowId.Destination.Index}]=c{rowId.Cursor.Index}.rowid"),
            RowCountInstruction => VdbeExplain.Describe(instruction),
            FilterInstruction filter => (
                filter.Cursor.Index,
                filter.FalseTarget.Offset,
                0,
                null,
                filter.Description),
            FilterRowIdInstruction => VdbeExplain.Describe(instruction),
            SeekRowidInstruction => VdbeExplain.Describe(instruction),
            SeekRowidRangeInstruction => VdbeExplain.Describe(instruction),
            FilterRegistersInstruction filterRegisters => (
                filterRegisters.Row.Start.Index,
                filterRegisters.FalseTarget.Offset,
                filterRegisters.Row.Count,
                null,
                filterRegisters.Description),
            GroupKeyInstruction => VdbeExplain.Describe(instruction),
            ProjectRegistersInstruction => VdbeExplain.Describe(instruction),
            DistinctFilterInstruction => VdbeExplain.Describe(instruction),
            NextInstruction next => (
                next.Cursor.Index,
                next.LoopTarget.Offset,
                0,
                null,
                $"next cursor {next.Cursor.Index}, goto {next.LoopTarget.Offset} if more rows"),
            PrevInstruction => VdbeExplain.Describe(instruction),
            OpenSorterInstruction openSorter => (
                openSorter.Sorter.Index,
                0,
                openSorter.ColumnCount,
                null,
                $"open sorter {openSorter.Sorter.Index} ({openSorter.ColumnCount} cols)"),
            SorterInsertInstruction sorterInsert => (
                sorterInsert.Sorter.Index,
                sorterInsert.Record.Start.Index,
                sorterInsert.Record.Count,
                null,
                $"sorter {sorterInsert.Sorter.Index} insert {FormatRegisterRange(sorterInsert.Record)}"),
            SorterSortInstruction sorterSort => (
                sorterSort.Sorter.Index,
                sorterSort.EmptyTarget.Offset,
                0,
                null,
                $"sort sorter {sorterSort.Sorter.Index}, goto {sorterSort.EmptyTarget.Offset} if empty"),
            SorterDataInstruction sorterData => (
                sorterData.Sorter.Index,
                sorterData.Destination.Start.Index,
                sorterData.Destination.Count,
                null,
                $"{FormatRegisterRange(sorterData.Destination)}=sorter {sorterData.Sorter.Index} data"),
            SorterNextInstruction sorterNext => (
                sorterNext.Sorter.Index,
                sorterNext.LoopTarget.Offset,
                0,
                null,
                $"next sorter {sorterNext.Sorter.Index}, goto {sorterNext.LoopTarget.Offset} if more rows"),
            CloseSorterInstruction closeSorter => (
                closeSorter.Sorter.Index,
                0,
                0,
                null,
                $"close sorter {closeSorter.Sorter.Index}"),
            ResultRowInstruction result => (
                result.Values.Start.Index,
                result.Values.Count,
                0,
                null,
                DescribeResultRow(result.Values)),
            DistinctResultRowInstruction distinct => (
                distinct.Values.Start.Index,
                distinct.Values.Count,
                distinct.DistinctSetIndex,
                null,
                $"{DescribeResultRow(distinct.Values)} if new to distinct set {distinct.DistinctSetIndex}"),
            DistinctGateInstruction => VdbeExplain.Describe(instruction),
            YieldInstruction => (0, 0, 0, null, "yield"),
            DeleteInstruction delete => (
                delete.Cursor.Index,
                0,
                0,
                null,
                $"delete current row of cursor {delete.Cursor.Index}"),
            InsertInstruction insert => (
                insert.Cursor.Index,
                0,
                0,
                null,
                $"insert row into cursor {insert.Cursor.Index}"),
            UpdateInstruction update => (
                update.Cursor.Index,
                0,
                0,
                null,
                $"update current row of cursor {update.Cursor.Index}"),
            CommitInstruction commit => (
                commit.Cursor.Index,
                0,
                0,
                null,
                $"commit mutations of cursor {commit.Cursor.Index}"),
            GotoInstruction gotoInstruction => (
                0,
                gotoInstruction.Target.Offset,
                0,
                null,
                $"goto {gotoInstruction.Target.Offset}"),
            JumpIfInstruction jumpIf => (
                jumpIf.Register.Index,
                jumpIf.Target.Offset,
                0,
                null,
                $"goto {jumpIf.Target.Offset} if r[{jumpIf.Register.Index}]"),
            AggResetInstruction aggReset => (
                aggReset.Accumulator.Index,
                0,
                0,
                null,
                $"reset accumulator {aggReset.Accumulator.Index}"),
            AggStepInstruction aggStep => (
                aggStep.Accumulator.Index,
                aggStep.Arguments.Start.Index,
                aggStep.Arguments.Count,
                aggStep.Aggregate.Name,
                $"accumulator {aggStep.Accumulator.Index}={aggStep.Aggregate.Name} step {FormatRegisterRange(aggStep.Arguments)}"),
            AggFinalizeInstruction aggFinalize => (
                aggFinalize.Accumulator.Index,
                aggFinalize.Destination.Index,
                0,
                aggFinalize.Aggregate.Name,
                $"r[{aggFinalize.Destination.Index}]={aggFinalize.Aggregate.Name} finalize accumulator {aggFinalize.Accumulator.Index}"),
            SameGroupInstruction sameGroup => (
                sameGroup.CurrentKey.Start.Index,
                sameGroup.SameGroupTarget.Offset,
                sameGroup.SavedKey.Start.Index,
                null,
                $"goto {sameGroup.SameGroupTarget.Offset} if group {FormatRegisterRange(sameGroup.CurrentKey)}=={FormatRegisterRange(sameGroup.SavedKey)}"),
            RowSetInsertInstruction rowSetInsert => (
                rowSetInsert.Values.Start.Index,
                rowSetInsert.Values.Count,
                rowSetInsert.RowSetIndex,
                null,
                $"insert {FormatRegisterRange(rowSetInsert.Values)} into row set {rowSetInsert.RowSetIndex}"),
            CompoundResultRowInstruction compound => (
                compound.Values.Start.Index,
                compound.Values.Count,
                compound.OutputSetIndex,
                FormatSetList(compound.MembershipSetIndices),
                $"{DescribeResultRow(compound.Values)} if new to distinct set {compound.OutputSetIndex} and {FormatMembership(compound.Mode)} {FormatSetList(compound.MembershipSetIndices)}"),
            OffsetGateInstruction offsetGate => (
                offsetGate.Counter.Index,
                offsetGate.SkipTarget.Offset,
                0,
                null,
                $"goto {offsetGate.SkipTarget.Offset} and decrement r[{offsetGate.Counter.Index}] while r[{offsetGate.Counter.Index}]>0"),
            LimitGateInstruction limitGate => (
                limitGate.Counter.Index,
                limitGate.DoneTarget.Offset,
                0,
                null,
                $"goto {limitGate.DoneTarget.Offset} when r[{limitGate.Counter.Index}]<=0, else decrement r[{limitGate.Counter.Index}]"),
            HaltInstruction => (0, 0, 0, null, "halt"),
            // The recursive-worktable opcodes are shared with the executor's own describe path, so reuse
            // its canonical rendering here rather than duplicating it and risking drift.
            OpenWorkTableInstruction => VdbeExplain.Describe(instruction),
            SeedWorkTableInstruction => VdbeExplain.Describe(instruction),
            WorkTableStepInstruction => VdbeExplain.Describe(instruction),
            WorkTableExpandInstruction => VdbeExplain.Describe(instruction),
            WorkTableExpandGenerationInstruction => VdbeExplain.Describe(instruction),
            CloseWorkTableInstruction => VdbeExplain.Describe(instruction),
            OpenWindowBufferInstruction => VdbeExplain.Describe(instruction),
            WindowBufferInsertInstruction => VdbeExplain.Describe(instruction),
            WindowBufferComputeInstruction => VdbeExplain.Describe(instruction),
            WindowBufferDataInstruction => VdbeExplain.Describe(instruction),
            WindowBufferNextInstruction => VdbeExplain.Describe(instruction),
            CloseWindowBufferInstruction => VdbeExplain.Describe(instruction),
            RowSetRewindInstruction => VdbeExplain.Describe(instruction),
            RowSetNextInstruction => VdbeExplain.Describe(instruction),
            GuardedRowInstruction => VdbeExplain.Describe(instruction),
            _ => throw new EmbeddedSqlException($"Cannot describe unsupported opcode {instruction.Opcode}."),
        };
    }

    private static string DescribeResultRow(RegisterRange range)
    {
        if (range.Count == 0)
            return "output=r[]";

        var start = range.Start.Index;
        return range.Count == 1
            ? $"output=r[{start}]"
            : $"output=r[{start}..{start + range.Count - 1}]";
    }

    // Mirrors VdbeExplain.FormatMembership so the SQL EXPLAIN comment for a routed set operation is
    // byte-identical to the canonical instruction renderer.
    private static string FormatMembership(CompoundMembershipMode mode) => mode switch
    {
        CompoundMembershipMode.PresentInAll => "present in all of",
        CompoundMembershipMode.AbsentFromAll => "absent from all of",
        _ => throw new EmbeddedSqlException($"Unknown compound membership mode {mode}."),
    };

    // Mirrors VdbeExplain.FormatSetList so the SQL EXPLAIN p4/comment for a routed set operation is
    // byte-identical to the canonical instruction renderer.
    private static string FormatSetList(IReadOnlyList<int> setIndices)
    {
        if (setIndices is null || setIndices.Count == 0)
            return "sets {}";

        return $"sets {{{string.Join(",", setIndices)}}}";
    }

    private static string FormatRegisterRange(RegisterRange range)
    {
        if (range.Count == 0)
            return "r[]";

        var start = range.Start.Index;
        return range.Count == 1
            ? $"r[{start}]"
            : $"r[{start}..{start + range.Count - 1}]";
    }

    private static string FormatExplainValue(SqlValue value)
    {
        return value.Kind switch
        {
            SqlValueKind.Null => "NULL",
            SqlValueKind.Integer => value.AsInteger().ToString(CultureInfo.InvariantCulture),
            SqlValueKind.Real => value.AsReal().ToString("R", CultureInfo.InvariantCulture),
            SqlValueKind.Text => $"'{value.AsText()}'",
            SqlValueKind.Blob => FormatExplainBlob(value.AsBlob().Span),
            _ => throw new EmbeddedSqlException($"Unknown SQL value kind {value.Kind}."),
        };
    }

    private static string FormatExplainBlob(ReadOnlySpan<byte> bytes)
    {
        var builder = new StringBuilder(bytes.Length * 2 + 3);
        builder.Append("x'");
        foreach (var b in bytes)
            builder.Append(b.ToString("X2", CultureInfo.InvariantCulture));
        builder.Append('\'');
        return builder.ToString();
    }

    private void ValidateStatementIndexDirectives(ParsedStatement statement, QueryContext context)
    {
        switch (statement)
        {
            case QueryStatement query:
                ValidateQueryIndexDirectives(query, context);
                break;
            case InsertStatement { Source: { } source }:
                ValidateQueryIndexDirectives(source, context);
                break;
            case WithDmlStatement with:
                ValidateWithIndexDirectives(
                    with.CommonTableExpressions,
                    context,
                    scoped => ValidateStatementIndexDirectives(with.Dml, scoped));
                break;
        }
    }

    private void ValidateQueryIndexDirectives(QueryStatement statement, QueryContext context)
    {
        switch (statement)
        {
            case SelectStatement select:
                ValidateSelectIndexDirectives(select, context);
                break;
            case CompoundSelectStatement compound:
                foreach (var term in compound.Terms)
                    ValidateQueryIndexDirectives(term, context);
                foreach (var order in compound.OrderBy)
                    ValidateExpressionIndexDirectives(order.Expression, context);
                ValidateExpressionIndexDirectives(compound.Limit, context);
                ValidateExpressionIndexDirectives(compound.Offset, context);
                break;
            case WithSelectStatement with:
                ValidateWithIndexDirectives(
                    with.CommonTableExpressions,
                    context,
                    scoped => ValidateQueryIndexDirectives(with.Query, scoped));
                break;
            case ValuesClause values:
                foreach (var expression in values.Rows.SelectMany(row => row))
                    ValidateExpressionIndexDirectives(expression, context);
                break;
        }
    }

    private void ValidateWithIndexDirectives(
        IReadOnlyList<CommonTableExpression> expressions,
        QueryContext context,
        Action<QueryContext> validateBody)
    {
        var commonTableExpressions = new Dictionary<string, SourceData>(
            context.CommonTableExpressions,
            StringComparer.OrdinalIgnoreCase);
        foreach (var expression in expressions)
        {
            commonTableExpressions[expression.Name] = new SourceData([], []);
            ValidateQueryIndexDirectives(
                expression.Query,
                context with { CommonTableExpressions = commonTableExpressions });
        }

        validateBody(context with { CommonTableExpressions = commonTableExpressions });
    }

    private void ValidateSelectIndexDirectives(SelectStatement statement, QueryContext context)
    {
        var whereTerms = statement.Where is null
            ? []
            : IndexExpressionSemantics.SplitConjuncts(statement.Where);
        ValidateTableSourceIndexDirectives(
            statement.Source,
            whereTerms,
            inheritedJoinConstraints: [],
            nullSupplying: false,
            allowUnqualified: CountTableSourceLeaves(statement.Source) <= 1,
            context);
        foreach (var projection in statement.Projections)
            ValidateExpressionIndexDirectives(projection.Expression, context);
        ValidateExpressionIndexDirectives(statement.Where, context);
        foreach (var expression in statement.GroupBy)
            ValidateExpressionIndexDirectives(expression, context);
        ValidateExpressionIndexDirectives(statement.Having, context);
        foreach (var window in statement.NamedWindows)
            ValidateWindowIndexDirectives(window.Specification, context);
        foreach (var order in statement.OrderBy)
            ValidateExpressionIndexDirectives(order.Expression, context);
        ValidateExpressionIndexDirectives(statement.Limit, context);
        ValidateExpressionIndexDirectives(statement.Offset, context);
    }

    private void ValidateTableSourceIndexDirectives(
        TableSource? source,
        IReadOnlyList<Expression> whereTerms,
        IReadOnlyList<IndexConstraint> inheritedJoinConstraints,
        bool nullSupplying,
        bool allowUnqualified,
        QueryContext context)
    {
        switch (source)
        {
            case null:
                return;
            case TableValuedFunctionSource function:
                foreach (var argument in function.Arguments)
                    ValidateExpressionIndexDirectives(argument, context);
                return;
            case NamedTableSource named:
                var constraints = inheritedJoinConstraints
                    .Concat(whereTerms.Select(expression =>
                        new IndexConstraint(expression, RequiresNullRejection: nullSupplying)))
                    .ToArray();
                ValidateNamedTableIndexDirective(named, constraints, allowUnqualified, context);
                if (TryGetView(context, named.Name, out var view)
                    && named.IndexDirective is not IndexedByDirective)
                {
                    ValidateQueryIndexDirectives(
                        view.Query,
                        EnterView(context, view.Name));
                }
                return;
            case DerivedTableSource derived:
                ValidateQueryIndexDirectives(derived.Query, context);
                return;
            case JoinTableSource join:
                ValidateExpressionIndexDirectives(join.Condition, context);
                var joinTerms = join.Condition is null
                    ? []
                    : IndexExpressionSemantics.SplitConjuncts(join.Condition);
                var leftBecomesNullSupplying = join.Kind is JoinKind.Right or JoinKind.Full;
                var rightBecomesNullSupplying = join.Kind is JoinKind.Left or JoinKind.Full;
                // Predicates inherited from above an outer-join boundary run after this
                // side can be null-extended. Only this join's own ON terms may filter its
                // non-preserved input without first proving null rejection.
                var leftJoinConstraints = RequireNullRejection(
                    inheritedJoinConstraints,
                    leftBecomesNullSupplying);
                var rightJoinConstraints = RequireNullRejection(
                    inheritedJoinConstraints,
                    rightBecomesNullSupplying);
                if (join.Kind is JoinKind.Inner or JoinKind.Right)
                {
                    leftJoinConstraints =
                    [
                        .. leftJoinConstraints,
                        .. joinTerms.Select(expression =>
                            new IndexConstraint(expression, RequiresNullRejection: false)),
                    ];
                }
                if (join.Kind is JoinKind.Inner or JoinKind.Left)
                {
                    rightJoinConstraints =
                    [
                        .. rightJoinConstraints,
                        .. joinTerms.Select(expression =>
                            new IndexConstraint(expression, RequiresNullRejection: false)),
                    ];
                }

                ValidateTableSourceIndexDirectives(
                    join.Left,
                    whereTerms,
                    leftJoinConstraints,
                    nullSupplying || leftBecomesNullSupplying,
                    allowUnqualified,
                    context);
                ValidateTableSourceIndexDirectives(
                    join.Right,
                    whereTerms,
                    rightJoinConstraints,
                    nullSupplying || rightBecomesNullSupplying,
                    allowUnqualified,
                    context);
                return;
            default:
                throw new InvalidOperationException($"Unknown table source {source.GetType().Name}.");
        }
    }

    private static IReadOnlyList<IndexConstraint> RequireNullRejection(
        IReadOnlyList<IndexConstraint> constraints,
        bool required)
    {
        if (!required || constraints.All(constraint => constraint.RequiresNullRejection))
            return constraints;

        return constraints
            .Select(constraint => constraint.RequiresNullRejection
                ? constraint
                : constraint with { RequiresNullRejection = true })
            .ToArray();
    }

    private void ValidateExpressionIndexDirectives(Expression? expression, QueryContext context)
    {
        switch (expression)
        {
            case null or LiteralExpression or CurrentTimeExpression or ParameterExpression or RaiseExpression
                or ColumnExpression or StarExpression or QualifiedStarExpression:
                return;
            case RowValueExpression row:
                foreach (var value in row.Values)
                    ValidateExpressionIndexDirectives(value, context);
                return;
            case FunctionExpression function:
                foreach (var argument in function.Arguments)
                    ValidateExpressionIndexDirectives(argument, context);
                ValidateExpressionIndexDirectives(function.Filter, context);
                ValidateWindowIndexDirectives(function.Window, context);
                return;
            case ScalarSubqueryExpression scalar:
                ValidateQueryIndexDirectives(scalar.Query, context);
                return;
            case ExistsExpression exists:
                ValidateQueryIndexDirectives(exists.Query, context);
                return;
            case InSubqueryExpression @in:
                ValidateExpressionIndexDirectives(@in.Value, context);
                ValidateQueryIndexDirectives(@in.Query, context);
                return;
            case CollationExpression collation:
                ValidateExpressionIndexDirectives(collation.Expression, context);
                return;
            case CastExpression cast:
                ValidateExpressionIndexDirectives(cast.Expression, context);
                return;
            case CaseExpression @case:
                ValidateExpressionIndexDirectives(@case.Operand, context);
                foreach (var clause in @case.Clauses)
                {
                    ValidateExpressionIndexDirectives(clause.When, context);
                    ValidateExpressionIndexDirectives(clause.Then, context);
                }
                ValidateExpressionIndexDirectives(@case.Else, context);
                return;
            case LikeExpression like:
                ValidateExpressionIndexDirectives(like.Value, context);
                ValidateExpressionIndexDirectives(like.Pattern, context);
                ValidateExpressionIndexDirectives(like.Escape, context);
                return;
            case GlobExpression glob:
                ValidateExpressionIndexDirectives(glob.Value, context);
                ValidateExpressionIndexDirectives(glob.Pattern, context);
                return;
            case InExpression @in:
                ValidateExpressionIndexDirectives(@in.Value, context);
                foreach (var value in @in.Values)
                    ValidateExpressionIndexDirectives(value, context);
                return;
            case BetweenExpression between:
                ValidateExpressionIndexDirectives(between.Value, context);
                ValidateExpressionIndexDirectives(between.Lower, context);
                ValidateExpressionIndexDirectives(between.Upper, context);
                return;
            case UnaryExpression unary:
                ValidateExpressionIndexDirectives(unary.Operand, context);
                return;
            case BinaryExpression binary:
                ValidateExpressionIndexDirectives(binary.Left, context);
                ValidateExpressionIndexDirectives(binary.Right, context);
                return;
            default:
                throw new InvalidOperationException($"Unknown expression {expression.GetType().Name}.");
        }
    }

    private void ValidateWindowIndexDirectives(WindowSpecification? window, QueryContext context)
    {
        if (window is null)
            return;
        foreach (var partition in window.PartitionBy)
            ValidateExpressionIndexDirectives(partition, context);
        foreach (var order in window.OrderBy)
            ValidateExpressionIndexDirectives(order.Expression, context);
        ValidateExpressionIndexDirectives(window.Frame?.Start.Offset, context);
        ValidateExpressionIndexDirectives(window.Frame?.End.Offset, context);
    }

    private void ValidateNamedTableIndexDirective(
        NamedTableSource source,
        IReadOnlyList<IndexConstraint> constraints,
        bool allowUnqualified,
        QueryContext context)
    {
        if (source.IndexDirective is not IndexedByDirective indexedBy)
            return;
        if (IsSchemaTable(source.Name)
            || context.CommonTableExpressions.ContainsKey(source.Name)
            || TryGetView(context, source.Name, out _))
        {
            throw new EmbeddedSqlException($"no such index: {indexedBy.IndexName}");
        }
        if (!context.Tables.TryGetValue(source.Name, out var table))
            return;

        var index = table.Indexes.FirstOrDefault(candidate =>
            string.Equals(candidate.Name, indexedBy.IndexName, StringComparison.OrdinalIgnoreCase));
        if (index is null)
            throw new EmbeddedSqlException($"no such index: {indexedBy.IndexName}");
        if (index.Where is null)
            return;

        var registeredPredicateFunction = IndexExpressionSemantics.ContainsFunction(
            index.Where,
            IsRegisteredScalarFunction);
        if (registeredPredicateFunction
            || !SourcePredicatesImplyIndex(
                constraints,
                index.Where,
                source,
                allowUnqualified))
        {
            throw new EmbeddedSqlException("no query solution");
        }
    }

    private static bool SourcePredicatesImplyIndex(
        IReadOnlyList<IndexConstraint> constraints,
        Expression indexPredicate,
        NamedTableSource source,
        bool allowUnqualified)
    {
        foreach (var required in IndexExpressionSemantics.SplitConjuncts(indexPredicate))
        {
            var matched = constraints.Any(constraint =>
                ExpressionColumnsBelongToSource(constraint.Expression, source, allowUnqualified)
                && IndexExpressionSemantics.PredicateTermsEqual(constraint.Expression, required)
                && (!constraint.RequiresNullRejection
                    || IsDirectNullRejectingPredicate(
                        constraint.Expression,
                        source,
                        allowUnqualified)));
            if (!matched)
                return false;
        }

        return true;
    }

    private static bool ExpressionColumnsBelongToSource(
        Expression expression,
        NamedTableSource source,
        bool allowUnqualified)
    {
        return expression switch
        {
            ColumnExpression column => ColumnBelongsToSource(column, source, allowUnqualified),
            RowValueExpression row => row.Values.All(value =>
                ExpressionColumnsBelongToSource(value, source, allowUnqualified)),
            FunctionExpression function => function.Arguments.All(argument =>
                    ExpressionColumnsBelongToSource(argument, source, allowUnqualified))
                && (function.Filter is null
                    || ExpressionColumnsBelongToSource(function.Filter, source, allowUnqualified))
                && WindowColumnsBelongToSource(function.Window, source, allowUnqualified),
            ScalarSubqueryExpression or ExistsExpression or InSubqueryExpression => false,
            CollationExpression collation =>
                ExpressionColumnsBelongToSource(collation.Expression, source, allowUnqualified),
            CastExpression cast =>
                ExpressionColumnsBelongToSource(cast.Expression, source, allowUnqualified),
            CaseExpression @case =>
                (@case.Operand is null
                    || ExpressionColumnsBelongToSource(@case.Operand, source, allowUnqualified))
                && @case.Clauses.All(clause =>
                    ExpressionColumnsBelongToSource(clause.When, source, allowUnqualified)
                    && ExpressionColumnsBelongToSource(clause.Then, source, allowUnqualified))
                && (@case.Else is null
                    || ExpressionColumnsBelongToSource(@case.Else, source, allowUnqualified)),
            LikeExpression like =>
                ExpressionColumnsBelongToSource(like.Value, source, allowUnqualified)
                && ExpressionColumnsBelongToSource(like.Pattern, source, allowUnqualified)
                && (like.Escape is null
                    || ExpressionColumnsBelongToSource(like.Escape, source, allowUnqualified)),
            GlobExpression glob =>
                ExpressionColumnsBelongToSource(glob.Value, source, allowUnqualified)
                && ExpressionColumnsBelongToSource(glob.Pattern, source, allowUnqualified),
            InExpression @in =>
                ExpressionColumnsBelongToSource(@in.Value, source, allowUnqualified)
                && @in.Values.All(value =>
                    ExpressionColumnsBelongToSource(value, source, allowUnqualified)),
            BetweenExpression between =>
                ExpressionColumnsBelongToSource(between.Value, source, allowUnqualified)
                && ExpressionColumnsBelongToSource(between.Lower, source, allowUnqualified)
                && ExpressionColumnsBelongToSource(between.Upper, source, allowUnqualified),
            UnaryExpression unary =>
                ExpressionColumnsBelongToSource(unary.Operand, source, allowUnqualified),
            BinaryExpression binary =>
                ExpressionColumnsBelongToSource(binary.Left, source, allowUnqualified)
                && ExpressionColumnsBelongToSource(binary.Right, source, allowUnqualified),
            QualifiedStarExpression => false,
            _ => true,
        };
    }

    private static bool WindowColumnsBelongToSource(
        WindowSpecification? window,
        NamedTableSource source,
        bool allowUnqualified)
    {
        if (window is null)
            return true;

        return window.PartitionBy.All(expression =>
                ExpressionColumnsBelongToSource(expression, source, allowUnqualified))
            && window.OrderBy.All(term =>
                ExpressionColumnsBelongToSource(term.Expression, source, allowUnqualified))
            && (window.Frame?.Start.Offset is null
                || ExpressionColumnsBelongToSource(window.Frame.Start.Offset, source, allowUnqualified))
            && (window.Frame?.End.Offset is null
                || ExpressionColumnsBelongToSource(window.Frame.End.Offset, source, allowUnqualified));
    }

    private static bool IsDirectNullRejectingPredicate(
        Expression expression,
        NamedTableSource source,
        bool allowUnqualified)
    {
        return expression switch
        {
            BinaryExpression binary when binary.Operator is BinaryOperator.Equal
                or BinaryOperator.NotEqual
                or BinaryOperator.LessThan
                or BinaryOperator.LessThanOrEqual
                or BinaryOperator.GreaterThan
                or BinaryOperator.GreaterThanOrEqual =>
                IsDirectSourceValue(binary.Left, source, allowUnqualified)
                || IsDirectSourceValue(binary.Right, source, allowUnqualified),
            BinaryExpression { Operator: BinaryOperator.Is } binary =>
                IsDirectSourceValue(binary.Left, source, allowUnqualified)
                    && binary.Right is LiteralExpression { Value.Kind: not SqlValueKind.Null }
                || IsDirectSourceValue(binary.Right, source, allowUnqualified)
                    && binary.Left is LiteralExpression { Value.Kind: not SqlValueKind.Null },
            BinaryExpression { Operator: BinaryOperator.IsNot } binary =>
                IsDirectSourceValue(binary.Left, source, allowUnqualified)
                    && binary.Right is LiteralExpression { Value.Kind: SqlValueKind.Null }
                || IsDirectSourceValue(binary.Right, source, allowUnqualified)
                    && binary.Left is LiteralExpression { Value.Kind: SqlValueKind.Null },
            BetweenExpression between =>
                IsDirectSourceValue(between.Value, source, allowUnqualified),
            InExpression @in =>
                IsDirectSourceValue(@in.Value, source, allowUnqualified),
            LikeExpression like =>
                IsDirectSourceValue(like.Value, source, allowUnqualified),
            GlobExpression glob =>
                IsDirectSourceValue(glob.Value, source, allowUnqualified),
            UnaryExpression { Operator: UnaryOperator.Not } unary =>
                IsDirectNullRejectingPredicate(unary.Operand, source, allowUnqualified),
            _ => false,
        };
    }

    private static bool IsDirectSourceValue(
        Expression expression,
        NamedTableSource source,
        bool allowUnqualified)
    {
        return expression switch
        {
            ColumnExpression column => ColumnBelongsToSource(column, source, allowUnqualified),
            CollationExpression collation =>
                IsDirectSourceValue(collation.Expression, source, allowUnqualified),
            CastExpression cast => IsDirectSourceValue(cast.Expression, source, allowUnqualified),
            UnaryExpression { Operator: UnaryOperator.Plus or UnaryOperator.Negate or UnaryOperator.BitwiseNot } unary =>
                IsDirectSourceValue(unary.Operand, source, allowUnqualified),
            _ => false,
        };
    }

    private static bool ColumnBelongsToSource(
        ColumnExpression column,
        NamedTableSource source,
        bool allowUnqualified)
    {
        if (column.Qualifier is null)
            return allowUnqualified;

        var qualifier = source.Alias ?? source.Name;
        return string.Equals(column.Qualifier, qualifier, StringComparison.OrdinalIgnoreCase);
    }

    private static int CountTableSourceLeaves(TableSource? source)
    {
        return source switch
        {
            null => 0,
            JoinTableSource join => CountTableSourceLeaves(join.Left) + CountTableSourceLeaves(join.Right),
            _ => 1,
        };
    }

    private ManagedIndexScanPlan? TryPlanManagedIndexScan(
        SelectStatement statement,
        QueryContext context)
    {
        if (statement.Source is not NamedTableSource source
            || IsSchemaTable(source.Name)
            || context.CommonTableExpressions.ContainsKey(source.Name)
            || context.Views?.ContainsKey(source.Name) == true
            || !context.Tables.TryGetValue(source.Name, out var table))
        {
            return null;
        }

        if (source.IndexDirective is NotIndexedDirective)
            return null;
        if (source.IndexDirective is IndexedByDirective)
            return CreateForcedIndexScanPlan(source, table, statement.Where);

        foreach (var index in table.Indexes.OrderBy(candidate => candidate.Name, StringComparer.OrdinalIgnoreCase))
        {
            if ((!index.IsPartial && index.Columns.All(term => !term.IsExpression))
                || !IndexExpressionSemantics.PredicateImplies(
                    statement.Where,
                    index.Where,
                    source.Name,
                    source.Alias)
                || IndexUsesRegisteredFunctions(index)
                || IndexUsesOverriddenBuiltInCollation(index, table))
            {
                continue;
            }

            var leading = index.Columns[0];
            var search = WhereUsesIndexTerm(statement.Where, table, leading);
            var ordered = OrderByUsesIndex(statement.OrderBy, table, index);
            if (search || ordered)
                return new ManagedIndexScanPlan(source, table, index, search);
        }

        return null;
    }

    private static ManagedIndexScanPlan CreateForcedIndexScanPlan(
        NamedTableSource source,
        EmbeddedTable table,
        Expression? where)
    {
        var indexedBy = source.IndexDirective as IndexedByDirective
            ?? throw new InvalidOperationException("A forced index scan requires an INDEXED BY directive.");
        var index = table.Indexes.FirstOrDefault(candidate =>
            string.Equals(candidate.Name, indexedBy.IndexName, StringComparison.OrdinalIgnoreCase))
            ?? throw new EmbeddedSqlException($"no such index: {indexedBy.IndexName}");
        return new ManagedIndexScanPlan(
            source,
            table,
            index,
            WhereUsesIndexTerm(where, table, index.Columns[0]));
    }

    private static bool OrderByUsesIndex(
        IReadOnlyList<OrderByTerm> orderBy,
        EmbeddedTable table,
        EmbeddedIndex index)
    {
        if (orderBy.Count == 0 || orderBy.Count > index.Columns.Count)
            return false;

        for (var position = 0; position < orderBy.Count; position++)
        {
            var order = orderBy[position];
            var indexed = index.Columns[position];
            if (order.Ordinal is not null
                || order.Descending != indexed.Descending
                || !NullPlacementMatchesIndex(order)
                || !QueryExpressionMatchesIndexTerm(order.Expression, table, indexed))
            {
                return false;
            }
        }

        return true;
    }

    private static bool NullPlacementMatchesIndex(OrderByTerm order)
    {
        return order.NullPlacement switch
        {
            NullPlacement.Default => true,
            NullPlacement.First => !order.Descending,
            NullPlacement.Last => order.Descending,
            _ => throw new InvalidOperationException($"Unknown NULL placement {order.NullPlacement}."),
        };
    }

    private bool IndexUsesRegisteredFunctions(EmbeddedIndex index)
        => index.Columns.Any(term =>
                term.Expression is not null
                && IndexExpressionSemantics.ContainsFunction(term.Expression, IsRegisteredScalarFunction))
            || index.Where is not null
                && IndexExpressionSemantics.ContainsFunction(index.Where, IsRegisteredScalarFunction);

    private bool IndexUsesOverriddenBuiltInCollation(EmbeddedIndex index, EmbeddedTable table)
        => index.Columns.Any(term =>
            IsOverriddenBuiltInCollation(IndexExpressionSemantics.GetCollationName(table, term)));

    private static bool WhereUsesIndexTerm(
        Expression? expression,
        EmbeddedTable table,
        EmbeddedIndexColumn term)
    {
        if (expression is null)
            return false;
        if (expression is BinaryExpression { Operator: BinaryOperator.And } and)
            return WhereUsesIndexTerm(and.Left, table, term)
                || WhereUsesIndexTerm(and.Right, table, term);
        if (expression is not BinaryExpression binary
            || binary.Operator is not (
                BinaryOperator.Equal
                or BinaryOperator.Is
                or BinaryOperator.LessThan
                or BinaryOperator.LessThanOrEqual
                or BinaryOperator.GreaterThan
                or BinaryOperator.GreaterThanOrEqual))
        {
            return false;
        }

        return QueryExpressionMatchesIndexTerm(binary.Left, table, term)
            || QueryExpressionMatchesIndexTerm(binary.Right, table, term);
    }

    private static bool QueryExpressionMatchesIndexTerm(
        Expression expression,
        EmbeddedTable table,
        EmbeddedIndexColumn term)
    {
        string? queryCollation = null;
        if (expression is CollationExpression collated)
        {
            queryCollation = collated.Name;
            expression = collated.Expression;
        }

        var indexedExpression = term.Expression ?? new ColumnExpression(term.Name);
        if (!IndexExpressionSemantics.ExpressionsEqual(expression, indexedExpression))
            return false;

        queryCollation ??= expression is ColumnExpression column
            && table.TryGetColumnIndex(column.UnqualifiedName ?? column.Name, out var columnIndex)
                ? table.ColumnDefinitions[columnIndex].Collation ?? "BINARY"
                : "BINARY";
        return string.Equals(
            queryCollation,
            IndexExpressionSemantics.GetCollationName(table, term),
            StringComparison.OrdinalIgnoreCase);
    }

    private SourceData GetManagedIndexRows(
        ManagedIndexScanPlan plan,
        QueryContext context,
        SourceRow? outerRow)
    {
        var table = plan.Table;
        var entries = new List<(int Position, SqlValue[] Key)>(table.Rows.Count);
        for (var position = 0; position < table.Rows.Count; position++)
        {
            context.CheckInterrupt();
            var rowId = table.HasRowid ? table.RowIds[position] : (long?)null;
            if (!IndexExpressionSemantics.Qualifies(
                    plan.Index,
                    table,
                    table.Rows[position],
                    rowId,
                    EvaluateIndexExpression))
            {
                continue;
            }

            entries.Add((
                position,
                IndexExpressionSemantics.ProjectKey(
                    plan.Index,
                    table,
                    table.Rows[position],
                    rowId,
                    EvaluateIndexExpression)));
        }

        entries.Sort((left, right) => CompareManagedIndexEntries(table, plan.Index, left, right));
        var qualifier = plan.Source.Alias ?? plan.Source.Name;
        var qualifiedColumns = BuildQualifiedColumns(qualifier, table.Columns);
        var rows = new SourceRow[entries.Count];
        for (var index = 0; index < entries.Count; index++)
        {
            var position = entries[index].Position;
            var rowId = table.HasRowid ? table.RowIds[position] : (long?)null;
            rows[index] = new SourceRow(
                table.Columns,
                table.Rows[position],
                qualifiedColumns,
                outerRow,
                RowId: rowId,
                RowIdQualifier: qualifier,
                ColumnDefinitions: table.ColumnDefinitions,
                QualifiedColumnDefinitions: BuildQualifiedColumnDefinitions(
                    qualifier,
                    table.ColumnDefinitions));
        }

        return new SourceData(table.Columns, rows);
    }

    private int CompareManagedIndexEntries(
        EmbeddedTable table,
        EmbeddedIndex index,
        (int Position, SqlValue[] Key) left,
        (int Position, SqlValue[] Key) right)
    {
        for (var position = 0; position < index.Columns.Count; position++)
        {
            var term = index.Columns[position];
            var comparison = Compare(
                left.Key[position],
                right.Key[position],
                IndexExpressionSemantics.GetCollationName(table, term));
            if (comparison != 0)
                return term.Descending ? -comparison : comparison;
        }

        if (table.HasRowid)
            return table.RowIds[left.Position].CompareTo(table.RowIds[right.Position]);

        var primaryKey = table.PrimaryKeySchema
            ?? throw new InvalidOperationException("WITHOUT ROWID table has no primary-key metadata.");
        foreach (var suffix in primaryKey.Terms)
        {
            var alreadyPresent = index.Columns.Any(term =>
                !term.IsExpression
                && term.ColumnIndex == suffix.ColumnIndex
                && string.Equals(
                    IndexExpressionSemantics.GetCollationName(table, term),
                    suffix.Collation.Name ?? "BINARY",
                    StringComparison.OrdinalIgnoreCase));
            if (alreadyPresent)
                continue;

            var comparison = Compare(
                table.Rows[left.Position][suffix.ColumnIndex],
                table.Rows[right.Position][suffix.ColumnIndex],
                suffix.Collation.Name);
            if (comparison != 0)
            {
                return suffix.SortOrder == SqliteKeySortOrder.Descending
                    ? -comparison
                    : comparison;
            }
        }

        return 0;
    }

    private ExecutionResult ExecuteSelect(
        SelectStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        context.CheckInterrupt();
        statement = BindTableValuedFunctionSources(statement, context);
        ValidateSelectIndexDirectives(statement, context);
        statement = ResolveNamedWindows(statement);
        context = EnterCollationSource(context, statement.Source);
        ValidateGroupByCollations(statement.GroupBy);
        var resolvedOrderBy = ResolveOrderBy(statement.OrderBy, statement.Projections);
        ValidateOrderByCollations(resolvedOrderBy);
        var windowFunctions = CollectSelectWindowFunctions(statement);
        foreach (var function in windowFunctions)
        {
            ValidateWindowFunction(function);
            ValidateOrderByCollations(function.Window!.OrderBy);
            ValidateGroupByCollations(function.Window.PartitionBy);
        }
        var limit = statement.Limit is null
            ? (long?)null
            : RequireLimitInteger(Evaluate(statement.Limit, parameters, outerRow, context));
        var offset = statement.Offset is null
            ? 0
            : Math.Max(0, RequireLimitInteger(Evaluate(statement.Offset, parameters, outerRow, context)));
        // An aggregate nested inside a window call - sum(count(*)) OVER (ORDER BY count(*)) - is
        // evaluated in the aggregate pass just like a top-level one, so it makes this an aggregate
        // query even when nothing outside the window call aggregates.
        var hasAggregate = statement.Projections.Any(projection =>
                ContainsAggregateAcrossWindows(projection.Expression))
            || statement.Having is not null && ContainsAggregate(statement.Having)
            || statement.OrderBy.Any(term => ContainsAggregateAcrossWindows(term.Expression));
        if (statement.Having is not null && !hasAggregate && statement.GroupBy.Count == 0)
            throw new EmbeddedSqlException("HAVING clause on a non-aggregate query");
        var hasWindow = windowFunctions.Count > 0;
        if (statement.Where is not null && ContainsWindowFunction(statement.Where))
            throw new EmbeddedSqlException("misuse of window function in WHERE clause");
        if (statement.GroupBy.Any(ContainsWindowFunction))
            throw new EmbeddedSqlException("misuse of window function in GROUP BY clause");
        if (statement.Having is not null && ContainsWindowFunction(statement.Having))
            throw new EmbeddedSqlException("misuse of window function in HAVING clause");

        // The window pass runs after aggregation, so a window call handed to an aggregate has no
        // pass left to be evaluated in.
        var windowInsideAggregate = statement.Projections
                .Select(projection => FindWindowFunctionInsideAggregate(projection.Expression))
                .FirstOrDefault(candidate => candidate is not null)
            ?? resolvedOrderBy
                .Select(term => FindWindowFunctionInsideAggregate(term.Expression))
                .FirstOrDefault(candidate => candidate is not null);
        if (windowInsideAggregate is not null)
            throw new EmbeddedSqlException($"misuse of window function {windowInsideAggregate.Name}()");
        var sourceColumns = GetSourceColumns(statement.Source, context);
        var outputColumns = GetOutputColumns(statement.Source, context);
        var rawOutputColumns = GetRawOutputColumns(statement.Source, context);
        if (limit == 0)
        {
            ValidateLimitZeroExpressions(statement, sourceColumns, context, outerRow);
            return new ExecutionResult(GetColumnNames(statement.Projections, outputColumns, rawOutputColumns), [], 0);
        }

        var sourceLimit = statement.Where is null
            && !hasAggregate
            && !hasWindow
            && statement.GroupBy.Count == 0
            && statement.OrderBy.Count == 0
            && !statement.Distinct
            && offset == 0
            && limit is >= 0
            ? limit
            : null;
        var indexPlan = TryPlanManagedIndexScan(statement, context);
        var streamProjectionRows = CanStreamProjectionRows(statement, context, outerRow);
        // A managed index plan wins over the transient probe: the index path defines
        // row order (SQLite parity, INDEXED BY), while the probe only prunes a plain scan.
        var source = indexPlan is not null
            ? GetManagedIndexRows(indexPlan, context, outerRow)
            : TryGetTransientLookupRows(
                    statement.Source,
                    statement.Where,
                    parameters,
                    context,
                    outerRow)
                ?? (statement.Source is JoinTableSource joinSource && statement.Where is not null
                    ? GetJoinRowsWithPredicatePushdown(
                        joinSource,
                        statement.Where,
                        parameters,
                        context,
                        sourceLimit,
                        outerRow)
                    : GetSourceRows(statement.Source, parameters, context, sourceLimit, outerRow));
        var selectedRows = new List<SourceRow>();
        foreach (var row in source.Rows)
        {
            context.CheckInterrupt();
            if (streamProjectionRows
                || statement.Where is null
                || IsTrue(Evaluate(statement.Where, parameters, row, context)))
                selectedRows.Add(row);
        }

        var columnNames = GetColumnNames(statement.Projections, outputColumns, rawOutputColumns);
        if (hasWindow)
        {
            // SQLite aggregates first and runs the window pass over the surviving grouped rows, so
            // a frame here sees one row per group rather than the base rows.
            if (hasAggregate || statement.GroupBy.Count > 0)
            {
                return ExecuteGroupedWindowSelect(
                    statement,
                    selectedRows,
                    windowFunctions,
                    columnNames,
                    resolvedOrderBy,
                    offset,
                    limit,
                    parameters,
                    context);
            }

            return ExecuteWindowSelect(
                statement,
                selectedRows,
                windowFunctions,
                columnNames,
                outputColumns,
                offset,
                limit,
                parameters,
                context);
        }

        // A statement whose only aggregates are owned by an enclosing block does not
        // aggregate on its own: SQLite hoists those calls into the enclosing block's
        // aggregate list, leaving this statement to produce ordinary per-row output
        // (possibly zero rows). Fall through to the plain path for that shape so an
        // empty selection stays empty instead of collapsing into one aggregate row.
        var aggregatesHoistedToOuterBlock = hasAggregate
            && statement.GroupBy.Count == 0
            && statement.Having is null
            && context.OuterAggregateScope is not null
            && AllAggregatesProvablyOuterOwned(statement, selectedRows, context);
        if ((hasAggregate || statement.GroupBy.Count > 0) && !aggregatesHoistedToOuterBlock)
        {
            if (statement.GroupBy.Count == 0)
            {
                var representative = GetAggregateRepresentative(statement, selectedRows, parameters, context);
                if (statement.Having is not null
                && !IsTrue(EvaluateAggregate(
                    statement.Having,
                    selectedRows,
                    parameters,
                    context,
                    representative)))
                {
                    return new ExecutionResult(columnNames, [], 0);
                }

                var aggregateValues = statement.Projections
                .Select(projection => EvaluateAggregate(
                    projection.Expression,
                    selectedRows,
                    parameters,
                    context,
                    representative))
                .ToArray();
                return new ExecutionResult(
                    columnNames,
                    ApplyDistinctLimit(
                        [aggregateValues],
                        statement.Distinct,
                        offset,
                        limit,
                        statement.Projections
                            .Select(projection => GetEffectiveCollation(projection.Expression, context))
                            .ToArray()),
                    0);
            }

            var groups = BuildGroups(statement.GroupBy, selectedRows, parameters, context);
            var groupedRows = groups.Select(entry =>
            {
                var group = entry.Rows;
                var representative = GetAggregateRepresentative(statement, group, parameters, context)
                    ?? group[0];
                // Aggregate-bearing projections may reference aggregates owned by this
                // group through nested subqueries (SQLite's aggregate-ownership rule), so
                // evaluate them under a scope exposing this group's rows.
                var groupContext = WithOuterAggregateScope(context, group);
                return new GroupedResult(
                    representative,
                    group,
                    statement.Projections
                        .Select(projection => ContainsAggregate(projection.Expression)
                            ? EvaluateAggregate(
                                projection.Expression,
                                group,
                                parameters,
                                groupContext,
                                representative)
                            : Evaluate(projection.Expression, parameters, representative, groupContext))
                        .ToArray());
            }).ToList();
            if (statement.Having is not null)
            {
                groupedRows.RemoveAll(group => !IsTrue(
                    hasAggregate
                        ? EvaluateAggregate(
                            statement.Having,
                            group.Rows,
                            parameters,
                            WithOuterAggregateScope(context, group.Rows),
                            group.Representative)
                        : Evaluate(
                            statement.Having,
                            parameters,
                            group.Representative,
                            WithOuterAggregateScope(context, group.Rows))));
            }
            if (statement.OrderBy.Count > 0)
            {
                var orderCollations = resolvedOrderBy
                    .Select(term => GetEffectiveCollation(term.Expression, context))
                    .ToArray();
                var orderedGroups = groupedRows
                    .Select((group, index) => new OrderByKeyed<GroupedResult>(
                        group,
                        resolvedOrderBy.Select(term => ContainsAggregate(term.Expression)
                            ? EvaluateAggregate(
                                term.Expression,
                                group.Rows,
                                parameters,
                                WithOuterAggregateScope(context, group.Rows),
                                group.Representative)
                            : Evaluate(
                                term.Expression,
                                parameters,
                                group.Representative,
                                WithOuterAggregateScope(context, group.Rows)))
                            .ToArray(),
                        index))
                    .ToList();
                orderedGroups.Sort((left, right) =>
                {
                    var comparison = CompareOrderKeys(
                        left.Keys,
                        right.Keys,
                        resolvedOrderBy,
                        orderCollations);
                    return comparison != 0
                        ? comparison
                        : left.Position.CompareTo(right.Position);
                });
                groupedRows = orderedGroups.Select(group => group.Item).ToList();
            }
            return new ExecutionResult(
                columnNames,
                ApplyDistinctLimit(
                    groupedRows.Select(group => group.Values),
                    statement.Distinct,
                    offset,
                    limit,
                    statement.Projections
                        .Select(projection => GetEffectiveCollation(projection.Expression, context))
                        .ToArray()),
                0);
        }

        if (statement.OrderBy.Count > 0)
        {
            var orderCollations = resolvedOrderBy
                .Select(term => GetEffectiveCollation(term.Expression, context))
                .ToArray();
            var orderedRows = selectedRows
                .Select((row, index) => new OrderByKeyed<SourceRow>(
                    row,
                    resolvedOrderBy
                        .Select(term => EvaluateOrderByKey(
                            term.Expression,
                            parameters,
                            row,
                            context,
                            outputColumns))
                        .ToArray(),
                    index))
                .ToList();
            orderedRows.Sort((left, right) =>
            {
                var comparison = CompareOrderKeys(
                    left.Keys,
                    right.Keys,
                    resolvedOrderBy,
                    orderCollations);
                // ORDER BY ties follow the scan order the query produced (stable across
                // all key directions), mirroring SQLite's stable sorter over its b-tree
                // scan. A rowid tie-break would contradict the bare scan whenever the
                // managed row store's scan order is not rowid order, breaking consumers
                // (EF Core) that assert ORDER BY ties match a stable sort of the scan.
                return comparison != 0 ? comparison : left.Position.CompareTo(right.Position);
            });
            selectedRows = orderedRows.Select(row => row.Item).ToList();
        }

        if (streamProjectionRows)
        {
            return new ExecutionResult(
                columnNames,
                new StreamingProjectionRows(
                    selectedRows,
                    offset,
                    limit,
                    statement.Where is null
                        ? null
                        : (row, cancellationToken) => IsTrue(Evaluate(
                            statement.Where,
                            parameters,
                            row,
                            context with { CancellationToken = cancellationToken })),
                    (row, cancellationToken) => EvaluateProjectionRow(
                        statement,
                        row,
                        parameters,
                        context with { CancellationToken = cancellationToken },
                        outputColumns,
                        rawOutputColumns)),
                0);
        }

        var resultRows = new List<SqlValue[]>();
        foreach (var row in selectedRows)
            resultRows.Add(EvaluateProjectionRow(statement, row, parameters, context, outputColumns, rawOutputColumns));

        return new ExecutionResult(
            columnNames,
            ApplyDistinctLimit(
                resultRows,
                statement.Distinct,
                offset,
                limit,
                GetDistinctProjectionCollations(
                    statement.Projections,
                    outputColumns,
                    rawOutputColumns,
                    statement.Source,
                    context)),
            0);
    }

    private SqlValue EvaluateOrderByKey(
        Expression expression,
        SqlValue[] parameters,
        SourceRow row,
        QueryContext context,
        IReadOnlyList<OutputColumn> outputColumns)
    {
        if (expression is StarExpression)
        {
            if (outputColumns.Count == 0)
                throw new EmbeddedSqlException("ORDER BY term does not match any column in the result set");

            return GetOutputValue(row, outputColumns[0]);
        }

        return Evaluate(expression, parameters, row, context);
    }

    private bool CanStreamProjectionRows(
        SelectStatement statement,
        QueryContext context,
        SourceRow? outerRow)
    {
        if (outerRow is not null
            || statement.Source is not NamedTableSource named
            || context.CommonTableExpressions.ContainsKey(named.Name)
            || TryGetView(context, named.Name, out _))
        {
            return false;
        }

        return (statement.Where is null || IsScanPredicate(statement.Where))
            && statement.GroupBy.Count == 0
            && statement.Having is null
            && statement.OrderBy.Count == 0
            && !statement.Distinct
            && !statement.Projections.Any(projection =>
                ContainsAggregate(projection.Expression)
                || ContainsWindowFunction(projection.Expression));
    }

    private SqlValue[] EvaluateProjectionRow(
        SelectStatement statement,
        SourceRow row,
        SqlValue[] parameters,
        QueryContext context,
        IReadOnlyList<OutputColumn> outputColumns,
        IReadOnlyList<OutputColumn> rawOutputColumns)
    {
        var values = new List<SqlValue>();
        foreach (var projection in statement.Projections)
        {
            switch (projection.Expression)
            {
                case StarExpression:
                    foreach (var column in outputColumns)
                        values.Add(GetOutputValue(row, column));
                    break;
                case QualifiedStarExpression qualifiedStar:
                    var rawMatches = rawOutputColumns
                        .Where(column => string.Equals(
                            column.Qualifier,
                            qualifiedStar.Qualifier,
                            StringComparison.OrdinalIgnoreCase))
                        .ToArray();
                    if (rawMatches.Length == 0)
                        throw new EmbeddedSqlException($"no such table: {qualifiedStar.Qualifier}");

                    foreach (var raw in rawMatches)
                    {
                        var output = outputColumns.FirstOrDefault(column =>
                            string.Equals(
                                column.Qualifier,
                                qualifiedStar.Qualifier,
                                StringComparison.OrdinalIgnoreCase)
                            && column.Index == raw.Index) ?? raw;
                        values.Add(GetOutputValue(row, output));
                    }

                    break;
                default:
                    values.Add(Evaluate(projection.Expression, parameters, row, context));
                    break;
            }
        }

        return values.ToArray();
    }

    private static IReadOnlyList<string?> GetDistinctProjectionCollations(
        IReadOnlyList<Projection> projections,
        IReadOnlyList<OutputColumn> outputColumns,
        IReadOnlyList<OutputColumn> rawOutputColumns,
        TableSource? source,
        QueryContext context)
    {
        var collations = new List<string?>();
        foreach (var projection in projections)
        {
            switch (projection.Expression)
            {
                case StarExpression:
                    collations.AddRange(outputColumns.Select(column =>
                        NormalizeDeclaredCollation(
                            GetDeclaredOutputColumnCollation(source, column, context))));
                    break;
                case QualifiedStarExpression qualifiedStar:
                    foreach (var raw in rawOutputColumns.Where(raw =>
                                 string.Equals(raw.Qualifier, qualifiedStar.Qualifier, StringComparison.OrdinalIgnoreCase)))
                    {
                        var output = outputColumns.FirstOrDefault(column =>
                            string.Equals(column.Qualifier, qualifiedStar.Qualifier, StringComparison.OrdinalIgnoreCase)
                            && column.Index == raw.Index) ?? raw;
                        collations.Add(NormalizeDeclaredCollation(
                            GetDeclaredOutputColumnCollation(source, output, context)));
                    }

                    break;
                case ColumnExpression column:
                    collations.Add(GetEffectiveCollation(
                        column,
                        EnterCollationSource(context, source)));
                    break;
                default:
                    collations.Add(GetEffectiveCollation(
                        projection.Expression,
                        EnterCollationSource(context, source)));
                    break;
            }
        }

        return collations;
    }

    private static string? GetDeclaredColumnCollation(
        TableSource? source,
        string columnName,
        QueryContext context)
    {
        return TryGetDeclaredColumnCollation(
            source,
            columnName,
            context,
            out var collation)
            ? NormalizeDeclaredCollation(collation)
            : null;
    }

    private static string NormalizeDeclaredCollation(string? collation) =>
        collation ?? "BINARY";

    private static bool TryGetDeclaredColumnCollation(
        TableSource? source,
        string columnName,
        QueryContext context,
        out string? collation)
    {
        var separator = columnName.IndexOf('.');
        var qualifier = separator < 0 ? null : columnName[..separator];
        var name = separator < 0 ? columnName : columnName[(separator + 1)..];
        var column = GetRawOutputColumns(source, context).FirstOrDefault(candidate =>
            string.Equals(candidate.Name, name, StringComparison.OrdinalIgnoreCase)
            && (qualifier is null
                || string.Equals(candidate.Qualifier, qualifier, StringComparison.OrdinalIgnoreCase)));
        if (column is null)
        {
            collation = null;
            return false;
        }

        collation = GetDeclaredOutputColumnCollation(source, column, context);
        return true;
    }

    private static string? GetDeclaredOutputColumnCollation(
        TableSource? source,
        OutputColumn column,
        QueryContext context)
    {
        switch (source)
        {
            case NamedTableSource named when context.CommonTableExpressions.TryGetValue(named.Name, out var commonTableExpression):
                {
                    var qualifier = named.Alias ?? named.Name;
                    if (!string.Equals(column.Qualifier, qualifier, StringComparison.OrdinalIgnoreCase))
                        return null;

                    return column.Index < commonTableExpression.Columns.Length
                        ? commonTableExpression.Collations?.ElementAtOrDefault(column.Index)
                        : null;
                }
            case NamedTableSource named when context.Tables.TryGetValue(named.Name, out var table):
                {
                    var qualifier = named.Alias ?? named.Name;
                    if (!string.Equals(column.Qualifier, qualifier, StringComparison.OrdinalIgnoreCase))
                        return null;

                    for (var index = 0; index < table.Columns.Length; index++)
                    {
                        if (string.Equals(table.Columns[index], column.Name, StringComparison.OrdinalIgnoreCase))
                            return table.ColumnDefinitions[index].Collation;
                    }

                    return null;
                }
            case NamedTableSource named when TryGetView(context, named.Name, out var view):
                {
                    var qualifier = named.Alias ?? view.Name;
                    if (!string.Equals(column.Qualifier, qualifier, StringComparison.OrdinalIgnoreCase))
                        return null;

                    var viewContext = EnterView(context, view.Name);
                    var columns = ResolveViewColumns(view, viewContext);
                    return column.Index >= columns.Length
                        ? null
                        : GetQueryOutputCollations(view.Query, viewContext).ElementAtOrDefault(column.Index);
                }
            case DerivedTableSource derived:
                {
                    if (!string.Equals(column.Qualifier, derived.Alias, StringComparison.OrdinalIgnoreCase))
                        return null;

                    var columns = DescribeQuery(derived.Query, context);
                    return column.Index >= columns.Length
                        ? null
                        : GetQueryOutputCollations(derived.Query, context).ElementAtOrDefault(column.Index);
                }
            case JoinTableSource join:
                {
                    var leftWidth = GetSourceColumns(join.Left, context).Length;
                    return column.Index < leftWidth
                        ? GetDeclaredOutputColumnCollation(join.Left, column, context)
                        : GetDeclaredOutputColumnCollation(
                            join.Right,
                            column with { Index = column.Index - leftWidth },
                            context);
                }
            default:
                return null;
        }
    }

    private static EmbeddedColumn? GetOutputColumnDefinition(
        TableSource? source,
        OutputColumn column,
        QueryContext context)
    {
        switch (source)
        {
            case NamedTableSource named when context.Tables.TryGetValue(named.Name, out var table):
                {
                    var qualifier = named.Alias ?? named.Name;
                    if (!string.Equals(column.Qualifier, qualifier, StringComparison.OrdinalIgnoreCase))
                        return null;
                    for (var index = 0; index < table.Columns.Length; index++)
                    {
                        if (string.Equals(table.Columns[index], column.Name, StringComparison.OrdinalIgnoreCase))
                            return table.ColumnDefinitions[index];
                    }

                    return null;
                }
            case JoinTableSource join:
                {
                    var leftWidth = GetSourceColumns(join.Left, context).Length;
                    return column.Index < leftWidth
                        ? GetOutputColumnDefinition(join.Left, column, context)
                        : GetOutputColumnDefinition(
                            join.Right,
                            column with { Index = column.Index - leftWidth },
                            context);
                }
            default:
                return null;
        }
    }

    private static IReadOnlyList<string?> GetQueryOutputCollations(
        QueryStatement query,
        QueryContext context)
    {
        var memo = context.StatementState?.QueryCollations;
        var key = new CollationMemoKey(query, context.CommonTableExpressions, context.CommonTableExpressions.Count);
        if (memo is not null && memo.TryGetValue(key, out var cached))
            return cached;

        var collations = query switch
        {
            SelectStatement select => GetDistinctProjectionCollations(
                select.Projections,
                GetOutputColumns(select.Source, context),
                GetRawOutputColumns(select.Source, context),
                select.Source,
                context),
            ValuesClause values when values.Rows.Count > 0
                => values.Rows[0].Select(GetCollation).ToArray(),
            CompoundSelectStatement compound when compound.Terms.Count > 0
                => GetQueryOutputCollations(compound.Terms[0], context),
            WithSelectStatement with => GetWithQueryOutputCollations(with, context),
            _ => (IReadOnlyList<string?>)[],
        };
        if (memo is not null)
            memo[key] = collations;
        return collations;
    }

    private static IReadOnlyList<string?> GetWithQueryOutputCollations(
        WithSelectStatement statement,
        QueryContext context)
    {
        var commonTableExpressions = new Dictionary<string, SourceData>(
            context.CommonTableExpressions,
            StringComparer.OrdinalIgnoreCase);
        var namesInCurrentClause = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var commonTableExpression in statement.CommonTableExpressions)
        {
            if (!namesInCurrentClause.Add(commonTableExpression.Name))
                throw new EmbeddedSqlException($"duplicate WITH table name: {commonTableExpression.Name}");

            var cteContext = context with { CommonTableExpressions = commonTableExpressions };
            var columns = ResolveCommonTableExpressionColumns(
                commonTableExpression,
                DescribeQuery(commonTableExpression.Query, cteContext));
            commonTableExpressions[commonTableExpression.Name] = new SourceData(
                columns,
                [],
                GetQueryOutputCollations(commonTableExpression.Query, cteContext));
        }

        return GetQueryOutputCollations(
            statement.Query,
            context with { CommonTableExpressions = commonTableExpressions });
    }

    private void ValidateLimitZeroExpressions(
        SelectStatement statement,
        IReadOnlyList<string> sourceColumns,
        QueryContext context,
        SourceRow? outerRow)
    {
        var qualifiedColumns = statement.Source is null
            ? null
            : GetQualifiedColumns(statement.Source, context);
        var row = new SourceRow(
            sourceColumns.ToArray(),
            Enumerable.Repeat(SqlValue.Null, sourceColumns.Count).ToArray(),
            qualifiedColumns,
            outerRow);

        foreach (var projection in statement.Projections)
            ValidateColumnReferences(projection.Expression, row);
        ValidateColumnReferences(statement.Where, row);
        foreach (var expression in statement.GroupBy)
            ValidateColumnReferences(expression, row);
        ValidateColumnReferences(statement.Having, row);
        foreach (var orderBy in statement.OrderBy)
            ValidateColumnReferences(orderBy.Expression, row);
    }

    private static void ValidateColumnReferences(Expression? expression, SourceRow row)
    {
        if (expression is null)
            return;

        switch (expression)
        {
            case ColumnExpression column:
                row.GetValue(column);
                return;
            case RowValueExpression rowValue:
                foreach (var value in rowValue.Values)
                    ValidateColumnReferences(value, row);
                return;
            case FunctionExpression function:
                foreach (var argument in function.Arguments)
                    ValidateColumnReferences(argument, row);
                ValidateColumnReferences(function.Filter, row);
                if (function.Window is not null)
                {
                    foreach (var partition in function.Window.PartitionBy)
                        ValidateColumnReferences(partition, row);
                    foreach (var orderBy in function.Window.OrderBy)
                        ValidateColumnReferences(orderBy.Expression, row);
                }

                return;
            case CollationExpression collation:
                ValidateColumnReferences(collation.Expression, row);
                return;
            case CastExpression cast:
                ValidateColumnReferences(cast.Expression, row);
                return;
            case CaseExpression @case:
                ValidateColumnReferences(@case.Operand, row);
                foreach (var clause in @case.Clauses)
                {
                    ValidateColumnReferences(clause.When, row);
                    ValidateColumnReferences(clause.Then, row);
                }
                ValidateColumnReferences(@case.Else, row);
                return;
            case LikeExpression like:
                ValidateColumnReferences(like.Value, row);
                ValidateColumnReferences(like.Pattern, row);
                ValidateColumnReferences(like.Escape, row);
                return;
            case GlobExpression glob:
                ValidateColumnReferences(glob.Value, row);
                ValidateColumnReferences(glob.Pattern, row);
                return;
            case InExpression @in:
                ValidateColumnReferences(@in.Value, row);
                foreach (var value in @in.Values)
                    ValidateColumnReferences(value, row);
                return;
            case InSubqueryExpression inSubquery:
                ValidateColumnReferences(inSubquery.Value, row);
                return;
            case BetweenExpression between:
                ValidateColumnReferences(between.Value, row);
                ValidateColumnReferences(between.Lower, row);
                ValidateColumnReferences(between.Upper, row);
                return;
            case UnaryExpression unary:
                ValidateColumnReferences(unary.Operand, row);
                return;
            case BinaryExpression binary:
                ValidateColumnReferences(binary.Left, row);
                ValidateColumnReferences(binary.Right, row);
                return;
            case LiteralExpression or ParameterExpression or StarExpression or QualifiedStarExpression or ScalarSubqueryExpression or ExistsExpression:
                return;
            default:
                throw new EmbeddedSqlException($"Unsupported expression type {expression.GetType().Name}.");
        }
    }

    private ExecutionResult ExecuteCompoundSelect(
        CompoundSelectStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        ValidateCompoundOrderByCollations(statement, context);

        // Route safe uniform UNION/INTERSECT/EXCEPT chains through the bytecode compiler. Metadata comes
        // structurally from the first term, matching the evaluator's fold. Ordered, limited, mixed,
        // callback-capable, cancellable, and otherwise non-lowerable shapes keep the evaluator.
        if (!context.CancellationToken.CanBeCanceled
            && TryCompileCompoundSelect(statement, parameters, context, outerRow, out var compiledCompound))
        {
            var compoundColumns = DescribeQuery(statement.Terms[0], context);
            return RunCompiledProgram(
                compiledCompound,
                compoundColumns,
                BuildValuesBinding(compiledCompound.ParameterIndices ?? [], parameters));
        }

        var first = ExecuteCompoundTerm(statement.Terms[0], parameters, context, outerRow);
        var rows = first.Rows.Select(row => row.ToArray()).ToList();
        var leftCollations = GetQueryOutputCollations(statement.Terms[0], context);
        for (var index = 1; index < statement.Terms.Count; index++)
        {
            var next = ExecuteCompoundTerm(statement.Terms[index], parameters, context, outerRow);
            if (next.Columns.Length != first.Columns.Length)
                throw new EmbeddedSqlException("SELECTs to the left and right of a compound operator do not have the same number of result columns");

            var nextRows = next.Rows.Select(row => row.ToArray()).ToArray();
            var collations = MergeCompoundCollations(
                leftCollations,
                GetQueryOutputCollations(statement.Terms[index], context),
                first.Columns.Length);
            rows = statement.Operators[index - 1] switch
            {
                CompoundOperator.Union => ApplyUnion(rows, nextRows, collations),
                CompoundOperator.UnionAll => [.. rows, .. nextRows],
                CompoundOperator.Intersect => ApplyIntersect(rows, nextRows, collations),
                CompoundOperator.Except => ApplyExcept(rows, nextRows, collations),
                _ => throw new EmbeddedSqlException($"Unsupported compound operator {statement.Operators[index - 1]}."),
            };
            leftCollations = collations;
        }

        if (statement.OrderBy.Count > 0)
            SortCompoundRows(rows, statement, first.Columns, context);

        var limit = statement.Limit is null
            ? (long?)null
            : RequireLimitInteger(Evaluate(statement.Limit, parameters, outerRow, context));
        var offset = statement.Offset is null
            ? 0
            : Math.Max(0, RequireLimitInteger(Evaluate(statement.Offset, parameters, outerRow, context)));
        return new ExecutionResult(first.Columns, ApplyDistinctLimit(rows, distinct: false, offset, limit), 0);
    }

    // Runs a single compound-select term. SELECT keeps the tree-walking evaluator so
    // compound semantics stay identical; VALUES uses the row-set evaluator.
    private ExecutionResult ExecuteCompoundTerm(
        QueryStatement term,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        return term switch
        {
            SelectStatement select => ExecuteSelect(select, parameters, context, outerRow),
            ValuesClause values => ExecuteValues(values, parameters, context, outerRow),
            _ => ExecuteQuery(term, parameters, context, outerRow),
        };
    }

    // Per-output-column collations for a compound; only SELECT terms carry projection
    // collations, so VALUES (and other) terms contribute no collation.
    private static IReadOnlyList<string?> GetCompoundCollations(
        IReadOnlyList<QueryStatement> terms,
        int columnCount,
        QueryContext context)
    {
        var collations = new string?[columnCount];
        foreach (var term in terms)
        {
            var termCollations = GetQueryOutputCollations(term, context);
            for (var index = 0; index < columnCount; index++)
                collations[index] ??= termCollations.ElementAtOrDefault(index);
        }

        return collations;
    }

    private static IReadOnlyList<string?> MergeCompoundCollations(
        IReadOnlyList<string?> left,
        IReadOnlyList<string?> right,
        int columnCount)
    {
        var collations = new string?[columnCount];
        for (var index = 0; index < columnCount; index++)
        {
            collations[index] = left.ElementAtOrDefault(index)
                ?? right.ElementAtOrDefault(index);
        }

        return collations;
    }

    // Routes a top-level source-less VALUES through the bytecode compiler when every cell is a
    // baked literal or a bare bind parameter, running the emitted ValuesProgramBuilder program as a
    // real execution path. Constant cells emit LoadConstant; parameter cells emit LoadParameter and
    // read their value from a late-bound VdbeParameterBinding assembled from the supplied parameter
    // array, so the same compiled program re-executes with fresh parameters without being rebuilt.
    // Its columns are named column1..columnN exactly as the tree-walking evaluator names them.
    // Everything the builder cannot reproduce byte-for-byte keeps the evaluator (see
    // TryCompileValues). Only the top-level statement reaches this cached wrapper; compound terms and
    // bare-star derived tables use the compound lowering, while other derived/subquery/CTE uses remain
    // evaluator-owned.
    private ExecutionResult ExecuteValuesStatement(
        ValuesClause values,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        if (TryPrepareValuesLowering(values, out var lowering))
            return ExecutePreparedValues(lowering, parameters);

        return ExecuteValues(values, parameters, context, outerRow);
    }

    // A cacheable, reusable lowering of an eligible top-level VALUES statement: the immutable compiled
    // program, its dense SQL-index-to-slot map (empty for a constant-only VALUES), and the generated
    // column-name template. A prepared statement builds this once and reuses it across every Reset/rebind,
    // so a routed VALUES no longer recompiles per Execute. Only immutable state is retained -- the
    // VdbeProgram is frozen, the slot map is read-only, and the column template is cloned per execution --
    // so nothing mutable is shared across executions. The lowering depends solely on the immutable parse
    // tree (not on bound values, which are late-bound, nor on the schema catalog, which a VALUES never
    // references), so it stays valid for the life of the prepared statement and never needs invalidation.
    internal sealed class PreparedValuesLowering
    {
        public PreparedValuesLowering(
            CompiledSelect compiled,
            IReadOnlyList<int> slotParameterIndices,
            string[] columns)
        {
            Compiled = compiled;
            SlotParameterIndices = slotParameterIndices;
            Columns = columns;
        }

        public CompiledSelect Compiled { get; }

        public IReadOnlyList<int> SlotParameterIndices { get; }

        public string[] Columns { get; }

        public VdbeProgram Program => Compiled.Program;
    }

    // Attempts to lower an eligible top-level VALUES into a PreparedValuesLowering. Returns false for a
    // fallback shape (any computed cell), which is never cached and keeps the evaluator. The unequal-width
    // diagnostic TryCompileValues raises propagates unchanged, so a width error surfaces at execution time
    // exactly as the evaluator raises it (callers resolve the lowering lazily on first execution).
    internal static bool TryPrepareValuesLowering(ValuesClause values, out PreparedValuesLowering lowering)
    {
        lowering = null!;
        if (!TryCompileValues(values, out var compiled, out var slotParameterIndices))
            return false;

        lowering = new PreparedValuesLowering(compiled, slotParameterIndices, DescribeValues(values));
        return true;
    }

    // Runs a prepared VALUES lowering against the current parameter values: it builds a fresh late-bound
    // binding for the declared slots (so a missing/out-of-range index raises the exact diagnostic the
    // evaluator raises) and executes the reused immutable program in a fresh runtime. The cached column
    // template is cloned per execution so no ExecutionResult shares a mutable array with the cache.
    internal static ExecutionResult ExecutePreparedValues(
        PreparedValuesLowering lowering,
        SqlValue[] parameters)
    {
        var binding = BuildValuesBinding(lowering.SlotParameterIndices, parameters);
        return RunCompiledProgram(lowering.Compiled, (string[])lowering.Columns.Clone(), binding);
    }

    // Lowers a VALUES row list into a ValuesProgramBuilder program, or returns false so the
    // evaluator keeps ownership of every shape the builder cannot lower exactly.
    //
    // Routed through the VDBE (return true) when every cell in every row is either:
    //  - a LiteralExpression, emitted as a baked LoadConstant, or
    //  - a ParameterExpression (SQL ?, ?NNN, or a named :/@/$ placeholder), emitted as a late-bound
    //    LoadParameter. Each distinct SQL parameter index is mapped to a dense zero-based slot in
    //    first-appearance (row-major) order via slotParameterIndices, so slot width stays minimal
    //    and duplicate placeholders -- the same ?NNN number or the same named identity, which the
    //    parser already collapses to one ParameterExpression.Index -- share a slot and therefore a
    //    value, preserving SQLite parameter identity. The generated column names (column1..columnN)
    //    come from DescribeValues, matching the evaluator's own metadata.
    //
    // Deliberately kept on the evaluator (return false):
    //  - any computed cell (arithmetic, function, CAST, CASE, subquery, column reference, ...): its
    //    value, folding, and error timing (e.g. VALUES (1/0), or a correlated column) stay with the
    //    evaluator, so a mixed row with even one computed cell is never lowered.
    //
    // Builder validation maps onto the evaluator's exact diagnostic: a parsed statement always has
    // at least one row and at least one term per row, so an unequal-width literal/parameter VALUES
    // is the only ArgumentException the builder can raise, and it surfaces as the identical
    // "all VALUES must have the same number of terms" the evaluator raises.
    //
    // slotParameterIndices maps each declared parameter slot to the 1-based SQL parameter index whose
    // value binds it; it is empty for a constant-only VALUES (which declares no slots).
    private static bool TryCompileValues(
        ValuesClause values,
        out CompiledSelect compiled,
        out IReadOnlyList<int> slotParameterIndices)
    {
        compiled = null!;
        slotParameterIndices = [];

        var parameterSlots = new Dictionary<int, int>();
        var slotToParameter = new List<int>();
        var cellRows = new List<IReadOnlyList<ValuesCell>>(values.Rows.Count);
        foreach (var row in values.Rows)
        {
            var cells = new ValuesCell[row.Count];
            for (var index = 0; index < row.Count; index++)
            {
                switch (row[index])
                {
                    case LiteralExpression literal:
                        cells[index] = ValuesCell.Constant(literal.Value);
                        break;
                    case ParameterExpression parameter:
                        if (!parameterSlots.TryGetValue(parameter.Index, out var slot))
                        {
                            slot = slotToParameter.Count;
                            parameterSlots.Add(parameter.Index, slot);
                            slotToParameter.Add(parameter.Index);
                        }

                        cells[index] = ValuesCell.Parameter(slot);
                        break;
                    default:
                        return false;
                }
            }

            cellRows.Add(cells);
        }

        VdbeProgram program;
        try
        {
            program = ValuesProgramBuilder.BuildCells(cellRows);
        }
        catch (ArgumentException exception)
        {
            throw new EmbeddedSqlException("all VALUES must have the same number of terms", exception);
        }

        compiled = new CompiledSelect(program, []);
        slotParameterIndices = slotToParameter;
        return true;
    }

    // Assembles the late-bound binding for a routed parameterized VALUES: one value per declared
    // slot, read from the supplied parameter array through ReadParameter so an out-of-range index
    // raises the exact "Missing value for parameter at position N" the evaluator raises. A
    // constant-only VALUES declares no slots and takes the empty binding.
    private static VdbeParameterBinding BuildValuesBinding(
        IReadOnlyList<int> slotParameterIndices,
        SqlValue[] parameters)
    {
        if (slotParameterIndices.Count == 0)
            return VdbeParameterBinding.Empty;

        var slotValues = new SqlValue[slotParameterIndices.Count];
        for (var slot = 0; slot < slotValues.Length; slot++)
            slotValues[slot] = ReadParameter(parameters, slotParameterIndices[slot]);

        return VdbeParameterBinding.FromValues(slotValues);
    }

    // Evaluates a VALUES(...) clause into a result whose columns are named
    // "column1".."columnN". Expressions are evaluated once per row against the current
    // row context so correlated VALUES (e.g. (VALUES(outer_col))) resolve outer columns.
    private ExecutionResult ExecuteValues(
        ValuesClause values,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        var columnCount = values.Rows[0].Count;
        var columns = new string[columnCount];
        for (var index = 0; index < columnCount; index++)
            columns[index] = $"column{index + 1}";

        var rows = new List<SqlValue[]>(values.Rows.Count);
        foreach (var row in values.Rows)
        {
            if (row.Count != columnCount)
                throw new EmbeddedSqlException("all VALUES must have the same number of terms");

            var evaluated = new SqlValue[columnCount];
            for (var index = 0; index < columnCount; index++)
                evaluated[index] = Evaluate(row[index], parameters, outerRow, context);
            rows.Add(evaluated);
        }

        return new ExecutionResult(columns, rows, 0);
    }

    private ExecutionResult ExecuteWithSelect(
        WithSelectStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        if (TryExecuteNotMaterializedPassThrough(
                statement,
                parameters,
                context,
                outerRow,
                out var passThrough))
        {
            return passThrough;
        }

        var cteContext = MaterializeCommonTableExpressions(
            statement.CommonTableExpressions,
            parameters,
            context,
            outerRow);

        return ExecuteQuery(statement.Query, parameters, cteContext, outerRow);
    }

    // NOT MATERIALIZED is advisory in SQLite. The only managed flattening proof is a single
    // nonrecursive CTE consumed by a bare SELECT *: removing that metadata-only outer scan cannot
    // duplicate work, reorder callbacks, or move an error. Every other shape keeps the one-shot
    // materialization boundary, including multiple references, DML, and recursive CTEs.
    private bool TryExecuteNotMaterializedPassThrough(
        WithSelectStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        out ExecutionResult result)
    {
        result = null!;
        if (!TryGetNotMaterializedPassThrough(statement, out var commonTableExpression))
            return false;

        var body = commonTableExpression.Query is ValuesClause values
            ? context.CancellationToken.CanBeCanceled
                ? ExecuteValues(values, parameters, context, outerRow)
                : ExecuteValuesStatement(values, parameters, context, outerRow)
            : ExecuteQuery(commonTableExpression.Query, parameters, context, outerRow);
        body = MaterializeQueryResult(body);
        result = body with
        {
            Columns = ResolveCommonTableExpressionColumns(commonTableExpression, body.Columns),
        };
        return true;
    }

    private ExecutionResult ExecuteWithDml(
        WithDmlStatement statement,
        SqlValue[] parameters,
        QueryContext context)
    {
        ValidateDmlCommonTableExpressionUsage(statement);
        var cteContext = MaterializeCommonTableExpressions(
            statement.CommonTableExpressions,
            parameters,
            context,
            outerRow: null);
        var backup = CloneTablesShallow(context.Tables);
        try
        {
            return statement.Dml switch
            {
                InsertStatement insert => ExecuteInsert(insert, parameters, cteContext),
                UpdateStatement update => ExecuteUpdate(update, parameters, cteContext),
                DeleteStatement delete => ExecuteDelete(delete, parameters, cteContext),
                _ => throw new EmbeddedSqlException("WITH must precede an INSERT, UPDATE, or DELETE statement."),
            };
        }
        catch (EmbeddedConflictFailException)
        {
            throw;
        }
        catch
        {
            RestoreTables(context.Tables, backup);
            throw;
        }
    }

    private static void ValidateDmlCommonTableExpressionUsage(WithDmlStatement statement)
    {
        var names = statement.CommonTableExpressions.Select(commonTableExpression => commonTableExpression.Name).ToArray();
        if (names.Distinct(StringComparer.OrdinalIgnoreCase).Count() != names.Length)
            return;

        var required = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var name in names)
        {
            if (CountDmlReferences(statement.Dml, name) > 0)
                required.Add(name);
        }

        var changed = true;
        while (changed)
        {
            changed = false;
            foreach (var commonTableExpression in statement.CommonTableExpressions)
            {
                if (!required.Contains(commonTableExpression.Name))
                    continue;

                foreach (var name in names)
                {
                    if (CountAllReferences(commonTableExpression.Query, name) > 0)
                        changed |= required.Add(name);
                }
            }
        }

        var unused = names.FirstOrDefault(name => !required.Contains(name));
        if (unused is not null)
        {
            throw new EmbeddedSqlException(
                $"Managed CTE DML requires every CTE to contribute to the DML statement; {unused} is unused.");
        }
    }

    private QueryContext MaterializeCommonTableExpressions(
        IReadOnlyList<CommonTableExpression> expressions,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        var resolvedExpressions = new Dictionary<string, SourceData>(
            context.CommonTableExpressions,
            StringComparer.OrdinalIgnoreCase);
        var namesInCurrentClause = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var commonTableExpression in expressions)
        {
            if (!namesInCurrentClause.Add(commonTableExpression.Name))
                throw new EmbeddedSqlException($"duplicate WITH table name: {commonTableExpression.Name}");

            var cteContext = context with { CommonTableExpressions = resolvedExpressions };
            var resolved = CountAllReferences(commonTableExpression.Query, commonTableExpression.Name) > 0
                ? EvaluateRecursiveCte(commonTableExpression, parameters, cteContext, outerRow)
                : EvaluateNonRecursiveCte(commonTableExpression, parameters, cteContext, outerRow);
            resolvedExpressions[commonTableExpression.Name] = resolved;
        }

        return context with { CommonTableExpressions = resolvedExpressions };
    }

    private SourceData EvaluateNonRecursiveCte(
        CommonTableExpression commonTableExpression,
        SqlValue[] parameters,
        QueryContext cteContext,
        SourceRow? outerRow)
    {
        var result = MaterializeQueryResult(
            ExecuteQuery(commonTableExpression.Query, parameters, cteContext, outerRow));
        var columns = ResolveCommonTableExpressionColumns(commonTableExpression, result.Columns);
        return new SourceData(
            columns,
            result.Rows.Select(row => new SourceRow(columns, row.ToArray())).ToArray(),
            GetQueryOutputCollations(commonTableExpression.Query, cteContext));
    }

    // Safety cap on the number of rows a recursive CTE may materialize. SQLite streams
    // results and relies on the query eventually terminating; because this engine
    // materializes eagerly, a runaway UNION ALL recursion (or a genuinely non-terminating
    // query that SQLite would also loop on forever) is bounded here so it fails loudly
    // instead of exhausting memory. The cap is far above any legitimately supported query.
    private const int RecursiveCteRowLimit = 100_000;

    // Evaluates a recursive common table expression using semi-naive (working-set)
    // iteration: run the anchor once, then repeatedly run the recursive term(s) over only
    // the rows produced by the previous step until no new rows appear. UNION deduplicates
    // (which also terminates cycles); UNION ALL keeps every row.
    private SourceData EvaluateRecursiveCte(
        CommonTableExpression commonTableExpression,
        SqlValue[] parameters,
        QueryContext cteContext,
        SourceRow? outerRow)
    {
        var name = commonTableExpression.Name;
        if (commonTableExpression.Query is not CompoundSelectStatement compound)
            throw new EmbeddedSqlException($"circular reference: {name}");

        var firstRecursiveIndex = -1;
        for (var index = 0; index < compound.Terms.Count; index++)
        {
            if (CountAllReferences(compound.Terms[index], name) > 0)
            {
                firstRecursiveIndex = index;
                break;
            }
        }

        // A recursive reference with no preceding anchor (including a recursive first term)
        // has nothing to seed the iteration and matches SQLite's "circular reference".
        if (firstRecursiveIndex <= 0)
            throw new EmbeddedSqlException($"circular reference: {name}");

        // The operator joining the anchor block to the recursive block, and every operator
        // between recursive terms, must be a uniform UNION or UNION ALL.
        var recursiveOperator = compound.Operators[firstRecursiveIndex - 1];
        if (recursiveOperator is not (CompoundOperator.Union or CompoundOperator.UnionAll))
            throw new EmbeddedSqlException($"circular reference: {name}");
        for (var index = firstRecursiveIndex; index < compound.Operators.Count; index++)
        {
            if (compound.Operators[index] != recursiveOperator)
                throw new EmbeddedSqlException("recursive table may not use mixed UNION and UNION ALL operators");
        }

        var recursiveTerms = new List<SelectStatement>();
        for (var index = firstRecursiveIndex; index < compound.Terms.Count; index++)
        {
            var term = ValidateRecursiveTerm(compound.Terms[index], name);
            recursiveTerms.Add(term);
        }

        var anchor = MaterializeQueryResult(
            EvaluateRecursiveAnchor(compound, firstRecursiveIndex, parameters, cteContext, outerRow));
        var columns = ResolveCommonTableExpressionColumns(commonTableExpression, anchor.Columns);
        var collations = GetQueryOutputCollations(commonTableExpression.Query, cteContext);
        var deduplicate = recursiveOperator == CompoundOperator.Union;
        var anchorsRoutable = AreRecursiveAnchorsRoutable(
            compound,
            firstRecursiveIndex,
            parameters,
            cteContext,
            outerRow);

        // Route one safe recursive SELECT through generation expansion. Evaluating the term once over each
        // complete working set preserves joined-source order and recursive-term DISTINCT, while callback,
        // custom-collation, cancellable, multi-term, ordered-compound, and unbounded-shape boundaries stay
        // on the evaluator below.
        if (recursiveTerms.Count == 1
            && !cteContext.CancellationToken.CanBeCanceled
            && anchor.Rows.Count >= 1
            && anchor.Rows.Count <= RecursiveCteRowLimit
            && compound.OrderBy.Count == 0
            && compound.Limit is null
            && compound.Offset is null
            && anchorsRoutable
            && collations.All(IsStreamingSafeDistinctCollation)
            && IsRoutableRecursiveTerm(recursiveTerms[0], name, cteContext))
        {
            return RunRecursiveCteViaVdbe(
                name,
                anchor.Rows,
                columns,
                collations,
                recursiveTerms[0],
                deduplicate,
                parameters,
                cteContext,
                outerRow);
        }

        var result = new List<SourceRow>();
        var seen = deduplicate ? new List<SqlValue[]>() : null;
        var workingSet = new List<SourceRow>();
        foreach (var row in anchor.Rows)
        {
            var values = row.ToArray();
            if (seen is not null && !TryAddRecursiveDistinctRow(seen, values, collations))
                continue;

            var sourceRow = new SourceRow(columns, values);
            result.Add(sourceRow);
            workingSet.Add(sourceRow);
        }

        while (workingSet.Count > 0)
        {
            var iterationContext = cteContext with
            {
                CommonTableExpressions = new Dictionary<string, SourceData>(
                    cteContext.CommonTableExpressions,
                    StringComparer.OrdinalIgnoreCase)
                {
                    [name] = new SourceData(columns, workingSet, collations),
                },
            };

            var produced = new List<SourceRow>();
            foreach (var term in recursiveTerms)
            {
                var termResult = MaterializeQueryResult(
                    ExecuteSelect(term, parameters, iterationContext, outerRow));
                if (termResult.Columns.Length != columns.Length)
                    throw new EmbeddedSqlException("SELECTs to the left and right of a compound operator do not have the same number of result columns");

                foreach (var row in termResult.Rows)
                {
                    var values = row.ToArray();
                    if (seen is not null && !TryAddRecursiveDistinctRow(seen, values, collations))
                        continue;

                    var sourceRow = new SourceRow(columns, values);
                    result.Add(sourceRow);
                    produced.Add(sourceRow);
                    if (result.Count > RecursiveCteRowLimit)
                        throw new EmbeddedSqlException(
                            $"recursive query for {name} exceeded the maximum of {RecursiveCteRowLimit} rows");
                }
            }

            workingSet = produced;
        }

        return new SourceData(columns, result, collations);
    }

    private static bool IsRoutableRecursiveTerm(
        SelectStatement term,
        string name,
        QueryContext context)
    {
        if (term.OrderBy.Count != 0
            || !IsRoutableRecursiveSource(term.Source, name, context)
            || !AreRoutableRecursiveJoinConditions(term.Source)
            || term.Projections.Any(projection => !IsRoutableRecursiveExpression(projection.Expression))
            || (term.Where is not null && !IsRoutableRecursiveExpression(term.Where)))
        {
            return false;
        }

        return true;
    }

    private static bool IsRoutableRecursiveSource(
        TableSource? source,
        string name,
        QueryContext context)
    {
        return source switch
        {
            NamedTableSource named when string.Equals(
                named.Name,
                name,
                StringComparison.OrdinalIgnoreCase) => true,
            NamedTableSource named when context.Tables.TryGetValue(named.Name, out var table)
                => table.ColumnDefinitions.All(definition =>
                    IsStreamingSafeDistinctCollation(definition.Collation)),
            JoinTableSource
            {
                Kind: JoinKind.Inner,
                Natural: false,
                UsingColumns: null,
            } join => IsRoutableRecursiveSource(join.Left, name, context)
                && IsRoutableRecursiveSource(join.Right, name, context),
            _ => false,
        };
    }

    private static bool AreRoutableRecursiveJoinConditions(TableSource? source)
    {
        return source switch
        {
            JoinTableSource join => (join.Condition is null
                    || IsRoutableRecursiveExpression(join.Condition))
                && AreRoutableRecursiveJoinConditions(join.Left)
                && AreRoutableRecursiveJoinConditions(join.Right),
            _ => true,
        };
    }

    // Functions, subqueries, pattern operators, and custom collations remain evaluator-owned because
    // they can invoke callbacks or raise errors from code the recursive worktable cannot introspect.
    private static bool IsRoutableRecursiveExpression(Expression expression)
    {
        return expression switch
        {
            LiteralExpression or ParameterExpression or ColumnExpression
                or StarExpression or QualifiedStarExpression => true,
            CollationExpression collation => IsStreamingSafeDistinctCollation(collation.Name)
                && IsRoutableRecursiveExpression(collation.Expression),
            CastExpression cast => IsRoutableRecursiveExpression(cast.Expression),
            CaseExpression @case => (@case.Operand is null
                    || IsRoutableRecursiveExpression(@case.Operand))
                && @case.Clauses.All(clause =>
                    IsRoutableRecursiveExpression(clause.When)
                    && IsRoutableRecursiveExpression(clause.Then))
                && (@case.Else is null || IsRoutableRecursiveExpression(@case.Else)),
            BetweenExpression between => IsRoutableRecursiveExpression(between.Value)
                && IsRoutableRecursiveExpression(between.Lower)
                && IsRoutableRecursiveExpression(between.Upper),
            InExpression @in => IsRoutableRecursiveExpression(@in.Value)
                && @in.Values.All(IsRoutableRecursiveExpression),
            UnaryExpression unary => IsRoutableRecursiveExpression(unary.Operand),
            BinaryExpression binary => IsRoutableRecursiveExpression(binary.Left)
                && IsRoutableRecursiveExpression(binary.Right),
            _ => false,
        };
    }

    // Runs a routed recursive CTE on the resumable state machine and materializes its result as a
    // SourceData whose columns are the CTE's resolved columns -- byte-identical to what the tree-walking
    // loop produces, but with the FIFO Step/generation-expand recursion executing as real, observably looping
    // bytecode. The row guard surfaces as the evaluator's own "exceeded the maximum" diagnostic so a
    // runaway UNION ALL fails with the identical message whether it routed or not.
    private SourceData RunRecursiveCteViaVdbe(
        string name,
        IReadOnlyList<SqlValue[]> anchorRows,
        string[] columns,
        IReadOnlyList<string?> collations,
        SelectStatement recursiveTerm,
        bool deduplicate,
        SqlValue[] parameters,
        QueryContext cteContext,
        SourceRow? outerRow)
    {
        var program = BuildRecursiveCteProgram(
            name, anchorRows, columns, collations, recursiveTerm, deduplicate, parameters, cteContext, outerRow);

        var rows = new List<SourceRow>();
        try
        {
            using var runtime = new ResumableStatement(program);
            while (true)
            {
                switch (runtime.StepResumable())
                {
                    case ResumableStatementStepResult.Row:
                        rows.Add(new SourceRow(columns, MaterializeQueryRow(runtime.CurrentRow!)));
                        break;
                    case ResumableStatementStepResult.Done:
                        return new SourceData(columns, rows, collations);
                    default:
                        throw new EmbeddedSqlException("Recursive program yielded during evaluation.");
                }
            }
        }
        catch (RecursiveWorkTableOverflowException)
        {
            throw new EmbeddedSqlException(
                $"recursive query for {name} exceeded the maximum of {RecursiveCteRowLimit} rows");
        }
    }

    // Lowers a recursive CTE onto a RecursiveCteProgramBuilder program: anchor rows become the constant seed
    // generation and the recursive SELECT becomes a generation transform. Binding the CTE to the complete
    // frontier and invoking ExecuteSelect once preserves evaluator projection, join, DISTINCT, NULL,
    // collation, correlation, and source-order semantics rather than re-deriving them in the executor.
    // Both guards are pinned to the evaluator's row cap: the row guard reproduces its "exceeded the maximum"
    // bound (seeds count as admitted rows exactly as anchors count toward the loop's result), and the depth
    // guard is set to the same cap so it can never fire before the row guard (a chain of depth d needs more
    // than d admitted rows), leaving termination to de-duplication, the row cap, or the transform running dry
    // -- exactly as the tree-walking loop terminates.
    private VdbeProgram BuildRecursiveCteProgram(
        string name,
        IReadOnlyList<SqlValue[]> anchorRows,
        string[] columns,
        IReadOnlyList<string?> collations,
        SelectStatement recursiveTerm,
        bool deduplicate,
        SqlValue[] parameters,
        QueryContext cteContext,
        SourceRow? outerRow)
    {
        var width = columns.Length;

        // One dictionary/context is reused across expansions; each synchronous call replaces only the
        // CTE's current generation before ExecuteSelect consumes it.
        var iterationTables = new Dictionary<string, SourceData>(
            cteContext.CommonTableExpressions, StringComparer.OrdinalIgnoreCase);
        var iterationContext = cteContext with { CommonTableExpressions = iterationTables };

        IReadOnlyList<SqlValue[]> Transform(IReadOnlyList<SqlValue[]> frontierRows)
        {
            var workingSet = new SourceRow[frontierRows.Count];
            for (var index = 0; index < frontierRows.Count; index++)
                workingSet[index] = new SourceRow(columns, frontierRows[index]);
            iterationTables[name] = new SourceData(
                columns,
                workingSet,
                collations);
            var termResult = MaterializeQueryResult(
                ExecuteSelect(recursiveTerm, parameters, iterationContext, outerRow));
            if (termResult.Columns.Length != width)
            {
                throw new EmbeddedSqlException(
                    "SELECTs to the left and right of a compound operator do not have the same number of result columns");
            }

            var children = new SqlValue[termResult.Rows.Count][];
            for (var index = 0; index < termResult.Rows.Count; index++)
                children[index] = MaterializeQueryRow(termResult.Rows[index]);

            return children;
        }

        if (deduplicate)
        {
            return RecursiveCteProgramBuilder.BuildUnionDistinctGenerations(
                anchorRows,
                Transform,
                (left, right) => RecursiveRowsEqual(left, right, collations),
                RecursiveCteRowLimit,
                RecursiveCteRowLimit);
        }

        return RecursiveCteProgramBuilder.BuildUnionAllGenerations(
            anchorRows, Transform, RecursiveCteRowLimit, RecursiveCteRowLimit);
    }

    private bool TryAddRecursiveDistinctRow(
        List<SqlValue[]> seen,
        SqlValue[] candidate,
        IReadOnlyList<string?> collations)
    {
        if (seen.Any(existing => RecursiveRowsEqual(existing, candidate, collations)))
            return false;

        seen.Add(candidate);
        return true;
    }

    private bool RecursiveRowsEqual(
        IReadOnlyList<SqlValue> left,
        IReadOnlyList<SqlValue> right,
        IReadOnlyList<string?> collations)
    {
        if (left.Count != right.Count || left.Count != collations.Count)
            return false;

        for (var index = 0; index < left.Count; index++)
        {
            if (!DistinctValuesEqual(left[index], right[index], collations[index]))
                return false;
        }

        return true;
    }

    // Structural analysis of a recursive CTE body used only by EXPLAIN: returns true (with the single
    // recursive term, the anchor/recursive split point, and whether the operator de-duplicates) exactly
    // when the body is the routable linear shape. It mirrors EvaluateRecursiveCte's validation as pure
    // predicates -- it never throws -- so any non-routable or malformed shape simply declines and EXPLAIN
    // falls through to its standard "only lowered statements" error instead of a bytecode dump.
    private bool TryAnalyzeLinearRecursiveCte(
        CompoundSelectStatement compound,
        string name,
        QueryContext context,
        out SelectStatement recursiveTerm,
        out int firstRecursiveIndex,
        out bool deduplicate)
    {
        recursiveTerm = null!;
        firstRecursiveIndex = -1;
        deduplicate = false;

        for (var index = 0; index < compound.Terms.Count; index++)
        {
            if (CountAllReferences(compound.Terms[index], name) > 0)
            {
                firstRecursiveIndex = index;
                break;
            }
        }

        // Need at least one anchor term before the recursive block, exactly one recursive term (the last),
        // no compound-level ORDER BY/LIMIT/OFFSET, and a uniform UNION or UNION ALL operator chain.
        if (firstRecursiveIndex <= 0
            || compound.Terms.Count - firstRecursiveIndex != 1
            || compound.OrderBy.Count != 0
            || compound.Limit is not null
            || compound.Offset is not null)
        {
            return false;
        }

        var recursiveOperator = compound.Operators[firstRecursiveIndex - 1];
        if (recursiveOperator is not (CompoundOperator.Union or CompoundOperator.UnionAll))
            return false;
        for (var index = firstRecursiveIndex; index < compound.Operators.Count; index++)
        {
            if (compound.Operators[index] != recursiveOperator)
                return false;
        }

        if (compound.Terms[firstRecursiveIndex] is not SelectStatement select
            || !IsRoutableRecursiveTerm(select, name, context)
            || CountDirectFromReferences(select.Source, name) != 1
            || CountAllReferences(select, name) != 1
            || select.GroupBy.Count > 0
            || select.Having is not null
            || select.Limit is not null
            || select.Offset is not null
            || select.Projections.Any(projection => ContainsAggregate(projection.Expression))
            || CollectSelectWindowFunctions(select).Count > 0)
        {
            return false;
        }

        recursiveTerm = select;
        deduplicate = recursiveOperator == CompoundOperator.Union;
        return true;
    }

    // Whether a query is a bare `SELECT * FROM <name>` with no DISTINCT, WHERE, GROUP BY/HAVING, WINDOW,
    // ORDER BY, or LIMIT/OFFSET -- the pass-through outer query whose output is exactly the CTE's
    // materialized rows, so a recursive-worktable program is a faithful whole-statement lowering EXPLAIN
    // may describe.
    private static bool IsBareSelectStarFrom(QueryStatement query, string name)
        => query is SelectStatement select
            && !select.Distinct
            && select.Projections.Count == 1
            && select.Projections[0].Expression is StarExpression
            && select.Where is null
            && select.GroupBy.Count == 0
            && select.Having is null
            && select.NamedWindows.Count == 0
            && select.OrderBy.Count == 0
            && select.Limit is null
            && select.Offset is null
            && select.Source is NamedTableSource named
            && string.Equals(named.Name, name, StringComparison.OrdinalIgnoreCase);

    private static bool TryGetNotMaterializedPassThrough(
        WithSelectStatement statement,
        out CommonTableExpression commonTableExpression)
    {
        commonTableExpression = null!;
        if (statement.CommonTableExpressions.Count != 1)
            return false;

        var candidate = statement.CommonTableExpressions[0];
        if (candidate.MaterializationHint != CteMaterializationHint.NotMaterialized
            || CountAllReferences(candidate.Query, candidate.Name) != 0
            || !IsBareSelectStarFrom(statement.Query, candidate.Name))
        {
            return false;
        }

        commonTableExpression = candidate;
        return true;
    }

    // Produces a faithful program for the route selected by the pass-through execution path. MATERIALIZED and
    // unspecified CTEs never reach this method, so their optimization fence remains visible as an
    // evaluator fallback in EXPLAIN QUERY PLAN.
    private bool TryBuildNotMaterializedPassThroughExplainProgram(
        WithSelectStatement statement,
        SqlValue[] parameters,
        QueryContext context,
        out VdbeProgram program)
    {
        program = null!;
        if (context.CancellationToken.CanBeCanceled
            || !TryGetNotMaterializedPassThrough(statement, out var commonTableExpression))
        {
            return false;
        }

        ResolveCommonTableExpressionColumns(
            commonTableExpression,
            DescribeQuery(commonTableExpression.Query, context));

        CompiledSelect compiled;
        switch (commonTableExpression.Query)
        {
            case SelectStatement select:
                var indexPlan = TryPlanManagedIndexScan(select, context);
                if (indexPlan is not null)
                {
                    if (!TryCompileManagedIndexSelect(
                            select,
                            indexPlan,
                            parameters,
                            context,
                            outerRow: null,
                            materializeIndexRows: false,
                            out compiled))
                    {
                        return false;
                    }
                }
                else if (!TryCompileSelect(select, parameters, context, outerRow: null, out compiled))
                {
                    return false;
                }
                break;
            case CompoundSelectStatement compound:
                if (!TryCompileCompoundSelect(
                        compound,
                        parameters,
                        context,
                        outerRow: null,
                        out compiled))
                {
                    return false;
                }
                break;
            case ValuesClause values:
                if (!TryCompileValues(values, out compiled, out _))
                    return false;
                break;
            default:
                return false;
        }

        program = compiled.Program;
        return true;
    }

    // EXPLAIN lowering for the routed recursive-CTE subset. Only a WITH whose single common table
    // expression is a routable linear recursion and whose outer query is a bare `SELECT * FROM cte` is
    // described, so the emitted worktable program's ResultRows are exactly the statement's output rows and
    // the dump is a faithful whole-statement lowering. Every other shape declines so EXPLAIN keeps
    // reporting only genuinely lowered programs.
    private bool TryBuildRecursiveCteExplainProgram(
        WithSelectStatement with,
        SqlValue[] parameters,
        QueryContext context,
        out VdbeProgram program)
    {
        program = null!;
        if (context.CancellationToken.CanBeCanceled
            || with.CommonTableExpressions.Count != 1)
            return false;

        var cte = with.CommonTableExpressions[0];
        if (!IsBareSelectStarFrom(with.Query, cte.Name)
            || CountAllReferences(cte.Query, cte.Name) == 0
            || cte.Query is not CompoundSelectStatement compound
            || !TryAnalyzeLinearRecursiveCte(
                compound,
                cte.Name,
                context,
                out var recursiveTerm,
                out var firstRecursiveIndex,
                out var deduplicate))
        {
            return false;
        }

        var cteContext = context with
        {
            CommonTableExpressions = new Dictionary<string, SourceData>(
                context.CommonTableExpressions, StringComparer.OrdinalIgnoreCase),
        };

        if (!AreRecursiveAnchorsRoutable(
                compound,
                firstRecursiveIndex,
                parameters,
                cteContext,
                outerRow: null))
        {
            return false;
        }

        var anchor = EvaluateRecursiveAnchor(compound, firstRecursiveIndex, parameters, cteContext, outerRow: null);

        // Only describe when the anchor is non-empty and within the row guard and the declared column count
        // matches, i.e. exactly the shapes the execution path would route without raising a shape error.
        if (anchor.Rows.Count < 1
            || anchor.Rows.Count > RecursiveCteRowLimit
            || (cte.Columns is not null && cte.Columns.Count != anchor.Columns.Length))
        {
            return false;
        }

        var columns = ResolveCommonTableExpressionColumns(cte, anchor.Columns);
        var collations = GetQueryOutputCollations(cte.Query, cteContext);
        if (collations.Any(collation => !IsStreamingSafeDistinctCollation(collation)))
            return false;
        program = BuildRecursiveCteProgram(
            cte.Name,
            anchor.Rows,
            columns,
            collations,
            recursiveTerm,
            deduplicate,
            parameters,
            cteContext,
            outerRow: null);
        return true;
    }

    private bool AreRecursiveAnchorsRoutable(
        CompoundSelectStatement compound,
        int firstRecursiveIndex,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        for (var index = 0; index < firstRecursiveIndex; index++)
        {
            if (!TryCompileCompoundTerm(
                    compound.Terms[index],
                    parameters,
                    context,
                    outerRow,
                    out var compiledAnchor)
                || !IsConservativeCompoundTerm(compiledAnchor.Program))
            {
                return false;
            }
        }

        return true;
    }

    // Evaluates the anchor block (all terms before the first recursive term). A single
    // anchor term runs directly; multiple anchors run as their own compound so their
    // UNION/INTERSECT/EXCEPT semantics are preserved.
    private ExecutionResult EvaluateRecursiveAnchor(
        CompoundSelectStatement compound,
        int firstRecursiveIndex,
        SqlValue[] parameters,
        QueryContext cteContext,
        SourceRow? outerRow)
    {
        if (firstRecursiveIndex == 1)
            return ExecuteCompoundTerm(compound.Terms[0], parameters, cteContext, outerRow);

        var anchor = new CompoundSelectStatement(
            compound.Terms.Take(firstRecursiveIndex).ToArray(),
            compound.Operators.Take(firstRecursiveIndex - 1).ToArray(),
            [],
            null,
            null);
        return ExecuteCompoundSelect(anchor, parameters, cteContext, outerRow);
    }

    // Validates a single recursive term and returns it as a SELECT. Rejects constructs
    // SQLite forbids in a recursive term with the same messages it produces.
    private SelectStatement ValidateRecursiveTerm(QueryStatement term, string name)
    {
        if (term is not SelectStatement select)
            throw new EmbeddedSqlException($"circular reference: {name}");

        var directReferences = CountDirectFromReferences(select.Source, name);
        var allReferences = CountAllReferences(select, name);
        if (directReferences > 1)
            throw new EmbeddedSqlException($"multiple references to recursive table: {name}");

        // Any reference that is not a single top-level FROM entry (e.g. inside a subquery,
        // a derived table, or joined to itself) is not a supported linear recursion.
        if (directReferences != 1 || allReferences != 1)
            throw new EmbeddedSqlException($"circular reference: {name}");

        if (select.GroupBy.Count > 0
            || select.Having is not null
            || select.Projections.Any(projection => ContainsAggregate(projection.Expression)))
        {
            throw new EmbeddedSqlException("recursive aggregate queries not supported");
        }

        if (CollectSelectWindowFunctions(select).Count > 0)
            throw new EmbeddedSqlException("cannot use window functions in recursive queries");
        if (select.Limit is not null || select.Offset is not null)
            throw new EmbeddedSqlException("LIMIT and OFFSET are not supported in recursive queries");

        return select;
    }

    // Counts references to a CTE name that appear as a table in the top level of a FROM
    // clause (walking only the join tree, never descending into derived tables/subqueries).
    private static int CountDirectFromReferences(TableSource? source, string name)
    {
        return source switch
        {
            null => 0,
            NamedTableSource named => string.Equals(named.Name, name, StringComparison.OrdinalIgnoreCase) ? 1 : 0,
            JoinTableSource join => CountDirectFromReferences(join.Left, name) + CountDirectFromReferences(join.Right, name),
            _ => 0,
        };
    }

    private static int CountDmlReferences(ParsedStatement statement, string name)
    {
        return statement switch
        {
            InsertStatement insert => insert.Rows.Sum(row => row.Sum(expression => CountReferencesInExpression(expression, name)))
                + (insert.Source is null ? 0 : CountAllReferences(insert.Source, name))
                + (insert.Returning?.Sum(projection => CountReferencesInExpression(projection.Expression, name)) ?? 0),
            UpdateStatement update => update.Assignments.Sum(assignment => CountReferencesInExpression(assignment.Value, name))
                + (update.From is null ? 0 : CountReferencesInTableSource(update.From, name))
                + (update.Where is null ? 0 : CountReferencesInExpression(update.Where, name))
                + update.EffectiveOrderBy.Sum(term => CountReferencesInExpression(term.Expression, name))
                + (update.Limit is null ? 0 : CountReferencesInExpression(update.Limit, name))
                + (update.Offset is null ? 0 : CountReferencesInExpression(update.Offset, name))
                + (update.Returning?.Sum(projection => CountReferencesInExpression(projection.Expression, name)) ?? 0),
            DeleteStatement delete => (delete.Where is null ? 0 : CountReferencesInExpression(delete.Where, name))
                + delete.EffectiveOrderBy.Sum(term => CountReferencesInExpression(term.Expression, name))
                + (delete.Limit is null ? 0 : CountReferencesInExpression(delete.Limit, name))
                + (delete.Offset is null ? 0 : CountReferencesInExpression(delete.Offset, name))
                + (delete.Returning?.Sum(projection => CountReferencesInExpression(projection.Expression, name)) ?? 0),
            _ => 0,
        };
    }

    // Deep count of references to a CTE name anywhere in a query, including derived tables
    // and subquery expressions. A nested WITH that redefines the name shadows it, so
    // references beneath such a clause are not counted.
    private static int CountAllReferences(QueryStatement query, string name)
    {
        switch (query)
        {
            case SelectStatement select:
                var count = CountReferencesInTableSource(select.Source, name);
                if (select.Where is not null)
                    count += CountReferencesInExpression(select.Where, name);
                count += select.Projections.Sum(projection => CountReferencesInExpression(projection.Expression, name));
                count += select.GroupBy.Sum(expression => CountReferencesInExpression(expression, name));
                if (select.Having is not null)
                    count += CountReferencesInExpression(select.Having, name);
                count += select.OrderBy.Sum(term => CountReferencesInExpression(term.Expression, name));
                if (select.Limit is not null)
                    count += CountReferencesInExpression(select.Limit, name);
                if (select.Offset is not null)
                    count += CountReferencesInExpression(select.Offset, name);
                return count;
            case CompoundSelectStatement compound:
                return compound.Terms.Sum(term => CountAllReferences(term, name));
            case ValuesClause values:
                return values.Rows.Sum(row => row.Sum(expression => CountReferencesInExpression(expression, name)));
            case WithSelectStatement with:
                if (with.CommonTableExpressions.Any(cte => string.Equals(cte.Name, name, StringComparison.OrdinalIgnoreCase)))
                    return 0;
                return with.CommonTableExpressions.Sum(cte => CountAllReferences(cte.Query, name))
                    + CountAllReferences(with.Query, name);
            default:
                return 0;
        }
    }

    private static int CountReferencesInTableSource(TableSource? source, string name)
    {
        return source switch
        {
            null => 0,
            NamedTableSource named => string.Equals(named.Name, name, StringComparison.OrdinalIgnoreCase) ? 1 : 0,
            DerivedTableSource derived => CountAllReferences(derived.Query, name),
            JoinTableSource join => CountReferencesInTableSource(join.Left, name)
                + CountReferencesInTableSource(join.Right, name)
                + (join.Condition is null ? 0 : CountReferencesInExpression(join.Condition, name)),
            _ => 0,
        };
    }

    private static int CountReferencesInExpression(Expression expression, string name)
    {
        return expression switch
        {
            ScalarSubqueryExpression subquery => CountAllReferences(subquery.Query, name),
            ExistsExpression exists => CountAllReferences(exists.Query, name),
            InSubqueryExpression inSubquery => CountReferencesInExpression(inSubquery.Value, name)
                + CountAllReferences(inSubquery.Query, name),
            FunctionExpression function => function.Arguments.Sum(argument => CountReferencesInExpression(argument, name))
                + (function.Filter is null ? 0 : CountReferencesInExpression(function.Filter, name)),
            RowValueExpression rowValue => rowValue.Values.Sum(value => CountReferencesInExpression(value, name)),
            BinaryExpression binary => CountReferencesInExpression(binary.Left, name)
                + CountReferencesInExpression(binary.Right, name),
            UnaryExpression unary => CountReferencesInExpression(unary.Operand, name),
            CollationExpression collation => CountReferencesInExpression(collation.Expression, name),
            CastExpression cast => CountReferencesInExpression(cast.Expression, name),
            CaseExpression @case => (@case.Operand is null ? 0 : CountReferencesInExpression(@case.Operand, name))
                + @case.Clauses.Sum(clause => CountReferencesInExpression(clause.When, name) + CountReferencesInExpression(clause.Then, name))
                + (@case.Else is null ? 0 : CountReferencesInExpression(@case.Else, name)),
            LikeExpression like => CountReferencesInExpression(like.Value, name)
                + CountReferencesInExpression(like.Pattern, name)
                + (like.Escape is null ? 0 : CountReferencesInExpression(like.Escape, name)),
            GlobExpression glob => CountReferencesInExpression(glob.Value, name)
                + CountReferencesInExpression(glob.Pattern, name),
            InExpression @in => CountReferencesInExpression(@in.Value, name)
                + @in.Values.Sum(value => CountReferencesInExpression(value, name)),
            BetweenExpression between => CountReferencesInExpression(between.Value, name)
                + CountReferencesInExpression(between.Lower, name)
                + CountReferencesInExpression(between.Upper, name),
            _ => 0,
        };
    }

    private static string[] ResolveCommonTableExpressionColumns(
        CommonTableExpression commonTableExpression,
        IReadOnlyList<string> resultColumns)
    {
        if (commonTableExpression.Columns is null)
            return resultColumns.ToArray();
        if (commonTableExpression.Columns.Count != resultColumns.Count)
        {
            throw new EmbeddedSqlException(
                $"table {commonTableExpression.Name} has {resultColumns.Count} values for {commonTableExpression.Columns.Count} columns");
        }

        return commonTableExpression.Columns.ToArray();
    }

    private List<SqlValue[]> ApplyUnion(
        IReadOnlyList<SqlValue[]> left,
        IReadOnlyList<SqlValue[]> right,
        IReadOnlyList<string?> collations)
    {
        var result = new List<SqlValue[]>(left.Count + right.Count);
        AddDistinctRows(result, left, collations);
        AddDistinctRows(result, right, collations);
        return result;
    }

    private List<SqlValue[]> ApplyIntersect(
        IReadOnlyList<SqlValue[]> left,
        IReadOnlyList<SqlValue[]> right,
        IReadOnlyList<string?> collations)
    {
        var result = new List<SqlValue[]>();
        foreach (var row in left)
        {
            if (result.Any(candidate => RowsEqual(candidate, row, collations))
                || !right.Any(candidate => RowsEqual(candidate, row, collations)))
                continue;

            result.Add(row.ToArray());
        }

        return result;
    }

    private List<SqlValue[]> ApplyExcept(
        IReadOnlyList<SqlValue[]> left,
        IReadOnlyList<SqlValue[]> right,
        IReadOnlyList<string?> collations)
    {
        var result = new List<SqlValue[]>();
        foreach (var row in left)
        {
            if (result.Any(candidate => RowsEqual(candidate, row, collations))
                || right.Any(candidate => RowsEqual(candidate, row, collations)))
                continue;

            result.Add(row.ToArray());
        }

        return result;
    }

    private void AddDistinctRows(
        List<SqlValue[]> destination,
        IEnumerable<SqlValue[]> source,
        IReadOnlyList<string?> collations)
    {
        foreach (var row in source)
        {
            if (!destination.Any(candidate => RowsEqual(candidate, row, collations)))
                destination.Add(row.ToArray());
        }
    }

    private bool RowsEqual(
        IReadOnlyList<SqlValue> left,
        IReadOnlyList<SqlValue> right,
        IReadOnlyList<string?>? collations = null)
    {
        if (left.Count != right.Count)
            return false;

        for (var index = 0; index < left.Count; index++)
        {
            if (left[index].Kind == SqlValueKind.Null || right[index].Kind == SqlValueKind.Null)
            {
                if (left[index].Kind != right[index].Kind)
                    return false;
                continue;
            }

            if (Compare(left[index], right[index], collations?[index]) != 0)
                return false;
        }

        return true;
    }

    private void SortCompoundRows(
        List<SqlValue[]> rows,
        CompoundSelectStatement statement,
        IReadOnlyList<string> columns,
        QueryContext context)
    {
        var outputCollations = GetQueryOutputCollations(statement.Terms[0], context);
        var orderBy = statement.OrderBy.Select(term =>
        {
            var index = ResolveCompoundOrderByIndex(term, statement.Terms, columns);
            // An explicit ORDER BY collation overrides the result expression's collation.
            // Projection collations only exist on SELECT terms; a leading VALUES term has none.
            var projectionCollation = outputCollations.ElementAtOrDefault(index);
            return (index, term, GetCollation(term.Expression) ?? projectionCollation);
        }).ToArray();
        // Sort an ordinal array instead of the row list: List.Sort is unstable, so a
        // comparer returning 0 would scramble ties. Ties keep compound materialization
        // order (arm order, then within-arm scan order) — the same relative order native
        // SQLite's stable sorter preserves over its ephemeral compound table.
        var order = new int[rows.Count];
        for (var index = 0; index < order.Length; index++)
            order[index] = index;

        Array.Sort(order, (left, right) =>
        {
            var leftRow = rows[left];
            var rightRow = rows[right];
            foreach (var term in orderBy)
            {
                var comparison = CompareForOrdering(
                    leftRow[term.index],
                    rightRow[term.index],
                    term.term,
                    term.Item3);
                if (comparison == 0)
                    continue;

                return comparison;
            }

            return left.CompareTo(right);
        });

        var sorted = new List<SqlValue[]>(rows.Count);
        foreach (var index in order)
            sorted.Add(rows[index]);

        rows.Clear();
        rows.AddRange(sorted);
    }

    private void ValidateCompoundOrderByCollations(
        CompoundSelectStatement statement,
        QueryContext context)
    {
        if (statement.OrderBy.Count == 0)
            return;

        var columns = DescribeQuery(statement.Terms[0], context);
        var outputCollations = GetQueryOutputCollations(statement.Terms[0], context);
        foreach (var term in statement.OrderBy)
        {
            var index = ResolveCompoundOrderByIndex(term, statement.Terms, columns);
            ValidateCollation(GetCollation(term.Expression) ?? outputCollations.ElementAtOrDefault(index));
        }
    }

    private static int ResolveCompoundOrderByIndex(
        OrderByTerm orderBy,
        IReadOnlyList<QueryStatement> terms,
        IReadOnlyList<string> columns)
    {
        var expression = orderBy.Expression;
        if (orderBy.Ordinal is { } ordinal)
        {
            if (ordinal >= 1 && ordinal <= columns.Count)
                return (int)ordinal - 1;

            throw new EmbeddedSqlException(
                $"ORDER BY position {ordinal} is out of range for {columns.Count} result columns");
        }

        var reference = UnwrapCollation(expression);
        var selectTerms = terms.OfType<SelectStatement>().ToArray();
        if (reference is ColumnExpression column)
        {
            for (var index = 0; index < columns.Count; index++)
            {
                if (string.Equals(columns[index], column.Name, StringComparison.OrdinalIgnoreCase))
                    return index;
            }

            foreach (var term in selectTerms)
            {
                for (var index = 0; index < term.Projections.Count; index++)
                {
                    if (string.Equals(term.Projections[index].Alias, column.Name, StringComparison.OrdinalIgnoreCase))
                        return index;
                }
            }
        }

        foreach (var term in selectTerms)
        {
            for (var index = 0; index < term.Projections.Count; index++)
            {
                if (term.Projections[index].Expression.Equals(expression)
                    || term.Projections[index].Expression.Equals(reference))
                    return index;
            }
        }

        throw new EmbeddedSqlException("ORDER BY term does not match any column in the result set");
    }

    private SqlValue[][] ApplyDistinctLimit(
        IEnumerable<SqlValue[]> source,
        bool distinct,
        long offset,
        long? limit,
        IReadOnlyList<string?>? collations = null)
    {
        var rows = source.ToList();
        if (distinct)
        {
            var distinctRows = new List<SqlValue[]>(rows.Count);
            foreach (var row in rows)
            {
                if (!distinctRows.Any(candidate => RowsEqual(candidate, row, collations)))
                    distinctRows.Add(row);
            }

            rows = distinctRows;
        }

        if (offset >= rows.Count)
            return [];
        if (offset > 0)
            rows.RemoveRange(0, (int)offset);
        if (limit is >= 0 && limit.Value < rows.Count)
            rows.RemoveRange((int)limit.Value, rows.Count - (int)limit.Value);

        return rows.ToArray();
    }

    private SqlValue[] EvaluateGroupKey(
        IReadOnlyList<Expression> groupBy,
        SqlValue[] parameters,
        SourceRow row,
        QueryContext context)
    {
        var key = new SqlValue[groupBy.Count];
        for (var index = 0; index < key.Length; index++)
        {
            context.CheckInterrupt();
            key[index] = Evaluate(groupBy[index], parameters, row, context);
        }

        return key;
    }

    private static string[] GetSourceColumns(TableSource? source, QueryContext context)
    {
        return source switch
        {
            null => [],
            NamedTableSource named when IsSchemaTable(named.Name) => ["type", "name", "tbl_name", "rootpage", "sql"],
            NamedTableSource named when context.CommonTableExpressions.TryGetValue(named.Name, out var commonTableExpression)
                => commonTableExpression.Columns,
            NamedTableSource named when TryGetView(context, named.Name, out var view)
                => ResolveViewColumns(view, EnterView(context, view.Name)),
            NamedTableSource named when TryBindBareTableValuedFunction(named, context, out var bare)
                => GetSourceColumns(bare, context),
            NamedTableSource named => GetTable(named, context.Tables).Columns,
            TableValuedFunctionSource function
                => [.. TableValuedFunctionRegistry.Resolve(function.Name).Schema.AllColumns],
            DerivedTableSource derived => DescribeQuery(derived.Query, context),
            JoinTableSource join => GetSourceColumns(join.Left, context)
                .Concat(GetSourceColumns(join.Right, context))
                .ToArray(),
            _ => throw new EmbeddedSqlException($"Unsupported table source {source.GetType().Name}."),
        };
    }

    private static IReadOnlyList<OutputColumn> GetOutputColumns(TableSource? source, QueryContext context)
    {
        switch (source)
        {
            case null:
                return [];
            case NamedTableSource named when IsSchemaTable(named.Name):
                return BuildOutputColumns(named.Alias ?? named.Name, ["type", "name", "tbl_name", "rootpage", "sql"]);
            case NamedTableSource named when context.CommonTableExpressions.TryGetValue(named.Name, out var commonTableExpression):
                return BuildOutputColumns(named.Alias ?? named.Name, commonTableExpression.Columns);
            case NamedTableSource named when TryGetView(context, named.Name, out var view):
                return BuildOutputColumns(named.Alias ?? view.Name, ResolveViewColumns(view, EnterView(context, view.Name)));
            case NamedTableSource named when TryBindBareTableValuedFunction(named, context, out var bare):
                return GetOutputColumns(bare, context);
            case NamedTableSource named:
                return BuildOutputColumns(named.Alias ?? named.Name, GetTable(named, context.Tables).Columns);
            case TableValuedFunctionSource function:
                return BuildOutputColumns(
                    function.Alias ?? function.Name,
                    TableValuedFunctionRegistry.Resolve(function.Name).Schema.VisibleColumns);
            case DerivedTableSource derived:
                return BuildOutputColumns(derived.Alias, DescribeQuery(derived.Query, context));
            case JoinTableSource join:
                return GetJoinOutputColumns(join, context);
            default:
                throw new EmbeddedSqlException($"Unsupported table source {source.GetType().Name}.");
        }
    }

    private static IReadOnlyList<OutputColumn> GetRawOutputColumns(TableSource? source, QueryContext context)
    {
        if (source is not JoinTableSource join)
            return GetOutputColumns(source, context);

        var left = GetRawOutputColumns(join.Left, context);
        var leftWidth = GetSourceColumns(join.Left, context).Length;
        var right = GetRawOutputColumns(join.Right, context);
        return left.Concat(right.Select(column => column with { Index = column.Index + leftWidth })).ToArray();
    }

    private static IReadOnlyList<OutputColumn> BuildOutputColumns(string? qualifier, IReadOnlyList<string> columns)
    {
        var result = new OutputColumn[columns.Count];
        for (var index = 0; index < columns.Count; index++)
            result[index] = new OutputColumn(qualifier, columns[index], index);

        return result;
    }

    private static IReadOnlyList<OutputColumn> GetJoinOutputColumns(JoinTableSource join, QueryContext context)
    {
        var left = GetOutputColumns(join.Left, context);
        var right = GetOutputColumns(join.Right, context);
        var leftWidth = GetSourceColumns(join.Left, context).Length;

        IReadOnlyList<string> coalescedNames;
        if (join.UsingColumns is { } usingColumns)
        {
            foreach (var name in usingColumns)
            {
                if (!left.Any(column => string.Equals(column.Name, name, StringComparison.OrdinalIgnoreCase))
                    || !right.Any(column => string.Equals(column.Name, name, StringComparison.OrdinalIgnoreCase)))
                {
                    throw new EmbeddedSqlException($"cannot join using column {name} - column not present in both tables");
                }
            }

            coalescedNames = usingColumns;
        }
        else if (join.Natural)
        {
            var rightNames = new HashSet<string>(right.Select(column => column.Name), StringComparer.OrdinalIgnoreCase);
            coalescedNames = left.Where(column => rightNames.Contains(column.Name)).Select(column => column.Name).ToArray();
        }
        else
        {
            coalescedNames = [];
        }

        var result = new List<OutputColumn>(left.Count + right.Count);
        if (coalescedNames.Count == 0)
        {
            result.AddRange(left);
            foreach (var column in right)
            {
                result.Add(column with
                {
                    Index = column.Index + leftWidth,
                    CoalesceIndex = column.CoalesceIndex is { } coalesceIndex
                        ? coalesceIndex + leftWidth
                        : null,
                    AdditionalCoalesceIndices = ShiftCoalesceIndices(
                        column.AdditionalCoalesceIndices,
                        leftWidth),
                });
            }

            return result;
        }

        var coalescedSet = new HashSet<string>(coalescedNames, StringComparer.OrdinalIgnoreCase);
        foreach (var column in left)
        {
            if (coalescedSet.Contains(column.Name))
            {
                var match = right.First(candidate => string.Equals(candidate.Name, column.Name, StringComparison.OrdinalIgnoreCase));
                var rightIndices = new List<int> { match.Index + leftWidth };
                if (match.CoalesceIndex is { } matchCoalesce)
                    rightIndices.Add(matchCoalesce + leftWidth);
                if (match.AdditionalCoalesceIndices is not null)
                {
                    rightIndices.AddRange(match.AdditionalCoalesceIndices.Select(index => index + leftWidth));
                }

                if (column.CoalesceIndex is null)
                {
                    result.Add(column with
                    {
                        CoalesceIndex = rightIndices[0],
                        AdditionalCoalesceIndices = rightIndices.Count == 1
                            ? column.AdditionalCoalesceIndices
                            : [
                                .. column.AdditionalCoalesceIndices ?? [],
                                .. rightIndices.Skip(1),
                            ],
                    });
                }
                else
                {
                    result.Add(column with
                    {
                        AdditionalCoalesceIndices =
                        [
                            .. column.AdditionalCoalesceIndices ?? [],
                            .. rightIndices,
                        ],
                    });
                }
            }
            else
            {
                result.Add(column);
            }
        }

        foreach (var column in right)
        {
            if (!coalescedSet.Contains(column.Name))
            {
                result.Add(column with
                {
                    Index = column.Index + leftWidth,
                    CoalesceIndex = column.CoalesceIndex is { } coalesceIndex
                        ? coalesceIndex + leftWidth
                        : null,
                    AdditionalCoalesceIndices = ShiftCoalesceIndices(
                        column.AdditionalCoalesceIndices,
                        leftWidth),
                });
            }
        }

        return result;
    }

    private static IReadOnlyList<int>? ShiftCoalesceIndices(
        IReadOnlyList<int>? indices,
        int offset)
        => indices is null ? null : indices.Select(index => index + offset).ToArray();

    private SourceData GetSourceRows(
        TableSource? source,
        SqlValue[] parameters,
        QueryContext context,
        long? maximumRows,
        SourceRow? outerRow)
    {
        if (source is null)
            return new SourceData([], [new SourceRow([], [], Parent: outerRow)]);

        return source switch
        {
            NamedTableSource named when context.CommonTableExpressions.TryGetValue(named.Name, out var commonTableExpression)
                => GetCommonTableExpressionRows(named, commonTableExpression, outerRow, maximumRows),
            NamedTableSource named when TryGetView(context, named.Name, out var view)
                => GetViewRows(named, view, parameters, context, maximumRows, outerRow),
            NamedTableSource { IndexDirective: IndexedByDirective } named
                => GetManagedIndexRows(
                    CreateForcedIndexScanPlan(
                        named,
                        GetTable(named, context.Tables),
                        where: null),
                    context,
                    outerRow),
            NamedTableSource named when TryBindBareTableValuedFunction(named, context, out var bare)
                => GetSourceRows(bare, parameters, context, maximumRows, outerRow),
            NamedTableSource named => GetNamedTableRows(named, context, maximumRows, outerRow),
            TableValuedFunctionSource function => GetTableValuedFunctionRows(
                function,
                parameters,
                context,
                maximumRows,
                outerRow),
            DerivedTableSource derived => GetDerivedTableRows(derived, parameters, context, outerRow, maximumRows),
            JoinTableSource join => GetJoinRows(join, parameters, context, maximumRows, outerRow),
            _ => throw new EmbeddedSqlException($"Unsupported table source {source.GetType().Name}."),
        };
    }

    // Pushes WHERE conjuncts that reference only one side of an inner join down to that side,
    // so the nested loop (and hash index) run over pre-filtered row sets. The full WHERE is
    // still evaluated on the join output, so this is purely a performance rewrite; it is only
    // valid for inner joins, where (L sigma) join (R sigma) == sigma (L join R).
    private SourceData GetJoinRowsWithPredicatePushdown(
        JoinTableSource source,
        Expression where,
        SqlValue[] parameters,
        QueryContext context,
        long? maximumRows,
        SourceRow? outerRow)
    {
        var (leftPredicate, rightPredicate) = SplitJoinSidePredicates(where, source, context);

        // Push a WHERE conjunct into a join side's scans only when that side is preserved by
        // the join: INNER (and CROSS, which parses as INNER) may push both sides, LEFT may
        // push only its left side, RIGHT only its right side, and FULL neither. Pushing a
        // conjunct into the null-supplying side would drop the padded rows and silently turn
        // the outer join into an inner one. The full WHERE is re-applied to the join output,
        // so a pushed conjunct is at worst a harmless duplicate.
        var leftPush = source.Kind is JoinKind.Inner or JoinKind.Left ? leftPredicate : null;
        var rightPush = source.Kind is JoinKind.Inner or JoinKind.Right ? rightPredicate : null;
        return leftPush is null && rightPush is null
            ? GetJoinRows(source, parameters, context, maximumRows, outerRow)
            : GetJoinRows(
                source,
                parameters,
                context,
                maximumRows,
                outerRow,
                leftPush,
                rightPush);
    }

    private static (Expression? Left, Expression? Right) SplitJoinSidePredicates(
        Expression where,
        JoinTableSource join,
        QueryContext context)
    {
        var leftColumns = GetOutputColumns(join.Left, context);
        var rightColumns = GetOutputColumns(join.Right, context);
        List<Expression>? leftConjuncts = null;
        List<Expression>? rightConjuncts = null;
        var pending = new Stack<Expression>();
        pending.Push(where);
        while (pending.Count > 0)
        {
            var conjunct = pending.Pop();
            if (conjunct is BinaryExpression { Operator: BinaryOperator.And } and)
            {
                pending.Push(and.Left);
                pending.Push(and.Right);
                continue;
            }

            switch (ClassifyJoinSidePredicate(conjunct, leftColumns, rightColumns))
            {
                case JoinSidePredicate.Left:
                    (leftConjuncts ??= []).Add(conjunct);
                    break;
                case JoinSidePredicate.Right:
                    (rightConjuncts ??= []).Add(conjunct);
                    break;
            }
        }

        static Expression? Combine(List<Expression>? conjuncts)
        {
            if (conjuncts is null)
                return null;
            var combined = conjuncts[0];
            for (var index = 1; index < conjuncts.Count; index++)
                combined = new BinaryExpression(combined, BinaryOperator.And, conjuncts[index]);
            return combined;
        }

        return (Combine(leftConjuncts), Combine(rightConjuncts));
    }

    private enum JoinSidePredicate
    {
        None,
        Left,
        Right,
    }

    private static JoinSidePredicate ClassifyJoinSidePredicate(
        Expression conjunct,
        IReadOnlyList<OutputColumn> leftColumns,
        IReadOnlyList<OutputColumn> rightColumns)
    {
        var sawLeft = false;
        var sawRight = false;
        var pending = new Stack<Expression>();
        pending.Push(conjunct);
        while (pending.Count > 0)
        {
            switch (pending.Pop())
            {
                case ColumnExpression { BooleanKeyword: null } column:
                    var onLeft = ResolveJoinSideColumn(column, leftColumns) is not null;
                    var onRight = ResolveJoinSideColumn(column, rightColumns) is not null;
                    if (onLeft && onRight)
                        return JoinSidePredicate.None;
                    sawLeft |= onLeft;
                    sawRight |= onRight;
                    break;
                case ColumnExpression:
                case LiteralExpression:
                case ParameterExpression:
                    break;
                case BinaryExpression binary:
                    pending.Push(binary.Left);
                    pending.Push(binary.Right);
                    break;
                case UnaryExpression unary:
                    pending.Push(unary.Operand);
                    break;
                case CastExpression cast:
                    pending.Push(cast.Expression);
                    break;
                case CollationExpression collation:
                    pending.Push(collation.Expression);
                    break;
                case BetweenExpression between:
                    pending.Push(between.Value);
                    pending.Push(between.Lower);
                    pending.Push(between.Upper);
                    break;
                case LikeExpression like:
                    pending.Push(like.Value);
                    pending.Push(like.Pattern);
                    if (like.Escape is not null)
                        pending.Push(like.Escape);
                    break;
                case GlobExpression glob:
                    pending.Push(glob.Value);
                    pending.Push(glob.Pattern);
                    break;
                case InExpression inExpression:
                    pending.Push(inExpression.Value);
                    foreach (var value in inExpression.Values)
                        pending.Push(value);
                    break;
                case CaseExpression caseExpression:
                    if (caseExpression.Operand is not null)
                        pending.Push(caseExpression.Operand);
                    foreach (var clause in caseExpression.Clauses)
                    {
                        pending.Push(clause.When);
                        pending.Push(clause.Then);
                    }

                    if (caseExpression.Else is not null)
                        pending.Push(caseExpression.Else);
                    break;
                case RowValueExpression rowValue:
                    foreach (var value in rowValue.Values)
                        pending.Push(value);
                    break;
                default:
                    // Functions, subqueries, CURRENT_* and anything else not on the
                    // deterministic allowlist stays out of the pushed predicate.
                    return JoinSidePredicate.None;
            }
        }

        if (sawLeft && sawRight)
            return JoinSidePredicate.None;
        if (sawLeft)
            return JoinSidePredicate.Left;
        return sawRight ? JoinSidePredicate.Right : JoinSidePredicate.None;
    }

    private SourceData FilterSourceRows(
        SourceData data,
        Expression predicate,
        SqlValue[] parameters,
        QueryContext context)
    {
        var rows = new List<SourceRow>(data.Rows.Count);
        foreach (var row in data.Rows)
        {
            context.CheckInterrupt();
            if (IsTrue(Evaluate(predicate, parameters, row, context)))
                rows.Add(row);
        }

        return new SourceData(data.Columns, rows);
    }

    // Narrow a plain table scan through a statement-cached hash probe when the
    // filtering predicate equates a scan column to a scan-constant expression
    // (literals, parameters, outer-row references). Correlated subqueries re-run
    // their scans once per outer row; the cached lookup turns each re-run from a
    // full table scan into an O(matches) probe. The probed rows are unfiltered -
    // every predicate still runs through the normal evaluation path downstream -
    // so this only ever prunes rows that provably cannot match.
    private SourceData GetSourceRowsWithTransientIndex(
        TableSource source,
        Expression? predicate,
        SqlValue[] parameters,
        QueryContext context,
        long? maximumRows,
        SourceRow? outerRow)
    {
        var probed = TryGetTransientLookupRows(source, predicate, parameters, context, outerRow);
        return probed ?? GetSourceRows(source, parameters, context, maximumRows, outerRow);
    }

    // Returns the probed rows when the scan can use a transient lookup - including an
    // empty result when the probe matches nothing - or null when the scan shape is not
    // eligible and the caller must fall back to a plain scan.
    private SourceData? TryGetTransientLookupRows(
        TableSource? source,
        Expression? predicate,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        if (source is not NamedTableSource named
            || predicate is null
            || context.StatementState is not { } statementState
            || IsSchemaTable(named.Name)
            || context.CommonTableExpressions.ContainsKey(named.Name)
            || context.Views?.ContainsKey(named.Name) == true
            || !context.Tables.TryGetValue(named.Name, out var table)
            || !TryCreateTransientEqualityLookup(named, table, predicate, context, out var lookup))
        {
            return null;
        }

        var probeValue = Evaluate(lookup.ValueExpression, parameters, outerRow, context);
        if (probeValue.Kind is SqlValueKind.Null)
        {
            // SQL equality against NULL never holds, so no row can match.
            return new SourceData(table.Columns, []);
        }

        var affinity = GetJoinKeyAffinity(lookup.ColumnDefinition);
        var normalized = affinity is null
            ? probeValue
            : EmbeddedTable.ApplyColumnAffinity(affinity.Value, probeValue);
        var key = EquiJoinHashIndex.CanonicalizeJoinKeyValue(
            normalized,
            convertTextToNumeric: false,
            convertNumericToText: false,
            lookup.Collation);
        if (key is null)
            return new SourceData(table.Columns, []);

        var lookups = statementState.TransientLookups;
        var cacheKey = new TransientLookupKey(table, lookup.ColumnOrdinal, lookup.Collation);
        if (!lookups.TryGetValue(cacheKey, out var transient))
        {
            transient = new TransientLookup();
            lookups[cacheKey] = transient;
        }

        if (transient.Revision != table.Rows.Revision)
        {
            transient.Buckets.Clear();
            for (var position = 0; position < table.Rows.Count; position++)
            {
                context.CheckInterrupt();
                var segment = EquiJoinHashIndex.CanonicalizeJoinKeyValue(
                    table.Rows[position][lookup.ColumnOrdinal],
                    convertTextToNumeric: false,
                    convertNumericToText: false,
                    lookup.Collation);
                if (segment is null)
                    continue;
                if (!transient.Buckets.TryGetValue(segment, out var bucket))
                {
                    bucket = [];
                    transient.Buckets[segment] = bucket;
                }

                bucket.Add(position);
            }

            transient.Revision = table.Rows.Revision;
        }

        if (!transient.Buckets.TryGetValue(key, out var positions) || positions.Count == 0)
            return new SourceData(table.Columns, []);

        var qualifier = named.Alias ?? named.Name;
        var qualifiedColumns = BuildQualifiedColumns(qualifier, table.Columns);
        var qualifiedColumnDefinitions = BuildQualifiedColumnDefinitions(
            qualifier,
            table.ColumnDefinitions);
        var rows = new SourceRow[positions.Count];
        for (var index = 0; index < positions.Count; index++)
        {
            var position = positions[index];
            rows[index] = new SourceRow(
                table.Columns,
                table.Rows[position],
                qualifiedColumns,
                outerRow,
                RowId: table.HasRowid ? table.RowIds[position] : null,
                RowIdQualifier: qualifier,
                ColumnDefinitions: table.ColumnDefinitions,
                QualifiedColumnDefinitions: qualifiedColumnDefinitions);
        }

        return new SourceData(table.Columns, rows);
    }

    private sealed record TransientEqualityLookup(
        int ColumnOrdinal,
        EmbeddedColumn? ColumnDefinition,
        string Collation,
        Expression ValueExpression);

    // Finds the first AND-conjunct of <paramref name="predicate"/> that equates a column of
    // the scanned table to a scan-constant expression, with a hashable collation.
    private bool TryCreateTransientEqualityLookup(
        NamedTableSource source,
        EmbeddedTable table,
        Expression predicate,
        QueryContext context,
        [System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out TransientEqualityLookup? lookup)
    {
        var outputColumns = GetOutputColumns(source, context);
        var pending = new Stack<Expression>();
        pending.Push(predicate);
        while (pending.Count > 0)
        {
            var conjunct = pending.Pop();
            if (conjunct is BinaryExpression { Operator: BinaryOperator.And } and)
            {
                pending.Push(and.Left);
                pending.Push(and.Right);
                continue;
            }

            if (conjunct is BinaryExpression { Operator: BinaryOperator.Equal } equal
                && (TryMatchTransientEquality(equal.Left, equal.Right, source, table, outputColumns, out lookup)
                    || TryMatchTransientEquality(equal.Right, equal.Left, source, table, outputColumns, out lookup)))
            {
                return true;
            }
        }

        lookup = null;
        return false;
    }

    private bool TryMatchTransientEquality(
        Expression columnSide,
        Expression valueSide,
        NamedTableSource source,
        EmbeddedTable table,
        IReadOnlyList<OutputColumn> outputColumns,
        [System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out TransientEqualityLookup? lookup)
    {
        lookup = null;
        string? explicitCollation = null;
        if (columnSide is CollationExpression collatedColumn)
        {
            explicitCollation = collatedColumn.Name;
            columnSide = collatedColumn.Expression;
        }

        string? valueCollation = null;
        if (valueSide is CollationExpression collatedValue)
        {
            valueCollation = collatedValue.Name;
            valueSide = collatedValue.Expression;
        }

        if (columnSide is not ColumnExpression { BooleanKeyword: null } column
            || ResolveJoinSideColumn(column, outputColumns) is null
            || !table.TryGetColumnIndex(column.UnqualifiedName ?? column.Name, out var ordinal)
            || !IsScanConstantExpression(valueSide, outputColumns))
        {
            return false;
        }

        if (explicitCollation is not null
            && valueCollation is not null
            && !string.Equals(explicitCollation, valueCollation, StringComparison.OrdinalIgnoreCase))
        {
            // Conflicting explicit collations: leave the comparison error to the evaluator.
            return false;
        }

        var collation = explicitCollation
            ?? valueCollation
            ?? table.ColumnDefinitions[ordinal].Collation
            ?? "BINARY";
        // Hashing assumes built-in collation semantics; a registered override (or any
        // custom collation) compares differently, so leave those rows on the evaluator.
        if (!IsHashableJoinKeyCollation(collation) || IsUnsafeCompiledCollation(collation))
            return false;

        lookup = new TransientEqualityLookup(
            ordinal,
            table.ColumnDefinitions[ordinal],
            collation.ToUpperInvariant(),
            valueSide);
        return true;
    }

    // Scan-constant means the expression's value cannot change between rows of this
    // scan: literals, parameters, outer-row columns and deterministic compositions of
    // those. Functions and subqueries are excluded because evaluating them once per
    // scan instead of once per row could change results (non-deterministic built-ins).
    private static bool IsScanConstantExpression(
        Expression expression,
        IReadOnlyList<OutputColumn> scanColumns)
    {
        var pending = new Stack<Expression>();
        pending.Push(expression);
        while (pending.Count > 0)
        {
            switch (pending.Pop())
            {
                case ColumnExpression { BooleanKeyword: null } column:
                    if (ResolveJoinSideColumn(column, scanColumns) is not null)
                        return false;
                    break;
                case ColumnExpression:
                case LiteralExpression:
                case ParameterExpression:
                    break;
                case BinaryExpression binary:
                    pending.Push(binary.Left);
                    pending.Push(binary.Right);
                    break;
                case UnaryExpression unary:
                    pending.Push(unary.Operand);
                    break;
                case CastExpression cast:
                    pending.Push(cast.Expression);
                    break;
                case CollationExpression collation:
                    pending.Push(collation.Expression);
                    break;
                case BetweenExpression between:
                    pending.Push(between.Value);
                    pending.Push(between.Lower);
                    pending.Push(between.Upper);
                    break;
                case CaseExpression caseExpression:
                    if (caseExpression.Operand is not null)
                        pending.Push(caseExpression.Operand);
                    foreach (var clause in caseExpression.Clauses)
                    {
                        pending.Push(clause.When);
                        pending.Push(clause.Then);
                    }

                    if (caseExpression.Else is not null)
                        pending.Push(caseExpression.Else);
                    break;
                case RowValueExpression rowValue:
                    foreach (var value in rowValue.Values)
                        pending.Push(value);
                    break;
                default:
                    return false;
            }
        }

        return true;
    }

    // Fetches one join side, pushing a side-safe WHERE conjunct all the way down to the base
    // table scans. When the side is itself a nested join, recurse so a single-table conjunct
    // reaches the leaf scans instead of materializing the nested join's full cartesian output
    // first. The full side predicate is always re-applied to the returned rows: pushed
    // conjuncts are re-checked (harmless) and conjuncts spanning the nested join's two sides
    // are enforced here.
    private SourceData GetSideSourceRows(
        TableSource side,
        Expression? sidePredicate,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow)
    {
        var rows = sidePredicate is not null && side is JoinTableSource nestedJoin
            ? GetJoinRowsWithPredicatePushdown(
                nestedJoin,
                sidePredicate,
                parameters,
                context,
                maximumRows: null,
                outerRow)
            : GetSourceRowsWithTransientIndex(
                side,
                sidePredicate,
                parameters,
                context,
                maximumRows: null,
                outerRow);

        return sidePredicate is null ? rows : FilterSourceRows(rows, sidePredicate, parameters, context);
    }

    private SourceData GetJoinRows(
        JoinTableSource source,
        SqlValue[] parameters,
        QueryContext context,
        long? maximumRows,
        SourceRow? outerRow,
        Expression? leftPredicate = null,
        Expression? rightPredicate = null)
    {
        var left = GetSideSourceRows(source.Left, leftPredicate, parameters, context, outerRow);
        var right = GetSideSourceRows(source.Right, rightPredicate, parameters, context, outerRow);
        var leftQualifiedColumns = GetQualifiedColumns(source.Left, context);
        var rightQualifiedColumns = GetQualifiedColumns(source.Right, context);
        var leftQualifiedRowIds = GetQualifiedRowIdPlaceholders(source.Left, context);
        var rightQualifiedRowIds = GetQualifiedRowIdPlaceholders(source.Right, context);
        var columnDefinitions = GetSourceColumnDefinitions(source.Left, context)
            .Concat(GetSourceColumnDefinitions(source.Right, context))
            .ToArray();
        var qualifiedColumnDefinitions = GetSourceQualifiedColumnDefinitions(source, context);
        var columns = left.Columns.Concat(right.Columns).ToArray();
        var outputColumns = GetOutputColumns(source, context);
        var leftWidth = left.Columns.Length;
        var joinPairs = BuildJoinPairs(source, context);
        var joinHashIndex = TryBuildJoinHashIndex(source, right, context);
        IEnumerable<int>? allRightIndices = null;

        var rows = new List<SourceRow>();
        var rightMatched = new bool[right.Rows.Count];
        foreach (var leftRow in left.Rows)
        {
            var matched = false;
            var candidateIndices = joinHashIndex is not null
                ? joinHashIndex.Probe(leftRow)
                : allRightIndices ??= Enumerable.Range(0, right.Rows.Count);
            foreach (var rightIndex in candidateIndices)
            {
                var rightRow = right.Rows[rightIndex];
                if (source.Condition is null
                    && !JoinConditionMatches(source, joinPairs, combinedRow: null, leftRow, rightRow, parameters, context))
                {
                    continue;
                }

                var values = leftRow.Values.Concat(rightRow.Values).ToArray();
                var row = new SourceRow(
                    columns,
                    values,
                    CombineQualifiedColumns(leftRow.QualifiedColumns, rightRow.QualifiedColumns, leftWidth),
                    outerRow,
                    outputColumns,
                    QualifiedRowIds: CombineQualifiedRowIds(
                        GetQualifiedRowIds(leftRow),
                        GetQualifiedRowIds(rightRow)),
                    ColumnDefinitions: CombineColumnDefinitions(
                        leftRow,
                        rightRow,
                        left.Columns.Length,
                        right.Columns.Length,
                        columnDefinitions),
                    QualifiedColumnDefinitions: qualifiedColumnDefinitions);
                if (source.Condition is not null
                    && !JoinConditionMatches(source, joinPairs, row, leftRow, rightRow, parameters, context))
                {
                    continue;
                }

                matched = true;
                rightMatched[rightIndex] = true;
                rows.Add(row);
                if (maximumRows is not null && rows.Count >= maximumRows.Value)
                    return new SourceData(columns, rows);
            }

            if (!matched && source.Kind is JoinKind.Left or JoinKind.Full)
            {
                var values = leftRow.Values
                    .Concat(Enumerable.Repeat(SqlValue.Null, right.Columns.Length))
                    .ToArray();
                rows.Add(new SourceRow(
                    columns,
                    values,
                    CombineQualifiedColumns(leftRow.QualifiedColumns, rightQualifiedColumns, leftWidth),
                    outerRow,
                    outputColumns,
                    QualifiedRowIds: CombineQualifiedRowIds(
                        GetQualifiedRowIds(leftRow),
                        rightQualifiedRowIds),
                    ColumnDefinitions: CombineColumnDefinitions(
                        leftRow,
                        right.Rows.FirstOrDefault(),
                        left.Columns.Length,
                        right.Columns.Length,
                        columnDefinitions),
                    QualifiedColumnDefinitions: qualifiedColumnDefinitions));
                if (maximumRows is not null && rows.Count >= maximumRows.Value)
                    return new SourceData(columns, rows);
            }
        }

        if (source.Kind is JoinKind.Right or JoinKind.Full)
        {
            for (var rightIndex = 0; rightIndex < right.Rows.Count; rightIndex++)
            {
                if (rightMatched[rightIndex])
                    continue;

                var rightRow = right.Rows[rightIndex];
                var values = Enumerable.Repeat(SqlValue.Null, leftWidth)
                    .Concat(rightRow.Values)
                    .ToArray();
                rows.Add(new SourceRow(
                    columns,
                    values,
                    CombineQualifiedColumns(leftQualifiedColumns, rightRow.QualifiedColumns, leftWidth),
                    outerRow,
                    outputColumns,
                    QualifiedRowIds: CombineQualifiedRowIds(
                        leftQualifiedRowIds,
                        GetQualifiedRowIds(rightRow)),
                    ColumnDefinitions: CombineColumnDefinitions(
                        left.Rows.FirstOrDefault(),
                        rightRow,
                        left.Columns.Length,
                        right.Columns.Length,
                        columnDefinitions),
                    QualifiedColumnDefinitions: qualifiedColumnDefinitions));
                if (maximumRows is not null && rows.Count >= maximumRows.Value)
                    return new SourceData(columns, rows);
            }

        }

        return new SourceData(columns, rows);
    }

    private static IReadOnlyList<EmbeddedColumn?>? CombineColumnDefinitions(
        SourceRow? left,
        SourceRow? right,
        int leftWidth,
        int rightWidth,
        IReadOnlyList<EmbeddedColumn?>? fallbackDefinitions = null)
    {
        if (left?.ColumnDefinitions is null && right?.ColumnDefinitions is null)
            return fallbackDefinitions;

        var definitions = fallbackDefinitions?.ToArray()
            ?? new EmbeddedColumn?[leftWidth + rightWidth];
        if (definitions.Length != leftWidth + rightWidth)
            throw new InvalidOperationException("Join column metadata width does not match the joined row.");
        if (left?.ColumnDefinitions is not null)
        {
            for (var index = 0; index < left.ColumnDefinitions.Count; index++)
                definitions[index] = left.ColumnDefinitions[index];
        }
        if (right?.ColumnDefinitions is not null)
        {
            for (var index = 0; index < right.ColumnDefinitions.Count; index++)
                definitions[leftWidth + index] = right.ColumnDefinitions[index];
        }

        return definitions;
    }

    private static IReadOnlyList<(OutputColumn Left, OutputColumn Right)> BuildJoinPairs(
        JoinTableSource source,
        QueryContext context)
    {
        var leftColumns = GetOutputColumns(source.Left, context);
        var rightColumns = GetOutputColumns(source.Right, context);
        IReadOnlyList<string> names;
        if (source.UsingColumns is { } usingColumns)
        {
            names = usingColumns;
        }
        else if (source.Natural)
        {
            var rightSet = new HashSet<string>(rightColumns.Select(column => column.Name), StringComparer.OrdinalIgnoreCase);
            names = leftColumns
                .Select(column => column.Name)
                .Where(rightSet.Contains)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToArray();
        }
        else
        {
            return [];
        }

        var pairs = new List<(OutputColumn Left, OutputColumn Right)>(names.Count);
        foreach (var name in names)
        {
            var leftIndex = FindOutputColumnIndex(leftColumns, name);
            var rightIndex = FindOutputColumnIndex(rightColumns, name);
            if (leftIndex < 0 || rightIndex < 0)
                throw new EmbeddedSqlException($"cannot join using column {name} - column not present in both tables");

            pairs.Add((leftColumns[leftIndex], rightColumns[rightIndex]));
        }

        return pairs;
    }

    private static int FindOutputColumnIndex(IReadOnlyList<OutputColumn> columns, string name)
    {
        for (var index = 0; index < columns.Count; index++)
        {
            if (string.Equals(columns[index].Name, name, StringComparison.OrdinalIgnoreCase))
                return index;
        }

        return -1;
    }

    private bool JoinConditionMatches(
        JoinTableSource source,
        IReadOnlyList<(OutputColumn Left, OutputColumn Right)> joinPairs,
        SourceRow? combinedRow,
        SourceRow leftRow,
        SourceRow rightRow,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (source.Condition is not null)
            return IsTrue(Evaluate(source.Condition, parameters, combinedRow!, context));

        foreach (var (leftColumn, rightColumn) in joinPairs)
        {
            if (!JoinPairMatches(
                    source,
                    leftColumn,
                    rightColumn,
                    leftRow,
                    rightRow,
                    context))
            {
                return false;
            }
        }

        return true;
    }

    private bool JoinPairMatches(
        JoinTableSource source,
        OutputColumn leftColumn,
        OutputColumn rightColumn,
        SourceRow leftRow,
        SourceRow rightRow,
        QueryContext context)
    {
        var left = GetOutputValue(leftRow, leftColumn);
        var right = GetOutputValue(rightRow, rightColumn);
        var leftDefinition = GetOutputColumnDefinition(source.Left, leftColumn, context);
        var rightDefinition = GetOutputColumnDefinition(source.Right, rightColumn, context);
        ApplyComparisonAffinities(leftDefinition, rightDefinition, ref left, ref right);
        return IsTrue(EvaluateBinaryValues(
            BinaryOperator.Equal,
            left,
            right,
            leftDefinition?.Collation ?? rightDefinition?.Collation));
    }

    private EquiJoinHashIndex? TryBuildJoinHashIndex(
        JoinTableSource source,
        SourceData right,
        QueryContext context)
    {
        if (source.Condition is null)
            return null;

        var leftColumns = GetOutputColumns(source.Left, context);
        var rightColumns = GetOutputColumns(source.Right, context);
        var keys = new List<EquiJoinKey>();
        var pending = new Stack<Expression>();
        pending.Push(source.Condition);
        while (pending.Count > 0)
        {
            var conjunct = pending.Pop();
            if (conjunct is BinaryExpression { Operator: BinaryOperator.And } and)
            {
                pending.Push(and.Left);
                pending.Push(and.Right);
                continue;
            }

            if (TryCreateEquiJoinKey(conjunct, source, leftColumns, rightColumns, context) is { } key)
                keys.Add(key);
        }

        return keys.Count == 0 ? null : new EquiJoinHashIndex(keys, right);
    }

    private EquiJoinKey? TryCreateEquiJoinKey(
        Expression conjunct,
        JoinTableSource source,
        IReadOnlyList<OutputColumn> leftColumns,
        IReadOnlyList<OutputColumn> rightColumns,
        QueryContext context)
    {
        if (conjunct is not BinaryExpression { Operator: BinaryOperator.Equal } binary)
            return null;
        if (UnwrapCollation(binary.Left) is not ColumnExpression { BooleanKeyword: null } leftOperand
            || UnwrapCollation(binary.Right) is not ColumnExpression { BooleanKeyword: null } rightOperand)
        {
            return null;
        }

        var leftOnLeft = ResolveJoinSideColumn(leftOperand, leftColumns);
        var leftOnRight = ResolveJoinSideColumn(leftOperand, rightColumns);
        var rightOnLeft = ResolveJoinSideColumn(rightOperand, leftColumns);
        var rightOnRight = ResolveJoinSideColumn(rightOperand, rightColumns);

        OutputColumn leftColumn;
        OutputColumn rightColumn;
        if (leftOnLeft is not null && leftOnRight is null
            && rightOnLeft is null && rightOnRight is not null)
        {
            leftColumn = leftOnLeft;
            rightColumn = rightOnRight;
        }
        else if (leftOnRight is not null && leftOnLeft is null
            && rightOnLeft is not null && rightOnRight is null)
        {
            leftColumn = rightOnLeft;
            rightColumn = leftOnRight;
        }
        else
        {
            return null;
        }

        var leftDefinition = GetOutputColumnDefinition(source.Left, leftColumn, context);
        var rightDefinition = GetOutputColumnDefinition(source.Right, rightColumn, context);
        var leftAffinity = GetJoinKeyAffinity(leftDefinition);
        var rightAffinity = GetJoinKeyAffinity(rightDefinition);
        var collation = GetExplicitCollation(binary.Left)
            ?? GetExplicitCollation(binary.Right)
            ?? (leftDefinition is not null ? NormalizeDeclaredCollation(leftDefinition.Collation) : null)
            ?? (rightDefinition is not null ? NormalizeDeclaredCollation(rightDefinition.Collation) : null)
            ?? "BINARY";
        if (!IsHashableJoinKeyCollation(collation) || IsUnsafeCompiledCollation(collation))
        {
            return null;
        }

        return new EquiJoinKey(
            leftColumn,
            rightColumn,
            LeftConvertsTextToNumeric: IsNumericAffinity(rightAffinity) && !IsNumericAffinity(leftAffinity),
            LeftConvertsNumericToText: rightAffinity == ColumnAffinity.Text && leftAffinity is null,
            RightConvertsTextToNumeric: IsNumericAffinity(leftAffinity) && !IsNumericAffinity(rightAffinity),
            RightConvertsNumericToText: leftAffinity == ColumnAffinity.Text && rightAffinity is null,
            Collation: collation.ToUpperInvariant());
    }

    private static OutputColumn? ResolveJoinSideColumn(
        ColumnExpression operand,
        IReadOnlyList<OutputColumn> columns)
    {
        var operandName = operand.UnqualifiedName ?? operand.Name;
        foreach (var column in columns)
        {
            if (!string.Equals(column.Name, operandName, StringComparison.OrdinalIgnoreCase))
                continue;
            if (operand.Qualifier is not null
                && !string.Equals(column.Qualifier, operand.Qualifier, StringComparison.OrdinalIgnoreCase))
                continue;
            return column;
        }

        return null;
    }

    private static ColumnAffinity? GetJoinKeyAffinity(EmbeddedColumn? definition)
        => definition is null || definition.StrictAny
            ? null
            : EmbeddedTable.GetAffinity(definition.DeclaredType);

    private static bool IsHashableJoinKeyCollation(string collation)
        => string.Equals(collation, "BINARY", StringComparison.OrdinalIgnoreCase)
            || string.Equals(collation, "NOCASE", StringComparison.OrdinalIgnoreCase)
            || string.Equals(collation, "RTRIM", StringComparison.OrdinalIgnoreCase);

    // UNIQUE/PK constraint checks used to dedup the entire table with a nested loop on every
    // INSERT (O(rows^2) per statement, so a 2155-row Northwind child table made each bulk insert
    // scan ~4.8M rows and the whole fixture time out). Native SQLite validates only the new row
    // against the index; the hash probe below gets the same effect by bucketing rows on the same
    // canonical key the #8 equi-join probe uses, then confirming each bucket hit with the exact
    // Compare call the original loop used. Custom/overridden collations and unhashable values
    // fall back to the original nested loop (correctness preserved).
    private bool IsUniqueKeyCollationHashable(string? collation)
    {
        var normalized = collation ?? "BINARY";
        return IsHashableJoinKeyCollation(normalized) && !IsUnsafeCompiledCollation(normalized);
    }

    private static string? BuildUniqueCanonicalKey(
        SqlValue[] row,
        IReadOnlyList<int> columnIndices,
        IReadOnlyList<string?> collations)
    {
        string? key = null;
        for (var index = 0; index < columnIndices.Count; index++)
        {
            var collation = collations[index] ?? "BINARY";
            var segment = EquiJoinHashIndex.CanonicalizeJoinKeyValue(
                row[columnIndices[index]],
                convertTextToNumeric: false,
                convertNumericToText: false,
                collation);
            if (segment is null)
                return null;
            key = key is null ? segment.Length + ":" + segment : key + segment.Length + ":" + segment;
        }
        return key;
    }

    private static string? BuildUniqueCanonicalKeyFromValues(
        IReadOnlyList<SqlValue> keyValues,
        IReadOnlyList<string?> collations)
    {
        string? key = null;
        for (var index = 0; index < keyValues.Count; index++)
        {
            var collation = collations[index] ?? "BINARY";
            var segment = EquiJoinHashIndex.CanonicalizeJoinKeyValue(
                keyValues[index],
                convertTextToNumeric: false,
                convertNumericToText: false,
                collation);
            if (segment is null)
                return null;
            key = key is null ? segment.Length + ":" + segment : key + segment.Length + ":" + segment;
        }
        return key;
    }

    private sealed record EquiJoinKey(
        OutputColumn LeftColumn,
        OutputColumn RightColumn,
        bool LeftConvertsTextToNumeric,
        bool LeftConvertsNumericToText,
        bool RightConvertsTextToNumeric,
        bool RightConvertsNumericToText,
        string Collation);

    // Pre-filters equi-join candidates by hashing the right side on normalized key values.
    // Keys are canonicalized so that any pair comparing equal (after comparison affinities and
    // collation) lands in the same bucket; candidates still run the full join condition.
    private sealed class EquiJoinHashIndex
    {
        private static readonly IReadOnlyList<int> NoCandidates = [];
        private readonly IReadOnlyList<EquiJoinKey> _keys;
        private readonly Dictionary<string, List<int>> _buckets = new(StringComparer.Ordinal);

        public EquiJoinHashIndex(IReadOnlyList<EquiJoinKey> keys, SourceData right)
        {
            _keys = keys;
            for (var index = 0; index < right.Rows.Count; index++)
            {
                var key = BuildKey(right.Rows[index], leftSide: false);
                if (key is null)
                    continue;
                if (!_buckets.TryGetValue(key, out var bucket))
                {
                    bucket = [];
                    _buckets[key] = bucket;
                }

                bucket.Add(index);
            }
        }

        public IReadOnlyList<int> Probe(SourceRow leftRow)
        {
            var key = BuildKey(leftRow, leftSide: true);
            return key is not null && _buckets.TryGetValue(key, out var bucket)
                ? bucket
                : NoCandidates;
        }

        private string? BuildKey(SourceRow row, bool leftSide)
        {
            string? key = null;
            foreach (var equiKey in _keys)
            {
                var value = GetOutputValue(row, leftSide ? equiKey.LeftColumn : equiKey.RightColumn);
                var segment = CanonicalizeJoinKeyValue(
                    value,
                    leftSide ? equiKey.LeftConvertsTextToNumeric : equiKey.RightConvertsTextToNumeric,
                    leftSide ? equiKey.LeftConvertsNumericToText : equiKey.RightConvertsNumericToText,
                    equiKey.Collation);
                if (segment is null)
                    return null;
                key = key is null
                    ? segment.Length + ":" + segment
                    : key + segment.Length + ":" + segment;
            }

            return key;
        }

        internal static string? CanonicalizeJoinKeyValue(
            SqlValue value,
            bool convertTextToNumeric,
            bool convertNumericToText,
            string collation)
        {
            switch (value.Kind)
            {
                case SqlValueKind.Integer:
                case SqlValueKind.Real:
                    if (convertNumericToText)
                        return "T" + CanonicalizeJoinKeyText(ToSqlText(value), collation);
                    return "N" + ToNumericKeyBits(
                        value.Kind == SqlValueKind.Integer ? value.AsInteger() : value.AsReal());
                case SqlValueKind.Text:
                    if (convertTextToNumeric)
                    {
                        var converted = ApplyComparisonNumericAffinity(value);
                        if (converted.Kind is SqlValueKind.Integer or SqlValueKind.Real)
                        {
                            return "N" + ToNumericKeyBits(
                                converted.Kind == SqlValueKind.Integer ? converted.AsInteger() : converted.AsReal());
                        }
                    }

                    return "T" + CanonicalizeJoinKeyText(value.AsText(), collation);
                case SqlValueKind.Blob:
                    return "B" + Convert.ToHexString(value.AsBlob().Span);
                default:
                    return null;
            }
        }

        private static string ToNumericKeyBits(double number)
        {
            if (number == 0)
                number = 0; // normalize -0 so 0 and -0 share a bucket
            return BitConverter.DoubleToInt64Bits(number).ToString("X16", CultureInfo.InvariantCulture);
        }

        private static string CanonicalizeJoinKeyText(string text, string collation)
        {
            switch (collation)
            {
                case "NOCASE":
                    // SQLite NOCASE folds ASCII and stops comparing at the first NUL:
                    // strings agreeing up to a NUL are equal when their total lengths
                    // match, so bytes past the NUL contribute only that length to the key.
                    var nulIndex = text.IndexOf('\0');
                    var prefix = nulIndex < 0 ? text : text.Substring(0, nulIndex);
                    return AsciiUpper(prefix)
                        + '\u0001'
                        + System.Text.Encoding.UTF8.GetByteCount(text)
                            .ToString(CultureInfo.InvariantCulture);
                case "RTRIM":
                    return text.TrimEnd(' ');
                default:
                    return text;
            }
        }

        private static string AsciiUpper(string text)
        {
            // SQLite NOCASE folds only ASCII letters.
            var chars = text.ToCharArray();
            for (var index = 0; index < chars.Length; index++)
            {
                var c = chars[index];
                if (c is >= 'a' and <= 'z')
                    chars[index] = (char)(c - ('a' - 'A'));
            }

            return new string(chars);
        }
    }

    private static IReadOnlyDictionary<string, int> CombineQualifiedColumns(
        IReadOnlyDictionary<string, int>? left,
        IReadOnlyDictionary<string, int>? right,
        int rightOffset)
    {
        var columns = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        if (left is not null)
        {
            foreach (var (name, index) in left)
                columns.TryAdd(name, index);
        }
        if (right is not null)
        {
            foreach (var (name, index) in right)
                columns.TryAdd(name, rightOffset + index);
        }

        return columns;
    }

    private static IReadOnlyDictionary<string, long?> CombineQualifiedRowIds(
        IReadOnlyDictionary<string, long?> left,
        IReadOnlyDictionary<string, long?> right)
    {
        var rowIds = new Dictionary<string, long?>(StringComparer.OrdinalIgnoreCase);
        foreach (var (qualifier, rowId) in left)
            rowIds.TryAdd(qualifier, rowId);
        foreach (var (qualifier, rowId) in right)
            rowIds.TryAdd(qualifier, rowId);
        return rowIds;
    }

    private static IReadOnlyDictionary<string, long?> GetQualifiedRowIds(SourceRow row)
    {
        var rowIds = new Dictionary<string, long?>(StringComparer.OrdinalIgnoreCase);
        if (row.QualifiedRowIds is not null)
        {
            foreach (var (qualifier, rowId) in row.QualifiedRowIds)
                rowIds.TryAdd(qualifier, rowId);
        }

        if (row.RowIdQualifier is not null)
            rowIds.TryAdd(row.RowIdQualifier, row.RowId);
        return rowIds;
    }

    private static IReadOnlyDictionary<string, long?> GetQualifiedRowIdPlaceholders(
        TableSource source,
        QueryContext context)
    {
        switch (source)
        {
            case NamedTableSource named
                when context.Tables.TryGetValue(named.Name, out var table) && table.HasRowid:
                return new Dictionary<string, long?>(StringComparer.OrdinalIgnoreCase)
                {
                    [named.Alias ?? named.Name] = null,
                };
            case JoinTableSource join:
                return CombineQualifiedRowIds(
                    GetQualifiedRowIdPlaceholders(join.Left, context),
                    GetQualifiedRowIdPlaceholders(join.Right, context));
            default:
                return new Dictionary<string, long?>(StringComparer.OrdinalIgnoreCase);
        }
    }

    private static IReadOnlyDictionary<string, int> GetQualifiedColumns(
        TableSource source,
        QueryContext context)
    {
        return source switch
        {
            NamedTableSource named when IsSchemaTable(named.Name) => BuildQualifiedColumns(
                named.Alias ?? named.Name,
                ["type", "name", "tbl_name", "rootpage", "sql"]),
            NamedTableSource named when context.CommonTableExpressions.TryGetValue(named.Name, out var commonTableExpression)
                => BuildQualifiedColumns(named.Alias ?? named.Name, commonTableExpression.Columns),
            NamedTableSource named when TryGetView(context, named.Name, out var view)
                => BuildQualifiedColumns(named.Alias ?? view.Name, ResolveViewColumns(view, EnterView(context, view.Name))),
            NamedTableSource named when TryBindBareTableValuedFunction(named, context, out var bare)
                => GetQualifiedColumns(bare, context),
            NamedTableSource named => BuildQualifiedColumns(
                named.Alias ?? named.Name,
                GetTable(named, context.Tables).Columns),
            TableValuedFunctionSource function => BuildQualifiedColumns(
                function.Alias ?? function.Name,
                TableValuedFunctionRegistry.Resolve(function.Name).Schema.AllColumns),
            DerivedTableSource derived when derived.Alias is not null
                => BuildQualifiedColumns(derived.Alias, DescribeQuery(derived.Query, context)),
            DerivedTableSource => new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase),
            JoinTableSource join => CombineQualifiedColumns(
                GetQualifiedColumns(join.Left, context),
                GetQualifiedColumns(join.Right, context),
                GetSourceColumns(join.Left, context).Length),
            _ => throw new EmbeddedSqlException($"Unsupported table source {source.GetType().Name}."),
        };
    }

    private static IReadOnlyList<EmbeddedColumn?> GetSourceColumnDefinitions(
        TableSource source,
        QueryContext context)
    {
        return source switch
        {
            NamedTableSource named when context.Tables.TryGetValue(named.Name, out var table)
                => table.ColumnDefinitions.Select(static definition => (EmbeddedColumn?)definition).ToArray(),
            JoinTableSource join => GetSourceColumnDefinitions(join.Left, context)
                .Concat(GetSourceColumnDefinitions(join.Right, context))
                .ToArray(),
            _ => Enumerable.Repeat<EmbeddedColumn?>(
                    null,
                    GetSourceColumns(source, context).Length)
                .ToArray(),
        };
    }

    private static IReadOnlyDictionary<string, EmbeddedColumn> GetSourceQualifiedColumnDefinitions(
        TableSource source,
        QueryContext context)
    {
        switch (source)
        {
            case NamedTableSource named when context.Tables.TryGetValue(named.Name, out var table):
                return BuildQualifiedColumnDefinitions(
                    named.Alias ?? named.Name,
                    table.ColumnDefinitions);
            case JoinTableSource join:
                {
                    var definitions = new Dictionary<string, EmbeddedColumn>(
                        StringComparer.OrdinalIgnoreCase);
                    foreach (var (name, definition) in GetSourceQualifiedColumnDefinitions(join.Left, context))
                        definitions.TryAdd(name, definition);
                    foreach (var (name, definition) in GetSourceQualifiedColumnDefinitions(join.Right, context))
                        definitions.TryAdd(name, definition);
                    return definitions;
                }
            default:
                return new Dictionary<string, EmbeddedColumn>(StringComparer.OrdinalIgnoreCase);
        }
    }

    private static IReadOnlyDictionary<string, int> BuildQualifiedColumns(
        string qualifier,
        IReadOnlyList<string> columns)
    {
        var qualifiedColumns = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        for (var index = 0; index < columns.Count; index++)
            qualifiedColumns.TryAdd($"{qualifier}.{columns[index]}", index);

        return qualifiedColumns;
    }

    // Builds the evaluation row for one UPDATE/DELETE target row. Column references are
    // resolvable through the statement's alias when one is present and through the table
    // name otherwise, matching how SQLite scopes a qualified-table-name.
    private static SourceRow CreateDmlTargetRow(
        EmbeddedTable table,
        string qualifier,
        SqlValue[] row,
        long rowid)
        => new(
            table.Columns,
            row,
            BuildQualifiedColumns(qualifier, table.Columns),
            RowId: table.HasRowid ? rowid : null,
            RowIdQualifier: qualifier,
            ColumnDefinitions: table.ColumnDefinitions,
            QualifiedColumnDefinitions: BuildQualifiedColumnDefinitions(qualifier, table.ColumnDefinitions));

    private static EmbeddedTable GetTable(NamedTableSource source, Dictionary<string, EmbeddedTable> tables)
    {
        if (!tables.TryGetValue(source.Name, out var table))
            throw new EmbeddedSqlException($"no such table: {source.Name}");

        return table;
    }

    private static bool IsSchemaTable(string name)
        => string.Equals(name, "sqlite_master", StringComparison.OrdinalIgnoreCase)
            || string.Equals(name, "sqlite_schema", StringComparison.OrdinalIgnoreCase);

    private static bool IsSqliteSequenceTable(string name)
        => string.Equals(name, SqliteSequenceTableName, StringComparison.OrdinalIgnoreCase);

    private static SourceData GetNamedTableRows(
        NamedTableSource source,
        QueryContext context,
        long? maximumRows,
        SourceRow? outerRow)
    {
        if (IsSchemaTable(source.Name))
            return GetSchemaTableRows(source, context, outerRow);

        var table = GetTable(source, context.Tables);
        var qualifier = source.Alias ?? source.Name;
        var qualifiedColumns = BuildQualifiedColumns(qualifier, table.Columns);
        var qualifiedColumnDefinitions = BuildQualifiedColumnDefinitions(
            qualifier,
            table.ColumnDefinitions);
        var count = table.Rows.Count;
        if (maximumRows is { } maximum && maximum < count)
            count = (int)maximum;

        var sourceRows = new SourceRow[count];
        for (var index = 0; index < count; index++)
        {
            var rowid = index < table.RowIds.Count ? table.RowIds[index] : index + 1;
            sourceRows[index] = new SourceRow(
                table.Columns,
                table.Rows[index],
                qualifiedColumns,
                outerRow,
                RowId: table.HasRowid ? rowid : null,
                RowIdQualifier: qualifier,
                ColumnDefinitions: table.ColumnDefinitions,
                QualifiedColumnDefinitions: qualifiedColumnDefinitions);
        }

        return new SourceData(table.Columns, sourceRows);
    }

    private static SourceData GetSchemaTableRows(
        NamedTableSource source,
        QueryContext context,
        SourceRow? outerRow)
    {
        var tables = context.Tables;
        var columns = new[] { "type", "name", "tbl_name", "rootpage", "sql" };
        var qualifiedColumns = BuildQualifiedColumns(source.Alias ?? source.Name, columns);
        var rows = new List<SourceRow>();
        foreach (var entry in tables.OrderBy(entry => entry.Key, StringComparer.OrdinalIgnoreCase))
        {
            rows.Add(new SourceRow(
                columns,
                [
                    SqlValue.Text("table"),
                    SqlValue.Text(entry.Key),
                    SqlValue.Text(entry.Key),
                    SqlValue.Integer(0),
                    SqlValue.Text(BuildCreateTableSql(entry.Key, entry.Value)),
                ],
                qualifiedColumns,
                outerRow));

            foreach (var index in entry.Value.Indexes)
            {
                rows.Add(new SourceRow(
                    columns,
                    [
                        SqlValue.Text("index"),
                        SqlValue.Text(index.Name),
                        SqlValue.Text(entry.Key),
                        SqlValue.Integer(0),
                        index.Origin == EmbeddedIndexOrigin.Explicit
                            ? SqlValue.Text(BuildCreateIndexSql(entry.Key, index))
                            : SqlValue.Null,
                    ],
                    qualifiedColumns,
                    outerRow));
            }
        }

        if (context.Views is not null)
        {
            foreach (var entry in context.Views.OrderBy(entry => entry.Key, StringComparer.OrdinalIgnoreCase))
            {
                rows.Add(new SourceRow(
                    columns,
                    [
                        SqlValue.Text("view"),
                        SqlValue.Text(entry.Key),
                        SqlValue.Text(entry.Key),
                        SqlValue.Integer(0),
                        SqlValue.Text(entry.Value.Sql),
                    ],
                    qualifiedColumns,
                    outerRow));
            }
        }

        if (context.Triggers is not null)
        {
            foreach (var entry in context.Triggers
                         .OrderBy(entry => entry.Value.DeclarationOrder)
                         .ThenBy(entry => entry.Key, StringComparer.OrdinalIgnoreCase))
            {
                rows.Add(new SourceRow(
                    columns,
                    [
                        SqlValue.Text("trigger"),
                        SqlValue.Text(entry.Key),
                        SqlValue.Text(entry.Value.TableName),
                        SqlValue.Integer(0),
                        SqlValue.Text(entry.Value.Sql),
                    ],
                    qualifiedColumns,
                    outerRow));
            }
        }

        return new SourceData(columns, rows);
    }

    private static SourceData GetCommonTableExpressionRows(
        NamedTableSource source,
        SourceData commonTableExpression,
        SourceRow? outerRow,
        long? maximumRows)
    {
        var rows = commonTableExpression.Rows.AsEnumerable();
        if (maximumRows is { } maximum && maximum < commonTableExpression.Rows.Count)
            rows = rows.Take((int)maximum);

        var qualifiedColumns = BuildQualifiedColumns(source.Alias ?? source.Name, commonTableExpression.Columns);
        return new SourceData(
            commonTableExpression.Columns,
            rows.Select(row => new SourceRow(
                commonTableExpression.Columns,
                row.Values.ToArray(),
                qualifiedColumns,
                outerRow)).ToArray());
    }

    private SourceData GetViewRows(
        NamedTableSource source,
        ViewDefinition view,
        SqlValue[] parameters,
        QueryContext context,
        long? maximumRows,
        SourceRow? outerRow)
    {
        var viewContext = EnterView(context, view.Name);
        var result = MaterializeQueryResult(
            ExecuteQuery(view.Query, parameters, viewContext, outerRow));
        var columns = ApplyViewColumnNames(view, result.Columns);
        var rows = result.Rows.AsEnumerable();
        if (maximumRows is { } maximum && maximum < result.Rows.Count)
            rows = rows.Take((int)maximum);

        var qualifiedColumns = BuildQualifiedColumns(source.Alias ?? view.Name, columns);
        return new SourceData(
            columns,
            rows.Select(row => new SourceRow(columns, row.ToArray(), qualifiedColumns, outerRow)).ToArray());
    }

    private static bool TryGetView(QueryContext context, string name, out ViewDefinition view)
    {
        if (context.Views is not null && context.Views.TryGetValue(name, out var found))
        {
            view = found;
            return true;
        }

        view = null!;
        return false;
    }

    // Enters a view's resolution scope, guarding against direct or mutual recursion and
    // isolating the body from the enclosing query's CTEs while retaining the catalog.
    private static QueryContext EnterView(QueryContext context, string viewName)
    {
        EnsureNoViewRecursion(context, viewName);
        var expanding = context.ExpandingViews is null
            ? new List<string>()
            : new List<string>(context.ExpandingViews);
        expanding.Add(viewName);
        return context with
        {
            CommonTableExpressions = new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
            ExpandingViews = expanding,
        };
    }

    private static void EnsureNoViewRecursion(QueryContext context, string viewName)
    {
        if (context.ExpandingViews is not null
            && context.ExpandingViews.Any(name => string.Equals(name, viewName, StringComparison.OrdinalIgnoreCase)))
        {
            throw new EmbeddedSqlException($"view {viewName} is circularly defined");
        }
    }

    private static string[] ResolveViewColumns(ViewDefinition view, QueryContext viewContext)
        => viewContext.SchemaValidation && view.Columns is not null
            ? view.Columns.ToArray()
            : ApplyViewColumnNames(view, DescribeQuery(view.Query, viewContext));

    private static string[] ApplyViewColumnNames(ViewDefinition view, string[] queryColumns)
    {
        if (view.Columns is null)
            return queryColumns;
        if (view.Columns.Count != queryColumns.Length)
        {
            throw new EmbeddedSqlException(
                $"expected {view.Columns.Count} columns for {view.Name} but got {queryColumns.Length}");
        }

        return view.Columns.ToArray();
    }

    private SourceData GetDerivedTableRows(
        DerivedTableSource source,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? outerRow,
        long? maximumRows)
    {
        var result = MaterializeQueryResult(
            ExecuteQuery(source.Query, parameters, context, outerRow));
        var rows = result.Rows.AsEnumerable();
        if (maximumRows is { } maximum && maximum < result.Rows.Count)
            rows = rows.Take((int)maximum);

        var qualifiedColumns = source.Alias is null
            ? new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase)
            : BuildQualifiedColumns(source.Alias, result.Columns);
        return new SourceData(
            result.Columns,
            rows.Select(row => new SourceRow(result.Columns, row.ToArray(), qualifiedColumns, outerRow)).ToArray());
    }

    internal static string BuildCreateTableSql(string name, EmbeddedTable table)
    {
        if (IsSqliteSequenceTable(name))
        {
            ValidateSqliteSequenceCatalog(
                new Dictionary<string, EmbeddedTable>(StringComparer.OrdinalIgnoreCase)
                {
                    [SqliteSequenceTableName] = table,
                });
            return "CREATE TABLE sqlite_sequence(name,seq)";
        }

        var columns = table.ColumnDefinitions.Select(column =>
        {
            var definition = QuoteIdentifier(column.Name);
            if (!string.IsNullOrEmpty(column.DeclaredType))
                definition += " " + column.DeclaredType;
            if (column.Collation is { } collation)
            {
                definition += FormatConstraintName(column.CollationConstraintName)
                    + " COLLATE "
                    + collation;
            }

            // A generated column carries its expression instead of PRIMARY KEY / DEFAULT
            // markers (which SQLite forbids on generated columns); NOT NULL and UNIQUE still apply.
            if (column.IsGenerated)
            {
                definition += FormatConstraintName(column.GenerationConstraintName)
                    + (column.GenerationAlways ? " GENERATED ALWAYS" : string.Empty)
                    + $" AS ({column.GenerationSql}) "
                    + (column.GeneratedStored ? "STORED" : "VIRTUAL");
                if (column.NotNull)
                {
                    definition += FormatConstraintName(column.NotNullConstraintName)
                        + " NOT NULL"
                        + FormatConflictClause(column.NotNullConflictAlgorithm);
                }
                if (column.ExplicitNull)
                {
                    definition += FormatConstraintName(column.NullConstraintName) + " NULL";
                }
                if (column.Unique)
                {
                    definition += FormatConstraintName(column.UniqueConstraintName)
                        + " UNIQUE"
                        + FormatConflictClause(column.UniqueConflictAlgorithm);
                }
                foreach (var check in column.CheckConstraints)
                    definition += FormatCheckConstraint(check);
                return definition;
            }

            var keyConstraints = new List<(int DeclarationOrder, int FallbackOrder, string Sql)>();
            if (column.PrimaryKey)
            {
                keyConstraints.Add((
                    column.PrimaryKeyDeclarationOrder ?? 0,
                    0,
                    FormatConstraintName(column.PrimaryKeyConstraintName)
                    + (column.PrimaryKeyDescending ? " PRIMARY KEY DESC" : " PRIMARY KEY")
                    + FormatConflictClause(column.PrimaryKeyConflictAlgorithm)
                    + (column.AutoIncrement ? " AUTOINCREMENT" : string.Empty)));
            }
            if (column.Unique)
            {
                keyConstraints.Add((
                    column.UniqueDeclarationOrder ?? 1,
                    1,
                    FormatConstraintName(column.UniqueConstraintName)
                    + " UNIQUE"
                    + FormatConflictClause(column.UniqueConflictAlgorithm)));
            }
            foreach (var constraint in keyConstraints
                         .OrderBy(constraint => constraint.DeclarationOrder)
                         .ThenBy(constraint => constraint.FallbackOrder))
                definition += constraint.Sql;
            if (column.NotNull)
            {
                definition += FormatConstraintName(column.NotNullConstraintName)
                    + " NOT NULL"
                    + FormatConflictClause(column.NotNullConflictAlgorithm);
            }
            if (column.ExplicitNull)
            {
                definition += FormatConstraintName(column.NullConstraintName) + " NULL";
            }
            if (column.HasDefault)
            {
                definition += FormatConstraintName(column.DefaultConstraintName)
                    + " DEFAULT "
                    + (column.DefaultSql
                        ?? FormatSqlLiteral(column.DefaultValue
                            ?? throw new InvalidOperationException("Default metadata is incomplete.")));
            }
            foreach (var foreignKey in column.ForeignKeyConstraints)
            {
                definition += FormatConstraintName(foreignKey.ConstraintName)
                    + FormatForeignKeyReference(foreignKey);
            }
            foreach (var check in column.CheckConstraints)
                definition += FormatCheckConstraint(check);
            return definition;
        }).ToList();

        var tableKeyConstraints = new List<(int DeclarationOrder, int FallbackOrder, string Sql)>();
        if (table.TableLevelPrimaryKey is { } tablePrimaryKey)
        {
            var keyColumns = tablePrimaryKey.Select(keyColumn =>
                QuoteIdentifier(keyColumn.Name)
                + (keyColumn.Collation is { } collation ? " COLLATE " + collation : string.Empty)
                + (keyColumn.Descending ? " DESC" : string.Empty)
                + (keyColumn.AutoIncrement ? " AUTOINCREMENT" : string.Empty));
            tableKeyConstraints.Add((
                table.TablePrimaryKeyDeclarationOrder ?? -1,
                0,
                FormatConstraintName(table.TablePrimaryKeyConstraintName).TrimStart()
                + (table.TablePrimaryKeyConstraintName is null ? string.Empty : " ")
                + $"PRIMARY KEY ({string.Join(", ", keyColumns)})"
                + FormatConflictClause(table.TablePrimaryKeyConflictAlgorithm)));
        }

        for (var index = 0; index < table.TableUniqueConstraints.Count; index++)
        {
            var unique = table.TableUniqueConstraints[index];
            var keyColumns = unique.Columns.Select(keyColumn =>
                QuoteIdentifier(keyColumn.Name)
                + (keyColumn.Collation is { } collation ? " COLLATE " + collation : string.Empty)
                + (keyColumn.Descending ? " DESC" : string.Empty));
            tableKeyConstraints.Add((
                unique.DeclarationOrder,
                index + 1,
                FormatConstraintName(unique.Name).TrimStart()
                + (unique.Name is null ? string.Empty : " ")
                + $"UNIQUE ({string.Join(", ", keyColumns)})"
                + FormatConflictClause(unique.ConflictAlgorithm)));
        }

        columns.AddRange(tableKeyConstraints
            .OrderBy(constraint => constraint.DeclarationOrder)
            .ThenBy(constraint => constraint.FallbackOrder)
            .Select(constraint => constraint.Sql));

        foreach (var check in table.CheckConstraints)
            columns.Add(FormatCheckConstraint(check).TrimStart());

        foreach (var foreignKey in table.TableForeignKeys)
        {
            columns.Add(
                FormatConstraintName(foreignKey.ConstraintName).TrimStart()
                + (foreignKey.ConstraintName is null ? string.Empty : " ")
                + $"FOREIGN KEY ({string.Join(", ", foreignKey.ChildColumns.Select(QuoteIdentifier))})"
                + FormatForeignKeyReference(foreignKey));
        }

        var options = table switch
        {
            { WithoutRowid: true, Strict: true } => " WITHOUT ROWID, STRICT",
            { WithoutRowid: true } => " WITHOUT ROWID",
            { Strict: true } => " STRICT",
            _ => string.Empty,
        };
        return $"CREATE TABLE {QuoteIdentifier(name)} ({string.Join(", ", columns)}){options}";
    }

    private static string FormatForeignKeyReference(ForeignKeyDefinition foreignKey)
    {
        var parentColumns = foreignKey.ParentColumns.Count == 0
            ? string.Empty
            : $" ({string.Join(", ", foreignKey.ParentColumns.Select(QuoteIdentifier))})";
        var clause = $" REFERENCES {QuoteIdentifier(foreignKey.ParentTable)}{parentColumns}";
        if (foreignKey.OnDelete != ForeignKeyAction.NoAction)
            clause += " ON DELETE " + FormatForeignKeyAction(foreignKey.OnDelete);
        if (foreignKey.OnUpdate != ForeignKeyAction.NoAction)
            clause += " ON UPDATE " + FormatForeignKeyAction(foreignKey.OnUpdate);
        if (foreignKey.Match is { } match)
            clause += " MATCH " + QuoteIdentifier(match);
        clause += foreignKey.Deferral switch
        {
            ForeignKeyDeferral.NotDeferrable => string.Empty,
            ForeignKeyDeferral.InitiallyImmediate => " DEFERRABLE INITIALLY IMMEDIATE",
            ForeignKeyDeferral.InitiallyDeferred => " DEFERRABLE INITIALLY DEFERRED",
            _ => throw new InvalidOperationException($"Unknown foreign key deferral {foreignKey.Deferral}."),
        };
        return clause;
    }

    private static string FormatForeignKeyAction(ForeignKeyAction action)
        => action switch
        {
            ForeignKeyAction.NoAction => "NO ACTION",
            ForeignKeyAction.Restrict => "RESTRICT",
            ForeignKeyAction.SetNull => "SET NULL",
            ForeignKeyAction.SetDefault => "SET DEFAULT",
            ForeignKeyAction.Cascade => "CASCADE",
            _ => throw new InvalidOperationException($"Unknown foreign key action {action}."),
        };

    private static string FormatConstraintName(string? name)
        => name is null ? string.Empty : " CONSTRAINT " + QuoteIdentifier(name);

    private static string FormatCheckConstraint(CheckConstraint check)
        => FormatConstraintName(check.Name)
            + $" CHECK ({check.Sql})"
            + FormatConflictClause(check.ConflictAlgorithm);

    private static string FormatConflictClause(InsertConflictAlgorithm? algorithm)
        => algorithm is null ? string.Empty : " ON CONFLICT " + algorithm.Value.ToString().ToUpperInvariant();

    private static string BuildCreateIndexSql(string tableName, EmbeddedIndex index)
        => IndexSqlFormatter.BuildCreateIndexSql(tableName, index);

    private static string QuoteIdentifier(string identifier)
        => "\"" + identifier.Replace("\"", "\"\"", StringComparison.Ordinal) + "\"";

    private static string FormatSqlLiteral(SqlValue value)
    {
        return value.Kind switch
        {
            SqlValueKind.Null => "NULL",
            SqlValueKind.Integer => value.AsInteger().ToString(CultureInfo.InvariantCulture),
            SqlValueKind.Real => value.AsReal().ToString("R", CultureInfo.InvariantCulture),
            SqlValueKind.Text => "'" + value.AsText().Replace("'", "''", StringComparison.Ordinal) + "'",
            SqlValueKind.Blob => "X'" + Convert.ToHexString(value.AsBlob().Span) + "'",
            _ => throw new InvalidOperationException($"Unknown SQL value kind {value.Kind}."),
        };
    }

    /// <summary>
    /// Executes one table-valued function call. Argument expressions are evaluated against
    /// the outer row so a correlated call re-runs per outer row, then the module produces the
    /// rows. Hidden columns are materialized alongside the visible ones so predicates on the
    /// call arguments still resolve, while <see cref="SourceRow.OutputColumns"/> exposes only
    /// the visible columns to <c>*</c> expansion.
    /// </summary>
    private SourceData GetTableValuedFunctionRows(
        TableValuedFunctionSource source,
        SqlValue[] parameters,
        QueryContext context,
        long? maximumRows,
        SourceRow? outerRow)
    {
        var module = TableValuedFunctionRegistry.Resolve(source.Name);
        var schema = module.Schema;
        var arguments = new SqlValue[schema.HiddenColumns.Count];
        var supplied = new bool[schema.HiddenColumns.Count];
        for (var index = 0; index < arguments.Length; index++)
        {
            if (index < source.Arguments.Count)
            {
                arguments[index] = Evaluate(source.Arguments[index], parameters, outerRow, context);
                supplied[index] = true;
            }
            else
            {
                arguments[index] = SqlValue.Null;
            }
        }

        var produced = module.Enumerate(new TableValuedFunctionCall(
            arguments,
            supplied,
            source.Schema,
            maximumRows,
            context));

        var qualifier = source.Alias ?? source.Name;
        var columns = schema.AllColumns.ToArray();
        var qualifiedColumns = BuildQualifiedColumns(qualifier, schema.AllColumns);
        var outputColumns = BuildOutputColumns(qualifier, schema.VisibleColumns);
        var rows = new List<SourceRow>(produced.Count);
        foreach (var values in produced)
        {
            context.CheckInterrupt();
            if (maximumRows is { } limit && rows.Count >= limit)
                break;

            rows.Add(new SourceRow(columns, values, qualifiedColumns, outerRow, outputColumns));
        }

        return new SourceData(columns, rows);
    }

    private static IReadOnlyList<QueryAffinityColumn> BuildTableValuedFunctionAffinities(
        TableValuedFunctionSource source)
    {
        var schema = TableValuedFunctionRegistry.Resolve(source.Name).Schema;
        var qualifier = source.Alias ?? source.Name;
        var columns = new QueryAffinityColumn[schema.AllColumns.Count];
        for (var index = 0; index < columns.Length; index++)
            columns[index] = new QueryAffinityColumn(qualifier, schema.AllColumns[index], schema.AffinityAt(index));

        return columns;
    }

    private static SqlValue GetOutputValue(SourceRow row, OutputColumn column)
    {
        var value = row.Values[column.Index];
        if (value.Kind != SqlValueKind.Null)
            return value;
        if (column.CoalesceIndex is { } coalesceIndex)
        {
            value = row.Values[coalesceIndex];
            if (value.Kind != SqlValueKind.Null)
                return value;
        }
        if (column.AdditionalCoalesceIndices is not null)
        {
            foreach (var additionalIndex in column.AdditionalCoalesceIndices)
            {
                value = row.Values[additionalIndex];
                if (value.Kind != SqlValueKind.Null)
                    return value;
            }
        }

        return value;
    }

    private static string[] GetColumnNames(
        IReadOnlyList<Projection> projections,
        IReadOnlyList<OutputColumn> outputColumns,
        IReadOnlyList<OutputColumn>? rawOutputColumns = null)
    {
        var names = new List<string>();
        foreach (var projection in projections)
        {
            if (projection.Expression is StarExpression)
            {
                if (outputColumns.Count == 0)
                    throw new EmbeddedSqlException("SELECT * requires a row source");

                names.AddRange(outputColumns.Select(column => column.Name));
                continue;
            }

            if (projection.Expression is QualifiedStarExpression qualifiedStar)
            {
                var rawMatches = (rawOutputColumns ?? outputColumns)
                    .Where(column => string.Equals(column.Qualifier, qualifiedStar.Qualifier, StringComparison.OrdinalIgnoreCase))
                    .ToArray();
                if (rawMatches.Length == 0)
                    throw new EmbeddedSqlException($"no such table: {qualifiedStar.Qualifier}");

                names.AddRange(rawMatches.Select(column => column.Name));
                continue;
            }

            names.Add(projection.Alias ?? GetExpressionName(projection.Expression));
        }

        return names.ToArray();
    }

    internal static string[] DescribeQuery(QueryStatement statement, QueryContext context)
    {
        return statement switch
        {
            SelectStatement select => GetColumnNames(
                select.Projections,
                GetOutputColumns(select.Source, context),
                GetRawOutputColumns(select.Source, context)),
            CompoundSelectStatement compound => DescribeQuery(compound.Terms[0], context),
            WithSelectStatement with => DescribeWithSelect(with, context),
            ValuesClause values => DescribeValues(values),
            _ => throw new EmbeddedSqlException($"Unsupported query type {statement.GetType().Name}."),
        };
    }

    private static string[] DescribeValues(ValuesClause values)
    {
        var columns = new string[values.Rows[0].Count];
        for (var index = 0; index < columns.Length; index++)
            columns[index] = $"column{index + 1}";
        return columns;
    }

    private static string[] DescribeWithSelect(WithSelectStatement statement, QueryContext context)
    {
        var commonTableExpressions = new Dictionary<string, SourceData>(
            context.CommonTableExpressions,
            StringComparer.OrdinalIgnoreCase);
        var namesInCurrentClause = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var commonTableExpression in statement.CommonTableExpressions)
        {
            if (!namesInCurrentClause.Add(commonTableExpression.Name))
                throw new EmbeddedSqlException($"duplicate WITH table name: {commonTableExpression.Name}");

            var columns = ResolveCommonTableExpressionColumns(
                commonTableExpression,
                DescribeQuery(
                    commonTableExpression.Query,
                    context with { CommonTableExpressions = commonTableExpressions }));
            commonTableExpressions[commonTableExpression.Name] = new SourceData(columns, []);
        }

        return DescribeQuery(
            statement.Query,
            context with { CommonTableExpressions = commonTableExpressions });
    }

    private sealed record QueryAffinityColumn(
        string? Qualifier,
        string Name,
        ColumnAffinity Affinity,
        string? DeclaredType = null);

    private static IReadOnlyList<QueryAffinityColumn> DescribeQueryAffinities(
        QueryStatement statement,
        QueryContext context,
        Dictionary<string, IReadOnlyList<QueryAffinityColumn>> commonTableExpressions)
    {
        return statement switch
        {
            SelectStatement select => DescribeSelectAffinities(select, context, commonTableExpressions),
            CompoundSelectStatement compound => DescribeQueryAffinities(
                compound.Terms[0],
                context,
                commonTableExpressions),
            WithSelectStatement with => DescribeWithSelectAffinities(with, context, commonTableExpressions),
            ValuesClause values => Enumerable.Range(0, values.Rows[0].Count)
                .Select(index => new QueryAffinityColumn(null, $"column{index + 1}", ColumnAffinity.Blob))
                .ToArray(),
            _ => throw new EmbeddedSqlException($"Unsupported query type {statement.GetType().Name}."),
        };
    }

    private static IReadOnlyList<QueryAffinityColumn> DescribeSelectAffinities(
        SelectStatement statement,
        QueryContext context,
        Dictionary<string, IReadOnlyList<QueryAffinityColumn>> commonTableExpressions)
    {
        var output = GetSourceAffinityColumns(statement.Source, context, commonTableExpressions);
        var rawOutput = GetRawSourceAffinityColumns(statement.Source, context, commonTableExpressions);
        var result = new List<QueryAffinityColumn>();
        foreach (var projection in statement.Projections)
        {
            if (projection.Expression is StarExpression)
            {
                if (output.Count == 0)
                    throw new EmbeddedSqlException("SELECT * requires a row source");
                result.AddRange(output);
                continue;
            }

            if (projection.Expression is QualifiedStarExpression qualifiedStar)
            {
                var matches = rawOutput
                    .Where(column => string.Equals(
                        column.Qualifier,
                        qualifiedStar.Qualifier,
                        StringComparison.OrdinalIgnoreCase))
                    .ToArray();
                if (matches.Length == 0)
                    throw new EmbeddedSqlException($"no such table: {qualifiedStar.Qualifier}");
                result.AddRange(matches);
                continue;
            }

            result.Add(new QueryAffinityColumn(
                null,
                projection.Alias ?? GetExpressionName(projection.Expression),
                GetExpressionAffinity(
                    projection.Expression,
                    output,
                    context,
                    commonTableExpressions),
                GetExpressionDeclaredType(
                    projection.Expression,
                    output,
                    context,
                    commonTableExpressions)));
        }

        return result;
    }

    private static IReadOnlyList<QueryAffinityColumn> DescribeWithSelectAffinities(
        WithSelectStatement statement,
        QueryContext context,
        Dictionary<string, IReadOnlyList<QueryAffinityColumn>> commonTableExpressions)
    {
        var ctes = new Dictionary<string, IReadOnlyList<QueryAffinityColumn>>(
            commonTableExpressions,
            StringComparer.OrdinalIgnoreCase);
        var runtimeCtes = new Dictionary<string, SourceData>(
            context.CommonTableExpressions,
            StringComparer.OrdinalIgnoreCase);
        var namesInCurrentClause = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var cte in statement.CommonTableExpressions)
        {
            if (!namesInCurrentClause.Add(cte.Name))
                throw new EmbeddedSqlException($"duplicate WITH table name: {cte.Name}");

            var columns = DescribeQueryAffinities(
                cte.Query,
                context with { CommonTableExpressions = runtimeCtes },
                ctes).ToArray();
            if (cte.Columns is { } declared)
            {
                if (declared.Count != columns.Length)
                    throw new EmbeddedSqlException($"table {cte.Name} has {columns.Length} values for {declared.Count} columns");
                columns = columns
                    .Select((column, index) => column with { Name = declared[index] })
                    .ToArray();
            }

            ctes[cte.Name] = columns;
            runtimeCtes[cte.Name] = new SourceData(columns.Select(column => column.Name).ToArray(), []);
        }

        return DescribeQueryAffinities(
            statement.Query,
            context with { CommonTableExpressions = runtimeCtes },
            ctes);
    }

    private static IReadOnlyList<QueryAffinityColumn> GetSourceAffinityColumns(
        TableSource? source,
        QueryContext context,
        Dictionary<string, IReadOnlyList<QueryAffinityColumn>> commonTableExpressions)
    {
        if (source is not JoinTableSource join)
            return GetRawSourceAffinityColumns(source, context, commonTableExpressions);

        var raw = GetRawSourceAffinityColumns(join, context, commonTableExpressions);
        return GetOutputColumns(join, context)
            .Select(column =>
            {
                var affinity = raw[column.Index];
                return affinity with { Qualifier = column.Qualifier, Name = column.Name };
            })
            .ToArray();
    }

    private static IReadOnlyList<QueryAffinityColumn> GetRawSourceAffinityColumns(
        TableSource? source,
        QueryContext context,
        Dictionary<string, IReadOnlyList<QueryAffinityColumn>> commonTableExpressions)
    {
        return source switch
        {
            null => [],
            NamedTableSource named when IsSchemaTable(named.Name) =>
            [
                new(named.Alias ?? named.Name, "type", ColumnAffinity.Text),
                new(named.Alias ?? named.Name, "name", ColumnAffinity.Text),
                new(named.Alias ?? named.Name, "tbl_name", ColumnAffinity.Text),
                new(named.Alias ?? named.Name, "rootpage", ColumnAffinity.Integer),
                new(named.Alias ?? named.Name, "sql", ColumnAffinity.Text),
            ],
            NamedTableSource named when commonTableExpressions.TryGetValue(named.Name, out var cte)
                => QualifyAffinityColumns(cte, named.Alias ?? named.Name),
            NamedTableSource named when TryGetView(context, named.Name, out var view)
                => QualifyAffinityColumns(
                    DescribeViewAffinities(view, EnterView(context, view.Name), commonTableExpressions),
                    named.Alias ?? view.Name),
            NamedTableSource named when TryBindBareTableValuedFunction(named, context, out var bare)
                => BuildTableValuedFunctionAffinities(bare),
            NamedTableSource named => GetTableAffinityColumns(named, context.Tables),
            TableValuedFunctionSource function => BuildTableValuedFunctionAffinities(function),
            DerivedTableSource derived => QualifyAffinityColumns(
                DescribeQueryAffinities(derived.Query, context, commonTableExpressions),
                derived.Alias),
            JoinTableSource join => GetRawSourceAffinityColumns(join.Left, context, commonTableExpressions)
                .Concat(GetRawSourceAffinityColumns(join.Right, context, commonTableExpressions))
                .ToArray(),
            _ => throw new EmbeddedSqlException($"Unsupported table source {source.GetType().Name}."),
        };
    }

    private static IReadOnlyList<QueryAffinityColumn> DescribeViewAffinities(
        ViewDefinition view,
        QueryContext context,
        Dictionary<string, IReadOnlyList<QueryAffinityColumn>> commonTableExpressions)
    {
        var columns = DescribeQueryAffinities(view.Query, context, commonTableExpressions).ToArray();
        if (view.Columns is not { } declared)
            return columns;
        if (declared.Count != columns.Length)
            throw new EmbeddedSqlException($"expected {declared.Count} columns for {view.Name} but got {columns.Length}");

        return columns.Select((column, index) => column with { Name = declared[index] }).ToArray();
    }

    private static IReadOnlyList<QueryAffinityColumn> GetTableAffinityColumns(
        NamedTableSource source,
        Dictionary<string, EmbeddedTable> tables)
    {
        var table = GetTable(source, tables);
        return table.ColumnDefinitions
            .Select(column => new QueryAffinityColumn(
                source.Alias ?? source.Name,
                column.Name,
                table.GetColumnAffinity(column),
                // A column declared without a type name has no stored type for the
                // view-pragma walk to report; SQLite falls back to the affinity name
                // ("BLOB") for a view column that passes such a reference through.
                column.DeclaredType ?? "BLOB"))
            .ToArray();
    }

    private static IReadOnlyList<QueryAffinityColumn> QualifyAffinityColumns(
        IReadOnlyList<QueryAffinityColumn> columns,
        string? qualifier)
        => columns.Select(column => column with { Qualifier = qualifier }).ToArray();

    private static ColumnAffinity GetExpressionAffinity(
        Expression expression,
        IReadOnlyList<QueryAffinityColumn> sourceColumns,
        QueryContext context,
        Dictionary<string, IReadOnlyList<QueryAffinityColumn>> commonTableExpressions)
    {
        if (expression is CollationExpression collation)
        {
            return GetExpressionAffinity(
                collation.Expression,
                sourceColumns,
                context,
                commonTableExpressions);
        }
        if (expression is CastExpression cast)
            return EmbeddedTable.GetAffinity(cast.TypeName);
        if (expression is ScalarSubqueryExpression { Query: SelectStatement { Source: null } select }
            && select.Projections.Count == 1)
        {
            return GetExpressionAffinity(
                select.Projections[0].Expression,
                sourceColumns,
                context,
                commonTableExpressions);
        }
        if (expression is ScalarSubqueryExpression scalarSubquery)
        {
            var columns = DescribeQueryAffinities(
                scalarSubquery.Query,
                context,
                commonTableExpressions);
            return columns.Count == 1 ? columns[0].Affinity : ColumnAffinity.Blob;
        }
        if (expression is not ColumnExpression column)
            return ColumnAffinity.Blob;

        var name = column.UnqualifiedName ?? column.Name[(column.Name.LastIndexOf('.') + 1)..];
        var matches = sourceColumns.Where(candidate =>
            string.Equals(candidate.Name, name, StringComparison.OrdinalIgnoreCase)
            && (column.Qualifier is null
                || string.Equals(candidate.Qualifier, column.Qualifier, StringComparison.OrdinalIgnoreCase)))
            .ToArray();
        return matches.Length == 1 ? matches[0].Affinity : ColumnAffinity.Blob;
    }

    // Derives the declared-type string SQLite's table-valued PRAGMA functions report
    // for a view column, walking the projection expression exactly like
    // GetExpressionAffinity so names and types can never drift apart. Only plain
    // column references (source column's stored declared type, verbatim), CASTs
    // (affinity name of the cast type), COLLATE passthroughs, and single-column
    // scalar subqueries propagate a type; every other expression reports no type.
    private static string? GetExpressionDeclaredType(
        Expression expression,
        IReadOnlyList<QueryAffinityColumn> sourceColumns,
        QueryContext context,
        Dictionary<string, IReadOnlyList<QueryAffinityColumn>> commonTableExpressions)
    {
        if (expression is CollationExpression collation)
        {
            return GetExpressionDeclaredType(
                collation.Expression,
                sourceColumns,
                context,
                commonTableExpressions);
        }
        if (expression is CastExpression cast)
            return PragmaTypeName(EmbeddedTable.GetAffinity(cast.TypeName));
        if (expression is ScalarSubqueryExpression { Query: SelectStatement { Source: null } select }
            && select.Projections.Count == 1)
        {
            return GetExpressionDeclaredType(
                select.Projections[0].Expression,
                sourceColumns,
                context,
                commonTableExpressions);
        }
        if (expression is ScalarSubqueryExpression scalarSubquery)
        {
            var columns = DescribeQueryAffinities(
                scalarSubquery.Query,
                context,
                commonTableExpressions);
            return columns.Count == 1 ? columns[0].DeclaredType : null;
        }
        if (expression is not ColumnExpression column)
            return null;

        var name = column.UnqualifiedName ?? column.Name[(column.Name.LastIndexOf('.') + 1)..];
        var matches = sourceColumns.Where(candidate =>
            string.Equals(candidate.Name, name, StringComparison.OrdinalIgnoreCase)
            && (column.Qualifier is null
                || string.Equals(candidate.Qualifier, column.Qualifier, StringComparison.OrdinalIgnoreCase)))
            .ToArray();
        return matches.Length == 1 ? matches[0].DeclaredType : null;
    }

    private static string PragmaTypeName(ColumnAffinity affinity)
        => affinity switch
        {
            ColumnAffinity.Integer => "INT",
            ColumnAffinity.Numeric => "NUM",
            ColumnAffinity.Real => "REAL",
            ColumnAffinity.Text => "TEXT",
            _ => "BLOB",
        };

    private static string? CtasDeclaredType(ColumnAffinity affinity)
        => affinity switch
        {
            ColumnAffinity.Integer => "INT",
            ColumnAffinity.Numeric => "NUM",
            ColumnAffinity.Real => "REAL",
            ColumnAffinity.Text => "TEXT",
            ColumnAffinity.Blob => null,
            _ => throw new InvalidOperationException($"Unknown CTAS affinity {affinity}."),
        };

    private static string[] MakeCreateTableColumnNamesUnique(IReadOnlyList<string> names)
    {
        var result = new string[names.Count];
        var used = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        for (var index = 0; index < names.Count; index++)
        {
            var baseName = names[index];
            if (used.Add(baseName))
            {
                result[index] = baseName;
                continue;
            }

            var suffixBase = baseName;
            var suffix = BigInteger.One;
            var separator = baseName.LastIndexOf(':');
            if (separator > 0
                && BigInteger.TryParse(
                    baseName.AsSpan(separator + 1),
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out var existingSuffix))
            {
                suffixBase = baseName[..separator];
                suffix = existingSuffix + BigInteger.One;
            }

            string candidate;
            do
            {
                candidate = $"{suffixBase}:{suffix}";
                suffix += BigInteger.One;
            }
            while (!used.Add(candidate));
            result[index] = candidate;
        }

        return result;
    }

    private static string GetExpressionName(Expression expression)
    {
        return expression switch
        {
            ColumnExpression column => column.Name[(column.Name.LastIndexOf('.') + 1)..],
            ParameterExpression parameter => $"?{parameter.Index}",
            FunctionExpression function => function.Name,
            _ => expression.ToString() ?? string.Empty,
        };
    }

    private SqlValue Evaluate(
        Expression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        context.CheckInterrupt();
        var result = expression switch
        {
            LiteralExpression literal => literal.Value,
            CurrentTimeExpression current => current.Kind switch
            {
                CurrentTimeKind.Date => SqliteDateTime.Execute([], SqliteDateTime.Func.Date),
                CurrentTimeKind.Time => SqliteDateTime.Execute([], SqliteDateTime.Func.Time),
                CurrentTimeKind.Timestamp => SqliteDateTime.Execute([], SqliteDateTime.Func.DateTime),
                _ => throw new InvalidOperationException($"Unknown current-time kind {current.Kind}."),
            },
            ParameterExpression parameter => ReadParameter(parameters, parameter.Index),
            RowValueExpression => throw new EmbeddedSqlException("row value misused"),
            ColumnExpression column => EvaluateColumn(column, row, context),
            RaiseExpression raise => EvaluateRaise(raise, context),
            FunctionExpression function => EvaluateFunctionRespectingOuterAggregateScope(function, parameters, row, context),
            ScalarSubqueryExpression subquery => EvaluateScalarSubquery(subquery, parameters, row, context),
            ExistsExpression exists => EvaluateExists(exists, parameters, row, context),
            CollationExpression collation => Evaluate(collation.Expression, parameters, row, context),
            CastExpression cast => EvaluateCast(cast, parameters, row, context),
            CaseExpression @case => EvaluateCase(@case, parameters, row, context),
            LikeExpression like => EvaluateLike(like, parameters, row, context),
            GlobExpression glob => EvaluateGlob(glob, parameters, row, context),
            InExpression @in => EvaluateIn(@in, parameters, row, context),
            InSubqueryExpression @in => EvaluateInSubquery(@in, parameters, row, context),
            BetweenExpression between => EvaluateBetween(between, parameters, row, context),
            UnaryExpression unary => EvaluateUnary(unary, parameters, row, context),
            BinaryExpression binary => EvaluateBinary(binary, parameters, row, context),
            QualifiedStarExpression => throw new EmbeddedSqlException("row value misused"),
            _ => throw new EmbeddedSqlException($"Unsupported expression type {expression.GetType().Name}."),
        };
        context.CheckInterrupt();
        return result;
    }

    private static SqlValue EvaluateColumn(
        ColumnExpression column,
        SourceRow? row,
        QueryContext context)
    {
        if (TriggerRowFrame.IsTriggerQualifier(column.Qualifier))
        {
            if (row?.TryGetQualifiedValue(column, out var scopedValue) == true)
                return scopedValue;
            return context.TriggerRow?.GetValue(column)
                ?? throw new EmbeddedSqlException($"no such column: {column.Name}");
        }

        if (row is not null && row.TryGetValue(column, out var value))
            return value;

        // TRUE/FALSE are not reserved words: they only become the integer literals 1/0 once the
        // name fails to resolve against the columns in scope, exactly as SQLite does.
        if (column.BooleanKeyword is { } boolean)
            return SqlValue.Integer(boolean ? 1 : 0);

        throw new EmbeddedSqlException($"no such column: {column.Name}");
    }

    /// <summary>
    /// Reports whether <paramref name="expression"/> is the right-hand operand of an
    /// <c>IS [NOT] TRUE|FALSE</c> test, meaning a bare <c>TRUE</c>/<c>FALSE</c> keyword that does not
    /// resolve to a column. SQLite turns those comparisons into a truth test rather than an
    /// equality test, so <c>2 IS TRUE</c> is 1 while <c>2 IS 1</c> is 0.
    /// </summary>
    private static bool IsTruthKeyword(Expression expression, SourceRow? row, out bool expected)
    {
        if (UnwrapCollation(expression) is ColumnExpression { BooleanKeyword: { } keyword } column
            && (row is null || !row.TryGetValue(column, out _)))
        {
            expected = keyword;
            return true;
        }

        expected = false;
        return false;
    }

    /// <summary>
    /// Evaluates <c>X IS TRUE</c>, <c>X IS FALSE</c> and their negations, mirroring SQLite's
    /// <c>OP_IsTrue</c>: the result is never NULL, and NULL counts as neither true nor false.
    /// </summary>
    private SqlValue EvaluateTruthTest(
        BinaryExpression expression,
        bool expected,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var operand = Evaluate(expression.Left, parameters, row, context);
        var truth = operand.Kind == SqlValueKind.Null ? !expected : IsTrue(operand);
        var negate = expected ^ (expression.Operator == BinaryOperator.Is);
        return SqlValue.Integer(truth ^ negate ? 1 : 0);
    }

    private static SqlValue EvaluateRaise(RaiseExpression expression, QueryContext context)
    {
        var message = expression.Message ?? string.Empty;
        var error = new EmbeddedSqlException(message);
        throw expression.Action switch
        {
            RaiseAction.Ignore => new TriggerIgnoreException(),
            RaiseAction.Rollback => new EmbeddedConflictRollbackException(error),
            RaiseAction.Abort => error,
            RaiseAction.Fail => new EmbeddedConflictFailException(
                new EmbeddedTriggerRaiseException(message, InsertConflictAlgorithm.Fail),
                context.TriggerState?.LiveLastInsertRowId ?? context.LastInsertRowId),
            _ => new InvalidOperationException($"Unknown RAISE action {expression.Action}."),
        };
    }

    // Executes a subquery, reusing a memoized result when the subquery is provably
    // uncorrelated and deterministic. An uncorrelated subquery yields the same result for
    // every outer row; evaluating it once and caching the outcome collapses the
    // O(outer rows x inner scan) re-execution that made EF's BulkUpdates DELETEs hang.
    private ExecutionResult ExecuteSubquery(
        QueryStatement query,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var state = context.StatementState;
        // No statement state (DDL/validation), or a live trigger row whose NEW./OLD.
        // references resolve outside the outer-row chain the probe inspects: fall back to
        // per-row execution.
        if (state is null || context.TriggerRow is not null)
            return ExecuteQuery(query, parameters, context, row);

        if (state.MemoizedSubqueries.TryGetValue(query, out var entry))
        {
            if (entry.RevisionFingerprint == ComputeSubqueryRevisionFingerprint(context))
                return entry.Result;

            // Data changed since the memo was taken; the subquery is still uncorrelated, so
            // recompute it once (again with no outer row and no outer aggregate scope — a
            // scope-consuming subquery is never memoized) and refresh the memo.
            var recomputed = MaterializeSubqueryResult(ExecuteQuery(
                query,
                parameters,
                context with { OuterAggregateScope = null },
                outerRow: null));
            entry.Result = recomputed;
            entry.RevisionFingerprint = ComputeSubqueryRevisionFingerprint(context);
            return recomputed;
        }

        if (state.NonMemoizableSubqueries.Contains(query))
            return ExecuteQuery(query, parameters, context, row);

        if (!IsMemoizableSubquery(query))
        {
            state.NonMemoizableSubqueries.Add(query);
            return ExecuteQuery(query, parameters, context, row);
        }

        // Correlation probe: evaluate with no outer row and no outer aggregate scope. A
        // correlated column reference then fails to resolve ("no such column"), proving the
        // subquery depends on the outer row; a reference to an outer-block aggregate fails
        // as a scalar misuse, proving the subquery's value varies with the enclosing group.
        // Both kinds must evaluate per row/group, never from a cross-row memo. Any other
        // failure is reproduced by the fresh evaluation below, so catching broadly and
        // falling back stays sound either way.
        ExecutionResult probed;
        try
        {
            probed = MaterializeSubqueryResult(ExecuteQuery(
                query,
                parameters,
                context with { OuterAggregateScope = null },
                outerRow: null));
        }
        catch (EmbeddedSqlException)
        {
            state.NonMemoizableSubqueries.Add(query);
            return ExecuteQuery(query, parameters, context, row);
        }

        state.MemoizedSubqueries[query] = new SubqueryMemoEntry(probed, ComputeSubqueryRevisionFingerprint(context));
        return probed;
    }

    // Detaches a subquery result from the streaming projection state so the memoized value
    // can be re-read after the surrounding statement moves on. Row values are preserved
    // exactly (no JSON-subtype stripping); only the lazy wrapper is forced.
    private static ExecutionResult MaterializeSubqueryResult(ExecutionResult result)
        => result.Rows is StreamingProjectionRows
            ? result with { Rows = result.Rows.ToArray() }
            : result;

    private static long ComputeSubqueryRevisionFingerprint(QueryContext context)
    {
        // Revisions only increment, so a sum over the active catalog strictly increases on
        // any table mutation - a cheap sound guard against reusing a stale subquery result.
        long fingerprint = 0;
        foreach (var table in context.Tables.Values)
            fingerprint = unchecked(fingerprint + table.Rows.Revision);
        return fingerprint;
    }

    // Native SQLite resolves LIMIT/OFFSET in a scope with no columns: any direct column
    // reference fails prepare with "no such column: X", even an outer (correlated) one.
    // Columns nested inside a subquery within the LIMIT expression stay legal - they are
    // scoped by that subquery, which executes and validates on its own. Trigger bodies are
    // the one exception: NEW./OLD. pseudo-row references resolve against the trigger row,
    // which native treats as in scope for LIMIT/OFFSET too.
    private static void ValidateLimitOffsetColumnScope(QueryStatement statement, bool allowTriggerPseudoRows)
    {
        switch (statement)
        {
            case SelectStatement select:
                ThrowOnLimitOffsetColumnReference(select.Limit, allowTriggerPseudoRows);
                ThrowOnLimitOffsetColumnReference(select.Offset, allowTriggerPseudoRows);
                break;
            case CompoundSelectStatement compound:
                ThrowOnLimitOffsetColumnReference(compound.Limit, allowTriggerPseudoRows);
                ThrowOnLimitOffsetColumnReference(compound.Offset, allowTriggerPseudoRows);
                break;
        }
    }

    private static void ThrowOnLimitOffsetColumnReference(Expression? expression, bool allowTriggerPseudoRows)
    {
        if (expression is null)
            return;

        var pending = new Stack<object>();
        pending.Push(expression);
        while (pending.Count > 0)
        {
            switch (pending.Pop())
            {
                case ColumnExpression column:
                    if (allowTriggerPseudoRows
                        && column.Qualifier is not null
                        && (column.Qualifier.Equals("NEW", StringComparison.OrdinalIgnoreCase)
                            || column.Qualifier.Equals("OLD", StringComparison.OrdinalIgnoreCase)))
                        break;
                    throw new EmbeddedSqlException($"no such column: {column.Name}");
                case ScalarSubqueryExpression:
                case ExistsExpression:
                    break; // nested query scopes its own columns
                case InSubqueryExpression inSubquery:
                    pending.Push(inSubquery.Value);
                    break;
                case FunctionExpression function:
                    foreach (var argument in function.Arguments)
                        pending.Push(argument);
                    if (function.Filter is not null)
                        pending.Push(function.Filter);
                    break;
                case RowValueExpression rowValue:
                    foreach (var value in rowValue.Values)
                        pending.Push(value);
                    break;
                case CollationExpression collation:
                    pending.Push(collation.Expression);
                    break;
                case CastExpression cast:
                    pending.Push(cast.Expression);
                    break;
                case CaseExpression @case:
                    if (@case.Operand is not null)
                        pending.Push(@case.Operand);
                    foreach (var clause in @case.Clauses)
                    {
                        pending.Push(clause.When);
                        pending.Push(clause.Then);
                    }
                    if (@case.Else is not null)
                        pending.Push(@case.Else);
                    break;
                case LikeExpression like:
                    pending.Push(like.Value);
                    pending.Push(like.Pattern);
                    if (like.Escape is not null)
                        pending.Push(like.Escape);
                    break;
                case GlobExpression glob:
                    pending.Push(glob.Value);
                    pending.Push(glob.Pattern);
                    break;
                case InExpression @in:
                    pending.Push(@in.Value);
                    foreach (var value in @in.Values)
                        pending.Push(value);
                    break;
                case BetweenExpression between:
                    pending.Push(between.Value);
                    pending.Push(between.Lower);
                    pending.Push(between.Upper);
                    break;
                case UnaryExpression unary:
                    pending.Push(unary.Operand);
                    break;
                case BinaryExpression binary:
                    pending.Push(binary.Left);
                    pending.Push(binary.Right);
                    break;
                default:
                    break; // leaves and unknown nodes carry no column references to reject
            }
        }
    }

    // Statically classifies whether a subquery is deterministic over stable table data - a
    // precondition for memoization. Rejects non-deterministic built-ins and user functions,
    // wall-clock literals (CURRENT_DATE/TIME/TIMESTAMP), side-effecting RAISE, and
    // table-valued sources (pragma_*/json_each may be catalog- or connection-scoped).
    // Aggregates and window functions are allowed (stable over stable data).
    private static bool IsMemoizableSubquery(QueryStatement root)
    {
        var pending = new Stack<object>();
        pending.Push(root);
        while (pending.Count > 0)
        {
            switch (pending.Pop())
            {
                case SelectStatement select:
                    if (select.Source is not null)
                        pending.Push(select.Source);
                    foreach (var projection in select.Projections)
                        pending.Push(projection.Expression);
                    if (select.Where is not null)
                        pending.Push(select.Where);
                    foreach (var group in select.GroupBy)
                        pending.Push(group);
                    if (select.Having is not null)
                        pending.Push(select.Having);
                    foreach (var order in select.OrderBy)
                        pending.Push(order.Expression);
                    if (select.Limit is not null)
                        pending.Push(select.Limit);
                    if (select.Offset is not null)
                        pending.Push(select.Offset);
                    foreach (var window in select.NamedWindows)
                        PushWindowSpecification(pending, window.Specification);
                    break;
                case CompoundSelectStatement compound:
                    foreach (var term in compound.Terms)
                        pending.Push(term);
                    foreach (var order in compound.OrderBy)
                        pending.Push(order.Expression);
                    if (compound.Limit is not null)
                        pending.Push(compound.Limit);
                    if (compound.Offset is not null)
                        pending.Push(compound.Offset);
                    break;
                case WithSelectStatement with:
                    foreach (var cte in with.CommonTableExpressions)
                        pending.Push(cte.Query);
                    pending.Push(with.Query);
                    break;
                case ValuesClause values:
                    foreach (var valueRow in values.Rows)
                    foreach (var value in valueRow)
                        pending.Push(value);
                    break;
                case NamedTableSource:
                    break; // reads stable table data
                case TableValuedFunctionSource:
                    return false; // conservative: may be catalog- or connection-scoped
                case DerivedTableSource derived:
                    pending.Push(derived.Query);
                    break;
                case JoinTableSource join:
                    pending.Push(join.Left);
                    pending.Push(join.Right);
                    if (join.Condition is not null)
                        pending.Push(join.Condition);
                    break;
                case CurrentTimeExpression:
                case RaiseExpression:
                    return false; // wall-clock value / side-effecting control flow
                case FunctionExpression function:
                    if (!SqliteBuiltinFunctions.IsDeterministic(function.Name))
                        return false;
                    foreach (var argument in function.Arguments)
                        pending.Push(argument);
                    if (function.Filter is not null)
                        pending.Push(function.Filter);
                    if (function.Window is not null)
                        PushWindowSpecification(pending, function.Window);
                    break;
                case ScalarSubqueryExpression scalar:
                    pending.Push(scalar.Query);
                    break;
                case ExistsExpression exists:
                    pending.Push(exists.Query);
                    break;
                case InSubqueryExpression inSubquery:
                    pending.Push(inSubquery.Value);
                    pending.Push(inSubquery.Query);
                    break;
                case RowValueExpression rowValue:
                    foreach (var value in rowValue.Values)
                        pending.Push(value);
                    break;
                case CollationExpression collation:
                    pending.Push(collation.Expression);
                    break;
                case CastExpression cast:
                    pending.Push(cast.Expression);
                    break;
                case CaseExpression @case:
                    if (@case.Operand is not null)
                        pending.Push(@case.Operand);
                    foreach (var clause in @case.Clauses)
                    {
                        pending.Push(clause.When);
                        pending.Push(clause.Then);
                    }
                    if (@case.Else is not null)
                        pending.Push(@case.Else);
                    break;
                case LikeExpression like:
                    pending.Push(like.Value);
                    pending.Push(like.Pattern);
                    if (like.Escape is not null)
                        pending.Push(like.Escape);
                    break;
                case GlobExpression glob:
                    pending.Push(glob.Value);
                    pending.Push(glob.Pattern);
                    break;
                case InExpression @in:
                    pending.Push(@in.Value);
                    foreach (var value in @in.Values)
                        pending.Push(value);
                    break;
                case BetweenExpression between:
                    pending.Push(between.Value);
                    pending.Push(between.Lower);
                    pending.Push(between.Upper);
                    break;
                case UnaryExpression unary:
                    pending.Push(unary.Operand);
                    break;
                case BinaryExpression binary:
                    pending.Push(binary.Left);
                    pending.Push(binary.Right);
                    break;
                case LiteralExpression:
                case ParameterExpression:
                case ColumnExpression:
                case StarExpression:
                case QualifiedStarExpression:
                    break; // deterministic leaves; correlation is detected by the probe
                default:
                    return false; // unknown node: stay conservative
            }
        }

        return true;
    }

    private static void PushWindowSpecification(Stack<object> pending, WindowSpecification window)
    {
        foreach (var partition in window.PartitionBy)
            pending.Push(partition);
        foreach (var order in window.OrderBy)
            pending.Push(order.Expression);
        if (window.Frame is { } frame)
        {
            if (frame.Start.Offset is not null)
                pending.Push(frame.Start.Offset);
            if (frame.End.Offset is not null)
                pending.Push(frame.End.Offset);
        }
    }

    private SqlValue EvaluateScalarSubquery(
        ScalarSubqueryExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var result = ExecuteSubquery(expression.Query, parameters, row, context);
        RequireSingleColumnSubquery(result);
        return result.Rows.Count == 0 ? SqlValue.Null : result.Rows[0][0];
    }

    private SqlValue EvaluateExists(
        ExistsExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var exists = ExecuteSubquery(expression.Query, parameters, row, context).Rows.Count > 0;
        return SqlValue.Integer(exists == expression.Negated ? 0 : 1);
    }

    private SqlValue EvaluateInSubquery(
        InSubqueryExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var result = ExecuteSubquery(expression.Query, parameters, row, context);
        var valueCount = GetExpressionValueCount(expression.Value, context);
        if (result.Columns.Length != valueCount)
        {
            throw new EmbeddedSqlException(
                $"sub-select returns {result.Columns.Length} columns - expected {valueCount}");
        }

        var value = EvaluateExpressionValues(expression.Value, valueCount, parameters, row, context);
        return EvaluateInRows(
            value,
            result.Rows,
            expression.Value,
            candidateExpression: null,
            row,
            expression.Negated);
    }

    private static void RequireSingleColumnSubquery(ExecutionResult result)
    {
        if (result.Columns.Length != 1)
            throw new EmbeddedSqlException($"sub-select returns {result.Columns.Length} columns - expected 1");
    }

    private SqlValue EvaluateBinary(
        BinaryExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        if (IsComparisonOperator(expression.Operator))
            return EvaluateComparison(expression, parameters, row, context);

        var left = Evaluate(expression.Left, parameters, row, context);
        if (expression.Operator == BinaryOperator.And
            && left.Kind != SqlValueKind.Null
            && !IsTrue(left))
        {
            return SqlValue.Integer(0);
        }
        if (expression.Operator == BinaryOperator.Or
            && left.Kind != SqlValueKind.Null
            && IsTrue(left))
        {
            return SqlValue.Integer(1);
        }
        var right = Evaluate(expression.Right, parameters, row, context);
        var leftColumn = row?.GetColumnDefinition(expression.Left);
        var rightColumn = row?.GetColumnDefinition(expression.Right);
        if (IsComparisonOperator(expression.Operator))
            ApplyComparisonAffinities(leftColumn, rightColumn, ref left, ref right);
        return EvaluateBinaryValues(
            expression.Operator,
            left,
            right,
            GetComparisonCollation(expression.Left, expression.Right, context));
    }

    private SqlValue EvaluateComparison(
        BinaryExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        if (expression.Operator is BinaryOperator.Is or BinaryOperator.IsNot
            && IsTruthKeyword(expression.Right, row, out var expectedTruth))
        {
            return EvaluateTruthTest(expression, expectedTruth, parameters, row, context);
        }

        var leftCount = GetExpressionValueCount(expression.Left, context);
        var rightCount = GetExpressionValueCount(expression.Right, context);
        if (leftCount != rightCount)
            throw new EmbeddedSqlException("row value misused");

        SqlValue[]? leftSubqueryValues = null;
        SqlValue[]? rightSubqueryValues = null;
        if (expression.Left is ScalarSubqueryExpression leftSubquery)
        {
            leftSubqueryValues = EvaluateSubqueryValues(
                leftSubquery.Query,
                leftCount,
                parameters,
                row,
                context);
        }
        if (expression.Right is ScalarSubqueryExpression rightSubquery)
        {
            rightSubqueryValues = EvaluateSubqueryValues(
                rightSubquery.Query,
                rightCount,
                parameters,
                row,
                context);
        }

        var foundNull = false;
        for (var index = 0; index < leftCount; index++)
        {
            var left = EvaluateExpressionElement(
                expression.Left,
                index,
                leftCount,
                parameters,
                row,
                context,
                ref leftSubqueryValues);
            var right = EvaluateExpressionElement(
                expression.Right,
                index,
                rightCount,
                parameters,
                row,
                context,
                ref rightSubqueryValues);
            var leftElement = GetExpressionElement(expression.Left, index);
            var rightElement = GetExpressionElement(expression.Right, index);
            ApplyComparisonAffinities(leftElement, rightElement, row, ref left, ref right);
            var collation = GetComparisonCollation(leftElement, rightElement, row);

            if (expression.Operator is BinaryOperator.Is or BinaryOperator.IsNot)
            {
                var equal = left.Kind == SqlValueKind.Null || right.Kind == SqlValueKind.Null
                    ? left.Kind == right.Kind
                    : Compare(left, right, collation) == 0;
                if (!equal)
                    return SqlValue.Integer(expression.Operator == BinaryOperator.IsNot ? 1 : 0);
                continue;
            }

            if (left.Kind == SqlValueKind.Null || right.Kind == SqlValueKind.Null)
            {
                foundNull = true;
                if (expression.Operator is not (BinaryOperator.Equal or BinaryOperator.NotEqual))
                    return SqlValue.Null;
                continue;
            }

            var comparison = Compare(left, right, collation);
            if (expression.Operator is BinaryOperator.Equal or BinaryOperator.NotEqual)
            {
                if (comparison != 0)
                    return SqlValue.Integer(expression.Operator == BinaryOperator.NotEqual ? 1 : 0);
                continue;
            }

            if (comparison != 0)
                return EvaluateOrderingComparison(expression.Operator, comparison);
        }

        if (expression.Operator is BinaryOperator.Is or BinaryOperator.IsNot)
            return SqlValue.Integer(expression.Operator == BinaryOperator.Is ? 1 : 0);
        if (foundNull)
            return SqlValue.Null;
        if (expression.Operator is BinaryOperator.Equal or BinaryOperator.NotEqual)
            return SqlValue.Integer(expression.Operator == BinaryOperator.Equal ? 1 : 0);
        return EvaluateOrderingComparison(expression.Operator, comparison: 0);
    }

    private static SqlValue EvaluateOrderingComparison(BinaryOperator operation, int comparison)
    {
        var result = operation switch
        {
            BinaryOperator.LessThan => comparison < 0,
            BinaryOperator.LessThanOrEqual => comparison <= 0,
            BinaryOperator.GreaterThan => comparison > 0,
            BinaryOperator.GreaterThanOrEqual => comparison >= 0,
            _ => throw new EmbeddedSqlException($"Unsupported ordering operator {operation}."),
        };
        return SqlValue.Integer(result ? 1 : 0);
    }

    private static int GetExpressionValueCount(Expression expression, QueryContext context)
    {
        return expression switch
        {
            RowValueExpression rowValue => rowValue.Values.Count,
            ScalarSubqueryExpression subquery => DescribeQuery(subquery.Query, context).Length,
            _ => 1,
        };
    }

    private SqlValue EvaluateExpressionElement(
        Expression expression,
        int index,
        int count,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context,
        ref SqlValue[]? subqueryValues)
    {
        switch (expression)
        {
            case RowValueExpression rowValue:
                return Evaluate(rowValue.Values[index], parameters, row, context);
            case ScalarSubqueryExpression subquery:
                subqueryValues ??= EvaluateSubqueryValues(subquery.Query, count, parameters, row, context);
                return subqueryValues[index];
            default:
                if (index != 0 || count != 1)
                    throw new EmbeddedSqlException("row value misused");
                return Evaluate(expression, parameters, row, context);
        }
    }

    private SqlValue[] EvaluateSubqueryValues(
        QueryStatement query,
        int expectedCount,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var result = ExecuteSubquery(query, parameters, row, context);
        if (result.Columns.Length != expectedCount)
        {
            throw new EmbeddedSqlException(
                $"sub-select returns {result.Columns.Length} columns - expected {expectedCount}");
        }

        return result.Rows.Count == 0
            ? Enumerable.Repeat(SqlValue.Null, expectedCount).ToArray()
            : result.Rows[0].ToArray();
    }

    private static Expression GetExpressionElement(Expression expression, int index)
        => expression is RowValueExpression rowValue ? rowValue.Values[index] : expression;

    private static void ApplyComparisonAffinities(
        EmbeddedColumn? leftColumn,
        EmbeddedColumn? rightColumn,
        ref SqlValue left,
        ref SqlValue right)
    {
        var leftAffinity = leftColumn is null
            ? (ColumnAffinity?)null
            : EmbeddedTable.GetDeclaredColumnAffinity(leftColumn);
        var rightAffinity = rightColumn is null
            ? (ColumnAffinity?)null
            : EmbeddedTable.GetDeclaredColumnAffinity(rightColumn);
        if (leftAffinity is { } leftNumeric
            && IsNumericColumnAffinity(leftNumeric)
            && (rightAffinity is null || !IsNumericColumnAffinity(rightAffinity.Value)))
        {
            right = EmbeddedTable.ApplyColumnAffinity(leftNumeric, right);
        }
        else if (rightAffinity is { } rightNumeric
            && IsNumericColumnAffinity(rightNumeric)
            && (leftAffinity is null || !IsNumericColumnAffinity(leftAffinity.Value)))
        {
            left = EmbeddedTable.ApplyColumnAffinity(rightNumeric, left);
        }
        else if (leftAffinity == ColumnAffinity.Text && rightAffinity is null)
        {
            right = EmbeddedTable.ApplyColumnAffinity(ColumnAffinity.Text, right);
        }
        else if (rightAffinity == ColumnAffinity.Text && leftAffinity is null)
        {
            left = EmbeddedTable.ApplyColumnAffinity(ColumnAffinity.Text, left);
        }
    }
    private static bool IsNumericColumnAffinity(ColumnAffinity affinity)
        => affinity is ColumnAffinity.Integer or ColumnAffinity.Real or ColumnAffinity.Numeric;

    private SqlValue EvaluateBinaryValues(
        BinaryOperator operation,
        SqlValue left,
        SqlValue right,
        string? collation = null)
    {
        if (operation is BinaryOperator.Is or BinaryOperator.IsNot)
        {
            var equal = left.Kind == SqlValueKind.Null || right.Kind == SqlValueKind.Null
                ? left.Kind == right.Kind
                : Compare(left, right, collation) == 0;
            return SqlValue.Integer((operation == BinaryOperator.Is) == equal ? 1 : 0);
        }
        if (operation is BinaryOperator.And or BinaryOperator.Or)
            return ApplyLogical(operation, left, right);

        if (left.Kind == SqlValueKind.Null || right.Kind == SqlValueKind.Null)
            return SqlValue.Null;

        return operation switch
        {
            BinaryOperator.Add => ApplyNumeric(left, right, static (a, b) => checked(a + b), static (a, b) => a + b),
            BinaryOperator.Subtract => ApplyNumeric(left, right, static (a, b) => checked(a - b), static (a, b) => a - b),
            BinaryOperator.Multiply => ApplyNumeric(left, right, static (a, b) => checked(a * b), static (a, b) => a * b),
            BinaryOperator.Divide => ApplyDivision(left, right),
            BinaryOperator.Modulo => ApplyModulo(left, right),
            BinaryOperator.BitwiseAnd => ApplyBitwise(left, right, and: true),
            BinaryOperator.BitwiseOr => ApplyBitwise(left, right, and: false),
            BinaryOperator.ShiftLeft => ApplyShift(left, right, leftShift: true),
            BinaryOperator.ShiftRight => ApplyShift(left, right, leftShift: false),
            BinaryOperator.Concatenate => ApplyConcatenation(left, right),
            BinaryOperator.JsonArrow => SqliteJson.JsonArrow(left, right, textResult: false),
            BinaryOperator.JsonArrowText => SqliteJson.JsonArrow(left, right, textResult: true),
            BinaryOperator.Equal => SqlValue.Integer(Compare(left, right, collation) == 0 ? 1 : 0),
            BinaryOperator.NotEqual => SqlValue.Integer(Compare(left, right, collation) != 0 ? 1 : 0),
            BinaryOperator.LessThan => SqlValue.Integer(Compare(left, right, collation) < 0 ? 1 : 0),
            BinaryOperator.LessThanOrEqual => SqlValue.Integer(Compare(left, right, collation) <= 0 ? 1 : 0),
            BinaryOperator.GreaterThan => SqlValue.Integer(Compare(left, right, collation) > 0 ? 1 : 0),
            BinaryOperator.GreaterThanOrEqual => SqlValue.Integer(Compare(left, right, collation) >= 0 ? 1 : 0),
            _ => throw new EmbeddedSqlException($"Unsupported binary operator {operation}."),
        };
    }

    private SqlValue EvaluateUnary(
        UnaryExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var value = Evaluate(expression.Operand, parameters, row, context);
        return EvaluateUnaryValue(expression.Operator, value);
    }

    private static SqlValue EvaluateUnaryValue(UnaryOperator operation, SqlValue value)
    {
        return operation switch
        {
            UnaryOperator.Not => value.Kind == SqlValueKind.Null
                ? SqlValue.Null
                : SqlValue.Integer(IsTrue(value) ? 0 : 1),
            UnaryOperator.Plus => value,
            UnaryOperator.Negate => value.Kind == SqlValueKind.Null
                ? SqlValue.Null
                : VdbeArithmetic.Evaluate(
                    ArithmeticOperator.Negate,
                    [ApplyNumericAffinity(value)]),
            UnaryOperator.BitwiseNot => value.Kind == SqlValueKind.Null
                ? SqlValue.Null
                : SqlValue.Integer(~ToPrintfInteger(value)),
            _ => throw new EmbeddedSqlException($"Unsupported unary operator {operation}."),
        };
    }

    private SqlValue EvaluateCast(
        CastExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
        => CastValue(Evaluate(expression.Expression, parameters, row, context), expression.TypeName);

    private SqlValue EvaluateCase(
        CaseExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        SqlValue[]? operand = null;
        var operandCount = 0;
        if (expression.Operand is not null)
        {
            operandCount = GetExpressionValueCount(expression.Operand, context);
            operand = EvaluateExpressionValues(
                expression.Operand,
                operandCount,
                parameters,
                row,
                context);
        }

        foreach (var clause in expression.Clauses)
        {
            var matches = operand is null
                ? IsTrue(Evaluate(clause.When, parameters, row, context))
                : EvaluateMaterializedExpressionComparison(
                    BinaryOperator.Equal,
                    operand,
                    expression.Operand!,
                    clause.When,
                    parameters,
                    row,
                    context) is { Kind: SqlValueKind.Integer } equality
                    && equality.AsInteger() != 0;
            if (matches)
                return Evaluate(clause.Then, parameters, row, context);
        }

        return expression.Else is null
            ? SqlValue.Null
            : Evaluate(expression.Else, parameters, row, context);
    }

    internal static SqlValue CastValue(SqlValue value, string typeName)
    {
        if (value.Kind == SqlValueKind.Null)
            return SqlValue.Null;

        typeName = typeName.ToUpperInvariant();
        if (typeName.Contains("INT", StringComparison.Ordinal))
        {
            var numeric = ApplyNumericAffinity(value);
            return numeric.Kind switch
            {
                SqlValueKind.Integer => numeric,
                SqlValueKind.Real => SqlValue.Integer((long)Math.Clamp(
                    Math.Truncate(numeric.AsReal()),
                    long.MinValue,
                    long.MaxValue)),
                _ => throw new InvalidOperationException($"Unexpected numeric value {numeric.Kind}."),
            };
        }
        if (typeName is "REAL" or "FLOAT" or "DOUBLE"
            || typeName.Contains("REAL", StringComparison.Ordinal)
            || typeName.Contains("FLOA", StringComparison.Ordinal)
            || typeName.Contains("DOUB", StringComparison.Ordinal))
        {
            var numeric = ApplyNumericAffinity(value);
            return numeric.Kind == SqlValueKind.Real
                ? numeric
                : SqlValue.Real(numeric.AsInteger());
        }
        if (typeName is "NUMERIC" or "DECIMAL" or "BOOLEAN" or "DATE" or "DATETIME"
            || typeName.Contains("NUM", StringComparison.Ordinal)
            || typeName.Contains("DEC", StringComparison.Ordinal)
            || typeName.Contains("BOOL", StringComparison.Ordinal)
            || typeName.Contains("DATE", StringComparison.Ordinal))
        {
            return CastToNumeric(value);
        }
        if (typeName is "BLOB" or "NONE")
            return value.Kind == SqlValueKind.Blob
                ? value
                : SqlValue.Blob(System.Text.Encoding.UTF8.GetBytes(ToSqlText(value)));

        return value.Kind == SqlValueKind.Text
            ? value
            : SqlValue.Text(ToSqlText(value));
    }

    private SqlValue EvaluateLike(
        LikeExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var value = Evaluate(expression.Value, parameters, row, context);
        var pattern = Evaluate(expression.Pattern, parameters, row, context);
        var escape = expression.Escape is null
            ? (SqlValue?)null
            : Evaluate(expression.Escape, parameters, row, context);
        return EvaluateLikeValues(value, pattern, escape, expression.Negated);
    }

    private static SqlValue EvaluateLikeValues(SqlValue value, SqlValue pattern, SqlValue? escapeValue, bool negated)
    {
        if (value.Kind == SqlValueKind.Null || pattern.Kind == SqlValueKind.Null)
            return SqlValue.Null;

        char? escape = null;
        if (escapeValue is not null)
        {
            if (escapeValue.Value.Kind == SqlValueKind.Null)
                return SqlValue.Null;

            var escapeText = ToSqlText(escapeValue.Value);
            if (escapeText.Length != 1)
                throw new EmbeddedSqlException("ESCAPE expression must be a single character");
            escape = escapeText[0];
        }

        var matches = IsLikeMatch(ToSqlText(value), ToSqlText(pattern), escape);
        return SqlValue.Integer(matches == negated ? 0 : 1);
    }

    private SqlValue EvaluateGlob(
        GlobExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var value = Evaluate(expression.Value, parameters, row, context);
        var pattern = Evaluate(expression.Pattern, parameters, row, context);
        return EvaluateGlobValues(value, pattern, expression.Negated);
    }

    private static SqlValue EvaluateGlobValues(SqlValue value, SqlValue pattern, bool negated)
    {
        if (value.Kind == SqlValueKind.Null || pattern.Kind == SqlValueKind.Null)
            return SqlValue.Null;

        var matches = IsGlobMatch(ToSqlText(value), ToSqlText(pattern));
        return SqlValue.Integer(matches == negated ? 0 : 1);
    }

    private static int[] ToCodePoints(string text)
    {
        var result = new List<int>(text.Length);
        for (var index = 0; index < text.Length; index++)
        {
            if (char.IsHighSurrogate(text[index])
                && index + 1 < text.Length
                && char.IsLowSurrogate(text[index + 1]))
            {
                result.Add(char.ConvertToUtf32(text[index], text[index + 1]));
                index++;
            }
            else
            {
                result.Add(text[index]);
            }
        }

        return result.ToArray();
    }

    private static bool IsGlobMatch(string text, string pattern)
    {
        return GlobMatch(ToCodePoints(pattern), 0, ToCodePoints(text), 0);
    }

    private static bool GlobMatch(int[] pattern, int patternIndex, int[] text, int textIndex)
    {
        while (patternIndex < pattern.Length)
        {
            var patternChar = pattern[patternIndex];
            if (patternChar == '*')
            {
                patternIndex++;
                while (patternIndex < pattern.Length && (pattern[patternIndex] == '*' || pattern[patternIndex] == '?'))
                {
                    if (pattern[patternIndex] == '?')
                    {
                        if (textIndex >= text.Length)
                            return false;

                        textIndex++;
                    }

                    patternIndex++;
                }

                if (patternIndex == pattern.Length)
                    return true;

                for (var scan = textIndex; scan <= text.Length; scan++)
                {
                    if (GlobMatch(pattern, patternIndex, text, scan))
                        return true;
                }

                return false;
            }

            if (patternChar == '?')
            {
                if (textIndex >= text.Length)
                    return false;

                textIndex++;
                patternIndex++;
                continue;
            }

            if (patternChar == '[')
            {
                if (textIndex >= text.Length)
                    return false;

                var (matched, nextIndex) = MatchGlobSet(pattern, patternIndex, text[textIndex]);
                if (nextIndex < 0)
                    return false;

                if (!matched)
                    return false;

                textIndex++;
                patternIndex = nextIndex;
                continue;
            }

            if (textIndex >= text.Length || text[textIndex] != patternChar)
                return false;

            textIndex++;
            patternIndex++;
        }

        return textIndex == text.Length;
    }

    private static (bool Matched, int NextIndex) MatchGlobSet(int[] pattern, int start, int ch)
    {
        var index = start + 1;
        var invert = false;
        if (index < pattern.Length && pattern[index] == '^')
        {
            invert = true;
            index++;
        }

        var matched = false;
        var first = true;
        while (index < pattern.Length)
        {
            var current = pattern[index];
            if (current == ']' && !first)
                return (invert ? !matched : matched, index + 1);

            first = false;
            if (index + 2 < pattern.Length && pattern[index + 1] == '-' && pattern[index + 2] != ']')
            {
                if (ch >= current && ch <= pattern[index + 2])
                    matched = true;

                index += 3;
            }
            else
            {
                if (ch == current)
                    matched = true;

                index++;
            }
        }

        return (false, -1);
    }

    private SqlValue EvaluateIn(
        InExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        if (expression.Values.Count == 0)
            return SqlValue.Integer(expression.Negated ? 1 : 0);

        var valueCount = GetExpressionValueCount(expression.Value, context);
        if (valueCount == 1
            && expression.Values.All(candidate => GetExpressionValueCount(candidate, context) == 1))
        {
            return EvaluateScalarIn(expression, parameters, row, context);
        }

        var candidateRows = new List<SqlValue[]>(expression.Values.Count);
        foreach (var candidate in expression.Values)
        {
            var candidateCount = GetExpressionValueCount(candidate, context);
            if (valueCount == 1 || candidateCount == 1 && valueCount != 1)
            {
                if (valueCount == 1)
                    throw new EmbeddedSqlException("row value misused");
                throw new EmbeddedSqlException($"IN(...) element has {candidateCount} term - expected {valueCount}");
            }
            if (candidateCount != valueCount)
            {
                throw new EmbeddedSqlException(
                    $"IN(...) element has {candidateCount} terms - expected {valueCount}");
            }

            candidateRows.Add(EvaluateExpressionValues(candidate, valueCount, parameters, row, context));
        }

        var valueRow = EvaluateExpressionValues(expression.Value, valueCount, parameters, row, context);
        return EvaluateInRows(
            valueRow,
            candidateRows,
            expression.Value,
            expression.Values[^1],
            row,
            expression.Negated);
    }

    private SqlValue[] EvaluateExpressionValues(
        Expression expression,
        int expectedCount,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var actualCount = GetExpressionValueCount(expression, context);
        if (actualCount != expectedCount)
            throw new EmbeddedSqlException($"{expectedCount} columns assigned {actualCount} values");

        switch (expression)
        {
            case RowValueExpression rowValue:
                return rowValue.Values.Select(value => Evaluate(value, parameters, row, context)).ToArray();
            case ScalarSubqueryExpression subquery:
                return EvaluateSubqueryValues(subquery.Query, expectedCount, parameters, row, context);
            default:
                return [Evaluate(expression, parameters, row, context)];
        }
    }

    private SqlValue EvaluateScalarIn(
        InExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var value = Evaluate(expression.Value, parameters, row, context);
        var valueIsNull = value.Kind == SqlValueKind.Null;
        var foundNull = false;
        var collation = GetEffectiveCollation(expression.Value, context);
        foreach (var candidateExpression in expression.Values)
        {
            var candidate = Evaluate(candidateExpression, parameters, row, context);
            if (valueIsNull)
                continue;
            if (candidate.Kind == SqlValueKind.Null)
            {
                foundNull = true;
                continue;
            }

            ApplyInComparisonAffinity(expression.Value, row, ref candidate);
            if (Compare(value, candidate, collation) == 0)
                return SqlValue.Integer(expression.Negated ? 0 : 1);
        }

        if (valueIsNull || foundNull)
            return SqlValue.Null;
        return SqlValue.Integer(expression.Negated ? 1 : 0);
    }

    private static void ApplyInComparisonAffinity(
        Expression valueExpression,
        SourceRow? row,
        ref SqlValue candidate)
    {
        var affinity = GetComparisonAffinity(valueExpression, row);
        if (IsNumericAffinity(affinity))
            candidate = ApplyComparisonNumericAffinity(candidate);
        else if (affinity == ColumnAffinity.Text)
            candidate = ApplyComparisonTextAffinity(candidate);
    }

    private SqlValue EvaluateInRows(
        IReadOnlyList<SqlValue> value,
        IEnumerable<IReadOnlyList<SqlValue>> candidates,
        Expression valueExpression,
        Expression? candidateExpression,
        SourceRow? row,
        bool negated)
    {
        var foundNull = false;
        foreach (var candidate in candidates)
        {
            var equality = EvaluateMaterializedComparison(
                BinaryOperator.Equal,
                value,
                candidate,
                valueExpression,
                candidateExpression,
                row);
            if (equality.Kind == SqlValueKind.Null)
            {
                foundNull = true;
                continue;
            }
            if (equality.AsInteger() != 0)
                return SqlValue.Integer(negated ? 0 : 1);
        }

        if (foundNull)
            return SqlValue.Null;
        return SqlValue.Integer(negated ? 1 : 0);
    }

    private SqlValue EvaluateMaterializedComparison(
        BinaryOperator operation,
        IReadOnlyList<SqlValue> left,
        IReadOnlyList<SqlValue> right,
        Expression leftExpression,
        Expression? rightExpression,
        SourceRow? row)
    {
        if (left.Count != right.Count)
            throw new EmbeddedSqlException("row value misused");

        var isOperator = operation is BinaryOperator.Is or BinaryOperator.IsNot;
        var foundNull = false;
        for (var index = 0; index < left.Count; index++)
        {
            var leftValue = left[index];
            var rightValue = right[index];
            if (leftValue.Kind == SqlValueKind.Null || rightValue.Kind == SqlValueKind.Null)
            {
                if (isOperator)
                {
                    if (leftValue.Kind != rightValue.Kind)
                        return SqlValue.Integer(operation == BinaryOperator.IsNot ? 1 : 0);
                    continue;
                }

                foundNull = true;
                if (operation is not (BinaryOperator.Equal or BinaryOperator.NotEqual))
                    return SqlValue.Null;
                continue;
            }

            var leftElement = GetExpressionElement(leftExpression, index);
            var rightElement = rightExpression is null
                ? null
                : GetExpressionElement(rightExpression, index);
            ApplyComparisonAffinities(leftElement, rightElement, row, ref leftValue, ref rightValue);
            var collation = GetComparisonCollation(leftElement, rightElement, row);
            var comparison = Compare(leftValue, rightValue, collation);
            if (operation is BinaryOperator.Equal or BinaryOperator.NotEqual || isOperator)
            {
                if (comparison != 0)
                    return SqlValue.Integer(
                        operation is BinaryOperator.NotEqual or BinaryOperator.IsNot ? 1 : 0);
                continue;
            }
            if (comparison != 0)
                return EvaluateOrderingComparison(operation, comparison);
        }

        if (foundNull)
            return SqlValue.Null;
        if (operation is BinaryOperator.Equal or BinaryOperator.NotEqual || isOperator)
        {
            return SqlValue.Integer(
                operation is BinaryOperator.Equal or BinaryOperator.Is ? 1 : 0);
        }
        return EvaluateOrderingComparison(operation, comparison: 0);
    }

    private SqlValue EvaluateBetween(
        BetweenExpression expression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var valueCount = GetExpressionValueCount(expression.Value, context);
        var lowerCount = GetExpressionValueCount(expression.Lower, context);
        var upperCount = GetExpressionValueCount(expression.Upper, context);
        if (valueCount != lowerCount || valueCount != upperCount)
            throw new EmbeddedSqlException("row value misused");
        if (valueCount == 1)
        {
            var value = Evaluate(expression.Value, parameters, row, context);
            var lower = Evaluate(expression.Lower, parameters, row, context);
            var upper = Evaluate(expression.Upper, parameters, row, context);
            var lowerValue = value;
            var upperValue = value;
            ApplyComparisonAffinities(
                expression.Value,
                expression.Lower,
                row,
                ref lowerValue,
                ref lower);
            ApplyComparisonAffinities(
                expression.Value,
                expression.Upper,
                row,
                ref upperValue,
                ref upper);
            return EvaluateBetweenValues(
                lowerValue,
                lower,
                upperValue,
                upper,
                expression.Negated,
                GetComparisonCollation(expression.Value, expression.Lower, context),
                GetComparisonCollation(expression.Value, expression.Upper, context));
        }

        var valueRow = EvaluateExpressionValues(expression.Value, valueCount, parameters, row, context);
        var result = ApplyLogical(
            BinaryOperator.And,
            EvaluateMaterializedExpressionComparison(
                BinaryOperator.GreaterThanOrEqual,
                valueRow,
                expression.Value,
                expression.Lower,
                parameters,
                row,
                context),
            EvaluateMaterializedExpressionComparison(
                BinaryOperator.LessThanOrEqual,
                valueRow,
                expression.Value,
                expression.Upper,
                parameters,
                row,
                context));
        if (result.Kind == SqlValueKind.Null || !expression.Negated)
            return result;
        return SqlValue.Integer(result.AsInteger() == 0 ? 1 : 0);
    }

    private SqlValue EvaluateMaterializedExpressionComparison(
        BinaryOperator operation,
        IReadOnlyList<SqlValue> left,
        Expression leftExpression,
        Expression rightExpression,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        var rightCount = GetExpressionValueCount(rightExpression, context);
        if (left.Count != rightCount)
            throw new EmbeddedSqlException("row value misused");

        SqlValue[]? rightSubqueryValues = rightExpression is ScalarSubqueryExpression subquery
            ? EvaluateSubqueryValues(subquery.Query, rightCount, parameters, row, context)
            : null;
        var foundNull = false;
        var isOperator = operation is BinaryOperator.Is or BinaryOperator.IsNot;
        for (var index = 0; index < left.Count; index++)
        {
            var leftValue = left[index];
            var rightValue = EvaluateExpressionElement(
                rightExpression,
                index,
                rightCount,
                parameters,
                row,
                context,
                ref rightSubqueryValues);
            var leftElement = GetExpressionElement(leftExpression, index);
            var rightElement = GetExpressionElement(rightExpression, index);
            ApplyComparisonAffinities(leftElement, rightElement, row, ref leftValue, ref rightValue);
            if (leftValue.Kind == SqlValueKind.Null || rightValue.Kind == SqlValueKind.Null)
            {
                if (isOperator)
                {
                    if (leftValue.Kind != rightValue.Kind)
                        return SqlValue.Integer(operation == BinaryOperator.IsNot ? 1 : 0);
                    continue;
                }

                foundNull = true;
                if (operation is not (BinaryOperator.Equal or BinaryOperator.NotEqual))
                    return SqlValue.Null;
                continue;
            }

            var comparison = Compare(
                leftValue,
                rightValue,
                GetComparisonCollation(leftElement, rightElement, row));
            if (comparison != 0)
            {
                if (operation is BinaryOperator.Equal or BinaryOperator.NotEqual || isOperator)
                {
                    return SqlValue.Integer(
                        operation is BinaryOperator.NotEqual or BinaryOperator.IsNot ? 1 : 0);
                }

                return EvaluateOrderingComparison(operation, comparison);
            }
        }

        if (foundNull)
            return SqlValue.Null;
        if (operation is BinaryOperator.Equal or BinaryOperator.NotEqual || isOperator)
        {
            return SqlValue.Integer(
                operation is BinaryOperator.Equal or BinaryOperator.Is ? 1 : 0);
        }
        return EvaluateOrderingComparison(operation, comparison: 0);
    }

    private SqlValue EvaluateBetweenValues(
        SqlValue lowerValue,
        SqlValue lower,
        SqlValue upperValue,
        SqlValue upper,
        bool negated,
        string? lowerCollation = null,
        string? upperCollation = null)
    {
        var result = EvaluateBinaryValues(
            BinaryOperator.And,
            EvaluateBinaryValues(
                BinaryOperator.GreaterThanOrEqual,
                lowerValue,
                lower,
                lowerCollation),
            EvaluateBinaryValues(
                BinaryOperator.LessThanOrEqual,
                upperValue,
                upper,
                upperCollation));
        if (result.Kind == SqlValueKind.Null || !negated)
            return result;

        return SqlValue.Integer(result.AsInteger() == 0 ? 1 : 0);
    }

    private static bool IsLikeMatch(string value, string pattern, char? escape)
    {
        var valueIndex = 0;
        var patternIndex = 0;
        var wildcardIndex = -1;
        var wildcardMatchIndex = 0;

        while (valueIndex < value.Length)
        {
            if (patternIndex < pattern.Length && escape is not null && pattern[patternIndex] == escape)
            {
                patternIndex++;
                if (patternIndex < pattern.Length && LikeCharactersEqual(value[valueIndex], pattern[patternIndex]))
                {
                    valueIndex++;
                    patternIndex++;
                    continue;
                }
            }
            else if (patternIndex < pattern.Length && pattern[patternIndex] == '_')
            {
                valueIndex++;
                patternIndex++;
                continue;
            }
            else if (patternIndex < pattern.Length && pattern[patternIndex] == '%')
            {
                wildcardIndex = patternIndex++;
                wildcardMatchIndex = valueIndex;
                continue;
            }
            else if (patternIndex < pattern.Length && LikeCharactersEqual(value[valueIndex], pattern[patternIndex]))
            {
                valueIndex++;
                patternIndex++;
                continue;
            }

            if (wildcardIndex < 0)
                return false;

            patternIndex = wildcardIndex + 1;
            valueIndex = ++wildcardMatchIndex;
        }

        while (patternIndex < pattern.Length && pattern[patternIndex] == '%')
            patternIndex++;

        return patternIndex == pattern.Length;
    }

    private static bool LikeCharactersEqual(char left, char right)
    {
        return left == right
            || left <= 127 && right <= 127 && char.ToUpperInvariant(left) == char.ToUpperInvariant(right);
    }

    private static SqlValue ApplyLogical(BinaryOperator operation, SqlValue left, SqlValue right)
    {
        if (operation == BinaryOperator.And)
        {
            if (left.Kind != SqlValueKind.Null && !IsTrue(left)
                || right.Kind != SqlValueKind.Null && !IsTrue(right))
            {
                return SqlValue.Integer(0);
            }

            return left.Kind == SqlValueKind.Null || right.Kind == SqlValueKind.Null
                ? SqlValue.Null
                : SqlValue.Integer(1);
        }

        if (left.Kind != SqlValueKind.Null && IsTrue(left)
            || right.Kind != SqlValueKind.Null && IsTrue(right))
        {
            return SqlValue.Integer(1);
        }

        return left.Kind == SqlValueKind.Null || right.Kind == SqlValueKind.Null
            ? SqlValue.Null
            : SqlValue.Integer(0);
    }

    private bool ContainsAggregate(Expression expression)
    {
        return expression switch
        {
            FunctionExpression function when function.Window is not null => false,
            FunctionExpression function when IsBuiltInAggregate(function) => true,
            FunctionExpression function => IsManagedPercentileAggregate(function.Name)
                || TryGetAggregateFunction(function.Name, function.Arguments.Count, out _)
                || function.Arguments.Any(ContainsAggregate),
            RowValueExpression rowValue => rowValue.Values.Any(ContainsAggregate),
            UnaryExpression unary => ContainsAggregate(unary.Operand),
            BinaryExpression binary => ContainsAggregate(binary.Left) || ContainsAggregate(binary.Right),
            CollationExpression collation => ContainsAggregate(collation.Expression),
            CastExpression cast => ContainsAggregate(cast.Expression),
            CaseExpression @case => (@case.Operand is not null && ContainsAggregate(@case.Operand))
                || @case.Clauses.Any(clause => ContainsAggregate(clause.When) || ContainsAggregate(clause.Then))
                || @case.Else is not null && ContainsAggregate(@case.Else),
            LikeExpression like => ContainsAggregate(like.Value)
                || ContainsAggregate(like.Pattern)
                || like.Escape is not null && ContainsAggregate(like.Escape),
            GlobExpression glob => ContainsAggregate(glob.Value) || ContainsAggregate(glob.Pattern),
            InExpression @in => ContainsAggregate(@in.Value) || @in.Values.Any(ContainsAggregate),
            InSubqueryExpression @in => ContainsAggregate(@in.Value),
            BetweenExpression between => ContainsAggregate(between.Value)
                || ContainsAggregate(between.Lower)
                || ContainsAggregate(between.Upper),
            _ => false,
        };
    }

    private bool IsAggregateExpression(Expression expression)
    {
        return expression switch
        {
            FunctionExpression function when function.Window is not null => false,
            FunctionExpression function when IsBuiltInAggregate(function) => true,
            FunctionExpression function => IsManagedPercentileAggregate(function.Name)
                || TryGetAggregateFunction(function.Name, function.Arguments.Count, out _),
            LiteralExpression or ParameterExpression or ScalarSubqueryExpression or ExistsExpression => true,
            RowValueExpression rowValue => rowValue.Values.All(IsAggregateExpression),
            BinaryExpression binary => IsAggregateExpression(binary.Left) && IsAggregateExpression(binary.Right),
            CollationExpression collation => IsAggregateExpression(collation.Expression),
            CastExpression cast => IsAggregateExpression(cast.Expression),
            CaseExpression @case => (@case.Operand is null || IsAggregateExpression(@case.Operand))
                && @case.Clauses.All(clause => IsAggregateExpression(clause.When) && IsAggregateExpression(clause.Then))
                && (@case.Else is null || IsAggregateExpression(@case.Else)),
            LikeExpression like => IsAggregateExpression(like.Value)
                && IsAggregateExpression(like.Pattern)
                && (like.Escape is null || IsAggregateExpression(like.Escape)),
            GlobExpression glob => IsAggregateExpression(glob.Value) && IsAggregateExpression(glob.Pattern),
            InExpression @in => IsAggregateExpression(@in.Value) && @in.Values.All(IsAggregateExpression),
            InSubqueryExpression @in => IsAggregateExpression(@in.Value),
            BetweenExpression between => IsAggregateExpression(between.Value)
                && IsAggregateExpression(between.Lower)
                && IsAggregateExpression(between.Upper),
            _ => false,
        };
    }

    private SourceRow? GetAggregateRepresentative(
        SelectStatement statement,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (rows.Count == 0)
            return null;

        FunctionExpression? controllingExtremum = null;
        foreach (var projection in statement.Projections)
            controllingExtremum = FindLastExtremumAggregate(projection.Expression) ?? controllingExtremum;
        foreach (var term in statement.OrderBy)
            controllingExtremum = FindLastExtremumAggregate(term.Expression) ?? controllingExtremum;
        if (statement.Having is not null)
            controllingExtremum = FindLastExtremumAggregate(statement.Having) ?? controllingExtremum;

        if (controllingExtremum is null)
            return rows[0];

        var effectiveRows = ApplyAggregateModifiers(controllingExtremum, rows, parameters, context);
        if (effectiveRows.Count == 0)
            return rows[0];

        var maximum = controllingExtremum.Name == "MAX";
        var collation = GetEffectiveCollation(controllingExtremum.Arguments[0], context);
        var extreme = SqlValue.Null;
        SourceRow? representative = null;
        foreach (var row in effectiveRows)
        {
            context.CheckInterrupt();
            var value = Evaluate(controllingExtremum.Arguments[0], parameters, row, context);
            if (value.Kind == SqlValueKind.Null)
                continue;

            if (representative is null
                || (maximum
                    ? Compare(value, extreme, collation) > 0
                    : Compare(value, extreme, collation) < 0))
            {
                extreme = value;
                representative = row;
            }
        }

        // SQLite visits every row for an all-NULL min/max and leaves the final row selected.
        return representative ?? effectiveRows[^1];
    }

    private static FunctionExpression? FindLastExtremumAggregate(Expression? expression)
    {
        return expression switch
        {
            FunctionExpression { Window: null, Name: "MIN" or "MAX", Arguments.Count: 1 } function
                => function,
            FunctionExpression { Window: null } function => function.Arguments
                .Reverse()
                .Select(FindLastExtremumAggregate)
                .FirstOrDefault(aggregate => aggregate is not null),
            RowValueExpression rowValue => rowValue.Values
                .Reverse()
                .Select(FindLastExtremumAggregate)
                .FirstOrDefault(aggregate => aggregate is not null),
            UnaryExpression unary => FindLastExtremumAggregate(unary.Operand),
            BinaryExpression binary => FindLastExtremumAggregate(binary.Right)
                ?? FindLastExtremumAggregate(binary.Left),
            CollationExpression collation => FindLastExtremumAggregate(collation.Expression),
            CastExpression cast => FindLastExtremumAggregate(cast.Expression),
            CaseExpression @case => FindLastExtremumAggregate(@case.Else)
                ?? @case.Clauses
                    .Reverse()
                    .Select(clause => FindLastExtremumAggregate(clause.Then)
                        ?? FindLastExtremumAggregate(clause.When))
                    .FirstOrDefault(function => function is not null)
                ?? FindLastExtremumAggregate(@case.Operand),
            LikeExpression like => FindLastExtremumAggregate(like.Escape)
                ?? FindLastExtremumAggregate(like.Pattern)
                ?? FindLastExtremumAggregate(like.Value),
            GlobExpression glob => FindLastExtremumAggregate(glob.Pattern)
                ?? FindLastExtremumAggregate(glob.Value),
            InExpression @in => @in.Values
                    .Reverse()
                    .Select(FindLastExtremumAggregate)
                    .FirstOrDefault(function => function is not null)
                ?? FindLastExtremumAggregate(@in.Value),
            InSubqueryExpression @in => FindLastExtremumAggregate(@in.Value),
            BetweenExpression between => FindLastExtremumAggregate(between.Upper)
                ?? FindLastExtremumAggregate(between.Lower)
                ?? FindLastExtremumAggregate(between.Value),
            _ => null,
        };
    }

    private SqlValue EvaluateAggregate(
        Expression expression,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative = null)
    {
        // Expose this aggregate evaluation's rows so nested subqueries can resolve an
        // aggregate owned by this block. The guard keeps recursive calls on the same rows
        // from stacking duplicate scopes.
        context = WithOuterAggregateScope(context, rows);
        return expression switch
        {
            FunctionExpression { Name: "COUNT" } function => EvaluateAggregateFunctionWithOwnership(function, rows, parameters, context, representative),
            FunctionExpression function when IsBuiltInAggregate(function)
                => EvaluateAggregateFunctionWithOwnership(function, rows, parameters, context, representative),
            FunctionExpression function when IsManagedPercentileAggregate(function.Name)
                => EvaluateAggregateFunctionWithOwnership(function, rows, parameters, context, representative),
            FunctionExpression function when TryGetAggregateFunction(function.Name, function.Arguments.Count, out _)
                => EvaluateAggregateFunctionWithOwnership(function, rows, parameters, context, representative),
            FunctionExpression function => EvaluateScalarFunction(
                function with
                {
                    Arguments = function.Arguments
                        .Select(argument => new LiteralExpression(
                            EvaluateAggregate(argument, rows, parameters, context, representative)))
                        .ToArray(),
                },
                parameters,
                representative,
                context),
            UnaryExpression unary => EvaluateUnaryValue(
                unary.Operator,
                EvaluateAggregate(unary.Operand, rows, parameters, context, representative)),
            BinaryExpression binary when IsComparisonOperator(binary.Operator)
                => EvaluateAggregateComparison(binary, rows, parameters, context, representative),
            BinaryExpression binary => EvaluateBinaryValues(
                binary.Operator,
                EvaluateAggregate(binary.Left, rows, parameters, context, representative),
                EvaluateAggregate(binary.Right, rows, parameters, context, representative),
                GetComparisonCollation(binary.Left, binary.Right, context)),
            CollationExpression collation
                => EvaluateAggregate(collation.Expression, rows, parameters, context, representative),
            CastExpression cast => CastValue(
                EvaluateAggregate(cast.Expression, rows, parameters, context, representative),
                cast.TypeName),
            CaseExpression @case => EvaluateAggregateCase(@case, rows, parameters, context, representative),
            LikeExpression like => EvaluateLikeValues(
                EvaluateAggregate(like.Value, rows, parameters, context, representative),
                EvaluateAggregate(like.Pattern, rows, parameters, context, representative),
                like.Escape is null
                    ? null
                    : EvaluateAggregate(like.Escape, rows, parameters, context, representative),
                like.Negated),
            GlobExpression glob => EvaluateGlobValues(
                EvaluateAggregate(glob.Value, rows, parameters, context, representative),
                EvaluateAggregate(glob.Pattern, rows, parameters, context, representative),
                glob.Negated),
            InExpression @in => EvaluateAggregateIn(@in, rows, parameters, context, representative),
            InSubqueryExpression @in
                => EvaluateAggregateInSubquery(@in, rows, parameters, context, representative),
            BetweenExpression between
                => EvaluateAggregateBetween(between, rows, parameters, context, representative),
            RowValueExpression => throw new EmbeddedSqlException("row value misused"),
            _ => rows.Count == 0 && expression is ColumnExpression
                ? SqlValue.Null
                : Evaluate(expression, parameters, representative ?? (rows.Count == 0 ? null : rows[0]), context),
        };
    }

    private SqlValue EvaluateAggregateComparison(
        BinaryExpression expression,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative)
    {
        var leftCount = GetExpressionValueCount(expression.Left, context);
        var rightCount = GetExpressionValueCount(expression.Right, context);
        if (leftCount != rightCount)
            throw new EmbeddedSqlException("row value misused");

        SqlValue[]? leftSubqueryValues = null;
        SqlValue[]? rightSubqueryValues = null;
        var foundNull = false;
        var isOperator = expression.Operator is BinaryOperator.Is or BinaryOperator.IsNot;
        for (var index = 0; index < leftCount; index++)
        {
            var leftValue = EvaluateAggregateExpressionElement(
                expression.Left,
                index,
                leftCount,
                rows,
                parameters,
                context,
                representative,
                ref leftSubqueryValues);
            var rightValue = EvaluateAggregateExpressionElement(
                expression.Right,
                index,
                rightCount,
                rows,
                parameters,
                context,
                representative,
                ref rightSubqueryValues);
            var leftElement = GetExpressionElement(expression.Left, index);
            var rightElement = GetExpressionElement(expression.Right, index);
            ApplyComparisonAffinities(
                leftElement,
                rightElement,
                representative,
                ref leftValue,
                ref rightValue);
            if (leftValue.Kind == SqlValueKind.Null || rightValue.Kind == SqlValueKind.Null)
            {
                if (isOperator)
                {
                    if (leftValue.Kind != rightValue.Kind)
                    {
                        return SqlValue.Integer(
                            expression.Operator == BinaryOperator.IsNot ? 1 : 0);
                    }

                    continue;
                }

                foundNull = true;
                if (expression.Operator is not (BinaryOperator.Equal or BinaryOperator.NotEqual))
                    return SqlValue.Null;
                continue;
            }

            var comparison = Compare(
                leftValue,
                rightValue,
                GetComparisonCollation(leftElement, rightElement, representative));
            if (expression.Operator is BinaryOperator.Equal or BinaryOperator.NotEqual || isOperator)
            {
                if (comparison != 0)
                {
                    return SqlValue.Integer(
                        expression.Operator is BinaryOperator.NotEqual or BinaryOperator.IsNot
                            ? 1
                            : 0);
                }

                continue;
            }
            if (comparison != 0)
                return EvaluateOrderingComparison(expression.Operator, comparison);
        }

        if (foundNull)
            return SqlValue.Null;
        if (expression.Operator is BinaryOperator.Equal or BinaryOperator.NotEqual || isOperator)
        {
            return SqlValue.Integer(
                expression.Operator is BinaryOperator.Equal or BinaryOperator.Is ? 1 : 0);
        }

        return EvaluateOrderingComparison(expression.Operator, comparison: 0);
    }

    private SqlValue EvaluateAggregateExpressionElement(
        Expression expression,
        int index,
        int count,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative,
        ref SqlValue[]? subqueryValues)
    {
        return expression switch
        {
            RowValueExpression rowValue => EvaluateAggregate(
                rowValue.Values[index],
                rows,
                parameters,
                context,
                representative),
            ScalarSubqueryExpression subquery => (subqueryValues ??=
                EvaluateSubqueryValues(
                    subquery.Query,
                    count,
                    parameters,
                    representative,
                    context))[index],
            _ when count == 1 => EvaluateAggregate(
                expression,
                rows,
                parameters,
                context,
                representative),
            _ => throw new EmbeddedSqlException("row value misused"),
        };
    }

    private SqlValue EvaluateAggregateIn(
        InExpression expression,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative)
    {
        if (expression.Values.Count == 0)
            return SqlValue.Integer(expression.Negated ? 1 : 0);

        var valueCount = GetExpressionValueCount(expression.Value, context);
        if (valueCount == 1
            && expression.Values.All(candidate =>
                GetExpressionValueCount(candidate, context) == 1))
        {
            return EvaluateAggregateScalarIn(
                expression,
                rows,
                parameters,
                context,
                representative);
        }

        var candidates = new List<SqlValue[]>(expression.Values.Count);
        foreach (var candidate in expression.Values)
        {
            var candidateCount = GetExpressionValueCount(candidate, context);
            if (candidateCount != valueCount)
            {
                if (valueCount == 1)
                    throw new EmbeddedSqlException("row value misused");
                throw new EmbeddedSqlException(
                    $"IN(...) element has {candidateCount} {(candidateCount == 1 ? "term" : "terms")} - expected {valueCount}");
            }

            candidates.Add(EvaluateAggregateExpressionValues(
                candidate,
                valueCount,
                rows,
                parameters,
                context,
                representative));
        }

        return EvaluateInRows(
            EvaluateAggregateExpressionValues(
                expression.Value,
                valueCount,
                rows,
                parameters,
                context,
                representative),
            candidates,
            expression.Value,
            expression.Values[^1],
            representative,
            expression.Negated);
    }

    private SqlValue EvaluateAggregateScalarIn(
        InExpression expression,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative)
    {
        var value = EvaluateAggregate(
            expression.Value,
            rows,
            parameters,
            context,
            representative);
        var valueIsNull = value.Kind == SqlValueKind.Null;
        var foundNull = false;
        var collation = GetEffectiveCollation(expression.Value, context);
        foreach (var candidateExpression in expression.Values)
        {
            var candidate = EvaluateAggregate(
                candidateExpression,
                rows,
                parameters,
                context,
                representative);
            if (valueIsNull)
                continue;
            if (candidate.Kind == SqlValueKind.Null)
            {
                foundNull = true;
                continue;
            }

            ApplyInComparisonAffinity(expression.Value, representative, ref candidate);
            if (Compare(value, candidate, collation) == 0)
                return SqlValue.Integer(expression.Negated ? 0 : 1);
        }

        if (valueIsNull || foundNull)
            return SqlValue.Null;
        return SqlValue.Integer(expression.Negated ? 1 : 0);
    }

    private SqlValue EvaluateAggregateInSubquery(
        InSubqueryExpression expression,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative)
    {
        var result = ExecuteQuery(expression.Query, parameters, context, representative);
        var valueCount = GetExpressionValueCount(expression.Value, context);
        if (result.Columns.Length != valueCount)
        {
            throw new EmbeddedSqlException(
                $"sub-select returns {result.Columns.Length} columns - expected {valueCount}");
        }

        return EvaluateInRows(
            EvaluateAggregateExpressionValues(
                expression.Value,
                valueCount,
                rows,
                parameters,
                context,
                representative),
            result.Rows,
            expression.Value,
            candidateExpression: null,
            representative,
            expression.Negated);
    }

    private SqlValue EvaluateAggregateBetween(
        BetweenExpression expression,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative)
    {
        var count = GetExpressionValueCount(expression.Value, context);
        if (GetExpressionValueCount(expression.Lower, context) != count
            || GetExpressionValueCount(expression.Upper, context) != count)
        {
            throw new EmbeddedSqlException("row value misused");
        }

        var value = EvaluateAggregateExpressionValues(
            expression.Value,
            count,
            rows,
            parameters,
            context,
            representative);
        var lowerResult = EvaluateAggregateMaterializedExpressionComparison(
            BinaryOperator.GreaterThanOrEqual,
            value,
            expression.Value,
            expression.Lower,
            rows,
            parameters,
            context,
            representative);
        var result = lowerResult.Kind == SqlValueKind.Integer
            && lowerResult.AsInteger() == 0
                ? lowerResult
                : ApplyLogical(
                    BinaryOperator.And,
                    lowerResult,
                    EvaluateAggregateMaterializedExpressionComparison(
                        BinaryOperator.LessThanOrEqual,
                        value,
                        expression.Value,
                        expression.Upper,
                        rows,
                        parameters,
                        context,
                        representative));
        if (result.Kind == SqlValueKind.Null || !expression.Negated)
            return result;
        return SqlValue.Integer(result.AsInteger() == 0 ? 1 : 0);
    }

    private SqlValue EvaluateAggregateMaterializedExpressionComparison(
        BinaryOperator operation,
        IReadOnlyList<SqlValue> left,
        Expression leftExpression,
        Expression rightExpression,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative)
    {
        var count = GetExpressionValueCount(rightExpression, context);
        if (left.Count != count)
            throw new EmbeddedSqlException("row value misused");

        SqlValue[]? subqueryValues = null;
        for (var index = 0; index < count; index++)
        {
            var leftValue = left[index];
            var rightValue = EvaluateAggregateExpressionElement(
                rightExpression,
                index,
                count,
                rows,
                parameters,
                context,
                representative,
                ref subqueryValues);
            var leftElement = GetExpressionElement(leftExpression, index);
            var rightElement = GetExpressionElement(rightExpression, index);
            ApplyComparisonAffinities(
                leftElement,
                rightElement,
                representative,
                ref leftValue,
                ref rightValue);
            if (leftValue.Kind == SqlValueKind.Null || rightValue.Kind == SqlValueKind.Null)
                return SqlValue.Null;

            var comparison = Compare(
                leftValue,
                rightValue,
                GetComparisonCollation(leftElement, rightElement, representative));
            if (comparison != 0)
                return EvaluateOrderingComparison(operation, comparison);
        }

        return EvaluateOrderingComparison(operation, comparison: 0);
    }

    private SqlValue[] EvaluateAggregateExpressionValues(
        Expression expression,
        int expectedCount,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative)
    {
        return expression switch
        {
            RowValueExpression rowValue when rowValue.Values.Count == expectedCount
                => rowValue.Values.Select(value =>
                    EvaluateAggregate(value, rows, parameters, context, representative)).ToArray(),
            ScalarSubqueryExpression subquery
                => EvaluateSubqueryValues(subquery.Query, expectedCount, parameters, representative, context),
            _ when expectedCount == 1
                => [EvaluateAggregate(expression, rows, parameters, context, representative)],
            _ => throw new EmbeddedSqlException("row value misused"),
        };
    }

    private SqlValue EvaluateAggregateFunction(
        FunctionExpression function,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context)
    {
        var effectiveRows = ApplyAggregateModifiers(function, rows, parameters, context);
        if (string.Equals(function.Name, "COUNT", StringComparison.Ordinal))
            return EvaluateCount(function, effectiveRows, parameters, context);
        if (IsBuiltInAggregate(function))
            return EvaluateBuiltInAggregate(function, effectiveRows, parameters, context);
        if (IsManagedPercentileAggregate(function.Name))
            return EvaluatePercentileAggregate(function, effectiveRows, parameters, context);
        if (TryGetAggregateFunction(function.Name, function.Arguments.Count, out var aggregate))
            return EvaluateManagedAggregate(aggregate, function, effectiveRows, parameters, context);

        throw new EmbeddedSqlException($"Unsupported aggregate function {function.Name}().");
    }

    private IReadOnlyList<SourceRow> ApplyAggregateModifiers(
        FunctionExpression function,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context)
    {
        var result = rows;
        if (function.Filter is not null)
        {
            var filtered = new List<SourceRow>();
            foreach (var row in result)
            {
                context.CheckInterrupt();
                if (IsTrue(Evaluate(function.Filter, parameters, row, context)))
                    filtered.Add(row);
            }

            result = filtered;
        }

        // ORDER BY within an aggregate sorts the group rows before accumulation (SQLite 3.44+):
        // the sorter feeds rows to the step function in term order, so every aggregate — not just
        // group_concat — observes that order.
        if (function.AggregateOrderBy is { Count: > 0 } aggregateOrderBy)
        {
            result = SortAggregateRows(result, aggregateOrderBy, parameters, context);
        }

        if (function.Distinct)
        {
            if (function.AggregateOrderBy is { Count: > 0 })
            {
                throw new EmbeddedSqlException(
                    "DISTINCT aggregates with ORDER BY are not supported by the managed engine.");
            }

            if (function.Arguments.Count != 1)
                throw new EmbeddedSqlException("DISTINCT aggregates must have exactly one argument.");

            var collation = GetEffectiveCollation(function.Arguments[0], context);
            var seen = new List<SqlValue>();
            var deduplicated = new List<SourceRow>();
            foreach (var row in result)
            {
                context.CheckInterrupt();
                var value = Evaluate(function.Arguments[0], parameters, row, context);
                if (seen.Any(existing => DistinctValuesEqual(existing, value, collation)))
                    continue;

                seen.Add(value);
                deduplicated.Add(row);
            }

            result = deduplicated;
        }

        return result;
    }

    private IReadOnlyList<SourceRow> SortAggregateRows(
        IReadOnlyList<SourceRow> rows,
        IReadOnlyList<OrderByTerm> orderBy,
        SqlValue[] parameters,
        QueryContext context)
    {
        var collations = orderBy
            .Select(term => GetEffectiveCollation(term.Expression, context))
            .ToArray();
        var decorated = rows
            .Select((row, index) => (
                Row: row,
                Keys: orderBy.Select(term => Evaluate(term.Expression, parameters, row, context)).ToArray(),
                Index: index))
            .ToArray();
        Array.Sort(decorated, Comparer<(SourceRow Row, SqlValue[] Keys, int Index)>.Create((left, right) =>
        {
            var comparison = CompareOrderKeys(left.Keys, right.Keys, orderBy, collations);
            return comparison != 0 ? comparison : left.Index.CompareTo(right.Index);
        }));

        return decorated.Select(entry => entry.Row).ToArray();
    }

    private bool DistinctValuesEqual(SqlValue left, SqlValue right, string? collation)
    {
        if (left.Kind == SqlValueKind.Null || right.Kind == SqlValueKind.Null)
            return left.Kind == right.Kind;

        return Compare(left, right, collation) == 0;
    }

    private SqlValue EvaluateCount(
        FunctionExpression function,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (function.CountStar || function.Arguments.Count == 0)
            return SqlValue.Integer(rows.Count);

        var count = 0L;
        foreach (var row in rows)
        {
            context.CheckInterrupt();
            if (Evaluate(function.Arguments[0], parameters, row, context).Kind != SqlValueKind.Null)
                count++;
        }

        return SqlValue.Integer(count);
    }

    internal static bool IsBuiltInAggregate(FunctionExpression function)
    {
        return function.Name switch
        {
            "COUNT" => function.CountStar || function.Arguments.Count is 0 or 1,
            "SUM" or "TOTAL" or "AVG" or "MIN" or "MAX" => function.Arguments.Count == 1,
            "GROUP_CONCAT" => function.Arguments.Count is 1 or 2,
            // Arity is validated during evaluation so a wrong-argument-count call reports
            // SQLite's arity diagnostic instead of "no such function".
            "STRING_AGG" or "JSON_GROUP_ARRAY" or "JSON_GROUP_OBJECT" => true,
            _ => false,
        };
    }

    internal static bool IsManagedPercentileAggregate(string name)
    {
        return name.Equals("MEDIAN", StringComparison.OrdinalIgnoreCase)
            || name.Equals("PERCENTILE", StringComparison.OrdinalIgnoreCase)
            || name.Equals("PERCENTILE_CONT", StringComparison.OrdinalIgnoreCase)
            || name.Equals("PERCENTILE_DISC", StringComparison.OrdinalIgnoreCase);
    }

    // The aggregate-ownership machinery below implements SQLite's rule that an aggregate
    // call whose argument columns belong to an enclosing query block evaluates against
    // that block's rows, provided the immediately enclosing SELECT is aggregate-bearing.

    // True when the call resolves to any aggregate implementation, mirroring the cases
    // EvaluateAggregate dispatches on (COUNT by name, built-ins, managed percentiles, and
    // connection-registered aggregates).
    private bool IsAggregateFunctionCall(FunctionExpression function)
        => string.Equals(function.Name, "COUNT", StringComparison.Ordinal)
            || IsBuiltInAggregate(function)
            || IsManagedPercentileAggregate(function.Name)
            || TryGetAggregateFunction(function.Name, function.Arguments.Count, out _);

    // An outer-block aggregate may only be referenced when the immediately enclosing
    // SELECT is itself aggregate-bearing (a projection, the HAVING clause, or an ORDER BY
    // term holds an aggregate). ExecuteQuery clears the scope for anything else so the
    // reference surfaces as the same scalar-dispatch misuse error native reports.
    private bool SelectIsAggregateBearing(SelectStatement select)
        => select.Projections.Any(projection => ContainsAggregate(projection.Expression))
            || select.Having is not null && ContainsAggregate(select.Having)
            || select.OrderBy.Any(term => ContainsAggregate(term.Expression));

    private static QueryContext WithOuterAggregateScope(QueryContext context, IReadOnlyList<SourceRow> rows)
        => ReferenceEquals(context.OuterAggregateScope?.Rows, rows)
            ? context
            : context with
            {
                OuterAggregateScope = new OuterAggregateScope(rows, context.OuterAggregateScope, context),
            };

    // An aggregate call reached through scalar dispatch normally means a misuse (the
    // built-in scalar max()/min() with two or more arguments throws "wrong number of
    // arguments"), but when its argument columns belong to an enclosing aggregate block
    // SQLite instead evaluates it against that block's rows. Detect the latter here and
    // hand the call to the owning scope; everything else takes the ordinary scalar path.
    private SqlValue EvaluateFunctionRespectingOuterAggregateScope(
        FunctionExpression function,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        if (context.OuterAggregateScope is not null
            && function.Window is null
            && IsAggregateFunctionCall(function)
            && AggregateColumnsResolveLocally(function, row) is false
            && TryEvaluateOuterScopedAggregate(function, parameters, context, out var value))
        {
            return value;
        }
        return EvaluateScalarFunction(function, parameters, row, context);
    }

    // Walks the enclosing aggregate scopes for one whose rows own every argument column
    // and evaluates the call against them. Returns false when no scope qualifies or
    // ownership is indeterminate, in which case the caller uses the normal (local) path.
    // A scope with no rows and unresolved columns counts as an owner: an aggregate over an
    // empty outer set still belongs to that outer block and yields its empty-set identity.
    private bool TryEvaluateOuterScopedAggregate(
        FunctionExpression function,
        SqlValue[] parameters,
        QueryContext context,
        out SqlValue value)
    {
        value = SqlValue.Null;
        for (var scope = context.OuterAggregateScope; scope is not null; scope = scope.Parent)
        {
            var probeRow = scope.Rows.Count > 0 ? scope.Rows[0] : null;
            var resolution = AggregateColumnsResolveLocally(function, probeRow);
            if (resolution is null)
                return false;
            if (resolution == false && probeRow is not null)
                continue;
            value = EvaluateAggregateFunction(function, scope.Rows, parameters, scope.Context);
            return true;
        }
        return false;
    }

    // Redirects an aggregate call evaluated in an aggregate context to the enclosing scope
    // that owns its argument columns (an outer-block aggregate referenced from an
    // aggregate-bearing subquery). The scope EvaluateAggregate just added for the rows
    // being processed here is skipped, so only genuinely outer scopes qualify. Anything
    // else - locally owned calls, mixed-ownership arguments, indeterminate ownership -
    // evaluates against the given rows exactly as before.
    private SqlValue EvaluateAggregateFunctionWithOwnership(
        FunctionExpression function,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative)
    {
        if (context.OuterAggregateScope is not null
            && AggregateColumnsResolveLocally(
                function,
                representative ?? (rows.Count > 0 ? rows[0] : null)) is false)
        {
            for (var scope = context.OuterAggregateScope; scope is not null; scope = scope.Parent)
            {
                if (ReferenceEquals(scope.Rows, rows))
                    continue;
                var probeRow = scope.Rows.Count > 0 ? scope.Rows[0] : null;
                var resolution = AggregateColumnsResolveLocally(function, probeRow);
                if (resolution is null)
                    break;
                if (resolution == false && probeRow is not null)
                    continue;
                return EvaluateAggregateFunction(function, scope.Rows, parameters, scope.Context);
            }
        }
        return EvaluateAggregateFunction(function, rows, parameters, context);
    }

    // Decides whether every column an aggregate call references (arguments plus FILTER)
    // resolves against the probe row alone, ignoring its parent chain: true means the call
    // belongs to the block the probe row came from, false means some column belongs to an
    // enclosing block, and null means a nested subquery makes ownership indeterminate, in
    // which case the caller falls back to normal evaluation. A call with no columns at
    // all (COUNT(*), count of a constant) resolves locally, keeping it inner-owned.
    private static bool? AggregateColumnsResolveLocally(FunctionExpression function, SourceRow? probeRow)
    {
        var pending = new Stack<Expression>();
        foreach (var argument in function.Arguments)
            pending.Push(argument);
        if (function.Filter is not null)
            pending.Push(function.Filter);
        while (pending.Count > 0)
        {
            switch (pending.Pop())
            {
                case ColumnExpression column:
                    if (probeRow is null || !TryResolveColumnLocally(probeRow, column))
                        return false;
                    break;
                case ScalarSubqueryExpression or ExistsExpression or InSubqueryExpression:
                    return null;
                case FunctionExpression nested:
                    foreach (var argument in nested.Arguments)
                        pending.Push(argument);
                    if (nested.Filter is not null)
                        pending.Push(nested.Filter);
                    break;
                case RowValueExpression rowValue:
                    foreach (var value in rowValue.Values)
                        pending.Push(value);
                    break;
                case UnaryExpression unary:
                    pending.Push(unary.Operand);
                    break;
                case BinaryExpression binary:
                    pending.Push(binary.Left);
                    pending.Push(binary.Right);
                    break;
                case CollationExpression collation:
                    pending.Push(collation.Expression);
                    break;
                case CastExpression cast:
                    pending.Push(cast.Expression);
                    break;
                case CaseExpression @case:
                    if (@case.Operand is not null)
                        pending.Push(@case.Operand);
                    foreach (var clause in @case.Clauses)
                    {
                        pending.Push(clause.When);
                        pending.Push(clause.Then);
                    }
                    if (@case.Else is not null)
                        pending.Push(@case.Else);
                    break;
                case LikeExpression like:
                    pending.Push(like.Value);
                    pending.Push(like.Pattern);
                    if (like.Escape is not null)
                        pending.Push(like.Escape);
                    break;
                case GlobExpression glob:
                    pending.Push(glob.Value);
                    pending.Push(glob.Pattern);
                    break;
                case InExpression @in:
                    pending.Push(@in.Value);
                    foreach (var value in @in.Values)
                        pending.Push(value);
                    break;
                case BetweenExpression between:
                    pending.Push(between.Value);
                    pending.Push(between.Lower);
                    pending.Push(between.Upper);
                    break;
                default:
                    break; // literals, parameters, stars: no columns to resolve
            }
        }
        return true;
    }

    private static bool TryResolveColumnLocally(SourceRow row, ColumnExpression column)
        => (row.Parent is null ? row : row with { Parent = null }).TryGetValue(column, out _);

    // True when every aggregate call this statement evaluates belongs to an enclosing
    // aggregate block. With selected rows, ownership is probed against the first row: a
    // call whose columns all resolve there is inner-owned. With an empty selection the
    // probe cannot distinguish, so the outer scope chain is walked instead - a scope
    // whose rows resolve the columns (or an empty scope, which owns by the same rule
    // the evaluation-time redirect uses) proves outer ownership, while a call resolving
    // on no scope is inner-owned over an empty set and keeps its one-NULL-row
    // cardinality. This mirrors SQLite's innermost-binding resolution, except that an
    // unqualified column present in both an inner and an outer source is provable only
    // when the inner selection produced a row.
    private bool AllAggregatesProvablyOuterOwned(
        SelectStatement statement,
        IReadOnlyList<SourceRow> selectedRows,
        QueryContext context)
    {
        var aggregates = new List<FunctionExpression>();
        foreach (var projection in statement.Projections)
            CollectNonWindowAggregates(projection.Expression, aggregates);
        foreach (var term in statement.OrderBy)
            CollectNonWindowAggregates(term.Expression, aggregates);
        if (aggregates.Count == 0)
            return false;

        foreach (var aggregate in aggregates)
        {
            if (selectedRows.Count > 0)
            {
                if (AggregateColumnsResolveLocally(aggregate, selectedRows[0]) is not false)
                    return false;
                continue;
            }

            // A call that references no columns at all (COUNT(*)) is inner-owned no
            // matter who encloses it, and an indeterminate call keeps the aggregate
            // path so its evaluation reports the same misuse native would.
            if (AggregateColumnsResolveLocally(aggregate, null) is not false)
                return false;
            var provenOuter = false;
            for (var scope = context.OuterAggregateScope; scope is not null && !provenOuter; scope = scope.Parent)
            {
                var probeRow = scope.Rows.Count > 0 ? scope.Rows[0] : null;
                var resolution = AggregateColumnsResolveLocally(aggregate, probeRow);
                if (resolution is null)
                    return false;
                provenOuter = resolution == true || probeRow is null;
            }
            if (!provenOuter)
                return false;
        }
        return true;
    }

    // Collects the aggregate calls that make a statement an aggregate query, mirroring
    // ContainsAggregate's traversal: window calls and subquery expressions are not
    // descended into (their aggregates belong to their own blocks), and an aggregate
    // call's own arguments are covered by the ownership probe rather than collected
    // separately (a nested aggregate there is a misuse native rejects).
    private void CollectNonWindowAggregates(Expression expression, List<FunctionExpression> aggregates)
    {
        switch (expression)
        {
            case FunctionExpression { Window: not null }:
                break;
            case FunctionExpression function when IsAggregateFunctionCall(function):
                aggregates.Add(function);
                break;
            case FunctionExpression function:
                foreach (var argument in function.Arguments)
                    CollectNonWindowAggregates(argument, aggregates);
                break;
            case RowValueExpression rowValue:
                foreach (var value in rowValue.Values)
                    CollectNonWindowAggregates(value, aggregates);
                break;
            case UnaryExpression unary:
                CollectNonWindowAggregates(unary.Operand, aggregates);
                break;
            case BinaryExpression binary:
                CollectNonWindowAggregates(binary.Left, aggregates);
                CollectNonWindowAggregates(binary.Right, aggregates);
                break;
            case CollationExpression collation:
                CollectNonWindowAggregates(collation.Expression, aggregates);
                break;
            case CastExpression cast:
                CollectNonWindowAggregates(cast.Expression, aggregates);
                break;
            case CaseExpression @case:
                if (@case.Operand is not null)
                    CollectNonWindowAggregates(@case.Operand, aggregates);
                foreach (var clause in @case.Clauses)
                {
                    CollectNonWindowAggregates(clause.When, aggregates);
                    CollectNonWindowAggregates(clause.Then, aggregates);
                }
                if (@case.Else is not null)
                    CollectNonWindowAggregates(@case.Else, aggregates);
                break;
            case LikeExpression like:
                CollectNonWindowAggregates(like.Value, aggregates);
                CollectNonWindowAggregates(like.Pattern, aggregates);
                if (like.Escape is not null)
                    CollectNonWindowAggregates(like.Escape, aggregates);
                break;
            case GlobExpression glob:
                CollectNonWindowAggregates(glob.Value, aggregates);
                CollectNonWindowAggregates(glob.Pattern, aggregates);
                break;
            case InExpression @in:
                CollectNonWindowAggregates(@in.Value, aggregates);
                foreach (var value in @in.Values)
                    CollectNonWindowAggregates(value, aggregates);
                break;
            case InSubqueryExpression @inSubquery:
                CollectNonWindowAggregates(@inSubquery.Value, aggregates);
                break;
            case BetweenExpression between:
                CollectNonWindowAggregates(between.Value, aggregates);
                CollectNonWindowAggregates(between.Lower, aggregates);
                CollectNonWindowAggregates(between.Upper, aggregates);
                break;
        }
    }

    private SqlValue EvaluateBuiltInAggregate(
        FunctionExpression function,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context)
    {
        return function.Name switch
        {
            "SUM" => EvaluateSum(function, rows, parameters, context, forceReal: false, average: false),
            "TOTAL" => EvaluateSum(function, rows, parameters, context, forceReal: true, average: false),
            "AVG" => EvaluateSum(function, rows, parameters, context, forceReal: true, average: true),
            "MIN" => EvaluateMinMax(function, rows, parameters, context, maximum: false),
            "MAX" => EvaluateMinMax(function, rows, parameters, context, maximum: true),
            "GROUP_CONCAT" => EvaluateGroupConcat(function, rows, parameters, context),
            "STRING_AGG" => EvaluateStringAgg(function, rows, parameters, context),
            "JSON_GROUP_ARRAY" => EvaluateJsonGroupArray(function, rows, parameters, context),
            "JSON_GROUP_OBJECT" => EvaluateJsonGroupObject(function, rows, parameters, context),
            _ => throw new EmbeddedSqlException($"Unsupported aggregate function {function.Name}()."),
        };
    }

    private SqlValue EvaluateSum(
        FunctionExpression function,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        bool forceReal,
        bool average)
    {
        RequireAggregateArgumentCount(function.Name.ToLowerInvariant(), function.Arguments, 1);

        // SQLite's SumCtx keeps an exact 64-bit accumulator for as long as every input is an
        // integer, and only switches to the Kahan-Babuska-Neumaier compensated double
        // accumulator when a non-integer arrives or the integer sum overflows. avg() and total()
        // share that accumulator, so avg(9223372036854775807, -9223372036854775806) is 0.5 and
        // not the 0.0 that double accumulation produces.
        var integerTotal = 0L;
        var realTotal = 0d;
        var realError = 0d;
        var approximate = false;
        var overflowed = false;
        var count = 0L;
        foreach (var row in rows)
        {
            context.CheckInterrupt();
            var value = Evaluate(function.Arguments[0], parameters, row, context);
            if (value.Kind == SqlValueKind.Null)
                continue;

            // SQLite accumulates in integers only while every value is exactly an integer
            // (sqlite3_value_numeric_type). Anything else - a real, or text such as '12abc' that
            // merely starts with a number - switches to floating point via sqlite3_value_double.
            var exact = ApplyComparisonNumericAffinity(value);
            count++;
            if (exact.Kind != SqlValueKind.Integer)
            {
                var real = exact.Kind == SqlValueKind.Real
                    ? AsReal(exact)
                    : AsReal(ApplyNumericAffinity(value));
                if (!approximate)
                {
                    KahanBabuskaNeumaierInit(integerTotal, out realTotal, out realError);
                    approximate = true;
                }
                else
                {
                    // A real input clears a previous integer overflow, exactly as sumStep does:
                    // the running total is already inexact, so the overflow no longer matters.
                    overflowed = false;
                }

                KahanBabuskaNeumaierStep(real, ref realTotal, ref realError);
                continue;
            }

            var addend = exact.AsInteger();
            if (!approximate)
            {
                var candidate = unchecked(integerTotal + addend);
                if (((integerTotal ^ candidate) & (addend ^ candidate)) >= 0)
                {
                    integerTotal = candidate;
                    continue;
                }

                overflowed = true;
                KahanBabuskaNeumaierInit(integerTotal, out realTotal, out realError);
                approximate = true;
            }

            KahanBabuskaNeumaierStepInt64(addend, ref realTotal, ref realError);
        }

        var accumulated = approximate
            ? (double.IsNaN(realError) ? realTotal : realTotal + realError)
            : integerTotal;

        if (average)
            return count == 0 ? SqlValue.Null : SqlValue.Real(accumulated / count);
        if (forceReal)
            return SqlValue.Real(count == 0 ? 0 : accumulated);
        if (count == 0)
            return SqlValue.Null;

        // Only sum() reports the overflow. avg() and total() are documented to return a real, so
        // sqlite3's avgFinalize and totalFinalize ignore the flag entirely.
        if (overflowed)
            throw new EmbeddedSqlException("integer overflow");

        return approximate ? SqlValue.Real(accumulated) : SqlValue.Integer(integerTotal);
    }

    /// <summary>Seeds the compensated accumulator from an exact 64-bit running total.</summary>
    /// <remarks>
    /// Splitting off the low 14 bits keeps the high part exactly representable as a double, so
    /// no precision is lost at the moment the accumulator switches modes.
    /// </remarks>
    private static void KahanBabuskaNeumaierInit(long value, out double sum, out double error)
    {
        if (value is <= -4503599627370496L or >= 4503599627370496L)
        {
            var low = value % 16384;
            sum = value - low;
            error = low;
        }
        else
        {
            sum = value;
            error = 0d;
        }
    }

    /// <summary>Adds one term to the Kahan-Babuska-Neumaier compensated sum.</summary>
    private static void KahanBabuskaNeumaierStep(double term, ref double sum, ref double error)
    {
        var running = sum;
        var next = running + term;
        error += Math.Abs(running) > Math.Abs(term)
            ? (running - next) + term
            : (term - next) + running;
        sum = next;
    }

    private static void KahanBabuskaNeumaierStepInt64(long value, ref double sum, ref double error)
    {
        if (value is <= -4503599627370496L or >= 4503599627370496L)
        {
            var low = value % 16384;
            KahanBabuskaNeumaierStep(value - low, ref sum, ref error);
            KahanBabuskaNeumaierStep(low, ref sum, ref error);
            return;
        }

        KahanBabuskaNeumaierStep(value, ref sum, ref error);
    }

    private SqlValue EvaluateMinMax(
        FunctionExpression function,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        bool maximum)
    {
        RequireAggregateArgumentCount(function.Name.ToLowerInvariant(), function.Arguments, 1);
        var collation = GetEffectiveCollation(function.Arguments[0], context);
        var result = SqlValue.Null;
        foreach (var row in rows)
        {
            context.CheckInterrupt();
            var value = Evaluate(function.Arguments[0], parameters, row, context);
            if (value.Kind == SqlValueKind.Null)
                continue;
            if (result.Kind == SqlValueKind.Null
                || (maximum
                    ? Compare(value, result, collation) > 0
                    : Compare(value, result, collation) < 0))
            {
                result = value;
            }
        }

        return result;
    }

    private SqlValue EvaluateGroupConcat(
        FunctionExpression function,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (function.Arguments.Count is < 1 or > 2)
            throw new EmbeddedSqlException("wrong number of arguments to function group_concat()");

        var result = new System.Text.StringBuilder();
        var hasValue = false;
        foreach (var row in rows)
        {
            context.CheckInterrupt();
            var value = Evaluate(function.Arguments[0], parameters, row, context);
            if (value.Kind == SqlValueKind.Null)
                continue;

            if (hasValue)
            {
                var separator = function.Arguments.Count == 1
                    ? SqlValue.Text(",")
                    : Evaluate(function.Arguments[1], parameters, row, context);
                if (separator.Kind != SqlValueKind.Null)
                    result.Append(ToSqlText(separator));
            }

            result.Append(ToSqlText(value));
            hasValue = true;
        }

        return hasValue ? SqlValue.Text(result.ToString()) : SqlValue.Null;
    }

    private static void RequireAggregateArgumentCount(
        string functionName,
        IReadOnlyList<Expression> arguments,
        int expected)
    {
        if (arguments.Count != expected)
            throw new EmbeddedSqlException($"wrong number of arguments to function {functionName}()");
    }

    private SqlValue EvaluateManagedAggregate(
        ManagedAggregateFunction aggregate,
        FunctionExpression function,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context)
    {
        var accumulator = aggregate.Seed;
        foreach (var row in rows)
        {
            context.CheckInterrupt();
            var arguments = function.Arguments
                .Select(argument => Evaluate(argument, parameters, row, context))
                .ToArray();
            accumulator = InvokeManagedCallback(() => aggregate.Step(accumulator, arguments));
        }

        return InvokeManagedCallback(() => aggregate.Finalize(accumulator));
    }

    private SqlValue EvaluatePercentileAggregate(
        FunctionExpression function,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context)
    {
        var name = function.Name.ToUpperInvariant();
        var isMedian = name == "MEDIAN";
        var isPercentile = name == "PERCENTILE";
        var isContinuous = !isMedian && name != "PERCENTILE_DISC";
        RequireAggregateArgumentCount(name.ToLowerInvariant(), function.Arguments, isMedian ? 1 : 2);

        var values = new List<double>();
        double? percentile = null;
        string? error = null;
        var maximumPercentile = isPercentile ? 100d : 1d;

        foreach (var row in rows)
        {
            context.CheckInterrupt();
            if (!TryGetPercentileNumericValue(
                    Evaluate(function.Arguments[0], parameters, row, context),
                    out var value))
            {
                continue;
            }

            if (isMedian)
            {
                values.Add(value);
                continue;
            }

            if (!TryGetPercentileNumericValue(
                    Evaluate(function.Arguments[1], parameters, row, context),
                    out var candidate))
            {
                continue;
            }

            if (!(candidate >= 0d && candidate <= maximumPercentile))
            {
                error ??= isPercentile
                    ? "Invalid percentile value"
                    : "Percentile value must be between 0.0 and 1.0 inclusive";
                continue;
            }

            if (percentile is { } existing)
            {
                if (Math.Abs(existing - candidate) >= 0.001d)
                    error ??= "Inconsistent percentile values across rows";
            }
            else
            {
                percentile = candidate;
            }

            values.Add(value);
        }

        if (error is not null)
            throw new EmbeddedSqlException(error);
        if (values.Count == 0)
            return SqlValue.Null;

        values.Sort(ComparePercentileValues);
        if (isMedian)
        {
            var middle = values.Count / 2;
            return SqlValue.Real(values.Count % 2 == 0
                ? (values[middle - 1] + values[middle]) / 2d
                : values[middle]);
        }

        var fraction = percentile!.Value / maximumPercentile;
        var rank = fraction * (values.Count - 1);
        if (isContinuous)
        {
            var lower = (int)Math.Floor(rank);
            var upper = (int)Math.Ceiling(rank);
            if (lower == upper)
                return SqlValue.Real(values[lower]);

            var weight = rank - lower;
            return SqlValue.Real(values[lower] * (1d - weight) + values[upper] * weight);
        }

        return SqlValue.Real(values[(int)Math.Floor(rank)]);
    }

    private static bool TryGetPercentileNumericValue(SqlValue value, out double numeric)
    {
        switch (value.Kind)
        {
            case SqlValueKind.Integer:
                numeric = value.AsInteger();
                return true;
            case SqlValueKind.Real:
                numeric = value.AsReal();
                return true;
            case SqlValueKind.Text:
                return double.TryParse(
                    value.AsText(),
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out numeric);
            default:
                numeric = default;
                return false;
        }
    }

    private static int ComparePercentileValues(double left, double right)
    {
        var leftBits = BitConverter.DoubleToInt64Bits(left);
        var rightBits = BitConverter.DoubleToInt64Bits(right);
        leftBits ^= (leftBits >> 63) & long.MaxValue;
        rightBits ^= (rightBits >> 63) & long.MaxValue;
        return leftBits.CompareTo(rightBits);
    }

    private SqlValue EvaluateAggregateCase(
        CaseExpression expression,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative)
    {
        SqlValue[]? operand = null;
        var operandCount = 0;
        if (expression.Operand is not null)
        {
            operandCount = GetExpressionValueCount(expression.Operand, context);
            operand = EvaluateAggregateExpressionValues(
                expression.Operand,
                operandCount,
                rows,
                parameters,
                context,
                representative);
        }

        foreach (var clause in expression.Clauses)
        {
            var matches = operand is null
                ? IsTrue(EvaluateAggregate(
                    clause.When,
                    rows,
                    parameters,
                    context,
                    representative))
                : EvaluateAggregateCaseEquality(
                    operand,
                    expression.Operand!,
                    clause.When,
                    rows,
                    parameters,
                    context,
                    representative) is { Kind: SqlValueKind.Integer } equality
                    && equality.AsInteger() != 0;
            if (matches)
                return EvaluateAggregate(clause.Then, rows, parameters, context, representative);
        }

        return expression.Else is null
            ? SqlValue.Null
            : EvaluateAggregate(expression.Else, rows, parameters, context, representative);
    }

    private SqlValue EvaluateAggregateCaseEquality(
        IReadOnlyList<SqlValue> operand,
        Expression operandExpression,
        Expression whenExpression,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context,
        SourceRow? representative)
    {
        var count = GetExpressionValueCount(whenExpression, context);
        if (operand.Count != count)
            throw new EmbeddedSqlException("row value misused");

        SqlValue[]? subqueryValues = null;
        var foundNull = false;
        for (var index = 0; index < count; index++)
        {
            var left = operand[index];
            var right = EvaluateAggregateExpressionElement(
                whenExpression,
                index,
                count,
                rows,
                parameters,
                context,
                representative,
                ref subqueryValues);
            var leftElement = GetExpressionElement(operandExpression, index);
            var rightElement = GetExpressionElement(whenExpression, index);
            ApplyComparisonAffinities(
                leftElement,
                rightElement,
                representative,
                ref left,
                ref right);
            if (left.Kind == SqlValueKind.Null || right.Kind == SqlValueKind.Null)
            {
                foundNull = true;
                continue;
            }
            if (Compare(
                    left,
                    right,
                    GetComparisonCollation(leftElement, rightElement, representative)) != 0)
            {
                return SqlValue.Integer(0);
            }
        }

        return foundNull ? SqlValue.Null : SqlValue.Integer(1);
    }

    private SqlValue EvaluateScalarFunction(
        FunctionExpression function,
        SqlValue[] parameters,
        SourceRow? row,
        QueryContext context)
    {
        if (string.Equals(function.Name, "COUNT", StringComparison.OrdinalIgnoreCase))
            throw new EmbeddedSqlException("misuse of aggregate function COUNT()");

        if (function.Filter is not null)
            throw new EmbeddedSqlException($"FILTER may not be used with non-aggregate {function.Name.ToLowerInvariant()}()");

        var arguments = function.Arguments.Select(argument => Evaluate(argument, parameters, row, context)).ToArray();
        var normalizedName = function.Name.ToUpperInvariant();
        if (!context.IndexExpression
            && (_scalarFunctions.TryGetValue((normalizedName, arguments.Length), out var managedFunction)
                || _scalarFunctions.TryGetValue((normalizedName, -1), out managedFunction)))
        {
            return InvokeManagedCallback(() => managedFunction(arguments));
        }

        return function.Name.ToUpperInvariant() switch
        {
            "ABS" => EvaluateAbsoluteValue(arguments),
            "CEIL" or "CEILING" => EvaluateIntegralMath(function.Name, arguments, Math.Ceiling),
            "FLOOR" => EvaluateIntegralMath("floor", arguments, Math.Floor),
            "TRUNC" => EvaluateIntegralMath("trunc", arguments, Math.Truncate),
            "ROUND" => EvaluateRound(arguments),
            "LN" => EvaluateUnaryMath("ln", arguments, Math.Log),
            "LOG" => EvaluateLogarithm(arguments),
            "LOG2" => EvaluateUnaryMath("log2", arguments, Math.Log2),
            "LOG10" => EvaluateUnaryMath("log10", arguments, Math.Log10),
            "EXP" => EvaluateUnaryMath("exp", arguments, Math.Exp),
            "SQRT" => EvaluateUnaryMath("sqrt", arguments, Math.Sqrt),
            "POW" or "POWER" => EvaluateBinaryMath(function.Name, arguments, Math.Pow),
            "MOD" => EvaluateModulo(arguments),
            "SIGN" => EvaluateSign(arguments),
            "PI" => EvaluatePi(arguments),
            "DEGREES" => EvaluateUnaryMath("degrees", arguments, static value => value * (180.0 / Math.PI)),
            "RADIANS" => EvaluateUnaryMath("radians", arguments, static value => value * (Math.PI / 180.0)),
            "SIN" => EvaluateUnaryMath("sin", arguments, Math.Sin),
            "COS" => EvaluateUnaryMath("cos", arguments, Math.Cos),
            "TAN" => EvaluateUnaryMath("tan", arguments, Math.Tan),
            "ASIN" => EvaluateUnaryMath("asin", arguments, Math.Asin),
            "ACOS" => EvaluateUnaryMath("acos", arguments, Math.Acos),
            "ATAN" => EvaluateUnaryMath("atan", arguments, Math.Atan),
            "ATAN2" => EvaluateBinaryMath("atan2", arguments, Math.Atan2),
            "SINH" => EvaluateUnaryMath("sinh", arguments, Math.Sinh),
            "COSH" => EvaluateUnaryMath("cosh", arguments, Math.Cosh),
            "TANH" => EvaluateUnaryMath("tanh", arguments, Math.Tanh),
            "ASINH" => EvaluateUnaryMath("asinh", arguments, Math.Asinh),
            "ACOSH" => EvaluateUnaryMath("acosh", arguments, Math.Acosh),
            "ATANH" => EvaluateUnaryMath("atanh", arguments, Math.Atanh),
            "SUBSTR" or "SUBSTRING" => EvaluateSubstring(arguments),
            "REPLACE" => EvaluateReplace(arguments),
            "TRIM" or "BTRIM" => EvaluateTrim(arguments, "trim", trimStart: true, trimEnd: true),
            "LTRIM" => EvaluateTrim(arguments, "ltrim", trimStart: true, trimEnd: false),
            "RTRIM" => EvaluateTrim(arguments, "rtrim", trimStart: false, trimEnd: true),
            "QUOTE" => EvaluateQuote(arguments),
            "CHAR" => EvaluateChar(arguments),
            "UNICODE" => EvaluateUnicode(arguments),
            "UNHEX" => EvaluateUnhex(arguments),
            "ZEROBLOB" => EvaluateZeroBlob(arguments),
            "RANDOMBLOB" => EvaluateRandomBlob(arguments),
            "RANDOM" => EvaluateRandom(arguments),
            "CONCAT" => EvaluateConcat(arguments),
            "CONCAT_WS" => EvaluateConcatWithSeparator(arguments),
            "IIF" => EvaluateIif(arguments),
            "LIKELY" => EvaluateProbabilityHint("likely", arguments, 1),
            "UNLIKELY" => EvaluateProbabilityHint("unlikely", arguments, 1),
            "LIKELIHOOD" => EvaluateProbabilityHint("likelihood", arguments, 2),
            "SQLITE_VERSION" => EvaluateSqliteVersion(arguments),
            "SQLITE_SOURCE_ID" => EvaluateSqliteSourceId(arguments),
            "CHANGES" => EvaluateChanges(arguments),
            "TOTAL_CHANGES" => EvaluateTotalChanges(arguments),
            "TIMEDIFF" => EvaluateTimeDiff(arguments),
            "COALESCE" => EvaluateCoalesce(arguments),
            "DATE" => SqliteDateTime.Execute(arguments, SqliteDateTime.Func.Date),
            "DATETIME" => SqliteDateTime.Execute(arguments, SqliteDateTime.Func.DateTime),
            "GLOB" => EvaluateGlobFunction(arguments),
            "HEX" => EvaluateHex(arguments),
            "IFNULL" => EvaluateIfNull(arguments),
            "INSTR" => EvaluateInstr(arguments),
            "JSON" => SqliteJson.Json(arguments),
            "JSON_ARRAY" => SqliteJson.JsonArray(arguments),
            "JSON_ARRAY_LENGTH" => SqliteJson.JsonArrayLength(arguments),
            "JSON_ERROR_POSITION" => SqliteJson.JsonErrorPosition(arguments),
            "JSON_EXTRACT" => SqliteJson.JsonExtract(arguments),
            "JSON_INSERT" => SqliteJson.JsonInsert(arguments),
            "JSON_OBJECT" => SqliteJson.JsonObject(arguments),
            "JSON_PATCH" => SqliteJson.JsonPatch(arguments),
            "JSON_PRETTY" => SqliteJson.JsonPretty(arguments),
            "JSON_QUOTE" => SqliteJson.JsonQuote(arguments),
            "JSON_REMOVE" => SqliteJson.JsonRemove(arguments),
            "JSON_REPLACE" => SqliteJson.JsonReplace(arguments),
            "JSON_SET" => SqliteJson.JsonSet(arguments),
            "JSON_TYPE" => SqliteJson.JsonType(arguments),
            "JSON_VALID" => SqliteJson.JsonValid(arguments),
            "JULIANDAY" => SqliteDateTime.Execute(arguments, SqliteDateTime.Func.JulianDay),
            "LAST_INSERT_ROWID" => EvaluateLastInsertRowId(arguments, context),
            "LENGTH" => EvaluateLength(arguments),
            "LIKE" => EvaluateLikeFunction(arguments),
            "LOWER" => EvaluateCase(arguments, ToSqliteLower),
            "MIN" => EvaluateScalarMinMax(function, arguments, context, maximum: false),
            "MAX" => EvaluateScalarMinMax(function, arguments, context, maximum: true),
            "NULLIF" => EvaluateNullIf(function, arguments, context),
            "FORMAT" or "PRINTF" => EvaluatePrintf(arguments),
            "STRFTIME" => SqliteDateTime.Strftime(arguments),
            "TIME" => SqliteDateTime.Execute(arguments, SqliteDateTime.Func.Time),
            "TYPEOF" => EvaluateTypeOf(arguments),
            "UNIXEPOCH" => SqliteDateTime.Execute(arguments, SqliteDateTime.Func.UnixEpoch),
            "UPPER" => EvaluateCase(arguments, ToSqliteUpper),
            "UUID4_STR" or "GEN_RANDOM_UUID" => SqlValue.Text(FormatUuid(CreateUuid4())),
            "UUID4" => SqlValue.Blob(CreateUuid4()),
            "UUID7_STR" => EvaluateUuid7String(arguments),
            "UUID7" => EvaluateUuid7Blob(arguments),
            "UUID7_TIMESTAMP_MS" => EvaluateUuid7TimestampMilliseconds(arguments),
            "UUID_STR" => EvaluateUuidString(arguments),
            "UUID_BLOB" => EvaluateUuidBlob(arguments),
            _ => throw new EmbeddedSqlException($"no such function: {function.Name}"),
        };
    }

    private static SqlValue EvaluateGlobFunction(IReadOnlyList<SqlValue> arguments)
    {
        RequireArgumentCount("glob", arguments, 2);
        return EvaluateGlobValues(arguments[1], arguments[0], negated: false);
    }

    // Keep this bounded independently of SQLite's process-wide SQLITE_LIMIT_LENGTH. The managed
    // evaluator must not let a SQL format string allocate an unbounded managed string.
    private const int MaximumPrintfWidth = 1_000_000;
    private const int MaximumPrintfPrecision = 1_000;
    private const int MaximumPrintfOutputLength = 1_000_000;

    // SQLite format() is an alias for printf(). Keep the parser independent of the platform
    // formatter so width, precision, rounding, quoting, and numeric coercion remain deterministic.
    private static SqlValue EvaluatePrintf(IReadOnlyList<SqlValue> arguments)
    {
        if (arguments.Count == 0 || arguments[0].Kind == SqlValueKind.Null)
            return SqlValue.Null;

        var format = ToPrintfText(arguments[0]);
        if (format.Length == 0)
            return SqlValue.Null;

        var result = new StringBuilder(Math.Min(format.Length, MaximumPrintfOutputLength));
        var argumentIndex = 1;
        for (var formatIndex = 0; formatIndex < format.Length; formatIndex++)
        {
            var character = format[formatIndex];
            if (character != '%')
            {
                AppendPrintfOutput(result, character.ToString());
                continue;
            }

            if (++formatIndex == format.Length)
            {
                AppendPrintfOutput(result, "%");
                break;
            }

            if (format[formatIndex] == '%')
            {
                AppendPrintfOutput(result, "%");
                continue;
            }

            var specifier = ParsePrintfSpecifier(
                format,
                ref formatIndex,
                arguments,
                ref argumentIndex);
            if (specifier.Verb == 'n')
                continue;

            var value = argumentIndex < arguments.Count ? arguments[argumentIndex] : SqlValue.Null;
            argumentIndex++;
            AppendPrintfOutput(result, FormatPrintfValue(specifier, value).Value);
        }

        return SqlValue.Text(result.ToString());
    }

    private static PrintfSpecifier ParsePrintfSpecifier(
        string format,
        ref int formatIndex,
        IReadOnlyList<SqlValue> arguments,
        ref int argumentIndex)
    {
        var leftJustify = false;
        var forceSign = false;
        var spaceSign = false;
        var zeroPad = false;
        var alternate = false;
        var alternate2 = false;
        var comma = false;

        while (formatIndex < format.Length)
        {
            switch (format[formatIndex])
            {
                case '-':
                    leftJustify = true;
                    formatIndex++;
                    continue;
                case '+':
                    forceSign = true;
                    formatIndex++;
                    continue;
                case ' ':
                    spaceSign = true;
                    formatIndex++;
                    continue;
                case '0':
                    zeroPad = true;
                    formatIndex++;
                    continue;
                case '#':
                    alternate = true;
                    formatIndex++;
                    continue;
                case '!':
                    alternate2 = true;
                    formatIndex++;
                    continue;
                case ',':
                    comma = true;
                    formatIndex++;
                    continue;
                default:
                    break;
            }

            break;
        }

        int? width;
        if (formatIndex < format.Length && format[formatIndex] == '*')
        {
            formatIndex++;
            var dynamicWidth = ReadPrintfDynamicSize(arguments, ref argumentIndex, MaximumPrintfWidth, "width");
            if (dynamicWidth < 0)
            {
                leftJustify = true;
                dynamicWidth = -dynamicWidth;
            }

            width = dynamicWidth;
        }
        else
        {
            width = ReadPrintfSize(format, ref formatIndex, MaximumPrintfWidth, "width");
        }

        int? precision = null;
        if (formatIndex < format.Length && format[formatIndex] == '.')
        {
            formatIndex++;
            if (formatIndex < format.Length && format[formatIndex] == '*')
            {
                formatIndex++;
                precision = Math.Abs(ReadPrintfDynamicSize(
                    arguments,
                    ref argumentIndex,
                    MaximumPrintfPrecision,
                    "precision"));
            }
            else
            {
                precision = ReadPrintfSize(format, ref formatIndex, MaximumPrintfPrecision, "precision") ?? 0;
            }
        }

        if (formatIndex == format.Length)
            throw new EmbeddedSqlException("unterminated printf format specifier.");

        if (format[formatIndex] == 'l')
        {
            formatIndex++;
            if (formatIndex < format.Length && format[formatIndex] == 'l')
                formatIndex++;
            if (formatIndex == format.Length)
                throw new EmbeddedSqlException("unterminated printf format specifier.");
        }

        var verb = format[formatIndex];
        if (!IsSupportedPrintfVerb(verb))
            throw new EmbeddedSqlException($"unsupported printf format conversion: %{verb}");

        var numeric = verb is 'd' or 'i' or 'u' or 'x' or 'X' or 'o' or 'r' or 'p'
            or 'f' or 'e' or 'E' or 'g' or 'G';
        var signedNumeric = verb is 'd' or 'i' or 'r' or 'f' or 'e' or 'E' or 'g' or 'G';

        // SQLite resolves a "-" and "0" flag pair differently per conversion class: an integer
        // stays zero padded (%-05d is "00042") while a real is left justified (%-010.2f is
        // "3.14      "). A "0" on a string conversion is ignored entirely.
        var realVerb = verb is 'f' or 'e' or 'E' or 'g' or 'G';
        var zeroPadsNumeric = zeroPad && numeric;

        return new PrintfSpecifier(
            verb,
            leftJustify && !(zeroPadsNumeric && !realVerb),
            forceSign && signedNumeric,
            spaceSign && signedNumeric,
            zeroPadsNumeric && !(leftJustify && realVerb),
            alternate,
            alternate2,
            comma,
            width,
            precision);
    }

    private static int ReadPrintfDynamicSize(
        IReadOnlyList<SqlValue> arguments,
        ref int argumentIndex,
        int maximum,
        string kind)
    {
        var value = argumentIndex < arguments.Count
            ? ToPrintfInteger(arguments[argumentIndex])
            : 0;
        argumentIndex++;
        if (value > maximum || value < -maximum)
            throw new EmbeddedSqlException($"printf {kind} exceeds {maximum}.");

        return (int)value;
    }

    private static int? ReadPrintfSize(string format, ref int formatIndex, int maximum, string kind)
    {
        if (formatIndex == format.Length || !char.IsAsciiDigit(format[formatIndex]))
            return null;

        var value = 0;
        while (formatIndex < format.Length && char.IsAsciiDigit(format[formatIndex]))
        {
            var digit = format[formatIndex] - '0';
            if (value > (maximum - digit) / 10)
                throw new EmbeddedSqlException($"printf {kind} exceeds {maximum}.");

            value = value * 10 + digit;
            formatIndex++;
        }

        return value;
    }

    private static bool IsSupportedPrintfVerb(char verb)
        => verb is 's' or 'd' or 'i' or 'u' or 'x' or 'X' or 'o'
            or 'f' or 'e' or 'E' or 'g' or 'G' or 'c' or 'q' or 'Q' or 'w'
            or 'p' or 'r' or 'z' or 'n';

    private static void AppendPrintfOutput(StringBuilder output, string value)
    {
        if (value.Length > MaximumPrintfOutputLength - output.Length)
            throw new EmbeddedSqlException($"printf output exceeds {MaximumPrintfOutputLength} characters.");

        output.Append(value);
    }

    private static PrintfText FormatPrintfValue(PrintfSpecifier specifier, SqlValue value)
    {
        return specifier.Verb switch
        {
            's' => ApplyPrintfTextWidth(
                specifier,
                value.Kind == SqlValueKind.Null
                    ? PrintfText.Empty
                    : LimitPrintfText(value, specifier.Precision, specifier.Alternate2)),
            'z' => ApplyPrintfTextWidth(
                specifier,
                value.Kind == SqlValueKind.Null
                    ? PrintfText.Empty
                    : LimitPrintfText(value, specifier.Precision, specifier.Alternate2)),
            'd' or 'i' => FormatPrintfSignedInteger(specifier, ToPrintfInteger(value)),
            'u' => FormatPrintfUnsignedInteger(
                specifier,
                unchecked((ulong)ToPrintfInteger(value)).ToString(CultureInfo.InvariantCulture),
                group: true),
            'x' => FormatPrintfUnsignedInteger(
                specifier,
                unchecked((ulong)ToPrintfInteger(value)).ToString("x", CultureInfo.InvariantCulture),
                specifier.Alternate && ToPrintfInteger(value) != 0 ? "0x" : string.Empty),
            'X' => FormatPrintfUnsignedInteger(
                specifier,
                unchecked((ulong)ToPrintfInteger(value)).ToString("X", CultureInfo.InvariantCulture),
                specifier.Alternate && ToPrintfInteger(value) != 0 ? "0X" : string.Empty),
            'o' => FormatPrintfUnsignedInteger(
                specifier,
                FormatPrintfOctal(unchecked((ulong)ToPrintfInteger(value))),
                specifier.Alternate && ToPrintfInteger(value) != 0 ? "0" : string.Empty),
            'p' => FormatPrintfUnsignedInteger(
                specifier,
                unchecked((ulong)ToPrintfInteger(value)).ToString("X", CultureInfo.InvariantCulture),
                specifier.Alternate && ToPrintfInteger(value) != 0 ? "0x" : string.Empty),
            'r' => FormatPrintfOrdinal(specifier, ToPrintfInteger(value)),
            'f' or 'e' or 'E' or 'g' or 'G' => FormatPrintfFloatingPoint(specifier, ToPrintfReal(value)),
            'c' => FormatPrintfCharacter(specifier, value),
            'q' => FormatPrintfQuotedText(specifier, value, '\0'),
            'Q' => FormatPrintfQuotedText(specifier, value, '\''),
            'w' => FormatPrintfQuotedText(specifier, value, '"'),
            _ => throw new InvalidOperationException($"Unexpected printf verb {specifier.Verb}."),
        };
    }

    private static PrintfText FormatPrintfSignedInteger(PrintfSpecifier specifier, long value)
    {
        var negative = value < 0;
        var magnitude = negative
            ? unchecked((ulong)(-(value + 1))) + 1
            : (ulong)value;
        var digits = ApplyPrintfIntegerPrecision(
            magnitude.ToString(CultureInfo.InvariantCulture),
            specifier.Precision);
        var sign = negative ? "-" : specifier.ForceSign ? "+" : specifier.SpaceSign ? " " : string.Empty;
        if (specifier.Comma)
        {
            if (specifier.ZeroPad && specifier.Width is { } width)
                digits = digits.PadLeft(Math.Max(digits.Length, width - sign.Length), '0');
            digits = AddPrintfThousandsSeparators(digits);
        }
        return ApplyPrintfNumericWidth(
            specifier.Comma && specifier.ZeroPad ? specifier with { Width = null } : specifier,
            sign,
            digits);
    }

    private static PrintfText FormatPrintfUnsignedInteger(
        PrintfSpecifier specifier,
        string digits,
        string prefix = "",
        bool group = false)
    {
        digits = ApplyPrintfIntegerPrecision(digits, specifier.Precision);
        if (specifier.Comma && group)
        {
            if (specifier.ZeroPad && specifier.Width is { } width)
                digits = digits.PadLeft(width, '0');
            digits = AddPrintfThousandsSeparators(digits);
        }

        return ApplyPrintfNumericWidth(
            specifier.Comma && group && specifier.ZeroPad
                ? specifier with { Width = null }
                : specifier,
            prefix,
            digits);
    }

    private static PrintfText FormatPrintfOrdinal(PrintfSpecifier specifier, long value)
    {
        var magnitude = value < 0
            ? unchecked((ulong)(-(value + 1))) + 1
            : (ulong)value;
        var suffix = magnitude % 100 is 11 or 12 or 13
            ? "th"
            : (magnitude % 10) switch
            {
                1 => "st",
                2 => "nd",
                3 => "rd",
                _ => "th",
            };
        var digits = string.Concat(
            ApplyPrintfIntegerPrecision(
                magnitude.ToString(CultureInfo.InvariantCulture),
                specifier.Precision),
            suffix);
        var sign = value < 0 ? "-" : specifier.ForceSign ? "+" : specifier.SpaceSign ? " " : string.Empty;
        return ApplyPrintfNumericWidth(specifier, sign, digits);
    }

    private static string ApplyPrintfIntegerPrecision(string digits, int? precision)
    {
        if (precision is not { } minimumDigits || digits.Length >= minimumDigits)
            return digits;

        return string.Concat(new string('0', minimumDigits - digits.Length), digits);
    }

    private static string AddPrintfThousandsSeparators(string digits)
    {
        if (digits.Length <= 3)
            return digits;

        var firstGroupLength = digits.Length % 3;
        if (firstGroupLength == 0)
            firstGroupLength = 3;
        var builder = new StringBuilder(digits.Length + (digits.Length - 1) / 3);
        builder.Append(digits.AsSpan(0, firstGroupLength));
        for (var index = firstGroupLength; index < digits.Length; index += 3)
        {
            builder.Append(',');
            builder.Append(digits.AsSpan(index, 3));
        }

        return builder.ToString();
    }

    private static PrintfText FormatPrintfFloatingPoint(PrintfSpecifier specifier, double value)
    {
        var negative = value < 0;
        var sign = negative ? "-" : specifier.ForceSign ? "+" : specifier.SpaceSign ? " " : string.Empty;
        var digits = FormatPrintfReal(
            specifier.Verb,
            Math.Abs(value),
            specifier.Precision,
            specifier.Alternate,
            specifier.Alternate2,
            specifier.ZeroPad);
        if (specifier.Comma && specifier.Verb == 'f')
        {
            var decimalIndex = digits.IndexOf('.');
            var integerLength = decimalIndex < 0 ? digits.Length : decimalIndex;
            digits = string.Concat(
                AddPrintfThousandsSeparators(digits[..integerLength]),
                digits.AsSpan(integerLength));
        }

        return ApplyPrintfNumericWidth(specifier, sign, digits);
    }

    private static PrintfText FormatPrintfQuotedText(PrintfSpecifier specifier, SqlValue value, char quote)
    {
        if (value.Kind == SqlValueKind.Null)
        {
            var nullText = quote == '\'' ? "NULL" : "(NULL)";
            return ApplyPrintfTextWidth(
                specifier,
                LimitPrintfText(nullText, specifier.Precision, specifier.Alternate2));
        }

        var text = LimitPrintfText(value, specifier.Precision, specifier.Alternate2);
        if (specifier.Alternate && quote is '\0' or '\'')
            return FormatPrintfEscapedControlText(specifier, text, quote == '\'');

        var quoteCount = text.Value.Count(character => character == quote || (quote == '\0' && character == '\''));
        var enclosingQuoteCount = quote == '\'' ? 2 : 0;
        if (text.Value.Length > MaximumPrintfOutputLength - quoteCount - enclosingQuoteCount)
            throw new EmbeddedSqlException($"printf output exceeds {MaximumPrintfOutputLength} characters.");

        var escaped = quote switch
        {
            '\0' => text.Value.Replace("'", "''", StringComparison.Ordinal),
            '\'' => $"'{text.Value.Replace("'", "''", StringComparison.Ordinal)}'",
            '"' => text.Value.Replace("\"", "\"\"", StringComparison.Ordinal),
            _ => throw new InvalidOperationException($"Unexpected printf quote {quote}."),
        };
        var byteLength = text.ByteLength + quoteCount + enclosingQuoteCount;
        return ApplyPrintfTextWidth(specifier, new PrintfText(escaped, byteLength));
    }

    private static PrintfText FormatPrintfEscapedControlText(
        PrintfSpecifier specifier,
        PrintfText text,
        bool enclose)
    {
        var builder = new StringBuilder(text.Value.Length);
        var changed = false;
        foreach (var rune in text.Value.EnumerateRunes())
        {
            if (Rune.IsControl(rune))
            {
                builder.Append(@"\u");
                builder.Append(rune.Value.ToString("x4", CultureInfo.InvariantCulture));
                changed = true;
            }
            else if (rune.Value == '\'')
            {
                builder.Append("''");
            }
            else
            {
                builder.Append(rune.ToString());
            }
        }

        var escaped = builder.ToString();
        if (enclose)
            escaped = changed ? $"unistr('{escaped}')" : $"'{escaped}'";
        return ApplyPrintfTextWidth(
            specifier,
            new PrintfText(escaped, Encoding.UTF8.GetByteCount(escaped)));
    }

    private static PrintfText FormatPrintfCharacter(PrintfSpecifier specifier, SqlValue value)
    {
        if (value.Kind == SqlValueKind.Null)
            return ApplyPrintfTextWidth(specifier, PrintfText.Empty);

        var text = ToPrintfText(value);
        var runes = text.EnumerateRunes();
        if (!runes.MoveNext())
            return ApplyPrintfTextWidth(specifier, PrintfText.Empty);

        var character = runes.Current.ToString();
        var count = specifier.Precision is > 0 ? specifier.Precision.Value : 1;
        var builder = new StringBuilder(character.Length * count);
        for (var index = 0; index < count; index++)
            builder.Append(character);

        var output = builder.ToString();
        return ApplyPrintfTextWidth(
            specifier,
            new PrintfText(output, Encoding.UTF8.GetByteCount(character) * count));
    }

    private static PrintfText LimitPrintfText(
        SqlValue value,
        int? precision,
        bool characterPrecision = false)
        => value.Kind == SqlValueKind.Text
            ? LimitPrintfText(value.AsText(), precision, characterPrecision)
            : LimitPrintfText(ToPrintfText(value), precision, characterPrecision);

    private static PrintfText LimitPrintfText(
        string value,
        int? precision,
        bool characterPrecision = false)
    {
        if (characterPrecision && precision is { } characterLimit)
        {
            var builder = new StringBuilder(Math.Min(value.Length, characterLimit));
            var count = 0;
            foreach (var rune in value.EnumerateRunes())
            {
                if (rune.Value == 0 || count++ == characterLimit)
                    break;
                builder.Append(rune.ToString());
            }

            var text = builder.ToString();
            return new PrintfText(text, Encoding.UTF8.GetByteCount(text));
        }

        if (precision is not { } byteLimit)
        {
            var terminatorOffset = value.IndexOf('\0');
            var textLength = terminatorOffset >= 0 ? terminatorOffset : value.Length;
            if (textLength > MaximumPrintfOutputLength)
                throw new EmbeddedSqlException($"printf output exceeds {MaximumPrintfOutputLength} characters.");

            var text = terminatorOffset >= 0 ? value[..terminatorOffset] : value;
            return new PrintfText(text, Encoding.UTF8.GetByteCount(text));
        }

        if (byteLimit == 0)
            return PrintfText.Empty;

        // Each UTF-16 code unit produces at least one UTF-8 byte. Inspecting at most byteLimit
        // code units therefore establishes the requested prefix without traversing the remainder.
        var sourceLength = Math.Min(value.Length, byteLimit);
        var source = value.AsSpan(0, sourceLength);
        var nulOffset = source.IndexOf('\0');
        var isTerminated = nulOffset >= 0;
        if (isTerminated)
            source = source[..nulOffset];

        Span<byte> bytes = stackalloc byte[byteLimit + 3];
        Encoding.UTF8.GetEncoder().Convert(
            source,
            bytes,
            flush: true,
            out _,
            out var bytesUsed,
            out var completed);

        if ((sourceLength == value.Length || isTerminated) && completed && bytesUsed <= byteLimit)
        {
            var text = isTerminated ? source.ToString() : value;
            return new PrintfText(text, bytesUsed);
        }

        return new PrintfText(Encoding.UTF8.GetString(bytes[..byteLimit]), byteLimit);
    }

    private static PrintfText ApplyPrintfTextWidth(PrintfSpecifier specifier, PrintfText text)
    {
        var length = specifier.Alternate2
            ? text.Value.EnumerateRunes().Count()
            : text.ByteLength;
        var padding = Math.Max(0, (specifier.Width ?? 0) - length);
        if (padding == 0)
            return text;

        var spaces = new string(' ', padding);
        return specifier.LeftJustify
            ? new PrintfText(string.Concat(text.Value, spaces), text.ByteLength + padding)
            : new PrintfText(string.Concat(spaces, text.Value), text.ByteLength + padding);
    }

    private static PrintfText ApplyPrintfNumericWidth(PrintfSpecifier specifier, string sign, string digits)
    {
        // An alternate-form integer prefix such as "0x" sits outside the zero padded field in
        // SQLite, so %#04x of 255 pads the digits to four and still emits the prefix: "0x00ff".
        var prefixIsAlternateInteger = sign is "0" or "0x" or "0X";
        var zeroPadsDigitsOnly = specifier.ZeroPad && prefixIsAlternateInteger && !specifier.LeftJustify;
        var occupied = zeroPadsDigitsOnly ? digits.Length : sign.Length + digits.Length;
        var padding = Math.Max(0, (specifier.Width ?? 0) - occupied);
        if (padding == 0)
            return new PrintfText(string.Concat(sign, digits), sign.Length + digits.Length);

        if (specifier.LeftJustify)
        {
            var spaces = new string(' ', padding);
            return new PrintfText(string.Concat(sign, digits, spaces), sign.Length + digits.Length + padding);
        }

        if (specifier.ZeroPad)
        {
            var zeroes = new string('0', padding);
            var formatted = string.Concat(sign, zeroes, digits);
            return new PrintfText(formatted, formatted.Length);
        }

        var leadingSpaces = new string(' ', padding);
        return new PrintfText(string.Concat(leadingSpaces, sign, digits), sign.Length + digits.Length + padding);
    }

    private static string ToPrintfText(SqlValue value)
    {
        if (value.Kind == SqlValueKind.Integer)
            return value.AsInteger().ToString(CultureInfo.InvariantCulture);
        if (value.Kind == SqlValueKind.Text)
            return TruncatePrintfAtNul(value.AsText());
        if (value.Kind == SqlValueKind.Real)
            return FormatPrintfTextReal(value.AsReal());
        if (value.Kind != SqlValueKind.Blob)
            throw new EmbeddedSqlException($"Cannot convert {value.Kind} to printf text.");

        var blob = value.AsBlob().Span;
        var nulOffset = blob.IndexOf((byte)0);
        if (nulOffset >= 0)
            blob = blob[..nulOffset];

        try
        {
            return TruncatePrintfAtNul(
                new UTF8Encoding(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: true).GetString(blob));
        }
        catch (DecoderFallbackException exception)
        {
            throw new EmbeddedSqlException("printf() only supports UTF-8 blob arguments.", exception);
        }
    }

    private static string TruncatePrintfAtNul(string value)
    {
        var nulOffset = value.IndexOf('\0');
        return nulOffset >= 0 ? value[..nulOffset] : value;
    }

    internal static string FormatPrintfTextReal(double value)
    {
        if (double.IsNaN(value))
            return "NaN";
        if (double.IsPositiveInfinity(value))
            return "Inf";
        if (double.IsNegativeInfinity(value))
            return "-Inf";
        if (value == 0)
            return "0.0";

        var formatted = FormatPrintfGeneral(Math.Abs(value), 15, upperCase: false);
        if (value < 0)
            formatted = string.Concat("-", formatted);

        var exponentIndex = formatted.IndexOfAny(['e', 'E']);
        if (exponentIndex < 0)
            return formatted.Contains('.') ? formatted : $"{formatted}.0";

        var mantissa = formatted[..exponentIndex];
        if (!mantissa.Contains('.'))
            mantissa += ".0";

        var exponent = NormalizePrintfExponent(formatted[exponentIndex..], upperCase: false);
        return string.Concat(mantissa, exponent);
    }

    private static string NormalizePrintfExponent(string exponent, bool upperCase)
    {
        var sign = exponent[1];
        var digits = exponent[2..].TrimStart('0');
        if (digits.Length == 0)
            digits = "0";

        return string.Concat(upperCase ? "E" : "e", sign, digits.PadLeft(2, '0'));
    }

    private static long ToPrintfInteger(SqlValue value)
    {
        return value.Kind switch
        {
            SqlValueKind.Null => 0,
            SqlValueKind.Integer => value.AsInteger(),
            SqlValueKind.Real => ToSqliteInteger(value.AsReal()),
            _ => ToPrintfInteger(ToPrintfText(value)),
        };
    }

    private static long ToPrintfInteger(string text)
    {
        var numericPrefix = GetSqliteNumericPrefix(text);
        if (numericPrefix is null)
            return 0;

        if (!ContainsPrintfRealMarker(numericPrefix))
            return ParseSqliteInteger(numericPrefix);

        return double.TryParse(
            numericPrefix,
            NumberStyles.Float,
            CultureInfo.InvariantCulture,
            out var real)
            ? ToSqliteInteger(real)
            : 0;
    }

    private static double ToPrintfReal(SqlValue value)
    {
        return value.Kind switch
        {
            SqlValueKind.Null => 0,
            SqlValueKind.Integer => value.AsInteger(),
            SqlValueKind.Real => value.AsReal(),
            _ => ToPrintfReal(ToPrintfText(value)),
        };
    }

    private static double ToPrintfReal(string text)
    {
        var numericPrefix = GetSqliteNumericPrefix(text);
        return numericPrefix is not null
            && double.TryParse(numericPrefix, NumberStyles.Float, CultureInfo.InvariantCulture, out var real)
            ? real
            : 0;
    }

    private static string? GetSqliteNumericPrefix(string value)
    {
        var index = 0;
        while (index < value.Length && char.IsWhiteSpace(value[index]))
            index++;

        var start = index;
        if (index < value.Length && value[index] is '+' or '-')
            index++;

        var digitStart = index;
        while (index < value.Length && char.IsAsciiDigit(value[index]))
            index++;
        var hasDigits = index != digitStart;

        if (index < value.Length && value[index] == '.')
        {
            index++;
            var fractionalDigitStart = index;
            while (index < value.Length && char.IsAsciiDigit(value[index]))
                index++;
            hasDigits |= index != fractionalDigitStart;
        }

        if (!hasDigits)
            return null;

        if (index < value.Length && value[index] is 'e' or 'E')
        {
            var exponentStart = index++;
            if (index < value.Length && value[index] is '+' or '-')
                index++;
            var exponentDigitStart = index;
            while (index < value.Length && char.IsAsciiDigit(value[index]))
                index++;
            if (index == exponentDigitStart)
                index = exponentStart;
        }

        return value[start..index];
    }

    private static long ParseSqliteInteger(string value)
    {
        var index = 0;
        while (index < value.Length && char.IsWhiteSpace(value[index]))
            index++;

        var negative = index < value.Length && value[index] == '-';
        if (index < value.Length && value[index] is '+' or '-')
            index++;

        if (!ulong.TryParse(value[index..], NumberStyles.None, CultureInfo.InvariantCulture, out var magnitude))
            return negative ? long.MinValue : long.MaxValue;

        if (negative)
        {
            const ulong MinimumMagnitude = 9_223_372_036_854_775_808;
            return magnitude switch
            {
                > MinimumMagnitude => long.MinValue,
                MinimumMagnitude => long.MinValue,
                _ => -(long)magnitude,
            };
        }

        return magnitude > long.MaxValue ? long.MaxValue : (long)magnitude;
    }

    private static long ToSqliteInteger(double value)
    {
        if (double.IsNaN(value))
            return 0;
        if (value >= long.MaxValue)
            return long.MaxValue;
        if (value <= long.MinValue)
            return long.MinValue;

        return (long)Math.Truncate(value);
    }

    private static string FormatPrintfOctal(ulong value)
    {
        Span<char> buffer = stackalloc char[22];
        var index = buffer.Length;
        do
        {
            buffer[--index] = (char)('0' + (value & 7));
            value >>= 3;
        } while (value != 0);

        return new string(buffer[index..]);
    }

    private static string FormatPrintfReal(
        char verb,
        double value,
        int? requestedPrecision,
        bool alternate,
        bool alternate2,
        bool zeroPad)
    {
        if (double.IsNaN(value))
            return "NaN";
        if (double.IsPositiveInfinity(value))
        {
            // SQLite renders an infinity as "Inf" unless zero padding was requested, in which
            // case zero padding a three character word would be meaningless, so it substitutes
            // the largest value its formatter can describe: 9.0e+999.
            if (!zeroPad)
                return "Inf";
            return FormatPrintfInfinitySubstitute(verb, requestedPrecision, alternate, alternate2);
        }

        if (alternate2 && requestedPrecision is > 26)
            requestedPrecision = 26;
        var forceDecimalPoint = alternate || alternate2;
        var formatted = verb switch
        {
            'f' => EnsurePrintfDecimalPoint(
                FormatPrintfFixed(value, requestedPrecision ?? 6),
                forceDecimalPoint,
                alternate2),
            'e' => EnsurePrintfDecimalPoint(
                FormatPrintfExponential(value, requestedPrecision ?? 6, upperCase: false),
                forceDecimalPoint,
                alternate2),
            'E' => EnsurePrintfDecimalPoint(
                FormatPrintfExponential(value, requestedPrecision ?? 6, upperCase: true),
                forceDecimalPoint,
                alternate2),
            'g' => EnsurePrintfDecimalPoint(
                FormatPrintfGeneral(
                    value,
                    requestedPrecision ?? 6,
                    upperCase: false,
                    preserveTrailingZeros: alternate),
                alternate2,
                alternate2),
            'G' => EnsurePrintfDecimalPoint(
                FormatPrintfGeneral(
                    value,
                    requestedPrecision ?? 6,
                    upperCase: true,
                    preserveTrailingZeros: alternate),
                alternate2,
                alternate2),
            _ => throw new InvalidOperationException($"Unexpected printf real verb {verb}."),
        };

        return alternate2 ? StripPrintfFractionZeros(formatted) : formatted;
    }

    /// <summary>
    /// Applies SQLite's <c>!</c> (alternate form 2) flag to an already formatted real: trailing
    /// fractional zeroes are removed while at least one fractional digit is retained, so
    /// <c>%!f</c> of 3.14 is "3.14" and of 1.0 is "1.0" rather than "1".
    /// </summary>
    private static string StripPrintfFractionZeros(string value)
    {
        var exponentIndex = value.IndexOfAny(['e', 'E']);
        var mantissa = exponentIndex < 0 ? value : value[..exponentIndex];
        var exponent = exponentIndex < 0 ? string.Empty : value[exponentIndex..];
        var pointIndex = mantissa.IndexOf('.');
        if (pointIndex < 0)
            return string.Concat(mantissa, ".0", exponent);

        var end = mantissa.Length;
        while (end > pointIndex + 2 && mantissa[end - 1] == '0')
            end--;

        return string.Concat(mantissa.AsSpan(0, end), exponent);
    }

    /// <summary>
    /// Renders the 9.0e+999 value SQLite substitutes for an infinity when zero padding is
    /// requested. The magnitude is beyond <see cref="double"/> range, so its digits are
    /// synthesized rather than computed.
    /// </summary>
    private static string FormatPrintfInfinitySubstitute(
        char verb,
        int? requestedPrecision,
        bool alternate,
        bool alternate2)
    {
        const int InfinityExponent = 999;
        var precision = requestedPrecision ?? 6;
        var forceDecimalPoint = alternate || alternate2;
        switch (verb)
        {
            case 'f':
                {
                    var digits = string.Concat("9", new string('0', InfinityExponent));
                    var formatted = precision > 0
                        ? string.Concat(digits, ".", new string('0', precision))
                        : digits;
                    return EnsurePrintfDecimalPoint(formatted, forceDecimalPoint, alternate2);
                }

            case 'e':
            case 'E':
                {
                    var mantissa = precision > 0
                        ? string.Concat("9.", new string('0', precision))
                        : "9";
                    var formatted = string.Concat(
                        mantissa,
                        verb == 'E' ? "E+" : "e+",
                        InfinityExponent.ToString(CultureInfo.InvariantCulture));
                    return EnsurePrintfDecimalPoint(formatted, forceDecimalPoint, alternate2);
                }

            default:
                {
                    // %g selects the exponential form because the exponent is far outside the
                    // range where the fixed form is used, and drops trailing zeroes unless the
                    // alternate flag asked for them.
                    var significant = Math.Max(1, precision);
                    var mantissa = alternate && significant > 1
                        ? string.Concat("9.", new string('0', significant - 1))
                        : "9";
                    var formatted = string.Concat(
                        mantissa,
                        verb == 'G' ? "E+" : "e+",
                        InfinityExponent.ToString(CultureInfo.InvariantCulture));
                    return EnsurePrintfDecimalPoint(formatted, alternate2, alternate2);
                }
        }
    }

    private static string EnsurePrintfDecimalPoint(
        string value,
        bool required,
        bool trailingZero = false)
    {
        if (!required)
            return value;
        var exponentIndex = value.IndexOfAny(['e', 'E']);
        var mantissa = exponentIndex < 0 ? value : value[..exponentIndex];
        if (mantissa.Contains('.'))
            return value;
        var decimalSuffix = trailingZero ? ".0" : ".";
        return exponentIndex < 0
            ? string.Concat(value, decimalSuffix)
            : string.Concat(mantissa, decimalSuffix, value.AsSpan(exponentIndex));
    }

    private static string FormatPrintfFixed(double value, int precision)
    {
        var digits = RoundPrintfReal(value, precision).ToString(CultureInfo.InvariantCulture);
        if (precision == 0)
            return digits;

        if (digits.Length <= precision)
            digits = digits.PadLeft(precision + 1, '0');

        return string.Concat(digits.AsSpan(0, digits.Length - precision), ".", digits.AsSpan(digits.Length - precision));
    }

    private static string FormatPrintfExponential(double value, int precision, bool upperCase)
    {
        if (value == 0)
            return BuildPrintfExponential(BigInteger.Zero, precision, 0, upperCase);

        var exponent = GetPrintfDecimalExponent(value);
        var digits = RoundPrintfReal(value, precision - exponent);
        var overflow = BigInteger.Pow(10, precision + 1);
        if (digits >= overflow)
        {
            digits /= 10;
            exponent++;
        }

        return BuildPrintfExponential(digits, precision, exponent, upperCase);
    }

    private static string FormatPrintfGeneral(
        double value,
        int requestedPrecision,
        bool upperCase,
        bool preserveTrailingZeros = false)
    {
        var precision = requestedPrecision == 0 ? 1 : requestedPrecision;
        if (value == 0)
            return preserveTrailingZeros
                ? precision == 1 ? "0." : string.Concat("0.", new string('0', precision - 1))
                : "0";

        var exponent = GetPrintfDecimalExponent(value);
        var digits = RoundPrintfReal(value, precision - 1 - exponent);
        var overflow = BigInteger.Pow(10, precision);
        if (digits >= overflow)
        {
            digits /= 10;
            exponent++;
        }

        if (exponent < -4 || exponent >= precision)
        {
            var exponential = BuildPrintfExponential(digits, precision - 1, exponent, upperCase);
            return preserveTrailingZeros ? exponential : TrimPrintfFractionalZeros(exponential);
        }

        var decimalDigits = digits.ToString(CultureInfo.InvariantCulture).PadLeft(precision, '0');
        string fixedPoint;
        if (exponent >= precision - 1)
        {
            fixedPoint = string.Concat(decimalDigits, new string('0', exponent - precision + 1));
        }
        else if (exponent >= 0)
        {
            fixedPoint = string.Concat(
                decimalDigits.AsSpan(0, exponent + 1),
                ".",
                decimalDigits.AsSpan(exponent + 1));
        }
        else
        {
            fixedPoint = string.Concat(
                "0.",
                new string('0', -exponent - 1),
                decimalDigits);
        }

        return preserveTrailingZeros ? EnsurePrintfDecimalPoint(fixedPoint, required: true) : TrimPrintfFractionalZeros(fixedPoint);
    }

    private static string BuildPrintfExponential(BigInteger digits, int precision, int exponent, bool upperCase)
    {
        var mantissaDigits = digits.ToString(CultureInfo.InvariantCulture).PadLeft(precision + 1, '0');
        var mantissa = precision == 0
            ? mantissaDigits
            : string.Concat(mantissaDigits[0], ".", mantissaDigits[1..]);
        var exponentSign = exponent < 0 ? '-' : '+';
        var exponentDigits = Math.Abs(exponent).ToString(CultureInfo.InvariantCulture).PadLeft(2, '0');
        return string.Concat(mantissa, upperCase ? "E" : "e", exponentSign, exponentDigits);
    }

    private static string TrimPrintfFractionalZeros(string value)
    {
        var exponentIndex = value.IndexOfAny(['e', 'E']);
        var mantissa = exponentIndex < 0 ? value : value[..exponentIndex];
        var exponent = exponentIndex < 0 ? string.Empty : value[exponentIndex..];
        if (!mantissa.Contains('.'))
            return value;

        mantissa = mantissa.TrimEnd('0').TrimEnd('.');
        return string.Concat(mantissa, exponent);
    }

    private static BigInteger RoundPrintfReal(double value, int decimalScale)
    {
        var parts = GetPrintfDoubleParts(value);
        var numerator = parts.Significand;
        var denominator = BigInteger.One;
        var binaryScale = parts.BinaryExponent;

        if (decimalScale >= 0)
        {
            numerator *= BigInteger.Pow(5, decimalScale);
            binaryScale += decimalScale;
        }
        else
        {
            denominator = BigInteger.Pow(5, -decimalScale);
            binaryScale += decimalScale;
        }

        if (binaryScale >= 0)
            numerator <<= binaryScale;
        else
            denominator <<= -binaryScale;

        var quotient = BigInteger.DivRem(numerator, denominator, out var remainder);
        var rounded = remainder * 2 >= denominator ? quotient + 1 : quotient;
        return ClampPrintfSignificantDigits(rounded);
    }

    /// <summary>
    /// SQLite decodes a double to at most 16 significant decimal digits and zero fills the rest,
    /// so <c>printf('%.25f', 0.1)</c> is "0.1000000000000000000000000" rather than the exact
    /// binary expansion "0.1000000000000000055511151".
    /// </summary>
    private static BigInteger ClampPrintfSignificantDigits(BigInteger digits)
    {
        const int MaximumSignificantDigits = 16;
        if (digits.IsZero)
            return digits;

        var length = BigInteger.Abs(digits).ToString(CultureInfo.InvariantCulture).Length;
        if (length <= MaximumSignificantDigits)
            return digits;

        var scale = BigInteger.Pow(10, length - MaximumSignificantDigits);
        var quotient = BigInteger.DivRem(digits, scale, out var remainder);
        if (remainder * 2 >= scale)
            quotient += 1;

        return quotient * scale;
    }

    private static int GetPrintfDecimalExponent(double value)
    {
        var exponent = (int)Math.Floor(Math.Log10(value));
        while (ComparePrintfRealWithPowerOfTen(value, exponent) < 0)
            exponent--;
        while (ComparePrintfRealWithPowerOfTen(value, exponent + 1) >= 0)
            exponent++;

        return exponent;
    }

    private static int ComparePrintfRealWithPowerOfTen(double value, int decimalExponent)
    {
        var parts = GetPrintfDoubleParts(value);
        if (decimalExponent >= 0)
        {
            var commonBinaryExponent = Math.Min(parts.BinaryExponent, decimalExponent);
            var left = parts.Significand << (parts.BinaryExponent - commonBinaryExponent);
            var right = BigInteger.Pow(5, decimalExponent) << (decimalExponent - commonBinaryExponent);
            return left.CompareTo(right);
        }

        var decimalPower = -decimalExponent;
        var numerator = parts.Significand * BigInteger.Pow(5, decimalPower);
        var binaryExponent = parts.BinaryExponent + decimalPower;
        return binaryExponent >= 0
            ? (numerator << binaryExponent).CompareTo(BigInteger.One)
            : numerator.CompareTo(BigInteger.One << -binaryExponent);
    }

    private static PrintfDoubleParts GetPrintfDoubleParts(double value)
    {
        var bits = unchecked((ulong)BitConverter.DoubleToInt64Bits(value));
        var exponent = (int)((bits >> 52) & 0x7ff);
        var fraction = bits & ((1UL << 52) - 1);
        return exponent == 0
            ? new PrintfDoubleParts(new BigInteger(fraction), -1074)
            : new PrintfDoubleParts(new BigInteger((1UL << 52) | fraction), exponent - 1023 - 52);
    }

    private readonly record struct PrintfSpecifier(
        char Verb,
        bool LeftJustify,
        bool ForceSign,
        bool SpaceSign,
        bool ZeroPad,
        bool Alternate,
        bool Alternate2,
        bool Comma,
        int? Width,
        int? Precision);

    private readonly record struct PrintfText(string Value, int ByteLength)
    {
        public static PrintfText Empty { get; } = new(string.Empty, 0);
    }

    private readonly record struct PrintfDoubleParts(BigInteger Significand, int BinaryExponent);

    // last_insert_rowid() reports the rowid of the most recent successful INSERT on this
    // connection, or 0 before any INSERT, matching SQLite's per-connection semantics.
    private static SqlValue EvaluateLastInsertRowId(IReadOnlyList<SqlValue> arguments, QueryContext context)
    {
        RequireArgumentCount("last_insert_rowid", arguments, 0);
        return SqlValue.Integer(GetLastInsertRowId(context));
    }

    private static long GetLastInsertRowId(QueryContext context)
        => context.TriggerState?.LiveLastInsertRowId
            ?? context.StatementState?.LastInsertRowId
            ?? context.LastInsertRowId;

    private static void SetLastInsertRowId(QueryContext context, long rowId)
    {
        if (context.TriggerState is not null)
        {
            context.TriggerState.LiveLastInsertRowId = rowId;
            return;
        }
        if (context.StatementState is null)
            throw new InvalidOperationException("INSERT execution lost its statement rowid state.");

        context.StatementState.LastInsertRowId = rowId;
    }

    private SqlValue EvaluateNullIf(
        FunctionExpression function,
        IReadOnlyList<SqlValue> arguments,
        QueryContext context)
    {
        RequireArgumentCount("nullif", arguments, 2);
        var value = arguments[0];
        if (value.Kind == SqlValueKind.Null)
            return SqlValue.Null;

        return Compare(
            value,
            arguments[1],
            GetComparisonCollation(
                function.Arguments[0],
                function.Arguments[1],
                context)) == 0
            ? SqlValue.Null
            : value;
    }

    private static SqlValue EvaluateAbsoluteValue(IReadOnlyList<SqlValue> arguments)
    {
        RequireArgumentCount("abs", arguments, 1);
        var value = arguments[0];
        if (value.Kind == SqlValueKind.Null)
            return SqlValue.Null;
        if (value.Kind == SqlValueKind.Integer)
        {
            if (value.AsInteger() == long.MinValue)
                throw new EmbeddedSqlException("integer overflow");

            return SqlValue.Integer(Math.Abs(value.AsInteger()));
        }

        // Text and blobs numerify rather than raising, so abs('abc') is 0.0 like SQLite.
        return SqlValue.Real(Math.Abs(AsReal(ApplyNumericAffinity(value))));
    }

    private static string ToSqliteLower(string value)
        => string.Create(value.Length, value, static (destination, source) =>
        {
            for (var index = 0; index < source.Length; index++)
            {
                var character = source[index];
                destination[index] = character is >= 'A' and <= 'Z'
                    ? (char)(character + ('a' - 'A'))
                    : character;
            }
        });

    private static string ToSqliteUpper(string value)
        => string.Create(value.Length, value, static (destination, source) =>
        {
            for (var index = 0; index < source.Length; index++)
            {
                var character = source[index];
                destination[index] = character is >= 'a' and <= 'z'
                    ? (char)(character - ('a' - 'A'))
                    : character;
            }
        });

    private static SqlValue EvaluateCoalesce(IReadOnlyList<SqlValue> arguments)
    {
        if (arguments.Count == 0)
            throw new EmbeddedSqlException("wrong number of arguments to function coalesce()");

        return arguments.FirstOrDefault(static value => value.Kind != SqlValueKind.Null);
    }

    private static SqlValue EvaluateHex(IReadOnlyList<SqlValue> arguments)
    {
        RequireArgumentCount("hex", arguments, 1);
        var value = arguments[0];
        if (value.Kind == SqlValueKind.Null)
            return SqlValue.Text(string.Empty);
        if (value.Kind == SqlValueKind.Blob)
            return SqlValue.Text(Convert.ToHexString(value.AsBlob().Span));

        return SqlValue.Text(Convert.ToHexString(System.Text.Encoding.UTF8.GetBytes(ToSqlText(value))));
    }

    private static SqlValue EvaluateUuid7String(IReadOnlyList<SqlValue> arguments)
    {
        if (arguments.Count == 0)
            return SqlValue.Text(FormatUuid(CreateUuid7((ulong)DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())));

        var seconds = arguments[0] switch
        {
            { Kind: SqlValueKind.Integer } value => value.AsInteger(),
            { Kind: SqlValueKind.Text } value => ParseUuid7StringTimestamp(value.AsText()),
            _ => throw new EmbeddedSqlException("invalid arguments to function uuid7_str()"),
        };
        return SqlValue.Text(FormatUuid(CreateUuid7FromUnixSeconds(seconds)));
    }

    private static SqlValue EvaluateUuid7Blob(IReadOnlyList<SqlValue> arguments)
    {
        if (arguments.Count == 0)
            return SqlValue.Blob(CreateUuid7((ulong)DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()));

        return arguments[0].Kind == SqlValueKind.Integer
            ? SqlValue.Blob(CreateUuid7FromUnixSeconds(arguments[0].AsInteger()))
            : SqlValue.Null;
    }

    private static SqlValue EvaluateUuid7TimestampMilliseconds(IReadOnlyList<SqlValue> arguments)
    {
        if (arguments.Count == 0)
            throw new EmbeddedSqlException("wrong number of arguments to function uuid7_timestamp_ms()");

        if (!TryGetUuidBytes(arguments[0], out var uuid))
            return SqlValue.Null;

        return SqlValue.Integer(
            ((long)uuid[0] << 40)
            | ((long)uuid[1] << 32)
            | ((long)uuid[2] << 24)
            | ((long)uuid[3] << 16)
            | ((long)uuid[4] << 8)
            | uuid[5]);
    }

    private static SqlValue EvaluateUuidString(IReadOnlyList<SqlValue> arguments)
    {
        if (arguments.Count == 0)
            throw new EmbeddedSqlException("wrong number of arguments to function uuid_str()");
        if (arguments[0].Kind != SqlValueKind.Blob || arguments[0].AsBlob().Length != 16)
            return SqlValue.Null;

        return SqlValue.Text(FormatUuid(arguments[0].AsBlob().Span));
    }

    private static SqlValue EvaluateUuidBlob(IReadOnlyList<SqlValue> arguments)
    {
        if (arguments.Count == 0)
            throw new EmbeddedSqlException("wrong number of arguments to function uuid_blob()");

        return arguments[0].Kind == SqlValueKind.Text && TryParseUuid(arguments[0].AsText(), out var uuid)
            ? SqlValue.Blob(uuid)
            : SqlValue.Null;
    }

    private static long ParseUuid7StringTimestamp(string value)
    {
        if (!long.TryParse(value, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out var seconds))
            throw new EmbeddedSqlException("invalid arguments to function uuid7_str()");
        if (seconds <= 0)
            throw new EmbeddedSqlException("Invalid timestamp");

        return seconds;
    }

    private static byte[] CreateUuid4()
    {
        var uuid = new byte[16];
        RandomNumberGenerator.Fill(uuid);
        uuid[6] = (byte)((uuid[6] & 0x0f) | 0x40);
        uuid[8] = (byte)((uuid[8] & 0x3f) | 0x80);
        return uuid;
    }

    private static byte[] CreateUuid7FromUnixSeconds(long seconds)
        => CreateUuid7(unchecked((ulong)seconds * 1000UL));

    private static byte[] CreateUuid7(ulong milliseconds)
    {
        var uuid = new byte[16];
        RandomNumberGenerator.Fill(uuid);
        uuid[0] = (byte)(milliseconds >> 40);
        uuid[1] = (byte)(milliseconds >> 32);
        uuid[2] = (byte)(milliseconds >> 24);
        uuid[3] = (byte)(milliseconds >> 16);
        uuid[4] = (byte)(milliseconds >> 8);
        uuid[5] = (byte)milliseconds;
        uuid[6] = (byte)((uuid[6] & 0x0f) | 0x70);
        uuid[8] = (byte)((uuid[8] & 0x3f) | 0x80);
        return uuid;
    }

    private static bool TryGetUuidBytes(SqlValue value, out byte[] uuid)
    {
        if (value.Kind == SqlValueKind.Blob && value.AsBlob().Length == 16)
        {
            uuid = value.AsBlob().ToArray();
            return true;
        }

        if (value.Kind == SqlValueKind.Text && TryParseUuid(value.AsText(), out uuid))
            return true;

        uuid = [];
        return false;
    }

    private static bool TryParseUuid(string value, out byte[] uuid)
    {
        if (value.Length == value.Trim().Length && Guid.TryParse(value, out var parsed))
        {
            uuid = Convert.FromHexString(parsed.ToString("N"));
            return true;
        }

        uuid = [];
        return false;
    }

    private static string FormatUuid(ReadOnlySpan<byte> uuid)
    {
        var hex = Convert.ToHexString(uuid).ToLowerInvariant();
        return $"{hex[..8]}-{hex[8..12]}-{hex[12..16]}-{hex[16..20]}-{hex[20..]}";
    }

    private static SqlValue EvaluateIfNull(IReadOnlyList<SqlValue> arguments)
    {
        RequireArgumentCount("ifnull", arguments, 2);
        return arguments[0].Kind == SqlValueKind.Null ? arguments[1] : arguments[0];
    }

    private static SqlValue EvaluateInstr(IReadOnlyList<SqlValue> arguments)
    {
        RequireArgumentCount("instr", arguments, 2);
        var haystack = arguments[0];
        var needle = arguments[1];
        if (haystack.Kind == SqlValueKind.Null || needle.Kind == SqlValueKind.Null)
            return SqlValue.Null;

        if (haystack.Kind == SqlValueKind.Blob && needle.Kind == SqlValueKind.Blob)
        {
            var offset = haystack.AsBlob().Span.IndexOf(needle.AsBlob().Span);
            return SqlValue.Integer(offset + 1L);
        }

        var text = ToSqlText(haystack);
        var index = text.IndexOf(ToSqlText(needle), StringComparison.Ordinal);
        if (index < 0)
            return SqlValue.Integer(0);

        var codePointCount = 0;
        foreach (var _ in text.AsSpan(0, index).EnumerateRunes())
            codePointCount++;
        return SqlValue.Integer(codePointCount + 1L);
    }

    private static SqlValue EvaluateLength(IReadOnlyList<SqlValue> arguments)
    {
        RequireArgumentCount("length", arguments, 1);
        var value = arguments[0];
        return value.Kind switch
        {
            SqlValueKind.Null => SqlValue.Null,
            SqlValueKind.Text => SqlValue.Integer(value.AsText().EnumerateRunes().Count()),
            SqlValueKind.Blob => SqlValue.Integer(value.AsBlob().Length),
            _ => SqlValue.Integer(ToSqlText(value).Length),
        };
    }

    private static SqlValue EvaluateLikeFunction(IReadOnlyList<SqlValue> arguments)
    {
        if (arguments.Count is < 2 or > 3)
            throw new EmbeddedSqlException("wrong number of arguments to function like()");

        return EvaluateLikeValues(
            arguments[1],
            arguments[0],
            arguments.Count == 3 ? arguments[2] : null,
            negated: false);
    }

    private SqlValue EvaluateScalarMinMax(
        FunctionExpression function,
        IReadOnlyList<SqlValue> arguments,
        QueryContext context,
        bool maximum)
    {
        if (arguments.Count < 2)
            throw new EmbeddedSqlException($"wrong number of arguments to function {(maximum ? "max" : "min")}()");

        var collation = function.Arguments
                .Select(argument => GetEffectiveCollation(argument, context))
                .FirstOrDefault(candidate => candidate is not null);
        var result = arguments[0];
        foreach (var value in arguments.Skip(1))
        {
            if (result.Kind == SqlValueKind.Null || value.Kind == SqlValueKind.Null)
                return SqlValue.Null;
            if (maximum
                    ? Compare(value, result, collation) > 0
                    : Compare(value, result, collation) < 0)
                result = value;
        }

        return result;
    }

    private static SqlValue EvaluateCase(IReadOnlyList<SqlValue> arguments, Func<string, string> transform)
    {
        RequireArgumentCount("case", arguments, 1);
        var value = arguments[0];
        return value.Kind == SqlValueKind.Null
            ? SqlValue.Null
            : SqlValue.Text(transform(ToSqlText(value)));
    }

    private static SqlValue EvaluateTypeOf(IReadOnlyList<SqlValue> arguments)
    {
        RequireArgumentCount("typeof", arguments, 1);
        return SqlValue.Text(arguments[0].Kind switch
        {
            SqlValueKind.Null => "null",
            SqlValueKind.Integer => "integer",
            SqlValueKind.Real => "real",
            SqlValueKind.Text => "text",
            SqlValueKind.Blob => "blob",
            _ => throw new InvalidOperationException($"Unknown SQL value kind {arguments[0].Kind}."),
        });
    }

    private static void RequireArgumentCount(string functionName, IReadOnlyList<SqlValue> arguments, int expected)
    {
        if (arguments.Count != expected)
            throw new EmbeddedSqlException($"wrong number of arguments to function {functionName}()");
    }

    private static SqlValue ApplyNumeric(SqlValue left, SqlValue right, Func<long, long, long> integerOperation, Func<double, double, double> realOperation)
    {
        left = ApplyNumericAffinity(left);
        right = ApplyNumericAffinity(right);
        if (left.Kind == SqlValueKind.Integer && right.Kind == SqlValueKind.Integer)
        {
            try
            {
                return SqlValue.Integer(integerOperation(left.AsInteger(), right.AsInteger()));
            }
            catch (OverflowException)
            {
                return SqlValue.Real(realOperation(left.AsInteger(), right.AsInteger()));
            }
        }

        return SqlValue.Real(realOperation(AsReal(left), AsReal(right)));
    }

    private static SqlValue ApplyDivision(SqlValue left, SqlValue right)
    {
        left = ApplyNumericAffinity(left);
        right = ApplyNumericAffinity(right);
        if (left.Kind == SqlValueKind.Integer && right.Kind == SqlValueKind.Integer)
        {
            var divisor = right.AsInteger();
            if (divisor == 0)
                return SqlValue.Null;
            if (left.AsInteger() == long.MinValue && divisor == -1)
                return SqlValue.Real(-(double)long.MinValue);

            return SqlValue.Integer(left.AsInteger() / divisor);
        }

        var realDivisor = AsReal(right);
        if (realDivisor == 0)
            return SqlValue.Null;

        return SqlValue.Real(AsReal(left) / realDivisor);
    }

    private static SqlValue ApplyModulo(SqlValue left, SqlValue right)
    {
        left = ApplyModuloNumericAffinity(left);
        right = ApplyModuloNumericAffinity(right);
        var returnReal = left.Kind == SqlValueKind.Real || right.Kind == SqlValueKind.Real;
        var dividend = left.Kind == SqlValueKind.Integer ? left.AsInteger() : ToSqliteInteger(left.AsReal());
        var divisor = right.Kind == SqlValueKind.Integer ? right.AsInteger() : ToSqliteInteger(right.AsReal());
        if (divisor == 0)
            return SqlValue.Null;

        var remainder = dividend == long.MinValue && divisor == -1 ? 0 : dividend % divisor;
        return returnReal ? SqlValue.Real(remainder) : SqlValue.Integer(remainder);
    }

    private static SqlValue ApplyBitwise(SqlValue left, SqlValue right, bool and)
    {
        var a = ToPrintfInteger(left);
        var b = ToPrintfInteger(right);
        return SqlValue.Integer(and ? a & b : a | b);
    }

    private static SqlValue ApplyShift(SqlValue value, SqlValue count, bool leftShift)
    {
        var integer = ToPrintfInteger(value);
        var shift = ToPrintfInteger(count);
        return VdbeArithmetic.Evaluate(
            leftShift ? ArithmeticOperator.ShiftLeft : ArithmeticOperator.ShiftRight,
            [SqlValue.Integer(integer), SqlValue.Integer(shift)]);
    }

    private static SqlValue ApplyModuloNumericAffinity(SqlValue value)
    {
        if (value.Kind is SqlValueKind.Integer or SqlValueKind.Real)
            return value;

        var text = value.Kind == SqlValueKind.Text ? value.AsText() : ToPrintfText(value);
        var numericPrefix = GetSqliteNumericPrefix(text);
        if (numericPrefix is null)
            return SqlValue.Integer(0);

        if (!ContainsPrintfRealMarker(numericPrefix))
            return SqlValue.Integer(ParseSqliteInteger(numericPrefix));

        return double.TryParse(
            numericPrefix,
            NumberStyles.Float,
            CultureInfo.InvariantCulture,
            out var real)
            ? SqlValue.Real(real)
            : SqlValue.Integer(0);
    }

    private static bool ContainsPrintfRealMarker(string value)
        => value.IndexOf('.') >= 0 || value.IndexOf('e') >= 0 || value.IndexOf('E') >= 0;

    private static SqlValue ApplyConcatenation(SqlValue left, SqlValue right)
    {
        return SqlValue.Text(ToSqlText(left) + ToSqlText(right));
    }

    internal static string ToSqlText(SqlValue value)
    {
        return value.Kind switch
        {
            SqlValueKind.Integer => value.AsInteger().ToString(CultureInfo.InvariantCulture),
            SqlValueKind.Real => FormatRealAsText(value.AsReal()),
            SqlValueKind.Text => value.AsText(),
            SqlValueKind.Blob => System.Text.Encoding.UTF8.GetString(value.AsBlob().Span),
            _ => throw new EmbeddedSqlException($"Cannot convert {value.Kind} to text."),
        };
    }

    /// <summary>Renders a REAL the way SQLite converts a floating point value to text.</summary>
    /// <remarks>
    /// SQLite never renders a floating point value as a bare integer, so <c>CAST(0.0 AS TEXT)</c>
    /// is "0.0" and not "0", and 1e20 is "1.0e+20" rather than the platform's "1E+20".
    /// </remarks>
    internal static string FormatRealAsText(double value) => SqliteRealText.Format(value);

    private static string? GetCollation(Expression expression) =>
        GetExplicitCollation(expression);

    private static string? GetEffectiveCollation(Expression expression, QueryContext context) =>
        GetExplicitCollation(expression) ?? GetInheritedDeclaredCollation(expression, context);

    private static string? GetComparisonCollation(
        Expression left,
        Expression right,
        QueryContext context) =>
        GetExplicitCollation(left)
            ?? GetExplicitCollation(right)
            ?? GetInheritedDeclaredCollation(left, context)
            ?? GetInheritedDeclaredCollation(right, context);

    private static string? GetExplicitCollation(Expression? expression)
    {
        return expression switch
        {
            null => null,
            CollationExpression collation => collation.Name,
            FunctionExpression function => function.Arguments
                    .Select(GetExplicitCollation)
                    .FirstOrDefault(collation => collation is not null),
            UnaryExpression unary => GetExplicitCollation(unary.Operand),
            BinaryExpression binary => GetExplicitCollation(binary.Left)
                ?? GetExplicitCollation(binary.Right),
            CastExpression cast => GetExplicitCollation(cast.Expression),
            CaseExpression @case => GetExplicitCollation(@case.Operand)
                ?? @case.Clauses
                    .SelectMany(clause => new[]
                    {
                        GetExplicitCollation(clause.When),
                        GetExplicitCollation(clause.Then),
                    })
                    .FirstOrDefault(collation => collation is not null)
                ?? GetExplicitCollation(@case.Else),
            LikeExpression like => GetExplicitCollation(like.Value)
                ?? GetExplicitCollation(like.Pattern)
                ?? GetExplicitCollation(like.Escape),
            GlobExpression glob => GetExplicitCollation(glob.Value)
                ?? GetExplicitCollation(glob.Pattern),
            InExpression @in => GetExplicitCollation(@in.Value)
                ?? @in.Values
                    .Select(GetExplicitCollation)
                    .FirstOrDefault(collation => collation is not null),
            InSubqueryExpression @in => GetExplicitCollation(@in.Value),
            BetweenExpression between => GetExplicitCollation(between.Value)
                ?? GetExplicitCollation(between.Lower)
                ?? GetExplicitCollation(between.Upper),
            _ => null,
        };
    }

    private static string? GetInheritedDeclaredCollation(
        Expression expression,
        QueryContext context)
    {
        var column = expression switch
        {
            ColumnExpression direct => direct,
            CastExpression cast => cast.Expression as ColumnExpression,
            _ => null,
        };
        if (column is null)
            return expression is CastExpression cast
                ? GetInheritedDeclaredCollation(cast.Expression, context)
                : null;

        if (context.CollationScope is not null
            && context.CollationScope.TryGetValue(column.Name, out var collation))
        {
            return collation;
        }

        if (context.OuterCollationScopes is not null)
        {
            foreach (var scope in context.OuterCollationScopes)
            {
                if (scope.TryGetValue(column.Name, out collation))
                    return collation;
            }
        }

        return null;
    }

    private static QueryContext EnterCollationSource(QueryContext context, TableSource? source)
    {
        if (ReferenceEquals(context.CollationSource, source))
            return context;

        IReadOnlyList<IReadOnlyDictionary<string, string?>>? outerScopes =
            context.OuterCollationScopes;
        if (context.CollationScope is not null)
        {
            var scopes = new List<IReadOnlyDictionary<string, string?>>(
                1 + (outerScopes?.Count ?? 0))
            {
                context.CollationScope,
            };
            if (outerScopes is not null)
                scopes.AddRange(outerScopes);
            outerScopes = scopes;
        }

        return context with
        {
            CollationSource = source,
            CollationScope = source is null ? null : BuildCollationScope(source, context),
            OuterCollationScopes = outerScopes,
        };
    }

    private static QueryContext RefreshCollationSource(
        QueryContext context,
        TableSource? source)
    {
        context.StatementState?.ClearCollationMemos();
        return context with
        {
            CollationSource = source,
            CollationScope = source is null ? null : BuildCollationScope(source, context),
        };
    }

    private static IReadOnlyDictionary<string, string?> BuildCollationScope(
        TableSource source,
        QueryContext context)
    {
        var memo = context.StatementState?.CollationScopes;
        var key = new CollationMemoKey(source, context.CommonTableExpressions, context.CommonTableExpressions.Count);
        if (memo is not null && memo.TryGetValue(key, out var cached))
            return cached;

        var scope = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);
        if (source is NamedTableSource named
            && !IsSchemaTable(named.Name)
            && !context.Tables.ContainsKey(named.Name)
            && !context.CommonTableExpressions.ContainsKey(named.Name)
            && !TryGetView(context, named.Name, out _))
        {
            if (memo is not null)
                memo[key] = scope;
            return scope;
        }

        foreach (var column in GetRawOutputColumns(source, context))
        {
            var collation = NormalizeDeclaredCollation(
                GetDeclaredOutputColumnCollation(source, column, context));
            scope.TryAdd(column.Name, collation);
            if (column.Qualifier is not null)
                scope[$"{column.Qualifier}.{column.Name}"] = collation;
        }

        if (memo is not null)
            memo[key] = scope;
        return scope;
    }

    private static void ApplyComparisonAffinities(
        Expression leftExpression,
        Expression? rightExpression,
        SourceRow? row,
        ref SqlValue left,
        ref SqlValue right)
    {
        var leftAffinity = GetComparisonAffinity(leftExpression, row);
        var rightAffinity = rightExpression is null
            ? null
            : GetComparisonAffinity(rightExpression, row);
        if (IsNumericAffinity(leftAffinity) && !IsNumericAffinity(rightAffinity))
        {
            right = ApplyComparisonNumericAffinity(right);
            return;
        }
        if (IsNumericAffinity(rightAffinity) && !IsNumericAffinity(leftAffinity))
        {
            left = ApplyComparisonNumericAffinity(left);
            return;
        }
        if (leftAffinity == ColumnAffinity.Text && rightAffinity is null)
        {
            right = ApplyComparisonTextAffinity(right);
            return;
        }
        if (rightAffinity == ColumnAffinity.Text && leftAffinity is null)
            left = ApplyComparisonTextAffinity(left);
    }

    private static ColumnAffinity? GetComparisonAffinity(Expression expression, SourceRow? row)
    {
        return expression switch
        {
            CollationExpression collation => GetComparisonAffinity(collation.Expression, row),
            ColumnExpression column => row?.GetColumnDefinition(column) is { } definition
                ? definition.StrictAny
                    ? null
                    : EmbeddedTable.GetAffinity(definition.DeclaredType)
                : null,
            CastExpression cast => EmbeddedTable.GetAffinity(cast.TypeName),
            _ => null,
        };
    }

    private static bool IsNumericAffinity(ColumnAffinity? affinity)
        => affinity is ColumnAffinity.Integer or ColumnAffinity.Numeric or ColumnAffinity.Real;

    private static SqlValue ApplyComparisonNumericAffinity(SqlValue value)
    {
        if (value.Kind != SqlValueKind.Text)
            return value;

        var text = value.AsText().Trim();
        if (long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var integer))
            return SqlValue.Integer(integer);
        if (double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var real)
            && double.IsFinite(real))
        {
            return SqlValue.Real(real);
        }

        return value;
    }

    private static SqlValue ApplyComparisonTextAffinity(SqlValue value)
        => value.Kind is SqlValueKind.Integer or SqlValueKind.Real
            ? SqlValue.Text(ToSqlText(value))
            : value;

    private static string? GetComparisonCollation(
        Expression leftExpression,
        Expression? rightExpression,
        SourceRow? row)
    {
        return GetCollation(leftExpression)
            ?? (rightExpression is null ? null : GetCollation(rightExpression))
            ?? GetDeclaredCollation(leftExpression, row)
            ?? (rightExpression is null ? null : GetDeclaredCollation(rightExpression, row));
    }

    private static string? GetDeclaredCollation(Expression expression, SourceRow? row)
    {
        while (expression is CollationExpression collation)
            expression = collation.Expression;
        if (expression is CastExpression cast)
            return GetDeclaredCollation(cast.Expression, row);
        return expression is ColumnExpression column
            && row?.GetColumnDefinition(column) is { } definition
                ? NormalizeDeclaredCollation(definition.Collation)
                : null;
    }

    private void ValidateOrderByCollations(IReadOnlyList<OrderByTerm> orderBy)
    {
        foreach (var term in orderBy)
            ValidateCollation(GetCollation(term.Expression));
    }

    private void ValidateGroupByCollations(IReadOnlyList<Expression> groupBy)
    {
        foreach (var expression in groupBy)
            ValidateCollation(GetCollation(expression));
    }

    private void ValidateCollation(string? collation)
    {
        if (collation is null
            || collation.Equals("BINARY", StringComparison.OrdinalIgnoreCase)
            || collation.Equals("NOCASE", StringComparison.OrdinalIgnoreCase)
            || collation.Equals("RTRIM", StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        if (!_collations.ContainsKey(collation))
            throw new EmbeddedSqlException($"no such collation sequence: {collation}");
    }

    private bool TryGetAggregateFunction(string name, int arity, out ManagedAggregateFunction function)
    {
        var normalizedName = name.ToUpperInvariant();
        return _aggregateFunctions.TryGetValue((normalizedName, arity), out function!)
            || _aggregateFunctions.TryGetValue((normalizedName, -1), out function!);
    }

    private int Compare(SqlValue left, SqlValue right, string? collation = null)
    {
        if (left.Kind == SqlValueKind.Integer && right.Kind == SqlValueKind.Integer)
            return left.AsInteger().CompareTo(right.AsInteger());
        if (left.Kind == SqlValueKind.Integer && right.Kind == SqlValueKind.Real)
            return CompareIntegerAndReal(left.AsInteger(), right.AsReal());
        if (left.Kind == SqlValueKind.Real && right.Kind == SqlValueKind.Integer)
            return -CompareIntegerAndReal(right.AsInteger(), left.AsReal());
        if (left.Kind == SqlValueKind.Real && right.Kind == SqlValueKind.Real)
            return left.AsReal().CompareTo(right.AsReal());
        if (left.Kind == SqlValueKind.Text && right.Kind == SqlValueKind.Text)
        {
            if (_collations.TryGetValue(collation ?? "BINARY", out var compare))
            {
                return InvokeManagedCallback(
                    () => compare(left.AsText(), right.AsText()));
            }
            if (collation is null || string.Equals(collation, "BINARY", StringComparison.OrdinalIgnoreCase))
                return string.CompareOrdinal(left.AsText(), right.AsText());
            if (string.Equals(collation, "NOCASE", StringComparison.OrdinalIgnoreCase))
                return SqliteIndexRecordComparer.CompareNoCaseText(left.AsText(), right.AsText());
            if (string.Equals(collation, "RTRIM", StringComparison.OrdinalIgnoreCase))
                return SqliteIndexRecordComparer.CompareRTrimText(left.AsText(), right.AsText());

            throw new EmbeddedSqlException($"no such collation sequence: {collation}");
        }
        if (left.Kind == SqlValueKind.Blob && right.Kind == SqlValueKind.Blob)
            return left.AsBlob().Span.SequenceCompareTo(right.AsBlob().Span);

        return left.Kind.CompareTo(right.Kind);
    }

    private static int CompareIntegerAndReal(long integer, double real)
    {
        if (real < long.MinValue)
            return 1;
        if (real >= -(double)long.MinValue)
            return -1;

        var truncated = (long)real;
        var comparison = integer.CompareTo(truncated);
        if (comparison != 0)
            return comparison;

        return real == truncated
            ? 0
            : real > truncated
                ? -1
                : 1;
    }

    // ----- Aggregate window functions (func(...) OVER (...)) -----

    private SelectStatement ResolveNamedWindows(SelectStatement statement)
    {
        if (statement.NamedWindows.Count == 0
            && !SelectExpressions(statement).Any(ContainsNamedWindowReference))
        {
            return statement;
        }

        var resolved = new Dictionary<string, WindowSpecification>(StringComparer.OrdinalIgnoreCase);

        WindowSpecification ResolveSpecification(
            WindowSpecification specification,
            bool ignoreUnknownBase = false)
        {
            if (specification.BaseWindowName is null)
            {
                return RewriteWindowExpressions(specification with { IsNamedReference = false });
            }

            if (!resolved.TryGetValue(specification.BaseWindowName, out var baseSpecification))
            {
                if (!ignoreUnknownBase || specification.IsNamedReference)
                    throw new EmbeddedSqlException($"no such window: {specification.BaseWindowName}");

                return RewriteWindowExpressions(specification with
                {
                    BaseWindowName = null,
                    IsNamedReference = false,
                });
            }

            if (specification.IsNamedReference)
                return baseSpecification;

            if (specification.PartitionBy.Count != 0)
            {
                throw new EmbeddedSqlException(
                    $"cannot override PARTITION clause of window: {specification.BaseWindowName}");
            }
            if (baseSpecification.OrderBy.Count != 0 && specification.OrderBy.Count != 0)
            {
                throw new EmbeddedSqlException(
                    $"cannot override ORDER BY clause of window: {specification.BaseWindowName}");
            }
            if (baseSpecification.Frame is not null)
            {
                throw new EmbeddedSqlException(
                    $"cannot override frame specification of window: {specification.BaseWindowName}");
            }

            return RewriteWindowExpressions(new WindowSpecification(
                null,
                baseSpecification.PartitionBy,
                specification.OrderBy.Count == 0 ? baseSpecification.OrderBy : specification.OrderBy,
                specification.Frame));
        }

        WindowSpecification RewriteWindowExpressions(WindowSpecification specification)
        {
            return specification with
            {
                BaseWindowName = null,
                IsNamedReference = false,
                PartitionBy = specification.PartitionBy.Select(ResolveExpression).ToArray(),
                OrderBy = specification.OrderBy.Select(term => term with
                {
                    Expression = ResolveExpression(term.Expression),
                }).ToArray(),
                Frame = specification.Frame is null
                    ? null
                    : specification.Frame with
                    {
                        Start = specification.Frame.Start with
                        {
                            Offset = specification.Frame.Start.Offset is null
                                ? null
                                : ResolveExpression(specification.Frame.Start.Offset),
                        },
                        End = specification.Frame.End with
                        {
                            Offset = specification.Frame.End.Offset is null
                                ? null
                                : ResolveExpression(specification.Frame.End.Offset),
                        },
                    },
            };
        }

        Expression ResolveExpression(Expression expression)
        {
            return expression switch
            {
                FunctionExpression function => function with
                {
                    Arguments = function.Arguments.Select(ResolveExpression).ToArray(),
                    Filter = function.Filter is null ? null : ResolveExpression(function.Filter),
                    Window = function.Window is null ? null : ResolveSpecification(function.Window),
                },
                UnaryExpression unary => unary with { Operand = ResolveExpression(unary.Operand) },
                BinaryExpression binary => binary with
                {
                    Left = ResolveExpression(binary.Left),
                    Right = ResolveExpression(binary.Right),
                },
                CollationExpression collation => collation with
                {
                    Expression = ResolveExpression(collation.Expression),
                },
                CastExpression cast => cast with { Expression = ResolveExpression(cast.Expression) },
                CaseExpression @case => @case with
                {
                    Operand = @case.Operand is null ? null : ResolveExpression(@case.Operand),
                    Clauses = @case.Clauses.Select(clause => clause with
                    {
                        When = ResolveExpression(clause.When),
                        Then = ResolveExpression(clause.Then),
                    }).ToArray(),
                    Else = @case.Else is null ? null : ResolveExpression(@case.Else),
                },
                LikeExpression like => like with
                {
                    Value = ResolveExpression(like.Value),
                    Pattern = ResolveExpression(like.Pattern),
                    Escape = like.Escape is null ? null : ResolveExpression(like.Escape),
                },
                GlobExpression glob => glob with
                {
                    Value = ResolveExpression(glob.Value),
                    Pattern = ResolveExpression(glob.Pattern),
                },
                InExpression @in => @in with
                {
                    Value = ResolveExpression(@in.Value),
                    Values = @in.Values.Select(ResolveExpression).ToArray(),
                },
                InSubqueryExpression inSubquery => inSubquery with
                {
                    Value = ResolveExpression(inSubquery.Value),
                },
                BetweenExpression between => between with
                {
                    Value = ResolveExpression(between.Value),
                    Lower = ResolveExpression(between.Lower),
                    Upper = ResolveExpression(between.Upper),
                },
                _ => expression,
            };
        }

        // SQLite resolves bases against definitions already seen and lets the last duplicate
        // name win. A forward base is therefore an empty base, while OVER name is resolved
        // after the complete WINDOW clause.
        foreach (var definition in statement.NamedWindows)
            resolved[definition.Name] = ResolveSpecification(definition.Specification, ignoreUnknownBase: true);

        return statement with
        {
            Projections = statement.Projections.Select(projection => projection with
            {
                Expression = ResolveExpression(projection.Expression),
            }).ToArray(),
            Where = statement.Where is null ? null : ResolveExpression(statement.Where),
            GroupBy = statement.GroupBy.Select(ResolveExpression).ToArray(),
            Having = statement.Having is null ? null : ResolveExpression(statement.Having),
            NamedWindows = [],
            OrderBy = statement.OrderBy.Select(term => term with
            {
                Expression = ResolveExpression(term.Expression),
            }).ToArray(),
            Limit = statement.Limit is null ? null : ResolveExpression(statement.Limit),
            Offset = statement.Offset is null ? null : ResolveExpression(statement.Offset),
        };
    }

    private static IEnumerable<Expression> SelectExpressions(SelectStatement statement)
    {
        foreach (var projection in statement.Projections)
            yield return projection.Expression;
        if (statement.Where is not null)
            yield return statement.Where;
        foreach (var expression in statement.GroupBy)
            yield return expression;
        if (statement.Having is not null)
            yield return statement.Having;
        foreach (var term in statement.OrderBy)
            yield return term.Expression;
        if (statement.Limit is not null)
            yield return statement.Limit;
        if (statement.Offset is not null)
            yield return statement.Offset;
    }

    private static bool ContainsNamedWindowReference(Expression expression)
    {
        return expression switch
        {
            FunctionExpression function => function.Window?.BaseWindowName is not null
                || function.Arguments.Any(ContainsNamedWindowReference)
                || (function.Filter is not null && ContainsNamedWindowReference(function.Filter)),
            UnaryExpression unary => ContainsNamedWindowReference(unary.Operand),
            BinaryExpression binary => ContainsNamedWindowReference(binary.Left)
                || ContainsNamedWindowReference(binary.Right),
            CollationExpression collation => ContainsNamedWindowReference(collation.Expression),
            CastExpression cast => ContainsNamedWindowReference(cast.Expression),
            CaseExpression @case => (@case.Operand is not null && ContainsNamedWindowReference(@case.Operand))
                || @case.Clauses.Any(clause => ContainsNamedWindowReference(clause.When)
                    || ContainsNamedWindowReference(clause.Then))
                || (@case.Else is not null && ContainsNamedWindowReference(@case.Else)),
            LikeExpression like => ContainsNamedWindowReference(like.Value)
                || ContainsNamedWindowReference(like.Pattern)
                || (like.Escape is not null && ContainsNamedWindowReference(like.Escape)),
            GlobExpression glob => ContainsNamedWindowReference(glob.Value)
                || ContainsNamedWindowReference(glob.Pattern),
            InExpression @in => ContainsNamedWindowReference(@in.Value)
                || @in.Values.Any(ContainsNamedWindowReference),
            InSubqueryExpression inSubquery => ContainsNamedWindowReference(inSubquery.Value),
            BetweenExpression between => ContainsNamedWindowReference(between.Value)
                || ContainsNamedWindowReference(between.Lower)
                || ContainsNamedWindowReference(between.Upper),
            _ => false,
        };
    }

    private List<FunctionExpression> CollectSelectWindowFunctions(SelectStatement statement)
    {
        var result = new List<FunctionExpression>();
        foreach (var projection in statement.Projections)
            CollectWindowFunctions(projection.Expression, result);

        var orderBy = ResolveOrderBy(statement.OrderBy, statement.Projections);
        foreach (var term in orderBy)
            CollectWindowFunctions(term.Expression, result);

        return result;
    }

    private void CollectWindowFunctions(Expression expression, List<FunctionExpression> result)
    {
        switch (expression)
        {
            case FunctionExpression function when function.Window is not null:
                if (!result.Contains(function))
                    result.Add(function);
                return;
            case FunctionExpression function:
                foreach (var argument in function.Arguments)
                    CollectWindowFunctions(argument, result);
                if (function.Filter is not null)
                    CollectWindowFunctions(function.Filter, result);
                return;
            case RowValueExpression rowValue:
                foreach (var value in rowValue.Values)
                    CollectWindowFunctions(value, result);
                return;
            case BinaryExpression binary:
                CollectWindowFunctions(binary.Left, result);
                CollectWindowFunctions(binary.Right, result);
                return;
            case UnaryExpression unary:
                CollectWindowFunctions(unary.Operand, result);
                return;
            case CollationExpression collation:
                CollectWindowFunctions(collation.Expression, result);
                return;
            case CastExpression cast:
                CollectWindowFunctions(cast.Expression, result);
                return;
            case CaseExpression @case:
                if (@case.Operand is not null)
                    CollectWindowFunctions(@case.Operand, result);
                foreach (var clause in @case.Clauses)
                {
                    CollectWindowFunctions(clause.When, result);
                    CollectWindowFunctions(clause.Then, result);
                }

                if (@case.Else is not null)
                    CollectWindowFunctions(@case.Else, result);
                return;
            case LikeExpression like:
                CollectWindowFunctions(like.Value, result);
                CollectWindowFunctions(like.Pattern, result);
                if (like.Escape is not null)
                    CollectWindowFunctions(like.Escape, result);
                return;
            case GlobExpression glob:
                CollectWindowFunctions(glob.Value, result);
                CollectWindowFunctions(glob.Pattern, result);
                return;
            case InExpression @in:
                CollectWindowFunctions(@in.Value, result);
                foreach (var value in @in.Values)
                    CollectWindowFunctions(value, result);
                return;
            case InSubqueryExpression inSubquery:
                CollectWindowFunctions(inSubquery.Value, result);
                return;
            case BetweenExpression between:
                CollectWindowFunctions(between.Value, result);
                CollectWindowFunctions(between.Lower, result);
                CollectWindowFunctions(between.Upper, result);
                return;
            default:
                return;
        }
    }

    private bool ContainsWindowFunction(Expression expression)
    {
        return expression switch
        {
            FunctionExpression function when function.Window is not null => true,
            FunctionExpression function => function.Arguments.Any(ContainsWindowFunction)
                || (function.Filter is not null && ContainsWindowFunction(function.Filter)),
            RowValueExpression rowValue => rowValue.Values.Any(ContainsWindowFunction),
            BinaryExpression binary => ContainsWindowFunction(binary.Left) || ContainsWindowFunction(binary.Right),
            UnaryExpression unary => ContainsWindowFunction(unary.Operand),
            CollationExpression collation => ContainsWindowFunction(collation.Expression),
            CastExpression cast => ContainsWindowFunction(cast.Expression),
            CaseExpression @case => (@case.Operand is not null && ContainsWindowFunction(@case.Operand))
                || @case.Clauses.Any(clause => ContainsWindowFunction(clause.When) || ContainsWindowFunction(clause.Then))
                || (@case.Else is not null && ContainsWindowFunction(@case.Else)),
            LikeExpression like => ContainsWindowFunction(like.Value)
                || ContainsWindowFunction(like.Pattern)
                || (like.Escape is not null && ContainsWindowFunction(like.Escape)),
            GlobExpression glob => ContainsWindowFunction(glob.Value) || ContainsWindowFunction(glob.Pattern),
            InExpression @in => ContainsWindowFunction(@in.Value) || @in.Values.Any(ContainsWindowFunction),
            InSubqueryExpression inSubquery => ContainsWindowFunction(inSubquery.Value),
            BetweenExpression between => ContainsWindowFunction(between.Value)
                || ContainsWindowFunction(between.Lower)
                || ContainsWindowFunction(between.Upper),
            _ => false,
        };
    }

    // Rewrites each windowed function call to a literal holding its already-computed value
    // for a specific row. Subquery bodies are left untouched: only their outer value
    // expression is rewritten, mirroring CollectWindowFunctions exactly.
    private Expression ReplaceWindowFunctions(
        Expression expression,
        IReadOnlyDictionary<FunctionExpression, SqlValue> substitution)
    {
        switch (expression)
        {
            case FunctionExpression function when function.Window is not null:
                return substitution.TryGetValue(function, out var value)
                    ? new LiteralExpression(value)
                    : expression;
            case FunctionExpression function:
                return function with
                {
                    Arguments = function.Arguments
                        .Select(argument => ReplaceWindowFunctions(argument, substitution))
                        .ToArray(),
                    Filter = function.Filter is null
                        ? null
                        : ReplaceWindowFunctions(function.Filter, substitution),
                };
            case RowValueExpression rowValue:
                return rowValue with
                {
                    Values = rowValue.Values
                        .Select(value => ReplaceWindowFunctions(value, substitution))
                        .ToArray(),
                };
            case BinaryExpression binary:
                return binary with
                {
                    Left = ReplaceWindowFunctions(binary.Left, substitution),
                    Right = ReplaceWindowFunctions(binary.Right, substitution),
                };
            case UnaryExpression unary:
                return unary with { Operand = ReplaceWindowFunctions(unary.Operand, substitution) };
            case CollationExpression collation:
                return collation with { Expression = ReplaceWindowFunctions(collation.Expression, substitution) };
            case CastExpression cast:
                return cast with { Expression = ReplaceWindowFunctions(cast.Expression, substitution) };
            case CaseExpression @case:
                return @case with
                {
                    Operand = @case.Operand is null ? null : ReplaceWindowFunctions(@case.Operand, substitution),
                    Clauses = @case.Clauses
                        .Select(clause => new CaseClause(
                            ReplaceWindowFunctions(clause.When, substitution),
                            ReplaceWindowFunctions(clause.Then, substitution)))
                        .ToArray(),
                    Else = @case.Else is null ? null : ReplaceWindowFunctions(@case.Else, substitution),
                };
            case LikeExpression like:
                return like with
                {
                    Value = ReplaceWindowFunctions(like.Value, substitution),
                    Pattern = ReplaceWindowFunctions(like.Pattern, substitution),
                    Escape = like.Escape is null ? null : ReplaceWindowFunctions(like.Escape, substitution),
                };
            case GlobExpression glob:
                return glob with
                {
                    Value = ReplaceWindowFunctions(glob.Value, substitution),
                    Pattern = ReplaceWindowFunctions(glob.Pattern, substitution),
                };
            case InExpression @in:
                return @in with
                {
                    Value = ReplaceWindowFunctions(@in.Value, substitution),
                    Values = @in.Values.Select(value => ReplaceWindowFunctions(value, substitution)).ToArray(),
                };
            case InSubqueryExpression inSubquery:
                return inSubquery with { Value = ReplaceWindowFunctions(inSubquery.Value, substitution) };
            case BetweenExpression between:
                return between with
                {
                    Value = ReplaceWindowFunctions(between.Value, substitution),
                    Lower = ReplaceWindowFunctions(between.Lower, substitution),
                    Upper = ReplaceWindowFunctions(between.Upper, substitution),
                };
            default:
                return expression;
        }
    }

    private void ValidateWindowFunction(FunctionExpression function)
    {
        if (function.Distinct)
            throw new EmbeddedSqlException("DISTINCT is not supported for window functions");

        var name = function.Name.ToUpperInvariant();
        var isBuiltInWindow = name is "ROW_NUMBER"
            or "RANK"
            or "DENSE_RANK"
            or "PERCENT_RANK"
            or "CUME_DIST"
            or "NTILE"
            or "LAG"
            or "LEAD"
            or "FIRST_VALUE"
            or "LAST_VALUE"
            or "NTH_VALUE";
        var isAggregate = IsAggregateWindowFunction(function);
        if (!isBuiltInWindow && !isAggregate)
        {
            throw new EmbeddedSqlException(
                $"{function.Name} is not a supported window function");
        }

        if (function.Filter is not null && !isAggregate)
            throw new EmbeddedSqlException("FILTER clause may only be used with aggregate window functions");

        if (function.AggregateOrderBy is { Count: > 0 })
        {
            throw new EmbeddedSqlException(
                "ORDER BY within window functions is not supported by the managed engine.");
        }

        switch (name)
        {
            case "ROW_NUMBER":
            case "RANK":
            case "DENSE_RANK":
            case "PERCENT_RANK":
            case "CUME_DIST":
                RequireWindowArgumentCount(function, 0);
                break;
            case "NTILE":
            case "FIRST_VALUE":
            case "LAST_VALUE":
                RequireWindowArgumentCount(function, 1);
                break;
            case "NTH_VALUE":
                RequireWindowArgumentCount(function, 2);
                break;
            case "LAG":
            case "LEAD":
                if (function.Arguments.Count is < 1 or > 3 || function.CountStar)
                    ThrowWrongWindowArgumentCount(function);
                break;
            case "COUNT":
                if ((!function.CountStar && function.Arguments.Count > 1)
                    || (function.CountStar && function.Arguments.Count != 0))
                {
                    ThrowWrongWindowArgumentCount(function);
                }
                break;
            case "SUM":
            case "TOTAL":
            case "AVG":
            case "MIN":
            case "MAX":
                RequireWindowArgumentCount(function, 1);
                break;
            case "GROUP_CONCAT":
                if (function.Arguments.Count is < 1 or > 2 || function.CountStar)
                    ThrowWrongWindowArgumentCount(function);
                break;
            case "STRING_AGG":
            case "JSON_GROUP_OBJECT":
                RequireWindowArgumentCount(function, 2);
                break;
            case "JSON_GROUP_ARRAY":
                RequireWindowArgumentCount(function, 1);
                break;
        }

        // Aggregates are legal everywhere inside a window call's own subtree: SQLite aggregates
        // first and runs the window pass over the grouped rows, so sum(count(*)) OVER (ORDER BY
        // count(*)) reads an already-aggregated value. A *window* call nested in that subtree has
        // no such later pass to be evaluated in and stays a misuse, named after the inner call.
        var nestedInInputs = function.Arguments
                .Select(FindWindowFunction)
                .FirstOrDefault(candidate => candidate is not null)
            ?? FindWindowFunction(function.Filter);
        if (nestedInInputs is not null)
            throw new EmbeddedSqlException($"misuse of window function {nestedInInputs.Name}()");

        var window = function.Window!;
        ValidateWindowFrameStructure(window);
        var nestedInSpec = window.PartitionBy
                .Select(FindWindowFunction)
                .FirstOrDefault(candidate => candidate is not null)
            ?? window.OrderBy
                .Select(term => FindWindowFunction(term.Expression))
                .FirstOrDefault(candidate => candidate is not null);
        if (nestedInSpec is not null)
            throw new EmbeddedSqlException($"misuse of window function {nestedInSpec.Name}()");

        // Frame offsets have no aggregate pass of their own - they are evaluated once per
        // statement - so anything non-constant stays rejected here.
        if (window.Frame?.Start.Offset is { } startOffset
                && (ContainsWindowFunction(startOffset) || ContainsAggregate(startOffset))
            || window.Frame?.End.Offset is { } endOffset
                && (ContainsWindowFunction(endOffset) || ContainsAggregate(endOffset)))
        {
            throw new EmbeddedSqlException("misuse of window function");
        }
    }

    // Returns the outermost window call inside <paramref name="expression"/>, or null when the
    // expression carries none. Used to name the offending call in a misuse diagnostic exactly the
    // way SQLite does.
    private FunctionExpression? FindWindowFunction(Expression? expression)
    {
        if (expression is null)
            return null;

        var found = new List<FunctionExpression>();
        CollectWindowFunctions(expression, found);
        return found.Count == 0 ? null : found[0];
    }

    // True when the expression contains an aggregate call anywhere, including inside a window
    // call's arguments, FILTER, PARTITION BY or ORDER BY. Those aggregates are evaluated in the
    // statement's aggregate pass, so their presence makes the statement an aggregate query even
    // when no aggregate appears outside a window call.
    private bool ContainsAggregateAcrossWindows(Expression expression)
    {
        if (ContainsAggregate(expression))
            return true;

        var windowFunctions = new List<FunctionExpression>();
        CollectWindowFunctions(expression, windowFunctions);
        return windowFunctions.Any(WindowFunctionContainsAggregate);
    }

    private bool WindowFunctionContainsAggregate(FunctionExpression function)
    {
        var window = function.Window!;
        return function.Arguments.Any(ContainsAggregate)
            || function.Filter is not null && ContainsAggregate(function.Filter)
            || window.PartitionBy.Any(ContainsAggregate)
            || window.OrderBy.Any(term => ContainsAggregate(term.Expression));
    }

    // Returns the window call that a non-window aggregate takes as input, if any. SQLite has no
    // pass in which such a call could be evaluated - the window pass runs after aggregation - so
    // it is a misuse named after the window call.
    private FunctionExpression? FindWindowFunctionInsideAggregate(Expression? expression)
    {
        switch (expression)
        {
            case null:
                return null;
            case FunctionExpression { Window: not null }:
                return null;
            case FunctionExpression function when IsBuiltInAggregate(function)
                || IsManagedPercentileAggregate(function.Name)
                || TryGetAggregateFunction(function.Name, function.Arguments.Count, out _):
                return function.Arguments
                        .Select(FindWindowFunction)
                        .FirstOrDefault(candidate => candidate is not null)
                    ?? FindWindowFunction(function.Filter)
                    ?? function.Arguments
                        .Select(FindWindowFunctionInsideAggregate)
                        .FirstOrDefault(candidate => candidate is not null);
            case FunctionExpression function:
                return function.Arguments
                        .Select(FindWindowFunctionInsideAggregate)
                        .FirstOrDefault(candidate => candidate is not null)
                    ?? FindWindowFunctionInsideAggregate(function.Filter);
            case RowValueExpression rowValue:
                return rowValue.Values
                    .Select(FindWindowFunctionInsideAggregate)
                    .FirstOrDefault(candidate => candidate is not null);
            case UnaryExpression unary:
                return FindWindowFunctionInsideAggregate(unary.Operand);
            case BinaryExpression binary:
                return FindWindowFunctionInsideAggregate(binary.Left)
                    ?? FindWindowFunctionInsideAggregate(binary.Right);
            case CollationExpression collation:
                return FindWindowFunctionInsideAggregate(collation.Expression);
            case CastExpression cast:
                return FindWindowFunctionInsideAggregate(cast.Expression);
            case CaseExpression @case:
                return FindWindowFunctionInsideAggregate(@case.Operand)
                    ?? @case.Clauses
                        .Select(clause => FindWindowFunctionInsideAggregate(clause.When)
                            ?? FindWindowFunctionInsideAggregate(clause.Then))
                        .FirstOrDefault(candidate => candidate is not null)
                    ?? FindWindowFunctionInsideAggregate(@case.Else);
            case LikeExpression like:
                return FindWindowFunctionInsideAggregate(like.Value)
                    ?? FindWindowFunctionInsideAggregate(like.Pattern)
                    ?? FindWindowFunctionInsideAggregate(like.Escape);
            case GlobExpression glob:
                return FindWindowFunctionInsideAggregate(glob.Value)
                    ?? FindWindowFunctionInsideAggregate(glob.Pattern);
            case InExpression @in:
                return FindWindowFunctionInsideAggregate(@in.Value)
                    ?? @in.Values
                        .Select(FindWindowFunctionInsideAggregate)
                        .FirstOrDefault(candidate => candidate is not null);
            case InSubqueryExpression inSubquery:
                return FindWindowFunctionInsideAggregate(inSubquery.Value);
            case BetweenExpression between:
                return FindWindowFunctionInsideAggregate(between.Value)
                    ?? FindWindowFunctionInsideAggregate(between.Lower)
                    ?? FindWindowFunctionInsideAggregate(between.Upper);
            default:
                return null;
        }
    }

    private bool IsAggregateWindowFunction(FunctionExpression function)
    {
        var name = function.Name.ToUpperInvariant();
        return name is "COUNT" or "SUM" or "TOTAL" or "AVG" or "MIN" or "MAX" or "GROUP_CONCAT"
            or "STRING_AGG" or "JSON_GROUP_ARRAY" or "JSON_GROUP_OBJECT"
            || TryGetAggregateFunction(function.Name, function.Arguments.Count, out _);
    }

    private static void RequireWindowArgumentCount(FunctionExpression function, int expected)
    {
        if (function.CountStar || function.Arguments.Count != expected)
            ThrowWrongWindowArgumentCount(function);
    }

    private static void ThrowWrongWindowArgumentCount(FunctionExpression function)
        => throw new EmbeddedSqlException(
            $"wrong number of arguments to function {function.Name.ToLowerInvariant()}()");

    private static void ValidateWindowFrameStructure(WindowSpecification specification)
    {
        if (specification.Frame is not { Mode: Ahtola.Core.Parsing.WindowFrameMode.Range } frame)
            return;

        var hasOffset = frame.Start.Kind is FrameBoundKind.Preceding or FrameBoundKind.Following
            || frame.End.Kind is FrameBoundKind.Preceding or FrameBoundKind.Following;
        if (hasOffset && specification.OrderBy.Count != 1)
        {
            throw new EmbeddedSqlException(
                "RANGE with offset PRECEDING/FOLLOWING requires one ORDER BY expression");
        }
    }

    // Runs the window pass over the aggregate pass's output. SQLite evaluates GROUP BY (and HAVING)
    // first and only then applies window functions to the surviving grouped rows, so a frame here
    // spans groups rather than base rows, a window argument may read an aggregate result
    // (sum(count(*)) OVER ...), and a group removed by HAVING is invisible to every frame.
    // Bare columns resolve against each group's representative row exactly as in the plain grouped
    // path, which is why every window input goes through EvaluateAggregate.
    private ExecutionResult ExecuteGroupedWindowSelect(
        SelectStatement statement,
        IReadOnlyList<SourceRow> selectedRows,
        IReadOnlyList<FunctionExpression> windowFunctions,
        string[] columnNames,
        IReadOnlyList<OrderByTerm> resolvedOrderBy,
        long offset,
        long? limit,
        SqlValue[] parameters,
        QueryContext context)
    {
        var grouped = new List<(SourceRow? Representative, IReadOnlyList<SourceRow> Rows)>();
        if (statement.GroupBy.Count == 0)
        {
            // An aggregate without GROUP BY collapses to exactly one row, even over no rows at all.
            var representative = GetAggregateRepresentative(statement, selectedRows, parameters, context);
            if (statement.Having is null
                || IsTrue(EvaluateAggregate(statement.Having, selectedRows, parameters, context, representative)))
            {
                grouped.Add((representative, selectedRows));
            }
        }
        else
        {
            foreach (var entry in BuildGroups(statement.GroupBy, selectedRows, parameters, context))
            {
                var representative = GetAggregateRepresentative(statement, entry.Rows, parameters, context)
                    ?? entry.Rows[0];
                if (statement.Having is null
                    || IsTrue(EvaluateAggregate(
                        statement.Having,
                        entry.Rows,
                        parameters,
                        context,
                        representative)))
                {
                    grouped.Add((representative, entry.Rows));
                }
            }
        }

        SqlValue EvaluateInGroup(int index, Expression expression) => EvaluateAggregate(
            expression,
            grouped[index].Rows,
            parameters,
            context,
            grouped[index].Representative);

        var valueRows = ComputeWindowFunctionValueRows(
            windowFunctions,
            grouped.Count,
            EvaluateInGroup,
            parameters,
            context);
        var windowValues = new Dictionary<FunctionExpression, SqlValue>[grouped.Count];
        for (var index = 0; index < grouped.Count; index++)
        {
            var substitution = new Dictionary<FunctionExpression, SqlValue>(windowFunctions.Count);
            for (var ordinal = 0; ordinal < windowFunctions.Count; ordinal++)
                substitution[windowFunctions[ordinal]] = valueRows[index][ordinal];

            windowValues[index] = substitution;
        }

        var results = new List<OrderByKeyed<SqlValue[]>>(grouped.Count);
        for (var index = 0; index < grouped.Count; index++)
        {
            context.CheckInterrupt();
            var substitution = windowValues[index];
            var values = statement.Projections
                .Select(projection => EvaluateInGroup(
                    index,
                    ReplaceWindowFunctions(projection.Expression, substitution)))
                .ToArray();
            var keys = resolvedOrderBy
                .Select(term => EvaluateInGroup(index, ReplaceWindowFunctions(term.Expression, substitution)))
                .ToArray();
            results.Add(new OrderByKeyed<SqlValue[]>(values, keys, index));
        }

        if (resolvedOrderBy.Count > 0)
        {
            var orderCollations = resolvedOrderBy
                .Select(term => GetEffectiveCollation(term.Expression, context))
                .ToArray();
            results.Sort((left, right) =>
            {
                var comparison = CompareOrderKeys(left.Keys, right.Keys, resolvedOrderBy, orderCollations);
                return comparison != 0 ? comparison : left.Position.CompareTo(right.Position);
            });
        }

        return new ExecutionResult(
            columnNames,
            ApplyDistinctLimit(
                results.Select(result => result.Item),
                statement.Distinct,
                offset,
                limit,
                statement.Projections
                    .Select(projection => GetEffectiveCollation(projection.Expression, context))
                    .ToArray()),
            0);
    }

    // Partitions the selected rows into GROUP BY groups and returns them in ascending
    // key order, matching the order SQLite's aggregation sorter emits groups in (which
    // queries observe when no ORDER BY overrides it, e.g. through LIMIT).
    private List<(SqlValue[] Key, List<SourceRow> Rows)> BuildGroups(
        IReadOnlyList<Expression> groupBy,
        IReadOnlyList<SourceRow> selectedRows,
        SqlValue[] parameters,
        QueryContext context)
    {
        var groupCollations = groupBy
            .Select(expression => GetEffectiveCollation(expression, context))
            .ToArray();
        VdbeGroupComparer groupEquality = (left, right) =>
            GroupKeysEqual(left, right, groupCollations);
        var groupHasher = BuildGroupHasher(groupCollations);
        var groupIndexByKey = groupHasher is null
            ? null
            : new Dictionary<SqlValue[], int>(
                new GroupKeyEqualityComparer(groupEquality, groupHasher));
        var groups = new List<(SqlValue[] Key, List<SourceRow> Rows)>();
        foreach (var row in selectedRows)
        {
            context.CheckInterrupt();
            var key = EvaluateGroupKey(groupBy, parameters, row, context);
            var groupIndex = groupIndexByKey is not null
                && groupIndexByKey.TryGetValue(key, out var indexedGroup)
                    ? indexedGroup
                    : groupIndexByKey is null
                        ? groups.FindIndex(group => groupEquality(group.Key, key))
                        : -1;
            if (groupIndex < 0)
            {
                groupIndex = groups.Count;
                groups.Add((key, []));
                groupIndexByKey?.Add(key, groupIndex);
            }

            groups[groupIndex].Rows.Add(row);
        }

        var ordered = groups
            .Select((group, position) => (group, position))
            .ToList();
        ordered.Sort((left, right) =>
        {
            context.CheckInterrupt();
            var comparison = CompareGroupKeysForOrdering(
                left.group.Key,
                right.group.Key,
                left.group.Key.Length,
                groupCollations);
            return comparison != 0 ? comparison : left.position.CompareTo(right.position);
        });
        return ordered.Select(entry => entry.group).ToList();
    }

    private ExecutionResult ExecuteWindowSelect(
        SelectStatement statement,
        IReadOnlyList<SourceRow> selectedRows,
        IReadOnlyList<FunctionExpression> windowFunctions,
        string[] columnNames,
        IReadOnlyList<OutputColumn> outputColumns,
        long offset,
        long? limit,
        SqlValue[] parameters,
        QueryContext context)
    {
        var rowCount = selectedRows.Count;
        var valueRows = ComputeWindowFunctionValueRows(
            windowFunctions,
            selectedRows,
            parameters,
            context);
        var windowValues = new Dictionary<FunctionExpression, SqlValue>[rowCount];
        for (var index = 0; index < rowCount; index++)
        {
            var substitution = new Dictionary<FunctionExpression, SqlValue>(windowFunctions.Count);
            for (var ordinal = 0; ordinal < windowFunctions.Count; ordinal++)
                substitution[windowFunctions[ordinal]] = valueRows[index][ordinal];

            windowValues[index] = substitution;
        }

        var orderBy = ResolveOrderBy(statement.OrderBy, statement.Projections);
        var indices = Enumerable.Range(0, rowCount).ToList();
        if (orderBy.Count > 0)
        {
            var orderCollations = orderBy
                .Select(term => GetEffectiveCollation(term.Expression, context))
                .ToArray();
            var orderKeys = new SqlValue[rowCount][];
            for (var index = 0; index < rowCount; index++)
            {
                orderKeys[index] = orderBy
                    .Select(term => Evaluate(
                        ReplaceWindowFunctions(term.Expression, windowValues[index]),
                        parameters,
                        selectedRows[index],
                        context))
                    .ToArray();
            }
            indices = StableSortIndices(indices, (left, right) =>
                CompareOrderKeys(orderKeys[left], orderKeys[right], orderBy, orderCollations));
        }

        var resultRows = new List<SqlValue[]>(rowCount);
        foreach (var index in indices)
        {
            var row = selectedRows[index];
            var substitution = windowValues[index];
            var values = new List<SqlValue>();
            foreach (var projection in statement.Projections)
            {
                switch (projection.Expression)
                {
                    case StarExpression:
                        foreach (var column in outputColumns)
                            values.Add(GetOutputValue(row, column));
                        break;
                    case QualifiedStarExpression qualifiedStar:
                        var rawMatches = GetRawOutputColumns(statement.Source, context)
                            .Where(column => string.Equals(column.Qualifier, qualifiedStar.Qualifier, StringComparison.OrdinalIgnoreCase))
                            .ToArray();
                        if (rawMatches.Length == 0)
                            throw new EmbeddedSqlException($"no such table: {qualifiedStar.Qualifier}");

                        var matches = rawMatches
                            .Select(raw => outputColumns.FirstOrDefault(column =>
                                string.Equals(column.Qualifier, qualifiedStar.Qualifier, StringComparison.OrdinalIgnoreCase)
                                && column.Index == raw.Index) ?? raw)
                            .ToArray();
                        foreach (var column in matches)
                            values.Add(GetOutputValue(row, column));
                        break;
                    default:
                        values.Add(Evaluate(
                            ReplaceWindowFunctions(projection.Expression, substitution),
                            parameters,
                            row,
                            context));
                        break;
                }
            }

            resultRows.Add(values.ToArray());
        }

        var collations = BuildProjectionCollations(statement, outputColumns, context);
        return new ExecutionResult(
            columnNames,
            ApplyDistinctLimit(resultRows, statement.Distinct, offset, limit, collations),
            0);
    }

    // Computes each collected window function's value for every selected row, aligned by function ordinal.
    // Window calls are grouped by identical OVER spec so one partition/order/frame pass serves every
    // function sharing a spec, which is how a statement carrying several different windows is evaluated.
    // Both the tree-walking ExecuteWindowSelect and the compiled buffered-window route consume this, so
    // the two paths cannot drift.
    private SqlValue[][] ComputeWindowFunctionValueRows(
        IReadOnlyList<FunctionExpression> windowFunctions,
        IReadOnlyList<SourceRow> rows,
        SqlValue[] parameters,
        QueryContext context)
    {
        return ComputeWindowFunctionValueRows(
            windowFunctions,
            rows.Count,
            (index, expression) => Evaluate(expression, parameters, rows[index], context),
            parameters,
            context);
    }

    // The window pass reads every one of its inputs - arguments, FILTER, PARTITION BY and window
    // ORDER BY - through <paramref name="evaluate"/> rather than from a SourceRow directly. A plain
    // windowed SELECT supplies the scanned row; a grouped one supplies the aggregate pass's output
    // for the group at that index, which is what makes a frame see grouped rows instead of base rows.
    private SqlValue[][] ComputeWindowFunctionValueRows(
        IReadOnlyList<FunctionExpression> windowFunctions,
        int rowCount,
        WindowInputEvaluator evaluate,
        SqlValue[] parameters,
        QueryContext context)
    {
        var values = new SqlValue[rowCount][];
        for (var index = 0; index < rowCount; index++)
            values[index] = new SqlValue[windowFunctions.Count];

        if (windowFunctions.Count == 0)
            return values;

        var inputs = PrepareWindowFunctionInputs(windowFunctions, rowCount, evaluate, context);
        var groups = new List<List<int>>();
        foreach (var ordinal in Enumerable.Range(0, windowFunctions.Count))
        {
            var group = groups.FirstOrDefault(candidate =>
                WindowSpecsEqual(windowFunctions[candidate[0]].Window!, windowFunctions[ordinal].Window!));
            if (group is null)
            {
                group = [];
                groups.Add(group);
            }

            group.Add(ordinal);
        }

        foreach (var group in groups)
        {
            var functions = group.Select(ordinal => windowFunctions[ordinal]).ToArray();
            var computed = ComputeWindowFunctions(functions, rowCount, evaluate, inputs, parameters, context);
            for (var position = 0; position < functions.Length; position++)
            {
                var series = computed[functions[position]];
                for (var index = 0; index < rowCount; index++)
                    values[index][group[position]] = series[index];
            }
        }

        return values;
    }

    private Dictionary<FunctionExpression, WindowFunctionInput[]> PrepareWindowFunctionInputs(
        IReadOnlyList<FunctionExpression> functions,
        int rowCount,
        WindowInputEvaluator evaluate,
        QueryContext context)
    {
        var inputs = new Dictionary<FunctionExpression, WindowFunctionInput[]>();
        foreach (var function in functions)
            inputs.Add(function, new WindowFunctionInput[rowCount]);

        for (var rowIndex = 0; rowIndex < rowCount; rowIndex++)
        {
            context.CheckInterrupt();
            foreach (var function in functions)
            {
                var included = !IsAggregateWindowFunction(function)
                    || function.Filter is null
                    || IsTrue(evaluate(rowIndex, function.Filter));
                var arguments = included
                    ? function.Arguments
                        .Select(argument => evaluate(rowIndex, argument))
                        .ToArray()
                    : [];
                inputs[function][rowIndex] = new WindowFunctionInput(included, arguments);
            }
        }

        return inputs;
    }

    // Produces a collation entry per output column (not per projection) so that DISTINCT
    // comparison never indexes past the end when a projection expands to several columns
    // via * or table.*.
    private IReadOnlyList<string?> BuildProjectionCollations(
        SelectStatement statement,
        IReadOnlyList<OutputColumn> outputColumns,
        QueryContext context)
    {
        var collations = new List<string?>();
        foreach (var projection in statement.Projections)
        {
            switch (projection.Expression)
            {
                case StarExpression:
                    collations.AddRange(outputColumns.Select(column =>
                        NormalizeDeclaredCollation(
                            GetDeclaredOutputColumnCollation(statement.Source, column, context))));
                    break;
                case QualifiedStarExpression qualifiedStar:
                    foreach (var raw in GetRawOutputColumns(statement.Source, context).Where(raw =>
                                 string.Equals(
                                     raw.Qualifier,
                                     qualifiedStar.Qualifier,
                                     StringComparison.OrdinalIgnoreCase)))
                    {
                        var output = outputColumns.FirstOrDefault(column =>
                            string.Equals(
                                column.Qualifier,
                                qualifiedStar.Qualifier,
                                StringComparison.OrdinalIgnoreCase)
                            && column.Index == raw.Index) ?? raw;
                        collations.Add(NormalizeDeclaredCollation(
                            GetDeclaredOutputColumnCollation(
                                statement.Source,
                                output,
                                context)));
                    }

                    break;
                default:
                    collations.Add(GetEffectiveCollation(
                        projection.Expression,
                        EnterCollationSource(context, statement.Source)));
                    break;
            }
        }

        return collations;
    }

    // Sorts row indices with a caller-supplied comparison while guaranteeing stability by
    // breaking ties on the element's original ordinal. Window ordering must be stable so
    // ROWS frames and ORDER BY peer groups observe rows in their source order.
    private static List<int> StableSortIndices(List<int> indices, Comparison<int> comparison)
    {
        var decorated = indices
            .Select((value, ordinal) => (value, ordinal))
            .ToList();
        decorated.Sort((left, right) =>
        {
            var result = comparison(left.value, right.value);
            return result != 0 ? result : left.ordinal.CompareTo(right.ordinal);
        });

        return decorated.Select(entry => entry.value).ToList();
    }

    private sealed class WindowPartition
    {
        public WindowPartition(SqlValue[] keys)
        {
            Keys = keys;
        }

        public SqlValue[] Keys { get; }

        public List<int> Members { get; } = [];
    }

    private sealed record WindowOrderEntry(
        int SourceIndex,
        int StableOrdinal,
        SqlValue[] OrderKeys);

    private readonly record struct WindowFunctionInput(bool Included, SqlValue[] Arguments);

    private sealed record WindowPeerInfo(
        int[] Starts,
        int[] Ends,
        int[] GroupIndexes,
        IReadOnlyList<(int Start, int End)> Groups);

    private readonly record struct WindowFrameRuntime(SqlValue? StartOffset, SqlValue? EndOffset);

    private delegate SqlValue WindowInputEvaluator(int rowIndex, Expression expression);

    private Dictionary<FunctionExpression, SqlValue[]> ComputeWindowFunctions(
        IReadOnlyList<FunctionExpression> functions,
        int rowCount,
        WindowInputEvaluator evaluate,
        IReadOnlyDictionary<FunctionExpression, WindowFunctionInput[]> inputs,
        SqlValue[] parameters,
        QueryContext context)
    {
        var spec = functions[0].Window!;
        var results = new Dictionary<FunctionExpression, SqlValue[]>();
        foreach (var function in functions)
            results.Add(function, new SqlValue[rowCount]);

        var partitionCollations = spec.PartitionBy
            .Select(expression => GetEffectiveCollation(expression, context))
            .ToArray();
        VdbeGroupComparer partitionEquality = (left, right) =>
            GroupKeysEqual(left, right, partitionCollations);
        var partitionHasher = BuildGroupHasher(partitionCollations);
        var partitionIndexByKey = partitionHasher is null
            ? null
            : new Dictionary<SqlValue[], WindowPartition>(
                new GroupKeyEqualityComparer(partitionEquality, partitionHasher));
        var partitions = new List<WindowPartition>();
        var orderKeysBySource = new SqlValue[rowCount][];
        for (var index = 0; index < rowCount; index++)
        {
            context.CheckInterrupt();
            var keys = spec.PartitionBy.Count == 0
                ? []
                : spec.PartitionBy.Select(expression => evaluate(index, expression)).ToArray();
            WindowPartition? partition;
            if (partitionIndexByKey is not null)
            {
                partitionIndexByKey.TryGetValue(keys, out partition);
            }
            else
            {
                partition = partitions.FirstOrDefault(candidate =>
                    partitionEquality(candidate.Keys, keys));
            }
            if (partition is null)
            {
                partition = new WindowPartition(keys);
                partitions.Add(partition);
                partitionIndexByKey?.Add(keys, partition);
            }

            partition.Members.Add(index);
            orderKeysBySource[index] = spec.OrderBy
                .Select(term => evaluate(index, term.Expression))
                .ToArray();
        }

        if (partitions.Count == 0)
            return results;

        var needsFrame = functions.Any(WindowFunctionUsesFrame);
        var frameRuntime = needsFrame
            ? PrepareWindowFrame(spec, parameters, context)
            : default;
        foreach (var partition in partitions)
        {
            context.CheckInterrupt();
            var entries = new List<WindowOrderEntry>(partition.Members.Count);
            for (var ordinal = 0; ordinal < partition.Members.Count; ordinal++)
            {
                var sourceIndex = partition.Members[ordinal];
                entries.Add(new WindowOrderEntry(
                    sourceIndex,
                    ordinal,
                    orderKeysBySource[sourceIndex]));
            }

            if (spec.OrderBy.Count > 0)
            {
                entries.Sort((left, right) =>
                {
                    var comparison = CompareWindowOrderKeys(left.OrderKeys, right.OrderKeys, spec.OrderBy);
                    return comparison != 0
                        ? comparison
                        : left.StableOrdinal.CompareTo(right.StableOrdinal);
                });
            }

            var peers = BuildWindowPeerInfo(entries, spec.OrderBy);
            var ntileBuckets = new Dictionary<FunctionExpression, long>();
            foreach (var function in functions.Where(function =>
                         function.Name.Equals("NTILE", StringComparison.OrdinalIgnoreCase)))
            {
                var buckets = ToSqliteInteger(
                    inputs[function][entries[0].SourceIndex].Arguments[0]);
                if (buckets <= 0)
                    throw new EmbeddedSqlException("argument of ntile must be a positive integer");
                ntileBuckets.Add(function, buckets);
            }

            for (var position = 0; position < entries.Count; position++)
            {
                context.CheckInterrupt();
                var framePositions = needsFrame
                    ? ResolveWindowFramePositions(
                        spec,
                        entries,
                        peers,
                        position,
                        frameRuntime)
                    : [];
                foreach (var function in functions)
                {
                    results[function][entries[position].SourceIndex] = EvaluateWindowFunctionAtPosition(
                        function,
                        entries,
                        peers,
                        position,
                        framePositions,
                        ntileBuckets.GetValueOrDefault(function),
                        inputs[function],
                        parameters,
                        context);
                }
            }
        }

        return results;
    }

    private static bool WindowFunctionUsesFrame(FunctionExpression function)
    {
        return function.Name.ToUpperInvariant() switch
        {
            "ROW_NUMBER" or "RANK" or "DENSE_RANK" or "PERCENT_RANK" or "CUME_DIST"
                or "NTILE" or "LAG" or "LEAD" => false,
            _ => true,
        };
    }

    private bool WindowPartitionKeysEqual(
        IReadOnlyList<SqlValue> left,
        IReadOnlyList<SqlValue> right,
        IReadOnlyList<string?> collations)
    {
        if (left.Count != right.Count)
            return false;

        for (var index = 0; index < left.Count; index++)
        {
            if (!DistinctValuesEqual(left[index], right[index], collations[index]))
                return false;
        }

        return true;
    }

    private int CompareWindowOrderKeys(
        IReadOnlyList<SqlValue> left,
        IReadOnlyList<SqlValue> right,
        IReadOnlyList<OrderByTerm> orderBy)
    {
        for (var index = 0; index < orderBy.Count; index++)
        {
            var comparison = CompareForOrdering(
                left[index],
                right[index],
                orderBy[index],
                GetCollation(orderBy[index].Expression));
            if (comparison != 0)
                return comparison;
        }

        return 0;
    }

    private WindowPeerInfo BuildWindowPeerInfo(
        IReadOnlyList<WindowOrderEntry> entries,
        IReadOnlyList<OrderByTerm> orderBy)
    {
        var starts = new int[entries.Count];
        var ends = new int[entries.Count];
        var groupIndexes = new int[entries.Count];
        var groups = new List<(int Start, int End)>();
        var start = 0;
        while (start < entries.Count)
        {
            var end = start;
            while (end + 1 < entries.Count
                && CompareWindowOrderKeys(entries[start].OrderKeys, entries[end + 1].OrderKeys, orderBy) == 0)
            {
                end++;
            }

            var groupIndex = groups.Count;
            groups.Add((start, end));
            for (var position = start; position <= end; position++)
            {
                starts[position] = start;
                ends[position] = end;
                groupIndexes[position] = groupIndex;
            }

            start = end + 1;
        }

        return new WindowPeerInfo(starts, ends, groupIndexes, groups);
    }

    private WindowFrameRuntime PrepareWindowFrame(
        WindowSpecification spec,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (spec.Frame is not { } frame)
            return default;

        return new WindowFrameRuntime(
            EvaluateWindowFrameOffset(frame.Mode, frame.Start, "starting", parameters, context),
            EvaluateWindowFrameOffset(frame.Mode, frame.End, "ending", parameters, context));
    }

    private SqlValue? EvaluateWindowFrameOffset(
        Ahtola.Core.Parsing.WindowFrameMode mode,
        FrameBound bound,
        string boundary,
        SqlValue[] parameters,
        QueryContext context)
    {
        if (bound.Offset is null)
            return null;

        if (!IsWindowFrameConstant(bound.Offset))
        {
            throw new EmbeddedSqlException(
                mode == Ahtola.Core.Parsing.WindowFrameMode.Range
                    ? $"frame {boundary} offset must be a non-negative number"
                    : $"frame {boundary} offset must be a non-negative integer");
        }

        var value = Evaluate(bound.Offset, parameters, null, context);
        if (mode == Ahtola.Core.Parsing.WindowFrameMode.Range)
        {
            if (!TryGetWindowNumber(value, out var number) || number < 0 || double.IsNaN(number))
            {
                throw new EmbeddedSqlException(
                    $"frame {boundary} offset must be a non-negative number");
            }

            return SqlValue.Real(number);
        }

        if (!TryGetExactWindowInteger(value, out var integer) || integer < 0)
        {
            throw new EmbeddedSqlException(
                $"frame {boundary} offset must be a non-negative integer");
        }

        return SqlValue.Integer(integer);
    }

    private static bool IsWindowFrameConstant(Expression expression)
    {
        return expression switch
        {
            LiteralExpression or ParameterExpression => true,
            UnaryExpression unary => IsWindowFrameConstant(unary.Operand),
            BinaryExpression binary => IsWindowFrameConstant(binary.Left)
                && IsWindowFrameConstant(binary.Right),
            CollationExpression collation => IsWindowFrameConstant(collation.Expression),
            CastExpression cast => IsWindowFrameConstant(cast.Expression),
            CaseExpression @case => (@case.Operand is null || IsWindowFrameConstant(@case.Operand))
                && @case.Clauses.All(clause => IsWindowFrameConstant(clause.When)
                    && IsWindowFrameConstant(clause.Then))
                && (@case.Else is null || IsWindowFrameConstant(@case.Else)),
            LikeExpression like => IsWindowFrameConstant(like.Value)
                && IsWindowFrameConstant(like.Pattern)
                && (like.Escape is null || IsWindowFrameConstant(like.Escape)),
            GlobExpression glob => IsWindowFrameConstant(glob.Value)
                && IsWindowFrameConstant(glob.Pattern),
            InExpression @in => IsWindowFrameConstant(@in.Value)
                && @in.Values.All(IsWindowFrameConstant),
            BetweenExpression between => IsWindowFrameConstant(between.Value)
                && IsWindowFrameConstant(between.Lower)
                && IsWindowFrameConstant(between.Upper),
            _ => false,
        };
    }

    private IReadOnlyList<int> ResolveWindowFramePositions(
        WindowSpecification spec,
        IReadOnlyList<WindowOrderEntry> entries,
        WindowPeerInfo peers,
        int position,
        WindowFrameRuntime runtime)
    {
        var frame = spec.Frame ?? new WindowFrame(
            Ahtola.Core.Parsing.WindowFrameMode.Range,
            new FrameBound(FrameBoundKind.UnboundedPreceding, null),
            new FrameBound(FrameBoundKind.CurrentRow, null));
        var startRaw = ResolveWindowFrameBound(
            frame,
            frame.Start,
            isStart: true,
            entries,
            peers,
            position,
            runtime.StartOffset,
            spec.OrderBy);
        var endRaw = ResolveWindowFrameBound(
            frame,
            frame.End,
            isStart: false,
            entries,
            peers,
            position,
            runtime.EndOffset,
            spec.OrderBy);
        var start = (int)Math.Clamp(startRaw, 0L, entries.Count);
        var end = (int)Math.Clamp(endRaw, -1L, entries.Count - 1L);
        if (start > end)
            return [];

        var result = new List<int>(end - start + 1);
        for (var candidate = start; candidate <= end; candidate++)
        {
            var peer = candidate >= peers.Starts[position] && candidate <= peers.Ends[position];
            var include = frame.Exclusion switch
            {
                FrameExclusion.NoOthers => true,
                FrameExclusion.CurrentRow => candidate != position,
                FrameExclusion.Group => !peer,
                FrameExclusion.Ties => candidate == position || !peer,
                _ => throw new InvalidOperationException(
                    $"Unsupported window frame exclusion {frame.Exclusion}."),
            };
            if (include)
                result.Add(candidate);
        }

        return result;
    }

    private long ResolveWindowFrameBound(
        WindowFrame frame,
        FrameBound bound,
        bool isStart,
        IReadOnlyList<WindowOrderEntry> entries,
        WindowPeerInfo peers,
        int position,
        SqlValue? offset,
        IReadOnlyList<OrderByTerm> orderBy)
    {
        return frame.Mode switch
        {
            Ahtola.Core.Parsing.WindowFrameMode.Rows
                => ResolveRowsFrameBound(bound, position, entries.Count, offset),
            Ahtola.Core.Parsing.WindowFrameMode.Groups
                => ResolveGroupsFrameBound(bound, isStart, entries.Count, peers, position, offset),
            Ahtola.Core.Parsing.WindowFrameMode.Range
                => ResolveRangeFrameBound(bound, isStart, entries, peers, position, offset, orderBy),
            _ => throw new InvalidOperationException($"Unsupported window frame mode {frame.Mode}."),
        };
    }

    private static long ResolveRowsFrameBound(
        FrameBound bound,
        int position,
        int count,
        SqlValue? offset)
    {
        return bound.Kind switch
        {
            FrameBoundKind.UnboundedPreceding => 0,
            FrameBoundKind.UnboundedFollowing => count - 1L,
            FrameBoundKind.CurrentRow => position,
            FrameBoundKind.Preceding => position - Math.Min(offset!.Value.AsInteger(), count),
            FrameBoundKind.Following => position + Math.Min(offset!.Value.AsInteger(), count),
            _ => throw new InvalidOperationException($"Unsupported ROWS frame bound {bound.Kind}."),
        };
    }

    private static long ResolveGroupsFrameBound(
        FrameBound bound,
        bool isStart,
        int count,
        WindowPeerInfo peers,
        int position,
        SqlValue? offset)
    {
        if (bound.Kind == FrameBoundKind.UnboundedPreceding)
            return 0;
        if (bound.Kind == FrameBoundKind.UnboundedFollowing)
            return count - 1L;

        var currentGroup = peers.GroupIndexes[position];
        var targetGroup = bound.Kind switch
        {
            FrameBoundKind.CurrentRow => currentGroup,
            FrameBoundKind.Preceding => currentGroup - Math.Min(offset!.Value.AsInteger(), peers.Groups.Count),
            FrameBoundKind.Following => currentGroup + Math.Min(offset!.Value.AsInteger(), peers.Groups.Count),
            _ => throw new InvalidOperationException($"Unsupported GROUPS frame bound {bound.Kind}."),
        };
        if (targetGroup < 0)
            return isStart ? 0 : -1;
        if (targetGroup >= peers.Groups.Count)
            return isStart ? count : count - 1L;

        var group = peers.Groups[(int)targetGroup];
        return isStart ? group.Start : group.End;
    }

    private long ResolveRangeFrameBound(
        FrameBound bound,
        bool isStart,
        IReadOnlyList<WindowOrderEntry> entries,
        WindowPeerInfo peers,
        int position,
        SqlValue? offset,
        IReadOnlyList<OrderByTerm> orderBy)
    {
        if (bound.Kind == FrameBoundKind.UnboundedPreceding)
            return 0;
        if (bound.Kind == FrameBoundKind.UnboundedFollowing)
            return entries.Count - 1L;
        if (bound.Kind == FrameBoundKind.CurrentRow)
            return isStart ? peers.Starts[position] : peers.Ends[position];

        var current = entries[position].OrderKeys[0];
        if (!TryGetStoredWindowNumber(current, out var currentNumber))
            return isStart ? peers.Starts[position] : peers.Ends[position];

        var direction = orderBy[0].Descending ? -1d : 1d;
        // Negating descending keys maps both directions onto one ascending coordinate space.
        var currentCoordinate = direction * currentNumber;
        var distance = offset!.Value.AsReal();
        var target = bound.Kind == FrameBoundKind.Preceding
            ? currentCoordinate - distance
            : currentCoordinate + distance;

        if (isStart)
        {
            for (var candidate = 0; candidate < entries.Count; candidate++)
            {
                if (TryGetStoredWindowNumber(entries[candidate].OrderKeys[0], out var value)
                    && direction * value >= target)
                {
                    return candidate;
                }
            }

            return entries.Count;
        }

        for (var candidate = entries.Count - 1; candidate >= 0; candidate--)
        {
            if (TryGetStoredWindowNumber(entries[candidate].OrderKeys[0], out var value)
                && direction * value <= target)
            {
                return candidate;
            }
        }

        return -1;
    }

    private SqlValue EvaluateWindowFunctionAtPosition(
        FunctionExpression function,
        IReadOnlyList<WindowOrderEntry> entries,
        WindowPeerInfo peers,
        int position,
        IReadOnlyList<int> framePositions,
        long ntileBuckets,
        IReadOnlyList<WindowFunctionInput> inputs,
        SqlValue[] parameters,
        QueryContext context)
    {
        var name = function.Name.ToUpperInvariant();
        switch (name)
        {
            case "ROW_NUMBER":
                return SqlValue.Integer(position + 1L);
            case "RANK":
                return SqlValue.Integer(peers.Starts[position] + 1L);
            case "DENSE_RANK":
                return SqlValue.Integer(peers.GroupIndexes[position] + 1L);
            case "PERCENT_RANK":
                return SqlValue.Real(entries.Count == 1
                    ? 0
                    : (double)peers.Starts[position] / (entries.Count - 1));
            case "CUME_DIST":
                return SqlValue.Real((double)(peers.Ends[position] + 1) / entries.Count);
            case "NTILE":
                return SqlValue.Integer(ComputeNtile(position, entries.Count, ntileBuckets));
            case "LAG":
            case "LEAD":
                return EvaluateLagLead(function, entries, position, inputs);
            case "FIRST_VALUE":
                return framePositions.Count == 0
                    ? SqlValue.Null
                    : inputs[entries[framePositions[0]].SourceIndex].Arguments[0];
            case "LAST_VALUE":
                return framePositions.Count == 0
                    ? SqlValue.Null
                    : inputs[entries[framePositions[^1]].SourceIndex].Arguments[0];
            case "NTH_VALUE":
                {
                    var value = inputs[entries[position].SourceIndex].Arguments[1];
                    if (!TryGetExactWindowInteger(value, out var nth) || nth <= 0)
                    {
                        throw new EmbeddedSqlException(
                            "second argument to nth_value must be a positive integer");
                    }

                    return nth > framePositions.Count
                        ? SqlValue.Null
                        : inputs[entries[framePositions[(int)nth - 1]].SourceIndex].Arguments[0];
                }
            default:
                return EvaluateWindowAggregate(
                    function,
                    entries,
                    framePositions,
                    inputs,
                    parameters,
                    context);
        }
    }

    private SqlValue EvaluateWindowAggregate(
        FunctionExpression function,
        IReadOnlyList<WindowOrderEntry> entries,
        IReadOnlyList<int> framePositions,
        IReadOnlyList<WindowFunctionInput> inputs,
        SqlValue[] parameters,
        QueryContext context)
    {
        var isBuiltIn = function.Name.Equals("COUNT", StringComparison.OrdinalIgnoreCase)
            || IsBuiltInAggregate(function);
        if (!isBuiltIn
            && TryGetAggregateFunction(function.Name, function.Arguments.Count, out var aggregate))
        {
            var accumulator = aggregate.Seed;
            foreach (var position in framePositions)
            {
                var input = inputs[entries[position].SourceIndex];
                if (!input.Included)
                    continue;

                accumulator = InvokeManagedCallback(
                    () => aggregate.Step(accumulator, [.. input.Arguments]));
            }

            return InvokeManagedCallback(() => aggregate.Finalize(accumulator));
        }

        var argumentNames = Enumerable.Range(0, function.Arguments.Count)
            .Select(index => $"window_arg_{index}")
            .ToArray();
        var preparedRows = new List<SourceRow>(framePositions.Count);
        foreach (var position in framePositions)
        {
            var input = inputs[entries[position].SourceIndex];
            if (!input.Included)
                continue;

            preparedRows.Add(new SourceRow(argumentNames, input.Arguments));
        }

        var preparedArguments = function.Arguments
            .Select((argument, index) => RewritePreparedWindowArgument(
                argument,
                new ColumnExpression(argumentNames[index])))
            .ToArray();
        return EvaluateAggregateFunction(
            function with
            {
                Arguments = preparedArguments,
                Filter = null,
                Window = null,
            },
            preparedRows,
            parameters,
            context);
    }

    private static Expression RewritePreparedWindowArgument(
        Expression original,
        ColumnExpression prepared)
        => original is CollationExpression collation
            ? collation with { Expression = prepared }
            : prepared;

    private static long ComputeNtile(int position, int count, long buckets)
    {
        var smallerSize = count / buckets;
        if (smallerSize == 0)
            return position + 1L;

        var largerBucketCount = count % buckets;
        var largerRows = (smallerSize + 1) * largerBucketCount;
        return position < largerRows
            ? position / (smallerSize + 1) + 1
            : largerBucketCount + (position - largerRows) / smallerSize + 1;
    }

    private SqlValue EvaluateLagLead(
        FunctionExpression function,
        IReadOnlyList<WindowOrderEntry> entries,
        int position,
        IReadOnlyList<WindowFunctionInput> inputs)
    {
        var current = inputs[entries[position].SourceIndex].Arguments;
        var offsetValue = function.Arguments.Count >= 2
            ? current[1]
            : SqlValue.Integer(1);
        decimal? target = null;
        if (offsetValue.Kind != SqlValueKind.Null
            && TryGetExactWindowInteger(offsetValue, out var offset))
        {
            target = function.Name.Equals("LAG", StringComparison.OrdinalIgnoreCase)
                ? (decimal)position - offset
                : (decimal)position + offset;
        }

        if (target is >= 0 && target < entries.Count)
            return inputs[entries[(int)target.Value].SourceIndex].Arguments[0];

        return function.Arguments.Count == 3
            ? current[2]
            : SqlValue.Null;
    }

    private static bool TryGetExactWindowInteger(SqlValue value, out long integer)
    {
        switch (value.Kind)
        {
            case SqlValueKind.Integer:
                integer = value.AsInteger();
                return true;
            case SqlValueKind.Real:
                {
                    var real = value.AsReal();
                    if (double.IsFinite(real)
                        && real == Math.Truncate(real)
                        && real >= long.MinValue
                        && real < -(double)long.MinValue)
                    {
                        integer = (long)real;
                        return true;
                    }

                    break;
                }
            case SqlValueKind.Text:
                {
                    var text = value.AsText().Trim();
                    if (long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out integer))
                        return true;
                    if (double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var real)
                        && double.IsFinite(real)
                        && real == Math.Truncate(real)
                        && real >= long.MinValue
                        && real < -(double)long.MinValue)
                    {
                        integer = (long)real;
                        return true;
                    }

                    break;
                }
        }

        integer = 0;
        return false;
    }

    private static bool TryGetWindowNumber(SqlValue value, out double number)
    {
        switch (value.Kind)
        {
            case SqlValueKind.Integer:
                number = value.AsInteger();
                return true;
            case SqlValueKind.Real:
                number = value.AsReal();
                return true;
            case SqlValueKind.Text:
                return double.TryParse(
                    value.AsText().Trim(),
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out number);
            default:
                number = 0;
                return false;
        }
    }

    private static bool TryGetStoredWindowNumber(SqlValue value, out double number)
    {
        if (value.Kind == SqlValueKind.Integer)
        {
            number = value.AsInteger();
            return true;
        }
        if (value.Kind == SqlValueKind.Real)
        {
            number = value.AsReal();
            return true;
        }

        number = 0;
        return false;
    }

    private static long ToSqliteInteger(SqlValue value)
    {
        if (TryGetExactWindowInteger(value, out var integer))
            return integer;
        if (value.Kind == SqlValueKind.Real)
            return (long)value.AsReal();
        if (value.Kind == SqlValueKind.Text
            && double.TryParse(
                value.AsText().Trim(),
                NumberStyles.Float,
                CultureInfo.InvariantCulture,
                out var real))
        {
            return (long)real;
        }

        return 0;
    }

    private int CompareRows(
        SourceRow left,
        SourceRow right,
        IReadOnlyList<OrderByTerm> orderBy,
        SqlValue[] parameters,
        QueryContext context)
    {
        foreach (var term in orderBy)
        {
            var comparison = CompareForOrdering(
                Evaluate(term.Expression, parameters, left, context),
                Evaluate(term.Expression, parameters, right, context),
                term,
                GetEffectiveCollation(term.Expression, context));
            if (comparison == 0)
                continue;

            return comparison;
        }

        // ORDER BY ties are left to the caller. Every compiled route that consumes this
        // comparer sorts through the stable VDBE sorter (equal keys keep sorter-insertion
        // = scan order), and interpreted paths break ties by scan position. A rowid
        // tie-break would contradict the bare scan whenever the managed row store's scan
        // order is not rowid order (out-of-order rowid insertion) — native SQLite stays
        // self-consistent because its stable sorter runs over a rowid-ordered b-tree scan.
        return 0;
    }

    private int CompareGroupedRows(
        GroupedResult left,
        GroupedResult right,
        IReadOnlyList<OrderByTerm> orderBy,
        SqlValue[] parameters,
        QueryContext context)
    {
        foreach (var term in orderBy)
        {
            var comparison = CompareForOrdering(
                ContainsAggregate(term.Expression)
                    ? EvaluateAggregate(
                        term.Expression,
                        left.Rows,
                        parameters,
                        context,
                        left.Representative)
                    : Evaluate(term.Expression, parameters, left.Representative, context),
                ContainsAggregate(term.Expression)
                    ? EvaluateAggregate(
                        term.Expression,
                        right.Rows,
                        parameters,
                        context,
                        right.Representative)
                    : Evaluate(term.Expression, parameters, right.Representative, context),
                term,
                GetEffectiveCollation(term.Expression, context));
            if (comparison == 0)
                continue;

            return comparison;
        }

        return 0;
    }

    private int CompareOrderKeys(
        IReadOnlyList<SqlValue> left,
        IReadOnlyList<SqlValue> right,
        IReadOnlyList<OrderByTerm> orderBy,
        IReadOnlyList<string?> collations)
    {
        if (left.Count != orderBy.Count
            || right.Count != orderBy.Count
            || collations.Count != orderBy.Count)
        {
            throw new InvalidOperationException("ORDER BY key widths do not match their terms.");
        }

        for (var index = 0; index < orderBy.Count; index++)
        {
            var comparison = CompareForOrdering(
                left[index],
                right[index],
                orderBy[index],
                collations[index]);
            if (comparison != 0)
                return comparison;
        }

        return 0;
    }

    private int CompareForOrdering(
        SqlValue left,
        SqlValue right,
        OrderByTerm term,
        string? collation)
    {
        if (left.Kind == SqlValueKind.Null || right.Kind == SqlValueKind.Null)
        {
            if (left.Kind == right.Kind)
                return 0;

            var nullPlacement = term.NullPlacement switch
            {
                NullPlacement.Default => term.Descending ? NullPlacement.Last : NullPlacement.First,
                NullPlacement.First => NullPlacement.First,
                NullPlacement.Last => NullPlacement.Last,
                _ => throw new InvalidOperationException($"Unsupported NULL placement {term.NullPlacement}."),
            };
            return left.Kind == SqlValueKind.Null
                ? nullPlacement == NullPlacement.First ? -1 : 1
                : nullPlacement == NullPlacement.First ? 1 : -1;
        }

        var comparison = Compare(left, right, collation);
        return term.Descending && comparison != 0
            ? comparison > 0 ? -1 : 1
            : comparison;
    }

    private static IReadOnlyList<OrderByTerm> ResolveOrderBy(
        IReadOnlyList<OrderByTerm> orderBy,
        IReadOnlyList<Projection> projections)
    {
        return orderBy
            .Select(term => term with
            {
                Expression = ResolveOrderByExpression(term.Expression, projections, term.Ordinal),
                Ordinal = null,
            })
            .ToArray();
    }

    private static Expression ResolveOrderByExpression(
        Expression expression,
        IReadOnlyList<Projection> projections,
        long? ordinal = null)
    {
        if (expression is CollationExpression collation)
        {
            return collation with
            {
                Expression = ResolveOrderByExpression(collation.Expression, projections, ordinal),
            };
        }

        if (ordinal is { } value)
        {
            if (value is >= 1 and <= int.MaxValue && value <= projections.Count)
                return projections[(int)value - 1].Expression;

            if (!projections.Any(projection =>
                    projection.Expression is StarExpression or QualifiedStarExpression))
            {
                throw new EmbeddedSqlException(
                    $"ORDER BY position {value} is out of range for {projections.Count} result columns");
            }
        }

        if (expression is not ColumnExpression column)
            return expression;

        var projection = projections.FirstOrDefault(projection =>
            projection.Alias is not null
            && string.Equals(projection.Alias, column.Name, StringComparison.OrdinalIgnoreCase));
        return projection?.Expression ?? expression;
    }

    private static double AsReal(SqlValue value)
    {
        return value.Kind switch
        {
            SqlValueKind.Integer => value.AsInteger(),
            SqlValueKind.Real => value.AsReal(),
            _ => throw new EmbeddedSqlException($"Expected a numeric value, got {value.Kind}."),
        };
    }

    /// <summary>
    /// Numerifies a value the way SQLite's <c>sqlite3_value_double</c> does for CAST, arithmetic,
    /// truth tests, <c>abs()</c> and <c>round()</c>: a leading numeric prefix is consumed and the
    /// remainder is ignored, so <c>'12abc'</c> becomes 12 and a blob is read as its bytes. This is
    /// deliberately more permissive than <see cref="ApplyComparisonNumericAffinity"/>, which
    /// converts only a value that is entirely a well-formed number so that <c>'12abc'</c> never
    /// compares equal to 12 and is still stored as text in a NUMERIC column. The math builtins use
    /// that stricter rule instead and yield NULL; see <c>TryGetMathOperand</c>.
    /// </summary>
    private static SqlValue ApplyNumericAffinity(SqlValue value)
    {
        switch (value.Kind)
        {
            case SqlValueKind.Integer:
            case SqlValueKind.Real:
                return value;
            case SqlValueKind.Text when TryParseNumericPrefix(value.AsText(), out var text):
                return text;
            case SqlValueKind.Blob when TryParseNumericPrefix(DecodeBlobAsLatin1(value.AsBlob().Span), out var blob):
                return blob;
            default:
                return SqlValue.Integer(0);
        }
    }

    /// <summary>
    /// Casts a value to NUMERIC affinity for the CAST operator. Mirrors SQLite's
    /// <c>checked_cast_text_to_numeric</c> / <c>real_to_numeric_value</c> (ahtoladb core/util.rs):
    /// INTEGER and REAL inputs are no-ops, while TEXT/BLOB inputs parse to a numeric prefix and a
    /// float-looking result is downgraded to an integer when it is integral AND its magnitude is
    /// strictly below 2^51 (one bit under the f64 52-bit mantissa, preserving text-to-float
    /// round-trip precision). This is distinct from <see cref="ApplyNumericAffinity"/>, which
    /// implements the NUMERIC column storage affinity — storage preserves any integral real as an
    /// integer regardless of magnitude, so the shared helper must not gain the 2^51 cap.
    /// </summary>
    private static SqlValue CastToNumeric(SqlValue value)
    {
        switch (value.Kind)
        {
            case SqlValueKind.Integer:
            case SqlValueKind.Real:
                return value;
            case SqlValueKind.Text when TryParseNumericPrefix(value.AsText(), out var text):
                return DowngradeRealToNumeric(text);
            case SqlValueKind.Blob when TryParseNumericPrefix(DecodeBlobAsLatin1(value.AsBlob().Span), out var blob):
                return DowngradeRealToNumeric(blob);
            default:
                return SqlValue.Integer(0);
        }
    }

    private static SqlValue DowngradeRealToNumeric(SqlValue parsed)
    {
        if (parsed.Kind != SqlValueKind.Real)
            return parsed;

        var real = parsed.AsReal();
        if (real == 0.0)
            return SqlValue.Integer(0);

        if (double.IsFinite(real))
        {
            // unchecked: never throws on out-of-range magnitudes; the round-trip equality
            // check rejects inexact conversions (including saturated casts).
            var i = unchecked((long)real);
            const long Int51Max = 1L << 51; // 2251799813685248
            if ((double)i == real && i > -Int51Max && i < Int51Max)
                return SqlValue.Integer(i);
        }

        return parsed;
    }

    /// <summary>
    /// Reads blob bytes as characters for numerification. SQLite runs its text-to-number parser
    /// straight over the blob's bytes, and that parser accepts only ASCII, so a byte-preserving
    /// decode is equivalent while never throwing on non-UTF-8 content.
    /// </summary>
    private static string DecodeBlobAsLatin1(ReadOnlySpan<byte> bytes)
        => System.Text.Encoding.Latin1.GetString(bytes);

    /// <summary>
    /// Parses the leading numeric prefix of <paramref name="text"/>, mirroring SQLite's
    /// <c>sqlite3AtoF</c>. The result is an integer only when the prefix carries no fraction and
    /// no exponent and fits in a 64-bit integer, so <c>'1e3xyz'</c> is the real 1000.0 while
    /// <c>'12abc'</c> is the integer 12.
    /// </summary>
    private static bool TryParseNumericPrefix(ReadOnlySpan<char> text, out SqlValue value)
    {
        var index = 0;
        while (index < text.Length && IsSqlSpace(text[index]))
            index++;

        var start = index;
        if (index < text.Length && text[index] is '+' or '-')
            index++;

        var digits = 0;
        while (index < text.Length && char.IsAsciiDigit(text[index]))
        {
            index++;
            digits++;
        }

        var isReal = false;
        if (index < text.Length && text[index] == '.')
        {
            isReal = true;
            index++;
            while (index < text.Length && char.IsAsciiDigit(text[index]))
            {
                index++;
                digits++;
            }
        }

        if (digits == 0)
        {
            value = default;
            return false;
        }

        // An exponent only counts when at least one digit follows it, so '1e' is 1 rather than
        // a parse failure and '.e5' has no numeric prefix at all.
        if (index < text.Length && text[index] is 'e' or 'E')
        {
            var exponent = index + 1;
            if (exponent < text.Length && text[exponent] is '+' or '-')
                exponent++;
            if (exponent < text.Length && char.IsAsciiDigit(text[exponent]))
            {
                isReal = true;
                index = exponent;
                while (index < text.Length && char.IsAsciiDigit(text[index]))
                    index++;
            }
        }

        var number = text[start..index];
        if (!isReal
            && long.TryParse(number, NumberStyles.Integer, CultureInfo.InvariantCulture, out var integer))
        {
            value = SqlValue.Integer(integer);
            return true;
        }

        // An integer prefix too large for 64 bits degrades to a real, matching SQLite.
        if (double.TryParse(number, NumberStyles.Float, CultureInfo.InvariantCulture, out var real))
        {
            value = SqlValue.Real(real);
            return true;
        }

        value = default;
        return false;
    }

    private static bool IsSqlSpace(char character)
        => character is ' ' or '\t' or '\n' or '\v' or '\f' or '\r';

    private static long RequireInteger(SqlValue value)
    {
        if (value.Kind != SqlValueKind.Integer)
            throw new EmbeddedSqlException($"Expected an integer value, got {value.Kind}.");

        return value.AsInteger();
    }

    private static long RequireLimitInteger(SqlValue value)
    {
        if (value.Kind == SqlValueKind.Integer)
            return value.AsInteger();
        if (value.Kind == SqlValueKind.Real)
        {
            var real = value.AsReal();
            if (double.IsFinite(real)
                && real == Math.Truncate(real)
                && real >= long.MinValue
                && real < -(double)long.MinValue)
            {
                return (long)real;
            }
        }

        throw new EmbeddedSqlException("datatype mismatch");
    }

    internal static bool IsTrue(SqlValue value)
    {
        return value.Kind switch
        {
            SqlValueKind.Null => false,
            SqlValueKind.Integer => value.AsInteger() != 0,
            SqlValueKind.Real => value.AsReal() != 0,
            _ => IsTrue(ApplyNumericAffinity(value)),
        };
    }

    private static SqlValue ReadParameter(SqlValue[] parameters, int index)
    {
        if (index < 1 || index >= parameters.Length)
            throw new EmbeddedSqlException($"Missing value for parameter at position {index}.");

        return parameters[index];
    }

    internal static Dictionary<string, EmbeddedTable> CloneTables(Dictionary<string, EmbeddedTable> source)
    {
        var clone = new Dictionary<string, EmbeddedTable>(source.Comparer);
        foreach (var pair in source)
            clone.Add(pair.Key, pair.Value.Clone());

        return clone;
    }

    // Shallow per-statement DML rollback snapshot: shares per-row SqlValue[] references
    // with the live catalog (see EmbeddedTable.CloneShallow). Use this for INSERT/UPDATE/
    // DELETE/UPSERT/trigger backups; the deep CloneTables is still used for transaction
    // snapshots (SchemaCatalog.Clone) and DDL rollback, which may outlive the statement.
    internal static Dictionary<string, EmbeddedTable> CloneTablesShallow(Dictionary<string, EmbeddedTable> source)
    {
        var clone = new Dictionary<string, EmbeddedTable>(source.Comparer);
        foreach (var pair in source)
            clone.Add(pair.Key, pair.Value.CloneShallow());

        return clone;
    }

    // SQLite-compatible date/time scalar functions.
    //
    // This is a faithful port of SQLite's date.c algorithm (Julian Day arithmetic on integer
    // milliseconds), matched against the reference implementation in core/functions/datetime.rs.
    // It reproduces SQLite's exact parsing, modifier, and formatting semantics, including NULL
    // results for malformed inputs, out-of-range dates, and unsupported modifiers.
    private static class SqliteDateTime
    {
        internal enum Func
        {
            Date,
            Time,
            DateTime,
            JulianDay,
            UnixEpoch,
        }

        private const long JdToMs = 86_400_000L;
        private const long MaxJd = 464269060799999L; // 9999-12-31 23:59:59.999
        private const long UnixEpochIJd = 210866760000000L;
        private const double DoubleEpsilon = 2.220446049250313e-16; // f64::EPSILON
        private static readonly char[] AsciiWsChars = { ' ', '\t', '\n', '\r', '\u000C' };

        private sealed class Dt
        {
            public long IJd;
            public int Y = 2000;
            public int M = 1;
            public int D = 1;
            public int H;
            public int Min;
            public double S;
            public int Tz;
            public int NFloor;
            public bool ValidJd;
            public bool ValidYmd;
            public bool ValidHms;
            public bool RawS;
            public bool IsError;
            public bool UseSubsec;
            public bool IsUtc;
            public bool IsLocal;

            public Dt Clone() => (Dt)MemberwiseClone();

            public void SetError()
            {
                IJd = 0;
                Y = 2000;
                M = 1;
                D = 1;
                H = 0;
                Min = 0;
                S = 0.0;
                Tz = 0;
                NFloor = 0;
                ValidJd = ValidYmd = ValidHms = RawS = UseSubsec = IsUtc = IsLocal = false;
                IsError = true;
            }

            public void ComputeJd()
            {
                if (ValidJd)
                    return;

                int y;
                int m;
                int d;
                if (ValidYmd)
                {
                    y = Y;
                    m = M;
                    d = D;
                }
                else
                {
                    y = 2000;
                    m = 1;
                    d = 1;
                }

                if (y < -4713 || y > 9999 || RawS)
                {
                    SetError();
                    return;
                }

                if (m <= 2)
                {
                    y -= 1;
                    m += 12;
                }

                int a = (y + 4800) / 100;
                int b = 38 - a + (a / 4);
                int x1 = 36525 * (y + 4716) / 100;
                int x2 = 306001 * (m + 1) / 10000;
                IJd = ((long)x1 + x2 + d + b) * 86400000L - 131716800000L;
                ValidJd = true;
                if (ValidHms)
                {
                    IJd += (long)H * 3_600_000 + (long)Min * 60_000 + (long)(S * 1000.0 + 0.5);
                    if (Tz != 0)
                    {
                        IJd -= (long)Tz * 60_000;
                        ValidYmd = false;
                        ValidHms = false;
                        Tz = 0;
                        IsUtc = true;
                        IsLocal = false;
                    }
                }
            }

            public void ComputeYmd()
            {
                if (ValidYmd)
                    return;

                if (!ValidJd)
                {
                    Y = 2000;
                    M = 1;
                    D = 1;
                }
                else if (IJd < 0 || IJd > MaxJd)
                {
                    SetError();
                    return;
                }
                else
                {
                    int z = (int)((IJd + 43200000) / JdToMs);
                    int alpha = (int)((z + 32044.75) / 36524.25) - 52;
                    int a = z + 1 + alpha - ((alpha + 100) / 4) + 25;
                    int b = a + 1524;
                    int c = (int)((b - 122.1) / 365.25);
                    int dCalc = 36525 * (c & 32767) / 100;
                    int e = (int)((b - dCalc) / 30.6001);
                    int x1 = (int)(30.6001 * e);
                    D = b - dCalc - x1;
                    M = e < 14 ? e - 1 : e - 13;
                    Y = M > 2 ? c - 4716 : c - 4715;
                }

                ValidYmd = true;
            }

            public void ComputeHms()
            {
                if (ValidHms)
                    return;

                ComputeJd();
                int dayMs = (int)((IJd + 43200000) % 86400000);
                S = (dayMs % 60000) / 1000.0;
                int dayMin = dayMs / 60000;
                Min = dayMin % 60;
                H = dayMin / 60;
                RawS = false;
                ValidHms = true;
            }

            public void ComputeYmdHms()
            {
                ComputeYmd();
                ComputeHms();
            }

            public void ClearYmdHmsTz()
            {
                ValidYmd = false;
                ValidHms = false;
                Tz = 0;
            }

            public void ComputeFloor()
            {
                if (D <= 28 || ((1 << M) & 0x15aa) != 0)
                    NFloor = 0;
                else if (M != 2)
                    NFloor = D == 31 ? 1 : 0;
                else if (Y % 4 != 0 || (Y % 100 == 0 && Y % 400 != 0))
                    NFloor = D - 28;
                else
                    NFloor = D - 29;
            }
        }

        internal static SqlValue Execute(IReadOnlyList<SqlValue> args, Func func)
        {
            var p = new Dt();
            bool hasModifier = false;
            if (args.Count == 0)
            {
                SetToCurrent(p);
            }
            else
            {
                if (!InitTimeValue(p, args[0]))
                    return SqlValue.Null;

                for (int i = 1; i < args.Count; i++)
                {
                    hasModifier = true;
                    var v = args[i];
                    if (v.Kind != SqlValueKind.Text)
                        return SqlValue.Null;
                    if (!ParseModifier(p, v.AsText(), i - 1))
                        return SqlValue.Null;
                }
            }

            p.ComputeJd();
            if (p.IsError || p.IJd < 0 || p.IJd > MaxJd)
                return SqlValue.Null;

            if (!hasModifier && p.ValidYmd && p.D > 28)
                p.ValidYmd = false;

            switch (func)
            {
                case Func.JulianDay:
                    return SqlValue.Real((double)p.IJd / 86400000.0);
                case Func.UnixEpoch:
                    if (p.UseSubsec)
                        return SqlValue.Real((double)(p.IJd - UnixEpochIJd) / 1000.0);
                    return SqlValue.Integer((p.IJd - UnixEpochIJd) / 1000);
                default:
                    p.ComputeYmdHms();
                    if (p.IsError)
                        return SqlValue.Null;
                    return SqlValue.Text(Format(p, func));
            }
        }

        /// <summary>
        /// Resolves a date/time argument to UTC using the same parsing rules as the
        /// date/time builtins, so callers such as timediff() stay consistent with them.
        /// </summary>
        internal static bool TryResolveUtc(SqlValue value, out DateTime result)
        {
            result = default;
            var p = new Dt();
            if (!InitTimeValue(p, value))
                return false;

            p.ComputeJd();
            if (p.IsError || p.IJd < 0 || p.IJd > MaxJd)
                return false;

            result = DateTimeOffset.FromUnixTimeMilliseconds(p.IJd - UnixEpochIJd).UtcDateTime;
            return true;
        }

        internal static SqlValue Strftime(IReadOnlyList<SqlValue> args)
        {
            if (args.Count < 1)
                return SqlValue.Null;

            var fmtVal = args[0];
            if (fmtVal.Kind == SqlValueKind.Null)
                return SqlValue.Null;
            string fmt = fmtVal.Kind == SqlValueKind.Text ? fmtVal.AsText() : ToSqlText(fmtVal);

            var p = new Dt();
            if (args.Count == 1)
            {
                SetToCurrent(p);
            }
            else
            {
                if (!InitTimeValue(p, args[1]))
                    return SqlValue.Null;

                for (int i = 2; i < args.Count; i++)
                {
                    var v = args[i];
                    if (v.Kind != SqlValueKind.Text)
                        return SqlValue.Null;
                    if (!ParseModifier(p, v.AsText(), i - 2))
                        return SqlValue.Null;
                }
            }

            p.ComputeJd();
            if (p.IsError)
                return SqlValue.Null;
            p.ComputeYmdHms();

            return FormatStrftime(fmt, p);
        }

        private static bool InitTimeValue(Dt p, SqlValue value)
        {
            switch (value.Kind)
            {
                case SqlValueKind.Text:
                    return ParseDateOrTime(value.AsText(), p);
                case SqlValueKind.Integer:
                    SetRawNumber(p, value.AsInteger());
                    return true;
                case SqlValueKind.Real:
                    SetRawNumber(p, value.AsReal());
                    return true;
                default:
                    return false;
            }
        }

        private static void SetRawNumber(Dt p, double value)
        {
            p.S = value;
            p.RawS = true;
            if (value >= 0.0 && value < 5373484.5)
            {
                p.IJd = (long)(value * JdToMs + 0.5);
                p.ValidJd = true;
            }
        }

        private static string Format(Dt p, Func func)
        {
            var sb = new StringBuilder();
            if (func == Func.Time)
            {
                sb.Append(p.H.ToString("D2", CultureInfo.InvariantCulture));
                sb.Append(':').Append(p.Min.ToString("D2", CultureInfo.InvariantCulture));
                AppendSeconds(sb, p);
            }
            else
            {
                AppendDate(sb, p);
                if (func == Func.DateTime)
                {
                    sb.Append(' ');
                    sb.Append(p.H.ToString("D2", CultureInfo.InvariantCulture));
                    sb.Append(':').Append(p.Min.ToString("D2", CultureInfo.InvariantCulture));
                    AppendSeconds(sb, p);
                }
            }

            return sb.ToString();
        }

        private static void AppendDate(StringBuilder sb, Dt p)
        {
            if (p.Y < 0)
                sb.Append('-').Append(Math.Abs(p.Y).ToString("D4", CultureInfo.InvariantCulture));
            else
                sb.Append(p.Y.ToString("D4", CultureInfo.InvariantCulture));
            sb.Append('-').Append(p.M.ToString("D2", CultureInfo.InvariantCulture));
            sb.Append('-').Append(p.D.ToString("D2", CultureInfo.InvariantCulture));
        }

        private static void AppendSeconds(StringBuilder sb, Dt p)
        {
            sb.Append(':');
            if (p.UseSubsec)
                sb.Append(p.S.ToString("00.000", CultureInfo.InvariantCulture));
            else
                sb.Append(((int)p.S).ToString("D2", CultureInfo.InvariantCulture));
        }

        private static SqlValue FormatStrftime(string fmt, Dt p)
        {
            var res = new StringBuilder();
            for (int i = 0; i < fmt.Length; i++)
            {
                char c = fmt[i];
                if (c != '%')
                {
                    res.Append(c);
                    continue;
                }

                i++;
                if (i >= fmt.Length)
                    return SqlValue.Null;

                switch (fmt[i])
                {
                    case 'd':
                        res.Append(p.D.ToString("D2", CultureInfo.InvariantCulture));
                        break;
                    case 'e':
                        res.Append(p.D.ToString(CultureInfo.InvariantCulture).PadLeft(2));
                        break;
                    case 'F':
                        res.Append(p.Y.ToString("D4", CultureInfo.InvariantCulture));
                        res.Append('-').Append(p.M.ToString("D2", CultureInfo.InvariantCulture));
                        res.Append('-').Append(p.D.ToString("D2", CultureInfo.InvariantCulture));
                        break;
                    case 'f':
                        {
                            double sf = p.S;
                            if (sf > 59.999)
                                sf = 59.999;
                            res.Append(sf.ToString("00.000", CultureInfo.InvariantCulture));
                            break;
                        }
                    case 'g':
                        {
                            var iso = p.Clone();
                            iso.IJd += (3 - DaysAfterMon(p)) * 86400000;
                            iso.ValidYmd = false;
                            iso.ComputeYmd();
                            res.Append((iso.Y % 100).ToString("D2", CultureInfo.InvariantCulture));
                            break;
                        }
                    case 'G':
                        {
                            var iso = p.Clone();
                            iso.IJd += (3 - DaysAfterMon(p)) * 86400000;
                            iso.ValidYmd = false;
                            iso.ComputeYmd();
                            res.Append(iso.Y.ToString("D4", CultureInfo.InvariantCulture));
                            break;
                        }
                    case 'H':
                        res.Append(p.H.ToString("D2", CultureInfo.InvariantCulture));
                        break;
                    case 'I':
                        {
                            int h = p.H % 12 == 0 ? 12 : p.H % 12;
                            res.Append(h.ToString("D2", CultureInfo.InvariantCulture));
                            break;
                        }
                    case 'j':
                        res.Append((DaysAfterJan1(p) + 1).ToString("D3", CultureInfo.InvariantCulture));
                        break;
                    case 'J':
                        res.Append(FormatJulianDaySpecifier(p));
                        break;
                    case 'k':
                        res.Append(p.H.ToString(CultureInfo.InvariantCulture).PadLeft(2));
                        break;
                    case 'l':
                        {
                            int h = p.H % 12 == 0 ? 12 : p.H % 12;
                            res.Append(h.ToString(CultureInfo.InvariantCulture).PadLeft(2));
                            break;
                        }
                    case 'm':
                        res.Append(p.M.ToString("D2", CultureInfo.InvariantCulture));
                        break;
                    case 'M':
                        res.Append(p.Min.ToString("D2", CultureInfo.InvariantCulture));
                        break;
                    case 'p':
                        res.Append(p.H >= 12 ? "PM" : "AM");
                        break;
                    case 'P':
                        res.Append(p.H >= 12 ? "pm" : "am");
                        break;
                    case 'R':
                        res.Append(p.H.ToString("D2", CultureInfo.InvariantCulture));
                        res.Append(':').Append(p.Min.ToString("D2", CultureInfo.InvariantCulture));
                        break;
                    case 's':
                        if (p.UseSubsec)
                            res.Append(((double)(p.IJd - UnixEpochIJd) / 1000.0).ToString("F3", CultureInfo.InvariantCulture));
                        else
                            res.Append(((p.IJd - UnixEpochIJd) / 1000).ToString(CultureInfo.InvariantCulture));
                        break;
                    case 'S':
                        res.Append(((int)p.S).ToString("D2", CultureInfo.InvariantCulture));
                        break;
                    case 'T':
                        res.Append(p.H.ToString("D2", CultureInfo.InvariantCulture));
                        res.Append(':').Append(p.Min.ToString("D2", CultureInfo.InvariantCulture));
                        res.Append(':').Append(((int)p.S).ToString("D2", CultureInfo.InvariantCulture));
                        break;
                    case 'u':
                        {
                            long w = DaysAfterSun(p);
                            if (w == 0)
                                w = 7;
                            res.Append(w.ToString(CultureInfo.InvariantCulture));
                            break;
                        }
                    case 'U':
                        res.Append(((DaysAfterJan1(p) - DaysAfterSun(p) + 7) / 7).ToString("D2", CultureInfo.InvariantCulture));
                        break;
                    case 'V':
                        {
                            var iso = p.Clone();
                            iso.IJd += (3 - DaysAfterMon(p)) * 86400000;
                            iso.ValidYmd = false;
                            iso.ComputeYmd();
                            res.Append((DaysAfterJan1(iso) / 7 + 1).ToString("D2", CultureInfo.InvariantCulture));
                            break;
                        }
                    case 'w':
                        res.Append(DaysAfterSun(p).ToString(CultureInfo.InvariantCulture));
                        break;
                    case 'W':
                        res.Append(((DaysAfterJan1(p) - DaysAfterMon(p) + 7) / 7).ToString("D2", CultureInfo.InvariantCulture));
                        break;
                    case 'Y':
                        res.Append(p.Y.ToString("D4", CultureInfo.InvariantCulture));
                        break;
                    case '%':
                        res.Append('%');
                        break;
                    default:
                        return SqlValue.Null;
                }
            }

            return SqlValue.Text(res.ToString());
        }

        private static string FormatJulianDaySpecifier(Dt p)
        {
            double val = (double)p.IJd / 86400000.0;
            double abs = Math.Abs(val);
            if (abs >= 1_000_000.0 && abs < 10_000_000.0)
            {
                string s = val.ToString("F9", CultureInfo.InvariantCulture);
                s = s.TrimEnd('0').TrimEnd('.');
                return s;
            }

            return val.ToString(CultureInfo.InvariantCulture);
        }

        private static long DaysAfterJan1(Dt cur)
        {
            var jan1 = new Dt { Y = cur.Y, M = 1, D = 1, ValidYmd = true };
            jan1.ComputeJd();
            var c1 = new Dt { Y = cur.Y, M = cur.M, D = cur.D, ValidYmd = true };
            c1.ComputeJd();
            return (c1.IJd - jan1.IJd) / JdToMs;
        }

        private static long DaysAfterMon(Dt cur) => ((cur.IJd + 43200000) / JdToMs) % 7;

        private static long DaysAfterSun(Dt cur) => ((cur.IJd + 129600000) / JdToMs) % 7;

        private static void SetToCurrent(Dt p)
        {
            long ms = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            p.IJd = UnixEpochIJd + ms;
            p.ValidJd = true;
            p.IsUtc = true;
            p.IsLocal = false;
            p.ClearYmdHmsTz();
        }

        private static bool ParseDateOrTime(string value, Dt p)
        {
            if (ParseYyyyMmDd(value, p))
                return true;
            if (ParseHhMmSs(value, p))
                return true;
            if (value.Equals("now", StringComparison.OrdinalIgnoreCase))
            {
                SetToCurrent(p);
                return true;
            }

            string numeric = value.Trim(AsciiWsChars);
            if (double.TryParse(numeric, NumberStyles.Float, CultureInfo.InvariantCulture, out double val))
            {
                p.S = val;
                p.RawS = true;
                if (val >= 0.0 && val < 5373484.5)
                {
                    p.IJd = (long)(val * JdToMs + 0.5);
                    p.ValidJd = true;
                }

                return true;
            }

            if (value.Equals("subsec", StringComparison.OrdinalIgnoreCase)
                || value.Equals("subsecond", StringComparison.OrdinalIgnoreCase))
            {
                p.UseSubsec = true;
                SetToCurrent(p);
                return true;
            }

            return false;
        }

        private static bool ParseYyyyMmDd(string z, Dt p)
        {
            bool neg = z.StartsWith('-');
            if (neg)
                z = z.Substring(1);

            if (!GetDigits(z, 4, 0, 9999, out int y, out z))
                return false;
            if (!z.StartsWith('-'))
                return false;
            z = z.Substring(1);
            if (!GetDigits(z, 2, 1, 12, out int m, out z))
                return false;
            if (!z.StartsWith('-'))
                return false;
            z = z.Substring(1);
            if (!GetDigits(z, 2, 1, 31, out int d, out z))
                return false;

            while (z.Length > 0 && (IsAsciiWhitespace(z[0]) || z[0] == 'T'))
                z = z.Substring(1);

            if (ParseHhMmSs(z, p))
            {
                // Time component parsed.
            }
            else if (z.Length == 0)
            {
                p.ValidHms = false;
            }
            else
            {
                return false;
            }

            p.ValidJd = false;
            p.ValidYmd = true;
            p.Y = neg ? -y : y;
            p.M = m;
            p.D = d;
            p.ComputeFloor();
            if (p.Tz != 0)
                p.ComputeJd();
            return true;
        }

        private static bool ParseHhMmSs(string z, Dt p)
        {
            if (!GetDigits(z, 2, 0, 24, out int h, out z))
                return false;
            if (!z.StartsWith(':'))
                return false;
            z = z.Substring(1);
            if (!GetDigits(z, 2, 0, 59, out int m, out z))
                return false;

            int s;
            double ms = 0.0;
            if (z.StartsWith(':'))
            {
                z = z.Substring(1);
                if (!GetDigits(z, 2, 0, 59, out s, out z))
                    return false;

                if (z.Length > 1 && z[0] == '.' && char.IsAsciiDigit(z[1]))
                {
                    double rScale = 1.0;
                    z = z.Substring(1);
                    while (z.Length > 0 && char.IsAsciiDigit(z[0]))
                    {
                        ms = ms * 10.0 + (z[0] - '0');
                        rScale *= 10.0;
                        z = z.Substring(1);
                    }

                    ms /= rScale;
                    if (ms > 0.999)
                        ms = 0.999;
                }
            }
            else
            {
                s = 0;
            }

            p.ValidJd = false;
            p.RawS = false;
            p.ValidHms = true;
            p.H = h;
            p.Min = m;
            p.S = s + ms;

            return !ParseTimezone(z, p);
        }

        private static bool ParseTimezone(string z, Dt p)
        {
            while (z.Length > 0 && IsAsciiWhitespace(z[0]))
                z = z.Substring(1);

            p.Tz = 0;
            if (z.Length == 0)
                return false;

            char c = z[0];
            int sgn;
            if (c == '-')
            {
                sgn = -1;
            }
            else if (c == '+')
            {
                sgn = 1;
            }
            else if (c == 'Z' || c == 'z')
            {
                z = z.Substring(1);
                p.IsLocal = false;
                p.IsUtc = true;
                return CheckTrailingGarbage(z);
            }
            else
            {
                return true;
            }

            z = z.Substring(1);
            if (!GetDigits(z, 2, 0, 14, out int nHr, out z))
                return true;
            if (!z.StartsWith(':'))
                return true;
            z = z.Substring(1);
            if (!GetDigits(z, 2, 0, 59, out int nMn, out z))
                return true;

            p.Tz = sgn * (nMn + nHr * 60);
            if (p.Tz == 0)
            {
                p.IsLocal = false;
                p.IsUtc = true;
            }

            return CheckTrailingGarbage(z);
        }

        private static bool CheckTrailingGarbage(string z)
        {
            while (z.Length > 0 && IsAsciiWhitespace(z[0]))
                z = z.Substring(1);
            return z.Length > 0;
        }

        private static void AutoAdjustDate(Dt p)
        {
            if (!p.RawS || p.ValidJd)
            {
                p.RawS = false;
            }
            else if (p.S >= -210866760000.0 && p.S <= 253402300799.0)
            {
                double r = p.S * 1000.0 + 210866760000000.0;
                p.IJd = (long)(r + 0.5);
                p.ValidJd = true;
                p.RawS = false;
                p.ClearYmdHmsTz();
            }
        }

        private static bool ParseModifier(Dt p, string z, int idx)
        {
            if (z.Length == 0)
                return false;

            switch (char.ToLowerInvariant(z[0]))
            {
                case 'a':
                    if (z.Equals("auto", StringComparison.OrdinalIgnoreCase))
                    {
                        if (idx > 0)
                            return false;
                        AutoAdjustDate(p);
                        return true;
                    }

                    return false;
                case 'c':
                    if (z.Equals("ceiling", StringComparison.OrdinalIgnoreCase))
                    {
                        p.ComputeJd();
                        p.ClearYmdHmsTz();
                        p.NFloor = 0;
                        return true;
                    }

                    return false;
                case 'f':
                    if (z.Equals("floor", StringComparison.OrdinalIgnoreCase))
                    {
                        p.ComputeJd();
                        if (p.NFloor != 0)
                        {
                            p.IJd -= (long)p.NFloor * JdToMs;
                            p.NFloor = 0;
                        }

                        p.ClearYmdHmsTz();
                        return true;
                    }

                    return false;
                case 'j':
                    if (z.Equals("julianday", StringComparison.OrdinalIgnoreCase))
                    {
                        if (idx > 0)
                            return false;
                        if (p.ValidJd && p.RawS)
                        {
                            p.RawS = false;
                            return true;
                        }

                        return false;
                    }

                    return false;
                case 'l':
                    if (z.Equals("localtime", StringComparison.OrdinalIgnoreCase))
                    {
                        if (!p.IsLocal)
                        {
                            p.ComputeJd();
                            p.IJd += (long)LocalOffsetSeconds(p.IJd) * 1000;
                            p.ClearYmdHmsTz();
                            p.IsLocal = true;
                            p.IsUtc = false;
                        }

                        return true;
                    }

                    return false;
                case 'u':
                    if (z.Equals("unixepoch", StringComparison.OrdinalIgnoreCase))
                    {
                        if (idx > 0)
                            return false;
                        if (p.RawS)
                        {
                            double r = p.S * 1000.0 + 210866760000000.0;
                            p.IJd = (long)(r + 0.5);
                            p.ValidJd = true;
                            p.RawS = false;
                            p.ClearYmdHmsTz();
                            return true;
                        }

                        return false;
                    }

                    if (z.Equals("utc", StringComparison.OrdinalIgnoreCase))
                    {
                        if (!p.IsUtc)
                        {
                            p.ComputeJd();
                            p.IJd -= (long)LocalOffsetSeconds(p.IJd) * 1000;
                            p.ClearYmdHmsTz();
                            p.IsUtc = true;
                            p.IsLocal = false;
                        }

                        return true;
                    }

                    return false;
                case 'w':
                    if (z.Length >= 8 && z.Substring(0, 8).Equals("weekday ", StringComparison.OrdinalIgnoreCase))
                    {
                        string rest = z.Substring(8).Trim();
                        if (double.TryParse(rest, NumberStyles.Float, CultureInfo.InvariantCulture, out double val)
                            && val >= 0.0 && val < 7.0 && (double)(long)val == val)
                        {
                            long n = (long)val;
                            p.ComputeYmdHms();
                            p.ValidJd = false;
                            p.ComputeJd();
                            long zz = ((p.IJd + 129600000) / 86400000) % 7;
                            if (zz > n)
                                zz -= 7;
                            p.IJd += (n - zz) * 86400000;
                            p.ClearYmdHmsTz();
                            return true;
                        }

                        return false;
                    }

                    return false;
                case 's':
                    if (z.Equals("subsec", StringComparison.OrdinalIgnoreCase)
                        || z.Equals("subsecond", StringComparison.OrdinalIgnoreCase))
                    {
                        p.UseSubsec = true;
                        return true;
                    }

                    if (z.Length >= 9 && z.Substring(0, 9).Equals("start of ", StringComparison.OrdinalIgnoreCase))
                    {
                        if (!p.ValidJd && !p.ValidYmd && !p.ValidHms)
                            return false;

                        p.ComputeYmd();
                        p.ValidHms = true;
                        p.H = 0;
                        p.Min = 0;
                        p.S = 0.0;
                        p.RawS = false;
                        p.ValidJd = false;
                        p.Tz = 0;
                        p.NFloor = 0;

                        string suffix = z.Substring(9);
                        if (suffix.Equals("month", StringComparison.OrdinalIgnoreCase))
                        {
                            p.D = 1;
                            return true;
                        }

                        if (suffix.Equals("year", StringComparison.OrdinalIgnoreCase))
                        {
                            p.M = 1;
                            p.D = 1;
                            return true;
                        }

                        if (suffix.Equals("day", StringComparison.OrdinalIgnoreCase))
                            return true;

                        return false;
                    }

                    return false;
                case '+':
                case '-':
                case '0':
                case '1':
                case '2':
                case '3':
                case '4':
                case '5':
                case '6':
                case '7':
                case '8':
                case '9':
                    return ParseArithmeticModifier(p, z);
                default:
                    return false;
            }
        }

        private static bool ParseArithmeticModifier(Dt p, string z)
        {
            z = z.Trim(AsciiWsChars);
            bool isNeg = z.StartsWith('-');
            int sign = isNeg ? -1 : 1;
            bool hasSign = z.StartsWith('+') || z.StartsWith('-');
            string cleanZ = hasSign ? z.Substring(1) : z;

            // Case 1: YYYY-MM-DD [HH:MM:SS] arithmetic modifier.
            // SQLite's date.c requires an explicit leading '+'/'-' sign for this form; the
            // unsigned "NNNN-NN-NN[ HH:MM:SS]" spelling is rejected (yields NULL). Match that
            // exactly, even though the Rust reference currently accepts the unsigned spelling.
            if (hasSign && cleanZ.Length >= 10 && cleanZ[4] == '-' && cleanZ[7] == '-')
            {
                bool okY = GetDigits(cleanZ.Substring(0, 4), 4, 0, 9999, out int yy, out _);
                bool okM = GetDigits(cleanZ.Substring(5, 2), 2, 0, 11, out int mm, out _);
                bool okD = GetDigits(cleanZ.Substring(8, 2), 2, 0, 30, out int dd, out _);
                if (okY && okM && okD)
                {
                    string rem = cleanZ.Substring(10);
                    bool validFormat = true;
                    string? timeStr = null;
                    if (rem.Length != 0)
                    {
                        if (rem.StartsWith(' '))
                            timeStr = rem.TrimStart(AsciiWsChars);
                        else
                            validFormat = false;
                    }

                    if (validFormat)
                    {
                        p.ComputeYmdHms();
                        p.ValidJd = false;
                        unchecked
                        {
                            if (isNeg)
                            {
                                p.Y -= yy;
                                p.M -= mm;
                            }
                            else
                            {
                                p.Y += yy;
                                p.M += mm;
                            }

                            long mCurrent = p.M;
                            long x = mCurrent > 0 ? (mCurrent - 1) / 12 : (mCurrent - 12) / 12;
                            p.Y += (int)x;
                            p.M = (int)(mCurrent - x * 12);
                        }

                        p.ComputeFloor();
                        p.ComputeJd();

                        long dayDiff = isNeg ? -(long)dd : dd;
                        p.IJd = unchecked(p.IJd + dayDiff * JdToMs);

                        if (timeStr != null)
                        {
                            var tx = new Dt();
                            if (ParseHhMmSs(timeStr, tx))
                            {
                                tx.ComputeJd();
                                long ms = (long)tx.H * 3600000 + (long)tx.Min * 60000 + (long)(tx.S * 1000.0);
                                p.IJd = unchecked(p.IJd + sign * ms);
                            }
                            else
                            {
                                return false;
                            }
                        }

                        p.ClearYmdHmsTz();
                        return true;
                    }
                }
            }

            // Case 2: HH:MM:SS arithmetic modifier.
            if (z.Contains(':'))
            {
                var tx = new Dt();
                string timeStr = z.StartsWith('+') || z.StartsWith('-') ? z.Substring(1) : z;
                if (ParseHhMmSs(timeStr, tx))
                {
                    tx.ComputeJd();
                    long ms = (long)tx.H * 3600000 + (long)tx.Min * 60000 + (long)(tx.S * 1000.0);
                    p.ComputeJd();
                    p.IJd = unchecked(p.IJd + sign * ms);
                    p.ClearYmdHmsTz();
                    return true;
                }
            }

            // Case 3: NNN <unit> arithmetic modifier.
            string[] parts = z.Split(AsciiWsChars, StringSplitOptions.RemoveEmptyEntries);
            if (parts.Length >= 2
                && double.TryParse(parts[0], NumberStyles.Float, CultureInfo.InvariantCulture, out double amount))
            {
                string unit = parts[1];
                double abs = Math.Abs(amount);

                if (UnitIs(unit, "day"))
                    return ApplyMillisecondUnit(p, amount, abs, 5373485.0, 86400000.0);
                if (UnitIs(unit, "hour"))
                    return ApplyMillisecondUnit(p, amount, abs, 1.2897e+11, 3600000.0);
                if (UnitIs(unit, "minute"))
                    return ApplyMillisecondUnit(p, amount, abs, 7.7379e+12, 60000.0);
                if (UnitIs(unit, "second"))
                    return ApplyMillisecondUnit(p, amount, abs, 4.6427e+14, 1000.0);
                if (UnitIs(unit, "month"))
                    return ApplyMonths(p, amount, abs);
                if (UnitIs(unit, "year"))
                    return ApplyYears(p, amount, abs);
            }

            return false;
        }

        private static bool UnitIs(string unit, string singular)
            => unit.Equals(singular, StringComparison.OrdinalIgnoreCase)
                || unit.Equals(singular + "s", StringComparison.OrdinalIgnoreCase);

        private static bool ApplyMillisecondUnit(Dt p, double amount, double abs, double limit, double scale)
        {
            if (!(abs < limit))
                return false;

            p.ComputeJd();
            double ms = amount * scale;
            double rounder = ms < 0.0 ? -0.5 : 0.5;
            p.IJd = unchecked(p.IJd + (long)(ms + rounder));
            p.NFloor = 0;
            p.ClearYmdHmsTz();
            return true;
        }

        private static bool ApplyMonths(Dt p, double amount, double abs)
        {
            if (!(abs < 176546.0))
                return false;

            p.ComputeYmdHms();
            long intMonths = (long)amount;
            double fracMonths = amount - intMonths;

            long totalMonths = p.M + intMonths;
            long x = totalMonths > 0 ? (totalMonths - 1) / 12 : (totalMonths - 12) / 12;
            p.Y = unchecked(p.Y + (int)x);
            p.M = (int)(totalMonths - x * 12);

            p.ComputeFloor();
            p.ValidJd = false;
            p.ComputeJd();

            if (Math.Abs(fracMonths) > DoubleEpsilon)
            {
                double ms = fracMonths * 30.0 * JdToMs;
                double rounder = ms < 0.0 ? -0.5 : 0.5;
                p.IJd = unchecked(p.IJd + (long)(ms + rounder));
            }

            p.ClearYmdHmsTz();
            return true;
        }

        private static bool ApplyYears(Dt p, double amount, double abs)
        {
            if (!(abs < 14713.0))
                return false;

            p.ComputeYmdHms();
            long intYears = (long)amount;
            double fracYears = amount - intYears;

            p.Y = unchecked(p.Y + (int)intYears);

            p.ComputeFloor();
            p.ValidJd = false;
            p.ComputeJd();

            if (Math.Abs(fracYears) > DoubleEpsilon)
            {
                double ms = fracYears * 365.0 * JdToMs;
                double rounder = ms < 0.0 ? -0.5 : 0.5;
                p.IJd = unchecked(p.IJd + (long)(ms + rounder));
            }

            p.ClearYmdHmsTz();
            return true;
        }

        private static int LocalOffsetSeconds(long iJd)
        {
            long timestamp = (iJd - UnixEpochIJd) / 1000;
            try
            {
                var instant = DateTimeOffset.FromUnixTimeSeconds(timestamp);
                return (int)TimeZoneInfo.Local.GetUtcOffset(instant).TotalSeconds;
            }
            catch (ArgumentOutOfRangeException)
            {
                return 0;
            }
        }

        private static bool GetDigits(string z, int digits, int minVal, int maxVal, out int val, out string rem)
        {
            val = 0;
            rem = z;
            if (z.Length < digits)
                return false;
            for (int i = 0; i < digits; i++)
            {
                if (!char.IsAsciiDigit(z[i]))
                    return false;
            }

            if (!int.TryParse(z.AsSpan(0, digits), NumberStyles.None, CultureInfo.InvariantCulture, out val))
                return false;
            if (val < minVal || val > maxVal)
                return false;

            rem = z.Substring(digits);
            return true;
        }

        private static bool IsAsciiWhitespace(char c)
            => c is ' ' or '\t' or '\n' or '\r' or '\u000C';
    }

    // SQLite-compatible JSON scalar functions. JSON text keeps an ephemeral subtype while an
    // expression is evaluated, so constructors and mutators embed direct JSON function results.
    // Column affinity strips that subtype before values are stored or later read as column data.
    //
    // The parser is strict RFC-8259. This yields exact parity with SQLite's json_valid()
    // (whose default behavior is strict) and with json()/json_type()/json_extract() for every
    // RFC-8259-conformant input. SQLite additionally accepts non-standard JSON5 leniencies
    // (leading '+', a trailing '.', a leading '.', trailing commas, single quotes, unquoted
    // object keys, hexadecimal, comments, and raw control characters inside strings). Those are
    // deliberately rejected here as "malformed JSON" instead of returning a canonicalized value,
    // matching the task's requirement to reject unsupported input rather than guess.
    private static partial class SqliteJson
    {
        private enum JKind
        {
            Null,
            True,
            False,
            Integer,
            Real,
            Text,
            Array,
            Object,
        }

        private sealed class JMember
        {
            public string RawKey = string.Empty;
            public string Key = string.Empty;
            public JNode Value = null!;
        }

        private sealed class JNode
        {
            public JKind Kind;
            public string Raw = string.Empty; // Verbatim token for numbers and quoted strings.
            public string Str = string.Empty; // Decoded text for Text nodes.
            public List<JNode>? Items;
            public List<JMember>? Members;
        }

        private enum MutationMode
        {
            Set,
            Insert,
            Replace,
        }

        private enum PathStepKind
        {
            Key,
            Index,
            FromEndIndex,
            Append,
        }

        private readonly record struct PathStep(PathStepKind Kind, string? Key, long Index);

        internal static SqlValue Json(IReadOnlyList<SqlValue> args)
        {
            RequireArgumentCount("json", args, 1);
            var value = args[0];
            switch (value.Kind)
            {
                case SqlValueKind.Null:
                    return SqlValue.Null;
                case SqlValueKind.Integer:
                    return SqlValue.JsonText(value.AsInteger().ToString(CultureInfo.InvariantCulture));
                case SqlValueKind.Real:
                    return SqlValue.JsonText(FormatJsonReal(value.AsReal()));
                default:
                    var node = TryParse(InputText(value));
                    if (node is null)
                        throw new EmbeddedSqlException("malformed JSON");
                    return SqlValue.JsonText(Serialize(node));
            }
        }

        internal static SqlValue JsonValid(IReadOnlyList<SqlValue> args)
        {
            RequireArgumentCount("json_valid", args, 1);
            var value = args[0];
            switch (value.Kind)
            {
                case SqlValueKind.Null:
                    return SqlValue.Null;
                case SqlValueKind.Integer:
                case SqlValueKind.Real:
                    return SqlValue.Integer(1);
                default:
                    return SqlValue.Integer(TryParse(InputText(value)) is null ? 0 : 1);
            }
        }

        internal static SqlValue JsonType(IReadOnlyList<SqlValue> args)
        {
            if (args.Count is < 1 or > 2)
                throw new EmbeddedSqlException("wrong number of arguments to function json_type()");

            var value = args[0];
            if (value.Kind == SqlValueKind.Null)
                return SqlValue.Null;

            var root = ParseOrThrow(value);

            if (args.Count == 2)
            {
                var pathArg = args[1];
                if (pathArg.Kind == SqlValueKind.Null)
                    return SqlValue.Null;

                var (found, node) = Navigate(root, RequirePathText(pathArg));
                if (!found)
                    return SqlValue.Null;
                return SqlValue.Text(TypeName(node));
            }

            return SqlValue.Text(TypeName(root));
        }

        internal static SqlValue JsonExtract(IReadOnlyList<SqlValue> args)
        {
            if (args.Count < 1)
                throw new EmbeddedSqlException("wrong number of arguments to function json_extract()");

            var value = args[0];
            if (value.Kind == SqlValueKind.Null)
                return SqlValue.Null;

            var root = ParseOrThrow(value);

            if (args.Count == 1)
                return SqlValue.Null;

            // A NULL anywhere in the path list makes the whole result NULL.
            for (int i = 1; i < args.Count; i++)
            {
                if (args[i].Kind == SqlValueKind.Null)
                    return SqlValue.Null;
            }

            if (args.Count == 2)
            {
                var (found, node) = Navigate(root, RequirePathText(args[1]));
                return found ? NodeToSql(node) : SqlValue.Null;
            }

            var result = new StringBuilder();
            result.Append('[');
            for (int i = 1; i < args.Count; i++)
            {
                if (i > 1)
                    result.Append(',');
                var (found, node) = Navigate(root, RequirePathText(args[i]));
                result.Append(found ? Serialize(node) : "null");
            }

            result.Append(']');
            return SqlValue.JsonText(result.ToString());
        }

        internal static SqlValue JsonArrow(SqlValue value, SqlValue operand, bool textResult)
        {
            if (!TryGetArrowPath(operand, out var path))
                return SqlValue.Null;

            var root = ParseOrThrow(value);
            var (found, node) = Navigate(root, path);
            if (!found)
                return SqlValue.Null;

            if (!textResult)
                return SqlValue.JsonText(Serialize(node));

            return node.Kind is JKind.Array or JKind.Object
                ? SqlValue.Text(Serialize(node))
                : NodeToSql(node);
        }

        internal static SqlValue JsonArray(IReadOnlyList<SqlValue> args)
        {
            var items = new List<JNode>(args.Count);
            for (int i = 0; i < args.Count; i++)
                items.Add(ValueToNode(args[i]));
            return SqlValue.JsonText(Serialize(new JNode { Kind = JKind.Array, Items = items }));
        }

        internal static SqlValue JsonArrayLength(IReadOnlyList<SqlValue> args)
        {
            if (args.Count is < 1 or > 2)
                throw new EmbeddedSqlException("wrong number of arguments to function json_array_length()");
            if (args[0].Kind == SqlValueKind.Null || (args.Count == 2 && args[1].Kind == SqlValueKind.Null))
                return SqlValue.Null;

            var root = ParseOrThrow(args[0]);
            if (args.Count == 2)
            {
                var (found, node) = Navigate(root, RequirePathText(args[1]));
                if (!found)
                    return SqlValue.Null;
                root = node;
            }

            return SqlValue.Integer(root.Kind == JKind.Array ? root.Items!.Count : 0);
        }

        internal static SqlValue JsonObject(IReadOnlyList<SqlValue> args)
        {
            if ((args.Count & 1) != 0)
                throw new EmbeddedSqlException("json_object() requires an even number of arguments");

            var members = new List<JMember>(args.Count / 2);
            for (int i = 0; i < args.Count; i += 2)
            {
                if (args[i].Kind != SqlValueKind.Text)
                    throw new EmbeddedSqlException("json_object() labels must be TEXT");

                string key = args[i].AsText();
                members.Add(new JMember
                {
                    RawKey = QuoteString(key),
                    Key = key,
                    Value = ValueToNode(args[i + 1]),
                });
            }

            return SqlValue.JsonText(Serialize(new JNode { Kind = JKind.Object, Members = members }));
        }

        internal static SqlValue JsonQuote(IReadOnlyList<SqlValue> args)
        {
            RequireArgumentCount("json_quote", args, 1);
            return SqlValue.JsonText(Serialize(ValueToNode(args[0])));
        }

        internal static SqlValue JsonPretty(IReadOnlyList<SqlValue> args)
        {
            if (args.Count is < 1 or > 2)
                throw new EmbeddedSqlException("wrong number of arguments to function json_pretty()");
            if (args[0].Kind == SqlValueKind.Null)
                return SqlValue.Null;

            var indent = args.Count == 2 && args[1].Kind != SqlValueKind.Null
                ? ToSqlText(args[1])
                : "    ";
            var builder = new StringBuilder();
            SerializePretty(ParseOrThrow(args[0]), builder, indent, 0);
            return SqlValue.Text(builder.ToString());
        }

        private static void SerializePretty(JNode node, StringBuilder sb, string indent, int depth)
        {
            switch (node.Kind)
            {
                case JKind.Array:
                    // SQLite renders an empty container inline rather than across three lines.
                    if (node.Items!.Count == 0)
                    {
                        sb.Append("[]");
                        break;
                    }

                    sb.Append('[');
                    for (int i = 0; i < node.Items.Count; i++)
                    {
                        if (i > 0)
                            sb.Append(',');
                        sb.Append('\n');
                        AppendIndent(sb, indent, depth + 1);
                        SerializePretty(node.Items[i], sb, indent, depth + 1);
                    }

                    sb.Append('\n');
                    AppendIndent(sb, indent, depth);
                    sb.Append(']');
                    break;
                case JKind.Object:
                    if (node.Members!.Count == 0)
                    {
                        sb.Append("{}");
                        break;
                    }

                    sb.Append('{');
                    for (int i = 0; i < node.Members.Count; i++)
                    {
                        if (i > 0)
                            sb.Append(',');
                        sb.Append('\n');
                        AppendIndent(sb, indent, depth + 1);
                        sb.Append(node.Members[i].RawKey);
                        sb.Append(": ");
                        SerializePretty(node.Members[i].Value, sb, indent, depth + 1);
                    }

                    sb.Append('\n');
                    AppendIndent(sb, indent, depth);
                    sb.Append('}');
                    break;
                default:
                    Serialize(node, sb);
                    break;
            }
        }

        private static void AppendIndent(StringBuilder sb, string indent, int depth)
        {
            for (int i = 0; i < depth; i++)
                sb.Append(indent);
        }

        internal static SqlValue JsonErrorPosition(IReadOnlyList<SqlValue> args)
        {
            RequireArgumentCount("json_error_position", args, 1);
            if (args[0].Kind == SqlValueKind.Null)
                return SqlValue.Null;

            string input = args[0].Kind switch
            {
                SqlValueKind.Integer => args[0].AsInteger().ToString(CultureInfo.InvariantCulture),
                SqlValueKind.Real => FormatJsonReal(args[0].AsReal()),
                _ => InputText(args[0]),
            };
            return SqlValue.Integer(ParseErrorPosition(input));
        }

        internal static SqlValue JsonRemove(IReadOnlyList<SqlValue> args)
        {
            if (args.Count < 1)
                throw new EmbeddedSqlException("wrong number of arguments to function json_remove()");
            if (args[0].Kind == SqlValueKind.Null)
                return SqlValue.Null;

            var root = ParseOrThrow(args[0]);
            for (int i = 1; i < args.Count; i++)
            {
                if (args[i].Kind == SqlValueKind.Null)
                    return SqlValue.Null;

                string path = RequirePathText(args[i]);
                var (found, _) = Navigate(root, path);
                if (!found)
                    continue;

                var steps = ParsePath(path);
                if (steps.Count == 0)
                    return SqlValue.Null;
                Remove(root, steps);
            }

            return SqlValue.JsonText(Serialize(root));
        }

        internal static SqlValue JsonSet(IReadOnlyList<SqlValue> args)
            => JsonModify(args, MutationMode.Set, "json_set");

        internal static SqlValue JsonInsert(IReadOnlyList<SqlValue> args)
            => JsonModify(args, MutationMode.Insert, "json_insert");

        internal static SqlValue JsonReplace(IReadOnlyList<SqlValue> args)
            => JsonModify(args, MutationMode.Replace, "json_replace");

        internal static SqlValue JsonPatch(IReadOnlyList<SqlValue> args)
        {
            RequireArgumentCount("json_patch", args, 2);
            if (args[0].Kind == SqlValueKind.Null || args[1].Kind == SqlValueKind.Null)
                return SqlValue.Null;

            return SqlValue.JsonText(Serialize(MergePatch(ParseOrThrow(args[0]), ParseOrThrow(args[1]))));
        }

        private static SqlValue JsonModify(
            IReadOnlyList<SqlValue> args,
            MutationMode mode,
            string functionName)
        {
            if ((args.Count & 1) == 0)
                throw new EmbeddedSqlException($"wrong number of arguments to function {functionName}()");
            if (args[0].Kind == SqlValueKind.Null)
                return SqlValue.Null;

            var root = ParseOrThrow(args[0]);
            for (int i = 1; i < args.Count; i += 2)
            {
                if (args[i].Kind == SqlValueKind.Null)
                    continue;

                var value = ValueToNode(args[i + 1]);
                string path = RequirePathText(args[i]);

                if (mode == MutationMode.Replace)
                {
                    var (found, _) = Navigate(root, path);
                    if (!found)
                        continue;
                }

                List<PathStep> steps;
                try
                {
                    steps = ParsePath(path);
                }
                catch (EmbeddedSqlException)
                {
                    if (mode != MutationMode.Replace && MutationPathCannotReachValue(root, path, mode))
                        continue;
                    throw;
                }

                var candidate = Clone(root);
                if (TryModify(ref candidate, steps, value, mode))
                    root = candidate;
            }

            return SqlValue.JsonText(Serialize(root));
        }

        private static JNode ValueToNode(SqlValue value)
        {
            if (value.IsJson)
                return ParseOrThrow(value);

            return value.Kind switch
            {
                SqlValueKind.Null => new JNode { Kind = JKind.Null },
                SqlValueKind.Integer => new JNode
                {
                    Kind = JKind.Integer,
                    Raw = value.AsInteger().ToString(CultureInfo.InvariantCulture),
                },
                SqlValueKind.Real => new JNode
                {
                    Kind = JKind.Real,
                    Raw = FormatJsonValueReal(value.AsReal()),
                },
                SqlValueKind.Text => new JNode
                {
                    Kind = JKind.Text,
                    Raw = QuoteString(value.AsText()),
                    Str = value.AsText(),
                },
                SqlValueKind.Blob => throw new EmbeddedSqlException("JSON cannot hold BLOB values"),
                _ => throw new InvalidOperationException(),
            };
        }

        private static List<PathStep> ParsePath(string path)
        {
            if (path.Length == 0 || path[0] != '$')
                throw BadPath(path);

            var steps = new List<PathStep>();
            int i = 1;
            while (i < path.Length)
            {
                if (path[i] == '.')
                {
                    i++;
                    string key;
                    if (i < path.Length && path[i] == '"')
                    {
                        var parser = new Parser(path, i);
                        var node = parser.ParseString();
                        if (node is null)
                            throw BadPath(path);
                        i = parser.Pos;
                        key = node.Str;
                    }
                    else
                    {
                        int start = i;
                        while (i < path.Length && path[i] != '.' && path[i] != '[')
                            i++;
                        if (i == start)
                            throw BadPath(path);
                        key = path.Substring(start, i - start);
                    }

                    steps.Add(new PathStep(PathStepKind.Key, key, 0));
                    continue;
                }

                if (path[i] != '[')
                    throw BadPath(path);

                i++;
                if (i < path.Length && path[i] == '#')
                {
                    i++;
                    if (i < path.Length && path[i] == ']')
                    {
                        i++;
                        steps.Add(new PathStep(PathStepKind.Append, null, 0));
                        continue;
                    }

                    if (i >= path.Length || path[i] != '-')
                        throw BadPath(path);
                    i++;
                    if (!ReadDigits(path, ref i, out long index) || i >= path.Length || path[i] != ']')
                        throw BadPath(path);
                    i++;
                    steps.Add(new PathStep(PathStepKind.FromEndIndex, null, index));
                    continue;
                }

                if (!ReadDigits(path, ref i, out long absolute) || i >= path.Length || path[i] != ']')
                    throw BadPath(path);
                i++;
                steps.Add(new PathStep(PathStepKind.Index, null, absolute));
            }

            return steps;
        }

        private static bool MutationPathCannotReachValue(JNode root, string path, MutationMode mode)
        {
            if (path.Length == 0 || path[0] != '$')
                throw BadPath(path);

            JNode current = root;
            int i = 1;
            while (i < path.Length)
            {
                if (path[i] == '.')
                {
                    i++;
                    string key;
                    if (i < path.Length && path[i] == '"')
                    {
                        var parser = new Parser(path, i);
                        var node = parser.ParseString();
                        if (node is null)
                            throw BadPath(path);
                        i = parser.Pos;
                        key = node.Str;
                    }
                    else
                    {
                        int start = i;
                        while (i < path.Length && path[i] != '.' && path[i] != '[')
                            i++;
                        if (i == start)
                            throw BadPath(path);
                        key = path.Substring(start, i - start);
                    }

                    if (current.Kind != JKind.Object)
                        return true;
                    int memberIndex = FindMemberIndex(current, key);
                    if (memberIndex < 0)
                        return false;
                    current = current.Members![memberIndex].Value;
                    continue;
                }

                if (path[i] != '[')
                    throw BadPath(path);
                if (current.Kind != JKind.Array)
                    return true;

                i++;
                PathStep step;
                if (i < path.Length && path[i] == '#')
                {
                    i++;
                    if (i < path.Length && path[i] == ']')
                    {
                        i++;
                        step = new PathStep(PathStepKind.Append, null, 0);
                    }
                    else
                    {
                        if (i >= path.Length || path[i] != '-')
                            throw BadPath(path);
                        i++;
                        if (!ReadDigits(path, ref i, out long index) || i >= path.Length || path[i] != ']')
                            throw BadPath(path);
                        i++;
                        step = new PathStep(PathStepKind.FromEndIndex, null, index);
                    }
                }
                else
                {
                    if (!ReadDigits(path, ref i, out long absolute) || i >= path.Length || path[i] != ']')
                        throw BadPath(path);
                    i++;
                    step = new PathStep(PathStepKind.Index, null, absolute);
                }

                long arrayIndex = ResolveArrayIndex(current.Items!.Count, step);
                if (arrayIndex >= 0 && arrayIndex < current.Items.Count)
                {
                    current = current.Items[(int)arrayIndex];
                    continue;
                }

                return mode != MutationMode.Replace && arrayIndex != current.Items.Count;
            }

            return false;
        }

        private static bool TryModify(ref JNode root, IReadOnlyList<PathStep> steps, JNode value, MutationMode mode)
        {
            if (steps.Count == 0)
            {
                if (mode == MutationMode.Insert)
                    return false;
                root = Clone(value);
                return true;
            }

            JNode current = root;
            for (int i = 0; i < steps.Count - 1; i++)
            {
                var step = steps[i];
                var next = steps[i + 1];
                if (step.Kind == PathStepKind.Key)
                {
                    if (current.Kind != JKind.Object)
                        return false;

                    int memberIndex = FindMemberIndex(current, step.Key!);
                    if (memberIndex >= 0)
                    {
                        current = current.Members![memberIndex].Value;
                        continue;
                    }

                    if (mode == MutationMode.Replace)
                        return false;

                    var created = ContainerFor(next);
                    current.Members!.Add(new JMember
                    {
                        RawKey = QuoteString(step.Key!),
                        Key = step.Key!,
                        Value = created,
                    });
                    current = created;
                    continue;
                }

                if (current.Kind != JKind.Array)
                    return false;

                long index = ResolveArrayIndex(current.Items!.Count, step);
                if (index >= 0 && index < current.Items.Count)
                {
                    current = current.Items[(int)index];
                    continue;
                }

                if (mode == MutationMode.Replace || index != current.Items.Count)
                    return false;

                var appended = ContainerFor(next);
                current.Items.Add(appended);
                current = appended;
            }

            var final = steps[^1];
            if (final.Kind == PathStepKind.Key)
            {
                if (current.Kind != JKind.Object)
                    return false;

                int memberIndex = FindMemberIndex(current, final.Key!);
                if (memberIndex >= 0)
                {
                    if (mode == MutationMode.Insert)
                        return false;
                    current.Members![memberIndex].Value = Clone(value);
                    return true;
                }

                if (mode == MutationMode.Replace)
                    return false;
                current.Members!.Add(new JMember
                {
                    RawKey = QuoteString(final.Key!),
                    Key = final.Key!,
                    Value = Clone(value),
                });
                return true;
            }

            if (current.Kind != JKind.Array)
                return false;

            long arrayIndex = ResolveArrayIndex(current.Items!.Count, final);
            if (arrayIndex >= 0 && arrayIndex < current.Items.Count)
            {
                if (mode == MutationMode.Insert)
                    return false;
                current.Items[(int)arrayIndex] = Clone(value);
                return true;
            }

            if (mode == MutationMode.Replace || arrayIndex != current.Items.Count)
                return false;
            current.Items.Add(Clone(value));
            return true;
        }

        private static void Remove(JNode root, IReadOnlyList<PathStep> steps)
        {
            JNode current = root;
            for (int i = 0; i < steps.Count - 1; i++)
            {
                var step = steps[i];
                if (step.Kind == PathStepKind.Key)
                {
                    if (current.Kind != JKind.Object)
                        return;
                    int memberIndex = FindMemberIndex(current, step.Key!);
                    if (memberIndex < 0)
                        return;
                    current = current.Members![memberIndex].Value;
                    continue;
                }

                if (current.Kind != JKind.Array)
                    return;
                long index = ResolveArrayIndex(current.Items!.Count, step);
                if (index < 0 || index >= current.Items.Count)
                    return;
                current = current.Items[(int)index];
            }

            var final = steps[^1];
            if (final.Kind == PathStepKind.Key)
            {
                if (current.Kind != JKind.Object)
                    return;
                int memberIndex = FindMemberIndex(current, final.Key!);
                if (memberIndex >= 0)
                    current.Members!.RemoveAt(memberIndex);
                return;
            }

            if (current.Kind != JKind.Array)
                return;
            long arrayIndex = ResolveArrayIndex(current.Items!.Count, final);
            if (arrayIndex >= 0 && arrayIndex < current.Items.Count)
                current.Items.RemoveAt((int)arrayIndex);
        }

        private static JNode MergePatch(JNode target, JNode patch)
        {
            if (patch.Kind != JKind.Object)
                return Clone(patch);

            var merged = target.Kind == JKind.Object
                ? Clone(target)
                : new JNode { Kind = JKind.Object, Members = [] };
            foreach (var patchMember in patch.Members!)
            {
                int targetIndex = FindMemberIndex(merged, patchMember.Key);
                if (patchMember.Value.Kind == JKind.Null)
                {
                    if (targetIndex >= 0)
                        merged.Members!.RemoveAt(targetIndex);
                    continue;
                }

                var value = targetIndex >= 0
                    ? MergePatch(merged.Members![targetIndex].Value, patchMember.Value)
                    : MergePatch(new JNode { Kind = JKind.Object, Members = [] }, patchMember.Value);
                if (targetIndex >= 0)
                    merged.Members![targetIndex].Value = value;
                else
                    merged.Members!.Add(new JMember
                    {
                        RawKey = patchMember.RawKey,
                        Key = patchMember.Key,
                        Value = value,
                    });
            }

            return merged;
        }

        private static long ResolveArrayIndex(int length, PathStep step)
        {
            return step.Kind switch
            {
                PathStepKind.Index => step.Index,
                PathStepKind.FromEndIndex => (long)length - step.Index,
                PathStepKind.Append => length,
                _ => throw new InvalidOperationException(),
            };
        }

        private static int FindMemberIndex(JNode node, string key)
        {
            for (int i = 0; i < node.Members!.Count; i++)
            {
                if (string.Equals(node.Members[i].Key, key, StringComparison.Ordinal))
                    return i;
            }

            return -1;
        }

        private static JNode ContainerFor(PathStep next)
            => next.Kind == PathStepKind.Key
                ? new JNode { Kind = JKind.Object, Members = [] }
                : new JNode { Kind = JKind.Array, Items = [] };

        private static JNode Clone(JNode node)
        {
            var clone = new JNode
            {
                Kind = node.Kind,
                Raw = node.Raw,
                Str = node.Str,
            };
            if (node.Items is not null)
                clone.Items = node.Items.Select(Clone).ToList();
            if (node.Members is not null)
            {
                clone.Members = node.Members.Select(member => new JMember
                {
                    RawKey = member.RawKey,
                    Key = member.Key,
                    Value = Clone(member.Value),
                }).ToList();
            }

            return clone;
        }

        private static string QuoteString(string value)
        {
            var sb = new StringBuilder(value.Length + 2);
            sb.Append('"');
            foreach (char c in value)
            {
                switch (c)
                {
                    case '"':
                        sb.Append("\\\"");
                        break;
                    case '\\':
                        sb.Append("\\\\");
                        break;
                    case '\b':
                        sb.Append("\\b");
                        break;
                    case '\f':
                        sb.Append("\\f");
                        break;
                    case '\n':
                        sb.Append("\\n");
                        break;
                    case '\r':
                        sb.Append("\\r");
                        break;
                    case '\t':
                        sb.Append("\\t");
                        break;
                    default:
                        if (c < 0x20)
                            sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                        else
                            sb.Append(c);
                        break;
                }
            }

            sb.Append('"');
            return sb.ToString();
        }

        private static string FormatJsonValueReal(double d)
        {
            if (double.IsPositiveInfinity(d))
                return "9.0e+999";
            if (double.IsNegativeInfinity(d))
                return "-9.0e+999";
            return FormatJsonReal(d);
        }

        private static JNode ParseOrThrow(SqlValue value)
        {
            var node = value.Kind switch
            {
                SqlValueKind.Integer => TryParse(value.AsInteger().ToString(CultureInfo.InvariantCulture)),
                SqlValueKind.Real => TryParse(FormatJsonReal(value.AsReal())),
                _ => TryParse(InputText(value)),
            };

            if (node is null)
                throw new EmbeddedSqlException("malformed JSON");
            return node;
        }

        private static string InputText(SqlValue value)
            => value.Kind == SqlValueKind.Blob
                ? Encoding.UTF8.GetString(value.AsBlob().Span)
                : value.AsText();

        private static string RequirePathText(SqlValue value)
            => value.Kind switch
            {
                SqlValueKind.Text => value.AsText(),
                SqlValueKind.Blob => Encoding.UTF8.GetString(value.AsBlob().Span),
                SqlValueKind.Integer => value.AsInteger().ToString(CultureInfo.InvariantCulture),
                SqlValueKind.Real => value.AsReal().ToString("R", CultureInfo.InvariantCulture),
                _ => string.Empty,
            };

        private static bool TryGetArrowPath(SqlValue value, out string path)
        {
            switch (value.Kind)
            {
                case SqlValueKind.Integer:
                    {
                        var index = value.AsInteger();
                        path = index >= 0
                            ? $"$[{index}]"
                            : $"$[#{index}]";
                        return true;
                    }
                case SqlValueKind.Text:
                    {
                        var nameOrPath = value.AsText();
                        path = nameOrPath.Length == 0 || nameOrPath.StartsWith('$')
                            ? nameOrPath
                            : "$." + QuoteString(nameOrPath);
                        return true;
                    }
                default:
                    path = string.Empty;
                    return false;
            }
        }

        private static string TypeName(JNode node) => node.Kind switch
        {
            JKind.Null => "null",
            JKind.True => "true",
            JKind.False => "false",
            JKind.Integer => "integer",
            JKind.Real => "real",
            JKind.Text => "text",
            JKind.Array => "array",
            JKind.Object => "object",
            _ => throw new InvalidOperationException(),
        };

        private static SqlValue NodeToSql(JNode node)
        {
            switch (node.Kind)
            {
                case JKind.Null:
                    return SqlValue.Null;
                case JKind.True:
                    return SqlValue.Integer(1);
                case JKind.False:
                    return SqlValue.Integer(0);
                case JKind.Integer:
                    if (long.TryParse(node.Raw, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out long l))
                        return SqlValue.Integer(l);
                    return SqlValue.Real(ParseDouble(node.Raw));
                case JKind.Real:
                    return SqlValue.Real(ParseDouble(node.Raw));
                case JKind.Text:
                    return SqlValue.Text(node.Str);
                default:
                    return SqlValue.JsonText(Serialize(node));
            }
        }

        private static double ParseDouble(string raw)
            => double.Parse(raw, NumberStyles.Float, CultureInfo.InvariantCulture);

        private static string Serialize(JNode node)
        {
            var sb = new StringBuilder();
            Serialize(node, sb);
            return sb.ToString();
        }

        private static void Serialize(JNode node, StringBuilder sb)
        {
            switch (node.Kind)
            {
                case JKind.Null:
                    sb.Append("null");
                    break;
                case JKind.True:
                    sb.Append("true");
                    break;
                case JKind.False:
                    sb.Append("false");
                    break;
                case JKind.Integer:
                case JKind.Real:
                case JKind.Text:
                    sb.Append(node.Raw);
                    break;
                case JKind.Array:
                    sb.Append('[');
                    for (int i = 0; i < node.Items!.Count; i++)
                    {
                        if (i > 0)
                            sb.Append(',');
                        Serialize(node.Items[i], sb);
                    }

                    sb.Append(']');
                    break;
                case JKind.Object:
                    sb.Append('{');
                    for (int i = 0; i < node.Members!.Count; i++)
                    {
                        if (i > 0)
                            sb.Append(',');
                        sb.Append(node.Members[i].RawKey);
                        sb.Append(':');
                        Serialize(node.Members[i].Value, sb);
                    }

                    sb.Append('}');
                    break;
            }
        }

        private static (bool Found, JNode Node) Navigate(JNode root, string path)
        {
            if (path.Length == 0 || path[0] != '$')
                throw BadPath(path);

            JNode current = root;
            int i = 1;
            while (i < path.Length)
            {
                char c = path[i];
                if (c == '.')
                {
                    i++;
                    string keyName;
                    if (i < path.Length && path[i] == '"')
                    {
                        var parser = new Parser(path, i);
                        var strNode = parser.ParseString();
                        if (strNode is null)
                            throw BadPath(path);
                        i = parser.Pos;
                        keyName = strNode.Str;
                    }
                    else
                    {
                        int start = i;
                        while (i < path.Length && path[i] != '.' && path[i] != '[')
                            i++;
                        if (i == start)
                            throw BadPath(path);
                        keyName = path.Substring(start, i - start);
                    }

                    // The label is validated syntactically above: SQLite rejects an empty label
                    // (e.g. "$.") as a bad path even when the current node is not an object. Only a
                    // syntactically valid label against a non-object degrades to "not found".
                    if (current.Kind != JKind.Object)
                        return (false, root);

                    JNode? match = null;
                    foreach (var member in current.Members!)
                    {
                        if (string.Equals(member.Key, keyName, StringComparison.Ordinal))
                        {
                            match = member.Value;
                            break;
                        }
                    }

                    if (match is null)
                        return (false, root);
                    current = match;
                }
                else if (c == '[')
                {
                    // SQLite checks the container type before parsing the subscript: a '[' step
                    // against a non-array yields "not found" (NULL) without validating the bracket
                    // contents, whereas an invalid subscript on an array is a hard "bad path" error.
                    if (current.Kind != JKind.Array)
                        return (false, root);

                    i++;
                    long length = current.Items!.Count;
                    bool fromEnd = false;
                    long value;
                    if (i < path.Length && path[i] == '#')
                    {
                        fromEnd = true;
                        i++;
                        if (i < path.Length && path[i] == '-')
                        {
                            i++;
                            if (!ReadDigits(path, ref i, out value))
                                throw BadPath(path);
                        }
                        else
                        {
                            value = 0;
                        }
                    }
                    else if (i < path.Length && char.IsAsciiDigit(path[i]))
                    {
                        if (!ReadDigits(path, ref i, out value))
                            throw BadPath(path);
                    }
                    else
                    {
                        throw BadPath(path);
                    }

                    if (i >= path.Length || path[i] != ']')
                        throw BadPath(path);
                    i++;

                    long actual = fromEnd ? length - value : value;
                    if (actual < 0 || actual >= length)
                        return (false, root);
                    current = current.Items[(int)actual];
                }
                else
                {
                    throw BadPath(path);
                }
            }

            return (true, current);
        }

        private static bool ReadDigits(string s, ref int i, out long value)
        {
            int start = i;
            long acc = 0;
            while (i < s.Length && char.IsAsciiDigit(s[i]))
            {
                if (acc < 100000000000000000L)
                    acc = acc * 10 + (s[i] - '0');
                i++;
            }

            value = acc;
            return i > start;
        }

        private static EmbeddedSqlException BadPath(string path)
            => new($"bad JSON path: '{path}'");

        private static string FormatJsonReal(double d)
        {
            if (double.IsNaN(d))
                return "null";
            if (double.IsPositiveInfinity(d))
                return "9e999";
            if (double.IsNegativeInfinity(d))
                return "-9e999";
            if (d == 0.0)
                return "0.0";

            string s = d.ToString("G15", CultureInfo.InvariantCulture);
            int e = s.IndexOfAny(new[] { 'e', 'E' });
            if (e >= 0)
            {
                string mantissa = s.Substring(0, e);
                string exponent = s.Substring(e + 1);
                char sign = '+';
                if (exponent.StartsWith('+') || exponent.StartsWith('-'))
                {
                    sign = exponent[0];
                    exponent = exponent.Substring(1);
                }

                exponent = exponent.TrimStart('0');
                if (exponent.Length < 2)
                    exponent = exponent.PadLeft(2, '0');
                if (!mantissa.Contains('.'))
                    mantissa += ".0";
                return mantissa + "e" + sign + exponent;
            }

            if (!s.Contains('.'))
                s += ".0";
            return s;
        }

        private static int ParseErrorPosition(string input)
        {
            var parser = new Parser(input, 0);
            parser.SkipWs();
            int rootStart = parser.Pos;
            var node = parser.ParseValue();
            if (node is not null)
            {
                parser.SkipWs();
                if (parser.AtEnd)
                    return 0;
            }

            return parser.ErrorPosition >= 0 ? parser.ErrorPosition + 1 : rootStart + 1;
        }

        private static JNode? TryParse(string s)
        {
            var parser = new Parser(s, 0);
            parser.SkipWs();
            var node = parser.ParseValue();
            if (node is null)
                return null;
            parser.SkipWs();
            return parser.AtEnd ? node : null;
        }

        private sealed class Parser
        {
            private readonly string _s;
            private int _i;
            private int _errorPosition = -1;

            public Parser(string s, int start)
            {
                _s = s;
                _i = start;
            }

            public int Pos => _i;

            public bool AtEnd => _i >= _s.Length;

            public int ErrorPosition => _errorPosition;

            public void SkipWs()
            {
                while (_i < _s.Length)
                {
                    char c = _s[_i];
                    if (c is ' ' or '\t' or '\n' or '\r')
                        _i++;
                    else
                        break;
                }
            }

            public JNode? ParseValue()
            {
                if (_i >= _s.Length)
                {
                    RecordFailure();
                    return null;
                }

                char c = _s[_i];
                switch (c)
                {
                    case '{':
                        return ParseObject();
                    case '[':
                        return ParseArray();
                    case '"':
                        return ParseString();
                    case 't':
                        return ParseLiteral("true", JKind.True);
                    case 'f':
                        return ParseLiteral("false", JKind.False);
                    case 'n':
                        return ParseLiteral("null", JKind.Null);
                    default:
                        if (c == '-' || char.IsAsciiDigit(c))
                            return ParseNumber();
                        RecordFailure();
                        return null;
                }
            }

            private JNode? ParseLiteral(string literal, JKind kind)
            {
                int start = _i;
                if (_i + literal.Length > _s.Length)
                {
                    RecordFailure(start);
                    return null;
                }
                if (string.CompareOrdinal(_s, _i, literal, 0, literal.Length) != 0)
                {
                    RecordFailure(start);
                    return null;
                }
                _i += literal.Length;
                return new JNode { Kind = kind };
            }

            private JNode? ParseNumber()
            {
                int start = _i;
                if (_i < _s.Length && _s[_i] == '-')
                    _i++;

                if (_i >= _s.Length)
                {
                    RecordFailure();
                    return null;
                }

                if (_s[_i] == '0')
                {
                    _i++;
                }
                else if (_s[_i] is >= '1' and <= '9')
                {
                    while (_i < _s.Length && char.IsAsciiDigit(_s[_i]))
                        _i++;
                }
                else
                {
                    RecordFailure();
                    return null;
                }

                bool isReal = false;
                if (_i < _s.Length && _s[_i] == '.')
                {
                    isReal = true;
                    _i++;
                    if (_i >= _s.Length || !char.IsAsciiDigit(_s[_i]))
                    {
                        RecordFailure();
                        return null;
                    }
                    while (_i < _s.Length && char.IsAsciiDigit(_s[_i]))
                        _i++;
                }

                if (_i < _s.Length && (_s[_i] == 'e' || _s[_i] == 'E'))
                {
                    isReal = true;
                    _i++;
                    if (_i < _s.Length && (_s[_i] == '+' || _s[_i] == '-'))
                        _i++;
                    if (_i >= _s.Length || !char.IsAsciiDigit(_s[_i]))
                    {
                        RecordFailure();
                        return null;
                    }
                    while (_i < _s.Length && char.IsAsciiDigit(_s[_i]))
                        _i++;
                }

                string raw = _s.Substring(start, _i - start);
                return new JNode { Kind = isReal ? JKind.Real : JKind.Integer, Raw = raw };
            }

            public JNode? ParseString()
            {
                if (_i >= _s.Length || _s[_i] != '"')
                {
                    RecordFailure();
                    return null;
                }

                int start = _i;
                _i++;
                var sb = new StringBuilder();
                while (true)
                {
                    if (_i >= _s.Length)
                    {
                        RecordFailure();
                        return null;
                    }

                    char c = _s[_i];
                    if (c == '"')
                    {
                        _i++;
                        break;
                    }

                    if (c == '\\')
                    {
                        _i++;
                        if (_i >= _s.Length)
                        {
                            RecordFailure();
                            return null;
                        }
                        char escaped = _s[_i];
                        switch (escaped)
                        {
                            case '"':
                                sb.Append('"');
                                break;
                            case '\\':
                                sb.Append('\\');
                                break;
                            case '/':
                                sb.Append('/');
                                break;
                            case 'b':
                                sb.Append('\b');
                                break;
                            case 'f':
                                sb.Append('\f');
                                break;
                            case 'n':
                                sb.Append('\n');
                                break;
                            case 'r':
                                sb.Append('\r');
                                break;
                            case 't':
                                sb.Append('\t');
                                break;
                            case 'u':
                                if (_i + 4 >= _s.Length)
                                {
                                    RecordFailure();
                                    return null;
                                }
                                int cp = 0;
                                for (int k = 1; k <= 4; k++)
                                {
                                    int digit = HexValue(_s[_i + k]);
                                    if (digit < 0)
                                    {
                                        RecordFailure(_i + k);
                                        return null;
                                    }
                                    cp = (cp * 16) + digit;
                                }

                                sb.Append((char)cp);
                                _i += 4;
                                break;
                            default:
                                RecordFailure();
                                return null;
                        }

                        _i++;
                    }
                    else if (c < 0x20)
                    {
                        RecordFailure();
                        return null;
                    }
                    else
                    {
                        sb.Append(c);
                        _i++;
                    }
                }

                string raw = _s.Substring(start, _i - start);
                return new JNode { Kind = JKind.Text, Raw = raw, Str = sb.ToString() };
            }

            private JNode? ParseArray()
            {
                _i++;
                var items = new List<JNode>();
                SkipWs();
                if (_i < _s.Length && _s[_i] == ']')
                {
                    _i++;
                    return new JNode { Kind = JKind.Array, Items = items };
                }

                while (true)
                {
                    SkipWs();
                    var v = ParseValue();
                    if (v is null)
                        return null;
                    items.Add(v);
                    SkipWs();
                    if (_i >= _s.Length)
                    {
                        RecordFailure();
                        return null;
                    }
                    char c = _s[_i];
                    if (c == ',')
                    {
                        _i++;
                        continue;
                    }

                    if (c == ']')
                    {
                        _i++;
                        break;
                    }

                    RecordFailure();
                    return null;
                }

                return new JNode { Kind = JKind.Array, Items = items };
            }

            private JNode? ParseObject()
            {
                _i++;
                var members = new List<JMember>();
                SkipWs();
                if (_i < _s.Length && _s[_i] == '}')
                {
                    _i++;
                    return new JNode { Kind = JKind.Object, Members = members };
                }

                while (true)
                {
                    SkipWs();
                    if (_i >= _s.Length || _s[_i] != '"')
                    {
                        RecordFailure();
                        return null;
                    }
                    var key = ParseString();
                    if (key is null)
                        return null;
                    SkipWs();
                    if (_i >= _s.Length || _s[_i] != ':')
                    {
                        RecordFailure();
                        return null;
                    }
                    _i++;
                    SkipWs();
                    var v = ParseValue();
                    if (v is null)
                        return null;
                    members.Add(new JMember { RawKey = key.Raw, Key = key.Str, Value = v });
                    SkipWs();
                    if (_i >= _s.Length)
                    {
                        RecordFailure();
                        return null;
                    }
                    char c = _s[_i];
                    if (c == ',')
                    {
                        _i++;
                        continue;
                    }

                    if (c == '}')
                    {
                        _i++;
                        break;
                    }

                    RecordFailure();
                    return null;
                }

                return new JNode { Kind = JKind.Object, Members = members };
            }

            public void RecordFailure()
            {
                RecordFailure(_i);
            }

            private void RecordFailure(int position)
            {
                if (_errorPosition < 0)
                    _errorPosition = position;
            }

            private static int HexValue(char c) => c switch
            {
                >= '0' and <= '9' => c - '0',
                >= 'a' and <= 'f' => c - 'a' + 10,
                >= 'A' and <= 'F' => c - 'A' + 10,
                _ => -1,
            };
        }
    }
}

public sealed class EmbeddedConnection : IDisposable
{
    private const int MaximumAttachedDatabases = 10;
    private const char UnqualifiedSchemaMarker = '\0';
    private readonly EmbeddedDatabase _database;
    private EmbeddedDatabase _tempDatabase;
    private readonly Dictionary<string, AttachedDatabase> _attachedDatabases = new(StringComparer.OrdinalIgnoreCase);
    private readonly object _statementReaderGate = new();
    private readonly HashSet<ConnectionStatementReaderLease> _statementReaders = [];
    private Dictionary<EmbeddedDatabase, TransactionDatabaseState>? _transactionDatabases;
    private EmbeddedDatabase? _transactionWriteDatabase;
    private EmbeddedDatabase? _transactionMutationDatabase;
    private EmbeddedDatabase? _autocommitWriteReservation;
    private readonly List<EmbeddedDatabase> _writeReservations = [];
    private bool _transactionOpenedBySavepoint;
    private readonly List<SavepointEntry> _savepoints = [];
    private long _lastInsertRowId;
    private bool _queryOnly;
    private bool _foreignKeys;
    private bool _deferForeignKeys;
    private bool _recursiveTriggers;
    private bool _tempInitialized;
    private readonly Dictionary<EmbeddedDatabase, int> _pendingPageSizes = [];
    private readonly ManagedConnectionHooks _hooks = new();
    private bool _insideHookCallback;
    private bool _disposed;
    private TimeSpan _busyTimeout = TimeSpan.Zero;

    /// <summary>
    /// How long contended transaction-lock acquisitions wait for a competing
    /// connection to release before reporting busy, mirroring
    /// <c>sqlite3_busy_timeout</c> per connection. The default of zero preserves
    /// SQLite's fail-fast default.
    /// </summary>
    internal TimeSpan BusyTimeout
    {
        get => _busyTimeout;
        set
        {
            _busyTimeout = value;
            // The main database needs the timeout so its autocommit retry loop
            // and stale-snapshot waits can honor it; attached databases keep the
            // fail-fast default.
            _database.BusyTimeout = value;
        }
    }

    /// <summary>
    /// Tracks one outer statement's use of connection-private temp triggers. Temp triggers live in
    /// a separate in-memory database, so firing one for a main-schema table means handing it to the
    /// main database, and a body statement may target yet another schema. Those cross-schema writes
    /// run against a working copy of the target catalog that is published only after the statement
    /// that fired the trigger succeeds, mirroring how a local statement is rolled back on failure.
    /// </summary>
    private sealed class TempTriggerSession(EmbeddedConnection connection, EmbeddedDatabase executing)
    {
        private readonly Dictionary<ParsedStatement, RoutedStatement> _routes =
            new(ReferenceEqualityComparer.Instance);
        private readonly Dictionary<EmbeddedDatabase, ForeignWrite> _foreignWrites = [];

        private sealed class ForeignWrite(EmbeddedDatabase.SchemaCatalog catalog)
        {
            public EmbeddedDatabase.SchemaCatalog Catalog { get; } = catalog;

            public bool Changed { get; set; }

            public bool ForceFullCatalogRewrite { get; set; }
        }

        public bool IsForeign(ParsedStatement statement)
            => !ReferenceEquals(Resolve(statement).Database, executing);

        public ParsedStatement Localize(ParsedStatement statement) => Resolve(statement).Statement;

        public ExecutionResult ExecuteForeign(
            ParsedStatement statement,
            EmbeddedDatabase.QueryContext outer)
        {
            var route = Resolve(statement);
            if (!_foreignWrites.TryGetValue(route.Database, out var write))
            {
                var transaction = connection.GetTransactionState(route.Database);
                write = new ForeignWrite((transaction?.Catalog ?? route.Database.LiveCatalog).Clone());
                _foreignWrites.Add(route.Database, write);
            }

            var result = route.Database.ExecuteTriggerBodyStatement(
                route.Statement,
                write.Catalog,
                outer,
                connection.CreateTriggerBodyHooks(route.Database, outer.Hooks));

            write.Changed |= result.Changed;
            write.ForceFullCatalogRewrite |= result.ForceFullCatalogRewrite;
            return result;
        }

        public void Commit()
        {
            foreach (var pair in _foreignWrites)
            {
                if (!pair.Value.Changed)
                    continue;

                if (connection.GetTransactionState(pair.Key) is { } transaction)
                {
                    transaction.Catalog = pair.Value.Catalog;
                    transaction.HasChanges = true;
                    transaction.ForceFullCatalogRewrite |= pair.Value.ForceFullCatalogRewrite;
                    if (!ReferenceEquals(pair.Key, connection._tempDatabase))
                        connection._transactionWriteDatabase = pair.Key;
                }
                else
                {
                    pair.Key.PublishTriggerBodyCatalog(
                        pair.Value.Catalog,
                        pair.Value.ForceFullCatalogRewrite);
                }
                if (ReferenceEquals(pair.Key, connection._tempDatabase))
                    connection._tempInitialized = true;
            }

            _foreignWrites.Clear();
        }

        private RoutedStatement Resolve(ParsedStatement statement)
        {
            if (_routes.TryGetValue(statement, out var route))
                return route;

            route = connection.RouteStatement(statement);
            _routes.Add(statement, route);
            return route;
        }
    }

    // Temp triggers that watch a table owned by the executing database have to be handed over
    // explicitly: they are stored in the connection-private temp database so that they stay
    // invisible to other connections and never reach the persistent schema.
    private EmbeddedDatabase.TempTriggerBridge? CreateTempTriggerBridge(
        EmbeddedDatabase executing,
        out TempTriggerSession? session)
    {
        var transactionState = GetTransactionState(_tempDatabase);
        var isTempDatabase = ReferenceEquals(executing, _tempDatabase);

        // Statements that touch neither the temp database nor a temp trigger are the common case,
        // so bail out before snapshotting the temp catalog.
        if (!isTempDatabase
            && (transactionState is { } pending ? pending.Catalog.Triggers.Count == 0 : !_tempDatabase.HasTriggers))
        {
            session = null;
            return null;
        }

        var triggers = transactionState is { } state
            ? state.Catalog.Triggers.Values.ToArray()
            : _tempDatabase.SnapshotTriggers();
        var overlay = triggers
            .Where(trigger => trigger.TargetSchema is { } schema
                && ReferenceEquals(FindSchemaDatabase(schema), executing))
            .ToArray();

        // The temp database also needs the bridge without an overlay: its own triggers may name
        // their schema explicitly, and only the connection can resolve those names.
        if (overlay.Length == 0 && !isTempDatabase)
        {
            session = null;
            return null;
        }

        var scope = new TempTriggerSession(this, executing);
        session = scope;
        return new EmbeddedDatabase.TempTriggerBridge(
            overlay,
            scope.IsForeign,
            scope.Localize,
            scope.ExecuteForeign);
    }

    private EmbeddedDatabase? FindSchemaDatabase(string schema)
    {
        if (schema.Equals("temp", StringComparison.OrdinalIgnoreCase))
            return _tempDatabase;
        if (schema.Equals("main", StringComparison.OrdinalIgnoreCase))
            return _database;

        return _attachedDatabases.TryGetValue(schema, out var attachment) ? attachment.Database : null;
    }

    private string? GetSchemaName(EmbeddedDatabase database)
    {
        if (ReferenceEquals(database, _tempDatabase))
            return "temp";
        if (ReferenceEquals(database, _database))
            return "main";

        foreach (var pair in _attachedDatabases)
        {
            if (ReferenceEquals(pair.Value.Database, database))
                return pair.Key;
        }

        return null;
    }

    // SQLite drops the triggers that watch a dropped table or view, including temp triggers that
    // reach across schemas. Those live in the temp catalog, so prune them here.
    private void RemoveTempTriggersForDroppedObject(RoutedStatement routed)
    {
        var droppedName = routed.Statement switch
        {
            DropTableStatement drop => drop.Name,
            DropViewStatement drop => drop.Name,
            _ => null,
        };
        if (droppedName is null || GetSchemaName(routed.Database) is not { } schema)
            return;
        if (ReferenceEquals(routed.Database, _tempDatabase))
            return;

        if (GetTransactionState(_tempDatabase) is { } state)
        {
            if (EmbeddedDatabase.RemoveForeignTargetTriggers(state.Catalog, schema, droppedName))
                state.HasChanges = true;
            return;
        }

        if (EmbeddedDatabase.RemoveForeignTargetTriggers(_tempDatabase.LiveCatalog, schema, droppedName))
            _tempDatabase.MarkSchemaMutated();
    }

    private sealed class AttachedDatabase : IDisposable
    {
        public AttachedDatabase(
            string path,
            string pathIdentity,
            EmbeddedDatabase database,
            int sequence,
            IDisposable? ownedFileSystem)
        {
            Path = path;
            PathIdentity = pathIdentity;
            Database = database;
            Sequence = sequence;
            OwnedFileSystem = ownedFileSystem;
        }

        public string Path { get; }
        public string PathIdentity { get; }
        public EmbeddedDatabase Database { get; }
        public int Sequence { get; }
        private IDisposable? OwnedFileSystem { get; }

        public void Dispose()
        {
            try
            {
                Database.Dispose();
            }
            finally
            {
                OwnedFileSystem?.Dispose();
            }
        }
    }

    private sealed class ConnectionStatementReaderLease(
        EmbeddedConnection owner,
        IDisposable[] databaseLeases) : IDisposable
    {
        private EmbeddedConnection? _owner = owner;
        private IDisposable[]? _databaseLeases = databaseLeases;

        public void Dispose()
        {
            var currentOwner = Interlocked.Exchange(ref _owner, null);
            var leases = Interlocked.Exchange(ref _databaseLeases, null);
            if (currentOwner is not null && leases is not null)
                currentOwner.ReleaseStatementReader(this, leases);
        }

        internal void ReleaseFromOwner()
        {
            _ = Interlocked.Exchange(ref _owner, null);
            var leases = Interlocked.Exchange(ref _databaseLeases, null);
            DisposeDatabaseLeases(leases);
        }
    }

    private sealed class TransactionDatabaseState(
        EmbeddedDatabase.SchemaCatalog catalog,
        long version,
        PragmaHeaderMetadata pragmaHeader)
    {
        public EmbeddedDatabase.SchemaCatalog Catalog { get; set; } = catalog;
        public long Version { get; } = version;
        public PragmaHeaderMetadata PragmaHeader { get; set; } = pragmaHeader;
        public bool HasChanges { get; set; }
        public bool HasSnapshotPragmaHeader { get; set; }
        public bool ForceFullCatalogRewrite { get; set; }
        public HashSet<EmbeddedDatabase.ForeignKeyViolation> PendingDeferredViolations { get; } = [];
    }

    private readonly record struct RoutedStatement(
        EmbeddedDatabase Database,
        ParsedStatement Statement,
        bool IsAttached);

    internal EmbeddedConnection(EmbeddedDatabase database)
    {
        _database = database;
        _tempDatabase = new EmbeddedDatabase();
        _database.CopyFunctionAndCollationRegistriesTo(_tempDatabase);
    }

    internal bool HasActiveTransaction => _transactionDatabases is not null;

    internal IDisposable OpenStatementReaderLease()
    {
        ThrowIfDisposed();
        var databases = new[] { _database }
            .Concat(_attachedDatabases.Values.Select(attachment => attachment.Database))
            .Distinct()
            .ToArray();
        var databaseLeases = new List<IDisposable>(databases.Length);
        try
        {
            foreach (var database in databases)
                databaseLeases.Add(database.OpenStatementReaderLease());

            var lease = new ConnectionStatementReaderLease(this, databaseLeases.ToArray());
            lock (_statementReaderGate)
            {
                ThrowIfDisposed();
                if (!_statementReaders.Add(lease))
                    throw new InvalidOperationException("Managed statement reader lease is already registered.");
            }

            return lease;
        }
        catch
        {
            DisposeDatabaseLeases(databaseLeases);
            throw;
        }
    }

    internal EmbeddedConnection OpenDatabaseConnection(string databaseName)
        => ResolveDatabase(databaseName).Connect();

    internal (EmbeddedConnection Connection, EmbeddedDatabase? Owner) OpenSnapshotConnection(
        string databaseName)
    {
        var database = ResolveDatabase(databaseName);
        if (!database.IsFileBacked)
            return (database.Connect(), null);

        var snapshot = EmbeddedDatabase.OpenFile(
            database.DatabasePath,
            database.FileSystem,
            readOnly: true);
        try
        {
            database.CopyFunctionAndCollationRegistriesTo(snapshot);
            return (snapshot.Connect(), snapshot);
        }
        catch
        {
            snapshot.Dispose();
            throw;
        }
    }

    internal bool ReferencesSameDatabase(
        string databaseName,
        EmbeddedConnection other,
        string otherDatabaseName)
    {
        ArgumentNullException.ThrowIfNull(other);
        return ResolveDatabase(databaseName).ReferencesSameDatabase(other.ResolveDatabase(otherDatabaseName));
    }

    internal bool CannotProveDistinctSnapshotFiles(
        string databaseName,
        EmbeddedConnection other,
        string otherDatabaseName)
    {
        ArgumentNullException.ThrowIfNull(other);
        var database = ResolveDatabase(databaseName);
        var otherDatabase = other.ResolveDatabase(otherDatabaseName);
        if (!database.IsFileBacked || !otherDatabase.IsFileBacked)
            return false;

        var storageKind = GetSnapshotStorageKind(database.FileSystem);
        var otherStorageKind = GetSnapshotStorageKind(otherDatabase.FileSystem);
        return storageKind == SnapshotStorageKind.Unknown
               || otherStorageKind == SnapshotStorageKind.Unknown;
    }

    private static SnapshotStorageKind GetSnapshotStorageKind(IFileSystem fileSystem)
        => AhtolaEncryptionFileSystem.Unwrap(fileSystem) switch
        {
            PhysicalFileSystem => SnapshotStorageKind.Physical,
            InMemoryFileSystem => SnapshotStorageKind.InMemory,
            _ => SnapshotStorageKind.Unknown,
        };

    private enum SnapshotStorageKind
    {
        Physical,
        InMemory,
        Unknown,
    }

    public EmbeddedStatement Prepare(string sql)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ThrowIfDisposed();
        ThrowIfInsideHookCallback();
        var parameterMap = SqlParameterMap.Parse(sql);
        var statement = SqlParser.Parse(sql, parameterMap);
        if (_hooks.Authorizer is not null)
            statement = Authorize(statement);

        return new EmbeddedStatement(this, statement, parameterMap, sql);
    }

    /// <summary>
    /// The callbacks registered on this connection. Mutating the returned instance takes effect
    /// on the next prepared statement or execution, mirroring SQLite's hook registration APIs.
    /// </summary>
    public ManagedConnectionHooks Hooks => _hooks;

    private ParsedStatement Authorize(ParsedStatement statement)
    {
        var authorizer = _hooks.Authorizer!;
        var catalog = _transactionDatabases is not null
            && _transactionDatabases.TryGetValue(_database, out var transactionState)
            ? transactionState.Catalog
            : _database.CreateAuthorizationCatalog();
        var tempCatalog = _tempDatabase.CreateAuthorizationCatalog();
        return SqlAuthorization.Apply(
            statement,
            catalog,
            tempCatalog,
            context => InvokeHook(() => authorizer(context)));
    }

    /// <summary>
    /// Builds the per-execution hook payload for a routed statement. Returning <c>null</c> when
    /// nothing is registered keeps the uninstrumented execution path byte-for-byte unchanged.
    /// </summary>
    private ManagedStatementHooks? CreateStatementHooks(EmbeddedDatabase database, bool includeCommitGate)
    {
        var updateHook = _hooks.UpdateHook;
        var commitHook = includeCommitGate ? _hooks.CommitHook : null;
        var progressHandler = _hooks.ProgressHandler;
        var progressInterval = _hooks.ProgressInterval;
        if (updateHook is null && commitHook is null && (progressHandler is null || progressInterval <= 0))
            return null;

        var schema = ResolveSchemaName(database);
        return new ManagedStatementHooks
        {
            RowChanged = updateHook is null
                ? null
                : (operation, table, rowId) => InvokeHook(
                    () => updateHook(new SqliteRowChange(operation, schema, table, rowId))),
            CommitGate = commitHook is null ? null : () => InvokeHook(commitHook),
            Progress = progressHandler is null || progressInterval <= 0
                ? null
                : new ManagedProgressCounter(progressInterval, () => InvokeHook(progressHandler)),
        };
    }

    /// <summary>
    /// Builds the hooks for a temp trigger body statement that runs against <paramref name="target"/>
    /// while a different database executes the firing statement. The update hook has to report the
    /// schema that actually changed, so it is rebuilt for the target rather than forwarded; the
    /// commit gate is dropped because a nested body must not re-arm the outer statement's gate; and
    /// the outer progress counter is reused so its step interval keeps counting across the hop and
    /// can still interrupt the statement.
    /// </summary>
    private ManagedStatementHooks? CreateTriggerBodyHooks(
        EmbeddedDatabase target,
        ManagedStatementHooks? outerHooks)
    {
        var targetHooks = CreateStatementHooks(target, includeCommitGate: false);
        if (outerHooks?.Progress is not { } progress)
            return targetHooks;

        return targetHooks is null
            ? new ManagedStatementHooks { Progress = progress }
            : new ManagedStatementHooks { RowChanged = targetHooks.RowChanged, Progress = progress };
    }

    private string ResolveSchemaName(EmbeddedDatabase database)
    {
        if (ReferenceEquals(database, _tempDatabase))
            return "temp";

        foreach (var attachment in _attachedDatabases)
        {
            if (ReferenceEquals(attachment.Value.Database, database))
                return attachment.Key;
        }

        return "main";
    }

    private void FireRollbackHook()
    {
        if (_hooks.RollbackHook is { } rollbackHook)
            InvokeHook(rollbackHook);
    }

    internal void FireTraceHook(string sql)
    {
        if (_hooks.Trace is { } trace)
            InvokeHook(() => trace(sql));
    }

    /// <summary>
    /// Runs a user callback with reentrancy tracking. The managed engine cannot execute a
    /// statement while a mutation is in flight, so a hook that calls back into its own
    /// connection fails loudly instead of corrupting the working catalog.
    /// </summary>
    private void InvokeHook(Action callback)
    {
        if (_insideHookCallback)
            ThrowHookReentry();

        _insideHookCallback = true;
        try
        {
            callback();
        }
        finally
        {
            _insideHookCallback = false;
        }
    }

    private T InvokeHook<T>(Func<T> callback)
    {
        if (_insideHookCallback)
            ThrowHookReentry();

        _insideHookCallback = true;
        try
        {
            return callback();
        }
        finally
        {
            _insideHookCallback = false;
        }
    }

    internal void ThrowIfInsideHookCallback()
    {
        if (_insideHookCallback)
            ThrowHookReentry();
    }

    private static void ThrowHookReentry()
        => throw new EmbeddedSqlException(
            "Managed connections do not support reentrant use of the connection from a hook callback.");

    public IReadOnlyList<EmbeddedStatement> PrepareScript(string sql)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ThrowIfDisposed();
        return SqlScript.Split(sql).Select(Prepare).ToArray();
    }

    public void ResetForPooling()
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ThrowIfDisposed();
        ReleaseAllStatementReaders();
        ResetTransactionState();
        _lastInsertRowId = 0;
        _queryOnly = false;
        _busyTimeout = TimeSpan.Zero;
        _foreignKeys = false;
        _deferForeignKeys = false;
        _recursiveTriggers = false;
        _tempInitialized = false;
        _pendingPageSizes.Clear();
        _hooks.UpdateHook = null;
        _hooks.CommitHook = null;
        _hooks.RollbackHook = null;
        _hooks.Authorizer = null;
        _hooks.Trace = null;
        _hooks.ProgressHandler = null;
        _hooks.ProgressInterval = 0;
        foreach (var attachment in _attachedDatabases.Values)
            attachment.Dispose();
        _attachedDatabases.Clear();
        ResetTemporaryDatabase();
        _database.RefreshFileCatalogForPooling();
    }

